  ui_story_1_1_6_dialog_content = "<color=#e8d9bb>\"Error al iniciar. Recuento de Fallos: 3921.\"</color>",
  ui_story_1_1_7_dialog_content = "<color=#e8d9bb>\"Nivel de poder inferior al normal. 7% restante.\"</color>",
  ui_story_1_1_8_dialog_content = "<color=#e8d9bb>\"Mantener modo ahorro de energía.\"</color>",
  ui_story_1_1_10_dialog_content = "<color=#e8d9bb>Día <color=#FFB400>6,055</color>.</color>",
  ui_story_1_1_X1_dialog_content = "<color=#e8d9bb>\"Favor firmar y confirmar.\"</color>",
  ui_story_1_1_18_dialog_content = "<color=#FFB400>Soroz</color>...?",
  ui_story_1_1_X2_dialog_content = "Sí, PlayerName.",
  ui_story_1_1_A1_dialog_content = "¿Algo fuera de lo común en la periferia?",
  ui_story_1_1_A2_dialog_content = "Se acercan señales débiles, tal vez otra horda de <color=#FFB400>Eclipsites</color>, como siempre.",
  ui_story_1_1_A3_dialog_content = "Olvídalo entonces. Intentaré reiniciar de nuevo.",
  ui_story_1_1_A4_dialog_content = "Debo rechazar la solicitud, PlayerName.",
  ui_story_1_1_A5_dialog_content = "Simplemente ha habido demasiados intentos y está afectando tu estado mental...",
  ui_story_1_1_A6_dialog_content = "¡Pero estamos casi sin energía y debemos encontrar una salida!",
  ui_story_1_1_A7_dialog_content = "Mantenerte vivo y seguro es mi máxima prioridad.",
  ui_story_1_1_A8_dialog_content = "¡Moriremos cuando se acabe la energía!",
  ui_story_1_1_A9_dialog_content = "Si hay voluntad, hay una manera.",
  ui_story_1_1_A10_dialog_content = "Han pasado 17 años. Si hubiera una manera, ya estaríamos fuera.",
  ui_story_1_1_A11_dialog_content = "Lo siento, PlayerName, es muy riesgoso seguir intentando reiniciar. Por favor, cálmate primero.",
  ui_story_1_1_A12_dialog_content = "¿Los has conseguido?",
  ui_story_1_1_A13_dialog_content = "Las posibilidades de contactar a otros <color=#FFB400>Celestitas</color> son mínimas, pero intentaré de nuevo.",
  ui_story_1_1_A14_dialog_content = "Si podemos alcanzarlos, podremos...",
  ui_story_1_1_A15_dialog_content = "Según mis cálculos, las probabilidades de salir de aquí sin un generador en funcionamiento son casi nulas.",
  ui_story_1_1_A16_dialog_content = "...",
  ui_story_1_1_B1_dialog_content = "Esta es una prueba, PlayerName. Solo mejorando tu voluntad en soledad puedes volverte fuerte.",
  ui_story_1_1_B2_dialog_content = "Basta de sermones, por favor. Mis oídos no aguantan más.",
  ui_story_1_1_B3_dialog_content = "¿Quieres volver a escuchar la historia del continente?",
  ui_story_1_1_B4_dialog_content = "Ya la escuché 192 veces.",
  ui_story_1_1_B5_dialog_content = "¿Comandos del campo de batalla?",
  ui_story_1_1_B6_dialog_content = "246 veces. De nuevo, no puedo hacer eso estando encerrado aquí.",
  ui_story_1_1_B7_dialog_content = "Lo siento, PlayerName. Solo estaba tratando de animarte.",
  ui_story_1_1_B8_dialog_content = "...",
  ui_story_1_1_B9_dialog_content = "¿Tuviste <color=#FFB400>ese sueño</color> de nuevo?",
  ui_story_1_1_B10_dialog_content = "Sí.",
  ui_story_1_1_B11_dialog_content = "Los sueños son la visualización de lo desconocido provocado por la mente. Son ilusiones.",
  ui_story_1_1_B12_dialog_content = "Tienes predilección por exagerar este fenómeno psicológico, también conocido como...",
  ui_story_1_1_B13_dialog_content = "Han sido 17 años y todavía no me acostumbro a cómo hablas, Profesor Soroz.",
  ui_story_1_1_B14_dialog_content = "Simplemente enfatizo que no es más que un <color=#FFB400>sueño</color> y no refleja la realidad.",
  ui_story_1_1_B15_dialog_content = "Pero era muy real para ser un sueño. Era como si estuviera en <color=#FFB400>Eraveil</color>, experimentando la invasión en persona...",
  ui_story_1_1_B16_dialog_content = "Incluso podía sentir su dolor.",
  ui_story_1_1_B17_dialog_content = "Los recuerdos siempre están asociados con emociones y la verdad se distorsiona.",
  ui_story_1_1_B18_dialog_content = "La realidad es que estás vivo y es mi deber mantenerlo así.",
  ui_story_1_1_X3_dialog_content = "Ahí vas de nuevo...",
  ui_story_1_1_19_dialog_content = "Espera, he detectado una nueva señal.",
  ui_story_1_1_20_dialog_content = "¿Nueva señal?",
  ui_story_1_1_21_dialog_content = "Analizando la señal ahora... Se confirma que proviene de <color=#FFB400>Aurorians</color>.",
  ui_story_1_1_22_dialog_content = "¿Aurorians?",
  ui_story_1_1_23_dialog_content = "Lo siento si te hice ilusiones. No son Caelestitas.",
  ui_story_1_1_B20_dialog_content = "Está bien, estoy acostumbrado... Pero, ¿qué hacen los Aurorians aquí?",
  ui_story_1_1_B21_dialog_content = "Están luchando contra <color=#FFB400>Eclipsites</color> justo encima de nosostros y parecen estar en apuros.",
  ui_story_1_1_A17_dialog_content = "Ningún Aurorian se ha aventurado aquí antes. Por qué hoy de todos los días...",
  ui_story_1_1_24_dialog_content = "Te mostraré lo que está sucediendo afuera.",
  ui_story_1_1_25_dialog_content = "¿Está realmente aquí eso que mencionas, <color=#FFB400>Vice</color>?",
  ui_story_1_1_26_dialog_content = "¿Por qué hay tantos Eclipsites alrededor? Nos tienen rodeadas...",
  ui_story_1_1_27_dialog_content = "No hay error. De acuerdo con los resultados de detección, ¡debería haber un <color=#FFB400>Colossus</color> cerca!",
  ui_story_1_1_A18_dialog_content = "Nuestras búsquedas en las demás áreas no han dado nada, ¡pero presiento que encontraremos algo esta vez!",
  ui_story_1_1_A19_dialog_content = "Para ser completamente honesta, me importa más si puedo volver a casa con vida. Somos exploradoras, no soldados...",
  ui_story_1_1_28_dialog_content = "Los Eclipsites son esperables.",
  ui_story_1_1_29_dialog_content = "¡Pero hay demasiados!",
  ui_story_1_1_30_dialog_content = "¿Crees que nos dejarán ir si les decimos que estamos de paso?",
  ui_story_1_1_31_dialog_content = "¡No seas ridícula! La <color=#FFB400>guerra</color> entre nosotros y los Eclipsites lleva más que milenios.",
  ui_story_1_1_A20_dialog_content = "Además, ¿qué te hizo pensar que estas alimañas te entenderían?",
  ui_story_1_1_32_dialog_content = "Para empezar, no deberías estar en esta misión. Pensé que sería pan comido...",
  ui_story_1_1_33_dialog_content = "Enfócate. Los Eclipsites están llegando en masa. Debemos hallar una salida de algún modo.",
  ui_story_1_1_34_dialog_content = "Déjamelo a mí... ¡Torrente rápido!",
  ui_story_1_1_35_dialog_content = "¡Coordinemos con Vice!",
  ui_story_1_1_36_dialog_content = "¿Por qué se abre el suelo? ¿Estoy alucinando por falta de sueño?",
  ui_story_1_1_37_dialog_content = "<size=45>¡Ten cuidado y agárrate de algo!</size>",
  ui_story_1_1_38_dialog_content = "¡Lo siento! ¡Cuidado!",
  ui_story_1_1_40_dialog_content = "¡Ay, ay, ay...!",
  ui_story_1_1_41_dialog_content = "¿Están todas bien? ¿Ángel? ¿Dove?",
  ui_story_1_1_42_dialog_content = "Dónde es... ¿Hola puedes oírme?",
  ui_story_1_1_43_dialog_content = "¿Dónde estoy? ¿Por qué hay una estructura subterránea...?",
  ui_story_1_1_A21_dialog_content = "Este lugar... perfectamente conservado también. No estoy viendo cosas, ¿o sí?",
  ui_story_1_1_44_dialog_content = "¿Realmente encontré un Colossus?",
  ui_story_1_1_45_dialog_content = "Ángel, Dove, ¡¿dónde estás?!",
  ui_story_1_1_46_dialog_content = "<anim type=Shake>¡Gahhhhhh!</anim>",
  ui_story_1_1_47_dialog_content = "¡¿Oh, vamos, más Eclipsites?!",
  ui_story_1_1_48_dialog_content = "Un golpe directo de los Aurorians dejó un hueco en la parte posterior. Evaluando daños...",
  ui_story_1_1_49_dialog_content = "Eso significa... ¿Puedo salir de la apertura?",
  ui_story_1_1_50_dialog_content = "Según los resultados, sí, se puede evacuar a la superficie desde la abertura.",
  ui_story_1_1_51_dialog_content = "¿En serio? ¿Por fin puedo irme...?",
  ui_story_1_1_A23_dialog_content = "Sin embargo, no se recomienda ya que hay muchos Eclipsites en las cercanías.",
  ui_story_1_1_A24_dialog_content = "Parece que la crisis no se ha evitado y el mundo todavía no ha cambiado en absoluto.",
  ui_story_1_1_52_dialog_content = "Tengo tantas ganas de salir fuera, pero estoy... reacio...",
  ui_story_1_1_B22_dialog_content = "Para ti, los Eclipsites suponen una amenaza letal.",
  ui_story_1_1_B23_dialog_content = "No, no son solo los Eclipsites...",
  ui_story_1_1_B24_dialog_content = "Es otro sentimiento más complicado e indescriptible.",
  ui_story_1_1_A25_dialog_content = "Lo siento, no entiendo. ¿Te preocupa dejarme atrás?",
  ui_story_1_1_53_dialog_content = "Todo está bien. Una vez se acabe la energía, seré libre como los otros Colossus.",
  ui_story_1_1_54_dialog_content = "Pero tengo que cumplir mi misión. Y creo que tienes tu propia misión.",
  ui_story_1_1_55_dialog_content = "Pero basta de eso, lo hablaremos más tarde.",
  ui_story_1_1_56_dialog_content = "Ese Aurorian parece estar en gran problema. Mira...",
  ui_story_1_1_58_dialog_content = "No puedo... luchar... He usado todo mi poder...",
  ui_story_1_1_59_dialog_content = "¿¿Por qué tuve que encontrarme con Eclipsites justo ahora??",
  ui_story_1_1_60_dialog_content = "<anim type=Shake><size=50>¡Gahhhh!</size></anim>",
  ui_story_1_1_61_dialog_content = "Lumina... Necesito Lumina...",
  ui_story_1_1_62_dialog_content = "Da dos pasos a tu isquierda.",
  ui_story_1_1_63_dialog_content = "<size=45>¿Quién es?</size>",
  ui_story_1_1_64_dialog_content = "¿Estoy oyendo cosas o estos Eclipsites realmente están hablando?",
  ui_story_1_1_65_dialog_content = "No estás oyendo cosas. Te estoy hablando.",
  ui_story_1_1_66_dialog_content = "¡Oh, Dios mío, es una persona real hablando! Pero no es como cualquiera de nuestras comunicaciones...",
  ui_story_1_1_67_dialog_content = "Esto es <color=#FFB400>telepatía</color>.",
  ui_story_1_1_68_dialog_content = "¿Telepatía?",
  ui_story_1_1_B25_dialog_content = "Es primera vez que hablo con una persona real, así que todavía me estoy adaptando a esto.",
  ui_story_1_1_A26_dialog_content = "Puedes hacerlo. Aunque es tu primera vez, tienes tantos años de práctica...",
  ui_story_1_1_A27_dialog_content = "¿Por qué de repente me estás animando? ¿Quién demonios eres?",
  ui_story_1_1_A28_dialog_content = "¡Estaba hablando solo! De todas formas...",
  ui_story_1_1_69_option_content = "¡Potencia de fuerza!",
  ui_story_1_1_70_dialog_content = "<size=45>¡Woooaaahhh!</size>",
  ui_story_1_1_75_dialog_content = "¡Vencí a todos estos Eclipsites yo sola!",
  ui_story_1_1_76_dialog_content = "Ver el Sendero de la Luz aumentó mucho mi poder.",
  ui_story_1_1_77_dialog_content = "¿Estoy teniendo una ascensión de Luminocreación? ¿Dominé una nueva habilidad que ningún otro Aurorian tiene?",
  ui_story_1_1_78_dialog_content = "¡Destino, es el destino! No... ¿Quizás soy de un linaje especial?",
  ui_story_1_1_79_dialog_content = "¿Por qué sufro una tragedia y un revés tras otro? ¿Qué pasa si me desprecian por ser una forastera?",
  ui_story_1_1_80_dialog_content = "Técnicamente, esa es mi habilidad.",
  ui_story_1_1_81_dialog_content = "¡Eek! ¿Sigues aquí? ¿Eres un fantasma que acecha este lugar?",
  ui_story_1_1_82_dialog_content = "No soy un fantasma. Esa fue solo mi habilidad psíquica, igual que el Sendero de Luz que viste.",
  ui_story_1_1_83_dialog_content = "¿Qué pasa? Entonces, ¿no descubrí ningún poder nuevo...?",
  ui_story_1_1_84_dialog_content = "Lamento decepcionarte.",
  ui_story_1_1_B26_dialog_content = "...",
  ui_story_1_1_B27_dialog_content = "Ah... ¿Te asusté?",
  ui_story_1_1_B28_dialog_content = "Pero también me asustaste cuando irrumpiste.",
  ui_story_1_1_B29_dialog_content = "No tengo idea de lo que está pasando ahora.",
  ui_story_1_1_B30_dialog_content = "Hablemos en persona. Los Aurorians, quizás no están acostumbrados a comunicarse así.",
  ui_story_1_1_85_dialog_content = "De todos modos, sigue el túnel y te estaré esperando en la última habitación.",
  ui_story_1_1_86_dialog_content = "Whoa...",
  ui_story_1_1_A34_dialog_content = "Mmm...",
  ui_story_1_1_87_dialog_content = "¿Qué pasa? ¿Algo en mi cara? Acabo de lavarme la cara...",
  ui_story_1_1_88_dialog_content = "Uh, nada. Es que no esperaba una persona real. No eres un fantasma, ¿verdad?",
  ui_story_1_1_89_dialog_content = "<size=40>¿No dije que los fantasmas no existen?</size>",
  ui_story_1_1_B31_dialog_content = "Entonces, ¿por qué te ves tan sorprendido?",
  ui_story_1_1_B32_dialog_content = "... No esperaba que nadie siguiera vivo aquí.",
  ui_story_1_1_90_dialog_content = "No es lo mismo... ¿Entonces, quién eres? ¿Y esto es... un Colossus?",
  ui_story_1_1_91_dialog_content = "Es un Colossus. Yo estoy a cargo de esto, y soy quien te habló telepáticamente allá.",
  ui_story_1_1_92_dialog_content = "Solo he leído sobre este tipo de habilidad en libros de historia, pero...",
  ui_story_1_1_93_dialog_content = "¿Pero qué...?",
  ui_story_1_1_94_dialog_content = "Espera, ¿eres un...|\n<color=#FFB400>Celestita</color>?",
  ui_story_1_1_95_dialog_content = "¿Por qué tan sorprendida? Sí, soy Celestita.",
  ui_story_1_1_96_dialog_content = "... ¿Eres el único aquí?",
  ui_story_1_1_97_dialog_content = "Sí. Mi casa fue destruida por Eclipsites.",
  ui_story_1_1_A29_dialog_content = "Sí, escuché sobre eso...",
  ui_story_1_1_B33_dialog_content = "¿Puedo preguntarte algo?",
  ui_story_1_1_B34_dialog_content = "Estás demasiado cerca, Celestita ...",
  ui_story_1_1_B35_dialog_content = "Ah, lo siento. Sólo quería preguntar—",
  ui_story_1_1_B36_option_content = "¿Has conocido a otros Celestitas?",
  ui_story_1_1_B37_option_content = "¿Qué pasó hace 17 años?",
  ui_story_1_1_B38_option_content = "¿Qué son Aurorians y Eclipsites?",
  ui_story_1_1_B39_dialog_content = "Llevo aquí desde que tengo uso de razón y mi sistema de comunicación está roto. No puedo...",
  ui_story_1_1_B40_dialog_content = "Cálmate. Nunca conocí a un Celestita, pero tal vez sea porque nunca hubo ninguno a mi alrededor.",
  ui_story_1_1_B41_dialog_content = "... Pero, ¿por qué no intentaron encontrarme?",
  ui_story_1_1_B42_dialog_content = "...",
  ui_story_1_1_B43_dialog_content = "En aquel momento... Solo había leído los archivos de lo que sucedió en Eraveil. Pero a veces tengo <color=#FFB400>sueños</color> extraños...",
  ui_story_1_1_B44_dialog_content = "¿Sueños?",
  ui_story_1_1_B45_dialog_content = "Sobre ese desastre... ¿puedes contarme más sobre él?",
  ui_story_1_1_B46_dialog_content = "Yo era una recién nacida cuando eso sucedió, así que no sé mucho.",
  ui_story_1_1_B47_dialog_content = "Parece que los Eclipsites lanzaron de pronto un <color=#FFB400>ataque organizado</color> y arrasaron con Eraveil por la noche.",
  ui_story_1_1_B48_dialog_content = "Sí, eso ya lo sé.",
  ui_story_1_1_B49_dialog_content = "Es todo lo que sé, lo siento...",
  ui_story_1_1_B50_dialog_content = ",Entonces, ¿eres un <color=#FFB400>Aurorian</color>?",
  ui_story_1_1_B51_dialog_content = "Sí, y escuché que nos unimos con Celestitas en el pasado para luchar contra los Eclipsites.",
  ui_story_1_1_B52_dialog_content = "Esos monstruos justo ahora, eran Eclipsites, ¿verdad?",
  ui_story_1_1_B53_dialog_content = "Estás en lo correcto. Esos monstruos ahora andan sueltos en cada rincón del continente. Nadie sabe de dónde vienen.",
  ui_story_1_1_B54_dialog_content = "Algunos decían que venían del otro lado de la tierra. Algunos decían que venían aquí como castigo de arriba.",
  ui_story_1_1_B55_dialog_content = "Sólo sabemos que han sido nuestros enemigos en común desde el principio de los tiempos.",
  ui_story_1_1_B56_dialog_content = "Bien... Leí sobre todo esto en los archivos.",
  ui_story_1_1_B57_dialog_content = "Entonces, ¿por qué molestarse en preguntar?",
  ui_story_1_1_B58_option_content = "Tengo otra pregunta",
  ui_story_1_1_B59_option_content = "*Guarda silencio*",
  ui_story_1_1_B60_dialog_content = "Tengo otra pregunta-",
  ui_story_1_1_98_dialog_content = "Por cierto, has estado aquí todo este tiempo, ¿nunca has pensado en irte?",
  ui_story_1_1_99_dialog_content = "Bien... No sabemos cómo pelear, a diferencia de ustedes, que pueden usar <color=#FFB400>Luminatics</color>.",
  ui_story_1_1_100_dialog_content = "Puedo ver el Sendero de la Luz pero no puedo usarlo para luchar. Irónico, ¿verdad?",
  ui_story_1_1_101_dialog_content = "No, es irónico que los Aurorians sepan usarla para luchar y que no vean el Sendero de la Luz.",
  ui_story_1_1_103_dialog_content = "De todos modos, nunca dejé la clandestinidad y siempre viví con el soporte vital de Soroz.",
  ui_story_1_1_104_dialog_content = "¿\"<color=#FFB400>Soroz</color>\"? ¿Te refieres a este Colossus? ¿Tiene nombre? ¡Wow...!",
  ui_story_1_1_105_dialog_content = "Claro, como la combinación máxima de magia, tecnología y vida, los Colossus son capaces de tener pensamientos independientes.",
  ui_story_1_1_106_dialog_content = "Puedes comunicarte con él, ¿verdad, ya que eres Celestita y todo...?",
  ui_story_1_1_107_dialog_content = "Claro, es nuestra habilidad natural.",
  ui_story_1_1_109_dialog_content = "¿Qué ocurre? ¿Estás herida?",
  ui_story_1_1_110_dialog_content = "...",
  ui_story_1_1_111_dialog_content = "¿Eh...? No, acabo de recordar algo, eso es todo.",
  ui_story_1_1_112_dialog_content = "Oh, cierto, ¿significa que todavía es operable? Tal vez podamos...",
  ui_story_1_1_113_dialog_content = "Lo siento, aunque Soroz fue una vez un Colossus de primera de la clase Sky, todavía no puedo iniciarlo.",
  ui_story_1_1_114_dialog_content = "Sin embargo, parece que sabes mucho sobre Colossus, ¿no es así, Vice?",
  ui_story_1_1_115_dialog_content = "¡Solo un poco! Leí libros sobre ellos, y mi misión era buscar posibles Colossus sobrevivientes...",
  ui_story_1_1_A31_dialog_content = "Espera un minuto, ¿cómo me llamaste? ¡No recuerdo haberte dicho mi nombre!",
  ui_story_1_1_A32_dialog_content = "Es mi habilidad psíquica, Vice. Escuché tu conversación con tu escuadrón afuera.",
  ui_story_1_1_A33_dialog_content = "Oh... Es cierto, olvidé que eres Celestita.",
  ui_story_1_1_116_dialog_content = "Es una pena que no se pueda activar Soroz, ¡pero parece que he encontrado algo aún mejor!",
  ui_story_1_1_117_dialog_content = "¿Estás hablando de mí?",
  ui_story_1_1_118_dialog_content = "Todavía necesito tu ayuda... Uh, no entendí tu nombre...",
  ui_story_1_1_119_dialog_content = "PlayerName.",
  ui_story_1_1_120_dialog_content = "¿PlayerName? ¡Eso suena un poco exótico!",
  ui_story_1_1_121_dialog_content = "Me separé de mi escuadrón cuando caí. ¿Puedes ayudarme a encontrarlas?",
  ui_story_1_1_122_dialog_content = "No puedo sentirlas ahora mismo. ¿Y tú, Soroz, alguna idea?",
  ui_story_1_1_123_dialog_content = "Hay dos Aurorians en el Altar Luminite, con muchos Eclipsites acercándose a esa área.",
  ui_story_1_1_124_dialog_content = "Es decir, es probable que tampoco estemos a salvo aquí.",
  ui_story_1_1_125_dialog_content = "Parecen tener problemas cerca del Altar Luminite.",
  ui_story_1_1_126_dialog_content = "¡Entonces debo ir a ayudarlos!",
  ui_story_1_1_127_dialog_content = "¡Necesito tu ayuda! ¡Puedes ver el Sendero de Luz y, lo más importante, guiarnos en la batalla!",
  ui_story_1_1_128_dialog_content = "Es decir, ¡aumentaste mi poder de combate, así de fácil!",
  ui_story_1_1_129_option_content = "Pero luchar no es mi fuerte...",
  ui_story_1_1_130_option_content = "¡Entonces lucharemos juntos!",
  ui_story_1_1_131_dialog_content = "¡No te preocupes, te protegeré!",
  ui_story_1_1_132_dialog_content = "Ella tiene razón. Eclipsites se infiltraron en la premisa. Es más seguro estar con ella.",
  ui_story_1_1_133_dialog_content = "De acuerdo, Vice. Pero tengo una solicitud...",
  ui_story_1_1_134_dialog_content = "¡Está bien! No tienes nada de qué preocuparte, ¡yo te protegeré!",
  ui_story_1_1_135_dialog_content = "La Aurorian atrevida se llama Vice, ¿verdad?",
  ui_story_1_1_X6_dialog_content = "También tomaste una decisión extraordinaria, PlayerName.",
  ui_story_1_1_136_dialog_content = "Pero tengo una solicitud y espero que me puedas ayudar.",
  ui_story_1_1_B61_dialog_content = "¡No hay problema! No importa qué, ¡haré todo lo que pueda!",
  ui_story_1_1_137_dialog_content = "Quiero que me saques de aquí.",
  ui_story_1_1_138_dialog_content = "Fuera de aquí... Por supuesto. Pero, ¿estás seguro?",
  ui_story_1_1_139_dialog_content = "No estoy seguro.",
  ui_story_1_1_140_dialog_content = "¡Pero sé que tengo que irme!",
  ui_story_1_2_1_dialog_content = "Estoy acabada, Ángel...",
  ui_story_1_2_2_dialog_content = "Los Eclipsites siguen llegando. No puedo aguantar mucho más...",
  ui_story_1_2_3_dialog_content = "Casi no hay Lumina en este lugar oscuro y abandonado. ¡Sin luz, los Eclipsites son mucho más difíciles de tratar!",
  ui_story_1_2_4_dialog_content = "¿Cómo volvemos a la superficie y dónde está Vice...?",
  ui_story_1_2_6_dialog_content = "¡No quiero morir aquí!",
  ui_story_1_2_7_dialog_content = "¡Dove! ¡Soy yo!",
  ui_story_1_2_8_dialog_content = "Menos mal que no te quedaba mucho Lumina, o Vice se habría lastimado...",
  ui_story_1_2_9_dialog_content = "¿Vice? ¿Estás bien?",
  ui_story_1_2_10_dialog_content = "Estoy bien. ¡Te encontré gracias a PlayerName!",
  ui_story_1_2_11_dialog_content = "¿PlayerName? ¿Quién es ese? No veo a nadie...",
  ui_story_1_2_12_dialog_content = "¡PlayerName puede decirnos qué hacer desde lejos! ¡Todo lo que necesitas hacer es cooperar!",
  ui_story_1_2_13_dialog_content = "¿Cooperar? ¿Cómo? Nosotras...",
  ui_story_1_2_14_option_content = "¡Potencia de fuerza!",
  ui_story_1_2_15_dialog_content = "¿Estaba soñando con viajar a través de la luz?",
  ui_story_1_2_16_dialog_content = "¿Qué está pasando aquí, Vice? ¿Y por qué esa persona se esconde detrás de la puerta?",
  ui_story_1_2_17_dialog_content = "Lo siento, no puedo pelear.",
  ui_story_1_2_18_dialog_content = "Luminocreación y habilidad psíquica... Así que eres...",
  ui_story_1_2_19_dialog_content = "Nunca me dijiste que tenías un amigo así, Vice.",
  ui_story_1_2_20_option_content = "Bueno, en realidad nos acabamos de conocer...",
  ui_story_1_2_21_option_content = "¿Amigo?",
  ui_story_1_2_22_dialog_content = "Sí, PlayerName me salvó después que caímos.",
  ui_story_1_2_23_dialog_content = "PlayerName es el maestro de este Colossus y un Celestita.",
  ui_story_1_2_24_dialog_content = "Mi... \"¿amigo\"?",
  ui_story_1_2_25_dialog_content = "¿Qué te pasa, PlayerName?",
  ui_story_1_2_26_dialog_content = "Oh, uh, nada.",
  ui_story_1_2_28_dialog_content = "También me encontré con Eclipsites cuando caí. PlayerName me salvó.",
  ui_story_1_2_29_dialog_content = "Ella es Ángel y ella es Dove. Estamos en el mismo equipo.",
  ui_story_1_2_30_dialog_content = "Soy PlayerName, dueño de este Colossus y un Celestita.",
  ui_story_1_2_31_dialog_content = "Gracias por ayudar, PlayerName. Pero me temo que tengo más preguntas para ti...",
  ui_story_1_2_32_dialog_content = "¿Cele-qué? No tengo ni idea de lo que están hablando.",
  ui_story_1_2_33_dialog_content = "En fin, gracias, PlayerName. ¡Seamos amigos!",
  ui_story_1_2_34_dialog_content = "Nunca pensé que algún día haría amigos...",
  ui_story_1_3_1_dialog_content = "¿Y ahora qué, Vice? Hay demasiados Eclipsites. Necesitamos refuerzos.",
  ui_story_1_3_2_dialog_content = "El comunicador quedó destruido en la pelea. <color=#FFB400>Navegador</color>, ¿tiene Soroz algún medio de comunicación?",
  ui_story_1_3_3_dialog_content = "No, está destruido.",
  ui_story_1_3_X1_dialog_content = "Entonces deberías tener algún tipo de arma, ¿verdad?",
  ui_story_1_3_X2_dialog_content = "No, ninguna en absoluto.",
  ui_story_1_3_4_dialog_content = "¿Por qué no intentamos iniciar el Colossus?",
  ui_story_1_3_X3_dialog_content = "<color=#e8d9bb>Error al conectar. Recuento de Fallos: 3921. </color>",
  ui_story_1_3_X4_dialog_content = "No va a ninguna parte.",
  ui_story_1_3_X5_dialog_content = "¿Cómo es eso posible?",
  ui_story_1_3_X6_dialog_content = "No. Ya lo he intentado innumerables veces, pero siempre fallaba por alguna razón.",
  ui_story_1_3_X7_dialog_content = "Lo siento, pero el Colossus está en muy malas condiciones.",
  ui_story_1_3_X8_dialog_content = "El Colossus ya está haciendo lo posible, luchando solo para mantenerme con vida.",
  ui_story_1_3_X9_dialog_content = "Gracias por el cumplido, PlayerName.",
  ui_story_1_3_X10_dialog_content = "...",
  ui_story_1_3_6_dialog_content = "Espera un segundo, Navegador.",
  ui_story_1_3_X11_dialog_content = "Incluso si no se puede iniciar y no hay armas, allá mencionaste algo sobre...",
  ui_story_1_3_7_dialog_content = "El Altar Luminite, ¿verdad?",
  ui_story_1_3_8_dialog_content = "Recuerdo que cada Colossus tiene un Altar Luminite para lanzar señales de socorro.",
  ui_story_1_3_A1_dialog_content = "¡Alguien vendrá si ve la señal!",
  ui_story_1_3_9_dialog_content = "Debería estar cerca, ¿verdad? Dijiste que Dove y Ángel estaban muy cerca de eso.",
  ui_story_1_3_10_dialog_content = "... Eres todo un experta en Colossus, ¿eh?",
  ui_story_1_3_X12_dialog_content = "No, solo sé un poco. La gente solía decirme que saber todo esto era inútil...",
  ui_story_1_3_X13_dialog_content = "De hecho, la estación está cerca y en perfecto estado.",
  ui_story_1_3_X14_dialog_content = "Pero creo que puedes adivinar lo que voy a decir...",
  ui_story_1_3_11_dialog_content = "No tenemos el material para lanzar la señal...",
  ui_story_1_3_12_dialog_content = "<color=#FFB400>Lumamber</color>.",
  ui_story_1_3_13_dialog_content = "¿Cómo lo hiciste? Tanto por entender sólo \"un poco.\"",
  ui_story_1_3_14_dialog_content = "Tenemos Lumamber si eso es lo que necesitamos.",
  ui_story_1_3_15_dialog_content = "Pero Vice...",
  ui_story_1_3_16_dialog_content = "¿Qué pasa? Lo tenemos. Está en tu bolso. ¡Yo lo vi!",
  ui_story_1_3_18_dialog_content = "Eso es muy caro...",
  ui_story_1_3_19_dialog_content = "¡Estamos hablando de vida o muerte! ¡No hay tiempo para ser tacaña, Dove!",
  ui_story_1_3_B1_dialog_content = "¿Me reembolsarán?",
  ui_story_1_3_B2_dialog_content = "¡Por supuesto! Puedes tener 10 días libres cuando regresemos. ¿Cómo ves?",
  ui_story_1_3_B3_dialog_content = "¡Bien bien, hecho!",
  ui_story_1_3_B4_dialog_content = "¡Vamos al Altar Luminite, entonces!",
  ui_story_1_3_A2_dialog_content = "Puede haber más Eclipsites en camino, ¡así que ten los ojos abiertos!",
  ui_story_1_3_24_dialog_content = "¡Llegamos! Menos mal que tenemos el Navegador o es posible que nunca lo encontraríamos.",
  ui_story_1_3_25_dialog_content = "Han pasado 17 años, ya sabes...",
  ui_story_1_3_26_dialog_content = "Que bueno que llegamos antes que los Eclipsites.",
  ui_story_1_3_27_dialog_content = "Afortunadamente, nada está dañado.",
  ui_story_1_3_28_dialog_content = "Entonces, ¿ese es el control?",
  ui_story_1_3_29_dialog_content = "¡Vaya, primera vez que veo la cosa real! En cuanto a los detalles operativos...",
  ui_story_1_3_30_dialog_content = "Coloque el Lumamber en el proyector y <color=#FFB400>tire de la palanca</color>. Eso debería bastar.",
  ui_story_1_3_31_dialog_content = "Lástima que nunca tuve los materiales necesarios para ello...",
  ui_story_1_3_33_dialog_content = "¡Pero ahora tienes amigos confiables! ¡Dove!",
  ui_story_1_3_34_dialog_content = "Vice, darás un buen uso a estos materiales, ¿verdad?",
  ui_story_1_3_35_dialog_content = "Por supuesto.",
  ui_story_1_3_36_dialog_content = "...",
  ui_story_1_3_B5_dialog_content = "Dove, puedes... soltarlo ya.",
  ui_story_1_3_B6_dialog_content = "Coo coo, ¿es muy tarde para cambiar de idea?",
  ui_story_1_3_B7_dialog_content = "Incumple tu palabra y te haré comer mil dedos de Eclipsites.",
  ui_story_1_3_B8_dialog_content = "¡Bueno!",
  ui_story_1_4_1_dialog_content = "¡Oye, es un éxito! ¡Qué brillante!",
  ui_story_1_4_2_dialog_content = "Lo hicimos... ¡Gracias Vice!",
  ui_story_1_4_3_dialog_content = "¿Eh? Yo no hice nada. Solo ofrecí algunas ideas locas, eso es todo.",
  ui_story_1_4_4_dialog_content = "Si realmente quieres agradecerme, espera a que salgamos de aquí.",
  ui_story_1_4_5_dialog_content = "Bueno, de hecho tenemos un notable Aurorian aquí, ¡y todos hacen un buen trabajo en equipo!",
  ui_story_1_4_6_dialog_content = "El silencio de todos estos años... se ha roto hoy.",
  ui_story_1_4_X1_dialog_content = "Pero, ¿por qué pareces infeliz, PlayerName? ¿Te sientes bien?",
  ui_story_1_4_X2_dialog_content = "Estoy bien, solo un poco cansado...",
  ui_story_1_4_B29_dialog_content = "¿Somnoliento? Tengo esto para ti—¡dibujos mecánicos!",
  ui_story_1_4_B30_dialog_content = "Cada vez que tengo sueño, lo hojeo... Después de ver estos diagramas, ¡siempre me siento completamente renovada!",
  ui_story_1_4_B31_dialog_content = "No creo que la mente de todos funcione como la tuya, Vice.",
  ui_story_1_4_X3_dialog_content = "¿Ah? Pero... ¡Uh!",
  ui_story_1_4_X4_dialog_content = "¿Qué ocurre? ¿Algo en mi cara otra vez?",
  ui_story_1_4_X5_dialog_content = "¡Tu nariz está sangrando!",
  ui_story_1_4_X6_dialog_content = "Oh no. Telepatía... sobrecarga...",
  ui_story_1_4_X7_dialog_content = "Operar el Altar Luminite me llevó al límite...",
  ui_story_1_4_A1_dialog_content = "Nos dirigiste antes con facilidad, pero ¿por qué ahora...?",
  ui_story_1_4_A2_dialog_content = "Controlar el Colossus... requiere... más energía... Estoy bien... esto pasó antes... Estaré...",
  ui_story_1_4_7_option_content = "No puedo...",
  ui_story_1_4_8_option_content = "Vice...",
  ui_story_1_4_9_dialog_content = "Estás bien... ¡Oye, que alguien me ayude, PlayerName se cayó!",
  ui_story_1_4_10_dialog_content = "No puedo sostenerte... ¡Vengan, ustedes dos! ¡¡No puedo cargar a PlayerName yo sola!!",
  ui_story_1_4_12_dialog_content = "La llamarada está atrayendo Eclipsites. ¡Tenemos que movernos!",
  ui_story_1_4_13_dialog_content = "Teniente Vice, PlayerName todavía está apagado, y me temo que llevarlo nos retrasará.",
  ui_story_1_4_A6_dialog_content = "Mi deber principal es acompañar a esta dama a <color=#FFB400>Subciudad 28</color>. No tenemos mucho tiempo...",
  ui_story_1_4_A3_dialog_content = "Te agradezco tu ayuda, soldado.\nPero PlayerName nos salvó. No podemos simplemente abandonar a PlayerName.",
  ui_story_1_4_14_dialog_content = "Pagar amabilidad con abandono no es como lo hacemos en <color=#FFB400>Federación Ilumina</color>.",
  ui_story_1_4_A4_dialog_content = "Además, PlayerName es un Celestita.",
  ui_story_1_4_15_dialog_content = "¿Es cierto?",
  ui_story_1_4_16_dialog_content = "¡Pero no tenemos suficiente personal para mantener a todos a salvo mientras arrastramos a una persona inconsciente!",
  ui_story_1_4_17_dialog_content = "Tienes razón, soldado.|\nPor favor, saca a todos y deja algunos suministros. Me quedaré para proteger al Celestita.",
  ui_story_1_4_18_dialog_content = "¡Eres muy admirable, teniente Vice!",
  ui_story_1_4_19_dialog_content = "No me he presentado. Soy Blanc. Mucho gusto.",
  ui_story_1_4_20_dialog_content = "Perdón por detenerte, señora...",
  ui_story_1_4_21_dialog_content = "Está bien. No había razón para no responder a una señal de socorro.",
  ui_story_1_4_22_dialog_content = "Y poder ver un Colossus definitivamente vale la pena el viaje.",
  ui_story_1_4_23_dialog_content = "Ya que la capitana decidió quedarse, como miembro del equipo de Exploración, yo no puedo irme tampoco.",
  ui_story_1_4_24_dialog_content = "¿Hmm? Luego... Supongo que yo también me quedaré. Quiero decir, PlayerName nos salvó, después de todo.",
  ui_story_1_4_25_dialog_content = "A todos...",
  ui_story_1_4_A5_dialog_content = "¡Oh, estás despierto!|\nLos refuerzos están aquí. ¿Cómo te sientes? ¿Puedes moverte?",
  ui_story_1_4_26_dialog_content = "Mmm...",
  ui_story_1_4_28_dialog_content = "Acabamos de recibir un informe de que Kraken fue visto cerca, teniente Vice.",
  ui_story_1_4_29_dialog_content = "<color=#FFB400>Kraken, ¿el Eclipsite de alto nivel?</color> Lleva tiempo activo, pero ¿por qué estaría tan cerca de nosotros?",
  ui_story_1_4_30_dialog_content = "No importa, ¡no deberíamos preocuparnos por eso ahora! ¡Movámonos!",
  ui_story_1_4_31_dialog_content = "¿Vendrás con nosotros, PlayerName?",
  ui_story_1_4_32_dialog_content = "Me gustaría mucho ir contigo, Vice, pero Soroz...",
  ui_story_1_4_33_dialog_content = "¿Entonces el Colossus se llama Soroz? Podemos planear recuperar a Soroz más tarde.",
  ui_story_1_4_X8_dialog_content = "Mi trabajo es asegurarme de que todos estén seguros y nada más.",
  ui_story_1_4_X9_dialog_content = "Está bien, PlayerName. Mientras estés fuera de peligro, mi seguridad es de poca importancia.",
  ui_story_1_4_X10_dialog_content = "¡Primero pasa los Eclipsites y sal de aquí!",
  ui_story_1_4_B1_option_content = "Perdóname. ¡Volveré por ti lo antes posible!",
  ui_story_1_4_B2_option_content = "¿No hay forma de que nos vayamos juntos?",
  ui_story_1_4_B3_option_content = "Debo empacar mi equipaje...",
  ui_story_1_4_B4_dialog_content = "He decidido. ¡Iré contigo!",
  ui_story_1_4_B5_dialog_content = "En este momento, sólo sé es que he estado esperando mucho tiempo... No importa lo que pase afuera, tengo que verlo por mí mismo.",
  ui_story_1_4_B6_dialog_content = "Todavía tengo muchas preguntas que hacerle a mi gente...",
  ui_story_1_4_B7_dialog_content = "¡Bien! Entonces preparémonos para luchar. Si los Eclipsites ya están rondando por aquí, ¡podemos esperar más batallas por delante!",
  ui_story_1_4_B9_dialog_content = "Nostalgia, miedo, ansiedad... Debo superarlos todos para ser más fuerte.",
  ui_story_1_4_B10_dialog_content = "Espero que puedas aprender a superarlos... Puedes empezar diciéndome adiós.",
  ui_story_1_4_B11_dialog_content = "Soroz...",
  ui_story_1_4_B12_dialog_content = "Solo saliendo de aquí podrás vivir a la altura de tu destino como Celestita. ¡Vamos, todos cuentan contigo!",
  ui_story_1_4_B13_dialog_content = "Y no me voy a ninguna parte. No te preocupes.",
  ui_story_1_4_B14_dialog_content = "PlayerName, debemos actuar ahora, ¡antes que lleguen más Eclipsites!",
  ui_story_1_4_B15_dialog_content = "Entiendo...",
  ui_story_1_4_B16_dialog_content = "¡Está bien! ¡Todos, concéntrese! ¡Prepárense para luchar en cualquier momento! ¡Nos vamos de aquí!",
  ui_story_1_4_B17_dialog_content = "¿Ah? ¿Equipaje?",
  ui_story_1_4_B18_dialog_content = "Un caleidoscopio hecho de repuestos, bolitas envueltas con alambres y unos dibujos pintados con pintura Lumina.",
  ui_story_1_4_B19_dialog_content = "...",
  ui_story_1_4_B20_dialog_content = "¡No te burles de mí! A pesar de que son solo baratijas, han estado conmigo durante mucho tiempo...",
  ui_story_1_4_B21_dialog_content = "Incluso les di nombres.",
  ui_story_1_4_B22_dialog_content = "... Sé cómo te sientes, pero este no es el momento de dejarse atrapar por eso.",
  ui_story_1_4_B23_dialog_content = "Créeme, PlayerName, tendrás mucho más que atesorar después de salir de aquí.",
  ui_story_1_4_B24_dialog_content = "No me voy a ninguna parte, y ellos tampoco. Puedes volver con nosotros cuando todo esto termine.",
  ui_story_1_4_B25_dialog_content = "Parece que no tengo elección...",
  ui_story_1_4_B26_dialog_content = "Perdón por decir algo raro... Vámonos ahora.",
  ui_story_1_4_B32_dialog_content = "¡Jaja, no te preocupes por eso! ¡También tengo muchos pasatiempos extraños!",
  ui_story_1_4_B27_dialog_content = "¡Vamos! ¡Mantén la calma y busquemos la salida antes de que los Eclipsites se agrupen!",
  ui_story_1_4_B28_dialog_content = "¡Y Navegador, prepárate para dirigirnos en batalla en cualquier momento!",
  ui_story_1_8_1_dialog_content = "Había hordas de ellos... No deberíamos quedarnos más por aquí.",
  ui_story_1_8_B37_dialog_content = "Veo destrucción por todos lados. Todos estos años de limpieza incesante han sido en vano.",
  ui_story_1_8_2_dialog_content = "Lo siento, PlayerName, si no llegamos chocando...",
  ui_story_1_8_3_dialog_content = "Entonces no habría tenido la oportunidad de irme. No se culpen, no es culpa suya. Esas criaturas que salen de las sombras son las culpables.",
  ui_story_1_8_B29_dialog_content = "No te preocupes, espera que recuperemos Soroz. ¡Solicitaré a Illumina reparaciones completas!",
  ui_story_1_8_B30_dialog_content = "¡También puedo diseñar personalmente un plan de modificación para ti!",
  ui_story_1_8_B31_dialog_content = "¿Tienes en mente alguna mejora de diseño? ¿Qué tal una cocina abierta? Puedes cocinar un cremoso guiso de pulpo cuando quieras.",
  ui_story_1_8_B32_dialog_content = "No sé cocinar. Soroz suele ocuparse de eso...",
  ui_story_1_8_B33_dialog_content = "Ah, sí. ¿Qué tal una bañera enorme? Después de un duro día de trabajo, puedes tomar un baño caliente y leer un libro-",
  ui_story_1_8_B34_dialog_content = "No, no, no. No necesito nada de eso ahora mismo...",
  ui_story_1_8_B35_dialog_content = "Tal vez una sala de dibujo mecánica sea en realidad más importante...",
  ui_story_1_8_B36_dialog_content = "Gracias, Vice. Si estás tratando de animarme, lo has logrado. Ya me siento mejor.",
  ui_story_1_8_4_dialog_content = "¿Ah? Oh... lo siento...",
  ui_story_1_8_B38_dialog_content = "Es solo que parecías un poco deprimido y quería aligerar el estado de ánimo con algo que pensé que te podría resultar interesante...",
  ui_story_1_8_5_dialog_content = "Y también, a medida que la cantidad de personas bajo tu mando comienza a crecer, me preocupa que puedas tener otra sangrado nasal...",
  ui_story_1_8_6_dialog_content = "Apoyarlos a todos no es nada comparado con la vinculación mental con el Colossus. Es como caminar en un...",
  ui_story_1_8_7_dialog_content = "<size=45>¡Problemas por delante! ¡Retrocede, retrocede ahora!</size>",
  ui_story_1_8_8_dialog_content = "¿Es eso...?",
  ui_story_1_8_9_dialog_content = "Maldita sea, solo hay una cosa con ese tipo de poder...",
  ui_story_1_8_10_dialog_content = "<color=#FFB400>¡Kraken</color>!",
  ui_story_1_8_11_dialog_content = "<anim type=Shake><size=50>¡Gahhhhhh!</size></anim>",
  ui_story_1_8_12_dialog_content = "¡No sabía que los Eclipsites pudieran ser tan grandes! ¿Eraveil también se enfrentaba a esos monstruos?",
  ui_story_1_8_13_dialog_content = "¡Cuidado, PlayerName! ¡Encuentra un lugar seguro y cúbrete!",
  ui_story_1_8_14_dialog_content = "¡No hay lugar seguro! ¡Hacer frente al Kraken es la única forma de pasar!",
  ui_story_1_8_15_option_content = "¡Entonces derrotemos a este monstruo de frente!",
  ui_story_1_8_16_option_content = "¡Daré apoyo por detrás!",
  ui_story_1_8_17_dialog_content = "¡Ese es el espíritu! ¡Vamos!",
  ui_story_1_8_A2_dialog_content = "¡A tus órdenes, Navegador!",
  ui_story_1_8_18_dialog_content = "¡Iniciando el vínculo mental! ¡Prepárate!",
  ui_story_1_8_19_dialog_content = "¡Entendido! ¡Vamos!",
  ui_story_1_8_20_dialog_content = "<anim type=Shake><size=50>¡Gahhhhhh!</size></anim>",
  ui_story_1_8_21_dialog_content = "¡Cállate y vuelve a donde perteneces!",
  ui_story_1_8_B1_dialog_content = "Gah, gah...",
  ui_story_1_8_B2_dialog_content = "Es casi como si estuviera... ¿diciendo algo?",
  ui_story_1_8_B3_option_content = "Da el golpe final, Vice",
  ui_story_1_8_B4_option_content = "¡Potencia de fuerza!",
  ui_story_1_8_B6_dialog_content = "¡Torrente rápido...!",
  ui_story_1_8_B7_dialog_content = "No me importa de qué esté hablando esta criatura, ni siquiera quiero entender...",
  ui_story_1_8_B8_dialog_content = "¡¡¡Apesta tanto!!!",
  ui_story_1_8_B9_dialog_content = "Ese es el olor de <color=#FFB400>Eclipsium</color>. Todos los Eclipsites dependen de esta energía.",
  ui_story_1_8_B10_dialog_content = "El olor provocaría náuseas a cualquiera.",
  ui_story_1_8_B11_dialog_content = "Gah, gah...",
  ui_story_1_8_B12_dialog_content = "El lenguaje Eclipsite es completamente incomprensible...",
  ui_story_1_8_B13_dialog_content = "Nunca antes había intentado comunicarme telepáticamente con otras criaturas. Ni siquiera sé si puedo...",
  ui_story_1_8_B14_dialog_content = "¿<color=#FFB400>Celes</color>... <color=#FFB400>tita</color>?",
  ui_story_1_8_B15_dialog_content = "¿...?",
  ui_story_1_8_B16_dialog_content = "Urraagh...",
  ui_story_1_8_B17_dialog_content = "¿Murió...? Lástima que no pude obtener más información, pero tenía algunas emociones intensas.",
  ui_story_1_8_B18_dialog_content = "Cuando se enfrentó a la muerte, no parecía tener miedo... Fue más como... ¿sorpresa? ¿Por qué fue eso?",
  ui_story_1_8_22_dialog_content = "Nosotros... de hecho derrotamos a un Eclipsite de alto nivel...",
  ui_story_1_8_23_dialog_content = "¿Nos volvimos más poderosas de nuevo sin darnos cuenta?",
  ui_story_1_8_24_dialog_content = "Sé realista, todo fue obra de PlayerName. De lo contrario, no sabrías ni por dónde empezar.",
  ui_story_1_8_25_dialog_content = "PlayerName es realmente asombroso.",
  ui_story_1_8_A3_dialog_content = "Hablando de eso, solo me enteré por algunos veteranos.",
  ui_story_1_8_26_dialog_content = "Dice la leyenda que la victoria era segura cuando y dondequiera que el Celestita apareciera. Veo que no es una exageración.",
  ui_story_1_8_27_dialog_content = "La salida está más adelante. ¡Salgamos todos a la carga de aquí!",
  ui_story_1_8_28_dialog_content = "¿Cómo estás, PlayerName?",
  ui_story_1_8_B19_dialog_content = "Estoy bien. Aparte de la fatiga... ¿hay algo más que deba saber?",
  ui_story_1_8_B20_dialog_content = "¿Qué quieres decir?",
  ui_story_1_8_B21_dialog_content = "He estado viviendo en el Colossus todo este tiempo. Cuando se trata de explorar el mundo exterior...",
  ui_story_1_8_B22_dialog_content = "¿Necesitaré contener la respiración?",
  ui_story_1_8_B23_dialog_content = "¿Quizás el aire exterior sea tóxico para mí?",
  ui_story_1_8_B24_dialog_content = "¿Tengo que mantener los ojos cerrados hasta que me acostumbre a la luz del sol?",
  ui_story_1_8_B25_dialog_content = "Pensándolo bien, sería mejor cubrirme la cara...",
  ui_story_1_8_B26_dialog_content = "Estoy empezando a comprender en qué ha estado pensando este Celestita durante los últimos 17 años.",
  ui_story_1_8_B27_dialog_content = "No te dejes llevar. Sólo sígueme. El mundo exterior no da tanto miedo como imaginaba.",
  ui_story_1_8_B28_dialog_content = "Ven, dame tu mano.",
  ui_story_1_8_29_dialog_content = "<color=#FFB400>Nuevo mundo</color>...",
  ui_story_1_8_30_dialog_content = "¡¿?!",
  ui_story_1_8_31_dialog_content = "Tenemos problemas, Vice.",
  ui_story_1_8_32_dialog_content = "¿El <color=#FFB400>ejército de Eclipsites</color>? ¿Aquí? ¿Cómo puede ser?",
  ui_story_1_8_33_dialog_content = "¡Retrocedan todos y sellen el camino de entrada!",
  ui_story_1_8_34_dialog_content = "No estaban allí cuando llegamos... ¡Déjame fortificar el muro!",
  ui_story_1_8_A4_dialog_content = "¡Pero esa es nuestra salida, Teniente Vice!",
  ui_story_1_8_36_dialog_content = "¿Por qué tantos Eclipsites? ¡No estamos ni cerca de la línea del frente!",
  ui_story_1_8_37_dialog_content = "Tranquila, Teniente Vice. Al parecer, han cruzado la línea del frente.",
  ui_story_1_8_38_dialog_content = "El problema es, ¿cómo lograron atravesar la barrera de Illumina?",
  ui_story_1_8_39_dialog_content = "Tal vez tengan algún tipo de vehículo volando sobre él...",
  ui_story_1_8_40_dialog_content = "¿Qué puede llevar tantos Eclipsites a la vez? ¿Otro Colossus? ¿Cuáles son las posibilidades de eso?",
  ui_story_1_8_41_dialog_content = "Quizás estoy pensando demasiado. Pero esto nos deja solo una opción.",
  ui_story_1_8_42_dialog_content = "Eso es <color=#FFB400>poner en marcha el Colossus</color>.",
  ui_story_1_8_44_dialog_content = "Pero nunca lo has logrado...",
  ui_story_1_8_45_dialog_content = "¿Tenemos otra opción? Lo único que podemos hacer es intentarlo una vez más.",
  ui_story_1_8_46_dialog_content = "Si ni siquiera puedo iniciar el Colossus como Celestita...",
  ui_story_1_8_47_dialog_content = "Pero te desmayaste la última vez. ¿Puede tu cuerpo soportarlo?",
  ui_story_1_8_48_dialog_content = "Tu cabeza no explotaría intentándolo, ¿verdad?",
  ui_story_1_8_49_dialog_content = "Gracias por la preocupación, ¡pero tengo que intentarlo!",
  ui_story_1_8_50_dialog_content = "...",
  ui_story_1_8_51_dialog_content = "A juzgar por tu expresión, Vice, estás pensando...",
  ui_story_1_8_52_dialog_content = "Sí, en teoría debería poder ayudar, pero solo en teoría.",
  ui_story_1_8_53_dialog_content = "¿De qué estás hablando?",
  ui_story_1_8_54_dialog_content = "¡Bien, estoy lista! ¡Improvisaremos si hay algún problema! ¡No creo que haya nada que no podamos superar!",
  ui_story_1_8_55_dialog_content = "Siempre lo intentabas solo antes. Esta vez, ¡tal vez funcione con nosotros!",
  ui_story_1_8_56_dialog_content = "¿Cómo es que tienes más confianza que yo?",
  ui_story_1_8_57_dialog_content = "Por supuesto. Soy una eterna optimista, PlayerName.",
  ui_story_1_8_59_dialog_content = "A mi modo de ver, los obstáculos están ahí para ponernos a prueba, ¡y ya no tienes que afrontar las cosas solo!",
  ui_story_1_8_60_dialog_content = "¡Muy bien, entonces, vayamos al puente!",
  ui_story_1_8_61_dialog_content = "PlayerName...",
  ui_story_1_8_62_dialog_content = "¡Te ayudaré a comenzar esta vez, Soroz!",
  ui_story_1_9_1_dialog_content = "<color=#e8d9bb>Control primario... normal. Encendiendo...</color>",
  ui_story_1_9_2_dialog_content = "<color=#e8d9bb>Módulos biológicos... anormales y casi agotados.</color>",
  ui_story_1_9_3_dialog_content = "<color=#e8d9bb>Soporte vital... en apagado.</color>",
  ui_story_1_9_4_dialog_content = "<color=#e8d9bb>Generador... normal. Intento de inicio. </color>",
  ui_story_1_9_5_dialog_content = "<color=#e8d9bb>10%... 23%...</color>",
  ui_story_1_9_6_dialog_content = "<color=#e8d9bb>76%... 85%...</color>",
  ui_story_1_9_7_dialog_content = "<color=#e8d9bb>No se pudo iniciar. Recuento de fallos: 3922.</color>",
  ui_story_1_9_8_dialog_content = "No, todavía no funciona.",
  ui_story_1_9_10_dialog_content = "¿Por qué? ¿Por qué no funciona? ¿Cuál es el problema?",
  ui_story_1_9_11_dialog_content = "Uf, ¿alcanzando mis límites de nuevo...?",
  ui_story_1_9_12_dialog_content = "Coo Coo... ¿Qué pasa con PlayerName...?",
  ui_story_1_9_13_dialog_content = "Si estás segura, Vice, ahora es el momento.",
  ui_story_1_9_14_dialog_content = "Esta cosa del piano es el panel de control del Colossus, ¿verdad?",
  ui_story_1_9_15_dialog_content = "Déjame ayudarte a poner en marcha el Colossus, Navegador.",
  ui_story_1_9_16_dialog_content = "¿Conmigo? Eres un Aurorian, Vice. No tienes habilidades psíquicas.",
  ui_story_1_9_17_dialog_content = "Pero puedo ser tu fuerza. Yo... puedo ayudar.",
  ui_story_1_9_18_dialog_content = "¿...?",
  ui_story_1_9_19_dialog_content = "Cree en mí, PlayerName. Tu y yo... Realmente no somos tan diferentes.",
  ui_story_1_9_21_dialog_content = "Es una larga historia. ¡Te lo diré la próxima vez cuando tenga la oportunidad!",
  ui_story_1_9_22_dialog_content = "Pero, ¿sabes realmente cómo utilizar el panel de control?",
  ui_story_1_9_23_dialog_content = "¡Por supuesto! ¡No olvides que sé un par de cosas sobre Colossus!",
  ui_story_1_9_24_dialog_content = "E Illumina ha estado intentando reconstruir Colossus y reclutar navegadores. Es una pena que...",
  ui_story_1_9_25_dialog_content = "De todos modos, ¡podríamos potenciarlo si trabajamos juntos!",
  ui_story_1_9_26_dialog_content = "Pero si hay un problema, nuestras dos cabezas podrían...|\nComo lo dices, explotar.",
  ui_story_1_9_27_dialog_content = "Esta es la única opción restante.. Tenemos que intentarlo incluso si es arriesgado.",
  ui_story_1_9_28_dialog_content = "Muy bien, supongo que no hay vuelta atrás de todos modos. Ven y siéntate conmigo.",
  ui_story_1_9_29_dialog_content = "Déjame mostrarte cómo se \"juega\"...",
  ui_story_1_9_30_dialog_content = "<color=#e8d9bb>Generador... normal. Intento de inicio. </color>",
  ui_story_1_9_B1_dialog_content = "Navegador, solo dime lo que tengo que hacer.",
  ui_story_1_9_B2_dialog_content = "Es muy simple. Es como tocar el piano.",
  ui_story_1_9_B3_dialog_content = "¡Pero no hay puntaje aquí! ¿Puedes señalar qué teclas debo tocar?",
  ui_story_1_9_31_dialog_content = "<color=#e8d9bb>16%... 33%...</color>",
  ui_story_1_9_B4_dialog_content = "Puedo sentir... la energía fluyendo.",
  ui_story_1_9_B5_dialog_content = "¿Estás imbuyendo Lumina?",
  ui_story_1_9_B6_dialog_content = "Sí. Es como una conversación, aunque no entiendo el idioma de Colossus.",
  ui_story_1_9_B7_dialog_content = "El idioma está dentro de las teclas del piano, Vice.",
  ui_story_1_9_32_dialog_content = "<color=#e8d9bb>89%... 97%...</color>",
  ui_story_1_9_B8_dialog_content = "Está funcionando... Esto eso... increíble.",
  ui_story_1_9_B9_dialog_content = "Navegador, ¿la canción ya casi termina?",
  ui_story_1_9_B10_dialog_content = "Sí. Terminemos el comando de activación, Vice.",
  ui_story_1_9_B11_dialog_content = "La nota final-",
  ui_story_1_9_33_dialog_content = "<color=#e8d9bb>100% iniciado correctamente.</color>",
  ui_story_1_9_34_dialog_content = "¿Qué está pasando? ¡Se ilumina a nuestro alrededor!",
  ui_story_1_9_35_dialog_content = "<size=45>¡¡PlayerName!!</size>",
  ui_story_1_9_36_dialog_content = "¿Está brillando el puente?",
  ui_story_1_9_37_dialog_content = "<size=45>¡Nosotros lo empezamos!</size>",
  ui_story_1_9_38_dialog_content = "¡...!",
  ui_story_1_9_40_dialog_content = "¡Lo logramos, PlayerName! ¡No puedo creer que lo hicimos!",
  ui_story_1_9_41_dialog_content = "¡Así es como se ve el puente! ¡Es tan brillante!",
  ui_story_1_9_42_dialog_content = "Tan bonito... ¿Es este el color de Lumina?",
  ui_story_1_9_A1_dialog_content = "¿O es aurora?",
  ui_story_1_9_43_dialog_content = "Estoy maravillada... Nunca había visto algo así antes...",
  ui_story_1_9_44_dialog_content = "¿Es así como se ve el cielo real? Es difícil de verlo directamente, pero es absolutamente hermoso...",
  ui_story_1_9_45_dialog_content = "¡Todavía no puedo creer que lo hicimos! ¡Y nunca sentí un poder explosivo como este!",
  ui_story_1_9_46_dialog_content = "¡Has vuelto a ser tu antiguo yo, Soroz!",
  ui_story_1_9_47_dialog_content = "¡Afirmativo! El poder está surgiendo a través de cada fibra de mi ser, pero todavía necesito algo de tiempo antes de poder emprender el vuelo.",
  ui_story_1_9_48_dialog_content = "Puede haber enemigos en las cercanías. ¡Manténgase alerta!",
  ui_story_1_9_49_dialog_content = "¿Un poco de calentamiento después de no moverse durante tanto tiempo?",
  ui_story_1_9_50_dialog_content = "¡Estás en lo correcto! Parece que todavía te queda mucho en ti.",
  ui_story_1_9_51_dialog_content = "¡Ten cuidado de no cansarte, PlayerName!",
  ui_story_1_9_52_dialog_content = "Me siento muy bien, Vice. ¡No me pasa nada!",
  ui_story_1_9_A2_dialog_content = "Siempre he soñado con cómo me iría de aquí y regresaría al mundo.",
  ui_story_1_9_A3_dialog_content = "¡Pero nunca pensé que sería así y con un grupo de Aurorians!",
  ui_story_1_9_53_dialog_content = "¡Hemos logrado lo que pensé que era imposible!",
  ui_story_1_9_54_dialog_content = "También me resulta difícil imaginar todo esto.",
  ui_story_1_9_A4_dialog_content = "Un Colossus perfecto, la Aurora a mi alcance...",
  ui_story_1_9_55_dialog_content = "Ya sabes, ayer solo era una soldado de Illumina que no podía enfrentarse a un solo Eclipsite...",
  ui_story_1_9_56_dialog_content = "Muy mareado... Ese sueño... ¿Otra vez?",
  ui_story_1_9_58_dialog_content = "<color=#FFB400>Schummer</color>, ¿¡por qué!?",
  ui_story_1_9_59_dialog_content = "¡Schummer, traidora! ¡¿Cómo te atreves a traicionar a los tuyos por el poder?!",
  ui_story_1_9_60_dialog_content = "Los traidores y desertores son meras etiquetas dadas por hipócritas y cobardes.",
  ui_story_1_9_61_dialog_content = "Eraveil ha muerto, mis compañeros Celestitas. Me daré cuenta de tus supuestos valores a mi manera.",
  ui_story_1_9_62_dialog_content = "Luchar es inútil. Nada personal, solo supervivencia del más apto...",
  ui_story_1_9_63_dialog_content = "¡¡¡No!!!",
  ui_story_1_9_64_dialog_content = "... ¿Ese sueño otra vez?",
  ui_story_1_9_65_dialog_content = "No... más. Soroz, ¿qué significa todo esto? ¿¡De qué se trata todo esto!?",
  ui_story_1_9_A5_dialog_content = "...",
  ui_story_1_9_66_option_content = "No hay tiempo para eso ahora.",
  ui_story_1_9_A6_option_content = "¡Espera! ¡No son ilusiones!",
  ui_story_1_9_67_option_content = "¿Qué me estás escondiendo?",
  ui_story_1_9_B12_dialog_content = "Yo... no puedo permitir que estas imágenes sin sentido nublen mi mente.",
  ui_story_1_9_B13_dialog_content = "Ahora que lo he activado, necesito mantener el Colossus estabilizado... Vamos, concéntrate...",
  ui_story_1_9_B14_dialog_content = "Buen trabajo, PlayerName. Las imágenes que viste... pronto serán explicadas.",
  ui_story_1_9_B15_dialog_content = "Incluso yo estoy buscando respuestas, y ahora creo que estamos listos para encontrarlas.",
  ui_story_1_9_B16_dialog_content = "Estás hablando crípticamente de nuevo, Soroz. Pero no importa... Hoy, finalmente lo hice.",
  ui_story_1_9_B17_dialog_content = "Sí. Sigue adelante. Como Celestita, el vasto cielo azul es todo tuyo para explorar.",
  ui_story_1_9_B18_dialog_content = "Todo se siente tan real... ¡Demasiado real para ser ilusiones! DEBEN ser reales, ¿verdad?",
  ui_story_1_9_B19_dialog_content = "Dado que existen en su conciencia, deben tener sus raíces en los rastros de la realidad. Eso es innegable.",
  ui_story_1_9_B20_dialog_content = "Deja de esquivar la pregunta, Soroz... Necesito una respuesta.",
  ui_story_1_9_B21_dialog_content = "Lo siento... Yo también quiero responderte, pero no puedo.",
  ui_story_1_9_B22_dialog_content = "Simplemente no lo recuerdo. Perdí todo esa noche. Lo único que recuerdo es la orden de mantenerte con vida.",
  ui_story_1_9_B23_dialog_content = "...",
  ui_story_1_9_B24_dialog_content = "Realidad o ilusión... Todo lo que importa ahora es que nuestro viaje ha comenzado.",
  ui_story_1_9_B25_dialog_content = "Y ahora estás listo para encontrar las respuestas por ti mismo, ¿no es así?",
  ui_story_1_9_B26_dialog_content = "Contéstame, Soroz. ¿Qué escondes? ¿Son estas imágenes reales o falsas?",
  ui_story_1_9_B27_dialog_content = "No lo sé, PlayerName.",
  ui_story_1_9_B28_dialog_content = "Debes estar bromeando...",
  ui_story_1_9_B29_dialog_content = "No te estoy mintiendo. El hecho es que todo mi conocimiento de esa época se pierde en un mar profundo de recuerdos nublados.",
  ui_story_1_9_B30_dialog_content = "Siempre he esperado darte una respuesta en lugar de una falsa esperanza, pero parece que nuestro destino ha cambiado.",
  ui_story_1_9_B31_dialog_content = "Y con la ayuda de tus nuevos amigos, ahora estás listo para encontrar respuestas por ti mismo, ¿no es así?",
  ui_story_1_9_B32_dialog_content = "Pero la respuesta... ¿Qué podría ser?",
  ui_story_1_9_B33_dialog_content = "Mi gente, mi Eraveil... Si la respuesta termina siendo lo que más temo—",
  ui_story_1_9_B34_dialog_content = "¿Cuál es el significado de todo esto?",
  ui_story_1_10_1_dialog_content = "<color=#e8d9bb>En algún lugar</color>",
  ui_story_1_10_2_dialog_content = "(Hablando en Eclipsiano) Los Aurorians han abierto una brecha en el interior de Soroz el Colossus, y en su interior se encontró a un descendiente de Celestita.",
  ui_story_1_10_3_dialog_content = "(Hablando en Eclipsiano) La unidad Aurorian era demasiado poderosa para que Kraken completara la misión de la Verdad...",
  ui_story_1_10_A1_dialog_content = "(Hablando en Eclipsiano) Kraken cargará con el pecado y regresará al Otro Lado donde Madre debe pedir perdón.",
  ui_story_1_10_4_dialog_content = "(Hablando en Eclipsiano) Viva el <color=#FFB400>Eclipse</color>.",
  ui_story_1_10_5_dialog_content = "¿Fueron esas las últimas palabras de Kraken? ¿Fue derrotado por los Celestitas y los Aurorians?",
  ui_story_1_10_6_dialog_content = "Nunca esperé un sobreviviente de <color=#FFB400>ese entonces</color>. Pensé que estaban todos exterminados.",
  ui_story_1_10_A2_dialog_content = "¿Me permites tratar personalmente con el Celestita?",
  ui_story_1_10_7_dialog_content = "¿Matar a tu propia <color=#FFB400>especie</color> te excita sin fin?",
  ui_story_1_10_8_dialog_content = "¿Mi propia especie? No he escuchado ese término en años.",
  ui_story_1_10_9_dialog_content = "Tienes entre manos tareas de mayor importancia. No te preocupes por distracciones tan insignificantes.",
  ui_story_1_10_10_dialog_content = "Lo que queremos no está en ese Colossus. No pierdas tu tiempo y el mío. ¿No has esperado ya lo suficiente?",
  ui_story_1_10_11_dialog_content = "En cuanto a los Celestitas, déjalos a <color=#FFB400>Nozard</color>. ¿No se encuentra en las proximidades?",
  ui_story_1_10_12_dialog_content = "¿Le estás dejando terminar lo que Kraken no pudo?",
  ui_story_1_10_13_dialog_content = "Nozard es más que suficiente para cuidar de los Aurorians, y será mejor que los devuelva con vida.",
  ui_story_1_10_14_dialog_content = "Le informaré que se reúna con nosotras cuando termine, para no retrasar el plan.",
  ui_story_1_10_A3_dialog_content = "A diferencia de ti, sigue muy bien las órdenes. Deberías aprender más de él.",
  ui_story_1_10_15_dialog_content = "En comparación con el plan, un Celestita sin conocimiento no merece la pena.",
  ui_story_1_10_16_dialog_content = "Pero si me subestimas de nuevo, podría romperte el cuello.",
  ui_story_1_10_17_dialog_content = "Ja, ja, ja, eres muy graciosa,<color=#FFB400>Schummer</color>.",
  ui_story_1_10_18_dialog_content = "Hasta aquí te llevo, Nozard. ¡Sabes las consecuencias si te equivocas!",
  ui_story_1_10_19_dialog_content = "Por supuesto. Soy Nozard el intrépido...",
  ui_story_1_10_21_dialog_content = "El objetivo está por delante. ¡Que osadía! El Colossus que se escapó apareció en nuestro territorio.",
  ui_story_1_10_22_dialog_content = "¡Sujétalo al suelo antes de que despegue!",
  ui_story_1_10_23_dialog_content = "¡Luego voltea cada piedra hasta encontrar el Celestita para nuestro señor!",
  ui_story_1_10_24_dialog_content = "<size=45>¡En nombre de madre, al ataque!</size>",
  ui_story_1_10_25_dialog_content = "¿Realmente nos están enviando tantos?",
  ui_story_1_10_26_dialog_content = "Estamos prácticamente expuestos después de activar el Colossus. Por eso todos los Eclipsites se están reuniendo a nuestro alrededor.",
  ui_story_1_10_27_dialog_content = "Es inevitable. Entonces, ¿Soroz necesita más tiempo para calentar?",
  ui_story_1_10_B1_dialog_content = "...",
  ui_story_1_10_B2_dialog_content = "¿PlayerName?",
  ui_story_1_10_B3_dialog_content = "¿Ah? Lo siento, yo... Estaba pensando en otra cosa ahora mismo.",
  ui_story_1_10_B4_dialog_content = "... Me gustaría confirmar algo, si Soroz tardará o no en calentarse.",
  ui_story_1_10_28_dialog_content = "Bueno, eso me temo. Pasará algún tiempo antes de que Soroz pueda moverse, pero una vez que Soroz esté en el aire, estaremos a salvo.",
  ui_story_1_10_30_dialog_content = "Dame más tiempo, PlayerName.",
  ui_story_1_10_31_dialog_content = "¡No puedo esperar para irme de aquí con todos ustedes y experimentar el cielo del nuevo mundo!",
  ui_story_1_10_32_dialog_content = "¡Debemos defender a Soroz hasta que Soroz pueda volar!",
  ui_story_1_10_33_dialog_content = "Está bien. ¡Dividámonos y protejamos cada pasaje!",
  ui_story_1_10_34_dialog_content = "Por favor, quédate en el puente, PlayerName.",
  ui_story_1_10_35_dialog_content = "¡A la carga, muchachos! ¡Es hora de salir al campo de batalla!",
  ui_story_1_10_A4_dialog_content = "Prepara tus armas y gana tiempo para que Soroz se caliente.",
  ui_story_1_10_36_dialog_content = "¡Esplendor Illumina!",
  ui_story_1_10_37_dialog_content = "¡Esplendor Illumina!",
  ui_story_1_10_38_dialog_content = "Esplendor, ¿qué?",
  ui_story_1_14_1_dialog_content = "(Hablando en Eclipsiano) ¡El Colossus está a punto de despegar! ¡Destrúyelo y a los Aurorians que se esconden dentro de inmediato!",
  ui_story_1_14_2_dialog_content = "(Hablando en Eclipsiano) Nos hemos infiltrado en muchas áreas dentro del Colossus, pero nos encontramos con una fuerte resistencia cerca del puente. Nuestras fuerzas han sufrido grandes pérdidas.",
  ui_story_1_14_3_dialog_content = "(Hablando en Eclipsiano) ¿Entonces? ¿Tememos a la muerte?",
  ui_story_1_14_4_dialog_content = "(Habla en Eclipsiano) ¡Nunca!",
  ui_story_1_14_5_dialog_content = "(Hablando en Eclipsiano) ¡Entonces afila tus garras y no te detengas!",
  ui_story_1_14_A1_dialog_content = "(Hablando en Eclipsiano) ¡Incluso si mueres, despelleja tantos como puedas al salir!",
  ui_story_1_14_6_dialog_content = "(Hablando en Eclipsiano) Llévame allí. ¡Veré cuán duros son estos Aurorians para mí!",
  ui_story_1_14_7_dialog_content = "<color=#e8d9bb>(Dentro del Colossus)</color>",
  ui_story_1_14_8_dialog_content = "La próxima ola llegará pronto. Todos, tomen un respiro. Quiero un recuento de munición y un informe de bajas.",
  ui_story_1_14_9_dialog_content = "Quedan 11 tiros. De 6 combatientes, 4 levemente heridos, 2...",
  ui_story_1_14_10_dialog_content = "Bien, entendido.",
  ui_story_1_14_11_dialog_content = "Debemos retirarnos, Capitán...",
  ui_story_1_14_12_dialog_content = "¡No podemos! Vice y su escuadrón están protegiendo el área más crucial justo ahora. ¡Debemos detener a los Eclipsites en la periferia!",
  ui_story_1_14_13_dialog_content = "¡Todos luchamos por sobrevivir y es igualmente difícil para todos nosotros! ¡Así que detente con ese pensamiento y sigue la línea!",
  ui_story_1_14_14_dialog_content = "¡Levanta el ánimo! ¡Saca tu espada si te quedas sin munición!",
  ui_story_1_15_1_dialog_content = "¡Tú, tampoco piensas en escaparte!",
  ui_story_1_15_2_dialog_content = "¡Bien! ¡Eso debería despejar el puente!",
  ui_story_1_15_3_dialog_content = "¡Estás mejorando en coordinarnos, PlayerName!",
  ui_story_1_15_4_dialog_content = "Es obvio que tanto mi mente como mis habilidades han mejorado mucho hoy.",
  ui_story_1_15_5_dialog_content = "¿Me pregunto cómo van las peleas en otros lugares?",
  ui_story_1_15_6_dialog_content = "¿Cuánto tiempo más necesitas, Soroz?",
  ui_story_1_15_7_dialog_content = "El generador está arrancando. Mantén tu equilibrio.\n<size=45>¡Al cielo!</size>",
  ui_story_1_15_8_dialog_content = "¡¿Estamos volando?!",
  ui_story_1_15_9_dialog_content = "¡Vaya, casi me caigo! ¡¡Estamos tan arriba!! ¡¿Estamos volando?!",
  ui_story_1_15_10_dialog_content = "¡Aférrense a algo, todos!",
  ui_story_1_15_11_dialog_content = "¡Ese es mi cabello, Vice!",
  ui_story_1_15_A1_dialog_content = "¡Oh, el cielo! Ha pasado tanto tiempo... Todavía recuerdo la última vez, esa maldita noche...",
  ui_story_1_15_A2_dialog_content = "¡Deseo seguir acelerando, PlayerName!",
  ui_story_1_15_A3_dialog_content = "¡Adelante, Soroz! ¡Por supuesto, elévate!",
  ui_story_1_15_12_dialog_content = "¡Volemos a toda velocidad! ¡Incluso nos hemos deshecho de los Eclipsites!",
  ui_story_1_15_13_dialog_content = "¡Con gusto! ¡Volemos a través de los grandes cielos una vez más!",
  ui_story_1_15_14_dialog_content = "¿Qué es esta vibración, Vice?",
  ui_story_1_15_15_dialog_content = "¡Justo te iba a llamar! ¡Estamos en el aire!",
  ui_story_1_15_16_dialog_content = "¿En serio? ¡Eso es maravilloso! Estaba preocupado... podría ser demasiado tarde...",
  ui_story_1_15_17_dialog_content = "¿Demasiado tarde? ¿Qué sucedió? ¿Están bien chicos?",
  ui_story_1_15_18_dialog_content = "Un Behemoth irrumpió y no pudimos detenerlo. Perdimos tantos...",
  ui_story_1_15_19_dialog_content = "Se dirige directamente al puente. Definitivamente es un Eclipsite de alto nivel... Lo siento...",
  ui_story_1_15_20_dialog_content = "¿Un enemigo más poderoso? Estén alerta, todos, ¡aún no ha terminado!",
  ui_story_1_15_21_dialog_content = "Brr... ¿Por qué bajó la temperatura de repente? Tan frío...",
  ui_story_1_15_22_dialog_content = "No es la temperatura, Dove. Esa es la sensación de Darkflow... A todos, el enemigo está aquí.",
  ui_story_1_15_23_dialog_content = "<color=#e8d9bb>Un repentino y siniestro escalofrío llena el aire...</color>",
  ui_story_1_15_25_dialog_content = "Ustedes, locos, lograron hacer volar este ataúd. No importa, ¡es hora de tu desaparición!",
  ui_story_1_15_26_dialog_content = "¿Otro Eclipsite de alto nivel?",
  ui_story_1_15_27_dialog_content = "Tengo un nombre, Aurorian. Puedes llamarme <color=#FFB400>Nozard</color>. Fue otorgado por la propia Madre.",
  ui_story_1_15_28_dialog_content = "¡Recuerda mi nombre, porque te guiará a la Verdad del Otro Lado!",
  ui_story_1_15_29_dialog_content = "¿Cómo es posible que este Eclipsite pueda hablar? ¿Qué es esa tontería de \"Madre\" o \"Verdad\" de la que hablas?",
  ui_story_1_15_30_dialog_content = "¡No te molestes, PlayerName! Muy pocos Eclipsites hablan Universés, ¡así que éste parece un poco fuera de lugar!",
  ui_story_1_15_31_dialog_content = "¡Tch! Incluso aprendimos Universés para iluminar a los Aurorians, pero fue en vano. Las plagas serán plagas...",
  ui_story_1_15_32_dialog_content = "He mostrado suficiente respeto por los que pronto estarán muertos. Ahora...",
  ui_story_1_15_33_dialog_content = "Es tiempo de morir.",
  ui_story_1_15_34_option_content = "¡Debes estar refiriéndote a ti mismo!",
  ui_story_1_15_35_option_content = "¡Todos, prepárense para luchar!",
  ui_story_1_15_36_dialog_content = "¡Cómo te atreves a lastimarme! ¡Suficiente!",
  ui_story_1_15_37_dialog_content = "Había planeado perdonarte, ¡pero es difícil dominar una plaga sin matarla!",
  ui_story_1_15_38_dialog_content = "Me entregaste una tarea difícil, <color=#FFB400>Maestra Schummer</color>.",
  ui_story_1_15_39_dialog_content = "¿¡<color=#FFB400>Schummer</color>!? ¡Ese es el nombre de ese sueño! ¿De dónde lo escuchaste y quién es ella?",
  ui_story_1_15_40_dialog_content = "Veo que no estás completamente a oscuras sobre lo que sucedió en ese entonces, Celestita... ¿Y qué?",
  ui_story_1_15_B1_dialog_content = "Toda tu gente murió en nuestras manos. ¿Estás realmente satisfecho viviendo solo esta existencia vacía?",
  ui_story_1_15_B2_dialog_content = "¿Qué... dijiste?",
  ui_story_1_15_B3_dialog_content = "Qué pregunta más extraña. Creo que me escuchaste con claridad.",
  ui_story_1_15_B4_dialog_content = "Tu gente, están <color=#FFB400>todos muertos</color>.",
  ui_story_1_15_B5_dialog_content = "Eraveil ya no existe.",
  ui_story_1_15_B6_dialog_content = "Un mar de fuego y gritos frenéticos. Cuerpos aplastados, uno a uno... |\nY luego tirados.",
  ui_story_1_15_B7_dialog_content = "No... No... No puede ser.",
  ui_story_1_15_B8_dialog_content = "Imposible.",
  ui_story_1_15_B9_dialog_content = "¡Basta, Eclipsite! ¿¡Qué sabes!?",
  ui_story_1_15_B10_dialog_content = "Yo estuve allá. <color=#FFB400>Nosotros</color> todos estuvimos... ¿Quién podría permitirse perder un evento tan grandioso?",
  ui_story_1_15_B11_dialog_content = "Al igual que un día, atravesaremos las defensas de los Aurorians y te presentaremos el mismo regalo de aniquilación.",
  ui_story_1_15_41_dialog_content = "PlayerName, ¡no creas a ese Eclipsite!",
  ui_story_1_15_42_dialog_content = "Realmente no importa si me crees o no. Todos ustedes van a morir de todos modos.",
  ui_story_1_15_44_dialog_content = "¡No lo conseguirás!",
  ui_story_1_15_46_dialog_content = "¡Tonto! ¡Podrías haber vivido, pero has elegido la muerte!",
  ui_story_1_15_47_dialog_content = "¡Urgh!",
  ui_story_1_15_48_dialog_content = "¿Entonces tu brillante plan es atacarme imprudentemente, solo para ser aplastado bajo mis pies?",
  ui_story_1_15_49_dialog_content = "Sí, si es para plantar una <color=#FFB400>bomba</color>, ¡tonto!",
  ui_story_1_15_50_dialog_content = "¡Por qué tú...!",
  ui_story_1_15_53_dialog_content = "<size=45>Nos vemos en el infierno, idiota.</size>",
  ui_story_1_15_54_dialog_content = "¡PlayerName! ¡Ha habido una brecha en tu vecindad! ¡Procede con precaución!",
  ui_story_1_15_55_dialog_content = "¡La presión! ¡No puedo aguantar mucho más!",
  ui_story_1_15_56_dialog_content = "¡Espera-!",
  ui_story_1_15_B13_dialog_content = "¡Capitán!",
  ui_story_1_15_B14_dialog_content = "¡No te muevas! ¡Toma mi mano antes de que te succionen!",
  ui_story_1_15_B15_dialog_content = "¿Por qué resultó así? ¡Estábamos tan cerca!",
  ui_story_1_15_57_dialog_content = "¿Una explosión? No me digas, ¿ese Aurorian...?",
  ui_story_1_15_A4_dialog_content = "Esas cenizas de antes... ¿podría ser...?",
  ui_story_1_15_58_dialog_content = "¡Cálmate, PlayerName! Tu mente está vacilando...",
  ui_story_1_15_A5_dialog_content = "Y en mi memoria... Los cuerpos de mi gente...",
  ui_story_1_15_A6_dialog_content = "Todos muertos... ¿<color=#FFB400>Están todos muertos</color>? ¿Qué hay fuera de Eraveil y más allá del continente? ¿Soy realmente el <color=#FFB400>último Celestita</color>?",
  ui_story_1_15_A7_dialog_content = "¡Los latidos de tu corazón están aumentando! ¡Ten cuidado de no volver a esforzarte demasiado!",
  ui_story_1_15_B12_dialog_content = "No... No es así... No debería ser así. Apenas puedo...",
  ui_story_1_15_A8_dialog_content = "<size=45>¡Deja de jugar conmigo!</size>",
  ui_story_1_15_59_dialog_content = "¡El Colossus se acelera! No puedo aguantar más...",
  ui_story_1_15_60_dialog_content = "¿Qué has hecho, Celestita? Estoy perdiendo el control...",
  ui_story_1_15_61_dialog_content = "<size=45>No puede ser...</size>",
  ui_story_1_15_62_dialog_content = "<size=45>¡Navegador, baja la cabeza!</size>",
  ui_story_1_15_63_dialog_content = "¡Gaah!",
  ui_story_2_1_A1_dialog_content = "\"El Colossus por fin está en el aire.\"",
  ui_story_2_1_A2_dialog_content = "\"Por un tiempo, pensé que estaría atrapado bajo tierra para siempre...\"",
  ui_story_2_1_A3_dialog_content = "\"Pero tan pronto como lo logré...\"",
  ui_story_2_1_A4_dialog_content = "\"Mi vida perdió todo sentido...\"",
  ui_story_2_1_A5_dialog_content = "\"Porque mi pueblo... todos los Celestitas han sido aniquilados.\"",
  ui_story_2_1_1_dialog_content = "¿Estás escribiendo un diario?",
  ui_story_2_1_3_dialog_content = "Bueno, realmente no tenía nada más que hacer cuando estaba solo.",
  ui_story_2_1_4_dialog_content = "Llevar un diario me ayudó a controlar el tiempo, aunque no sirvió de mucho.",
  ui_story_2_1_5_dialog_content = "Es un gran hábito. A veces eres demasiado duro contigo mismo, PlayerName.",
  ui_story_2_1_6_dialog_content = "¿Cómo esta la situación?",
  ui_story_2_1_B26_dialog_content = "Estamos fuera de peligro por el momento. A casi todos los heridos se les han asignado plazas en la enfermería.",
  ui_story_2_1_B27_dialog_content = "El soldado que... se sacrificó...",
  ui_story_2_1_B28_dialog_content = "...",
  ui_story_2_1_B29_dialog_content = "No hay forma de recuperar el cuerpo, pero recogeré sus pertenencias personales y haré un memorial.",
  ui_story_2_1_B30_dialog_content = "...",
  ui_story_2_1_B31_dialog_content = "... ¿Es tu primera vez que presencias la muerte?",
  ui_story_2_1_B32_dialog_content = "No.",
  ui_story_2_1_B33_dialog_content = "No importa cuántas veces, nunca me acostumbraré.",
  ui_story_2_1_B34_dialog_content = "¿Qué pasa con... su familia?",
  ui_story_2_1_B35_dialog_content = "No te preocupes, la Federación Illumina se encargará de ellos.",
  ui_story_2_1_B37_dialog_content = "Recordaremos a todos los héroes que sacrificaron su vida por Illumina.",
  ui_story_2_1_B38_dialog_content = "Lo siento, PlayerName.",
  ui_story_2_1_B39_dialog_content = "¿Perdón por qué?",
  ui_story_2_1_B40_dialog_content = "Lo siento mucho, desde el fondo de mi corazón, por todo lo que pasó hoy...",
  ui_story_2_1_B41_dialog_content = "Pero seguimos vivos, y lo único que podemos hacer ahora es seguir adelante y no dejar que su sacrificio sea en vano.",
  ui_story_2_1_F1_dialog_content = "...",
  ui_story_2_1_7_dialog_content = "Entonces, ¿qué vas a hacer ahora?",
  ui_story_2_1_8_dialog_content = "... No lo sé.",
  ui_story_2_1_9_dialog_content = "¿Qué tal volver a Illumina conmigo?",
  ui_story_2_1_10_dialog_content = "¿Escuchaste lo que dijo Nozard antes?",
  ui_story_2_1_A8_dialog_content = "Escuché. Pero esa es sólo una cara de la historia.",
  ui_story_2_1_11_dialog_content = "Toda mi gente murió. Eraveil ya no existe.",
  ui_story_2_1_13_dialog_content = "...",
  ui_story_2_1_A9_dialog_content = "Todavía tienes una casa y gente que te está esperando, pero yo...",
  ui_story_2_1_14_dialog_content = "No pienses así, PlayerName...",
  ui_story_2_1_15_dialog_content = "¡Seguro que hay más sobrevivientes como tú!",
  ui_story_2_1_B1_dialog_content = "...",
  ui_story_2_1_B2_dialog_content = "¡Puedo ayudarte a encontrarlos!",
  ui_story_2_1_B3_dialog_content = "Lo siento, Vice. Sólo...",
  ui_story_2_1_B4_dialog_content = "Está bien, lo entiendo.",
  ui_story_2_1_B5_dialog_content = "Pasé 17 años bajo tierra pensando en Eraveil todos los días.",
  ui_story_2_1_B6_dialog_content = "Solo para descubrir que... ¿todo se había ido hace mucho tiempo? ¿Cómo podría aceptar eso? ¡No puedo!",
  ui_story_2_1_B7_dialog_content = "Entonces no lo hagas, PlayerName.",
  ui_story_2_1_B8_dialog_content = "¡Quiero saber exactamente qué pasó hace 17 años!",
  ui_story_2_1_B9_dialog_content = "¡Claro, podemos buscar la verdad en todo el continente!",
  ui_story_2_1_B10_dialog_content = "Pero hasta entonces, necesitas descansar. Vuelve a Illumina conmigo.",
  ui_story_2_1_A10_option_content = "Está bien. Iré contigo.",
  ui_story_2_1_A11_option_content = "No, debo seguir mi propia senda.",
  ui_story_2_1_A12_dialog_content = "Tienes razón, Vice.",
  ui_story_2_1_A13_dialog_content = "De todos modos, no tengo adónde ir ahora.",
  ui_story_2_1_A14_dialog_content = "Anímate. Créeme, ¡te encantará Illumina!",
  ui_story_2_1_B11_dialog_content = "¿<color=#FFB400>Schummer</color>, dices? Qué nombre tan extraño.",
  ui_story_2_1_B12_dialog_content = "No puedo borrar esa cara de mi mente... es todo lo que puedo hacer por ahora, creo.",
  ui_story_2_1_B13_dialog_content = "Entonces, primero debes prometerme que te protegerás a ti mismo y al Colossus.",
  ui_story_2_1_B14_dialog_content = "Después de que despejes tu mente y pongas a Soroz en forma, te acompañaré en el resto de tu aventura.",
  ui_story_2_1_A15_dialog_content = "¿Por qué?",
  ui_story_2_1_A16_dialog_content = "Bueno, porque la Federación Illumina...",
  ui_story_2_1_A17_dialog_content = "Lo que quiero decir es, ¿por qué estás tan dispuesta a ayudarme y ser mi amiga?",
  ui_story_2_1_A18_dialog_content = "¿Tengo que explicarlo? Me salvaste la vida, ¿recuerdas?",
  ui_story_2_1_A19_dialog_content = "Eso y tus habilidades significan mucho para los Aurorians...",
  ui_story_2_1_A20_dialog_content = "Es el programa Colossus Navegador, ¿no?",
  ui_story_2_1_A21_dialog_content = "¡Se llama el programa de Reconstrucción de Colossus y Desarrollo de Navegador!",
  ui_story_2_1_A22_dialog_content = "De hecho, yo también... ¡Eso no es importante ahora!",
  ui_story_2_1_A23_dialog_content = "Aunque no tengo idea de por qué estás haciendo esto...",
  ui_story_2_1_F2_dialog_content = "Confío en ti, Vice.",
  ui_story_2_1_A24_dialog_content = "Gracias, PlayerName.",
  ui_story_2_1_A25_dialog_content = "Muy bien, ¡busquemos la Subciudad Illumina más cercana lo antes posible! ¡Necesitamos descansar y reagruparnos!",
  ui_story_2_1_A26_dialog_content = "Lo he intentado todos estos años.",
  ui_story_2_1_A28_dialog_content = "Todos los días, traté de iniciar el Colossus, solo para desmayarme en innumerables ocasiones.",
  ui_story_2_1_B15_dialog_content = "Todos los días, estudié el conocimiento almacenado en Soroz. No sé si algo de eso me puede ayudar ahora.",
  ui_story_2_1_B16_dialog_content = "Todos los días, anhelaba ver el mundo exterior y algún día regresar a Eraveil.",
  ui_story_2_1_B17_dialog_content = "Sé que lo intentaste mucho, PlayerName.",
  ui_story_2_1_B19_dialog_content = "Creo que tengo mi propio camino a seguir.",
  ui_story_2_1_B20_dialog_content = "Pero, ¿a dónde vas a ir?",
  ui_story_2_1_B21_dialog_content = "...",
  ui_story_2_1_B22_dialog_content = "A casa, a Eraveil.",
  ui_story_2_1_B23_dialog_content = "Y quiero encontrar a <color=#FFB400>Schummer</color>.",
  ui_story_2_1_A29_dialog_content = "¡Es demasiado peligroso para que lo hagas solo, PlayerName!",
  ui_story_2_1_A30_dialog_content = "Sé que lo es, pero quiero saber la verdad. Quiero ir a casa.",
  ui_story_2_1_A31_dialog_content = "Tú y Soroz acaban de regresar a la superficie y ya han pasado por el infierno. Ustedes dos deberían descansar primero.",
  ui_story_2_1_A32_dialog_content = "Después de que ambos se recuperen, puedo ayudarlos a encontrar...",
  ui_story_2_1_A33_dialog_content = "¿Por qué me ayudarías?",
  ui_story_2_1_A34_dialog_content = "¿Tengo que explicarlo? Me salvaste la vida, ¿recuerdas?",
  ui_story_2_1_A35_dialog_content = "Eso... y tus habilidades realmente podrían ser de utilidad para nosotros los Aurorians...",
  ui_story_2_1_A36_dialog_content = "...",
  ui_story_2_1_A37_dialog_content = "¡Podemos luchar juntos contra enemigos comunes, como los Celestitas y Aurorians antes que nosotros!",
  ui_story_2_1_A38_dialog_content = "Pero antes de eso, tenemos que darnos prisa e ir a la Subciudad Illumina más cercana para descansar y reagruparnos...",
  ui_story_2_1_19_dialog_content = "¡Oh! ¿Qué ocurre?",
  ui_story_2_1_20_dialog_content = "¿¡Qué pasó, Soroz!?",
  ui_story_2_1_21_dialog_content = "El sistema de navegación está dañado en varias áreas y no se puede reparar en este momento.",
  ui_story_2_1_22_dialog_content = "17 años de mantenimiento descuidado nos están alcanzando. Parece que debemos volver al nivel del suelo.",
  ui_story_2_1_23_dialog_content = "Me temo que esto es lo más lejos que puedo llevarte, PlayerName.",
  ui_story_2_1_24_dialog_content = "...",
  ui_story_2_1_25_dialog_content = "Pase lo que pase, ¡protégete y protege a tus compañeros!",
  ui_story_2_1_26_dialog_content = "Creo en ti... Te volverás... fuerte...",
  ui_story_2_1_A43_dialog_content = "¡Soroz! ¡Soroz!",
  ui_story_2_1_27_dialog_content = "¡¡¡PlayerName!!!",
  ui_story_2_1_28_dialog_content = "¡¡¡Prepárate para el impacto!!!",
  ui_story_2_1_29_dialog_content = "Solo sentí una intensa ola de Lumina.",
  ui_story_2_1_30_dialog_content = "Maestro Schummer, todo está todavía bajo mi control.",
  ui_story_2_1_A44_dialog_content = "Gran charla proveniente del fracaso que fue arrojado desde el cielo. Sería mejor no hacer promesas que no puedas cumplir.",
  ui_story_2_1_A45_dialog_content = "...",
  ui_story_2_1_X1_dialog_content = "Eres más duro que Kraken, te concedo eso. Pero si no puedes cumplir nuestras órdenes...",
  ui_story_2_1_X2_dialog_content = "Entonces eres un inútil, Nozard.",
  ui_story_2_1_31_dialog_content = "El Colossus no puede protegerlos para siempre. Su desafío es inútil.",
  ui_story_2_1_32_dialog_content = "Pronto entregaré el resultado que esperas.",
  ui_story_2_1_33_dialog_content = "Agradece la segunda oportunidad. Será mejor que termines con esto antes de que se me acabe la paciencia.",
  ui_story_2_1_35_dialog_content = "Como desees, Maestro.",
  ui_story_2_1_36_dialog_content = "(Hablando en Eclipsiano) Colossus... cayó... naturaleza... en el oeste...",
  ui_story_2_1_37_dialog_content = "(Hablando en Eclipsiano) El Oeste. Invoca los <color=#FFB400> Umbrahulks</color>.",
  ui_story_2_1_38_dialog_content = "(Hablando en Eclipsiano) A tus órdenes.",
  ui_story_2_1_39_dialog_content = "(Hablando en Eclipsiano) Persíguelos y mátalos... ¡Me uniré a ustedes en breve!",
  ui_story_2_1_40_dialog_content = "(Hablando en Eclipsiano) ¡Entendido! ¡Eclipsites, a la ofensiva!",
  ui_story_2_2_2_dialog_content = "Ay... ¿Ah?",
  ui_story_2_2_3_dialog_content = "Podrías quitarte de encima, Vice...",
  ui_story_2_2_A1_dialog_content = "¿Ah? Oh lo siento... ¿Estás bien?",
  ui_story_2_2_A2_dialog_content = "Todavía vivo, al menos...",
  ui_story_2_2_4_dialog_content = "¡¿Ya estamos rodeados de Eclipsites?! ¿Tan pronto?",
  ui_story_2_2_5_dialog_content = "PlayerName, ¡dame tu comando!",
  ui_story_2_2_6_dialog_content = "<color=#e8d9bb>El fuerte estallido de la caída atrajo a varios Eclipsites.</color>",
  ui_story_2_3_1_dialog_content = "¿Cuál es la situación actual?",
  ui_story_2_3_2_dialog_content = "Detectamos hordas de Eclipsites acercándose, Teniente Vice, pero no tenemos suministros de combate.",
  ui_story_2_3_3_dialog_content = "¿Dónde está la Subciudad más cercana?",
  ui_story_2_3_A1_dialog_content = "Subciudad 28 no está muy lejos. Allí podemos refugiarnos.",
  ui_story_2_3_A2_dialog_content = "¡A tus órdenes, Teniente Vice!",
  ui_story_2_3_4_dialog_content = "¡Todas las tropas se dirigen a la Subciudad 28 a toda velocidad!",
  ui_story_2_3_6_dialog_content = "¡Vamos, PlayerName!",
  ui_story_2_3_7_dialog_content = "No te preocupes por mí y vete.",
  ui_story_2_3_8_dialog_content = "¡¿PlayerName?!",
  ui_story_2_3_A3_dialog_content = "Debes irte ya antes de que sea muy tarde.",
  ui_story_2_3_A4_dialog_content = "¿No vienes con nosotros?",
  ui_story_2_3_9_dialog_content = "Soroz está en muy mal estado para que me vaya.",
  ui_story_2_3_10_dialog_content = "Sobreviví durante 17 años, todo gracias a Soroz. Soroz es la única \"familia\" que tengo.",
  ui_story_2_3_A5_dialog_content = "...",
  ui_story_2_3_11_dialog_content = "Si todo lo que dijo Nozard fuera cierto...",
  ui_story_2_3_12_dialog_content = "Pase lo que pase, nunca volveré a dejar Soroz.",
  ui_story_2_3_13_dialog_content = "¿Cómo vas a luchar tú solo contra todos los Eclipsites aquí?",
  ui_story_2_3_A6_dialog_content = "Están detrás de mí, ¿verdad? Sería bueno para todos si me quedo.",
  ui_story_2_3_14_dialog_content = "¡¡Tú...!!",
  ui_story_2_3_15_dialog_content = "Entiendo. ¡Lleva a todos a la Subciudad, soldado!",
  ui_story_2_3_A7_dialog_content = "Y tú qué, Teniente Vice...",
  ui_story_2_3_A8_dialog_content = "¡Deja de perder el tiempo y vete ahora!",
  ui_story_2_3_A9_dialog_content = "¡Sí!",
  ui_story_2_3_A10_dialog_content = "Ya me has ayudado bastante, Vice. Deberías ir con tus camaradas.",
  ui_story_2_3_16_dialog_content = "Tú también eres mi camarada. ¡No puedo dejarte aquí para que mueras!",
  ui_story_2_3_17_dialog_content = "A este paso, los dos moriremos si no te vas.",
  ui_story_2_3_18_dialog_content = "¡¡PlayerName...!!",
  ui_story_2_3_19_dialog_content = "<anim type=Shake><size=45>*Rugido*</size></anim>",
  ui_story_2_3_B3_dialog_content = "¡Vice!",
  ui_story_2_3_B4_dialog_content = "¡A-atrás! ¡Encuentra un lugar seguro para esconderte primero!",
  ui_story_2_3_B5_dialog_content = "Se han reunido tan rápido...",
  ui_story_2_3_B6_option_content = "Establece un vínculo mental",
  ui_story_2_3_B7_dialog_content = "¡¡¡Wooga-!!!",
  ui_story_2_3_B8_dialog_content = "¡No puedo dejarte atrás!",
  ui_story_2_3_B9_dialog_content = "Vice...",
  ui_story_2_3_B10_dialog_content = "¡Gaah!",
  ui_story_2_3_22_dialog_content = "¡Ahhh-!",
  ui_story_2_3_A11_dialog_content = "¡Muy doloroso! No puedo enfocarme...",
  ui_story_2_3_F1_dialog_content = "¡Espera, PlayerName! ¡Estaré ahí!",
  ui_story_2_3_B11_dialog_content = "<anim type=Shake><size=45>*Rugido*</size></anim>",
  ui_story_2_3_B12_dialog_content = "<color=#e8d9bb>Sin tiempo para reaccionar, varios Eclipsites se abalanzaron sobre Vice una vez más-</color>",
  ui_story_2_3_B13_dialog_content = "Argh-",
  ui_story_2_3_B14_dialog_content = "¡Corre! Escóndete... Vamos...",
  ui_story_2_3_B15_dialog_content = "¿¡Vice!?",
  ui_story_2_3_24_option_content = "Establece un vínculo mental",
  ui_story_2_3_25_dialog_content = "No es bueno, está inconsciente...",
  ui_story_2_3_26_dialog_content = "Pelea... Necesito pelear... No puedo simplemente sentarme aquí...",
  ui_story_2_3_27_dialog_content = "<color=#e8d9bb>Los Eclipsites pasaron por encima de la inconsciente Vice y te rodearon...</color>",
  ui_story_2_3_28_dialog_content = "Oye, oye, oye, arriesgar tu vida no resolverá el problema. Matar Eclipsites es una forma de arte.",
  ui_story_2_3_29_dialog_content = "¡Es hora de jugar!",
  ui_story_2_3_30_dialog_content = "<size=45>¡¡Muévete!! ¡¡Muévete!!</size>",
  ui_story_2_3_31_dialog_content = "¡Si jefe!",
  ui_story_2_3_32_dialog_content = "¡Cuidado con la explosión!",
  ui_story_2_3_33_dialog_content = "¡Vamos de fiesta!",
  ui_story_2_3_34_dialog_content = "¡Hazte a un lado, estás en el camino!",
  ui_story_2_3_36_dialog_content = "¿Quién eres? ¿Qué quieres?",
  ui_story_2_3_37_dialog_content = "¿No es obvio? Estamos aquí para robarte.",
  ui_story_2_3_38_dialog_content = "Te salvamos la vida, así que danos todos tus tesoros, ¡rápido!",
  ui_story_2_3_F2_dialog_content = "¡Jajajajaja!",
  ui_story_2_3_39_dialog_content = "Permíteme presentarme, mi nombre es <color=#FFB400>Sinsa</color>, líder de <color=#FFB400>Rediesel Wrench</color>.",
  ui_story_2_3_40_dialog_content = "Esta a la que le gusta posar es <color=#FFB400>Regina</color>.",
  ui_story_2_3_41_dialog_content = "La que juega con bombas es <color=#FFB400>Joanie Boom</color>.",
  ui_story_2_3_42_dialog_content = "Son mis manos derechas.",
  ui_story_2_3_43_dialog_content = "¿Rediesel Wrench? ¿Robándonos...? ¿Qué estás haciendo? ¡No te atrevas a tocar el Colossus!",
  ui_story_2_3_44_dialog_content = "¿Te refieres a este grandulón de aquí? ¿Por qué no podemos entrar? ¡Tendré que hacerle un agujero!",
  ui_story_2_3_45_dialog_content = "¡Vamos! ¡Es hora de cargar!",
  ui_story_2_3_46_dialog_content = "¡Hurra! ¡Viva Joanie Boom!",
  ui_story_2_3_47_dialog_content = "¡Je, un Colossus! ¡Es mi día de suerte!",
  ui_story_2_3_A12_dialog_content = "¡Derríbalo y llévalo a casa!",
  ui_story_2_3_48_dialog_content = "¡No puedo dejar pasar una oportunidad como esta!",
  ui_story_2_3_49_dialog_content = "¡No destruyas a Soroz, el Colossus! Hay una persona con soporte vital...",
  ui_story_2_3_50_dialog_content = "¡Mi compañera Vice está herida y lo necesita!",
  ui_story_2_3_51_dialog_content = "Parece que esta joven ha recibido un gran golpe.",
  ui_story_2_3_52_dialog_content = "¿Este uniforme? ¿Es de Illumina?",
  ui_story_2_3_53_dialog_content = "No nos llevamos tan bien con estos oficiales como podrías pensar...",
  ui_story_2_3_54_dialog_content = "Además, el Colossus es ahora de nuestra propiedad. Para salvar a la niña, tendrás que cambiarla por otra cosa.",
  ui_story_2_3_55_dialog_content = "A juzgar por tu apariencia, no eres rico. ¿Cuánto tiempo ha pasado desde la última vez que lavaste esos trapos que estás usando?",
  ui_story_2_3_56_option_content = "Pero SOY rico. ¡Muy rico en verdad!",
  ui_story_2_3_57_option_content = "¡No se metan conmigo, Aurorians!",
  ui_story_2_3_58_dialog_content = "A decir verdad, lo más valioso es este Colossus. Nunca has visto uno antes, ¿verdad?",
  ui_story_2_3_59_dialog_content = "¡Ja, como sí! Pero, comparado con el de nuestra base, este está bastante intacto...",
  ui_story_2_3_60_dialog_content = "Así es, si continúas derribándolo, dejará de ser valioso.",
  ui_story_2_3_61_dialog_content = "Tsk. Eso es un problema. ¡Pensé que podría hacer todo lo posible esta vez! ¿Y ahora qué, jefe?",
  ui_story_2_3_62_dialog_content = "...",
  ui_story_2_3_63_dialog_content = "Este tipo tiene razón. Esperemos por ahora.",
  ui_story_2_3_64_dialog_content = "¡Estás en lo correcto! ¡Todos deténganse!",
  ui_story_2_3_65_dialog_content = "¡Eh, tú! Ven aquí.",
  ui_story_2_3_66_dialog_content = "¿Dime quién eres tú?",
  ui_story_2_3_67_dialog_content = "...",
  ui_story_2_3_68_dialog_content = "Podría adivinarlo incluso si no me lo dices. Solo las personas de hace 17 años usarían el tipo de ropa que tienes.",
  ui_story_2_3_69_dialog_content = "¡Es impresionante que hayas logrado sobrevivir tanto tiempo con esta enorme cosa alrededor!",
  ui_story_2_3_70_dialog_content = "¿Tú sabes quién soy?",
  ui_story_2_3_71_dialog_content = "No fue hace tanto tiempo, <color=#FFB400>Celestita</color>. No soy olvidadizo.",
  ui_story_2_3_72_dialog_content = "¡No sabes quién soy ni qué pasará si te metes conmigo! Soy... ¡No te tengo miedo!",
  ui_story_2_3_73_dialog_content = "...",
  ui_story_2_3_74_dialog_content = "¿Te golpeaste la cabeza o algo?",
  ui_story_2_3_75_dialog_content = "¿Intentas amenazarnos solo porque eres <color=#FFB400>de alguna raza especial</color>?",
  ui_story_2_3_76_dialog_content = "En serio, somos unos ladrones viciosos.",
  ui_story_2_3_77_dialog_content = "... ¿Tú sabes quién soy?",
  ui_story_2_3_78_dialog_content = "Vamos, la ropa que llevas puesta, el Colossus y la mirada desconcertada, cualquiera podría haberlo adivinado.",
  ui_story_2_3_79_dialog_content = "Debería poder conseguir una suma considerable...",
  ui_story_2_3_80_dialog_content = "¡¿V-venderme?! ¡¿Cómo es que me tratas de manera tan diferente a pesar de que también eres Aurorian?!",
  ui_story_2_3_81_dialog_content = "No nos malinterpretes, <color=#FFB400>Celestita</color>. No eres nada para nosotros los bandidos.",
  ui_story_2_3_82_dialog_content = "¿Celestitas? ¿Los asesinados por Eclipsites?",
  ui_story_2_3_B1_dialog_content = "Asesinados...",
  ui_story_2_3_B2_dialog_content = "Entonces, hace 17 años, ¿nadie más sobrevivió al ataque a Eraveil?",
  ui_story_2_3_83_dialog_content = "¿Conoces más detalles?",
  ui_story_2_3_84_dialog_content = "Lo siento, pero fue todo tan repentino. Todo terminó en una noche.",
  ui_story_2_3_85_dialog_content = "Yo era solo un niño entonces, así que no podía saber mucho, ¿no?",
  ui_story_2_3_89_dialog_content = "¡Bien, suficiente de esta tontería! No importa si es el Celestita o el Colossus, ¡ahora eres todo nuestro!",
  ui_story_2_3_90_dialog_content = "Entonces, sobre Vice...",
  ui_story_2_3_91_dialog_content = "¡Fue enviada a <color=#FFB400>soporte vital</color> para un tratamiento hace mucho tiempo! ¡Somos ladrones, no asesinos!",
  ui_story_2_3_92_dialog_content = "Por qué sabes tanto sobre el Colossus...",
  ui_story_2_3_93_dialog_content = "Ustedes, Celestitas, no son los únicos con Colossus. En Rediesel Wrench también tenemos nuestro propio <color=#FFB400>Correcaminos</color>.",
  ui_story_2_3_94_dialog_content = "¡Veamos si alguien nos da el dinero de tu rescate, Celestita!",
  ui_story_2_4_1_dialog_content = "Jefe, hay una ola de Eclipsites dirigiéndose hacia nosotros.",
  ui_story_2_4_2_dialog_content = "¿Cómo vamos a arrastrar el Colossus si siguen viniendo así?",
  ui_story_2_4_3_dialog_content = "Por cierto, PlayerName, los Eclipsites te perseguían antes de que llegáramos, ¿no?",
  ui_story_2_4_4_dialog_content = "Entiendo...",
  ui_story_2_4_5_dialog_content = "Maldita sea, más problemas.",
  ui_story_2_4_6_dialog_content = "¡Arriba, muchachos! ¡Es hora de exterminar algunos bichos!",
  ui_story_2_4_7_dialog_content = "¿Por qué no nos muestra la legendaria habilidad psíquica de los Celestitas?",
  ui_story_2_4_8_dialog_content = "¿Quieres que te guíe...?",
  ui_story_2_4_9_dialog_content = "¡Por supuesto, es difícil dejar pasar este tipo de oportunidad! ¡Muéstranos ese Sendero de Luz tuyo!",
  ui_story_2_4_10_dialog_content = "¡Enemigos entrantes! ¡Saca tus armas! ¡Manténganse vivos!",
  ui_story_2_8_1_dialog_content = "Este tipo de maniobras no se puede atribuir a una mera coincidencia.",
  ui_story_2_8_2_dialog_content = "¿Desde cuándo los Eclipsites se han vuelto inteligentes?",
  ui_story_2_8_3_dialog_content = "¿Qué opinas, Joanie?",
  ui_story_2_8_4_dialog_content = "¿Podría haber algún Eclipsite de alto nivel al mando?",
  ui_story_2_8_5_dialog_content = "¡No nos maldigas!",
  ui_story_2_8_7_dialog_content = "Eclipsite de alto nivel...",
  ui_story_2_8_B1_dialog_content = "¿Qué, ya es hora?",
  ui_story_2_8_B2_dialog_content = "Jefe, ¡finalmente lo recuerdas!",
  ui_story_2_8_B3_dialog_content = "Lo siento, es tan emocionante luchar junto a un Celestita que perdí la noción del tiempo...",
  ui_story_2_8_B4_dialog_content = "¡Tomemos un descanso del trabajo por ahora! ¡<color=#FFB400>Es hora de cenar</color>!",
  ui_story_2_8_B5_dialog_content = "<anim type=Shake><size=45>¡¡¡Yaaaaargh!!! ¡Es hora de cenar!</size></anim>",
  ui_story_2_8_SS_dialog_content = "Picnic CG Rediesel",
  ui_story_2_8_B6_dialog_content = "¡Oye! ¡No empujes! ¿¡No sabes que deberías dejar que tu jefe vaya primero!?",
  ui_story_2_8_B7_dialog_content = "¡Jaja! ¡Vas primero! ¡Déjame dos barriles!",
  ui_story_2_8_B8_dialog_content = "¿Qué... haces exactamente?",
  ui_story_2_8_B9_dialog_content = "Comiendo. ¿Por qué es esto extraño? ¿Nunca has comido antes?",
  ui_story_2_8_B10_dialog_content = "Quiero decir, ustedes son tan salvajes...",
  ui_story_2_8_B11_dialog_content = "Esta es la única manera de sobrevivir en este mundo, PlayerName. No subestimes nuestra tenacidad.",
  ui_story_2_8_B12_dialog_content = "¡Solo podemos vivir si comemos y bebemos, y vivimos para comer y beber!",
  ui_story_2_8_B13_dialog_content = "¡Sigue hablando con el Celestita y nos comeremos toda la carne, Sinsa!",
  ui_story_2_8_B14_dialog_content = "¡Te arrebaté dos <color=#FFB400>lagartijas asadas</color>!",
  ui_story_2_8_B15_dialog_content = "Dáselo al Celestita. No tengo hambre.",
  ui_story_2_8_B16_dialog_content = "¡Aquí!",
  ui_story_2_8_B17_dialog_content = "... Yo... Yo tampoco tengo hambre...",
  ui_story_2_8_B18_dialog_content = "¿Por qué siempre te ves tan deprimido?",
  ui_story_2_8_B19_dialog_content = "¿No dijiste que es tu primera vez en el mundo exterior?",
  ui_story_2_8_B20_dialog_content = "¿No quieres celebrar?",
  ui_story_2_8_B21_dialog_content = "¿Por qué estás reteniendo todo?",
  ui_story_2_8_B22_dialog_content = "¿Qué pasa? ¿El exterior no es tan bueno como el subterráneo?",
  ui_story_2_8_B23_dialog_content = "¿Ah?",
  ui_story_2_8_B24_dialog_content = "No me importa por lo que hayas pasado, pero ¿no estás tú, el Colossus y esa chica a salvo ahora?",
  ui_story_2_8_B25_dialog_content = "No habrías vivido tanto tiempo si no tuvieras nada que aportar.",
  ui_story_2_8_B26_dialog_content = "No es fácil vivir en este mundo, pero serías un tonto al pensar que eres único que la tiene difícil.",
  ui_story_2_8_B27_dialog_content = "¿Para qué necesito un tonto? Debería matarte y ahorrarme el problema.",
  ui_story_2_8_B28_dialog_content = "Habría problemas si me mataras. ¡L-La Illumina no te dejará escapar!",
  ui_story_2_8_B29_dialog_content = "¡Jajajajajaja!",
  ui_story_2_8_B30_dialog_content = "¿Qué es tan gracioso?",
  ui_story_2_8_B33_dialog_content = "¡Supongo que después de todo no eres tonto!",
  ui_story_2_8_8_dialog_content = "¡Encontré al Celestita!",
  ui_story_2_8_9_dialog_content = "¿¡Es un <color=#FFB400>Umbrahulk</color>!?",
  ui_story_2_8_B34_dialog_content = "¡Los Eclipsites! ¡¿Realmente vienen por mí?!",
  ui_story_2_8_B35_dialog_content = "¡Deja tu comida y ponte en formación! ¡Es hora de luchar!",
  ui_story_2_8_10_dialog_content = "¿Atacando en medio de una comida? ¿A qué viene el mundo?",
  ui_story_2_8_B36_dialog_content = "Supongo que necesito enseñarte algunos modales yo mismo.",
  ui_story_2_8_11_dialog_content = "Es un poco más difícil de lo que imaginaba...",
  ui_story_2_8_12_dialog_content = "Este <color=#FFB400>tren</color>...",
  ui_story_2_8_13_dialog_content = "No, no <color=#FFB400>ese tipo</color>...",
  ui_story_2_8_14_dialog_content = "Eso es vergonzoso, Sinsa.",
  ui_story_2_8_15_dialog_content = "¿Estás jugando a las casitas con los Eclipsites?",
  ui_story_2_8_16_dialog_content = "Sabía que eras tú. No he robado ninguno de tus suministros últimamente.",
  ui_story_2_8_17_dialog_content = "Estoy aquí para llevar a mi compañera de regreso a Illumina, pero me ocuparé de ti más tarde.",
  ui_story_2_8_18_dialog_content = "Oh, ¿esa jovencita?",
  ui_story_2_8_19_dialog_content = "¡Qué casualidad! Estaba considerando enviarla de regreso antes.",
  ui_story_2_8_20_dialog_content = "No solo ella, sino también este Colossus. Pertenece a la <color=#FFB400>Federación Illumina</color>.",
  ui_story_2_8_21_dialog_content = "¡No insistas, monstruo de pelo blanco!",
  ui_story_2_8_22_dialog_content = "Volaré tu auto.",
  ui_story_2_8_23_dialog_content = "¡Fácil, Bing Bang Boom!",
  ui_story_2_8_24_dialog_content = "Este tipo es un oponente mucho más duro que ese Umbrahulk.",
  ui_story_2_8_25_dialog_content = "Es solo un Colossus, y como no podemos desmantelarlo ni venderlo, en realidad no es tan importante para nosotros.",
  ui_story_2_8_26_dialog_content = "¡Hmph! ¡Tuviste suerte!",
  ui_story_2_8_B37_dialog_content = "Charon, espero que sepas con lo que estás lidiando.",
  ui_story_2_8_B38_dialog_content = "PlayerName, eres más interesante de lo que pensaba.",
  ui_story_2_8_B39_dialog_content = "¿Ah?",
  ui_story_2_8_B40_dialog_content = "¡Qué vergüenza! No te encuentras con un tesoro tan raro todos los días.",
  ui_story_2_8_B41_dialog_content = "PlayerName, realmente deberías relajarte...",
  ui_story_2_8_B42_dialog_content = "Pero aún brillas con el aura de la luz.",
  ui_story_2_8_B43_dialog_content = "¿El aura de la luz? Pero no puedo usar el poder de la Luz-",
  ui_story_2_8_B44_dialog_content = "¡Caramba! ¡Es simplemente una expresión!",
  ui_story_2_8_B48_dialog_content = "¿No puedes sólo escupirlo? No tienes que ser tan críptico.",
  ui_story_2_8_B49_dialog_content = "Jajaja... ¡Ese es el espíritu! ¡Parece que ya te sientes mejor!",
  ui_story_2_8_B50_dialog_content = "Recuerda esto, Celestita, es fácil morir, ¡pero también podrías vivir mientras puedas!",
  ui_story_2_8_B51_dialog_content = "Esta cosa llamada \"<color=#FFB400>esperanza</color>\" siempre se puede encontrar.",
  ui_story_2_8_B52_dialog_content = "La esperanza se encuentra incluso en los días más brillantes o en las noches más oscuras.",
  ui_story_2_8_B53_dialog_content = "¿De dónde has sacado eso?",
  ui_story_2_8_B54_dialog_content = "Hmm... Yo olvido.",
  ui_story_2_8_B55_dialog_content = "Hace unos días que no te veo y veo que has empezado a leer libros.",
  ui_story_2_8_B56_dialog_content = "¡Jajajaja! ¡No nos subestimes a los obstinados vagabundos! ¡Adiós a todos!",
  ui_story_2_8_28_dialog_content = "Tengo el presentimiento de que nos volveremos a encontrar...",
  ui_story_2_8_29_dialog_content = "Rediesel Wrench, ¡volvamos a casa y nos premiamos con unos gusanos de arena hoy!",
  ui_story_2_8_31_dialog_content = "... ¿No puedes traer buenas noticias por una vez, Nozard?",
  ui_story_2_8_32_dialog_content = "Han llegado los refuerzos de Illumina. Es un Aurorian llamado <color=#FFB400>Charon</color>...",
  ui_story_2_8_33_dialog_content = "¿Charon? Ha pasado tanto tiempo desde que escuché ese nombre.",
  ui_story_2_8_34_dialog_content = "Entonces, ¿el Celestita también fue quitado?",
  ui_story_2_8_35_dialog_content = "Se dirigen hacia <color=#FFB400>Subciudad 28</color>.",
  ui_story_2_8_36_dialog_content = "Al menos Umbrahulk descubrió a dónde se dirigían. Sabes qué hacer a continuación.",
  ui_story_2_8_37_dialog_content = "¡Sí!",
  ui_story_2_8_38_dialog_content = "Subciudad Aurorian...",
  ui_story_2_8_39_dialog_content = "¿Creen estos ratones que pueden esconderse en sus madrigueras y descansar tranquilos?",
  ui_story_2_8_40_dialog_content = "Cobardes... Si ahí es donde te vas a esconder...",
  ui_story_2_8_41_dialog_content = "¡Prepárate para ver morir a todos contigo!",
  ui_story_2_9_1_dialog_content = "¿Quién eres?",
  ui_story_2_9_2_dialog_content = "Soy director de <color=#FFB400>Logística Subciudad 28</color>.",
  ui_story_2_9_3_dialog_content = "Llámame Charon.",
  ui_story_2_9_4_dialog_content = "¿Dónde está Vice?",
  ui_story_2_9_5_dialog_content = "Ella está en soporte vital en el Colossus. Ella se lastimó. Yo... no pude protegerla.",
  ui_story_2_9_6_dialog_content = "¿Y tú eres de Vice...?",
  ui_story_2_9_7_dialog_content = "Vice informó sobre su misión de exploración aquí antes.",
  ui_story_2_9_8_dialog_content = "Luego vi las señales de socorro del Colossus y seguí a los Eclipsites hacia ti.",
  ui_story_2_9_9_dialog_content = "¿Cómo está Vice?",
  ui_story_2_9_10_dialog_content = "Su lesión ha sido estabilizada por el dispositivo de soporte vital del Colossus.",
  ui_story_2_9_11_dialog_content = "¿Qué hacemos ahora?",
  ui_story_2_9_12_dialog_content = "Realmente tienes muchas preguntas. ¿Por qué no vuelves a Subciudad 28 conmigo por ahora?",
  ui_story_2_9_13_dialog_content = "¡Oficial Charon ha regresado!",
  ui_story_2_9_14_dialog_content = "¡Whoa! ¡Eso es enorme! ¿Qué es eso?",
  ui_story_2_9_15_dialog_content = "Rápido, informe a Transporte para abrir el riel exclusivo de Charon.",
  ui_story_2_9_17_dialog_content = "¡Bienvenida de nuevo, oficial Charon!",
  ui_story_2_9_18_dialog_content = "¡¿Esto es... un Colossus?!",
  ui_story_2_9_19_dialog_content = "Sí, y hay alguien herido en el Colossus. Avisen al equipo médico.",
  ui_story_2_9_20_dialog_content = "Además, un escuadrón de Illumina... sacrificó sus vidas.",
  ui_story_2_9_21_dialog_content = "Sí, señor. Haré los arreglos necesarios y desplegaré respaldos de inmediato.",
  ui_story_2_9_22_dialog_content = "Bien. Gracias.",
  ui_story_2_9_23_dialog_content = "¿Cómo está la primera línea?",
  ui_story_2_9_24_dialog_content = "¡Nada inusual!",
  ui_story_2_9_25_dialog_content = "Eso es extraño. ¿Cómo logró un número tan grande de Eclipsites cruzar la línea del frente?",
  ui_story_2_9_26_dialog_content = "Dile a la división de comunicaciones que se comunique con la <color=#FFB400>Sede en Gannon</color>. Deseo hablar con ellos más tarde.",
  ui_story_2_9_B1_dialog_content = "...",
  ui_story_2_9_B2_dialog_content = "¿Qué pasa? ¿Nunca viste una ciudad subterránea tan grande o una organización tan impresionante?",
  ui_story_2_9_B3_dialog_content = "Aquí... ¿Es esto Illumina?",
  ui_story_2_9_B4_dialog_content = "Esta es solo una de las Subciudad de la Federación Illumina— Número 28.",
  ui_story_2_9_B5_dialog_content = "Aunque Subciudad 28 no es la primera línea en la batalla contra Eclipsites, seguimos siendo una base logística indispensable.",
  ui_story_2_9_F1_dialog_content = "Si cayéramos, los Eclipsites romperían la línea y marcharían directamente hacia...",
  ui_story_2_9_B6_dialog_content = "Oh, Celestita, ¿has estudiado geografía?",
  ui_story_2_9_F2_dialog_content = "Yo... Entendí un poco. Si los Eclipsites rompieran la línea, podrían incursionar en el corazón del continente, ¿verdad?",
  ui_story_2_9_B7_dialog_content = "¡Correcto! Por un lado el día eterno, el otro por la noche eterna, esta tierra es el único lugar donde podemos sobrevivir. No tenemos otro lugar donde ir.",
  ui_story_2_9_B8_dialog_content = "Aquí en Illumina nacimos para luchar contra los Eclipsites. Es nuestro propósito y destino.",
  ui_story_2_9_B9_dialog_content = "Debemos proteger nuestro precioso hogar.",
  ui_story_2_9_B10_dialog_content = "¿Tu hogar? ¿Te refieres a la tierra de los Aurorians?",
  ui_story_2_9_B11_dialog_content = "Para ser precisos, es donde se pueden encontrar todas las <color=#FFB400>cosas que apreciamos</color>.",
  ui_story_2_9_B13_dialog_content = "Podrían ser Aurorians, podrían ser ruinas perdidas, incluso podría ser un recuerdo insignificante.",
  ui_story_2_9_B14_dialog_content = "Parece... ¿bastante sentimental?",
  ui_story_2_9_B15_dialog_content = "¿Sentimental? Esa es la motivación para seguir viviendo.",
  ui_story_2_9_B16_dialog_content = "En otras palabras, ¡es <color=#FFB400>esperanza</color>!",
  ui_story_2_9_B17_dialog_content = "Si no se puede evitar la desesperación, debemos superar los tiempos oscuros con esperanza.",
  ui_story_2_9_B18_dialog_content = "Sí, de alguna manera se siente poético.",
  ui_story_2_9_B19_dialog_content = "... De alguna manera me recuerda lo que dijo Sinsa una vez.",
  ui_story_2_9_B20_dialog_content = "Pareces un poco fatigado. ¿Qué planeas hacer a continuación? ¿Descansar?",
  ui_story_2_9_B21_dialog_content = "¿O irás con tus otros amigos?",
  ui_story_2_9_B22_dialog_content = "¿Amigos...? No sé si mi gente...",
  ui_story_2_9_B23_dialog_content = "Me refiero a los Aurorians. ¿No son tus amigos?",
  ui_story_2_9_B24_dialog_content = "Ah... Sí, me han ayudado mucho...",
  ui_story_2_9_B25_dialog_content = "Puede que necesite algo de tiempo para organizar mis pensamientos. Hoy fue demasiado para mí...",
  ui_story_2_9_B26_dialog_content = "Ok. Entonces quédate aquí, todavía tengo algunos informes diarios que completar, así que debo despedirme por ahora.",
  ui_story_2_9_B27_dialog_content = "¿Por qué tan serio de repente...?",
  ui_story_2_9_B28_dialog_content = "¡Hasta el poeta más romántico tiene trabajo que hacer!",
  ui_story_2_9_B30_dialog_content = "Y por favor, no te culpes demasiado por todo lo que ha sucedido.",
  ui_story_2_9_B31_dialog_content = "Esos soldados de Illumina murieron cumpliendo con su deber, no solo por tu bien.",
  ui_story_2_9_27_dialog_content = "Espero que eso te tranquilice.",
  ui_story_2_9_28_dialog_content = "...",
  ui_story_2_9_29_dialog_content = "¿Celes... tita? ¿Está bien si te llamo así? El salón está acá.",
  ui_story_2_9_30_dialog_content = "Ven conmigo. Aunque es primera vez que nos conocemos, cualquiera que Charon traiga aquí es de fiar.",
  ui_story_2_9_32_dialog_content = "Bienvenido a Subciudad 28.",
  ui_story_2_9_33_dialog_content = "Subciudad 28 a Gannon. Este es Charon con una situación importante que informar.",
  ui_story_2_9_34_dialog_content = "Copiado. Soy <color=#FFB400>Hiiro</color> en Gannon.",
  ui_story_2_9_35_dialog_content = "Contraseña.",
  ui_story_2_9_36_dialog_content = "<color=#FFB400>\"Trainman es súper guapo\".</color>",
  ui_story_2_9_37_dialog_content = "Estás de servicio hoy, Hiiro.",
  ui_story_2_9_38_dialog_content = "Respuesta.",
  ui_story_2_9_39_dialog_content = "<color=#FFB400>\"Flor de cerezo\"</color>...",
  ui_story_2_9_41_dialog_content = "¿Cómo está el progreso de Vice con la misión?",
  ui_story_2_9_42_dialog_content = "Eso es exactamente de lo que te iba a hablar.",
  ui_story_2_9_43_dialog_content = "El Colossus fue encontrado y devuelto a Subciudad 28.",
  ui_story_2_9_44_dialog_content = "Vice resultó herida y está recibiendo tratamiento.",
  ui_story_2_9_45_dialog_content = "¿Herida? ¿Es serio?",
  ui_story_2_9_46_dialog_content = "Ella está bien.",
  ui_story_2_9_47_dialog_content = "Como su superior interina, Charon, debes asumir la responsabilidad de esto.",
  ui_story_2_9_48_dialog_content = "Dime lo que sucedió.",
  ui_story_2_9_49_dialog_content = "Vice adivinó correctamente.",
  ui_story_2_9_50_dialog_content = "El Colossus que dejó Eraveil hace 17 años se estrelló cerca de Subciudad 28.",
  ui_story_2_9_51_dialog_content = "Ella y su equipo se encontraron con numerosos Eclipsites que parecían estar rastreando al Colossus.",
  ui_story_2_9_52_dialog_content = "¿Vice no solicitó refuerzos después de que descubrió el Colossus?",
  ui_story_2_9_F3_dialog_content = "Vi la señal de socorro, pero...",
  ui_story_2_9_53_dialog_content = "¿Fue muy tarde?",
  ui_story_2_9_54_dialog_content = "Por favor déjame terminar, Hiiro. Es más complicado de lo que crees.",
  ui_story_2_9_55_dialog_content = "El Colossus fue enterrado bajo tierra, pero nunca adivinarás que un Celestita también vivía en su interior.",
  ui_story_2_9_57_dialog_content = "¿Un Celestita?",
  ui_story_2_9_58_dialog_content = "¿Quieres decir que los Celestitas vivieron bajo tierra durante 17 años?",
  ui_story_2_9_60_dialog_content = "¿Y entonces?",
  ui_story_2_9_61_dialog_content = "Vice solicitó ayuda enviando señales de socorro del Colossus.",
  ui_story_2_9_62_dialog_content = "Partí tan pronto como pude y encontré huellas dejadas por hordas de Eclipsites.",
  ui_story_2_9_63_dialog_content = "Más tarde, me enteré por los Celestitas que lucharon contra Kraken, Nozard y Umbrahulk.",
  ui_story_2_9_64_dialog_content = "¿Tres Eclipsites de alto nivel?",
  ui_story_2_9_65_dialog_content = "¿Penetraron nuestras defensas e incluso se infiltraron en territorios cerca de Subciudad 28?",
  ui_story_2_9_66_dialog_content = "Ningún Eclipsite es capaz de atravesar nuestras defensas, con la excepción de Kraken.",
  ui_story_2_9_67_dialog_content = "Además de eso, también había una gran cantidad de Eclipsites ordinarios siguiendo su ejemplo.",
  ui_story_2_9_68_dialog_content = "No dejaron rastro del camino que tomaron para llegar allí, como si se hubieran caído del cielo, como sucedió hace 17 años en Eraveil.",
  ui_story_2_9_69_dialog_content = "¿Estás diciendo que los Eclipsites de alguna manera lograron pasar nuestras defensas?",
  ui_story_2_9_70_dialog_content = "Me temo que sí...",
  ui_story_2_9_71_dialog_content = "Además, el hecho de que Nozard siga vivo es un problema.",
  ui_story_2_9_72_dialog_content = "De acuerdo, le avisaré al Gran Mariscal de inmediato.",
  ui_story_2_9_73_dialog_content = "Todos ustedes también estén en guardia.",
  ui_story_2_9_74_dialog_content = "Subciudad 28 es una importante línea de suministro para la línea del frente. Si los suministros allí...",
  ui_story_2_9_75_dialog_content = "Hiiro, lo tengo.",
  ui_story_2_9_76_dialog_content = "<color=#e8d9bb>Unos días después - Patio de Reparación de Colossus</color>",
  ui_story_2_9_77_dialog_content = "Ahí tienes.",
  ui_story_2_9_78_dialog_content = "¿Vice? ¡¿Estás bien para moverte ya?!",
  ui_story_2_9_79_dialog_content = "Sí, ¿no es asombrosa la tecnología médica de Illumina?",
  ui_story_2_9_80_dialog_content = "¿Cómo está Soroz?",
  ui_story_2_9_81_dialog_content = "Todo está arreglado. La tecnología de Illumina es realmente asombrosa. Todas las unidades dañadas se han reparado en cuestión de días.",
  ui_story_2_9_82_dialog_content = "Los trabajadores están ahora en el proceso de aplicar los toques finales, que es un poco excesivo si me preguntas.",
  ui_story_2_9_83_dialog_content = "Sería bueno si pudieran quitar esa conspicua insignia de Illumina...",
  ui_story_2_9_84_dialog_content = "No esperaba este nivel de habilidad y conocimiento de Illumina... Agradece a Vice de mi parte.",
  ui_story_2_9_87_dialog_content = "Por supuesto, la división de ingeniería de Illumina siempre se esfuerza por alcanzar la excelencia.",
  ui_story_2_9_88_dialog_content = "Mira mi uniforme y mis armas. Todo esto es obra de la división de ingeniería. Son fundamentales para nuestras batallas.",
  ui_story_2_9_89_dialog_content = "Esta es una configuración Lumina diseñada que regula y alimenta los poderes de los Aurorians.",
  ui_story_2_9_90_dialog_content = "Esta tecnología es superior en términos de eficiencia y velocidad de activación.",
  ui_story_2_9_91_dialog_content = "Aunque es mucho menos potente que las prácticas tradicionales, la tecnología de ingeniería es adecuada para Illumina porque luchamos en grupos.",
  ui_story_2_9_A1_dialog_content = "...",
  ui_story_2_9_A2_dialog_content = "...",
  ui_story_2_9_A3_dialog_content = "Oh, ¿hay algo que no hayas entendido?",
  ui_story_2_9_A4_dialog_content = "... Sí, no pude entender casi nada.",
  ui_story_2_9_A5_dialog_content = "¿Todo? Oh, lo siento, olvidé que todavía eres nuevo en esto...",
  ui_story_2_9_A6_dialog_content = "Bien... Cambiando el tema...",
  ui_story_2_9_A7_dialog_content = "Vice, cuando nos estrellamos...",
  ui_story_2_9_98_dialog_content = "Creo que dije algo... bueno...",
  ui_story_2_9_99_dialog_content = "En breve... ¡Lo siento!",
  ui_story_2_9_100_dialog_content = "¿Ah? ¿Por qué la disculpa repentina?",
  ui_story_2_9_101_dialog_content = "Fui egoísta por decir todo eso en ese entonces, y te lastimaste por mi culpa. He tenido pesadillas los últimos días...",
  ui_story_2_9_102_dialog_content = "Oh, estabas hablando de eso. ¡No hay necesidad de disculparse en absoluto!",
  ui_story_2_9_103_dialog_content = "No entendía lo cerca que tú y Soroz eran en ese momento. Fue de mala educación por mi parte decir lo que hice.",
  ui_story_2_9_104_dialog_content = "Me preocupaba que te quedaras atrás y te enfrentas a los Eclipsites solo.",
  ui_story_2_9_105_dialog_content = "¡Pero salimos vivos y eso es todo lo que importa!",
  ui_story_2_9_107_dialog_content = "Espero trabajar contigo, PlayerName.",
  ui_story_2_9_108_dialog_content = "¡Sí!",
  ui_story_2_9_109_dialog_content = "<color=#e8d9bb>Estruendo...</color>",
  ui_story_2_9_110_dialog_content = "<color=#e8d9bb>Los temblores se intensifican, al parecer justo bajo nuestros pies.</color>",
  ui_story_2_9X_1_dialog_content = "<color=#e8d9bb>Se produce un temblor sutil.</color>",
  ui_story_2_9X_2_dialog_content = "<color=#e8d9bb>Los temblores se intensifican, al parecer justo bajo nuestros pies.</color>",
  ui_story_2_9X_3_dialog_content = "Algo está mal...",
  ui_story_2_9X_4_dialog_content = "¿Qué es ese temblor? ¿Es Soroz?",
  ui_story_2_9X_5_dialog_content = "No lo creo. Déjame establecer un vínculo mental.",
  ui_story_2_9X_6_dialog_content = "<color=#e8d9bb>¡Biiip—Biiip—BIIIIII!</color>",
  ui_story_2_9X_7_dialog_content = "Esta alarma... ¿Una brecha en el sistema de defensa? ¡Cómo es eso posible! El sistema funcionaba correctamente, ¿dónde exactamente...?",
  ui_story_2_9X_8_dialog_content = "¡Vice! Defensa... quebrada... ¡¡Estamos bajo ataque!! Tú...",
  ui_story_2_9X_9_dialog_content = "¿Qué estás diciendo? ¡No puedo oírte, Oficial Charon!",
  ui_story_2_9X_19_dialog_content = "¡Vice! ¡Estoy sintiendo Eclipsites!",
  ui_story_2_9X_20_dialog_content = "¿Eclipsites? ¿En Subciudad? ¿Cómo es eso posible?",
  ui_story_2_9X_21_dialog_content = "Tres... diez... No puedo seguir el ritmo. Vice, ¡los Eclipsites están creciendo en número!",
  ui_story_2_9X_22_dialog_content = "¡Definitivamente hay más en esos temblores de lo que pensamos! Tal vez Subciudad ya esté...",
  ui_story_2_9X_23_dialog_content = "¡Entonces vayamos a la fuente! Si esto es una invasión, ¡debemos detenerlos antes de que lleguen a las áreas residenciales!",
  ui_story_2_9X_24_dialog_content = "¡Prepárate para la batalla, PlayerName!",
  ui_story_2_9X_25_dialog_content = "¡Lo tienes!",
  ui_story_2_9X_26_dialog_content = "Ve... Mata... Haz trizas todo lo que tengas a la vista...",
  ui_story_2_9X_27_dialog_content = "No volveré a fallar. ¡Esta humillación solo puede eliminarse con la sangre y los huesos de los Aurorians!",
  ui_story_2_9X_28_dialog_content = "<size=45>¡Masacra esta Subciudad!</size>",
  ui_story_2_10_19_dialog_content = "¡Vice! ¡PlayerName!",
  ui_story_2_10_20_dialog_content = "¿Está bien, oficial Charon?",
  ui_story_2_10_21_dialog_content = "¿¿Vice??",
  ui_story_2_10_22_dialog_content = "<color=#FFB400>La defensa de Subciudad ha sido quebrada</color>... ¡Ha sucedido lo impensable! ¡Rompieron las barreras!",
  ui_story_2_10_23_dialog_content = "¿Cómo pudieron lanzar un ataque tan organizado contra los puntos débiles de Subciudad?",
  ui_story_2_10_24_dialog_content = "No puede ser. Algo está mal. Nunca antes había sucedido nada como esto en todos estos años.",
  ui_story_2_10_25_dialog_content = "Entonces, ¿cómo respondemos ahora? ¿Cuántos de nosotros todavía podemos luchar? ¡Reúne a todos en el área traspasada!",
  ui_story_2_10_26_dialog_content = "Ejecuta el plan de evacuación. Muchos Eclipsites ya han entrado en masa. Según el Código de Illumina, ya es una amenaza de Clase S.\nDebemos evacuar la ciudad.",
  ui_story_2_10_27_dialog_content = "Lo siento. No lo vi venir...",
  ui_story_2_10_28_dialog_content = "Vamos, Vice. ¡Evacuemos a los heridos y a los civiles juntos!",
  ui_story_2_10_29_option_content = "¿Ya no hay esperanza?",
  ui_story_2_10_30_option_content = "¿Realmente no hay posibilidad de contraatacar...?",
  ui_story_2_10_31_dialog_content = "¡Mira a tu alrededor! Subciudad 28 no es el frente de batalla. ¡Está lleno de soldados heridos y oficiales de logística!",
  ui_story_2_10_32_dialog_content = "¡Lo mejor que podemos hacer es guardar nuestras fuerzas y refugiarnos en otra Subciudad!",
  ui_story_2_10_33_dialog_content = "¿Cómo estamos ahora?",
  ui_story_2_10_34_dialog_content = "Las Eclipsites están en todas partes, con posibilidad de Eclipsites de alto nivel. En cualquier caso, ¡no podemos quedarnos aquí!",
  ui_story_2_10_A1_dialog_content = "Es Nozard...",
  ui_story_2_10_35_dialog_content = "No pasará mucho tiempo antes de que Subciudad esté plagada de Eclipsites.",
  ui_story_2_10_36_dialog_content = "¡Entendido! PlayerName, necesitamos tu orientación. ¡Evacuemos a todos juntos!",
  ui_story_2_10_40_dialog_content = "¡Entendido, no dejes a nadie atrás!",
  ui_story_2_10_41_dialog_content = "¡Sí, no abandonaré a nadie de mi gente! ¡Debemos evacuar a todos de manera segura!",
  ui_story_2_10_42_dialog_content = "¡Vamos, antes de que sea demasiado tarde!",
  ui_story_2_10_43_dialog_content = "¡Eso es! ¡No le des a los Aurorians la oportunidad de recuperar el aliento! Una vez que descubras dónde está el Colossus y el Celestita...",
  ui_story_2_10_44_dialog_content = "<size=45>¡Avísame de inmediato!</size>",
  ui_story_2_12_3_dialog_content = "¡Criaturas sucias y repugnantes deberían quedarse en las sombras!",
  ui_story_2_12_4_dialog_content = "¿Por qué tuvieron que venir y destruir esta hermosa Subciudad? ¡¡Simplemente no tiene ningún sentido!!",
  ui_story_2_12_5_dialog_content = "¡Wooga!",
  ui_story_2_12_6_dialog_content = "¡No entiendo!",
  ui_story_2_12_7_dialog_content = "¡A este ritmo, los Eclipsites llegarán a la zona residencial antes que nosotros!",
  ui_story_2_12_8_dialog_content = "¿Dónde está tu tren, Charon? ¿No podemos aceptar eso?",
  ui_story_2_12_9_dialog_content = "No hay ferrocarriles aquí para que corra el Other End.",
  ui_story_2_12_10_dialog_content = "Si esa cosa es convocada, podemos olvidarnos de salvar vidas. Sería un milagro si nuestros cadáveres estuvieran intactos.",
  ui_story_2_12_11_dialog_content = "Tenemos que hacer algo... y rápido...",
  ui_story_2_12_12_dialog_content = "¿Son estos realmente los mismos Eclipsites que he visto antes? ¿Cómo es que están tan... organizados... con algún tipo de objetivo?",
  ui_story_2_12_13_dialog_content = "<color=#FFB400>Como si tuvieran algún tipo de objetivo...</color>",
  ui_story_2_12_14_dialog_content = "...",
  ui_story_2_12_15_dialog_content = "Ah, ¿entonces su objetivo es el Celestita? Qué aprieto...",
  ui_story_2_12_16_dialog_content = "<color=#e8d9bb>La Subciudad vuelve a temblar vigorosamente.</color>",
  ui_story_2_12_17_dialog_content = "Odio admitirlo, pero parece que nos han llevado al límite.",
  ui_story_2_12_18_dialog_content = "Todavía hay un rayo de esperanza. ¡Aún no hemos jugado nuestra carta de triunfo!",
  ui_story_2_12_19_dialog_content = "PlayerName, te refieres a...",
  ui_story_2_12_20_dialog_content = "¡<color=#FFB400>Soroz</color>!",
  ui_story_2_12_24_dialog_content = "¡Cómo hice antes con PlayerName!",
  ui_story_2_12_25_dialog_content = "El Colossus todavía se está cargando y parece que va a llevar un tiempo.",
  ui_story_2_12_26_dialog_content = "Todavía tenemos que intentarlo, ¿no? Puede sacar a todos de aquí de todos modos...",
  ui_story_2_12_X26_dialog_content = "Vamos entonces. No tenemos de otra que dejar nuestro destino a Soroz ahora.",
  ui_story_2_12_27_dialog_content = "La gente siempre me confía misiones en momentos críticos y difíciles. Me he acostumbrado. Aún así, es mejor acelerar las cosas.",
  ui_story_2_12_X27_dialog_content = "Puedo sentir que los Eclipsites se acercan ya...",
  ui_story_2_12_28_dialog_content = "No tenemos elección. Haré los arreglos para que todos aborden el Colossus.",
  ui_story_2_12_29_dialog_content = "¡E iniciaremos el Colossus primero!",
  ui_story_2_13_1_dialog_content = "<color=#e8d9bb>En el puerto subterráneo, donde está el Colossus, Soroz, es</color>",
  ui_story_2_13_2_dialog_content = "Su número ha aumentado...",
  ui_story_2_13_3_dialog_content = "Distorsionar, distorsionar...",
  ui_story_2_13_4_dialog_content = "¡Lo sabía! ¡Los Eclipsites también han comenzado a reunirse alrededor del Colossus!",
  ui_story_2_13_5_dialog_content = "Mmm...",
  ui_story_2_13_6_dialog_content = "¿Está... enviando una señal...? ¿Podría estar comunicándose con Eclipsites distantes...?",
  ui_story_2_13_7_dialog_content = "¡Cómo sea! Todos, entren al Colossus ahora. ¡Qué vayan los heridos y niños primero! ¡Te cubriremos desde aquí!",
  ui_story_2_13_8_dialog_content = "Parece que no usaré el tren después de todo... Pensé que hoy íbamos a tener una hermosa llamada a escena.",
  ui_story_2_13_9_dialog_content = "Entonces supongo que me divertiré un poco con esto.",
  ui_story_2_13_10_dialog_content = "¿Qué estás haciendo con un... control remoto?",
  ui_story_2_13_11_dialog_content = "... ¿<color=#FFB400>Llave roja</color>? Cuando lo...",
  ui_story_2_13_12_dialog_content = "Es un procedimiento estándar para evacuación de clase S. Todo rastros de nuestra existencia debe ser borrado. Los fuegos artificiales serán gloriosos.",
  ui_story_2_13_13_dialog_content = "En realidad, es bastante difícil alejarse de la Subciudad... Después de todo, he vivido aquí durante tantos años.",
  ui_story_2_13_14_dialog_content = "\"El Supervisor de la Subciudad 28\" no ha logrado proteger la ciudad. ¡Qué fiasco!",
  ui_story_2_13_15_dialog_content = "Lo siento...",
  ui_story_2_13_16_dialog_content = "¿Por qué? ¿Dejaste entrar intencionalmente a los Eclipsites?",
  ui_story_2_13_17_dialog_content = "¡Claro que no!",
  ui_story_2_13_18_dialog_content = "Cálmate, teniente... Sólo bromeaba.",
  ui_story_2_13_19_dialog_content = "El tiempo de la Subciudad 28 se acabó. No hay nadie a quien culpar.",
  ui_story_2_13_20_dialog_content = "Tal vez... hay un final para todo, y así son las cosas...",
  ui_story_2_13_21_dialog_content = "Hasta los días eternos y noches eternas al final terminarán... ¿No suena poético?",
  ui_story_2_13_22_dialog_content = "¿Qué estas esperando? ¡Ve! Una vez que presione la llave roja, está fuera de mis manos quién explota.",
  ui_story_2_13_23_dialog_content = "¡Teniente, otra oleada de Eclipsites! Todavía tenemos heridos por detrás...",
  ui_story_2_13_24_dialog_content = "¡Entendido! Los detendremos. ¡El resto, aceleren el ritmo!",
  ui_story_2_13_25_dialog_content = "Parece que aún no es el momento de la llamada a escena. Guardaré la Llave Roja por ahora...",
  ui_story_2_14_1_dialog_content = "Estoy dentro... ¡al fin! ¿Alguien herido?",
  ui_story_2_14_2_dialog_content = "¡Estamos haciendo recuento! Creo que tenemos a todos. ¿Dónde está el Oficial Charon?",
  ui_story_2_14_3_dialog_content = "¿Oficial Charon? Estaba cubriendo la puerta del Colossus desde otra parte.",
  ui_story_2_14_4_dialog_content = "¡Perdón por la espera, teniente! No queda nadie más, ¿verdad? ¡¡Los Eclipsites prácticamente han cubierto cada centímetro de este lugar!!",
  ui_story_2_14_5_dialog_content = "¡Gracias por todo! Te he traído tantos problemas...",
  ui_story_2_14_6_dialog_content = "¡Por favor, no digas eso, teniente! Primero saquemos a todos. ¡Vamos!",
  ui_story_2_14_7_dialog_content = "Espera, ¡nos falta alguien! ¿Dónde está el Oficial Charon?",
  ui_story_2_14_8_dialog_content = "Lo vi cubriendo a algunos de los heridos que se quedaron atrás. Parecía...",
  ui_story_2_14_9_dialog_content = "¡Lo vi! ¡Por ahí!",
  ui_story_2_14_10_dialog_content = "Maldita sea, arruinaron mi atuendo...",
  ui_story_2_14_11_dialog_content = "¡Sigue luchando solo, y todos los Eclipsites de la Subciudad se han reunido aquí!",
  ui_story_2_14_12_dialog_content = "¡Está claro que soy su objetivo por la forma en que se mueven los Eclipsites!",
  ui_story_2_14_13_dialog_content = "¡Vamos arriba!",
  ui_story_2_14_14_dialog_content = "¡Ojalá pudiera! ¡Pero estas cosas son demasiado exasperantes!",
  ui_story_2_14_15_dialog_content = "¡Lo mínimo que puedo hacer es asegurarme de que no se acerquen a ti!",
  ui_story_2_14_16_dialog_content = "No, tengo que respaldarlo... ¡PlayerName, ven conmigo! ¡El resto de ustedes se quedan donde están!",
  ui_story_2_14_17_dialog_content = "¡¿Wooga?!",
  ui_story_2_14_18_dialog_content = "¡Hay demasiados de ellos! ¡Ni siquiera puedo seguir adelante!",
  ui_story_2_14_19_dialog_content = "¡Todos moriremos aquí si no vamos ahora! ¡No es momento de dudar!",
  ui_story_2_14_20_option_content = "Vice, debemos irnos ahora.",
  ui_story_2_14_21_dialog_content = "¡De ninguna manera! ¡Acordamos no dejar a nadie atrás!",
  ui_story_2_14_22_dialog_content = "Vice, PlayerName tiene razón. ¡Tenemos que irnos lo antes posible!",
  ui_story_2_14_23_dialog_content = "¡Charon te salvó antes! De hecho, ¡ha hecho algo por todos nosotros! ¡No podemos sólo dejarlo atrás!",
  ui_story_2_14_24_dialog_content = "¡Pero tampoco podemos arriesgar la vida de todos aquí!",
  ui_story_2_14_25_dialog_content = "Lo sé, por supuesto que sí... ¡¿Por qué llegó a esto?!",
  ui_story_2_14_26_option_content = "No. Debemos salvar a Charon.",
  ui_story_2_14_27_dialog_content = "¿Lo has pensado bien, PlayerName?",
  ui_story_2_14_28_dialog_content = "¡Todos los residentes de la Subciudad están aquí! Conoces el costo del fracaso, ¿verdad?",
  ui_story_2_14_29_dialog_content = "¡Creo que podemos hacerlo!",
  ui_story_2_14_31_dialog_content = "Quizás tu imprudente confianza aún pueda hacer maravillas.",
  ui_story_2_14_32_dialog_content = "Eso es lo que te distingue de los demás, PlayerName...",
  ui_story_2_15_1_dialog_content = "¡Oficial Charon!",
  ui_story_2_15_X1_dialog_content = "¡Gaah!",
  ui_story_2_15_F1_dialog_content = "¡Maldita sea, no puedo acercarme!",
  ui_story_2_15_X2_dialog_content = "¡Vice! ¡No hagas nada estúpido!",
  ui_story_2_15_X3_dialog_content = "¡Asquerosa escoria! ¡Te mostrare!",
  ui_story_2_15_X4_dialog_content = "<color=#e8d9bb>¡Whoosh!</color>",
  ui_story_2_15_A1_dialog_content = "¿Qué estás haciendo, Charon? ¡Las señales solo atraerán más Eclipsites!",
  ui_story_2_15_X6_dialog_content = "Teniente, ¿qué está esperando? ¡Qué infantil de tu parte! ¡Deja de hacerte cargo de esto! ¡Me estás causando aún más problemas!",
  ui_story_2_15_2_dialog_content = "¡Yo, Charon, el Barquero de Acheron, el epítome del esplendor y la belleza, no toleraré ninguna interferencia en la gloriosa misión!",
  ui_story_2_15_3_dialog_content = "¿Estás haciendo esto... a propósito?",
  ui_story_2_15_4_dialog_content = "¡Ponte en marcha, PlayerName! ¡No dejes que mi magnificencia te distraiga!",
  ui_story_2_15_5_dialog_content = "¡Este no es el momento de actuar, Oficial Charon! Nunca abordaremos si no lo haces...",
  ui_story_2_15_A2_dialog_content = "¡Seguro! ¡Enemigos como estos nunca podrán vencerme! ¡Lo sabes, Vice!",
  ui_story_2_15_A3_dialog_content = "¡Solo estarás en el camino, conseguirás que me maten a mí, el Barquero de Acheron, Charon el Carnicero Eclipsite!",
  ui_story_2_15_A4_dialog_content = "Charon...",
  ui_story_2_15_A5_dialog_content = "Sube a todos a bordo ahora, teniente. ¡Es una orden! Me pondré al día más tarde.",
  ui_story_2_15_A6_dialog_content = "... Sí, señor. Prepárate para el despegue, PlayerName...",
  ui_story_2_15_A7_dialog_content = "Despegando...",
  ui_story_2_15_A8_dialog_content = "Soroz, no cierres la puerta de embarque. ¡Charon podría estar aquí en cualquier momento!",
  ui_story_2_15_A9_dialog_content = "¿Estás seguro, PlayerName?",
  ui_story_2_15_A10_dialog_content = "... ¿Qué quieres decir?",
  ui_story_2_15_A11_dialog_content = "No... No parece que Charon esté tratando de ponerse al día.",
  ui_story_2_15_A12_dialog_content = "Todo lo contrario. Se adentra más en la horda Eclipsite.",
  ui_story_2_15_A13_dialog_content = "¡¿Qué?! Él...",
  ui_story_2_15_6_dialog_content = "¿Para qué es esa alarma?",
  ui_story_2_15_7_dialog_content = "¡Teniente! Esa es la secuencia de autodestrucción. ¡Charon presionó la llave roja!",
  ui_story_2_15_8_dialog_content = "¡No necesito que me digas eso!",
  ui_story_2_15_A14_dialog_content = "Charon... ¿Es eso lo que tenías en mente todo el tiempo...?",
  ui_story_2_15_9_dialog_content = "¡Estamos listos para el despegue! Recordaré a ese Aurorian. ¡Mantente quieto!",
  ui_story_2_15_10_option_content = "¡Nos vamos!",
  ui_story_2_15_13_dialog_content = "¡El casco está agrietado! Hay algo en el gran ala blanca, <color=#FFB400>y es demasiado pesado...</color>",
  ui_story_2_15_14_dialog_content = "...",
  ui_story_2_15_15_option_content = "¿Estás bien?",
  ui_story_2_15_17_dialog_content = "Mejor agárrate fuerte, PlayerName, ¡todavía no estamos a salvo!",
  ui_story_2_15_18_dialog_content = "Charon ya ha presionado la llave roja. Tenemos que elevarlo a una altura segura antes de que la Subciudad... explote.",
  ui_story_2_15_19_option_content = "Lo siento...",
  ui_story_2_15_20_option_content = "Acerca de Charon...",
  ui_story_2_15_21_dialog_content = "Prometí... que nunca dejaría a nadie atrás... Yo prometí...",
  ui_story_2_15_F2_dialog_content = "No es tu culpa, PlayerName. Es mía.",
  ui_story_2_15_22_dialog_content = "Si me hubiera esforzado un poco más, incluso si solo hubiera tomado una ruta diferente, tal vez los Eclipsites no lo hubieran separado de nosotros.",
  ui_story_2_15_23_dialog_content = "No, no deberíamos habernos separado y haberlo hecho cubrir a todos en primer lugar...",
  ui_story_2_15_24_dialog_content = "Qué momento conmovedor, y casi me lo pierdo.",
  ui_story_2_15_25_dialog_content = "Qué resiliente, al menos más de lo que esperaba.",
  ui_story_2_15_26_dialog_content = "¡¿Tú...?!",
  ui_story_2_15_27_dialog_content = "Ríndete. ¡No tiene sentido resistirse! No volveré a caer en tus trucos...",
  ui_story_2_15_28_option_content = "¿Por qué vienes detrás de mí?",
  ui_story_2_15_29_dialog_content = "Necesito ver la el final de mi misión.",
  ui_story_2_15_30_dialog_content = "¿Cuál es mi misión? Quizás destruya a todos los infieles.",
  ui_story_2_15_31_option_content = "¿Exactamente qué estás tratando de lograr?",
  ui_story_2_15_32_dialog_content = "Todo se hizo por el bien de nuestra misión.",
  ui_story_2_15_33_dialog_content = "Nuestra fuerza proviene de nuestra fe.",
  ui_story_2_15_34_dialog_content = "Nuestra fe viene de nuestra Madre.",
  ui_story_2_15_35_dialog_content = "Ustedes, Celestitas y Aurorians, son sanguijuelas que se nutren de esta tierra. Deberían estar agradecidos incluso de ser aniquilados por nosotros.",
  ui_story_2_15_36_dialog_content = "Luchar aún más es inútil. Solo retrasará lo inevitable, como lo que le pasó a ese soldado tonto.",
  ui_story_2_15_37_dialog_content = "Aurorians, regresen al suelo para que puedan disfrutar de una muerte rápida.",
  ui_story_2_15_38_dialog_content = "¡Nunca me rendiré! ¡Ya no permitiré que lastimes a mis amigos!",
  ui_story_2_15_39_dialog_content = "¿Buscando una muerte honorable en la batalla? Está bien.",
  ui_story_2_15_40_dialog_content = "Entonces te concederé una muerte digna de tu terquedad.",
  ui_story_2_15_41_dialog_content = "Te torturaré hasta la muerte de la forma más brutal posible.",
  ui_story_2_15_89_dialog_content = "Maestro... Fallé...",
  ui_story_2_15_91_dialog_content = "No va a terminar aquí... Te lo aseguro...",
  ui_story_2_15_X92_dialog_content = "¿Te gustaría escuchar mi confesión? Jaja... jajajajajaja...",
  ui_story_2_15_X93_dialog_content = "¡Disfruta brevemente de esta supuesta victoria tuya!",
  ui_story_2_15_X94_dialog_content = "El Maestro les dará su merecido cuando se enfrente a ustedes, a todos ustedes, incluyendo Aurorians y al cobarde Celestita.",
  ui_story_2_15_X95_dialog_content = "Para entonces, sus pobres gargantas ni siquiera podrán hacer el más leve gemido...",
  ui_story_2_15_92_dialog_content = "Schummer... Deja que este nombre resuene en tu cabeza.",
  ui_story_2_15_93_dialog_content = "Nunca podrás registrar lo tremendo de su poder.",
  ui_story_2_15_42_dialog_content = "Esta vez... Realmente se acabó.",
  ui_story_2_15_43_dialog_content = "<color=#e8d9bb>¡¡¡Boom!!!</color>",
  ui_story_2_15_44_dialog_content = "La Subciudad 28... explotó...",
  ui_story_2_15_45_dialog_content = "<color=#e8d9bb>Amaneció cuando estalló la explosión, aparentemente rindiendo homenaje a los muertos y al comienzo de un nuevo día...</color>",
  ui_story_2_15_46_dialog_content = "Despedida... La Subciudad 28 y Charon...",
  ui_story_2_15_47_dialog_content = "Lo siento mucho.",
  ui_story_2_15_48_dialog_content = "Esa fue su elección, PlayerName. No te culpes a ti mismo.",
  ui_story_2_15_49_dialog_content = "Por qué... ¿Por qué sacrificaste tu propia seguridad para protegernos? Por qué tuviste que poner cara de valiente hasta el último minuto...",
  ui_story_2_15_51_option_content = "Se convertirá en un ejemplo honorable para todos nosotros, ¿no es así?",
  ui_story_2_15_52_dialog_content = "¿De qué sirve si uno ya está muerto?",
  ui_story_2_15_B1_dialog_content = "¿\"Ejemplo\"? ¿Qué significa eso?",
  ui_story_2_15_B2_dialog_content = "Si entiendo correctamente, Charon estaba protegiendo lo que apreciaba.",
  ui_story_2_15_B3_dialog_content = "...",
  ui_story_2_15_B4_dialog_content = "Sus soldados, colegas, amigos... y la Subciudad.",
  ui_story_2_15_53_option_content = "Vivirá en todos nosotros.",
  ui_story_2_15_54_dialog_content = "¿Vivirá en todos nosotros? Probablemente sueno egoísta, pero esa no es forma de vivir, PlayerName.",
  ui_story_2_15_55_dialog_content = "Es solo otro tipo de dolor, sufrido por otros.",
  ui_story_2_15_B5_dialog_content = "Es como el dolor por el que has estado pasando. ¿Aceptarías un final como este?",
  ui_story_2_15_B6_dialog_content = "Pero solo puedo aceptarlo...",
  ui_story_2_15_B7_dialog_content = "Al menos murió para proteger aquellas cosas que apreciaba, soldados y seres queridos.",
  ui_story_2_15_B8_dialog_content = "No podemos defraudarlo, Vice.",
  ui_story_2_15_B9_dialog_content = "Sé lo que estás diciendo, PlayerName, pero mi mente es un desastre en este momento.",
  ui_story_2_15_B10_dialog_content = "Protección, dedicación... Como miembro de Illumina, por supuesto que valoro estas virtudes.",
  ui_story_2_15_B11_dialog_content = "Pero todavía no puedo afrontar ver a uno tras otro dejar mi lado.",
  ui_story_2_15_57_dialog_content = "Siempre estamos cantando, \"¡Esplendor Illumina!\" Pero, ¿podemos realmente ser Aurora y crear un futuro mejor?",
  ui_story_2_15_58_dialog_content = "Creo que, si un día...",
  ui_story_2_15_59_dialog_content = "Si un día nos vemos obligados a tomar una decisión similar...",
  ui_story_2_15_60_dialog_content = "Ni siquiera quiero imaginarlo.",
  ui_story_2_15_61_dialog_content = "Esperanza.",
  ui_story_2_15_62_dialog_content = "¿...?",
  ui_story_2_15_63_dialog_content = "Charon dijo una vez: \"Si no se puede evitar la desesperación, debemos superar los tiempos oscuros con esperanza.\"",
  ui_story_2_15_66_option_content = "Eso suena a él.",
  ui_story_2_15_F3_dialog_content = "Siempre recordaré su nombre, Charon el Barquero de Acheron.",
  ui_story_2_15_F4_dialog_content = "¿El barquero de Acheron...?",
  ui_story_2_15_F5_dialog_content = "¿Qué tal?",
  ui_story_2_15_70_dialog_content = "¿Por qué se llama Charon el Barquero de Acheron?",
  ui_story_2_15_71_dialog_content = "Eso es por su... tren extravagante. Lo has visto.",
  ui_story_2_15_72_dialog_content = "Como ex despachador de trenes, podía convocar al tren, Other End, en cualquier momento.",
  ui_story_2_15_73_dialog_content = "¡Ah!",
  ui_story_2_15_74_dialog_content = "¿Tren? Espera... ese destello de señal...",
  ui_story_2_15_79_dialog_content = "No me digas que él...",
  ui_story_2_15_80_dialog_content = "Teniente Vice, PlayerName, ¡miren ahí arriba!",
  ui_story_2_15_81_dialog_content = "<color=#FFB400>Eso sí es extravagante</color>...",
  ui_story_2_15_82_dialog_content = "<size=45>¡¡Ahí va la hermosa llamada a la cortina!!</size>",
  ui_story_2_15_A15_dialog_content = "Los fuegos artificiales, los aplausos y tus conmovedoras lágrimas. ¡Las tomo todas con mucho gusto!",
  ui_story_2_15_83_dialog_content = "<size=45>¡He aquí, Charon, el Barquero de Acheron, está aquí!</size>",
  ui_story_2_15_84_dialog_content = "¿Alguno de ustedes derramó lágrimas por mí, mi amada audiencia?",
  ui_story_2_15_F6_dialog_content = "Preguntémosle a un espectador afortunado. ¿Qué opinas, PlayerName?",
  ui_story_2_15_X85_dialog_content = "Uh, esa fue una... actuación deslumbrante...",
  ui_story_2_15_85_dialog_content = "Bien... hecho, oficial Charon...",
  ui_story_2_15_86_dialog_content = "No sé si debería estar feliz o enojado...",
  ui_story_2_15_87_option_content = "Eso es genial... Ugh...",
  ui_story_2_15_88_dialog_content = "¿PlayerName?",
  ui_story_2_15_X88_dialog_content = "Sintiéndome mareado... Está... volviendo de nuevo...",
  ui_story_2_15_95_dialog_content = "Esa visión familiar...",
  ui_story_2_15_96_dialog_content = "Vice...",
  ui_story_2_15_100_dialog_content = "¡PlayerName, estoy aquí! ¡Por favor, permanece despierto!",
  ui_story_2_15_101_dialog_content = "<color=#e8d9bb>Fuera de las ruinas de</color> <color=#FFB400>otro Colossus</color>",
  ui_story_2_15_102_dialog_content = "...",
  ui_story_2_15_103_dialog_content = "¿Estás bien, Maestro?",
  ui_story_2_15_104_dialog_content = "¿Por qué preguntas?",
  ui_story_2_15_105_dialog_content = "Estabas distraído. No deberías estar tan distraído ya que has esperado tanto tiempo esta oportunidad...",
  ui_story_2_15_106_dialog_content = "No me pongas a prueba preguntándome cosas que no deberías, Eclipsite. Sólo estaba... Quizás sea solo una ilusión.",
  ui_story_2_15_107_dialog_content = "Entonces te deseo una buena cacería. Espero que encuentres lo que has estado buscando.",
  ui_story_2_15_108_dialog_content = "¿Cacería? Hmm, me gusta cómo lo pones.",
  ui_story_2_15_109_dialog_content = "¿Puedes oír mi voz? Puedo sentir tu presencia...",
  ui_story_2_15_110_dialog_content = "Ya deberías darte cuenta de que también soy un <color=#FFB400>Celestita</color>. Pero me estoy quedando sin tiempo.",
  ui_story_2_15_111_dialog_content = "Aviduz, <color=#FFB400>esa mujer</color>... La siniestra oscuridad... El pecador que mató a los de su propia especie...",
  ui_story_2_15_112_dialog_content = "Ella me encontró ahora...",
  ui_story_2_15_113_dialog_content = "Mi Colossus y yo... se nos acabó el tiempo...",
  ui_story_3_1_1_dialog_content = "¿Puedes escucharme? No te conozco, pero sé que también eres Celestita.",
  ui_story_3_1_2_dialog_content = "Estoy seguro de que puedes oírme.",
  ui_story_3_1_3_dialog_content = "Se ha enviado una señal. Todos permanezcan quietos y no vayan a ningún lado.",
  ui_story_3_1_4_dialog_content = "¡Uh, Vice, este tipo PlayerName se está despertando!",
  ui_story_3_1_5_dialog_content = "Pero PlayerName todavía parece disfrutar de mi magnífica actuación.",
  ui_story_3_1_6_dialog_content = "Muchas gracias, Oficial Charon. ¡Ahora por favor ve a que te traten!",
  ui_story_3_1_7_dialog_content = "No, no, estoy bien. Es una pena que mi heroica hazaña no haya sido captada por la cámara...",
  ui_story_3_1_8_dialog_content = "Parece que tienes tus prioridades mezcladas...",
  ui_story_3_1_9_dialog_content = "Esencialmente, está claro que el poder de la Llave Roja es realmente asombroso. A decir verdad, siempre quise usarlo...",
  ui_story_3_1_10_dialog_content = "La Subciudad 28 ahora yace en escombros, Oficial Charon. ¿No te sientes... triste?",
  ui_story_3_1_11_dialog_content = "Es una lástima terrible, ¡pero ahórrate las lágrimas! Todavía tenemos <color=#FFB400>hogar</color>.",
  ui_story_3_1_12_dialog_content = "¿Hogar?",
  ui_story_3_1_13_dialog_content = "Seguro. Mira alrededor.",
  ui_story_3_1_14_dialog_content = "Los civiles, los soldados... Los activos más importantes de la Federación permanecen intactos.",
  ui_story_3_1_15_dialog_content = "El hogar es donde están sus seres queridos.",
  ui_story_3_1_F1_dialog_content = "Mmm...",
  ui_story_3_1_16_dialog_content = "Tú y el Celestita están bien, ¿verdad? Esta es la segunda vez que te salvo.",
  ui_story_3_1_F2_dialog_content = "Gracias Señor...",
  ui_story_3_1_17_dialog_content = "Debo ir a evaluar la situación. ¡Espera aquí pacientemente y no te vayas!",
  ui_story_3_1_18_dialog_content = "Está bien.",
  ui_story_3_1_19_dialog_content = "Charon... en realidad no es tan autoritario como parece.",
  ui_story_3_1_20_dialog_content = "¿Estás bien, PlayerName? Tú solo...",
  ui_story_3_1_B1_dialog_content = "Sí, estoy bien.",
  ui_story_3_1_B2_dialog_content = "No te ves bien, así que no te esfuerces.",
  ui_story_3_1_B3_dialog_content = "Gracias, Vice... por estar a mi lado todo este tiempo.",
  ui_story_3_1_B4_dialog_content = "¿Por qué no lo haría? ¡Somos un equipo!",
  ui_story_3_1_B5_dialog_content = "Vencimos a los Eclipsites de alto nivel, ¡gracias a ti!",
  ui_story_3_1_B6_dialog_content = "Este es solo el <color=#FFB400>comienzo</color>, Vice.",
  ui_story_3_1_B7_dialog_content = "¿Ah? ¿El comienzo?",
  ui_story_3_1_B8_dialog_content = "Antes de que Nozard muriera, volvió a mencionar ese nombre:<color=#FFB400>Schummer</color>.",
  ui_story_3_1_B9_dialog_content = "Schummer... ¿Quién es exactamente?",
  ui_story_3_1_B10_dialog_content = "No estoy seguro, pero creo que esta persona debe saber toda la verdad.",
  ui_story_3_1_B11_dialog_content = "Lo siento, Vice, pero debo encontrar a Schummer y saber la verdad.",
  ui_story_3_1_B12_dialog_content = "¿Por qué estás tan motivado de repente, PlayerName?",
  ui_story_3_1_B13_dialog_content = "Encontré mi \"<color=#FFB400>hogar</color>\" otra vez.",
  ui_story_3_1_B14_dialog_content = "Has estado hablando con Charon mientras me recuperaba...",
  ui_story_3_1_B15_dialog_content = "Lástima que no pudimos sacar más de Schummer de Nozard...",
  ui_story_3_1_B17_dialog_content = "Está bien. Quizás haya más archivos esperándonos en la sede de Illumina.",
  ui_story_3_1_B18_dialog_content = "¿Qué pasa, PlayerName?",
  ui_story_3_1_B21_dialog_content = "Ayuda...",
  ui_story_3_1_B22_dialog_content = "Rápido... ¿¡Puedes... escucharme!?",
  ui_story_3_1_B23_dialog_content = "¿Sentiste eso, PlayerName? ¿Qué fue eso ahora?",
  ui_story_3_1_B24_dialog_content = "Sí. ¿<color=#FFB400>Alguien parece estar pidiendo ayuda</color>?",
  ui_story_3_1_21_dialog_content = "Aviduz es... Estoy... fuera de tiempo...",
  ui_story_3_1_22_dialog_content = "Escuchaste algo, ¿no?",
  ui_story_3_1_23_option_content = "¡Solo podría ser la telepatía de un Celestita!",
  ui_story_3_1_24_dialog_content = "¿Un sobreviviente <color=#FFB400>como yo</color>? ¡¿Otro Celestita?!",
  ui_story_3_1_25_dialog_content = "Sí. Y por el mensaje, está en grave peligro.",
  ui_story_3_1_26_dialog_content = "Tal vez sea como nosotros...",
  ui_story_3_1_27_option_content = "Es la voz de un chico",
  ui_story_3_1_28_dialog_content = "Sí, su conciencia está llena de miedo, por lo que tiene que ser malo.",
  ui_story_3_1_F3_dialog_content = "Comunicación psíquica... ¡¿Es un Celestita?!",
  ui_story_3_1_29_dialog_content = "Sí, pero la señal de su Colossus era muy débil para poder localizarla.",
  ui_story_3_1_30_dialog_content = "Pide ayuda a gritos. Algo terrible le está sucediendo a él y a su Colossus.",
  ui_story_3_1_31_dialog_content = "¿<color=#FFB400>Otro Celestita</color>?",
  ui_story_3_1_32_dialog_content = "Espera, ¿dices que puedes hallar otros Colossus a través de él?",
  ui_story_3_1_33_dialog_content = "¿Puedes ayudarme, Vice?",
  ui_story_3_1_34_dialog_content = "...",
  ui_story_3_1_35_dialog_content = "¿Tienes algo que decirme, teniente?",
  ui_story_3_1_36_dialog_content = "Er, nosotros...",
  ui_story_3_1_37_dialog_content = "¡Recibimos una llamada de socorro de otro Celestita!",
  ui_story_3_1_38_dialog_content = "¡¿...?!",
  ui_story_3_1_39_dialog_content = "¿Dos Celestitas? ¿Qué está pasando últimamente?",
  ui_story_3_1_40_dialog_content = "¡Puedo confirmar que la comunicación psíquica fue exactamente como la mía!",
  ui_story_3_1_41_dialog_content = "¿Dónde está? ¿Está cerca?",
  ui_story_3_1_42_dialog_content = "No estoy seguro... Pero conozco la ubicación general. ¡Tenemos que irnos ahora!",
  ui_story_3_1_43_dialog_content = "...",
  ui_story_3_1_44_dialog_content = "Eso no servirá.",
  ui_story_3_1_45_dialog_content = "¡Señor!",
  ui_story_3_1_46_dialog_content = "Tanta desorganización... Tanta falta de disciplina... ¿¡No sabes cuántos problemas acabas de causar!?",
  ui_story_3_1_47_dialog_content = "Pero...",
  ui_story_3_1_48_dialog_content = "Todo el mundo está mirando, así que trata de no causar más pánico ahora.",
  ui_story_3_1_49_dialog_content = "Y tu superior inmediato Hiiro, la comandante de la 3ra Legión, ya casi está aquí.",
  ui_story_3_1_50_dialog_content = "¿No la vas a poner al corriente de la situación actual?",
  ui_story_3_1_51_dialog_content = "...",
  ui_story_3_1_52_dialog_content = "Pero no tenemos más tiempo que perder.",
  ui_story_3_1_53_dialog_content = "¿Quién sabe cuándo tendremos otra pista como esta?",
  ui_story_3_1_54_dialog_content = "¡Y parecía que realmente necesitaba ayuda! ¡Estoy seguro de que corre grave peligro!",
  ui_story_3_1_55_dialog_content = "Es uno de mi gente, Charon. ¡Un Celestita vivo y real!",
  ui_story_3_1_56_dialog_content = "...",
  ui_story_3_1_57_dialog_content = "Señor...",
  ui_story_3_1_58_dialog_content = "Entiendo lo importante que es esto para ti, PlayerName.",
  ui_story_3_1_59_dialog_content = "Pero la Federación Illumina también tiene su propio código de disciplina, especialmente cuando todavía estoy a cargo.",
  ui_story_3_1_60_dialog_content = "A menos que...",
  ui_story_3_1_61_dialog_content = "¡...!",
  ui_story_3_1_62_dialog_content = "A menos que nunca me informaran de su operación.",
  ui_story_3_1_63_dialog_content = "¿Ah?",
  ui_story_3_1_64_dialog_content = "Eres teniente, ¿no es así, Vice? Y no estás bajo mi mando directo.",
  ui_story_3_1_A1_dialog_content = "Por lo tanto, también tiene un cierto grado de discreción, siempre que no ponga en peligro a la Federación Illumina.",
  ui_story_3_1_A2_dialog_content = "Pero me gustaría enfatizar nuevamente que la Federación Illumina está mirando.",
  ui_story_3_1_A3_dialog_content = "Sé lo que debemos hacer, Vice.",
  ui_story_3_1_65_dialog_content = "¿Tienes una idea?",
  ui_story_3_1_B25_option_content = "Vamos a escabullirnos sin que nadie se dé cuenta",
  ui_story_3_1_B26_option_content = "Seamos creativos y demos un espectáculo",
  ui_story_3_1_66_dialog_content = "No digas eso frente a un oficial superior, PlayerName.",
  ui_story_3_1_67_dialog_content = "¿Ah? ¿De qué estaba hablando? No pude escucharte por encima del fuerte viento.",
  ui_story_3_1_68_dialog_content = "...",
  ui_story_3_1_B26_dialog_content = "Estás insinuando que deberíamos...",
  ui_story_3_1_B27_dialog_content = "¿Insinuando? ¡No estaba insinuando nada! ¿De qué estás hablando?",
  ui_story_3_1_B28_dialog_content = "Solo te recordaba tus opciones como teniente, Vice.",
  ui_story_3_1_B29_dialog_content = "Depende de ti decidir qué hacer.",
  ui_story_3_1_B30_dialog_content = "Entiendo, señor. Gracias.",
  ui_story_3_1_B31_dialog_content = "Hiiro estará aquí pronto. Si vas a hacer algo de lo que no soy consciente, es mejor que lo hagas ahora.",
  ui_story_3_1_B32_dialog_content = "De lo contrario, tendrás que quedarte e informarle cuando llegue.",
  ui_story_3_1_B33_dialog_content = "Charon... realmente está lleno de sorpresas.",
  ui_story_3_1_B34_dialog_content = "Wow... Estoy nervioso... Me pregunto cómo reaccionará la comandante Hiiro...",
  ui_story_3_1_B35_dialog_content = "¿Hará un show?",
  ui_story_3_1_B36_dialog_content = "¡Ejem!",
  ui_story_3_1_B37_dialog_content = "Charon, tengo algo que no estoy seguro de poder decir.",
  ui_story_3_1_B38_dialog_content = "¡Habla libremente, Celestita!",
  ui_story_3_1_B39_dialog_content = "¡Soroz me acaba de decir que un gran grupo de Eclipsites está siguiendo el rastro del Colossus y se dirige directamente hacia nosotros!",
  ui_story_3_1_B40_dialog_content = "¿Ah? ¿Ah?",
  ui_story_3_1_B41_dialog_content = "¿¡Qué!? ¿¡El aura del Colossus está atrayendo a más Eclipsites aquí!?",
  ui_story_3_1_B42_dialog_content = "¿¡Por qué no dijiste eso antes!? ¡Eso es extremadamente peligroso!",
  ui_story_3_1_B43_dialog_content = "¿¿¿???",
  ui_story_3_1_B44_dialog_content = "(¡Trabaja conmigo, Vice, solo hazlo!)",
  ui_story_3_1_B45_dialog_content = "Ah... ¡Oh! Lo siento, yo... me acabo de dar cuenta de que yo mismo...",
  ui_story_3_1_B46_dialog_content = "¡Increíble! Quiero decir, acabamos de salir del infierno, ¡y ahora estamos de vuelta en las fauces de la muerte otra vez!",
  ui_story_3_1_B47_dialog_content = "¡No puedo permitir que mi gente se enfrente a tal peligro!",
  ui_story_3_1_B48_dialog_content = "Ah, entonces... ¿¡Qué debemos hacer!?",
  ui_story_3_1_B49_dialog_content = "¡Navega al Colossus lejos de aquí! ¡Aléjalo de los civiles inocentes!",
  ui_story_3_1_B50_dialog_content = "¡Sí!",
  ui_story_3_1_B51_dialog_content = "(¡Ve rápido!)",
  ui_story_3_1_B52_dialog_content = "Gracias, Oficial Charon.",
  ui_story_3_1_B53_dialog_content = "... Hmph.",
  ui_story_3_1_B55_dialog_content = "Toda esa farsa de ahora... Era realmente necesario...",
  ui_story_3_1_B56_dialog_content = "No estoy seguro, pero parecía que Charon lo estaba disfrutando...",
  ui_story_3_1_B57_dialog_content = "Pero necesitábamos una razón para irnos, antes de que llegue su superior inmediato.",
  ui_story_3_1_B58_dialog_content = "Correcto... Hiiro...",
  ui_story_3_1_B59_dialog_content = "*Suspiros* Me estremezco al pensar en cómo va a reaccionar la Comandante Hiiro después de enterarse de que nos fuimos sin permiso.",
  ui_story_3_1_69_option_content = "¿Ya te arrepientes?",
  ui_story_3_1_70_dialog_content = "¡No!",
  ui_story_3_1_71_dialog_content = "Bueno, esperemos que Hiiro sea una superior comprensivo.",
  ui_story_3_1_72_dialog_content = "Bueno, ahora que dijiste eso, estoy empezando a arrepentirme un poco.",
  ui_story_3_1_73_option_content = "Espero que hayamos tomado la decisión correcta",
  ui_story_3_1_74_dialog_content = "Bien o no... probablemente no dependa de nosotros...",
  ui_story_3_1_76_dialog_content = "¡¡¡Oh no, la Comandante Hiiro me va a matar!!!",
  ui_story_3_1_77_dialog_content = "Destino: Sitio de lanzamiento de señales de Celestita desconocido. ¡Contando!",
  ui_story_3_1_78_dialog_content = "5, 4, 3, 2...",
  ui_story_3_1_79_dialog_content = "¡1! ¡Despegue!",
  ui_story_3_1_80_dialog_content = "Aquí está el informe del incidente que deseaba. Por favor echa un vistazo...",
  ui_story_3_1_81_dialog_content = "Déjame ver... Ajá, ajá. Debo hacerlo mejor aquí...",
  ui_story_3_1_82_dialog_content = "Elabora más sobre Vice y el Celestita, relaciona tu acción con lo que sucedió aquí.",
  ui_story_3_1_83_dialog_content = "¡Ah, sí señor!",
  ui_story_3_1_84_dialog_content = "Créeme, no te va a gustar cómo esa mujer te interroga por los detalles.",
  ui_story_3_1_85_dialog_content = "Esto es diferente de lo que esperaba, Charon.",
  ui_story_3_1_86_dialog_content = "...",
  ui_story_3_1_87_dialog_content = "Si te preguntas sobre la Subciudad 28, son las ruinas justo debajo de tus pies, Comandante de la Legión.",
  ui_story_3_1_88_dialog_content = "No reiteres cosas que ya sé, Charon. ¿Dónde se menciona el Colossus en su informe?",
  ui_story_3_1_89_dialog_content = "El pájaro se fue con estilo.",
  ui_story_3_1_90_dialog_content = "¿Dónde está mi subordinada?",
  ui_story_3_1_91_dialog_content = "Ella se ha ido. Ella está a bordo del Colossus.",
  ui_story_3_1_92_dialog_content = "Supervisor Charon de Subciudad 28, ¿estás diciendo que mi soldado desafió mi orden?",
  ui_story_3_1_93_dialog_content = "Solo digo que ella está con el Celestita.",
  ui_story_3_1_94_dialog_content = "Celestita...",
  ui_story_3_1_95_dialog_content = "Oficial, nosotros... ¡Perdón por interrumpir, Comandante de la Legión!",
  ui_story_3_1_96_dialog_content = "Adelante.",
  ui_story_3_1_97_dialog_content = "¡Sí! Terminamos de evaluar los daños y el estado civil. ¡Esperando su próxima orden!",
  ui_story_3_1_98_dialog_content = "Sigue el plan y evacúalos a la Subciudad más cercana. Haré que los batallones 1 y 3 los escolten.",
  ui_story_3_1_99_dialog_content = "Podemos proteger a los civiles nosotros mismos. No hay necesidad de molestarte...",
  ui_story_3_1_100_dialog_content = "El resto de ustedes, síganme.",
  ui_story_3_1_101_dialog_content = "...",
  ui_story_3_1_102_dialog_content = "Todavía gruñona como siempre, Hiiro.",
  ui_story_3_1_103_dialog_content = "¿Qué estás haciendo?",
  ui_story_3_1_104_dialog_content = "¿Yo?",
  ui_story_3_1_A4_dialog_content = "¿Qué es esto, utensilios de cocina?",
  ui_story_3_1_A5_dialog_content = "... Es un comunicador compacto de largo alcance.",
  ui_story_3_1_105_dialog_content = "¿Es un dispositivo Illumina? ¿Cómo es que nunca te he visto usarlo?",
  ui_story_3_1_106_dialog_content = "Charon me lo pasó a escondidas hace un tiempo.",
  ui_story_3_1_107_dialog_content = "Charon...",
  ui_story_3_1_108_dialog_content = "Bien, ¿cómo funciona esto...? ¡Hombre, esto es difícil!",
  ui_story_3_1_109_dialog_content = "Creo que lo cruzas aquí, lo vuelves a girar, luego ajustas la frecuencia...",
  ui_story_3_1_111_dialog_content = "¡Ajá, funciona!",
  ui_story_3_1_112_dialog_content = "Informe su ubicación actual.",
  ui_story_3_1_113_dialog_content = "¡Sí...! ¿Comandante Hiiro?",
  ui_story_3_1_114_dialog_content = "Veo que aún reconoce a su superior, teniente. ¿Por qué te fuiste sin permiso?",
  ui_story_3_1_115_dialog_content = "Mis disculpas. Subciudad 28 fue invadida por Eclipsites y se inició la secuencia de autodestrucción.",
  ui_story_3_1_116_dialog_content = "No repitas cosas que ya sé. Te pregunto por qué te fuiste con el Colossus sin autorización.",
  ui_story_3_1_117_dialog_content = "El Colossus... Yo...",
  ui_story_3_1_118_dialog_content = "Bueno, señora, el Colossus no le pertenece. Dejemos eso en claro.",
  ui_story_3_1_119_dialog_content = "Así que eres tú...",
  ui_story_3_1_120_dialog_content = "Sí, soy el dueño de este Colossus.",
  ui_story_3_1_122_dialog_content = "Gracias a ti y a tu precioso Colossus, Subciudad 28 ya no está.",
  ui_story_3_1_A6_dialog_content = "¿No crees que le debes una explicación a la Federación Illumina?",
  ui_story_3_1_123_dialog_content = "Lo siento mucho, ¡pero encontraré la manera de compensar a Illumina!",
  ui_story_3_1_124_dialog_content = "Nozard también mencionó a alguien con el nombre de <color=#FFB400>Schummer</color>.",
  ui_story_3_1_125_dialog_content = "Nozard, Schummer... No me interesan estos nombres raros.",
  ui_story_3_1_126_dialog_content = "Pero todo... y Subciudad 28, ¡probablemente todos tengan algo que ver con Schummer!",
  ui_story_3_1_127_dialog_content = "¿Oh?",
  ui_story_3_1_128_dialog_content = "¡Tenemos pistas sobre otro Celestita, señora, que puede apuntar a otro Colossus!",
  ui_story_3_1_129_dialog_content = "¿¡Qué dijiste!?",
  ui_story_3_1_130_dialog_content = "¡Pero ese Celestita y su Colossus están en un gran problema!",
  ui_story_3_1_131_dialog_content = "PlayerName quiere hacer algo para ayudar, así que pensé...",
  ui_story_3_1_132_dialog_content = "¡Creo que debería ayudarlo! ¡También es importante para Illumina!",
  ui_story_3_1_133_dialog_content = "Debo recordarle, teniente...",
  ui_story_3_1_A7_dialog_content = "Ahora eres un soldado de la Federación Illumina, ¡así que reconsidera!",
  ui_story_3_1_134_dialog_content = "Lo siento, señora. Intenté detener a PlayerName, ¡pero creo que PlayerName está en lo correcto esta vez!",
  ui_story_3_1_135_dialog_content = "¿Vice...?",
  ui_story_3_1_136_dialog_content = "PlayerName tiene razón... esta vez.",
  ui_story_3_1_137_dialog_content = "Rescataré al Celestita y llegaré al fondo de todo esto.",
  ui_story_3_1_A8_dialog_content = "...",
  ui_story_3_1_A9_dialog_content = "...",
  ui_story_3_1_138_dialog_content = "*Suspiros* ¿Qué tan seguro estás?",
  ui_story_3_1_139_dialog_content = "¡No dejaré que los Eclipsites se salgan con la suya de nuevo!",
  ui_story_3_1_140_dialog_content = "Envíame las coordenadas, ahora.",
  ui_story_3_1_141_dialog_content = "Tu señal es inestable. No podemos rastrear tu posición.",
  ui_story_3_1_142_dialog_content = "Y Vice, no olvides de qué lado estás y no hagas nada estúpido.",
  ui_story_3_1_144_dialog_content = "¡Perdimos la señal!",
  ui_story_3_1_145_dialog_content = "Siento una presencia fuerte y dominante que no se parece a nada que hayamos encontrado antes.",
  ui_story_3_1_146_dialog_content = "El Celestita mencionó <color=#FFB400>Aviduz</color> cuando pidió ayuda.",
  ui_story_3_1_A10_dialog_content = "¿Es esto?",
  ui_story_3_1_147_dialog_content = "No lo sé, PlayerName, pero es una fuerza poderosa, cambio...",
  ui_story_3_1_148_dialog_content = "¡Sí, por ahí!",
  ui_story_3_1_A11_dialog_content = "Soroz encontró la ubicación, Vice. Aviduz podría estar adentro.",
  ui_story_3_1_A12_dialog_content = "No tenemos suficiente información, tengan cuidado.",
  ui_story_3_1_149_dialog_content = "¿Aviduz? ¿Es el Colossus?",
  ui_story_3_1_150_dialog_content = "No estoy seguro ahora.",
  ui_story_3_1_151_dialog_content = "Eh...",
  ui_story_3_1_152_dialog_content = "Si te detengo ahora mismo, PlayerName, ¿me escucharás?",
  ui_story_3_1_153_dialog_content = "Lo siento, Soroz.",
  ui_story_3_1_154_dialog_content = "Eso es lo que pensé...",
  ui_story_3_1_155_dialog_content = "Aterriza ahora y prepárate para la batalla.",
  ui_story_3_1_A13_dialog_content = "¡Parece que tenemos bastantes Eclipsites esperándonos!",
  ui_story_3_3_1_dialog_content = "Alguien viene.",
  ui_story_3_3_2_dialog_content = "¿Quién sería tan tonto como para molestarme?",
  ui_story_3_3_3_dialog_content = "¿Quieres que me encargue de esto?",
  ui_story_3_3_4_dialog_content = "Ahora no. Estamos aquí por algo más importante.",
  ui_story_3_3_5_dialog_content = "Schummer... ¿Qué estás haciendo acá?",
  ui_story_3_3_6_dialog_content = "¡Bueno, si no es mi adorable hermano! Pensé que huirías como lo hiciste en ese entonces.",
  ui_story_3_3_7_dialog_content = "Maestro del <color=#FFB400>Mantiz</color>.",
  ui_story_3_3_8_dialog_content = "Oh, espera, no, debería llamarte por tu lindo apodo, <color=#FFB400>Mendelson</color> el Cobarde.",
  ui_story_3_3_9_dialog_content = "Eew, no puedo creer que lo primero que huelo después de despertar sea tu olor repugnante, Schummer.",
  ui_story_3_3_10_dialog_content = "¿O prefieres <color=#FFB400>Maestro del Aviduz</color>?",
  ui_story_3_3_11_dialog_content = "Al ver que eres mi hermano, te lo pondré fácil.",
  ui_story_3_3_12_dialog_content = "Llévame a buscar <color=#FFB400>esa cosa</color>.",
  ui_story_3_3_A1_dialog_content = "No sé a qué te refieres. No tengo nada aquí, Schummer, más que aburrida historia...",
  ui_story_3_3_A2_dialog_content = "Y secretos sucios. No asumas que no lo sé.",
  ui_story_3_3_A3_dialog_content = "Pásame el <color=#FFB400>Módulo Think Tank</color>. Sé que tienes uno aquí.",
  ui_story_3_3_A4_dialog_content = "... ¿Qué vas a hacer con eso?",
  ui_story_3_3_A5_dialog_content = "Oh, sólo para conseguir algo de... información que me interese.",
  ui_story_3_3_A6_dialog_content = "No, si eso es lo que estás planeando, nunca lo aceptaré.",
  ui_story_3_3_A7_dialog_content = "¡Lo que estás haciendo está explícitamente prohibido y en contra de los principios de los Colossus!",
  ui_story_3_3_13_dialog_content = "¿Y quieres que te lleve a eso?",
  ui_story_3_3_14_dialog_content = "Debes haber entendido mal el propósito de Mantiz, Schummer.",
  ui_story_3_3_15_dialog_content = "Vamos, Mendelson, no seas tan tacaño.",
  ui_story_3_3_16_dialog_content = "¿No estamos del mismo lado? De lo contrario, no habría sobrevivido hasta ahora.",
  ui_story_3_3_17_dialog_content = "Ese es el poder que un Celestita nunca puede poseer. Tú y yo somos lo mismo.",
  ui_story_3_3_18_dialog_content = "Y no he pasado un día sin arrepentimientos desde entonces, Schummer... Si tan solo supiera...",
  ui_story_3_3_19_dialog_content = "¿Mm...? Tu salud parece estar deteriorándose...",
  ui_story_3_3_A8_dialog_content = "Pobre Mendelson... Supongo que no has aceptado la bendición por completo.",
  ui_story_3_3_20_dialog_content = "¡Me duele verte luchar solo por hablar!",
  ui_story_3_3_22_dialog_content = "Donde cae mi martillo, la muerte será lanzada. Detén el vuelo.",
  ui_story_3_3_23_dialog_content = "¿Entendido? Cruza la línea y estás muerto.",
  ui_story_3_3_24_dialog_content = "No tengo ninguna pelea en mí de la que hablar, pero el Mantiz no es nada de lo que burlarse...",
  ui_story_3_3_25_dialog_content = "Escudos humanos. ¿Es eso lo que usan los cobardes para protegerse?",
  ui_story_3_3_26_dialog_content = "¡No me subestimes, Schummer!",
  ui_story_3_3_27_dialog_content = "¿Debo manejar esto, mi señora?",
  ui_story_3_3_A9_dialog_content = "¡Por última vez, no! ¡Esto no te incumbe!",
  ui_story_3_3_28_dialog_content = "Gatito y cachorro leales, qué apropiado, Mendelson.",
  ui_story_3_3_29_dialog_content = "Pero también por eso siempre has sido un cobarde inútil.",
  ui_story_3_3_30_dialog_content = "¡Qué insolente!",
  ui_story_3_3_31_dialog_content = "Suficiente. ¡Arrodíllate!",
  ui_story_3_3_32_dialog_content = "¡Desactivado! ¡Desactivado! Orden de máxima prioridad recibida, ¡ejecución obligatoria!",
  ui_story_3_3_33_dialog_content = "¡Philex! ¡Le está pasando algo, maestro!",
  ui_story_3_3_34_dialog_content = "Aghhh...",
  ui_story_3_3_35_dialog_content = "Vani, Philex... ¿Qué es esto? ¿¡Qué les hiciste, Schummer!?",
  ui_story_3_3_36_dialog_content = "\"Juguetes\" divertidos que tienes aquí, Mendelson.",
  ui_story_3_3_37_dialog_content = "Entonces, decidí hacerlos míos.",
  ui_story_3_3_38_dialog_content = "No son solo tu cuerpo y tu alma los que han caído, Schummer... ¡Te has convertido en algo completamente diabólico!",
  ui_story_3_3_39_dialog_content = "Gracias por el cumplido, pero eso no cambia lo que quiero hacer.",
  ui_story_3_3_40_dialog_content = "¡Devuélvemelas, monstruo!",
  ui_story_3_3_41_dialog_content = "¡Bueno, eso puedo hacer por ti! Philex, Vani... Esos son tus nombres, ¿verdad?",
  ui_story_3_3_42_dialog_content = "¡Sí!",
  ui_story_3_3_43_dialog_content = "Atrapa a Mendelson.",
  ui_story_3_3_44_dialog_content = "¡¿Qué?!",
  ui_story_3_3_45_dialog_content = "¡Pffft, se escapó una vez más!",
  ui_story_3_3_46_dialog_content = "\"No me subestimes\", dijo... Veo que sigue siendo el cobarde que era en ese entonces.",
  ui_story_3_3_47_dialog_content = "¿Qué debo hacer a continuación, mi señora?",
  ui_story_3_3_48_dialog_content = "Persíguelo y tráelo de vuelta...",
  ui_story_3_3_49_dialog_content = "Para poder ver bien su expresión.",
  ui_story_3_3_50_dialog_content = "¡Sí!",
  ui_story_3_3_51_dialog_content = "¡Sí!",
  ui_story_3_3_52_dialog_content = "No puedo permitirme que me atrapen... Oye, sé que puedes oírme... Ven rápido...",
  ui_story_3_3_53_dialog_content = "¡Puedo oírte! ¿Dónde estás? Tú también eres Celestita, ¿verdad?",
  ui_story_3_3_54_dialog_content = "Aviduz se ha vuelto aún más fuerte...",
  ui_story_3_3_55_dialog_content = "No puedo dejar que tome el Módulo Think Tank, no puedo dejar que... el secreto caiga en sus manos...",
  ui_story_3_3_56_dialog_content = "No puedes irte de mi lado nunca. Me duele verte esforzándote solo por hablar.",
  ui_story_3_3_57_dialog_content = "No se saldrá con la suya, Schummer, nunca...",
  ui_story_3_3_58_dialog_content = "No puedes marcharte de mi lado.",
  ui_story_3_3_59_dialog_content = "Pero has ganado, ¿no? Desde el principio.",
  ui_story_3_3_60_dialog_content = "Usaste un poder siniestro para corromperme, impidiéndome que te detuviera...",
  ui_story_3_3_61_dialog_content = "No, debo detenerte... Es mi deber y el del Mantiz.",
  ui_story_3_3_62_dialog_content = "Siempre has sido un cobarde llorón.",
  ui_story_3_3_63_dialog_content = "¿Debería vivir o morir...?",
  ui_story_3_3_64_dialog_content = "(Hablando en Eclipsiano) ¡Allí! ¡Atrápenlos!",
  ui_story_3_3_65_dialog_content = "¿Estás ahí, Celestita? ¡Debo seguir corriendo!",
  ui_story_3_3_66_dialog_content = "Date prisa... ¡Por mí y por ti mismo!",
  ui_story_3_3_A10_dialog_content = "Está siendo perseguido por Eclipsites, y no puedo precisar su ubicación exacta...",
  ui_story_3_3_A11_dialog_content = "Entiendo. ¡Pasemos a la acción!",
  ui_story_3_3_A12_dialog_content = "Hay más y más Eclipsites por delante, PlayerName. ¡Por favor, permanezca alerta!",
  ui_story_3_7_1_dialog_content = "Este lugar también está plagado de Eclipsites. ¿Estás bien, PlayerName?",
  ui_story_3_7_2_dialog_content = "Estoy bien.",
  ui_story_3_7_3_dialog_content = "Me pregunto si ese Celestita que mencionaste...",
  ui_story_3_7_4_dialog_content = "¡Espera!",
  ui_story_3_7_5_dialog_content = "No puedo dejar que me atrapen... No...",
  ui_story_3_7_6_dialog_content = "¡Estamos dentro! ¿Dónde estás? ¿Puedes escucharme?",
  ui_story_3_7_7_dialog_content = "¡Ven a mí! ¡Puedo protegerte!",
  ui_story_3_7_8_dialog_content = "¡Compañero Celestita, eres tú! ¡Estás aquí!",
  ui_story_3_7_9_dialog_content = "¡¡Perdón por llegar tarde!! ¡¿Puedes escucharme?!",
  ui_story_3_7_10_dialog_content = "Claro, compañero Celestita, claro. Incluso puedo verte. ¿Eres tú...?",
  ui_story_3_7_16_dialog_content = "¿Quién está ahí?",
  ui_story_3_7_17_dialog_content = "*Tose* Enemigo, detrás ...",
  ui_story_3_7_18_dialog_content = "¿Estás bien? ¡Bien, me alegro de haberlo hecho a tiempo!",
  ui_story_3_7_A5_dialog_content = "¿Es este...?",
  ui_story_3_7_A6_dialog_content = "¡Sí, Vice, es el Celestita que suplicó nuestra ayuda!",
  ui_story_3_7_19_dialog_content = "Está en muy mal estado, PlayerName, y estas lesiones no las infligen los Eclipsites.",
  ui_story_3_7_20_dialog_content = "¿Quién te hizo esto?",
  ui_story_3_7_22_dialog_content = "¡Objetivo Mendelson encontrado!",
  ui_story_3_7_23_dialog_content = "¡Ejecutando comando de captura!",
  ui_story_3_7_24_dialog_content = "Philex, Vani...",
  ui_story_3_7_25_dialog_content = "¡Cúbrete, compañero Celestita!",
  ui_story_3_7_26_dialog_content = "Es tuyo, PlayerName. ¡Nos ocuparemos de la lucha!",
  ui_story_3_7_27_dialog_content = "Philex, Vani...",
  ui_story_3_7_28_dialog_content = "Lo siento... Al final, todavía no pude hacer nada...",
  ui_story_3_7_29_dialog_content = "No parecen ser Eclipsites. ¿Qué está pasando?",
  ui_story_3_7_30_dialog_content = "Eran mis guardias como parte del mecanismo de defensa de este Colossus.",
  ui_story_3_7_31_dialog_content = "Pero, ¿por qué te atacaron?",
  ui_story_3_7_32_dialog_content = "Es ella... Sus poderes se apoderaron de ellos.",
  ui_story_3_7_33_dialog_content = "No puedo creerlo...",
  ui_story_3_7_34_dialog_content = "Mis condolencias...",
  ui_story_3_7_35_dialog_content = "Nunca pensé que sería como entonces ...",
  ui_story_3_7_36_dialog_content = "¿Cuál es tu nombre, compañero Celestita?",
  ui_story_3_7_37_dialog_content = "Soy Mendelson, Maestro de Mantiz.",
  ui_story_3_7_38_dialog_content = "Mantiz... Eso suena familiar. Desafortunadamente, he olvidado demasiado...",
  ui_story_3_7_40_dialog_content = "Ese día, para proteger a Spark, los Colossus sobrevivientes tomaron caminos separados.",
  ui_story_3_7_41_dialog_content = "Parece que Soroz te ha protegido todos estos años... Eso es maravilloso.",
  ui_story_3_7_42_dialog_content = "¿Cuánto tiempo llevas aquí? ¿Hay otros Celestitas sobrevivientes?",
  ui_story_3_7_43_dialog_content = "¿Por qué te ves así? ¿Y qué es Aviduz?",
  ui_story_3_7_44_dialog_content = "*Tose* Yo... *Tose*",
  ui_story_3_7_45_dialog_content = "Está lesionado, PlayerName. Déjalo respirar primero...",
  ui_story_3_7_46_dialog_content = "Perdóname, no soy como tú... PlayerName, Soroz...",
  ui_story_3_7_47_dialog_content = "Sigues vivo. Eso significa que Soroz cumplió con su deber de proteger a los Celestitas.",
  ui_story_3_7_48_dialog_content = "Pero no pude completar mi única misión...",
  ui_story_3_7_49_dialog_content = "Lo siento, pero no entiendo.",
  ui_story_3_7_50_dialog_content = "¿No te lo dijo Soroz, PlayerName?",
  ui_story_3_7_51_dialog_content = "Lamentablemente, perdí la memoria cuando choqué.",
  ui_story_3_7_52_dialog_content = "Aparte de la orden de servir y proteger PlayerName, tampoco recuerdo mucho más.",
  ui_story_3_7_53_dialog_content = "Soroz sufrió un daño tremendo ese día.",
  ui_story_3_7_54_dialog_content = "¿Así que...? *Tose* Sentí tu conversación...",
  ui_story_3_7_55_dialog_content = "No estoy seguro de si fue desafortunado o afortunado...",
  ui_story_3_7_56_dialog_content = "Entonces, ¿qué pasó realmente aquí?",
  ui_story_3_7_57_dialog_content = "En Mantiz, hay un elemento crucial llamado <color=#FFB400>Módulo Think Tank</color>...",
  ui_story_3_7_A1_dialog_content = "Incluye gran cantidad de información, desde historia Celestita hasta los clásicos Aurorians...",
  ui_story_3_7_58_dialog_content = "Tiene los himnos más gloriosos, así como los susurros más oscuros del abismo...",
  ui_story_3_7_60_dialog_content = "Pero lo que quiere Aviduz-Schummer es la parte más insignificante...",
  ui_story_3_7_61_dialog_content = "¡¿Entonces Schummer está aquí?!",
  ui_story_3_7_62_dialog_content = "Sí. En este momento, ella se dirige a mi núcleo para arrebatar el Módulo Think Tank.",
  ui_story_3_7_A2_dialog_content = "Y usarlo para... ¡No, no puedo decirte lo que nunca debería ser revelado!",
  ui_story_3_7_63_dialog_content = "¡Entonces tenemos que detenerla! ¡Ayúdame, Vice!",
  ui_story_3_7_64_dialog_content = "Pídele al Celestita que te guíe. Me encantaría conocer en persona al cerebro detrás de la destrucción de Subciudad 28.",
  ui_story_3_7_65_dialog_content = "También has estado esperando este día, ¿verdad, PlayerName?",
  ui_story_3_7_A3_dialog_content = "Exactamente. No puedo esperar a que me respondan todas mis preguntas.",
  ui_story_3_7_A4_dialog_content = "Ten cuidado, PlayerName... Ella...",
  ui_story_3_7_66_dialog_content = "*Tose*...",
  ui_story_3_7_67_dialog_content = "Su condición está empeorando. ¿Qué debo hacer?",
  ui_story_3_7_68_dialog_content = "No podemos dejarlo aquí, PlayerName, pero tenemos que seguir adelante...",
  ui_story_3_7_69_dialog_content = "...",
  ui_story_3_7_70_dialog_content = "No te preocupes, compañero Celestita.",
  ui_story_3_7_71_dialog_content = "Estaré bien. Será mucho más fácil conmigo guiándote.",
  ui_story_3_7_72_dialog_content = "Como maestra de Mantiz, es mi deber impedir que tome el Módulo Think Tank...",
  ui_story_3_7_73_dialog_content = "Gracias, Mendelson. Cuando esto termine, ¡debes contarme todo sobre los Celestitas!",
  ui_story_3_7_74_dialog_content = "Por supuesto, PlayerName. Te prometo que te contaré todo sobre Eraveil...",
  ui_story_3_7_75_dialog_content = "¡Entonces, por favor, abre el camino, Mendelson!",
  ui_story_3_7_76_dialog_content = "¡Detengamos a Schummer!",
  ui_story_3_9_A1_dialog_content = "(Qué estoy haciendo... Tengo la oportunidad de huir, pero elijo volver...)",
  ui_story_3_9_A2_dialog_content = "(Es imposible que ganemos, ¿no es así...? Entonces, por qué luchar...)",
  ui_story_3_9_A3_dialog_content = "(¡Corre, Mendelson! Olvídate de tu llamado deber, por el bien de tu propia vida...)",
  ui_story_3_9_2_dialog_content = "¿Por el bien de mi propia vida...?",
  ui_story_3_9_3_dialog_content = "¿Por qué te detienes? ¿Ya llegamos?",
  ui_story_3_9_4_dialog_content = "¿Estás seguro acerca de esto? Todavía hay tiempo para dar marcha atrás si quieres escapar...",
  ui_story_3_9_5_dialog_content = "Schummer no es un enemigo cualquiera. Solo mira lo que le hizo a Philex y Vani...",
  ui_story_3_9_6_dialog_content = "Eran mis leales guardianes, pero ahora me desean la muerte.",
  ui_story_3_9_7_dialog_content = "Lo que ella es capaz de hacer puede exceder incluso lo que podemos concebir.",
  ui_story_3_9_8_dialog_content = "¿Por qué quieres enfrentarte a ella cuando eres incapaz de combatir, PlayerName?",
  ui_story_3_9_10_dialog_content = "La he estado buscando para responder a mis muchas preguntas, sobre Subciudad 28, hace unos 17 años...",
  ui_story_3_9_A4_dialog_content = "Y ahora, ella está persiguiendo implacablemente a otro Celestita...",
  ui_story_3_9_13_dialog_content = "¡No puedo irme! ¡Debo detenerla!",
  ui_story_3_9_14_dialog_content = "Es fácil escapar, pero ¿a dónde podemos huir?",
  ui_story_3_9_15_dialog_content = "Hay lugares a los que nunca podremos volver, Mendelson. Si nos dirigimos directamente a la Puerta del Infierno...",
  ui_story_3_9_A5_dialog_content = "¡Entonces acabemos juntos con ese miserable ser!",
  ui_story_3_9_16_dialog_content = "Ahora lo entiendo. ¿Qué estaba pensando?",
  ui_story_3_9_18_dialog_content = "Eraveil fue destruido. Todos mis amigos y seres queridos fueron masacrados por los Eclipsites.",
  ui_story_3_9_19_dialog_content = "Solo yo, el tímido y cobarde, hui con Mantiz para ir . a la deriva.",
  ui_story_3_9_20_dialog_content = "Y ahora, no puedo creer que esté teniendo el mismo pensamiento.",
  ui_story_3_9_21_dialog_content = "Mendelson...",
  ui_story_3_9_22_dialog_content = "Si no persevero, entonces no soy diferente de lo que era. Nosotros...",
  ui_story_3_9_23_dialog_content = "¡Mendelson!",
  ui_story_3_9_24_dialog_content = "Ah... Mi...",
  ui_story_3_9_25_dialog_content = "¿Por qué de repente estás en tal agonía?",
  ui_story_3_9_26_dialog_content = "¿Ha comenzado? ¡Sé <color=#FFB400>que lo tienes</color>, Schummer!",
  ui_story_3_9_27_dialog_content = "¡Puedo sentir tu inmenso poder, suficiente para enterrar al Mantiz en completa oscuridad!",
  ui_story_3_9_28_dialog_content = "Apagando hasta el último destello de luz...",
  ui_story_3_9_29_dialog_content = "¿Puedo hacer algo por ti, Mendelson?",
  ui_story_3_9_30_dialog_content = "¡No te... preocupes! Esto realmente disipó lo último de mi cobardía.",
  ui_story_3_9_A8_dialog_content = "Vamos, PlayerName y tus amigos también. Sígueme.",
  ui_story_3_9_A9_dialog_content = "¡Mataremos a los Eclipsites ante nosotros hasta alcanzar las máximas profundidades de la oscuridad!",
  ui_story_3_9_A10_dialog_content = "¡Eso y cuida tu espalda! ¡Se acercan enemigos!",
  ui_story_3_9_31_dialog_content = "Oh, Mendelson, mi querido hermano, detén tu inútil lucha...",
  ui_story_3_9_32_dialog_content = "¿Cuál es el punto de esconderlo tan profundo? De todos modos lo encontré: ¡el <color=#FFB400>Módulo Think Tank</color>!",
  ui_story_3_9_33_dialog_content = "No es tan difícil como pensaba. De hecho, es un poco aburrido.",
  ui_story_3_9_34_dialog_content = "Vamos, enséñame tu secreto...",
  ui_story_3_9_A11_dialog_content = "¡Rayos! Un cifrado. Supongo que esto llevará un tiempo.",
  ui_story_3_9_35_dialog_content = "Mi amo te espera, mi Señora...",
  ui_story_3_9_36_dialog_content = "¿Cuánto tiempo vas a jugar con eso?",
  ui_story_3_9_37_dialog_content = "Solo un poco más y listo...",
  ui_story_3_9_38_dialog_content = "Un poco más y lo tendré todo, incluido el \"secreto.\"",
  ui_story_3_9_39_dialog_content = "¡A través de mí, se convertirán en uno con mi <color=#FFB400>Colossus Negro</color> y se convertirán en la piedra angular de la evolución!",
  ui_story_3_9_41_dialog_content = "En cualquier momento, Schummer.",
  ui_story_3_9_42_dialog_content = "(Hablando en Eclipsiano) Vayan, mis camaradas.",
  ui_story_3_9_43_dialog_content = "¿Es necesario enviar tantos?",
  ui_story_3_9_44_dialog_content = "Todavía no es lo suficientemente cerca. Los Eclipsites dijeron que los juguetes que le arrebataste a Mendelson han sido derrotados...",
  ui_story_3_9_45_dialog_content = "Por el maestro de Soroz y tu compañero Celestita.",
  ui_story_3_9_47_dialog_content = "Qué oportuno. Después de obtener lo que vine a buscar, los terminaré todos de una sola vez.",
  ui_story_3_9_48_dialog_content = "Los rencores se pueden resolver en cualquier momento, pero un plan es un plan, Schummer. No lo estropees.",
  ui_story_3_9_50_dialog_content = "¿Crees que puedo aguantarlo? ¿Cuándo el gusano que se escapó está al fin a mi alcance?",
  ui_story_3_9_51_dialog_content = "Odio el caos, el desorden y la improvisación.",
  ui_story_3_9_52_dialog_content = "Y no me gusta pelear. No me interesan esfuerzos tan vulgares.",
  ui_story_3_9_53_dialog_content = "...",
  ui_story_3_9_54_dialog_content = "Muy bien, esta conversación ha terminado.",
  ui_story_3_9_56_dialog_content = "¡Tabaad!",
  ui_story_3_9_57_dialog_content = "He acechado en las sombras el tiempo suficiente, maestro. ¿Debo hacer mi movimiento?",
  ui_story_3_9_58_dialog_content = "Actúa como te parezca.",
  ui_story_3_9_59_dialog_content = "Si señor.",
  ui_story_3_9_61_dialog_content = "Los haré pedazos con mis propias manos, sumergiendo su patética luz en una oscuridad infinita...",
  ui_story_3_9_A12_dialog_content = "¿Lo sientes, PlayerName? Los Eclipsites se están concentrando en nuestra dirección.",
  ui_story_3_9_A13_dialog_content = "Sí, y en masa. Pero estos tipos no nos disuadirán.",
  ui_story_3_9_A14_dialog_content = "Es correcto. ¡Sigamos moviéndonos y matemos a todos los Eclipsites que se interponen en nuestro camino!",
  ui_story_3_12_2_dialog_content = "Ya estamos acá.",
  ui_story_3_12_3_dialog_content = "¿Es ahí donde se encuentra el Módulo Think Tank?",
  ui_story_3_12_4_dialog_content = "Sí. Está atento a Schummer.",
  ui_story_3_12_5_dialog_content = "Terminemos con esto juntos, Mendelson.",
  ui_story_3_12_6_dialog_content = "¡Sí, PlayerName! Pararemos...",
  ui_story_3_12_7_dialog_content = "Tómalo con calma, Mendelson. Tu condición es...",
  ui_story_3_12_9_dialog_content = "No te preocupes por eso. Es el <color=#FFB400>poder de la oscuridad</color>... No se puede controlar y se ha extendido por todo mi cuerpo.",
  ui_story_3_12_10_dialog_content = "Cómo... ¿Cómo ocurrió eso?",
  ui_story_3_12_12_dialog_content = "Ese día, hace 17 años, acepté el <color=#FFB400>Poder de los Eclipsites</color> para poder sobrevivir.",
  ui_story_3_12_A1_dialog_content = "<color=#FFB400>Al igual que hizo Schummer</color>, excepto que mi cuerpo se había estado deteriorando.",
  ui_story_3_12_A2_dialog_content = "¿Fue porque mi fe no era lo suficientemente fuerte o porque siempre me he negado a vivir así?",
  ui_story_3_12_15_dialog_content = "El sufrimiento es solo temporal, niña. No tomes decisiones de las que te arrepientas.",
  ui_story_3_12_16_dialog_content = "Lo siento maestro. Es demasiado tarde. Quiero sobrevivir...",
  ui_story_3_12_17_dialog_content = "¿Aceptas el poder de Eclipsite solo para sobrevivir? ¿Pero por qué?",
  ui_story_3_12_18_dialog_content = "Irónico, ¿no es así?, que incluso como una abominación, he estado cumpliendo con mi deber como Maestro de Mantiz.",
  ui_story_3_12_A3_dialog_content = "¿Pero quién soy yo? ¿Qué soy yo?",
  ui_story_3_12_A4_dialog_content = "Todavía hay esperanza. Si ganamos a Schummer, ¡te prometo que encontraré la manera de que vuelvas a la normalidad!",
  ui_story_3_12_A5_dialog_content = "No importa. Es demasiado tarde para mí. El destino actúa de formas misteriosas.",
  ui_story_3_12_19_dialog_content = "Antes, confié en el poder de la oscuridad para permanecer dormido en este subterráneo oscuro sin ser detectado durante muchos años...",
  ui_story_3_12_20_dialog_content = "Como todas las veces antes, pensé que podría huir con el rabo entre las piernas...",
  ui_story_3_12_21_dialog_content = "Luego acurrucarse en otro rincón oscuro y continuar con mi miserable existencia.",
  ui_story_3_12_22_dialog_content = "¡Pero me encontré contigo! Quizás es hora de que sea valiente por una vez en mi vida.",
  ui_story_3_12_23_dialog_content = "¡No voy a correr esta vez! ¡Salvemos nuestro futuro de este miserable destino!",
  ui_story_3_13_1_dialog_content = "<color=#e8d9bb>Fuera de los restos de Mantiz</color>",
  ui_story_3_13_2_dialog_content = "¿Están aquí, Tabaad?",
  ui_story_3_13_3_dialog_content = "Tres almas inquietas, una al borde de la muerte.",
  ui_story_3_13_4_dialog_content = "Está bien. Manéjalo como quieras.",
  ui_story_3_13_5_dialog_content = "Sí. Que la Madre sea mi testigo, no escatimaré esfuerzos. Bajo la Aurora, solo el Eclipse es eterno.",
  ui_story_3_13_6_dialog_content = "¿Este es el chico?",
  ui_story_3_13_8_dialog_content = "¿Qué te tomó tanto tiempo? Te perdiste bastante el espectáculo.",
  ui_story_3_13_9_dialog_content = "Espera, ¿eres solo tú, sólo?",
  ui_story_3_13_10_dialog_content = "Incluso sólo, soy más que suficiente.",
  ui_story_3_13_11_dialog_content = "¿Suficiente?",
  ui_story_3_13_12_dialog_content = "PlayerName, el último de los Celestitas. Eres diferente de este Aurorian. Podrías haber elegido un camino mejor.",
  ui_story_3_13_13_dialog_content = "¿Cómo supiste el nombre de PlayerName?",
  ui_story_3_13_14_dialog_content = "Porque tenemos todo el conocimiento, la visión y el futuro que buscas.\nPlayerName, ¿no los has anhelado siempre?",
  ui_story_3_13_15_dialog_content = "No intentes ocultarlo, PlayerName. Entiendo los deseos más íntimos de ustedes, los Celestitas. Esto es lo que anhelas...",
  ui_story_3_13_16_dialog_content = "¿PlayerName?",
  ui_story_3_13_17_dialog_content = "Anhelas un gran poder para no tener que estar detrás de los Aurorians.",
  ui_story_3_13_18_dialog_content = "Yo...",
  ui_story_3_13_19_dialog_content = "Acércate. Sí, más cerca. ¡Serás como mi maestro, <color=#FFB400>abraza el Eclipse</color>!",
  ui_story_3_13_20_dialog_content = "¿El eclipse?",
  ui_story_3_13_21_dialog_content = "¡Piensa otra vez!",
  ui_story_3_13_22_dialog_content = "El perro llorón ha vuelto, arrastrando la cola.",
  ui_story_3_13_23_dialog_content = "¿Tienes miedo? ¿Dónde está tu amo?",
  ui_story_3_13_A1_dialog_content = "(¡El Módulo Think Tank y Schummer se han ido!)",
  ui_story_3_13_24_dialog_content = "Me sorprende, Mendelson.",
  ui_story_3_13_25_dialog_content = "Te escondiste dentro del Colossus como un perro inmundo mientras presenciabas la masacre de tu gente...",
  ui_story_3_13_26_dialog_content = "Cerraste el mundo, negándote a enfrentar la realidad. ¿Estás realmente preparado para afrontar tu peor pesadilla?",
  ui_story_3_13_27_dialog_content = "Qué pena. Tus escalofríos exponen lo débil e inútil que eres... Patético.",
  ui_story_3_13_28_dialog_content = "¡Cierra la boca y deja en paz a Mendelson!",
  ui_story_3_13_29_dialog_content = "¿Estás bien?",
  ui_story_3_13_30_dialog_content = "Lo siento, parece que el verdadero culpable se escapó.",
  ui_story_3_13_31_dialog_content = "Y también se tomó el Módulo Think Tank. Uf, casi termino por...",
  ui_story_3_13_32_dialog_content = "Pero ya que se fue, hay algo más que debo hacer...",
  ui_story_3_13_33_dialog_content = "Relájate. ¡Tenemos esto!",
  ui_story_3_13_34_dialog_content = "Qué extraño, los condenados se consuelan unos a otros.",
  ui_story_3_13_35_dialog_content = "¡No te distraigas, PlayerName!",
  ui_story_3_13_36_dialog_content = "¡Guía el camino!",
  ui_story_3_13_37_dialog_content = "¿Ya termino?",
  ui_story_3_13_38_dialog_content = "<color=#e8d9bb>Solo queda un silencio inquietante.</color>",
  ui_story_3_13_39_dialog_content = "¡No, algo no está bien! ¡El poder de las tinieblas se está acumulando! ¡Cuidado con el ataque!",
  ui_story_3_13_40_dialog_content = "¡Este no es el final para Tabaad! ¡Sé testigo de mi convicción!",
  ui_story_3_13_41_dialog_content = "¡Oscuridad, devora al Celestita!",
  ui_story_3_13_42_dialog_content = "¡Uh-oh, viene por mí!",
  ui_story_3_13_43_dialog_content = "¡No puede dañar a alguien protegido por Illumina tan fácilmente!",
  ui_story_3_13_44_dialog_content = "¡Bien dicho, teniente!",
  ui_story_3_13_45_dialog_content = "<color=#e8d9bb>¡Woosh!</color>",
  ui_story_3_13_F1_dialog_content = "¡¡¡Gaah!!!",
  ui_story_3_13_46_dialog_content = "¡Co-comandante!",
  ui_story_3_13_47_dialog_content = "Supongo que llegué en el momento adecuado.",
  ui_story_3_13_48_dialog_content = "(Hablando en Eclipsiano) Cosas inferiores, sucias, ignorantes, débiles...",
  ui_story_3_13_49_dialog_content = "El Eclipsite... se convirtió en flores de cerezo y se disipó...",
  ui_story_3_13_50_dialog_content = "¡Agradecemos tu ayuda!",
  ui_story_3_13_51_dialog_content = "Teniente Vice, has violado el protocolo de Illumina. ¿Te das cuenta de las consecuencias de tus acciones?",
  ui_story_3_13_52_dialog_content = "...",
  ui_story_3_13_53_dialog_content = "¡Teniente Vice!",
  ui_story_3_13_54_dialog_content = "¡Aquí!",
  ui_story_3_13_55_dialog_content = "Quiero un informe tuyo de no menos de 5,000 palabras sobre el Colossus y el Celestita incapaces de luchar.",
  ui_story_3_13_56_dialog_content = "¡Oye! ¡Soy un navegador experto y puedo comandar el Colossus!",
  ui_story_3_13_57_dialog_content = "No reiteres cosas que ya sé.",
  ui_story_3_13_58_dialog_content = "<color=#e8d9bb>¡Choque!</color>",
  ui_story_3_13_59_dialog_content = "¡Mendelson! ¡Tu cuerpo!",
  ui_story_3_13_60_dialog_content = "¡Oh, no! ¿Él...?",
  ui_story_3_13_61_dialog_content = "Parece que... mi destino está sellado. Es hora de expiar mis malas acciones.",
  ui_story_3_13_62_dialog_content = "No... ¡podemos salvarte! ¿Verdad, Vice?",
  ui_story_3_13_63_dialog_content = "PlayerName, yo...",
  ui_story_3_13_64_dialog_content = "Todo está bien. Es mi propia elección. Yo... Esperaba que llegara este día...",
  ui_story_3_13_A2_dialog_content = "Hay asuntos más importantes a la mano, PlayerName.",
  ui_story_3_13_A3_dialog_content = "Dada la situación, supongo que ya no tengo que mantenerlo en secreto...",
  ui_story_3_13_65_dialog_content = "¿Recuerdas el Módulo Think Tank que mencioné? <color=#FFB400>Escuche atentamente lo que tengo que decir</color>...",
  ui_story_3_13_A4_dialog_content = "Aunque cada Colossus tiene su propia especialización, ninguna fue diseñada en especial para combate.",
  ui_story_3_13_A5_dialog_content = "Excepto por el Aviduz. ¡Es el único Colossus con capacidades ofensivas!",
  ui_story_3_13_66_dialog_content = "Afortunadamente, aún no está completo.",
  ui_story_3_13_67_dialog_content = "Schummer, su maestro, busca rectificar el Colossus. Ella necesita:",
  ui_story_3_13_X67_dialog_content = "<color=#FFB400>Módulo Think Tank</color>",
  ui_story_3_13_X68_dialog_content = "<color=#FFB400>Unidad de crecimiento autónomo</color>",
  ui_story_3_13_X69_dialog_content = "...y <color=#FFB400>Módulo de control de llama</color>",
  ui_story_3_13_X70_dialog_content = "Los tres módulos.",
  ui_story_3_13_A6_dialog_content = "¡Primero necesita el Módulo Think Tank porque revelará la ubicación de los otros dos módulos!",
  ui_story_3_13_68_dialog_content = "Para adquirir el poder supremo, Schummer intentará obtenerlos a toda costa.",
  ui_story_3_13_69_dialog_content = "¡Pero el Módulo Think Tank ya está en sus manos!",
  ui_story_3_13_70_dialog_content = "No. Ella no se saldrá con la suya. El Módulo todavía tiene una secuencia de protección que se activará tras mi muerte. Le preparé una pequeña \"sorpresa\".",
  ui_story_3_13_71_dialog_content = "Tómalo con calma, Mendelson. Tendremos mucho tiempo para hablar después de que te recuperes.",
  ui_story_3_13_72_dialog_content = "Podemos acabar con Schummer juntos, y cuando termine, ¡podemos ir a casa!",
  ui_story_3_13_73_dialog_content = "Nunca he estado en Eraveil. Me lo puedes contar...",
  ui_story_3_13_74_dialog_content = "Desafortunadamente, se acabó para mí. Haz que Soroz te cuente las historias... O encuentra otros Celestitas...",
  ui_story_3_13_75_dialog_content = "¡No, Mendelson!",
  ui_story_3_13_A7_dialog_content = "Cállate y escúchame. El tiempo se acaba...",
  ui_story_3_13_76_dialog_content = "Cuando me haya ido, creo que el próximo lugar al que se dirigirá Schummer será <color=#FFB400>Lumopolis</color>, la última ciudad Aurorian...",
  ui_story_3_13_A8_dialog_content = "¡Porque hay otro Módulo Think Tank! Sí, hay más de uno.",
  ui_story_3_13_A9_dialog_content = "Debes advertir a Lumopolis, PlayerName.",
  ui_story_3_13_A10_dialog_content = "Los Aurorians seguramente no se dan cuenta de lo importante que es el Módulo Think Tank...",
  ui_story_3_13_77_dialog_content = "¡Mendelson! ¡No me dejes, te lo ruego!",
  ui_story_3_13_78_dialog_content = "Realmente desearía poder estar contigo y con todos estos nuevos amigos, PlayerName.",
  ui_story_3_13_79_dialog_content = "Pero esta vez no quiero correr más. Schummer no debe salirse con la suya...",
  ui_story_3_13_80_dialog_content = "¡Al menos nunca tendrá en sus manos mi Módulo Think Tank! Esta vez, el cobarde se pone de pie... ¡desafiante!",
  ui_story_3_13_81_dialog_content = "Mendelson...",
  ui_story_3_13_82_dialog_content = "Es tan hermoso...",
  ui_story_3_13_83_dialog_content = "...",
  ui_story_3_13_84_dialog_content = "Eso es... un dragón bastante singular.",
  ui_story_3_13_F2_dialog_content = "Ese es el <color=#FFB400>Zakura</color> de comandante Hiiro.",
  ui_story_3_13_F3_dialog_content = "Qué hermoso. ¿Quién sabía que había un color tan hermoso en este mundo? Si tan solo pudiera ver más...",
  ui_story_3_13_85_dialog_content = "Todos estos años en la oscuridad, casi me olvido de cómo es el cielo.",
  ui_story_3_13_86_dialog_content = "¡Tenemos que hacer algo, PlayerName, Comandante Hiiro! Vamos a dejarlo...",
  ui_story_3_13_F4_dialog_content = "...",
  ui_story_3_13_F5_dialog_content = "...",
  ui_story_3_13_87_dialog_content = "Ojalá tuviéramos más tiempo para hablar, PlayerName. Ojalá pudiera ser como en los viejos tiempos... Soroz, cuando nosotros...",
  ui_story_3_13_88_dialog_content = "Ojalá pudiera ver el cielo una vez más...",
  ui_story_3_13_89_dialog_content = "¡Soroz!",
  ui_story_3_13_90_dialog_content = "Sí, PlayerName.",
  ui_story_3_13_91_dialog_content = "Haz un enlace mental con Mendelson y enséñale el cielo.",
  ui_story_3_13_92_dialog_content = "Sí.",
  ui_story_3_13_93_dialog_content = "Oh, el cielo azul... Ha pasado mucho tiempo.",
  ui_story_3_13_94_dialog_content = "Permíteme compartir Soroz contigo, Mendelson.",
  ui_story_3_13_95_dialog_content = "Ahora y siempre, él será tus ojos y oídos para captar todo lo que esté por encima de las nubes.",
  ui_story_3_13_96_dialog_content = "¿Así es la muerte? Es un poco diferente... de lo que imaginaba... Se siente tan solo...",
  ui_story_3_13_97_dialog_content = "Estoy aquí, maestro.",
  ui_story_3_13_98_dialog_content = "¿Qué es esa voz?",
  ui_story_3_13_99_dialog_content = "Estamos todos aquí.",
  ui_story_3_13_100_dialog_content = "Estaremos contigo hasta el final.",
  ui_story_3_13_101_dialog_content = "Vani... Philex...",
  ui_story_3_13_103_dialog_content = "¡Mendelson!",
  ui_story_3_13_104_dialog_content = "...",
  ui_story_3_13_105_dialog_content = "...",
  ui_story_3_13_106_dialog_content = "<size=45>¿Recibiste mi sorpresa, Schummer?</size>",
  ui_story_3_13_107_dialog_content = "¿Qué?",
  ui_story_3_13_108_dialog_content = "¿El Módulo Think Tank es <color=#FFB400>autodestructivo</color>? ¡No está bien!",
  ui_story_3_13_110_dialog_content = "<anim type=Shake>¡MEN-DEL-SON!</anim>",
  ui_story_3_13_111_dialog_content = "Eso fue vergonzoso, Schummer. Parece que las cosas no salieron como se esperaba.",
  ui_story_3_13_112_dialog_content = "No creía que Mendelson tuviera un último truco bajo la manga. Esta cosa... ahora es inútil.",
  ui_story_3_13_113_dialog_content = "¡Cómo se atreve ese maldito y patético cobarde...!",
  ui_story_3_13_114_dialog_content = "Jajajaja, ¡ese es mi hermano!",
  ui_story_3_13_115_dialog_content = "Ha sido un cobarde toda su vida, sin embargo, encontró el coraje para desafiarme antes de su muerte.",
  ui_story_3_13_116_dialog_content = "No me digas que no obtuviste nada de eso.",
  ui_story_3_13_118_dialog_content = "Solo en fragmentos, pero nueva información, no obstante.",
  ui_story_3_13_120_dialog_content = "Hay otro Módulo Think Tank idéntico en <color=#FFB400>Lumopolis</color>.",
  ui_story_3_13_121_dialog_content = "Esos tontos Aurorians no tienen idea de su significado.",
  ui_story_3_13_122_dialog_content = "Lumopolis no es un lugar donde puedas entrar y salir cuando quieras. Tengo que averiguar cómo limpiar el desastre que hiciste.",
  ui_story_3_13_123_dialog_content = "Mendelson, observa de cerca. Nadie podrá evitar que complete...",
  ui_story_3_13_124_dialog_content = "Te mostraré lo insignificante que fue tu sacrificio.",
  ui_story_3_14_A2_dialog_content = "<color=#e8d9bb>El archivo de Lumopolis</color>",
  ui_story_3_14_1_dialog_content = "Hombre, tantas cosas que hacer de nuevo hoy...",
  ui_story_3_14_2_dialog_content = "Honestamente, qué lío... Todo está aquí... Oye, ¿Qué es esto?",
  ui_story_3_14_3_dialog_content = "<color=#e8d9bb>¡Clang!</color>",
  ui_story_3_14_4_dialog_content = "¡Ay!",
  ui_story_3_14_5_dialog_content = "¿Estás bien? ¿Dónde te golpeó?",
  ui_story_3_14_6_dialog_content = "Estoy bien, pero ¿qué te pasa? ¡Ni siquiera puedes mover las cosas bien!",
  ui_story_3_14_7_dialog_content = "Lo siento, esta es mi primera vez...",
  ui_story_3_14_8_dialog_content = "¡Oye! ¿Qué...? ¡¿Qué sucede contigo?!",
  ui_story_3_14_9_dialog_content = "Lo siento, lo siento mucho, no lo hice a propósito...",
  ui_story_3_14_10_dialog_content = "¡Tú! ¡Lo <color=#FFB400>rompiste</color>! ¡Es muy valioso, sabes!",
  ui_story_3_14_11_dialog_content = "... Lo recogeré ahora mismo.",
  ui_story_3_14_12_dialog_content = "No importa, lo haré yo. No sé qué hace, pero seguro que parece caro.",
  ui_story_3_14_13_dialog_content = "Pasos.",
  ui_story_3_14_14_dialog_content = "¡Tú, deja de charlar en tu turno! ¡Concéntrate en tu trabajo!",
  ui_story_3_14_15_dialog_content = "¡Estamos revisando los elementos del archivo, capitán! Estamos a mitad de camino...",
  ui_story_3_14_16_dialog_content = "Ya no te necesitan aquí. Sólo vete.",
  ui_story_3_14_17_dialog_content = "¡Sí, Capitán!",
  ui_story_3_14_18_dialog_content = "¡Sí, Capitán!",
  ui_story_3_14_A1_dialog_content = "Bueno, es exactamente como lo describió el <color=#FFB400>Maestro</color>.",
  ui_story_3_14_19_dialog_content = "Eres muy valioso, pero las autoridades de Lumopolis piensan que solo eres una antigüedad.",
  ui_story_3_14_20_dialog_content = "Alguien entenderá tu <color=#FFB400>valor verdadero</color> muy pronto...",
  ui_story_3_14_B1_dialog_content = "¡Capitán! ¡El Jefe nos pide que nos presentemos!",
  ui_story_3_14_B2_dialog_content = "...",
  ui_story_3_14_B3_dialog_content = "Entiendo. Vamos.",
  ui_story_4_1_1_dialog_content = "El <color=#FFB400>Módulo Think Tank</color>, <color=#FFB400>Unidad de Crecimiento Autónomo</color> y <color=#FFB400>Módulo de Control de Llama</color>... ¿Qué aspecto tienen exactamente?",
  ui_story_4_1_2_dialog_content = "Mendelson no proporcionó suficiente información, por lo que incluso si sabemos que hay otro Módulo Think Tank en Lumopolis...",
  ui_story_4_1_3_dialog_content = "¿Podría ser otro Colossus?",
  ui_story_4_1_4_dialog_content = "No importa lo que esté planeando, ¡debemos ir un paso por delante de ella!",
  ui_story_4_1_5_dialog_content = "¿Nos dirigimos directamente a Lumopolis? ¿Y luego qué?",
  ui_story_4_1_6_option_content = "¡Lo resolveremos entonces!",
  ui_story_4_1_7_option_content = "Francamente, no lo he pensado bien.",
  ui_story_4_1_8_dialog_content = "Eso no suena tranquilizador, PlayerName.",
  ui_story_4_1_9_dialog_content = "No sabemos nada sobre a quién nos enfrentamos. No conocemos sus habilidades, motivos o incluso cómo son.",
  ui_story_4_1_10_dialog_content = "Al menos eres honesto al respecto...",
  ui_story_4_1_11_dialog_content = "Pero no podemos idear un plan sin conocer a nuestro oponente.",
  ui_story_4_1_12_dialog_content = "No conocemos sus habilidades, motivos o incluso cómo son.",
  ui_story_4_1_13_dialog_content = "Además, Lumopolis no es como Illumina. Es... bueno, nada más que problemas.",
  ui_story_4_1_14_dialog_content = "<color=#e8d9bb>Vice tiene una expresión de agonía, como si evocara un recuerdo doloroso.</color>",
  ui_story_4_1_15_dialog_content = "Ya que eres el Navegador, PlayerName, deberías hacer la decisión.",
  ui_story_4_1_16_dialog_content = "Todavía quiero ir a Lumopolis.",
  ui_story_4_1_17_dialog_content = "Sé que esto quizá sea arriesgado, Vice, pero...",
  ui_story_4_1_18_dialog_content = "Esta es la única pista que tengo para averiguar qué pasó hace 17 años.",
  ui_story_4_1_19_dialog_content = "Bien, pero primero debo consultarlo con la Comandante Hiiro. Esto será más difícil de lo que crees.",
  ui_story_4_1_20_dialog_content = "Veo que no te has olvidado de tu oficial superior.",
  ui_story_4_1_21_dialog_content = "¡Ups! ¿Todavía estás aquí, comandante?",
  ui_story_4_1_22_dialog_content = "He estado aquí todo el tiempo, teniente Vice. PlayerName, lamento oír hablar de Celestita, pero tenemos que acercarnos a la información sobre Lumopolis con precaución.",
  ui_story_4_1_23_dialog_content = "Con precaución... ¿significa?",
  ui_story_4_1_24_dialog_content = "Sin una investigación exhaustiva, no podemos tomar las palabras de Mendelson al pie de la letra. Además, ya nos hemos encontrado con varios Eclipsites de alto nivel, así que sería mejor no actuar precipitadamente.",
  ui_story_4_1_25_dialog_content = "¡Pero no tenemos tiempo! Si pasa algo... ¡Soroz nos protegerá!",
  ui_story_4_1_26_dialog_content = "Con el debido respeto, PlayerName...",
  ui_story_4_1_27_dialog_content = "Me di cuenta de tu Colossus desde el principio y recibí toda la información necesaria de Charon.",
  ui_story_4_1_A1_dialog_content = "De acuerdo con el sistema de clasificación Colossus que usamos en ese entonces...",
  ui_story_4_1_28_dialog_content = "Soroz es un Colossus de <color=#FFB400>Nivel 6</color>.",
  ui_story_4_1_29_dialog_content = "...",
  ui_story_4_1_30_dialog_content = "¿Tan alto? Eso es Soroz, bien.",
  ui_story_4_1_31_dialog_content = "No, el nivel 1 es el nivel más alto. Cuanto mayor sea el número, menor será el nivel y peor será el rendimiento.",
  ui_story_4_1_32_dialog_content = "¿...?",
  ui_story_4_1_33_dialog_content = "Entonces, ¿cuál es el nivel más bajo?",
  ui_story_4_1_34_dialog_content = "<color=#FFB400>6</color>.",
  ui_story_4_1_35_dialog_content = "¡¿...?!",
  ui_story_4_1_36_dialog_content = "¡¿No dijiste ser un Colossus clase Sky, Soroz?!",
  ui_story_4_1_37_dialog_content = "Eso fue para darte las ganas de vivir. Fue una mentira necesaria.",
  ui_story_4_1_A2_dialog_content = "Además, no existe una \"clase Sky\".",
  ui_story_4_1_38_dialog_content = "¿Me mentiste y lo admites tan fácilmente?",
  ui_story_4_1_39_dialog_content = "Los Colossus de nivel 6 solo están equipados con funciones de soporte vital y transporte.",
  ui_story_4_1_40_dialog_content = "Y especializados en huir.",
  ui_story_4_1_41_dialog_content = "Puedes parar ahora...",
  ui_story_4_1_42_dialog_content = "PlayerName parece deprimido.",
  ui_story_4_1_43_dialog_content = "Supongo que dije demasiado. No te sientas mal, PlayerName.",
  ui_story_4_1_44_dialog_content = "Tienes un \"don\" único como Celestita, así como un destacado liderazgo de combate. Eso nunca lo dudé.",
  ui_story_4_1_45_dialog_content = "Y dado que la teniente Vice ha respondido por ti, debes ser confiable.",
  ui_story_4_1_46_dialog_content = "¿Ah?",
  ui_story_4_1_47_dialog_content = "Gracias. Trabajaré duro.",
  ui_story_4_1_48_dialog_content = "¡Entonces vámonos a Lumopolis! ¡Tenemos que darnos prisa si queremos vencer a Schummer!",
  ui_story_4_1_49_dialog_content = "¡Bien! ¿Puede darnos la autorización para entrar en Lumopolis, comandante?",
  ui_story_4_1_50_dialog_content = "No. Ese es tu problema.",
  ui_story_4_1_51_dialog_content = "¡¿Eh?!",
  ui_story_4_1_52_dialog_content = "Lo siento, pero sin ninguna información verificada, la Federación Illumina no puede tomar ninguna acción oficial, y mucho menos con Lumopolis.",
  ui_story_4_1_54_dialog_content = "...",
  ui_story_4_1_55_dialog_content = "¿No estudiaste en Lumopolis? Es hora de reunirse con tus antiguos compañeros.",
  ui_story_4_1_56_dialog_content = "¿No eras compañera de clase con <color=#FFB400>Carleen</color>, capitán de los Guardianes de Lumopolis?",
  ui_story_4_1_57_dialog_content = "Es por eso que este es un problema aún mayor. Ugh...",
  ui_story_4_1_58_dialog_content = "<color=#e8d9bb>Por encima de Lumopolis</color>",
  ui_story_4_1_59_dialog_content = "¿Es esa <color=#FFB400>ciudad flotante</color> a la que vamos?",
  ui_story_4_1_60_dialog_content = "Parece que llegamos. El viaje es bastante rápido con un Colossus...",
  ui_story_4_1_X1_dialog_content = "Vice, tu traje...",
  ui_story_4_1_X2_dialog_content = "¡Es solo un disfraz! Envié una carta a Carleen explicando nuestra situación, pero aún así deberías evitar llamar la atención...",
  ui_story_4_1_X3_dialog_content = "Uh, esto probablemente atraerá aún más la atención hacia ti.",
  ui_story_4_1_61_dialog_content = "¡Mira, PlayerName!",
  ui_story_4_1_62_dialog_content = "Eso es Lumopolis.",
  ui_story_4_1_64_option_content = "¿Es esa la última ciudad Aurorian?",
  ui_story_4_1_65_option_content = "¿Cómo está flotando en el aire?",
  ui_story_4_1_66_dialog_content = "Deja de murmurarte a ti mismo y ven aquí. ¡Quiero dejar una cosa clara antes de que comencemos esta misión!",
  ui_story_4_1_67_dialog_content = "No importa lo que pase, déjame hablar a mí. ¿Entiendes?",
  ui_story_4_1_68_dialog_content = "¡No te apresures y no olvides que debemos llegar al objetivo antes que Schummer!",
  ui_story_4_1_69_dialog_content = "Entendido, teniente Vice. Eres tan confiable.",
  ui_story_4_1_70_dialog_content = "Bueno, déjame revisar mi pase de nuevo... Realmente no quiero tratar con ella.",
  ui_story_4_1_71_dialog_content = "Estoy un poco nervioso, PlayerName. ¿Es realmente seguro para mí quedarme aquí solo?",
  ui_story_4_1_72_dialog_content = "No hay otra forma, Soroz. Sabes cómo te destacas.",
  ui_story_4_1_73_dialog_content = "Si te llevamos con nosotros, es posible que ni siquiera lleguemos a los suburbios, y mucho menos a Lumopolis.",
  ui_story_4_1_74_dialog_content = "¿Y no eres un Colossus de nivel 6? ¿No es como si pudieras brindar apoyo en combate?",
  ui_story_4_1_75_dialog_content = "Todavía estoy molesto por eso, ya veo.",
  ui_story_4_1_76_dialog_content = "Sí. Estás en lo correcto. Entonces te dejaré toda la pelea.",
  ui_story_4_1_A3_dialog_content = "Te estaré esperando en un espacio aéreo oculto. Por favor ten cuidado.",
  ui_story_4_1_77_dialog_content = "Muy bien, vamos. La cola para entrar en la ciudad ya es muy larga.",
  ui_story_4_1_A4_dialog_content = "Buu, odio esperar en la fila...",
  ui_story_4_1_78_dialog_content = "No quiero ver a esa persona en absoluto... Pero, por supuesto, <color=#FFB400>Carleen de Schwartz</color> solo tiene que ser la Capitán de los Guardianes de Lumopolis.",
  ui_story_4_1_79_dialog_content = "¿Qué le pasa a esta capitana?",
  ui_story_4_1_80_dialog_content = "Sólo espera y mira. Probablemente nos esté esperando en la puerta mientras hablamos.",
  ui_story_4_1_81_dialog_content = "¿Dónde está la Capitana que mencionaste, Vice?",
  ui_story_4_1_82_dialog_content = "¡Silencio!",
  ui_story_4_1_83_dialog_content = "¡Sigue las órdenes y coopera cuando te inspeccionen!",
  ui_story_4_1_84_dialog_content = "Los visitantes con pases temporales no pueden quedarse por más de 24 horas, ¡o serás deportado!",
  ui_story_4_1_85_dialog_content = "¡Reporte de inmediato cualquier persona sospechosa a un Guardia Lumo!",
  ui_story_4_1_86_dialog_content = "Lo reiteraré, PlayerName. No importa lo que pase, no...",
  ui_story_4_1_87_dialog_content = "¡No susurres y muestra tus pases!",
  ui_story_4_1_88_dialog_content = "Entiendo...",
  ui_story_4_1_89_dialog_content = "Otro de Illumina... ¿No pasa nada en el frente? No llevas el atuendo adecuado, niña.",
  ui_story_4_1_90_dialog_content = "Err, estoy aquí por asuntos personales.",
  ui_story_4_1_91_dialog_content = "¿Primera vez en Lumopolis? ¿Por qué miras a tu alrededor así?",
  ui_story_4_1_92_dialog_content = "No, fui a la escuela aquí. Vuelvo esta vez con un Pase Clase A renovado...",
  ui_story_4_1_93_dialog_content = "¿Qué pasa con el que parece sospechoso a tu lado?",
  ui_story_4_1_94_option_content = "¿Yo? Soy nuevo en este mundo.",
  ui_story_4_1_95_option_content = "(Vice me dijo que no hablara...)",
  ui_story_4_1_96_dialog_content = "¿Crees que estoy bromeando? ¿Dónde está tu pase? Una persona, un pase. ¡Está en el letrero!",
  ui_story_4_1_97_dialog_content = "¿Eres sordo? ¡Te hice una pregunta!",
  ui_story_4_1_98_dialog_content = "Lo siento, está conmigo. Mi solicitud ha sido aprobada especialmente. ¡Compruébalo de nuevo!",
  ui_story_4_1_99_dialog_content = "Es la Capitana Carleen quien...",
  ui_story_4_1_100_dialog_content = "¿La Capitana? ¡Oh, entonces eres tú!",
  ui_story_4_1_101_dialog_content = "¿Por qué no lo dijiste antes? Está bien, espera aquí.",
  ui_story_4_1_102_dialog_content = "Uff.",
  ui_story_4_1_103_dialog_content = "Pareces relajado. ¿Illumina no te pone a trabajar?",
  ui_story_4_1_104_dialog_content = "Ja, <color=#FFB400>Carleen</color>, ha pasado un tiempo. Eres tan... impresionante como siempre.",
  ui_story_4_1_105_dialog_content = "Se necesita valor para llamar a la Capitana por su nombre.",
  ui_story_4_1_106_dialog_content = "Esta extraña dama parece familiar...",
  ui_story_4_1_107_dialog_content = "¡Ah, debes ser la compañera de clase de Carleen!",
  ui_story_4_1_108_dialog_content = "Silencio, Raphaela. La Capitana puede encargarse de esto ella misma.",
  ui_story_4_1_109_dialog_content = "Podrías aprender de Michele. Sabe cuándo mantener la boca cerrada.",
  ui_story_4_1_110_dialog_content = "...",
  ui_story_4_1_111_dialog_content = "Calla.",
  ui_story_4_1_112_dialog_content = "No es necesario tener tanta gente aquí. Guardianes, reanuden sus deberes habituales de patrulla.",
  ui_story_4_1_113_dialog_content = "Déjame estos dos visitantes.",
  ui_story_4_1_114_dialog_content = "Creo que no es necesario que me presente.",
  ui_story_4_1_115_dialog_content = "Iré directo al grano, Carleen. Estamos aquí para...",
  ui_story_4_1_116_dialog_content = "Leí tu carta. Sigues igual que siempre, tu gramática es pobre y tu escritura formal es un desastre.",
  ui_story_4_1_117_dialog_content = "Estabas tratando de decirme que <color=#FFB400>Eclipsites tienen sus ojos puestos en Lumopolis</color>, ¿verdad?",
  ui_story_4_1_118_dialog_content = "¿Es este el momento de criticar mi estilo de escritura?",
  ui_story_4_1_A5_dialog_content = "Tenemos noticias de que alguien llamado Schummer está tramando contra Lumopolis.",
  ui_story_4_1_119_dialog_content = "Creemos que está intentando robar el <color=#FFB400>Módulo Think Tank</color> de Lumopolis.",
  ui_story_4_1_120_dialog_content = "¿El Módulo Think Tank? Lo siento, nunca he oído hablar de eso. Sin embargo, sea lo que sea, no creo que nadie pueda quitárselo a Lumopolis.",
  ui_story_4_1_122_dialog_content = "¿Hmm? ¿Quién eres?",
  ui_story_4_1_123_dialog_content = "¿Puedo contestar eso?",
  ui_story_4_1_124_dialog_content = "¿Crees que puede oírnos si susurramos?",
  ui_story_4_1_125_dialog_content = "...",
  ui_story_4_1_126_dialog_content = "PlayerName es... Carleen, ¿puedes acercarte? Eres el único que puede saber...",
  ui_story_4_1_127_dialog_content = "¿Estás hablando de... esas personas egoístas que prefieren estar en el lado seguro? ¿Qué pasa con el llamado Colossus?",
  ui_story_4_1_128_dialog_content = "El Colossus se llama Soroz... Soroz vuela sobre Lumopolis y es indetectable.",
  ui_story_4_1_129_dialog_content = "¡...!",
  ui_story_4_1_130_dialog_content = "Está bien, es solo un Colossus de nivel 6... no puede pelear, y se usa principalmente para huir.",
  ui_story_4_1_131_dialog_content = "Patético.",
  ui_story_4_1_132_dialog_content = "Pero eso no es importante, Carleen. Ya te dije quién es PlayerName, ¡así que puedes confiar en nosotros!",
  ui_story_4_1_133_dialog_content = "¿Tiene alguna otra evidencia para respaldar su caso?",
  ui_story_4_1_134_dialog_content = "No. Pero los Eclipsites definitivamente están tratando de ingresar a Lumopolis. ¡Incluso podrían estar entre la multitud haciendo cola en este momento!",
  ui_story_4_1_137_dialog_content = "¡Capitán! ¡Hay una emergencia!",
  ui_story_4_1_139_dialog_content = "¡¿En serio?!",
  ui_story_4_1_140_dialog_content = "¿De qué están hablando?",
  ui_story_4_1_141_dialog_content = "No lo sé, pero supongo que no son buenas noticias...",
  ui_story_4_1_142_dialog_content = "Teniente Vice, dado que éramos compañeras de clase, te creeré esta vez y te dejaré entrar a la ciudad.",
  ui_story_4_1_143_dialog_content = "Pero estarás bajo mi vigilancia todo el tiempo. ¡Si mientes, serás castigada por la ley!",
  ui_story_4_1_144_dialog_content = "¡Claro, no hay problema! Empecemos con...",
  ui_story_4_1_145_dialog_content = "Empecemos por <color=#FFB400>Baja Lumopolis</color>.",
  ui_story_4_1_146_dialog_content = "¿Baja Lumopolis?",
  ui_story_4_1_147_dialog_content = "Sí... Una <color=#FFB400>incursión</color> ocurrió hace un momento en Baja Lumopolis.",
  ui_story_4_1_148_dialog_content = "¡¿?!",
  ui_story_4_2_1_dialog_content = "<color=#e8d9bb>Baja Lumopolis</color>",
  ui_story_4_2_2_dialog_content = "No hay tiempo que perder. Toma un atajo de regreso...",
  ui_story_4_2_3_dialog_content = "¿Hm? Quién está ahí... ¡Arrgh!",
  ui_story_4_2_4_dialog_content = "Tan ruidoso.",
  ui_story_4_2_5_dialog_content = "Lo siento, lo siento. Mi error.",
  ui_story_4_2_6_dialog_content = "¿Muerto?",
  ui_story_4_2_A1_dialog_content = "Sí, pan comido.",
  ui_story_4_2_7_dialog_content = "Espero que no me tomes en cuenta esto. Pobrecito, estabas en el lugar equivocado en el momento equivocado.",
  ui_story_4_2_8_dialog_content = "La suerte también es una habilidad de supervivencia importante.",
  ui_story_4_2_9_dialog_content = "Realmente te gusta escupirles tonterías, no es así, Gertzurde.",
  ui_story_4_2_A2_dialog_content = "No nos hemos visto en mucho tiempo, ¡pero ya le has dicho más a ese tipo que a mí!",
  ui_story_4_2_10_dialog_content = "Siempre estás en mi corazón y en mi mente. Pienso en ti cada segundo, Shelt.",
  ui_story_4_2_11_dialog_content = "Tú, hablador sutil... Vamos a ir al grano. Tengo noticias de la Dama, deberíamos empezar pronto.",
  ui_story_4_2_12_dialog_content = "¿Ahora?",
  ui_story_4_2_13_dialog_content = "Sí. Te expondré los detalles del plan poco a poco.",
  ui_story_4_2_14_dialog_content = "He enviado algunos peones como cebo, para que los guardianes se acerquen al vecindario. Entonces tendrás una oportunidad...",
  ui_story_4_2_15_dialog_content = "Espera, ¿así que ya lo has decidido, Shelt? No tienes que correr un riesgo tan grande. Solo espérame.",
  ui_story_4_2_16_dialog_content = "Basta, Gertzurde, haz lo que te digo.",
  ui_story_4_2_17_dialog_content = "Mantendré alejados a los guardianes, y tú... Vas <color=#FFB400>a robar el artículo</color>.",
  ui_story_4_2_18_dialog_content = "Ya he confirmado la ubicación del artículo... Pero, ¿es realmente así de simple?",
  ui_story_4_2_19_dialog_content = "Sí, es así de simple. No obtendremos nuestra libertad hasta que nuestro plan tenga éxito. ¿Recuerdas?",
  ui_story_4_2_20_dialog_content = "Ok. Siempre eres tan persuasivo.",
  ui_story_4_2_21_dialog_content = "¡Capitán! ¡Algunos residentes han informado que fueron atacados por Eclipsites!",
  ui_story_4_2_22_dialog_content = "¿No es el mismo lugar? ¿Quizás es un esfuerzo de grupo?",
  ui_story_4_2_23_dialog_content = "¡Carleen! ¡Estamos aquí!",
  ui_story_4_2_24_dialog_content = "...",
  ui_story_4_2_25_dialog_content = "Parece que tenemos más de un grupo de enemigos.",
  ui_story_4_2_26_dialog_content = "¡Entendido! ¿Qué hay de los otros Guardianes?",
  ui_story_4_2_27_dialog_content = "Se quedaron en Zona residencial para proteger a los nobles. La orden de ese hombre, después de todo.",
  ui_story_4_2_28_dialog_content = "¿El <color=#FFB400>Señor de la ciudad</color>...?",
  ui_story_4_2_29_dialog_content = "Todos los ataques reportados están en el lado este, por lo que los supervisores en Baja Lumopolis se dirigen hacia allí.",
  ui_story_4_2_30_dialog_content = "Tengo la extraña sensación de que debería ir a la zona oeste...",
  ui_story_4_2_31_dialog_content = "Es esa mirada de nuevo. La mirada de \"Debo hacer cualquier gran cosa que se me ocurra en este momento\"...",
  ui_story_4_2_32_dialog_content = "¿Te dio esa misma mirada cuando estabas en la escuela?",
  ui_story_4_2_33_dialog_content = "Oh sí. Como cuando estábamos en clase de combate y ella estaba a punto de derribarme.",
  ui_story_4_2_34_dialog_content = "Supongo que Carleen es bastante impresionante.",
  ui_story_4_2_35_dialog_content = "No necesito halagos. Vayamos a la zona oeste. ¿Puedes pelear, PlayerName?",
  ui_story_4_2_36_dialog_content = "No puedo pelear, pero puedo coordinar y guiar.",
  ui_story_4_2_37_dialog_content = "Eso no sonó convincente viniendo de ti.",
  ui_story_4_2_38_dialog_content = "Pero estoy dispuesta a darte la oportunidad de demostrar tu valía.",
  ui_story_4_2_39_dialog_content = "Sintiendo la presión...",
  ui_story_4_3_1_dialog_content = "Sorprendentemente, tienes la habilidad de liderar.",
  ui_story_4_3_2_dialog_content = "¿Y ese es el Sendero de Luz? No puedo creer que la gente con tanto talento haya sido eliminada antes de que yo naciera.",
  ui_story_4_3_3_dialog_content = "Estás revelando tu edad, Carleen.",
  ui_story_4_3_4_dialog_content = "No te adelantes. También se observaron Eclipsites en el oeste. Debemos permanecer vigilantes.",
  ui_story_4_3_5_dialog_content = "Hay más Eclipsites de los que pensábamos...",
  ui_story_4_3_6_option_content = "Pero pensé que Lumopolis nunca podría caer, ¿verdad?",
  ui_story_4_3_7_option_content = "¿Los guardianes del portal no pudieron ocuparse de los Eclipsites?",
  ui_story_4_3_8_dialog_content = "El dicho solo es cierto para Zona residencial, no para Baja Lumopolis.",
  ui_story_4_3_9_dialog_content = "Los guardianes son útiles, por supuesto, pero la mayoría de ellos trabajan para proteger Zona residencial, no Baja Lumopolis.",
  ui_story_4_3_10_dialog_content = "Estamos en Baja Lumopolis, donde todos están solos, ¿verdad, Carleen?",
  ui_story_4_3_F1_dialog_content = "...",
  ui_story_4_3_11_dialog_content = "¿Baja Lumopolis y Zona residencial son realmente tratados de manera diferente?",
  ui_story_4_3_12_dialog_content = "No hay mucho que podamos hacer. Esto es Lumopolis...",
  ui_story_4_3_13_dialog_content = "Perdón por llegar tarde... Líder de escuadrón Gertzurde reportándose.",
  ui_story_4_3_14_dialog_content = "¿Detectas algo inusual?",
  ui_story_4_3_15_dialog_content = "No, Capitán.",
  ui_story_4_3_16_dialog_content = "Reúne a todos para evacuar a los civiles. ¡Además, sella todas las puertas de Baja Lumopolis!",
  ui_story_4_3_17_dialog_content = "Eso ya se hizo, Capitán.",
  ui_story_4_3_18_dialog_content = "¡Eso fue rápido! Siguiente, necesito que te unas a nosotros—",
  ui_story_4_3_19_dialog_content = "Perdona mi franqueza, pero muchos civiles están excluidos de la ciudad y hay que dejarlos entrar.",
  ui_story_4_3_20_dialog_content = "O caerán presa de los Eclipsites.",
  ui_story_4_3_21_dialog_content = "Está bien. ¡Haz eso, pero déjame algunos soldados!",
  ui_story_4_3_22_dialog_content = "Disculpa que me vaya primero, Capitán. Noche Blanca en lo alto.",
  ui_story_4_3_23_dialog_content = "Carleen, ¿eso fue...?",
  ui_story_4_3_24_dialog_content = "Uno de los líderes de escuadrón en la Baja Lumopolis. Está a cargo de muchas defensas y siempre ha sido muy eficiente.",
  ui_story_4_3_25_dialog_content = "Después de todo, solía ser un <color=#FFB400>famoso caballero</color>.",
  ui_story_4_3_26_dialog_content = "Supongo que no puedes juzgar un libro por su portada...",
  ui_story_4_3_27_dialog_content = "Bien, sigamos moviéndonos. Muchos Eclipsites se han escapado de las grietas, causando estragos en todo Baja Lumopolis.",
  ui_story_4_3_28_dialog_content = "También quiero conocer al esquivo <color=#FFB400>Schummer</color>.",
  ui_story_4_6_1_dialog_content = "¡Capitán! ¡La zona este ha sido despejada!",
  ui_story_4_6_2_dialog_content = "¡Capitán, noticias del oeste sobre posible encuentro de Eclipsite de alto nivel!",
  ui_story_4_6_3_dialog_content = "¡Lo sabía! ¡¡Dime donde esta!!",
  ui_story_4_6_4_dialog_content = "¿Todo fue solo una diversión? ¡Los Eclipsites de alto nivel deben ir tras el Módulo Think Tank!",
  ui_story_4_6_5_dialog_content = "No estamos muy atrás, ¿verdad?",
  ui_story_4_6_6_dialog_content = "¡Tenemos a Carleen y su aguda visión de nuestro lado!",
  ui_story_4_6_7_dialog_content = "...",
  ui_story_4_6_8_dialog_content = "Ooh, ella tiene esa mirada otra vez... ¿Por qué? ¿Ocurre algo?",
  ui_story_4_6_9_dialog_content = "No sé... Pero no me gusta este tipo de sensación... En fin, ¡sigamos adelante!",
  ui_story_4_6_10_dialog_content = "¡Shelt! ¡Debemos abandonar el plan!",
  ui_story_4_6_11_dialog_content = "¿Qué pasa? ¡Pero acabo de atraer esa princesa Carleen de Schwartz hasta aquí!",
  ui_story_4_6_12_dialog_content = "¿Y ahora quieres abortar? No quiero pelear contigo por esto, Gertzurde.",
  ui_story_4_6_13_dialog_content = "Carleen tiene a los mocosos de Illumina con ella, ¡y parece que también están buscando el Módulo Think Tank!",
  ui_story_4_6_14_dialog_content = "Y la puerta del Archivo es difícil de desbloquear. No sé si hay tiempo suficiente para...",
  ui_story_4_6_15_dialog_content = "¡No, no, esos malditos niños no van a arruinar el plan!",
  ui_story_4_6_16_dialog_content = "Absolutamente... absolutamente no puedo permitirlo...",
  ui_story_4_6_17_dialog_content = "¿Qué debemos hacer entonces?",
  ui_story_4_6_18_dialog_content = "¡Te compraré más tiempo!",
  ui_story_4_6_19_dialog_content = "<color=#FFB400>Shire</color>... Ah, sí. Puedo despertar a Shire para que esté conmigo...",
  ui_story_4_6_20_dialog_content = "¡No! No importa lo que estés pensando, Shelt, ¡no puedo dejarte hacerlo!",
  ui_story_4_6_21_dialog_content = "Shire, ¡tu hermana es impredecible! ¡Está loca!",
  ui_story_4_6_22_dialog_content = "¿Loca? Ja... ¿Entonces que soy yo?",
  ui_story_4_6_23_dialog_content = "Fuera de aquí, Gertzurde. Ve a donde se supone que debes estar. No me defraudes.",
  ui_story_4_6_24_dialog_content = "Te estaré esperando en el lugar que acordamos, Shelt...",
  ui_story_4_6_25_dialog_content = "Hiciste un voto de caballero. Y te lo vas a quedar, ¿verdad?",
  ui_story_4_6_26_dialog_content = "Claro, Gertzurde. Cumpliré mi palabra, pase lo que pase...",
  ui_story_4_6_27_dialog_content = "¿Has dormido lo suficiente, Shire? Despierta. Te voy a traer... a jugar.",
  ui_story_4_6_28_dialog_content = "¡Hurra! ¡Jugar!",
  ui_story_4_7_1_dialog_content = "<color=#e8d9bb>Calles de Baja Lumopolis</color>",
  ui_story_4_7_2_dialog_content = "Capitán, encontramos un cuerpo más adelante. Confirmamos que es un guardia encargado de defender Baja Lumopolis.",
  ui_story_4_7_3_dialog_content = "Solo hay una herida, empalada en el corazón.",
  ui_story_4_7_4_dialog_content = "¡Todos los guardias! Empieza la búsqueda. ¡No permitiré que nada dañe a mis ciudadanos!",
  ui_story_4_7_5_dialog_content = "¿\"<color=#FFB400>Mis ciudadanos</color>\"?",
  ui_story_4_7_6_dialog_content = "Carleen se preocupa por la gente.",
  ui_story_4_7_7_dialog_content = "No, ¿me pregunto acerca de \"<color=#FFB400>mis</color>\"?",
  ui_story_4_7_8_dialog_content = "Oh... ¿No lo he mencionado? Carleen es la <color=#FFB400>hija del Señor de Lumopolis</color>.",
  ui_story_4_7_9_dialog_content = "¿¿¿???",
  ui_story_4_7_10_dialog_content = "Lo siento, demasiadas cosas a la vez y me olvidé de decirte...",
  ui_story_4_7_11_dialog_content = "Pero al menos para nuestra situación actual, ella es la Capitana de los Guardianes de Lumopolis.",
  ui_story_4_7_13_dialog_content = "¡Whoa! ¡¿Qué fue eso?!",
  ui_story_4_7_14_dialog_content = "¡Guardias! ¡Dirígete hacia ese sonido a toda velocidad!",
  ui_story_4_7_16_dialog_content = "Esta es la primera vez... Me he mostrado en este estado.",
  ui_story_4_7_17_dialog_content = "¿Explotaron esa residencia civil?",
  ui_story_4_7_18_dialog_content = "Carleen, PlayerName, ¡cuidado! ¡Algo anda mal con esa persona!",
  ui_story_4_7_19_dialog_content = "Eres... ¿Shelt...?",
  ui_story_4_7_20_dialog_content = "¿No es sorprendente, princesa, que nos encontremos como iguales?",
  ui_story_4_7_21_dialog_content = "¿Qué piensas? ¿Me veo mejor que antes?",
  ui_story_4_7_22_dialog_content = "¿Se conocen, Carleen?",
  ui_story_4_7_23_dialog_content = "Sí, hace mucho tiempo. Ella es solo una pobre criatura que ha abandonado su fe.",
  ui_story_4_7_24_dialog_content = "¿Pobre criatura? Huh. Bien... Supongo que lo soy.",
  ui_story_4_7_25_dialog_content = "Pisoteada bajo los pies de las autoridades, no soy más que una criatura en Zona residencial a sus ojos. En verdad lamentable.",
  ui_story_4_7_26_dialog_content = "¡Tu miseria fue causada por tus propias decisiones!",
  ui_story_4_7_27_dialog_content = "Mírate ahora... Apenas puedo encontrar palabras para describir cómo te ves.",
  ui_story_4_7_28_dialog_content = "¿Es mi culpa? Si no hubieras nacido como noble, ¿en quién te hubieras convertido, princesa?",
  ui_story_4_7_29_dialog_content = "Si nacieras en los suburbios como yo... ¿En quién te habrías convertido?",
  ui_story_4_7_30_dialog_content = "...",
  ui_story_4_7_31_dialog_content = "¿Sin palabras? Qué arrogante de tu parte acusar mi miseria por mis propias acciones, princesa.",
  ui_story_4_7_32_dialog_content = "¿Aún recuerdas lo que te dije la última vez, Shelt?",
  ui_story_4_7_33_dialog_content = "He jurado en nombre de la Noche Blanca de que si alguna vez volvías a poner un pie aquí, ¡me ocuparía de que se hiciera justicia!",
  ui_story_4_7_34_dialog_content = "Hoy voy a cumplir el juramento que hice ese día.",
  ui_story_4_7_35_dialog_content = "De hecho, nunca me fui. He estado bajo tus narices todo el tiempo, escondida en un rincón oscuro...",
  ui_story_4_7_36_dialog_content = "¿Estás sorprendida? No solo eso, también he hecho muchos amigos.",
  ui_story_4_7_37_dialog_content = "¡¿Qué...?!",
  ui_story_4_7_38_dialog_content = "Ven a mí, mi hermana, mi querida Shire...",
  ui_story_4_7_39_dialog_content = "Hermana... Shire quiere...",
  ui_story_4_7_40_dialog_content = "¿Quieres jugar? Cómo puedo decirte que no, mi amada hermana.",
  ui_story_4_7_41_dialog_content = "¡Ven, juguemos con esta adorable princesa!",
  ui_story_4_7_42_dialog_content = "¡Jugar—!",
  ui_story_4_7_43_dialog_content = "¡Cuidado!",
  ui_story_4_7_44_dialog_content = "¡Maldita sea! ¿Por qué? ¿Por qué? ¡Tú...!",
  ui_story_4_7_45_dialog_content = "¡¿Quién eres?! ¡¿Por qué puedes coordinarlos?!",
  ui_story_4_7_46_dialog_content = "¡¿Eres... un Celestita?!",
  ui_story_4_7_47_dialog_content = "...",
  ui_story_4_7_48_dialog_content = "No es divertido... ¡¡No es divertido!! Vamos, hermana...",
  ui_story_4_7_49_dialog_content = "No, necesita más tiempo. No podemos... ¡No podemos simplemente dejarlos ir!",
  ui_story_4_7_50_dialog_content = "Si tú y tus lacayos de Lumopolis son tan valientes, ¡¡intenten alcanzarnos!!",
  ui_story_4_7_51_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_4_7_53_dialog_content = "*Tos, tos* ¡Maldita sea, <color=#FFB400>se han ido</color>!",
  ui_story_4_7_54_dialog_content = "¡Se dirigen hacia Zona residencial!",
  ui_story_4_7_55_dialog_content = "¡Suena la alarma! ¡Notifica a los Guardias! ¡Regresa a Zona residencial, ahora!",
  ui_story_4_7_56_dialog_content = "¡PlayerName! ¡Date prisa! ¡Debemos alcanzarla!",
  ui_story_4_8_1_dialog_content = "<color=#e8d9bb>El archivo de Lumopolis lejos de Zona residencial...</color>",
  ui_story_4_8_2_dialog_content = "Gira a la izquierda... 3 grados... Gira a la derecha... 14 grados... Luego...",
  ui_story_4_8_3_dialog_content = "Atascado de nuevo... ¡¿Qué tipo de encriptación es esta?! Fue un error no haber dejado una puerta trasera la última vez...",
  ui_story_4_8_4_dialog_content = "¡Debería explotarlo! No, no puedo arriesgarme a dañar el módulo.",
  ui_story_4_8_5_dialog_content = "¿Es necesario un candado como este para un archivo?",
  ui_story_4_8_6_dialog_content = "Gertzurde.",
  ui_story_4_8_7_dialog_content = "Lo siento, Shelt, necesito más tiempo. La puerta del archivo...",
  ui_story_4_8_8_dialog_content = "Espera, ¿estás peleando?",
  ui_story_4_8_9_dialog_content = "No... Lo siento, yo... Estoy huyendo.",
  ui_story_4_8_10_dialog_content = "¡Un Celestita, Gertzurde! Tienen un Celestita de su lado.",
  ui_story_4_8_11_dialog_content = "¿Luchaste contra Carleen? ¡¿Estás herida?!",
  ui_story_4_8_12_dialog_content = "Escúchame. Los llevaré al sur de Zona residencial, lejos de donde estás...",
  ui_story_4_8_A1_dialog_content = "Así que tendrás mucho tiempo para...",
  ui_story_4_8_13_dialog_content = "¡No! ¡Si corres a Zona residencial, estás casi muerto!",
  ui_story_4_8_14_dialog_content = "No olvides que estamos haciendo todo esto por...",
  ui_story_4_8_15_dialog_content = "<color=#FFB400>La Dama</color> nos ayudará. Ella lo prometió...",
  ui_story_4_8_16_dialog_content = "La fe es poder, Gertzurde. ¡Tomamos una decisión y debemos llevarla a cabo!",
  ui_story_4_8_17_dialog_content = "Nos vemos fuera de Lumopolis, querida.",
  ui_story_4_8_18_dialog_content = "¡¡Shelt!!",
  ui_story_4_8_19_dialog_content = "¡Espera! Espérame. Vas demasiado rápido...",
  ui_story_4_8_20_dialog_content = "¿Quién era esa chico llamada Shire, Carleen? ¿Ambas eran Aurorians?",
  ui_story_4_8_21_dialog_content = "Sí, aunque no quiero admitirlo. Son traidoras de Lumopolis.",
  ui_story_4_8_22_dialog_content = "PlayerName, tu comando hace un momento fue impecable. Pensé que te encogerías al ver Eclipsites de alto nivel.",
  ui_story_4_8_23_dialog_content = "Eres un Celestita completamente diferente de lo que imaginaba.",
  ui_story_4_8_24_option_content = "Es mi deber.",
  ui_story_4_8_25_option_content = "No, soy como cualquier otro Celestita.",
  ui_story_4_8_26_dialog_content = "¿No está siempre luchando también como Capitán de los Guardianes, señorita Carleen?",
  ui_story_4_8_A2_dialog_content = "No nos gusta pelear, ni tenemos la capacidad de hacerlo.",
  ui_story_4_8_27_dialog_content = "Simplemente no queremos que ganen los Eclipsites.",
  ui_story_4_8_28_dialog_content = "Te creo. Mi gente una vez luchó con esa misma actitud.",
  ui_story_4_8_29_dialog_content = "¿No tienes miedo de luchar cuando eres incapaz de luchar?",
  ui_story_4_8_31_dialog_content = "Sé que mi gente una vez luchó contra los Eclipsites con todas sus fuerzas y de hecho jugó un papel clave.",
  ui_story_4_8_32_dialog_content = "No soy diferente a ninguno de ellos.",
  ui_story_4_8_33_dialog_content = "Tus habilidades son muy impresionantes.",
  ui_story_4_8_34_dialog_content = "Mis habilidades... Probablemente por eso nos tendieron una emboscada.",
  ui_story_4_8_35_dialog_content = "¿No te sientes impotente?",
  ui_story_4_8_36_dialog_content = "No, porque tengo mi propio propósito que cumplir.",
  ui_story_4_8_37_dialog_content = "¿Y estás dispuesto a arriesgarte por ese supuesto propósito?",
  ui_story_4_8_F1_dialog_content = "Sí, porque no es sólo mi lucha.",
  ui_story_4_8_38_dialog_content = "Interesante. Tienes un compañero intrigante aquí, Vice.",
  ui_story_4_8_39_dialog_content = "Ponte en la línea para <color=#FFB400>luchar por los demás</color>... ¿verdad?",
  ui_story_4_8_40_dialog_content = "...",
  ui_story_4_8_41_dialog_content = "¡...!",
  ui_story_4_8_46_dialog_content = "¿Dónde estás, Raphaela?",
  ui_story_4_8_47_dialog_content = "¡Aquí!",
  ui_story_4_8_48_dialog_content = "No te dirijas hacia Zona residencial con nosotros. Necesito que... vayas en la dirección opuesta.",
  ui_story_4_8_49_dialog_content = "¡¿Qué?! ¿Por qué?",
  ui_story_4_8_50_dialog_content = "¿No crees que sería un suicidio ir hacia Zona residencial?",
  ui_story_4_8_51_dialog_content = "Tal vez no planean escapar en absoluto... Sino...",
  ui_story_4_8_52_dialog_content = "¿Para desviar nuestra atención?",
  ui_story_4_8_53_dialog_content = "Sí, aunque no tenemos más remedio que perseguirlos ahora mismo.",
  ui_story_4_8_54_dialog_content = "Entonces, me gustaría que Raphaela se dirigiera hacia la dirección opuesta. Mi corazonada me dice que alguien está en algún lugar allá atrás...",
  ui_story_4_8_55_dialog_content = "¡Ya veo! ¡Ahora lo entiendo! ¡Busco gente sospechosa! ¡Partiendo ahora!",
  ui_story_4_8_56_dialog_content = "Eres entusiasta, Carleen. Nada pasa desapercibido.",
  ui_story_4_8_57_dialog_content = "Al contrario, hay muchas cosas que todavía no veo con claridad. El punto de vista de todos es complicado.",
  ui_story_4_8_58_dialog_content = "Bueno, concéntrate. Hay algunos gusanos nuevos arrastrándose por la calle. Vamos a limpiarlos.",
  ui_story_4_12_1_dialog_content = "...",
  ui_story_4_12_2_dialog_content = "...",
  ui_story_4_12_3_dialog_content = "Eh... Entonces, ¿por qué estás aquí, líder de escuadrón?",
  ui_story_4_12_4_dialog_content = "Ya te lo dije dos veces, estoy aquí para acompañar al personal del Archivo. Pregúntales si no me crees.",
  ui_story_4_12_5_dialog_content = "¿Pero le dijiste al capitán que ibas a llevar a los ciudadanos desde afuera?",
  ui_story_4_12_6_dialog_content = "Y ellos son el personal de Archivo, y ahora han vuelto.",
  ui_story_4_12_7_dialog_content = "Oye, ¿qué es eso en tu mano? ¿Por qué está tapado?",
  ui_story_4_12_8_dialog_content = "Oh, ¿esto? Empaqué algunos archivos que dejé aquí la semana pasada.",
  ui_story_4_12_9_dialog_content = "Es, eh, el informe forense de los civiles asesinados por Eclipsites durante los últimos seis meses.",
  ui_story_4_12_10_dialog_content = "Err...",
  ui_story_4_12_11_dialog_content = "Los necesitamos como referencias para posibles medidas de seguridad. Hay principalmente fotos, bocetos de autopsias, cosas así.",
  ui_story_4_12_12_dialog_content = "¿Quieres echar un vistazo...?",
  ui_story_4_12_13_dialog_content = "...",
  ui_story_4_12_14_dialog_content = "...",
  ui_story_4_12_15_dialog_content = "Ah, ja, ja, no gracias.",
  ui_story_4_12_16_dialog_content = "Está bien. Las cosas se han descontrolado mucho, así que si te ordenaron que revises las cosas...",
  ui_story_4_12_17_dialog_content = "Oh ,¡jaja! No hay necesidad. ¡Me despediré y patrullaré por allí!",
  ui_story_4_12_18_dialog_content = "...",
  ui_story_4_13_1_dialog_content = "¡Capitán! ¡Las manchas de sangre se extienden hasta este lado, hasta el interior de esta puerta!",
  ui_story_4_13_2_dialog_content = "El espacio entre las gotas de sangre se ha vuelto más estrecho... Se han frenado. ¡Nos estamos acercando!",
  ui_story_4_13_3_dialog_content = "¡Apúrate! ¡Pueden estar un poco más adelante!",
  ui_story_4_13_4_dialog_content = "Vaya, hemos estado corriendo durante tanto tiempo, casi estamos en Zona residencial...",
  ui_story_4_13_5_dialog_content = "Supongo que saben que no pueden llegar a Zona Residencial, así que el plan es hacer un alto aquí.",
  ui_story_4_13_6_dialog_content = "Vamos. Esto siempre termina de la misma manera: ¡todos los traidores enfrentan el mismo destino!",
  ui_story_4_13_7_dialog_content = "Hermana... Tengo sueño...",
  ui_story_4_13_8_dialog_content = "No puedes dormir ahora, Shire... Lo siento, sé que estas cansada...",
  ui_story_4_13_9_dialog_content = "¿Han llegado ya aquí...? Son rápidos, como se esperaba de Carleen...",
  ui_story_4_13_10_dialog_content = "Es hora de cumplir su promesa, mi Señora...",
  ui_story_4_13_11_dialog_content = "Hola, Shelt.",
  ui_story_4_13_12_dialog_content = "¡Mi señora...! Estamos en una situación desesperada... Los enemigos, ¡tienen un Celestita de su lado!",
  ui_story_4_13_13_dialog_content = "Parece que la batalla es inevitable.",
  ui_story_4_13_14_dialog_content = "¡Necesitamos tu ayuda...! ¡Gertzurde necesita más tiempo...!",
  ui_story_4_13_15_dialog_content = "¡Danos el poder de derrotar a los enemigos! Por favor... ¡danos la esperanza de vivir!",
  ui_story_4_13_16_dialog_content = "Esas son dos solicitudes distintas, Shelt.",
  ui_story_4_13_17_dialog_content = "¡...!",
  ui_story_4_13_18_dialog_content = "¿Quieres derrotar a tus enemigos o quieres sobrevivir?",
  ui_story_4_14_1_dialog_content = "Shelt, Shire.",
  ui_story_4_14_3_dialog_content = "Tú... viniste...",
  ui_story_4_14_4_dialog_content = "Hermana...",
  ui_story_4_14_5_dialog_content = "Dime, Shelt, ¿<color=#FFB400>para quién estás haciendo tiempo</color>?",
  ui_story_4_14_6_dialog_content = "...",
  ui_story_4_14_7_dialog_content = "Bueno, supongo que prefieres pelear que hablar.",
  ui_story_4_14_8_dialog_content = "Carleen... ¿De verdad crees que nos tienes acorralados?",
  ui_story_4_14_9_dialog_content = "La dama nos ha concedido un nuevo poder...",
  ui_story_4_14_10_dialog_content = "¿La dama? ¿Podría ser Schummer?",
  ui_story_4_14_11_dialog_content = "Nosotros... ¡Viviremos! ¡Y luego dejaremos la corrupta Lumopolis con la cabeza en alto!",
  ui_story_4_14_13_dialog_content = "¡Nunca ganarás, princesa!",
  ui_story_4_14_14_dialog_content = "¿Hermana...? Mi cuerpo es...",
  ui_story_4_14_15_dialog_content = "<anim type=Shake>¡Arghhhhhhhhhhhh!</anim>",
  ui_story_4_14_17_dialog_content = "¡¿Qué...?! ¡¿Se fusionaron <color=#FFB400>en uno</color>?!",
  ui_story_4_14_18_dialog_content = "Me temo que lo que les diste hace un momento no es un poder ordinario.",
  ui_story_4_14_19_dialog_content = "Ah, sí. Pero es lo que querían, el poder para derrotar a sus enemigos.",
  ui_story_4_14_21_dialog_content = "¡Démosle un nombre a esta creación! ¿Cómo quieres llamarlos?",
  ui_story_4_14_22_dialog_content = "Aburrimiento.",
  ui_story_4_14_23_dialog_content = "<anim type=Shake>¡Argh! ¡Ay, ay! ¡¡Esto no está bien!! Nosotros—</anim>",
  ui_story_4_14_24_dialog_content = "<anim type=Shake>Puedo sentir que nos volvemos más fuertes, hermana, pero... ¡duele... tanto!</anim>",
  ui_story_4_14_25_dialog_content = "<anim type=Shake>¡Mi Señora! ¿¡Qué diablos está pasando!?</anim>",
  ui_story_4_14_26_dialog_content = "Retrocede, PlayerName. Esa cosa no se parece en nada a lo que hemos encontrado antes.",
  ui_story_4_14_27_option_content = "No te asustes. Estoy aquí.",
  ui_story_4_14_28_option_content = "Enfócate. Ganaremos.",
  ui_story_4_14_29_dialog_content = "Apenas puedo contener mi ira.",
  ui_story_4_14_30_dialog_content = "¡¿Qué clase de escoria otorgaría este tipo de poder retorcido?!",
  ui_story_4_14_31_dialog_content = "¡Está bien! ¡Entonces haz lo tuyo, PlayerName!",
  ui_story_4_14_32_dialog_content = "<anim type=Shake>¡Ay, ay! Hermana... Realmente duele...</anim>",
  ui_story_4_14_33_dialog_content = "<anim type=Shake>Mi hermana... Por favor mátanos...</anim>",
  ui_story_4_14_35_dialog_content = "...",
  ui_story_4_14_36_dialog_content = "¿Qué significa eso?",
  ui_story_4_14_A1_dialog_content = "No tengo idea de lo que acaba de pasar, pero eso es de esperar al ponerse del lado de la oscuridad.",
  ui_story_4_14_37_dialog_content = "En nombre de la Noche Blanca, te concedo...",
  ui_story_4_14_38_dialog_content = "<anim type=Shake>Diente de León...</anim>",
  ui_story_4_14_39_dialog_content = "?",
  ui_story_4_14_40_dialog_content = "<anim type=Shake>Me convertiré en un diente de león y volaré...</anim>",
  ui_story_4_14_41_dialog_content = "Ya eres incoherente. En este estado, no estoy segura si serías de mucha utilidad o...",
  ui_story_4_14_42_dialog_content = "<anim type=Shake>Pero yo... He cumplido el plan de Mi Señora...</anim>",
  ui_story_4_14_43_dialog_content = "<anim type=Shake>Esto no es lo que se prometió... Gertzurde me espera—</anim>",
  ui_story_4_14_44_dialog_content = "<anim type=Shake>Señora, mi Señora...</anim>",
  ui_story_4_14_45_dialog_content = "<color=#e8d9bb>¡¡Boom—!!</color>",
  ui_story_4_14_46_dialog_content = "¡¿Otra explosión?!",
  ui_story_4_14_47_dialog_content = "¡Es el <color=#FFB400>Archivo</color>, Capitán! Hubo una explosión... Lo siento...",
  ui_story_4_14_48_dialog_content = "¡Entendido! ¿Pero por qué te disculpas, Raphaela?",
  ui_story_4_14_49_dialog_content = "<anim type=Shake>Tee-hee... Tee-hee... Finalmente gané, Princesa...</anim>",
  ui_story_4_14_50_dialog_content = "<anim type=Shake>Gertzurde, Ger... Mi... Gertzurde... Debes seguir viviendo...</anim>",
  ui_story_4_14_53_dialog_content = "Sé que este es el enemigo, pero todavía no puedo soportar mirar.",
  ui_story_4_14_54_dialog_content = "<color=#e8d9bb>Fuera del archivo</color>",
  ui_story_4_14_55_dialog_content = "Entonces, ¿simplemente pasaste junto al traidor?",
  ui_story_4_14_56_dialog_content = "Lo siento, Carleen... Si tan solo fuera...",
  ui_story_4_14_57_dialog_content = "<color=#FFB400>Busca a Gertzurde en toda la ciudad</color>. Inmediatamente. ¡Ahora!",
  ui_story_4_14_58_dialog_content = "¡Sí, señora!",
  ui_story_4_14_59_dialog_content = "Poner en peligro la seguridad pública, causar estragos en la ciudad... Esto es inaceptable...",
  ui_story_4_14_60_dialog_content = "La persona robó el...",
  ui_story_4_14_61_dialog_content = "¿Módulo Think Tank del Archivo?",
  ui_story_4_14_62_dialog_content = "Ha sido robado, pero ni siquiera sé qué aspecto tiene... He fallado muy mal...",
  ui_story_4_14_63_dialog_content = "Yo también soy parcialmente responsable. No, incluso diría que la mayor parte recae sobre mí.",
  ui_story_4_14_64_dialog_content = "Lo siento mucho, Carleen.",
  ui_story_4_14_65_dialog_content = "Los Eclipsites siempre se defienden, Vice.",
  ui_story_4_14_66_dialog_content = "De hecho, estoy agradecido de que tú y PlayerName nos hayan advertido con anticipación.",
  ui_story_4_14_67_dialog_content = "Si hubiera sido cualquier otra persona, habríamos sufrido pérdidas aún mayores.",
  ui_story_4_14_68_dialog_content = "¿Nos hizo un cumplido hace un momento?",
  ui_story_4_14_69_dialog_content = "¿Creo que sí?",
  ui_story_4_14_70_dialog_content = "No he cumplido con mi deber como Capitán de los Guardianes. Yo... Debo enfrentar el castigo de Su Alteza el Señor.",
  ui_story_4_14_71_dialog_content = "Él es tu padre. Creo que te perdonará.",
  ui_story_4_14_72_dialog_content = "Veo que no lo entiendes a él ni a Lumopolis en absoluto.",
  ui_story_4_14_73_dialog_content = "Luego, deberíamos regresar a Illumina para discutir un plan de seguimiento.",
  ui_story_4_14_74_dialog_content = "Como dice el viejo refrán, \"Si te preocupas mucho por perderte el lunes, también te perderás el martes.\"",
  ui_story_4_14_75_dialog_content = "¿Eso es un dicho real?",
  ui_story_4_14_76_dialog_content = "Eres muy optimista, Vice.",
  ui_story_4_14_77_dialog_content = "Después de todo lo que has pasado, ¡no tiene sentido ser pesimista ahora!",
  ui_story_4_14_78_dialog_content = "Luego debo regresar a Zona residencial para informar al Señor. Cuídate.",
  ui_story_4_14_79_dialog_content = "Tal vez nos volvamos a ver, PlayerName...",
  ui_story_4_14_80_dialog_content = "<color=#e8d9bb>Mientras tanto, en algún lugar</color>",
  ui_story_4_14_81_dialog_content = "Las hermanas están muertas.",
  ui_story_4_14_82_dialog_content = "¿Es sorprendente?",
  ui_story_4_14_83_dialog_content = "Tengo cosas que contarte. La primera es que el Módulo Think Tank está en nuestras manos.",
  ui_story_4_14_84_dialog_content = "Y el Celestita volvió a aparecer.",
  ui_story_4_14_85_dialog_content = "PlayerName, ¿verdad?",
  ui_story_4_14_86_dialog_content = "Nunca olvidas los de tu propia especie, ¿o sí?",
  ui_story_4_14_90_dialog_content = "Lo diré una vez más. ¡¡¡Ya no formo parte de esa raza inferior!!!",
  ui_story_4_14_91_dialog_content = "¡Tus tontos secuaces casi arruinan todo el plan!",
  ui_story_4_14_92_dialog_content = "¡Obtendré el siguiente módulo yo misma! Y cualquiera que se atreva a detenerme... se hará pedazos.",
  ui_story_4_14_93_dialog_content = "¿Y el módulo? ¡Dámelo, Gertzurde!",
  ui_story_4_14_95_dialog_content = "Shelt... Shelt... ¡No, no!",
  ui_story_4_14_96_dialog_content = "Ella me prometió... Me prometió que se iría conmigo y que juntos seríamos libres...",
  ui_story_4_14_97_dialog_content = "¡¿Qué pasó...?!",
  ui_story_4_14_98_dialog_content = "¡Deja de hablarte a ti mismo con esa mirada miserable!",
  ui_story_4_14_99_dialog_content = "Fueron asesinadas por Guardianes de Lumopolis. ¡Deberías alegrarte que todavía tengas tiempo para cumplir nuestras órdenes!",
  ui_story_4_14_100_dialog_content = "¡Carleen...!",
  ui_story_4_14_101_dialog_content = "Ahora esta sí es una gran expresión, Gertzurde. Te ves completamente diferente a tu orden de arresto.",
  ui_story_4_14_102_dialog_content = "¡Yo las vengaré!",
  ui_story_5_1_1_dialog_content = "¿Es esa tu decisión, Capitán Carleen?",
  ui_story_5_1_2_dialog_content = "Sí, mi Señor. Creo que no sería prudente descuidar al Celestita, que es... realmente especial.",
  ui_story_5_1_3_dialog_content = "No interferiré, pero espero que recuerdes tu posición, Capitán.",
  ui_story_5_1_4_dialog_content = "Sí, mi Señor. Noche Blanca en lo alto.",
  ui_story_5_1_5_dialog_content = "Ahora comprendo la situación. La reunión habitual de Comandantes de la Legión es en media hora. Puedes dar un informe detallado en la reunión.",
  ui_story_5_1_6_dialog_content = "En cuanto a la resolución, dependerá de cómo resulte la negociación.",
  ui_story_5_1_7_dialog_content = "Ben, eso es todo para el primer punto, entonces.",
  ui_story_5_1_A1_dialog_content = "En cuanto a investigar Eclipsites cerca de las coordenadas antes mencionadas, está en manos de ustedes tres comandantes.",
  ui_story_5_1_8_dialog_content = "<size=30>Ejem, PlayerName, esa era <color=#FFB400>Sharona</color>, Comandante de la era Legión.</size>",
  ui_story_5_1_A2_dialog_content = "<size=30>Y ese es el Comandante <color=#FFB400>Barton</color> de la da Legión, también un destacado del ejército.</size>",
  ui_story_5_1_9_dialog_content = "Entiendo. Últimamente se han visto posibles Eclipsites de alto nivel cerca de Gannon, por lo que sin duda algo sospechoso está sucediendo.",
  ui_story_5_1_10_dialog_content = "Por eso trajimos a los tres comandantes. Queremos que todos estén alerta y no pasen por alto la amenaza.",
  ui_story_5_1_11_dialog_content = "¿Quiénes son los dos niños?",
  ui_story_5_1_12_dialog_content = "Son el segundo punto del día. Estás despierta, Hiiro.",
  ui_story_5_1_13_dialog_content = "Un operador de Colossus y Celestita sobreviviente, ¿eh?",
  ui_story_5_1_14_dialog_content = "...",
  ui_story_5_1_15_option_content = "¿Por qué todos me miran?",
  ui_story_5_1_16_dialog_content = "¿Te estás sonrojando?",
  ui_story_5_1_X16_dialog_content = "Sí, solo un niño, está bien.",
  ui_story_5_1_17_option_content = "¿Debería, eh, demostrar?",
  ui_story_5_1_18_dialog_content = "¿Y arrancar el techo con ese Colossus?",
  ui_story_5_1_19_dialog_content = "Muy volátil, ¡de acuerdo! ¿Qué hay entre tú y Schummer, chico?",
  ui_story_5_1_20_dialog_content = "¡PlayerName es diferente de Schummer, comandante!",
  ui_story_5_1_21_dialog_content = "Cálmate. No hay comparación entre un Celestita inocente y no combatiente y los que conspiran con los Eclipsites.",
  ui_story_5_1_22_dialog_content = "Nunca pensé que habría sobrevivientes Celestitas por ahí. Pensé que todos habían perecido en esa catástrofe.",
  ui_story_5_1_23_dialog_content = "Volviendo a Schummer que mencionaste. ¿Cuánto sabe ella sobre los tres módulos?",
  ui_story_5_1_24_dialog_content = "No estamos seguros, ya que los medios para encontrar los otros dos están en el Módulo Think Tank.",
  ui_story_5_1_25_dialog_content = "Y creemos que Schummer tiene el Módulo Think Tank, así que no se ve bien para nosotros ahora.",
  ui_story_5_1_26_dialog_content = "¡Nuestra máxima prioridad es hallar de algún modo los otros dos módulos antes que ella!",
  ui_story_5_1_27_dialog_content = "Espero que los comandantes puedan ayudarnos, o quizás manejar la operación.",
  ui_story_5_1_28_dialog_content = "La prioridad de Illumina es defender la línea frontal y el cuartel general en Ciudad Gannon.",
  ui_story_5_1_29_dialog_content = "Los Eclipsites han intensificado sus ataques últimamente, reduciendo nuestras fuerzas. Será difícil ahorrar personal.",
  ui_story_5_1_30_dialog_content = "Reitero, nadie más que el Gran Mariscal puede mandarnos a mí y a mi legión.",
  ui_story_5_1_31_dialog_content = "¿Y tú, Hiiro? ¿Qué opinas como superior de Vice?",
  ui_story_5_1_32_dialog_content = "Los soldados de Illumina se enorgullecen de seguir órdenes.",
  ui_story_5_1_33_dialog_content = "Entendido.",
  ui_story_5_1_34_dialog_content = "Lo sentimos, PlayerName, pero no podemos ayudarte antes de recibir pedidos directos.",
  ui_story_5_1_35_dialog_content = "¿Puedes sentir algo, PlayerName?",
  ui_story_5_1_36_dialog_content = "Solo un vasto vacío. Nada inusual.",
  ui_story_5_1_37_dialog_content = "¿Entonces ya no tenemos opciones?",
  ui_story_5_1_38_dialog_content = "Antes de morir, Mendelson dijo que Schummer definitivamente buscaría otros módulos.",
  ui_story_5_1_39_dialog_content = "Si podemos rastrear a Schummer, es posible que podamos averiguar más y hacer algo.",
  ui_story_5_1_40_dialog_content = "Pero ella prácticamente desapareció sin dejar rastro. ¿No vamos a hacer nada más que esperar?",
  ui_story_5_1_41_dialog_content = "*Bostezos* ¿Por qué las caras largas? ¿La reunión salió mal?",
  ui_story_5_1_42_dialog_content = "¡<color=#FFB400>Philyshy</color>!",
  ui_story_5_1_43_dialog_content = "¡Vamos, relájate! Aquí hay algo para ti.",
  ui_story_5_1_44_dialog_content = "¿<color=#FFB400>El informe sobre los restos del Colossus sin nombre-13</color>?",
  ui_story_5_1_45_dialog_content = "¡Pasé mucho tiempo en eso!",
  ui_story_5_1_46_dialog_content = "Vivian me puso en aprietos en esto. Fue demasiado intenso. Oh, tengo tanto sueño...",
  ui_story_5_1_47_dialog_content = "\"Se descubrieron módulos de crecimiento autónomo donde cayó el Colossus sin nombre, quizás exclusivo de este tipo de Colossus...\"",
  ui_story_5_1_48_dialog_content = "\"La unidad clave se encuentra en la parte más profunda de los restos, y aún se desconoce el método para desbloquearla. La investigación continúa...\"",
  ui_story_5_1_49_dialog_content = "¡La descripción suena como la <color=#FFB400>Unidad de Crecimiento Autónomo</color>!",
  ui_story_5_1_50_dialog_content = "¡Cuáles son las posibilidades! En fin, solo hay una forma de averiguarlo.",
  ui_story_5_1_51_dialog_content = "Oh, Vivian quería que te dijera ...",
  ui_story_5_1_52_dialog_content = "Aunque los comandantes no pueden ofrecer ayuda por ahora, hay bastantes de nuestra gente alrededor de los restos.",
  ui_story_5_1_53_dialog_content = "*Bostezos* No puedo aguantar mucho más. Tengo que ir a dormir un poco. Te animaré en mis sueños.",
  ui_story_5_1_54_dialog_content = "Philyshy es la misma de siempre.",
  ui_story_5_1_55_option_content = "Si tenemos a alguien así en el Colossus.",
  ui_story_5_1_56_dialog_content = "Ella es la jefa de Inteligencia de Illumina. Tenemos suerte de contar con su ayuda.",
  ui_story_5_1_57_dialog_content = "Si conseguimos que Philyshy se una a nosotros, al menos no estaremos tan perdidos sin un remo.",
  ui_story_5_1_58_dialog_content = "Pero parece que podría quedarse dormida en cualquier momento.",
  ui_story_5_1_59_dialog_content = "Puede ser estrés laboral...",
  ui_story_5_1_60_option_content = "De hecho, yo también tengo sueño.\nPor qué no...",
  ui_story_5_1_61_dialog_content = "¿Descansamos un poco?",
  ui_story_5_1_A4_dialog_content = "¡No, despierta, PlayerName! Cuanto antes nos ocupemos de estos problemas...",
  ui_story_5_1_62_dialog_content = "Cuanto antes te lleve a la biblioteca más grande de Gannon, ¡podrás tomártelo con calma todo lo que quieras!",
  ui_story_5_1_63_dialog_content = "¿No debería ser un parque de atracciones o un café? ¡Es inhumano estudiar después del trabajo!",
  ui_story_5_1_64_dialog_content = "De todos modos, ¡no nos queda mucho tiempo! ¡Tenemos que obtener el siguiente módulo antes de que lo haga Schummer!",
  ui_story_5_1_65_dialog_content = "¡Pongamos en marcha el Colossus!",
  ui_story_5_1_66_dialog_content = "Pareces confiada. Debes haber tenido una gran sesión informativa.",
  ui_story_5_1_67_dialog_content = "¡Carleen!",
  ui_story_5_1_68_dialog_content = "Pareces tan sorprendida. El Señor de la Ciudad aprobó mi solicitud de hacerme cargo de todo lo relacionado con Schummer.",
  ui_story_5_1_69_dialog_content = "Cualquiera que se atreva a oponerse a Lumopolis será castigado, y ponerse del lado de los Eclipsites es aún más imperdonable.",
  ui_story_5_1_70_dialog_content = "<size=30>Cuidado, Carleen se está volviendo volátil de nuevo.</size>",
  ui_story_5_1_71_dialog_content = "¿Qué dijiste?",
  ui_story_5_1_72_dialog_content = "¿Ah? ¿Lo dije en voz alta?",
  ui_story_5_1_73_dialog_content = "Si no hiciste nada malo, no tienes por qué temerme.",
  ui_story_5_1_A5_dialog_content = "A menos que seas Shelt, Gertzurde y los de su calaña, así como los que los respaldan.",
  ui_story_5_1_74_dialog_content = "¿No creó Gertzurde distracciones y trató de ayudar a Shelt y los demás a escapar?",
  ui_story_5_1_75_dialog_content = "Sí, el mismo desertor que buscó protección de Eclipse en las sombras.",
  ui_story_5_1_76_dialog_content = "Pero ningún traidor puede esconderse de la espada de la familia Schwartz, sin importar a dónde corran.",
  ui_story_5_1_77_dialog_content = "Basta de charla. ¿A dónde vamos?",
  ui_story_5_1_78_dialog_content = "Restos de Sin Nombre-13. ¿Has visto los restos de un Colossus antes, Capitán?",
  ui_story_5_1_79_dialog_content = "Eso no es importante, especialmente cuando hay asuntos que requieren mi atención inmediata.",
  ui_story_5_1_80_dialog_content = "De todos modos, gracias, PlayerName, por todo lo que has hecho por Lumopolis.",
  ui_story_5_1_81_dialog_content = "Te ayudaré en esta misión. ¡Juro que no dejaré que los traidores prevalezcan!",
  ui_story_5_2_1_dialog_content = "(Escucho voces. Voces tristes y nostálgicas.)",
  ui_story_5_2_2_dialog_content = "Flores para el hogar perdido, donde los árboles una vez crecieron con el viento...",
  ui_story_5_2_3_dialog_content = "Aurora para el difunto, que la luz redima a todos los espíritus...",
  ui_story_5_2_4_dialog_content = "Nuestro sufrimiento cesará con el tiempo, cenizas a cenizas, polvo al polvo...",
  ui_story_5_2_5_dialog_content = "Y daremos la bienvenida a la paz absoluta en nuestro sueño eterno cuando salga el sol.",
  ui_story_5_2_6_dialog_content = "¿Es eso suficiente, maestro? Pero todavía tengo miedo...",
  ui_story_5_2_7_dialog_content = "La flor que planté aún no ha brotado y tengo muchas ganas de verla florecer.",
  ui_story_5_2_8_dialog_content = "No tengas miedo, niño. Cierra tus ojos. El dolor es solo temporal. Siempre estaré contigo.",
  ui_story_5_2_9_dialog_content = "(Mi... ¿<color=#FFB400>gente</color>? ¿Es esto real o mi imaginación?)",
  ui_story_5_2_10_dialog_content = "Oración inútil y banal por los muertos. Vamos, no digas que nunca te di una opción...",
  ui_story_5_2_11_dialog_content = "Ya estamos acá. ¿Estás bien, PlayerName?",
  ui_story_5_2_12_option_content = "Vice...",
  ui_story_5_2_13_dialog_content = "No te preocupes, estoy aquí. ¿Sentiste algo?",
  ui_story_5_2_14_dialog_content = "Solo imágenes mentales... ¿Quiénes son?",
  ui_story_5_2_15_dialog_content = "Quizás los Celestitas que perecieron aquí dejaron atrás emociones intensas.",
  ui_story_5_2_16_dialog_content = "Muertos, ¿verdad? No pudieron hablarme como lo hizo Mendelson.",
  ui_story_5_2_17_dialog_content = "No tengo miedo. Probablemente no quede nada de sus restos.",
  ui_story_5_2_18_option_content = "Vi muchas imágenes en mi cabeza.",
  ui_story_5_2_19_dialog_content = "¿Sentiste la mente de alguien, PlayerName? ¿Podrían haber sobrevivientes aquí?",
  ui_story_5_2_A1_dialog_content = "Ningún sobreviviente aquí en absoluto. Lo que viste puede ser una especie de ilusión.",
  ui_story_5_2_20_dialog_content = "¿Imágenes tristes y desesperadas, o quizás restos psíquicos de los Celestitas muertos?",
  ui_story_5_2_21_dialog_content = "Eso creo. Sentí las emociones de mi gente.",
  ui_story_5_2_A2_dialog_content = "Aterricemos, Soroz.",
  ui_story_5_2_24_dialog_content = "Estamos en los <color=#FFB400>restos de Sin Nombre-13 </color>.",
  ui_story_5_2_25_dialog_content = "El documento dice, \"Las personas que descubrieron el sitio por primera vez se sorprendieron con el Colossus dormido...\"",
  ui_story_5_2_26_dialog_content = "\"Lo compararon con una estrella dormida que se estrelló desde el cielo.\"",
  ui_story_5_2_27_dialog_content = "\"No había señales de vida en el Colossus, solo el vacío dejado por el paso del tiempo.\"",
  ui_story_5_2_28_dialog_content = "Una represión tan tensa... Nunca antes había sentido algo así.",
  ui_story_5_2_29_dialog_content = "En cuanto a la catástrofe de Eraveil, leí en el archivo que...",
  ui_story_5_2_30_dialog_content = "\"Los Eclipsites abrumaron a los Celestitas en Eraveil con un ataque brutal. Nadie sobrevivió más que los que siguieron a los Eclipsites.\"",
  ui_story_5_2_31_dialog_content = "Pero cuando me acerco tanto, es más desgarrador de lo que imaginaba.",
  ui_story_5_2_A3_dialog_content = "...",
  ui_story_5_2_A4_dialog_content = "También debes estar llena de emociones, Vice.",
  ui_story_5_2_A5_dialog_content = "Sí. No tanto como PlayerName, pero puedo sentir el dolor.",
  ui_story_5_2_34_dialog_content = "¿Cómo sobreviviste, PlayerName?",
  ui_story_5_2_35_dialog_content = "Solo sé que cuando sucedió, Soroz ejecutó la orden final y me escoltó, que todavía era un bebé, fuera de allí.",
  ui_story_5_2_A6_dialog_content = "A esto le siguieron 17 largos años de vida subterránea hasta hace poco.",
  ui_story_5_2_36_dialog_content = "Vice me trajo al mundo exterior. Desafortunadamente, no es mucho mejor.",
  ui_story_5_2_37_dialog_content = "Ojalá pudiera volver a hablar con mi gente y también con Mendelson.",
  ui_story_5_2_38_dialog_content = "PlayerName...",
  ui_story_5_2_39_dialog_content = "No podemos permitir que la tragedia vuelva a ocurrir.",
  ui_story_5_2_40_dialog_content = "Por supuesto, ninguna raza debería pasar por eso.",
  ui_story_5_2_41_dialog_content = "Oye, mira, el Colossus más grande del medio. ¿Es eso lo que queremos?",
  ui_story_5_2_A7_dialog_content = "El archivo indica que se llama <color=#FFB400>Liebowitz</color>, el único Colossus capaz de crecimiento autónomo.",
  ui_story_5_2_42_dialog_content = "Debe tener la <color=#FFB400>Unidad de Crecimiento Autónomo</color>.",
  ui_story_5_2_43_dialog_content = "Pero está muy destrozado. ¿Puede la unidad aún estar intacta?",
  ui_story_5_2_44_dialog_content = "Eso es todo lo que saqué del archivo.",
  ui_story_5_2_45_dialog_content = "Entremos. Debe haber pistas.",
  ui_story_5_2_46_dialog_content = "Debes entender lo peligroso que es esto, PlayerName, solo piensa en lo que sucedió a Mendelson en ese entonces.",
  ui_story_5_2_F1_dialog_content = "Lo sé. Puedo meterme en problemas y desaparecer como él allí.",
  ui_story_5_2_47_dialog_content = "Todavía no puedo olvidar cómo pasó y desapareció Mendelson. Sentí como si podía alcanzarlo y tocarlo, pero estaba completamente indefenso.",
  ui_story_5_2_48_dialog_content = "Todavía podemos dar marcha atrás.",
  ui_story_5_2_F2_dialog_content = "Yo también tengo miedo, Vice, pero no tengo elección.",
  ui_story_5_2_F3_dialog_content = "He tomado una decisión. Pase lo que pase, lo afrontaré.",
  ui_story_5_2_49_dialog_content = "Entiendo, y no lo enfrentarás solo. Estaré contigo, pase lo que pase.",
  ui_story_5_2_A8_dialog_content = "<color=#e8d9bb>Dentro de los restos</color>",
  ui_story_5_2_50_dialog_content = "Esto es espantoso. La mayoría de las piezas están dañadas más allá del reconocimiento.",
  ui_story_5_2_51_dialog_content = "Puede que tengamos que reiniciar el Colossus para sacarlo.",
  ui_story_5_2_52_dialog_content = "¿De quién es esa voz?",
  ui_story_5_2_53_option_content = "Es... ¿Schummer?",
  ui_story_5_2_54_dialog_content = "No... ¡Es <color=#FFB400>Gronru</color>!",
  ui_story_5_2_55_option_content = "¿Alguien de Illumina?",
  ui_story_5_2_56_dialog_content = "¡Sí! Es <color=#FFB400>Madam Gronru</color>.",
  ui_story_5_2_57_dialog_content = "Gronru es la Oficial Técnico de Illumina y tiene un amplio conocimiento tanto de Colossus como de Lumina.",
  ui_story_5_2_58_dialog_content = "¡Señora!",
  ui_story_5_2_59_dialog_content = "¿Vice? No esperaba que llegaran refuerzos tan pronto...",
  ui_story_5_2_60_dialog_content = "¡Así que eres a quien Philyshy me dijo que tuviera cuidado!",
  ui_story_5_2_61_dialog_content = "¿Puedes imaginar? Philyshy actuó como si estuviera bajo un hechizo, quedándose dormida en medio de su discurso.",
  ui_story_5_2_62_dialog_content = "¡Me quedé sola sin poder hacer nada! ¡Estaba TAN ENOJADA! ¡Pero ahora veo que la suerte está de mi lado!",
  ui_story_5_2_63_dialog_content = "¿Y también tienes un Colossus que trabaja contigo? ¡Increíble! ¡Eso significa que está intacto!",
  ui_story_5_2_64_dialog_content = "<size=45>¿Puedo jugar con él?</size>",
  ui_story_5_2_65_dialog_content = "¿Ah?",
  ui_story_5_2_66_dialog_content = "Ejem, supongo que me emocioné un poco. ¡Volvamos a la misión principal que nos ocupa!",
  ui_story_5_2_67_dialog_content = "Gronru es agradable, pero a veces puede hacerte rascarte la cabeza con su forma de hablar.",
  ui_story_5_2_68_dialog_content = "Tal vez solo esté obsesionada con ciertas cosas...",
  ui_story_5_2_69_dialog_content = "¿Está usted aquí, señora Gronru?",
  ui_story_5_2_70_dialog_content = "¡Sí! La investigación ha sido increíblemente lenta, ya que este Colossus está gravemente dañado, por lo que no es más que una misión secundaria.",
  ui_story_5_2_71_dialog_content = "Pero no puedo evitar sentir que todavía hay algo dentro que deberíamos investigar más a fondo.",
  ui_story_5_2_72_dialog_content = "Un jugador profesional no puede dejar las misiones secundarias sin terminar, así que solicité volver aquí para volver a investigar durante unos días más.",
  ui_story_5_2_73_dialog_content = "Oh, ¿estás aquí por la <color=#FFB400>Unidad de Crecimiento Autónomo</color>?",
  ui_story_5_2_74_dialog_content = "Sí. ¿Encontraste alguno en tu investigación?",
  ui_story_5_2_75_dialog_content = "Este Colossus ciertamente tenía ese tipo de módulo, pero no es algo que puedas extraer con fuerza bruta.",
  ui_story_5_2_77_dialog_content = "El Colossus es el pináculo de la antigüedad, después de todo, y es inescrutable para el nivel tecnológico actual de Illumina.",
  ui_story_5_2_78_dialog_content = "¿No hay otra forma?",
  ui_story_5_2_79_dialog_content = "¿Otra forma? Eso no está fuera del ámbito de lo posible.",
  ui_story_5_2_80_dialog_content = "¿Debes ser el <color=#FFB400>único Celestita sobreviviente</color> que mencionó Philyshy? ¡Un lema tan directo para un protagonista!",
  ui_story_5_2_81_dialog_content = "Dado que tenemos un Celestita vivo que respira, podríamos intentar reiniciar este gran trozo de basura.",
  ui_story_5_2_82_dialog_content = "No hay tiempo que perder. Démonos prisa...",
  ui_story_5_2_83_dialog_content = "<anim type=Shake>¡Wooga!</anim>",
  ui_story_5_2_84_dialog_content = "Tenemos compañía. Supongo que tenemos que quitar la basura del camino para seguir adelante.",
  ui_story_5_2_A9_dialog_content = "¡Entonces debemos hacerlo rápido y sin demora!",
  ui_story_5_2_85_dialog_content = "Te encantará dónde se encuentra la Unidad de Crecimiento Autónomo...",
  ui_story_5_2_86_dialog_content = "¿Un vertedero lleno de alimañas? Y pensé que sería algo especial.",
  ui_story_5_2_87_dialog_content = "¿El módulo que quiero está entre estos patéticos muertos? No me digas que podría haberlo destruido accidentalmente.",
  ui_story_5_2_88_dialog_content = "Muy molesto. ¿Está<color=#FFB400>esa mujer</color> provocándome? ¿No te dije que no soy igual a estos débiles bastardos?",
  ui_story_5_2_89_dialog_content = "¡Los débiles merecen ser pisoteados, destrozados y esparcidos por el viento!",
  ui_story_5_2_90_dialog_content = "Maldición, aunque me está ayudando, esto sigue siendo insoportable.",
  ui_story_5_2_91_dialog_content = "Esos Eclipsites inútiles... Si hicieron bien su trabajo la última vez, yo misma no tendría que mover un dedo.",
  ui_story_5_2_92_dialog_content = "¡Y el Celestita, espero que nos veamos pronto!",
  ui_story_5_3_1_dialog_content = "No podemos ver bien lo dañado que está el interior. ¿Estás seguro de que vamos en la dirección correcta?",
  ui_story_5_3_2_dialog_content = "No te preocupes, soy un profesional. Ya me he dirigido al Puente. Está 200 metros más adelante.",
  ui_story_5_3_3_dialog_content = "Es pan comido para alguien con un impecable sentido de la orientación como yo.",
  ui_story_5_3_4_dialog_content = "Oigo algo.",
  ui_story_5_3_5_dialog_content = "Eso no sonaba como si viniera de cerca.",
  ui_story_5_3_6_dialog_content = "Tengo escalofríos por mi columna vertebral...",
  ui_story_5_3_8_dialog_content = "¿Qué pasa, PlayerName? ¿Estás bien?",
  ui_story_5_3_9_dialog_content = "Siento una presencia más poderosa que los Eclipsites de alto nivel... ¡Podría ser Schummer!",
  ui_story_5_3_10_dialog_content = "Mantén la calma y procede según lo planeado.",
  ui_story_5_3_11_dialog_content = "Si ella está aquí, aquí es donde acabaremos con ella.",
  ui_story_5_3_12_dialog_content = "Pero...",
  ui_story_5_3_13_dialog_content = "Sin peros. Ella ha causado suficiente dolor. Te mostraré el error de sus caminos.",
  ui_story_5_3_A1_dialog_content = "Adelante. Hay más Eclipsites esperándonos más adelante.",
  ui_story_5_3_14_dialog_content = "Siento una presencia familiar. ¿No me digas que realmente están aquí?",
  ui_story_5_3_16_dialog_content = "Débil, ni siquiera un rival, pero persistente.",
  ui_story_5_3_17_dialog_content = "Mendelson murió, y ahora conseguimos que PlayerName lo reemplace, tratando de proteger el módulo en vano.",
  ui_story_5_3_18_dialog_content = "Te dije que la única elección correcta es la que hice yo.",
  ui_story_5_3_A2_dialog_content = "Tomar la espada es la única forma de controlar tu propio destino, o siempre serás una presa patética.",
  ui_story_5_3_A3_dialog_content = "¡Sigue a Lumina y saluda a nuestros invitados, matorrales! Prepáralos para la gran batalla.",
  ui_story_5_3_A4_dialog_content = "De hecho, estoy que llegue la pelea.",
  ui_story_5_3_A5_dialog_content = "(Hablando en Eclipsiano) Sí... ¡A la carga!",
  ui_story_5_7_A14_dialog_content = "¡Y estamos aquí, en el Puente!",
  ui_story_5_7_A15_dialog_content = "Aún así, también tengo que tener cuidado con los molestos Eclipsites.",
  ui_story_5_7_A16_dialog_content = "A pesar de una larga investigación y esfuerzo, me he quedado atascado tratando de quitar la Unidad de Crecimiento Autónomo del Puente.",
  ui_story_5_7_A17_dialog_content = "¡Pero esta vez tengo un Celestita! Puedes reiniciar el Colossus, ¿verdad?",
  ui_story_5_7_A18_dialog_content = "Lo haré lo mejor que pueda.",
  ui_story_5_7_1_dialog_content = "El primer paso para iniciar un Colossus es evaluar el nivel de energía.",
  ui_story_5_7_2_dialog_content = "El Colossus está muy dañado, pero sorprendentemente, todavía tiene suficiente energía para reiniciar.",
  ui_story_5_7_3_dialog_content = "El segundo paso es establecer un vínculo mental con el Colossus. Esa es la única forma de acceder al panel de control, y solo un Celestita puede hacerlo.",
  ui_story_5_7_4_dialog_content = "El tercer paso es operar el control...",
  ui_story_5_7_5_dialog_content = "Sí, así. Lo estás haciendo muy bien.",
  ui_story_5_7_6_dialog_content = "¿Qué es esa voz?",
  ui_story_5_7_7_dialog_content = "Estoy extasiado. Ha pasado mucho, mucho tiempo desde la última vez que vi a un compañero Celestita, un descendiente de nuestra raza.",
  ui_story_5_7_8_dialog_content = "Crecer solo sin ningún contacto con nadie. Debe ser duro para ti.",
  ui_story_5_7_9_dialog_content = "Como sabes eso...",
  ui_story_5_7_11_dialog_content = "Como tú, soy de la hermosa Eraveil.",
  ui_story_5_7_14_dialog_content = "Había vivido y aprendido con mi gente desde pequeño, escuchando canciones y conversando con Colossus.",
  ui_story_5_7_A1_dialog_content = "Éramos una familia muy unida, PlayerName, a la que pertenecían los Celestitas.",
  ui_story_5_7_15_option_content = "Pero, ¿por qué eres transparente?",
  ui_story_5_7_16_dialog_content = "¿Por qué no puedo distinguir tu cara?",
  ui_story_5_7_17_dialog_content = "Porque soy solo un hilo de tus anhelos. Nos manifestamos solo cuando quieres vernos.",
  ui_story_5_7_18_dialog_content = "Corrimos en vano. Cuerpos descompuestos en simples huesos, espíritus esparcidos por el cielo sin límites.",
  ui_story_5_7_19_dialog_content = "Ella llevó a los Eclipsites a matarnos en una horrible masacre. Esa es la oscuridad que ni siquiera la Aurora podría penetrar.",
  ui_story_5_7_20_dialog_content = "Hasta la fecha, ha mantenido sus convicciones.",
  ui_story_5_7_21_dialog_content = "Pobre niño. Debe haber sido agonizante vivir en soledad.",
  ui_story_5_7_22_dialog_content = "No puedo abrazarte, pero puedo tocar esta melodía contigo, una melodía de memoria.",
  ui_story_5_7_23_dialog_content = "Vincula tu mente. Conéctate con Colossus como lo haces con Soroz.",
  ui_story_5_7_24_dialog_content = "Acepta este regalo, el último hijo que nunca conocí.",
  ui_story_5_7_A2_dialog_content = "(Es solo una visión, pero puedo sentir sus dedos tocando mi piel.)",
  ui_story_5_7_25_dialog_content = "(Sé que murió hace mucho tiempo, pero ¿cómo podría su psique cruzar a este mundo para guiarme?)",
  ui_story_5_7_26_dialog_content = "(Enciende el Colossus para verte.)",
  ui_story_5_7_27_dialog_content = "(¿Qué estás cantando? El coro es tan armonioso. ¿Por quién estás de luto? Sé que estás enterrado.)",
  ui_story_5_7_28_dialog_content = "(Nunca escuché algo como esto, pero puedo tararear contigo.)",
  ui_story_5_7_29_dialog_content = "(Gracias por tocar para mí. Siempre recordaré esta sinfonía.)",
  ui_story_5_7_30_dialog_content = "Mi gente, cómo espero que estén vivos y sean reales.",
  ui_story_5_7_31_dialog_content = "¡El Colossus se está reiniciando!",
  ui_story_5_7_32_dialog_content = "El Colossus gime. Suena a sollozos, pero no del todo...",
  ui_story_5_7_33_dialog_content = "Se siente como si alguien estuviera tarareando con PlayerName.",
  ui_story_5_7_34_dialog_content = "Déjame ayudarte, PlayerName.",
  ui_story_5_7_35_dialog_content = "Casi llegamos... 5, 4... ¡Enganchado con éxito!",
  ui_story_5_7_36_dialog_content = "¡Mira, es la <color=#FFB400>Unidad de Crecimiento Autónomo</color>!",
  ui_story_5_7_37_dialog_content = "Tómalo, rápido...",
  ui_story_5_7_38_dialog_content = "¡¿Qué está pasando?!",
  ui_story_5_7_39_dialog_content = "<anim type=Shake>*Rugido*</anim>",
  ui_story_5_7_40_dialog_content = "Parece que llegué en el momento perfecto.",
  ui_story_5_7_41_dialog_content = "¡¿Schummer?!",
  ui_story_5_7_A3_dialog_content = "Tú debes ser PlayerName.",
  ui_story_5_7_A4_dialog_content = "Eres más joven de lo que pensé. Sin embargo, me encanta la sorpresa y el miedo en tu rostro.",
  ui_story_5_7_42_dialog_content = "Ya es suficiente cantar. En fin, buen trabajo extrayendo la Unidad de Crecimiento Autónomo.",
  ui_story_5_7_A5_dialog_content = "Realmente eres tú, Schummer, parado frente a mí...",
  ui_story_5_7_45_dialog_content = "El dolor... Oh, el dolor...",
  ui_story_5_7_46_dialog_content = "Por favor, que alguien nos salve...",
  ui_story_5_7_47_dialog_content = "Me recuerdas a los Celestitas que aplasté como hormigas, PlayerName.",
  ui_story_5_7_48_dialog_content = "Cada vez que pienso en cómo fui uno de los mansos, me siento tan... disgustada.",
  ui_story_5_7_49_dialog_content = "Hablas demasiado.",
  ui_story_5_7_50_dialog_content = "¿Esa es tu respuesta? Que decepcionante.",
  ui_story_5_7_51_dialog_content = "¿Eres tú quien envió a esos inmundos monstruos a atacar Lumopolis?",
  ui_story_5_7_52_dialog_content = "Tú los llamas monstruos, yo los llamo ineptos.",
  ui_story_5_7_53_dialog_content = "¡Lo que hiciste es imperdonable y lo pagarás!",
  ui_story_5_7_54_dialog_content = "¿Y cómo vas a hacer eso?",
  ui_story_5_7_55_dialog_content = "¡PlayerName! ¡¿Estás bien?!",
  ui_story_5_7_A6_dialog_content = "(Mantén la calma... no puedo dejar que me moleste. Puedo hacerlo...)",
  ui_story_5_7_A7_dialog_content = "(Simplemente sigue la rutina normal y podremos acabar con Schummer, la fuente y el culpable de toda esta atrocidad.)",
  ui_story_5_7_A8_dialog_content = "PlayerName, parece que eres...",
  ui_story_5_7_A9_dialog_content = "Uff.",
  ui_story_5_7_A10_dialog_content = "Estoy bien, Vice. Tomen sus posiciones con Carleen como de costumbre, y yo lideraré.",
  ui_story_5_7_A11_dialog_content = "¡Bien, estoy listo!",
  ui_story_5_7_56_dialog_content = "Toma el mando, PlayerName. ¡Mi lanza traspasará todo lo que es malo!",
  ui_story_5_7_57_dialog_content = "¡Todos, prepárense para luchar! ¡Nuestro enemigo es Schummer!",
  ui_story_5_7_A12_dialog_content = "Los débiles deben someterse a la destrucción.",
  ui_story_5_7_58_dialog_content = "¿Por qué luchas? ¿Debo decirte otra vez que te acuestes como la mansa oveja que eres?",
  ui_story_5_7_59_dialog_content = "Tsk, eres difícil. A pesar de toda esta charla de mando y coordinación, sigues siendo un cobarde esquivando la pelea real.",
  ui_story_5_7_60_dialog_content = "Pero debo admitir que eres algo diferente de los otros Celestitas.",
  ui_story_5_7_61_option_content = "No, soy como cualquier otro Celestita.",
  ui_story_5_7_62_option_content = "Derribarte es simplemente un movimiento de muñeca.",
  ui_story_5_7_63_dialog_content = "No seas tonto. No fue un cumplido. Fue un elogio.",
  ui_story_5_7_64_dialog_content = "Después de todo, no eres nada a mis ojos.",
  ui_story_5_7_65_dialog_content = "Muy poderoso...",
  ui_story_5_7_66_dialog_content = "Elige uno, ¿aplastado o roto?",
  ui_story_5_7_67_dialog_content = "¡Ahora!",
  ui_story_5_7_68_dialog_content = "¿Qué es esa vibración...?",
  ui_story_5_7_69_dialog_content = "¡Segundos extra en el temporizador! ¡Somos bastante buenos para el estancamiento!",
  ui_story_5_7_70_dialog_content = "¡Tengo el módulo, Carleen y PlayerName!",
  ui_story_5_7_71_dialog_content = "Haré interferencia y te cubriré. Toma el módulo y vete.",
  ui_story_5_7_72_option_content = "Pero Gronru...",
  ui_story_5_7_73_dialog_content = "¿Cuál es el problema? ¡De todos modos, me moría por mostrar mi movimiento asesino!",
  ui_story_5_7_74_option_content = "¡Sí, señora!",
  ui_story_5_7_75_dialog_content = "¡Lo hiciste bien explotando las reglas del juego! ¡Ahora devuelve el módulo a Illumina!",
  ui_story_5_7_76_dialog_content = "Pero Schummer podría ser demasiado duro para ti...",
  ui_story_5_7_77_dialog_content = "¡Oye, no soy un investigadora común y corriente! ¡Entiendo el poder más que nadie! ¡Yo misma soy muy poderosa!",
  ui_story_5_7_78_dialog_content = "Ok. Vamos, Vice y PlayerName. No podemos desperdiciar la oportunidad que nos da Gronru.",
  ui_story_5_7_79_dialog_content = "Basta de parloteo y entrega el módulo.",
  ui_story_5_7_80_dialog_content = "¿Qué hacer ahora? ¡Realmente quiero pelear contigo!",
  ui_story_5_7_A13_dialog_content = "Una pelea de jefe en un nivel difícil contra una Celestita que domina el poder Eclipsite... ¡Eso suena tan emocionante!",
  ui_story_5_7_81_dialog_content = "¡Vamos, juguemos!",
  ui_story_5_7_82_dialog_content = "Me aburres.",
  ui_story_5_7_83_dialog_content = "Ha pasado un tiempo, Vice. Todavía nada de Gronru.",
  ui_story_5_7_84_dialog_content = "Gronru estará bien... Creo.",
  ui_story_5_7_85_dialog_content = "No podemos perder el tiempo. Tenemos que despegar ahora.",
  ui_story_5_7_86_dialog_content = "Lo se.",
  ui_story_5_7_87_dialog_content = "¿Escuchas eso en el comunicador?",
  ui_story_5_7_88_dialog_content = "Es...",
  ui_story_5_7_89_dialog_content = "¡¿<color=#FFB400>Señora Gronru</color>?!",
  ui_story_5_8_1_dialog_content = "Vice, vete con Soroz y el módulo de inmediato, vete...",
  ui_story_5_8_2_dialog_content = "¡Señora Gronru!",
  ui_story_5_8_3_dialog_content = "¡Cállate! ¡¿Es eso lo que te dije que dijeras?!",
  ui_story_5_8_4_dialog_content = "Escuchen, alimentadores del fondo, porque no lo repetiré de nuevo.",
  ui_story_5_8_5_dialog_content = "Vuelvan aquí en 30 minutos y pásame la Unidad de Crecimiento Autónomo, o este gusano muere.",
  ui_story_5_8_6_dialog_content = "¡No la escuches! ¡Vete ahora, Vice! ¡Es una orden!",
  ui_story_5_8_7_dialog_content = "¡Cállate!",
  ui_story_5_8_8_dialog_content = "30 minutos ni siquiera es tiempo suficiente para que Illumina envíe ayuda.",
  ui_story_5_8_9_dialog_content = "Se salvarán muchas más vidas recuperando la Unidad de Crecimiento Autónomo.",
  ui_story_5_8_10_dialog_content = "Sé que debo obedecer las órdenes de un superior. Esa es siempre la prioridad de un Illumina.",
  ui_story_5_8_11_dialog_content = "Pero simplemente no puedo soportar abandonar a Gronru a su muerte.",
  ui_story_5_8_12_dialog_content = "Para decirlo bien, eres tan compasivo como siempre... o indeciso, para decirlo no tan bien.",
  ui_story_5_8_13_dialog_content = "¿Es tan difícil elegir entre una vida o muchas?",
  ui_story_5_8_14_dialog_content = "Quiero proteger a todos.",
  ui_story_5_8_15_dialog_content = "*Rugido*",
  ui_story_5_8_16_dialog_content = "Deshagámonos de los invitados no invitados en el Colossus ahora y preocupémonos más tarde.",
  ui_story_5_10_1_dialog_content = "Déjame adivinar por qué los que se alimentan del fondo aún no se han decidido... ¿Intentas detenerte de nuevo?",
  ui_story_5_10_2_dialog_content = "Se me acaba la paciencia. Tienes 20... no, quedan 19 minutos.",
  ui_story_5_10_3_dialog_content = "Empezaré a destrozar a esta chica poco a poco en 19 minutos.",
  ui_story_5_10_4_dialog_content = "Oh, me da emoción solo imaginarme sus agonizantes gritos.",
  ui_story_5_10_5_dialog_content = "¿No hay otra forma de salvar a Gronru además de entregar el módulo?",
  ui_story_5_10_6_dialog_content = "¡Está loca!",
  ui_story_5_10_7_option_content = "Puede haber otra forma.",
  ui_story_5_10_8_dialog_content = "¿Ah?",
  ui_story_5_10_9_dialog_content = "Tengo una idea que podría funcionar en 15 minutos.",
  ui_story_5_10_10_dialog_content = "¿Qué quieres decir?",
  ui_story_5_10_11_dialog_content = "Tal vez podamos hacerlo de forma indirecta...",
  ui_story_5_10_12_option_content = "Quiero proteger a todos.",
  ui_story_5_10_13_dialog_content = "¿Estás de acuerdo conmigo, PlayerName?",
  ui_story_5_10_14_dialog_content = "Sí. Ya sea Gronru o cualquier otra persona, debemos protegerlos a todos.",
  ui_story_5_10_15_dialog_content = "Primero Vice, ahora tú. Me rindo.",
  ui_story_5_10_16_dialog_content = "Pero ya que lo pones de esa manera, debes tener un plan.",
  ui_story_5_10_17_dialog_content = "Sí. Es muy arriesgado y necesitaré tu ayuda.",
  ui_story_5_10_A1_dialog_content = "¡Tendremos que ser agresivos y movernos rápido!",
  ui_story_5_10_A2_dialog_content = "Escúchame, así será...",
  ui_story_5_10_18_dialog_content = "Solo quedan unos minutos. Sin aterrizaje ni salida. ¿Sigues debatiendo?",
  ui_story_5_10_19_dialog_content = "¡Activa el Trono!",
  ui_story_5_10_20_dialog_content = "Qué imprudente.",
  ui_story_5_10_21_dialog_content = "¡Falló otra vez!",
  ui_story_5_10_22_dialog_content = "Debes tener un deseo de muerte para intentar ya tres cargos de suicidio. Afortunadamente para ti, todavía no es hora de morir.",
  ui_story_5_10_23_dialog_content = "Combo impactante...",
  ui_story_5_10_24_dialog_content = "¡Muy mareada! ¿Se acabó el juego...?",
  ui_story_5_10_25_dialog_content = "Ve a dormir. Te sacaré para siempre en unos minutos.",
  ui_story_5_10_A3_dialog_content = "¡Aquí hay otro más!",
  ui_story_5_10_A4_dialog_content = "¡Muy sutil! Schummer no nos vio, ¿verdad?",
  ui_story_5_10_A5_dialog_content = "No soy apto para operaciones encubiertas, PlayerName.",
  ui_story_5_10_A6_dialog_content = "Lo estás haciendo genial. Continuemos, no es que tengamos otra opción.",
  ui_story_5_13_1_dialog_content = "Levántate, todavía tienes 5 minutos.",
  ui_story_5_13_2_dialog_content = "Veo estrellas... ¿Puedo subir de nivel recogiéndolos?",
  ui_story_5_13_3_dialog_content = "Levántate ahora.",
  ui_story_5_13_4_dialog_content = "¡Oye, muy malvado de tu parte al noquearme un segundo y despertarme al siguiente!",
  ui_story_5_13_5_dialog_content = "Quedan 5 minutos y todavía no hay respuesta. Probablemente te abandonaron.",
  ui_story_5_13_6_dialog_content = "¡Eso espero! ¡Los golpearía por ti si se atreven a volver!",
  ui_story_5_13_7_dialog_content = "También podría estar cansado de esperar, de todos modos.",
  ui_story_5_13_A1_dialog_content = "No es óptimo, pero acabar contigo ahora y matarlos más tarde tampoco es la peor opción.",
  ui_story_5_13_8_dialog_content = "Oye, ¿estás matando al rehén antes de que se acabe el tiempo? ¡No es así como juegas!",
  ui_story_5_13_9_dialog_content = "Tengo noticias para ti, ¡los fuertes siempre dictan cómo se juega el juego!",
  ui_story_5_13_A2_dialog_content = "¡Ahora, voy a cerrar tu molesto agujero de tarta por última vez!",
  ui_story_5_13_10_dialog_content = "¡¿Qué...?!",
  ui_story_5_13_11_dialog_content = "¡Flor de hielo!",
  ui_story_5_13_12_dialog_content = "Otro ataque furtivo...",
  ui_story_5_13_13_dialog_content = "Ella está impaciente. Creo que es posible que ni siquiera siga los términos.",
  ui_story_5_13_14_dialog_content = "Gronru corre grave peligro. Debemos actuar lo más rápido que podamos.",
  ui_story_5_13_A3_dialog_content = "¡Estoy listo para seguir tu plan, PlayerName!",
  ui_story_5_13_A13_dialog_content = "Dejemos que Soroz se quede donde estábamos para distraer a Schummer, entonces...",
  ui_story_5_13_17_dialog_content = "¡Lanza un ataque sorpresa! ¡Ella nunca esperará que la saltemos así!",
  ui_story_5_13_18_dialog_content = "¿Fingir indecisión y luego emboscar?",
  ui_story_5_13_19_dialog_content = "Sí. Bueno, funcionó, ¿no? ¡Ríndete, Schummer! ¡También limpiamos los Eclipsites!",
  ui_story_5_13_20_dialog_content = "Si llamas a esto \"trabajando\"...",
  ui_story_5_13_21_dialog_content = "¡No me olvides! ¡Haiyah!",
  ui_story_5_13_22_dialog_content = "¡El combo funcionó! ¡Grande Feroz está herido y reunimos el equipo! ¡Cómo cambió la marea!",
  ui_story_5_13_A4_dialog_content = "¿Supongo que ya escondiste ese módulo crucial en un lugar seguro? ¡Ahora todos podemos unirnos a ella, en serio!",
  ui_story_5_13_24_dialog_content = "¡Consigamos algunos, Carleen!",
  ui_story_5_13_26_dialog_content = "¡Sí, mantenla en los talones!",
  ui_story_5_13_27_dialog_content = "¿Es esto todo lo que tienes?",
  ui_story_5_13_28_dialog_content = "No puedo creer que ustedes matorrales me subestimen.",
  ui_story_5_13_29_dialog_content = "¡Estoy sintiendo un cambio!",
  ui_story_5_13_30_dialog_content = "¡Su poder se siente completamente diferente al de antes!",
  ui_story_5_13_31_dialog_content = "¡Suficiente! Dado que todos ustedes están tan ansiosos por morir, ¡no escatimaré esfuerzos!",
  ui_story_5_13_A14_dialog_content = "¡Bien, estás luchando mejor! Es casi entretenido ahora...",
  ui_story_5_13_A15_dialog_content = "¡Sin embargo, tu presunción me molesta! ¡Arrodíllate!",
  ui_story_5_13_A16_dialog_content = "¿Cómo se está volviendo aún más poderosa?",
  ui_story_5_13_A17_dialog_content = "¿Así que te has estado conteniendo... solo para jugar con nosotros?",
  ui_story_5_13_32_dialog_content = "(¡Todos vamos a morir si esto sigue así!)",
  ui_story_5_13_A5_dialog_content = "(¿Mi gente también luchó desesperadamente así? Este poder es abrumador...)",
  ui_story_5_13_33_dialog_content = "(¿Así de devastador puede ser un Celestita con poder Eclipsite?)",
  ui_story_5_13_34_dialog_content = "¿Conmocionado y asombrado? El Eclipse puede hacer que incluso un Celestita débil sea invencible.",
  ui_story_5_13_35_dialog_content = "<size=45>¡Más fuerte incluso que los Aurorians!</size>",
  ui_story_5_13_36_dialog_content = "Duele mucho... No puedo... respirar...",
  ui_story_5_13_37_dialog_content = "Haz tu elección ahora, ¿su vida o la Unidad de Crecimiento Autónoma?",
  ui_story_5_13_38_dialog_content = "*Tose* No, no se lo des...",
  ui_story_5_13_39_dialog_content = "¡Gronru! Vice, Carleen...",
  ui_story_5_13_40_dialog_content = "Todavía puedo luchar, maldita sea... Sé que puedo...",
  ui_story_5_13_41_dialog_content = "Yo...",
  ui_story_5_13_42_dialog_content = "¿Estás pensando en pelear conmigo? ¿Sin un ápice de poder Lumina en eso?",
  ui_story_5_13_43_dialog_content = "¡Oh, esto es precioso y ridículo al mismo tiempo!",
  ui_story_5_13_44_dialog_content = "Puede que no tenga a Lumina, ¡pero tengo mis puños!",
  ui_story_5_13_45_dialog_content = "¡Schummer!",
  ui_story_5_13_46_dialog_content = "¡No, PlayerName!",
  ui_story_5_13_47_dialog_content = "Aunque no puedo controlar a Lumina, ¡no tengo miedo de pelear!",
  ui_story_5_13_48_dialog_content = "¡Debo defender a mis compañeros, mi especie y mi familia!",
  ui_story_5_13_A6_dialog_content = "Si me rompo las manos, morderé. ¡Si pierdo los dientes, golpearé mi cabeza!",
  ui_story_5_13_A7_dialog_content = "No puedes obligarme a rendirme, Schummer. Esta vez, tú...",
  ui_story_5_13_49_dialog_content = "<size=45>¡tendrás que atravesarme para llegar a ellos!</size>",
  ui_story_5_13_A8_dialog_content = "...",
  ui_story_5_13_A9_dialog_content = "¿Cuál es el punto de esto?",
  ui_story_5_13_50_dialog_content = "¿Debes gritar? El discurso heroico es tan cliché.",
  ui_story_5_13_51_dialog_content = "Urgh...",
  ui_story_5_13_52_dialog_content = "¿Por qué, PlayerName?",
  ui_story_5_13_53_dialog_content = "Tomen una decisión, perdedores. El módulo o sus vidas. Estoy contando. Diez, nueve...",
  ui_story_5_13_54_option_content = "Tengo una propuesta...",
  ui_story_5_13_55_option_content = "Bien, aquí está el módulo.",
  ui_story_5_13_56_dialog_content = "¿Tienes una propuesta para mí? ¿En serio?",
  ui_story_5_13_57_dialog_content = "Puedes tener el módulo, ¡pero tienes que dejarlos ir primero!",
  ui_story_5_13_58_dialog_content = "¿Hablas en serio? Deberías ponerte de rodillas y suplicar piedad.",
  ui_story_5_13_59_dialog_content = "Los dejas ir y puedes tenerme a mí y al módulo. De lo contrario, lo destruiré.",
  ui_story_5_13_60_dialog_content = "¿Destruirlo? ¿Tomaste esa expresión de \"morir en el intento\" de Mendelson? Que desagradable.",
  ui_story_5_13_F1_dialog_content = "Está bien. Pueden irse.",
  ui_story_5_13_F2_dialog_content = "Aquí está el módulo.",
  ui_story_5_13_F3_dialog_content = "Pobre Celestita. Sin poder, te dejan simplemente para que te maten. Tu supervivencia depende puramente de la caridad de los fuertes.",
  ui_story_5_13_F4_dialog_content = "Oh, ¿eso tocó un nervio?",
  ui_story_5_13_F5_dialog_content = "¿Eso te recordó el pasado?",
  ui_story_5_13_F6_dialog_content = "Recuerda el sentimiento. Los <size=45>débiles</size> deben sufrir humillaciones solo para sobrevivir.",
  ui_story_5_13_61_dialog_content = "Pobre Celestita. Sin poder, te dejan simplemente para que te maten. Tu supervivencia depende puramente de la caridad de los fuertes.",
  ui_story_5_13_F7_dialog_content = "Ni siquiera los miraría a ninguno de ustedes si no fuera por el módulo.",
  ui_story_5_13_68_dialog_content = "Felicitaciones por tener la oportunidad de vivir. ¡Lo aprecio!",
  ui_story_5_13_69_dialog_content = "¿Estás bien, Gronru? Has estado fuera durante dos horas...",
  ui_story_5_13_70_dialog_content = "No te preocupes, soy muy terca para morir...",
  ui_story_5_13_F8_dialog_content = "Lamento que tengas que cambiar el módulo para salvarme.",
  ui_story_5_13_71_dialog_content = "No, es nuestra culpa por no ser lo bastante fuertes para tomarla.",
  ui_story_5_13_72_dialog_content = "Al menos todos siguen vivos. Podría ser peor.",
  ui_story_5_13_73_dialog_content = "¡Ya eres muy impresionante!",
  ui_story_5_13_74_dialog_content = "Lo ignoré cuando Philyshy me lo contó, pero ahora que lo he visto por mí misma...",
  ui_story_5_13_A10_dialog_content = "¡Schummer es una amenaza mucho mayor de lo que imaginaba!",
  ui_story_5_13_75_dialog_content = "Revisaré todo, informaré a mis superiores y les alertaré sobre la gravedad de este asunto.",
  ui_story_5_13_76_dialog_content = "¿No hay un tercer módulo?",
  ui_story_5_13_77_dialog_content = "El <color=#FFB400>Módulo de Control de Llama...</color>",
  ui_story_5_13_78_dialog_content = "El componente de ultra armas para modernizar un Colossus y equiparlo con capacidades ofensivas... Pero no sabemos su paradero.",
  ui_story_5_13_79_option_content = "Sé que debo hacer.",
  ui_story_5_13_F9_dialog_content = "La he visto tantas veces que nunca olvidaré su presencia.",
  ui_story_5_13_F10_dialog_content = "Ella no está lejos de nosotros. Todo lo que tengo que hacer es cerrar los ojos.",
  ui_story_5_13_F11_dialog_content = "Ella no me notará mientras me cuele como un debilucho.",
  ui_story_5_13_80_dialog_content = "(¿Es un laberinto bizantino con innumerables trampas?)",
  ui_story_5_13_81_dialog_content = "(Enigmático, oscuro y lleno de colecciones retorcidas...)",
  ui_story_5_13_82_dialog_content = "Schummer debe saber a dónde ir con seguridad.",
  ui_story_5_13_83_dialog_content = "El <color=#FFB400>Pasillo Susurrante</color>...",
  ui_story_5_13_85_option_content = "¡El Pasillo Susurrante!",
  ui_story_6_1_1_dialog_content = "Schummer es un oponente peligroso, sin duda alguna...",
  ui_story_6_1_2_dialog_content = "Será aún más difícil lidiar con ella si logra recolectar todos los módulos necesarios...",
  ui_story_6_1_3_dialog_content = "(Carleen y Vice están muy deprimidas. ¿Quizás debería decir algo?)",
  ui_story_6_1_F1_dialog_content = "Si buscamos a Schummer ahora, ¡podríamos evitar que obtenga el siguiente módulo!",
  ui_story_6_1_F2_dialog_content = "Obviamente, sería peligroso...",
  ui_story_6_1_4_option_content = "Entonces, ¿qué piensas, Carleen?",
  ui_story_6_1_5_dialog_content = "Estoy de acuerdo. No hay tiempo que perder. ¡Deberíamos perseguir a Schummer de inmediato!",
  ui_story_6_1_6_option_content = "¿Qué opinas, Vice?",
  ui_story_6_1_7_dialog_content = "Ya le envié un mensaje a HQ que estamos en camino al <color=#FFB400>Pasillo Susurrante</color>.",
  ui_story_6_1_8_dialog_content = "¿Alguien sabe algo sobre este Pasillo Susurrante?",
  ui_story_6_1_9_dialog_content = "Estoy bastante seguro de que está bajo el control de <color=#FFB400>Umbraton</color>, Carleen. Me enteré cuando era estudiante en Lumopolis.",
  ui_story_6_1_10_dialog_content = "Nada menos de un estudiante estrella como tú. ¿Apuesto a que podrías contarnos más?",
  ui_story_6_1_11_dialog_content = "Ejem, el Pasillo Susurrante es una ruina antigua en las afueras de Umbraton.",
  ui_story_6_1_12_dialog_content = "Después de que Lumopolis lo descubrió, las excavaciones revelaron una gran cantidad de valiosos hallazgos arqueológicos.",
  ui_story_6_1_13_dialog_content = "Sin embargo, una vez que no apareció nada de valor en nuevas excavaciones, el interés disminuyó y la ruina fue abandonada.",
  ui_story_6_1_14_dialog_content = "Desde entonces, se ha convertido en un centro para vagabundos y forajidos, y un semillero para el crimen.",
  ui_story_6_1_A1_dialog_content = "Hace aproximadamente una década, una organización conocida como la <color=#FFB400>Pandilla Istvan</color> apareció en Umbraton.",
  ui_story_6_1_A2_dialog_content = "Istvan, el líder y homónimo de la organización, disfruta de una alta reputación entre la gente de Umbraton, y se le conoce localmente como el \"Señor Sombrío.\"",
  ui_story_6_1_A3_dialog_content = "Apenas asumió el control del Pasillo Susurrante, se convirtió en un lugar donde nadie se atrevía a entrar como deseaba.",
  ui_story_6_1_A4_dialog_content = "Se rumorea que ahora es un depósito de todo tipo de antigüedades preciosas y desconocidas.",
  ui_story_6_1_A5_dialog_content = "Seguro que es conveniente tener una enciclopedia andante.",
  ui_story_6_1_F3_dialog_content = "¡Je, de nada!",
  ui_story_6_1_A6_dialog_content = "También envié un mensaje al Señor Sombrío solicitando su ayuda.",
  ui_story_6_1_A7_dialog_content = "Quién sabe, ¿quizás tenga a alguien esperando para guiarnos cuando lleguemos al Pasillo Susurrante?",
  ui_story_6_1_A8_dialog_content = "Si escribieras en tu estilo habitual, apuesto que el Señor Sombrío simplemente lo ignoraría.",
  ui_story_6_1_F4_dialog_content = "¡Oye, no importaba si era buena o no! ¡Tuve que enviarlo de cualquier manera!",
  ui_story_6_1_15_dialog_content = "Oh, tengo algo más para compartir. El ejército de Illumina acaba de celebrar otra reunión...",
  ui_story_6_1_16_dialog_content = "Permítanme recordarles a todos, que aunque el Pasillo Susurrante es el territorio del Señor Sombrío, dado quién es la amenaza...",
  ui_story_6_1_17_dialog_content = "Además de la participación de la Oficial de Tecnología Gronru, esto se considera una provocación flagrante.",
  ui_story_6_1_F5_dialog_content = "Si no fuera por PlayerName y la compañía que dio la noticia, los planes de Schummer probablemente hubieran permanecido desconocidos para nosotros.",
  ui_story_6_1_18_dialog_content = "Maldita sea, si no fuera por esos mocosos, ¡nada de esto habría sucedido!",
  ui_story_6_1_19_dialog_content = "Equivocado. La existencia de PlayerName no tiene nada que ver con el objetivo de Schummer de adquirir módulos.",
  ui_story_6_1_20_dialog_content = "¡Ahórrame el discurso, Hiiro! ¿Tus tropas vienen conmigo o no?",
  ui_story_6_1_21_dialog_content = "Bueno...",
  ui_story_6_1_22_dialog_content = "No es que no quiera hacerlo. Comparto tu mismo sentir con respecto a quienes amenazan Illumina.",
  ui_story_6_1_23_dialog_content = "Pero el Gran Mariscal nos ha ordenado que nos mantengamos alerta y esperemos la oportunidad adecuada.",
  ui_story_6_1_X23_dialog_content = "¿Por qué ordenó eso el Gran Mariscal?",
  ui_story_6_1_X24_dialog_content = "Mantengan la calma, todos. Entiendo como te sientes.",
  ui_story_6_1_X25_dialog_content = "Sin embargo, solo podemos quedarnos quietos y observar hasta que recibamos nuevas órdenes del Gran Mariscal.",
  ui_story_6_1_X26_dialog_content = "Es probable que comprenda la situación mucho mejor que nosotros. ¡Deberíamos creer en Illumina!",
  ui_story_6_1_X27_dialog_content = "...",
  ui_story_6_1_X28_dialog_content = "¿Dónde están Barton y su gente? ¿Por qué no aparecieron?",
  ui_story_6_1_X29_dialog_content = "Si él y esa musculosa accedían a movilizarse, al menos podríamos negociar con el Gran Mariscal por...",
  ui_story_6_1_X30_dialog_content = "¡Otros comandantes de la Legión también obtuvieron sus asignaciones provisionales!",
  ui_story_6_1_X31_dialog_content = "¡Vienes conmigo a defender los suburbios de Lumopolis, Sharona!",
  ui_story_6_1_25_dialog_content = "¡Cómo mínimo, todavía tenemos que montar un buen espectáculo!",
  ui_story_6_1_27_dialog_content = "Entonces esa es la situación actual. Estamos solos para descubrir qué está haciendo Schummer.",
  ui_story_6_1_28_dialog_content = "Tuvimos la suerte de contar con la ayuda de Philyshy y Gronru la última vez, pero esta vez...",
  ui_story_6_1_F6_dialog_content = "Nuestro destino está bajo jurisdicción de Umbraton, y Umbraton está justo debajo de Lumopolis...",
  ui_story_6_1_F7_dialog_content = "Comprendo. Illumina y Lumopolis pueden estar trabajando juntos, pero ambos tienen sus reservas.",
  ui_story_6_1_29_dialog_content = "Aun así, jugar a la política no hará ningún bien a ninguno de los bandos, especialmente dada la situación en la que nos encontramos ahora.",
  ui_story_6_1_30_dialog_content = "Déjame trabajar en el final de Lumopolis. Por lo menos...",
  ui_story_6_1_31_dialog_content = "¿Informe de estado, Capitán Carleen?",
  ui_story_6_1_32_dialog_content = "Mis disculpas, pero hemos fallado. Se ha tomado la <color=#FFB400>Unidad de Crecimiento Autónomo</color>.",
  ui_story_6_1_33_dialog_content = "¿Alguna baja?",
  ui_story_6_1_34_dialog_content = "Ninguna.",
  ui_story_6_1_35_dialog_content = "Desafortunadamente, están un paso por delante de nosotros y se han ido al Pasillo Susurrante.",
  ui_story_6_1_36_dialog_content = "Señor Schwartz, solicito humildemente la ayuda de los Guardianes, preferiblemente los Cuatro Ángeles.",
  ui_story_6_1_37_dialog_content = "Denegado.",
  ui_story_6_1_38_dialog_content = "Pero pad... Quiero decir, mi señor, si logra obtener el <color=#FFB400>Módulo de Control de Llamas</color>, ¡las consecuencias serían espantosas!",
  ui_story_6_1_39_dialog_content = "¡Incluso puede volver a amenazar a Lumopolis después de recargar su Colossus!",
  ui_story_6_1_40_dialog_content = "Sí, lo consideré, Capitán Carleen, y por eso decidí no enviar a los Guardianes.",
  ui_story_6_1_41_dialog_content = "Como su Capitán, tengo autoridad sobre los Guardianes, mi Señor. Permítame movilizarlos.",
  ui_story_6_1_42_dialog_content = "Podría fácilmente revocar esa autoridad, Capitán.",
  ui_story_6_1_43_dialog_content = "Luego, como Capitán, les proporcionaré refuerzos en nombre de Lumopolis, incluso si solo soy yo.",
  ui_story_6_1_45_dialog_content = "Admiro tu coraje, Carleen.",
  ui_story_6_1_46_dialog_content = "¡PlayerName! Como ciudadano de Lumopolis, espero que pueda garantizar la seguridad de la Capitana Carleen.",
  ui_story_6_1_47_dialog_content = "¿Qué...? Sí, claro.",
  ui_story_6_1_48_dialog_content = "<size=30>PlayerName y yo ni somos ciudadanos de Lumopolis...</size>",
  ui_story_6_1_49_dialog_content = "Incluso si Carleen no fuera Capitán, ¡nos protegeríamos mutuamente sin importar qué! ¡Eso es lo que hacen los amigos!",
  ui_story_6_1_50_dialog_content = "Corta la charla. ¡Deberíamos llegar pronto!",
  ui_story_6_1_51_dialog_content = "Esto es desierto hasta donde los ojos pueden ver. Nadie ha estado aquí durante mucho tiempo.",
  ui_story_6_1_52_dialog_content = "Afortunadamente, tenemos a Soroz, ¡o nunca podríamos alcanzar a Schummer!",
  ui_story_6_1_F8_dialog_content = "¿Escuchaste eso, Soroz? ¡Vice te está felicitando!",
  ui_story_6_1_53_dialog_content = "Mi propósito es servirte, Navegador. Es un honor para mí ayudarlos a todos.",
  ui_story_6_1_54_dialog_content = "Sin embargo, este lugar tiene el mismo aura siniestro que Eraveil... Ten cuidado.",
  ui_story_6_1_55_dialog_content = "Este lugar podría estar plagado de Eclipsites, PlayerName... ¿Soroz estará seguro aquí?",
  ui_story_6_1_56_dialog_content = "Está junto a las colinas, con un bosque lo suficientemente grande como para cubrirse.",
  ui_story_6_1_57_dialog_content = "No te preocupes, nuestro Colossus ha dominado el arte del camuflaje. Solo tenemos que concentrarnos en la pelea, y Soroz estará allí esperándonos cuando regresemos.",
  ui_story_6_1_58_dialog_content = "La sensación de tener a alguien esperándote cuando regreses es agradable. Ahora, si tan solo pudiera prepararnos un baño caliente para nosotros también...",
  ui_story_6_1_59_dialog_content = "Qué aplicación tan infantil para un Colossus...",
  ui_story_6_1_A9_dialog_content = "De todos modos, no veo dónde podría haber un depósito aquí en este desierto.",
  ui_story_6_1_A10_dialog_content = "La entrada al Pasillo Susurrante es imposible de encontrar si no investigas.",
  ui_story_6_1_A11_dialog_content = "Entonces, eso significa que ya has...",
  ui_story_6_1_A12_dialog_content = "¡Así es, está justo bajo de nuestros pies!",
  ui_story_6_1_A13_dialog_content = "¿Debajo de nosotros? ¿El Pasillo Susurrante es subterráneo?",
  ui_story_6_1_A14_dialog_content = "¡Cuida tus pies, estoy activando la entrada!",
  ui_story_6_1_A15_dialog_content = "¡El suelo se está cayendo a pedazos!",
  ui_story_6_1_A16_dialog_content = "Vaya, esto es...",
  ui_story_6_1_A17_dialog_content = "Muchos problemas que atravesar y construir. ¿Por qué alguien lo diseñaría así?",
  ui_story_6_1_A18_dialog_content = "Solo los delincuentes y los roedores optarían por esconderse en un agujero como este.",
  ui_story_6_1_A19_dialog_content = "El Pasillo Susurrante está justo debajo de nosotros. ¿Puedes sentir algo, PlayerName?",
  ui_story_6_1_60_dialog_content = "Schummer... Ella debería estar abajo. Puedo sentir un escalofrío extremo viniendo desde abajo.",
  ui_story_6_1_A20_dialog_content = "No estabas bromeando... ¡Hace mucho frío aquí abajo!",
  ui_story_6_1_A21_dialog_content = "Ahora no es el momento de quejarse. ¡Tenemos que darnos prisa!",
  ui_story_6_1_61_dialog_content = "¿Alguna forma de detectar su ubicación exacta?",
  ui_story_6_1_62_dialog_content = "Lo siento, solo puedo decir que está en algún lugar del Pasillo Susurrante. No puedo precisar su ubicación exacta.",
  ui_story_6_1_63_dialog_content = "Esto no será fácil...",
  ui_story_6_1_64_dialog_content = "Dicen que el Pasillo Susurrante es un laberinto lleno de puertas y pasadizos secretos... y que el Señor Sombrío es supuestamente el único que conoce cada rincón y grieta.",
  ui_story_6_1_65_dialog_content = "Esta es la razón principal por la que se cree que el Pasillo Susurrante es un depósito de artefactos de valor incalculable.",
  ui_story_6_1_F9_dialog_content = "Mantener las cosas aquí es mucho más seguro que esconderlas en Umbraton, eso es seguro.",
  ui_story_6_1_66_dialog_content = "¡Espera, viene alguien!",
  ui_story_6_1_67_dialog_content = "¡Cuidado! Podría ser una Eclipsite...",
  ui_story_6_1_68_dialog_content = "Teniendo en cuenta que PlayerName es tan tranquilo, solo puedo asumir que es un Aurorian.",
  ui_story_6_1_70_dialog_content = "Bueno, ¿qué tenemos aquí? Podía oírte parlotear a través de cada puerta y pared de este lugar, ¡sabes!",
  ui_story_6_1_71_dialog_content = "Que interesante... Una dama mimada de Lumopolis, una ingenua chica Illumina y un Celestita...",
  ui_story_6_1_72_dialog_content = "Parece ser el \"Escuadrón Colossus\" del que todos los grandes han estado hablando últimamente.",
  ui_story_6_1_73_dialog_content = "Lumopolis e Illumina se contentan con sentarse y mirar, pero el Señor Sombrío me eligió específicamente para ayudarte.",
  ui_story_6_1_X73_dialog_content = "Qué dolor real en el...",
  ui_story_6_1_74_dialog_content = "¡Supongo que tenemos tanta suerte!",
  ui_story_6_1_F10_dialog_content = "El nombre es Sheol. Entonces, ¿cómo puedo ser de ayuda?",
  ui_story_6_1_75_option_content = "¿Has visto a alguien más pasar por aquí?",
  ui_story_6_1_76_dialog_content = "Muy poca gente viene aquí. Un puñado de Eclipsites llegó recientemente, pero no se perdió nada.",
  ui_story_6_1_77_dialog_content = "Schummer...",
  ui_story_6_1_78_dialog_content = "Lo que más me preocupa es tu enemigo... Están aquí ahora mismo, ¿no?",
  ui_story_6_1_79_dialog_content = "Bueno, me preocupa más que nos espíes antes que decidas mostrarte.",
  ui_story_6_1_80_dialog_content = "¡Tus chicas son inteligentes, PlayerName!",
  ui_story_6_1_81_dialog_content = "Uh, Señorita Sheol, está bien si no quiere hablar de esto, pero ¿podría al menos contarnos sobre este lugar?",
  ui_story_6_1_82_dialog_content = "Bueno, es bien sabido que este lugar solía ser una gran ruina.",
  ui_story_6_1_83_dialog_content = "Como tal, no fue muy valioso... Así que el Señor Sombrío decidió comprarlo. Es el único que conoce el local por dentro y por fuera.",
  ui_story_6_1_84_dialog_content = "Aunque no hay guardias aquí, la mayoría de los intrusos de dos bits caen en una trampa o se pierden.",
  ui_story_6_1_85_dialog_content = "Es casi imposible encontrar lo que buscan... sin una guía adecuada, por supuesto.",
  ui_story_6_1_86_dialog_content = "Entonces, ¿quién es nuestro guía?",
  ui_story_6_1_87_dialog_content = "¿Ves a alguien más alrededor?",
  ui_story_6_1_88_dialog_content = "¡Oh ya veo! Entonces, por favor, dirige el camino.",
  ui_story_6_1_89_dialog_content = "¿Ah? ¿Cuándo acepté ser tu guía?",
  ui_story_6_1_90_dialog_content = "Tienes suerte, PlayerName, esta chica es tan dulce...",
  ui_story_6_1_91_dialog_content = "Creo que tienes una idea equivocada, Señorita Sheol.",
  ui_story_6_1_92_dialog_content = "¿Sabes lo que estamos buscando? ¿Has oído hablar del Módulo de Control de Llama?",
  ui_story_6_1_93_dialog_content = "Uh, no sé nada de eso.",
  ui_story_6_1_94_option_content = "¿Puedes hablarnos de este lugar?",
  ui_story_6_1_95_dialog_content = "Bueno, es bien sabido que este lugar solía ser una gran ruina.",
  ui_story_6_1_96_dialog_content = "Como tal, no fue muy valioso... Así que el Señor Sombrío decidió comprarlo. Es el único que conoce el local por dentro y por fuera.",
  ui_story_6_1_97_dialog_content = "Aunque no hay guardias aquí, la mayoría de los intrusos de dos bits caen en una trampa o se pierden.",
  ui_story_6_1_98_dialog_content = "Es casi imposible encontrar lo que buscan... sin una guía adecuada, por supuesto.",
  ui_story_6_1_99_dialog_content = "Entonces, ¿quién es nuestro guía?",
  ui_story_6_1_100_dialog_content = "¿Ves a alguien más alrededor?",
  ui_story_6_1_101_dialog_content = "¡Oh ya veo! Entonces, por favor, dirige el camino.",
  ui_story_6_1_102_dialog_content = "¿Cuándo dije que soy el guía, cariño?",
  ui_story_6_1_103_dialog_content = "PlayerName, tus amigos son tan amables y encantadores.",
  ui_story_6_1_104_dialog_content = "Uh, Señorita Sheol, por favor no cambie de tema. Estamos en apuros...",
  ui_story_6_1_105_dialog_content = "¿Lo estás? Oh, sí, tal vez tu enemigo ya esté aquí.",
  ui_story_6_1_106_dialog_content = "Hay pistas de Eclipsite por todas partes, y todas conducen al Pasillo Susurrante...",
  ui_story_6_1_107_dialog_content = "La situación aquí es bastante sombría, de hecho... ¡Lo que sea que estés buscando puede que ya te lo hayan quitado!",
  ui_story_6_1_108_dialog_content = "Entonces, ¿le importaría llevarnos al lugar donde se guarda el Módulo de Control de Llama?",
  ui_story_6_1_109_dialog_content = "¿El qué? Nunca lo oí.",
  ui_story_6_1_110_option_content = "De hecho, estamos buscando algo.",
  ui_story_6_1_111_dialog_content = "Lo sé. Todo el que viene aquí siempre está buscando algo. Pero creo que algunos Eclipsites podrían haberte adelantado.",
  ui_story_6_1_112_dialog_content = "Sé que hay Eclipsites aquí... ¡Tenemos que darnos prisa!",
  ui_story_6_1_113_dialog_content = "¿Cuál es la prisa?",
  ui_story_6_1_114_dialog_content = "Bueno, es bien sabido que este lugar solía ser una gran ruina.",
  ui_story_6_1_115_dialog_content = "Como tal, no fue muy valioso... Así que el Señor Sombrío decidió comprarlo. Es el único que conoce el local por dentro y por fuera.",
  ui_story_6_1_116_dialog_content = "Aunque no hay guardias aquí, la mayoría de los intrusos de dos bits caen en una trampa o se pierden.",
  ui_story_6_1_117_dialog_content = "Es casi imposible encontrar lo que buscan... sin una guía adecuada, por supuesto.",
  ui_story_6_1_118_dialog_content = "Entonces, ¿quién es nuestro guía?",
  ui_story_6_1_119_dialog_content = "¿Ves a alguien más alrededor?",
  ui_story_6_1_120_dialog_content = "¡Oh! Así veo. Entonces, por favor, dirige el camino.",
  ui_story_6_1_121_dialog_content = "¿Cuándo dije que sería el guía?",
  ui_story_6_1_122_dialog_content = "Tienes suerte, PlayerName. Esta chica es tan dulce.",
  ui_story_6_1_123_dialog_content = "No divaguemos, Señorita Sheol...",
  ui_story_6_1_124_dialog_content = "Señorita Sheol, ¿sabe entonces lo que estamos buscando? ¿Alguna vez has oído hablar del Módulo de Control de Llama?",
  ui_story_6_1_125_dialog_content = "Uh, no sé nada de eso.",
  ui_story_6_1_126_dialog_content = "<size=30>Ella está mintiendo.</size>",
  ui_story_6_1_127_dialog_content = "<size=30>Lo sé.</size>",
  ui_story_6_1_128_dialog_content = "Señorita Sheol, no tenemos la intención de entrometernos sin su consentimiento. Esa carta es la mejor prueba de nuestra sinceridad.",
  ui_story_6_1_129_dialog_content = "Lo sé. Entonces, ¿quieres detener a Schummer?",
  ui_story_6_1_130_dialog_content = "Sí. Creo que has oído lo que pasó en Lumopolis.",
  ui_story_6_1_131_dialog_content = "Schummer hará lo que sea necesario para apoderarse de él <color=#FFB400>Módulo de Control de Llama</color>.",
  ui_story_6_1_132_dialog_content = "Cuando descubrimos que tenía la intención de venir aquí, informamos inmediatamente al Señor Sombrío. Tememos si una gran cantidad de Eclipsites invaden...",
  ui_story_6_1_F11_dialog_content = "Umbraton puede estar en peligro. Es difícil no creerte, dada la sinceridad de tus palabras.",
  ui_story_6_1_F12_dialog_content = "¿Pero cómo sabes que ella viene aquí?",
  ui_story_6_1_F13_dialog_content = "Por favor, sepa que cuando digo esto, digo la verdad honesta... Puedo usar mis habilidades de Celestita para sentir su paradero.",
  ui_story_6_1_134_dialog_content = "Supongo que los Celestitas son dignos de su reputación. Bueno, para recompensarte por tu honestidad, seré tu guía.",
  ui_story_6_1_135_dialog_content = "Gracias, contamos contigo.",
  ui_story_6_1_136_dialog_content = "¡Qué dulce!",
  ui_story_6_1_137_dialog_content = "¿Ya llegamos? ¿Cuántos niveles más?",
  ui_story_6_1_138_dialog_content = "Ni por cerca... Llegamos a la periferia, queda mucho por recorrer.",
  ui_story_6_1_139_dialog_content = "Dios, este lugar es más confuso que Ciudad Gannon.",
  ui_story_6_1_140_dialog_content = "¿Por qué se guarda aquí el Módulo de Control de Llama?",
  ui_story_6_1_141_dialog_content = "Dicen que el Señor Sombrío lo encontró en un antiguo campo de batalla en la guerra contra los Eclipsites hace diez años.",
  ui_story_6_1_142_dialog_content = "Yo solo lo vi una vez. Parecía una vieja reliquia polvorienta.",
  ui_story_6_1_143_dialog_content = "Si no fuera por ti, tal vez hubiera permanecido escondido aquí para siempre.",
  ui_story_6_1_144_dialog_content = "Detente. Algo anda mal aquí...",
  ui_story_6_1_145_dialog_content = "Parece que alguien rompió esta puerta.",
  ui_story_6_1_146_dialog_content = "A juzgar por el daño, no creo que un Aurorian haya hecho esto.",
  ui_story_6_1_147_dialog_content = "¡Pero no quiero pelear!",
  ui_story_6_1_148_dialog_content = "PlayerName, ¿puedes sentir algo?",
  ui_story_6_1_149_dialog_content = "Schummer está aquí.",
  ui_story_6_1_150_dialog_content = "Así que se nos adelantó. ¿Qué tan lejos estamos de ella?",
  ui_story_6_1_151_dialog_content = "No lejos, pero tampoco cerca... Es posible que nos encontremos Eclipsites. Tengan cuidado, todos.",
  ui_story_6_1_152_dialog_content = "...",
  ui_story_6_1_153_dialog_content = "¡Todavía podemos ponernos al día! Existe la posibilidad de que se pierda sin un guía, pero tenemos...",
  ui_story_6_1_154_dialog_content = "Oye, guía, ¿a dónde vas? ¿Vamos al revés?",
  ui_story_6_1_155_dialog_content = "¿Estás retrocediendo, Señorita Sheol?",
  ui_story_6_1_156_dialog_content = "Bueno, esto es muy peligroso, después de todo. Señorita Sheol, no te forzaremos...",
  ui_story_6_1_157_dialog_content = "Es un plan peligroso, pero los que se acobardan en batalla solo auguran la perdición de sus aliados.",
  ui_story_6_1_158_dialog_content = "¿Cuándo dije que me estaba escapando? Dije que te guiaría, ¿no?",
  ui_story_6_1_159_dialog_content = "No soy buena luchadora, así que no puedo unirme a ti en batalla...",
  ui_story_6_1_160_dialog_content = "Pero, ¿cómo nos vas a orientar si no estás con nosotros? ¿Remotamente?",
  ui_story_6_1_161_dialog_content = "Como sugirió la dulce Vice, ¡me quedaré y mantendré contacto contigo desde aquí!",
  ui_story_6_1_162_dialog_content = "Siempre que me diga lo que puede ver a su alrededor, sabré exactamente dónde se encuentra.",
  ui_story_6_1_163_dialog_content = "Lo sé... Así se hacen las cosas en Umbraton, después de todo, Vice.",
  ui_story_6_1_164_dialog_content = "Pero no quise decir que debería guiarnos de forma remota. Señorita Sheol, creo que sería mejor que vayamos juntos.",
  ui_story_6_1_165_dialog_content = "¿Oh? ¡Eso tiene sentido! ¡Entonces te esperaré afuera! ¡Te guiaré de forma remota y me mantendré en contacto en todo momento!",
  ui_story_6_1_168_dialog_content = "Además, si logras salir con vida, PlayerName...",
  ui_story_6_1_169_dialog_content = "¡Recuerda visitar mi tienda! Te he conocido ahora, ¡habrá ofertas especiales para ti!",
  ui_story_6_1_170_dialog_content = "¡Buena suerte!",
  ui_story_6_1_171_dialog_content = "Creo que Señorita Sheol es una buena mujer de negocios...",
  ui_story_6_1_172_dialog_content = "¿Dije algo mal? ¿Fue todo el asunto de la \"guía remota\"?",
  ui_story_6_1_173_dialog_content = "No te preocupes, Vice. Debería irse ahora en lugar de abandonarnos cuando es necesario.",
  ui_story_6_1_174_dialog_content = "Envidio cómo siempre eres fresca como un pepino, Carleen...",
  ui_story_6_1_175_dialog_content = "No hay necesidad de entrar en pánico. Sea lo que venga, haré que se dé cuenta del error que fue venir aquí.",
  ui_story_6_2_X29_dialog_content = "¿Eh? Hmm...",
  ui_story_6_2_X30_dialog_content = "¿Oficial Charon? ¿Qué haces aquí haciendo todos los ruidos extraños?",
  ui_story_6_2_X31_dialog_content = "Srta. Philyshy, todavía se ve tan...",
  ui_story_6_2_X32_dialog_content = "Con insomnio.",
  ui_story_6_2_X33_dialog_content = "De hecho, estoy esperando a que los oficiales salgan de una reunión. Hay gastos detallados que quiero informar para el reembolso de Subciudad 28...",
  ui_story_6_2_X34_dialog_content = "¡Ya se fueron, miau! Quizás la próxima vez.",
  ui_story_6_2_X35_dialog_content = "¿Cómo pudieron desaparecer tan rápido? ¡Aún queda mucho subsidio por pagar!",
  ui_story_6_2_X36_dialog_content = "No hay nada que puedan hacer, miau. Todos recibieron órdenes urgentes a defender los suburbios, miau.",
  ui_story_6_2_X37_dialog_content = "Vice claramente les ha informado que la amenaza se encuentra en el <color=#FFB400>Pasillo Susurrante</color>...",
  ui_story_6_2_X38_dialog_content = "El Gran Mariscal tomó la decisión, pero no puedo entender por qué, miau...",
  ui_story_6_2_X39_dialog_content = "Más despacio, esto es mucho para asimilar a la vez.",
  ui_story_6_2_X40_dialog_content = "¿Puedes darme más detalles? ¿Vice y PlayerName están nuevamente en problemas?",
  ui_story_6_2_X41_dialog_content = "¿Problemas? ¿Cómo debería decir esto?, miau... Bien puede ser la <color=#FFB400>mayor crisis de la historia</color>, miau...",
  ui_story_6_2_X42_dialog_content = "¿¡Crisis!?",
  ui_story_6_2_1_dialog_content = "Parece que hemos recorrido una distancia muy larga.",
  ui_story_6_2_2_dialog_content = "Incluso puedo sentir la fuerte presencia de Eclipsites aquí.",
  ui_story_6_2_3_dialog_content = "¿Señorita Sheol?",
  ui_story_6_2_4_dialog_content = "¿Ah? Estoy aquí.",
  ui_story_6_2_6_dialog_content = "¿Estás perdido, querido?",
  ui_story_6_2_7_dialog_content = "No diría que estamos perdidos, pero este lugar es como un laberinto y es tan sombrío y deprimente.",
  ui_story_6_2_9_dialog_content = "Mira allá... Las huellas son muy extrañas. No solo huellas Eclipsites, sino también...",
  ui_story_6_2_10_dialog_content = "¿No son estas huellas dejadas por alguien que lleva botas de combate?",
  ui_story_6_2_11_dialog_content = "¿Botas de combate?",
  ui_story_6_2_12_dialog_content = "Estoy sintiendo Aurorians. ¿Puede ser un refuerzo?",
  ui_story_6_2_13_dialog_content = "Definitivamente botas estándar de Lumopolis. Estos fueron dejados por alguien de los Guardianes.",
  ui_story_6_2_14_dialog_content = "Las huellas siguen siendo claras, sin signos de combate, ni siquiera signos de pánico.",
  ui_story_6_2_15_dialog_content = "¿Sacaste todo eso de las huellas de las botas?",
  ui_story_6_2_16_dialog_content = "<color=#FFB400>Gertzurde</color>.",
  ui_story_6_2_X16_dialog_content = "¿Gertzurde? Si mal no recuerdo...",
  ui_story_6_2_17_option_content = "Escuché ese nombre cuando estábamos cazando a Shelt.",
  ui_story_6_2_18_option_content = "¿El ladrón que robó\nel Módulo Think Tank?",
  ui_story_6_2_19_dialog_content = "Correcto, pero ¿no desapareció Gertzurde?",
  ui_story_6_2_20_dialog_content = "El desertó. Tenemos pruebas irrefutables de que se unió al Eclipse.",
  ui_story_6_2_21_dialog_content = "Él y su amante han estado sirviendo a los Eclipsites durante mucho tiempo. Son una mancha en Lumopolis.",
  ui_story_6_2_22_dialog_content = "Caminó por este lugar con los Eclipsites, con botas de combate...",
  ui_story_6_2_23_dialog_content = "¡Solo puede ser Gertzurde!",
  ui_story_6_2_24_dialog_content = "¿Por qué hizo eso?",
  ui_story_6_2_25_dialog_content = "Nadie sabe.",
  ui_story_6_2_26_dialog_content = "Se dice que Gertzurde fue diligente en el trabajo y hasta fue héroe de guerra, por lo que nadie sospechó de él.",
  ui_story_6_2_27_dialog_content = "Será que Gertzurde guarda rencor por lo que sucedió con Shelt y vino aquí para...",
  ui_story_6_2_28_dialog_content = "Que venga el perro callejero.",
  ui_story_6_2_29_dialog_content = "¡Si lo veo, lo enterraré aquí, junto a Schummer!",
  ui_story_6_2_30_dialog_content = "Caray, esto es molesto. ¡Los pasajes son interminables y siento que me vigilan constantemente!",
  ui_story_6_2_31_dialog_content = "¡Esto apesta! Cántame una canción, Gertzurde.",
  ui_story_6_2_32_dialog_content = "...",
  ui_story_6_2_33_dialog_content = "¿Qué pasa con esa mirada, Gertzurde?",
  ui_story_6_2_34_dialog_content = "Los que asesinaron a Shelt están aquí. ¿No deberías cantar de alegría?",
  ui_story_6_2_35_dialog_content = "Están detrás de nosotros, como dijiste...",
  ui_story_6_2_36_dialog_content = "Los que mataron a Shelt se acercan, ¿no?",
  ui_story_6_2_37_dialog_content = "Correcto. Sabía que los matorrales no podrían detenerlos... Algo que no les falta es la tenacidad.",
  ui_story_6_2_39_dialog_content = "Acaso Shelt...",
  ui_story_6_2_40_dialog_content = "Terminó horrible, Gertzurde. Incluso me estremezco al pensar en lo terrible que fue.",
  ui_story_6_2_41_dialog_content = "¡Por qué! Ellas...",
  ui_story_6_2_42_dialog_content = "¡Shelt dijo que era una misión de gloria! ¿Por qué no te pidió ayuda a ti y a ESA persona?",
  ui_story_6_2_A1_dialog_content = "La conozco. Definitivamente habría pedido ayuda... Eso significa...",
  ui_story_6_2_43_dialog_content = "¿Por qué estas gritando?",
  ui_story_6_2_44_dialog_content = "Lo siento.",
  ui_story_6_2_45_dialog_content = "Dijeron que fue PlayerName quien jugó el papel clave en la desaparición de la pobre Shelt.",
  ui_story_6_2_46_dialog_content = "Baja Lumopolis se convirtió en un desastre después de que liberaste a Shelt, y Zona residencial no estaba de humor para hacer nada al respecto.",
  ui_story_6_2_47_dialog_content = "Pero PlayerName y esos dos perros feroces todavía le pisaban los talones.",
  ui_story_6_2_48_dialog_content = "¿Qué pasa? ¿No tienen piedad?",
  ui_story_6_2_49_dialog_content = "Lo sé. ¿Qué tipo de ley mataría a un ladrón que no roba?",
  ui_story_6_2_50_dialog_content = "Forzaron a Shelt y su hermana a... eh... a fusionarse en un monstruo repugnante.",
  ui_story_6_2_51_dialog_content = "Shelt, oh, Shelt...",
  ui_story_6_2_52_dialog_content = "Si hay algo que quieras hacer en particular, esta es tu oportunidad.",
  ui_story_6_2_53_dialog_content = "El Módulo de Control de Llama que buscaba está más adelante. Entonces, ¿cuál es tu próximo plan?",
  ui_story_6_2_54_dialog_content = "¡PlayerName!",
  ui_story_6_2_55_dialog_content = "¿Oh? Parece que estás listo para la venganza.",
  ui_story_6_2_56_dialog_content = "¡Achuu!",
  ui_story_6_2_57_dialog_content = "¿Esto es demasiado frío para ti, PlayerName?",
  ui_story_6_2_58_dialog_content = "No, de repente se me puso la piel de gallina.",
  ui_story_6_2_59_dialog_content = "Después de todo, PlayerName, eres un Celestita. Quizás el Darkflow aquí es muy intenso para ti.",
  ui_story_6_2_60_dialog_content = "Pero espera, todavía tenemos muchos enemigos que eliminar.",
  ui_story_6_2_61_dialog_content = "Lo haré. Continuemos.",
  ui_story_6_6_1_dialog_content = "Señorita Sheol, ¡creo que llegamos a un punto extraño!",
  ui_story_6_6_2_dialog_content = "Nom, nom... ¿Qué fue eso?",
  ui_story_6_6_3_dialog_content = "¿Estás comiendo, Señorita Sheol?",
  ui_story_6_6_4_dialog_content = "Estaba disfrutando mi hora del té. ¿Qué está pasando?",
  ui_story_6_6_5_dialog_content = "Nos gustaría saber si este pasaje nos llevará a donde está el <color=#FFB400>Módulo de Control de Llama</color> .",
  ui_story_6_6_6_dialog_content = "¿Qué pasa? ¡Por supuesto! Tuve que luchar para recordar dónde estaba esa cosa.",
  ui_story_6_6_7_dialog_content = "Tienes que aprender a confiar en los demás. ¡Oh, por cierto, deberías tener cuidado con las trampas que hay más adelante!",
  ui_story_6_6_8_dialog_content = "Espera, estoy sintiendo...",
  ui_story_6_6_9_dialog_content = "¿Eclipsites?",
  ui_story_6_6_10_dialog_content = "No, un Aurorian...",
  ui_story_6_6_11_dialog_content = "¿Aurorian? Señorita Sheol, nadie entró, ¿verdad?",
  ui_story_6_6_12_dialog_content = "Ni siquiera una mosca.",
  ui_story_6_6_13_dialog_content = "Tiene que ser Gertzurde. Temo que nos esté esperando una emboscada.",
  ui_story_6_6_14_dialog_content = "¿Emboscada?",
  ui_story_6_6_15_dialog_content = "Veo una intersección más adelante y una trampa.",
  ui_story_6_6_16_dialog_content = "Cuando se tiene en cuenta que el techo en ruinas podría derrumbarse o simplemente hundirse en cualquier momento... ¡Es perfecto para una emboscada!",
  ui_story_6_6_17_dialog_content = "Aunque una vez fue un caballero, desertó a Eclipse. Nadie sabe de lo que es capaz ahora.",
  ui_story_6_6_18_dialog_content = "Déjame tomar la iniciativa. Le daré a Gertzurde el final que se merece.",
  ui_story_6_7_1_dialog_content = "¡Uf, estuvo cerca! ¡Habríamos caído en un pozo si no fuera por Carleen!",
  ui_story_6_7_2_dialog_content = "Oye, ¿no te di muchas advertencias?",
  ui_story_6_7_3_dialog_content = "Por ejemplo, ¡la trampa del tambor de aceite que casi aplasta a nuestro querido PlayerName!",
  ui_story_6_7_4_dialog_content = "Casi me muero de miedo...",
  ui_story_6_7_5_dialog_content = "Esa es la estrategia de Gertzurde ahora. Se ha vuelto tan desvergonzado y despreciable como los Eclipsites...",
  ui_story_6_7_6_dialog_content = "Hablando del diablo...",
  ui_story_6_7_7_dialog_content = "Mataste a Shelt.",
  ui_story_6_7_8_dialog_content = "Tu... mataste a... ¡Shelt!",
  ui_story_6_7_9_dialog_content = "Tal como esperaba, estás aquí por venganza.",
  ui_story_6_7_10_dialog_content = "¿Venganza? Sí. Es una lástima que escapaste de mis trampas, porque...",
  ui_story_6_7_11_dialog_content = "Matarte no abatirá mi odio.",
  ui_story_6_7_F1_dialog_content = "Traidor, ¿quieres matarnos?",
  ui_story_6_7_12_dialog_content = "Gertzurde, como caballero de Lumopolis, has perdido tu honor y te has pasado a los Eclipsites. ¡Nunca te perdonaré!",
  ui_story_6_7_13_dialog_content = "¿Nunca me perdonarás? ¿Necesito tu perdón? Sí, solía ser un caballero de Lumopolis, ¡pero ahora soy uno de la élite Eclipsite!",
  ui_story_6_7_14_dialog_content = "¡Todo fue por ella! Pero tú, tú...",
  ui_story_6_7_15_dialog_content = "Eres mucho más cruel que los Eclipsites... ¡Torturaste y mataste a Shelt!",
  ui_story_6_7_16_dialog_content = "¡Shelt y su hermana, eligieron la muerte, Gertzurde!",
  ui_story_6_7_17_dialog_content = "Gertzurde, buscaron la muerte para liberarse.",
  ui_story_6_7_18_dialog_content = "¡Imposible!",
  ui_story_6_7_19_dialog_content = "Shelt... Anhelaba ser libre. ¿Por qué se quitaría la vida si no la obligaste?",
  ui_story_6_7_20_dialog_content = "Schummer te envió a detenernos, ¿no es así?",
  ui_story_6_7_21_dialog_content = "¡No, vine para vengarme de ti, de Lumopolis!",
  ui_story_6_7_22_dialog_content = "En cuanto a Schummer, lo que ella quiere no tiene nada que ver conmigo.",
  ui_story_6_7_23_dialog_content = "¿Un traidor que busca venganza por un topo?",
  ui_story_6_7_27_dialog_content = "...",
  ui_story_6_7_28_dialog_content = "Cuidado, Carleen, su odio parece hacerse cada vez más fuerte...",
  ui_story_6_7_29_dialog_content = "¿Odio? Eso es algo natural para los traidores.",
  ui_story_6_7_30_dialog_content = "Porque han sido llevados a la desesperación, porque sólo conocen el odio.",
  ui_story_6_7_31_dialog_content = "Odian a quienes los juzgan, odian su pasado insoportable y odian el futuro que nunca tendrán.",
  ui_story_6_7_32_dialog_content = "No hay nada que negociar con una escoria como él.",
  ui_story_6_7_33_dialog_content = "Eres la capitana de los Guardianes e hija del Señor de la Ciudad de Lumopolis. ¿Cómo es posible que lo entiendas?",
  ui_story_6_7_34_dialog_content = "¡Incluso si no fuera un traidor, todavía no entenderías mi odio!",
  ui_story_6_7_35_dialog_content = "¡Te odio por matar a Shelt!",
  ui_story_6_7_36_dialog_content = "Sí, se convirtió en una Eclipsite, y como enemiga de ustedes Aurorians, morir en batalla contra ustedes es su destino.",
  ui_story_6_7_37_dialog_content = "¡Pero ustedes fueron los que la hicieron así! ¡Tú tienes la culpa!",
  ui_story_6_7_38_dialog_content = "¡Está cambiando de forma!",
  ui_story_6_7_39_dialog_content = "Venganza... Mi venganza es como la tuya, PlayerName.",
  ui_story_6_7_40_dialog_content = "Somos iguales, en un camino de venganza sin retorno...",
  ui_story_6_7_41_dialog_content = "¿Lo mismo? ¿Qué quieres decir?",
  ui_story_6_7_42_dialog_content = "¡Tú te convertiste en un Eclipsite! ¿Obtuviste este poder de tu maestro?",
  ui_story_6_7_43_dialog_content = "¡Venganza! ¡Moriremos de la mano, PlayerName!",
  ui_story_6_7_44_dialog_content = "¡Viajemos al mundo más allá de la muerte y busquemos juntos el perdón de Shelt!",
  ui_story_6_7_45_dialog_content = "¡Vuelve, PlayerName! ¡No tendremos ninguna oportunidad sin ti!",
  ui_story_6_7_X45_dialog_content = "Perdí, Shelt...",
  ui_story_6_7_48_dialog_content = "¿Listo para tu veredicto, traidor?",
  ui_story_6_7_49_dialog_content = "...",
  ui_story_6_7_50_dialog_content = "¿Sin palabras? ¿Finalmente sientes remordimiento ante la muerte?",
  ui_story_6_7_51_dialog_content = "No, no me arrepiento. Sé cómo terminará para mí.",
  ui_story_6_7_52_dialog_content = "Solo quiero saber qué sucedió en los momentos finales de Shelt.",
  ui_story_6_7_53_dialog_content = "¡No necesitas saberlo!",
  ui_story_6_7_F2_dialog_content = "¡Espera un minuto! Podemos explicar...",
  ui_story_6_7_54_dialog_content = "Alcanzamos a Shelt, pero todo lo que queríamos hacer era averiguar qué estaban haciendo.",
  ui_story_6_7_55_dialog_content = "Exacto. Nunca tuvimos la intención de matarlas.",
  ui_story_6_7_56_dialog_content = "Pero, ansiosas por escapar, buscaron la ayuda de un líder Eclipsite.",
  ui_story_6_7_57_dialog_content = "¿Schummer?",
  ui_story_6_7_58_dialog_content = "No, esa aura era diferente a la de Schummer. Pertenecía a otra persona, incluso más poderosa que Schummer.",
  ui_story_6_7_59_dialog_content = "Entonces comenzó una transformación aterradora... Sus cuerpos se fundieron como cera de velas...",
  ui_story_6_7_60_dialog_content = "No es que eligieran convertirse en uno. Era más como...",
  ui_story_6_7_61_dialog_content = "Era más como si fueran empujados a fusionarse por una fuerza abrumadora...",
  ui_story_6_7_62_dialog_content = "¿¡Qué paso después!?",
  ui_story_6_7_63_dialog_content = "Tuvimos que matar a Shelt.",
  ui_story_6_7_64_dialog_content = "¿Murió de dolor?",
  ui_story_6_7_65_dialog_content = "Bueno...",
  ui_story_6_7_66_option_content = "Ella murió de una muerte muy agonizante.",
  ui_story_6_7_67_dialog_content = "<anim type=Shake><size=45>¡Agonizante!</size></anim>",
  ui_story_6_7_69_dialog_content = "Antes de que decidiéramos luchar contra ella, alguien les impuso un poder desconocido...",
  ui_story_6_7_70_dialog_content = "Los obligó a fusionarse, y los dos se convirtieron en un Eclipsite. Ésta era la fuente de su dolor.",
  ui_story_6_7_71_option_content = "Lo hicimos rápido.",
  ui_story_6_7_72_dialog_content = "¿Entonces la liberaste?",
  ui_story_6_7_73_dialog_content = "Sí. Porque no podíamos soportar verla sufrir.",
  ui_story_6_7_74_dialog_content = "Antes de que decidiéramos luchar contra ella, alguien les impuso un poder desconocido...",
  ui_story_6_7_75_dialog_content = "Los obligó a fusionarse, y los dos se convirtieron en un Eclipsite. Ésta era la fuente de su dolor.",
  ui_story_6_7_76_dialog_content = "Quizás su dolor también provenía de su propio arrepentimiento.",
  ui_story_6_7_78_dialog_content = "Especialmente Shelt. Podía sentir que ella no quería pelear con nosotros.",
  ui_story_6_7_79_dialog_content = "Solo quería escapar, huir de Lumopolis e irse muy, muy lejos...",
  ui_story_6_7_80_dialog_content = "Parecía haber mencionado algo sobre una flor al final.",
  ui_story_6_7_81_dialog_content = "¿Flor?",
  ui_story_6_7_82_option_content = "Diente de León.",
  ui_story_6_7_83_dialog_content = "<size=45>¡...!</size>",
  ui_story_6_7_84_dialog_content = "No significó nada para nosotros, pero tú... debes saberlo.",
  ui_story_6_7_85_dialog_content = "Lo siento mucho, Shelt, lo siento mucho...",
  ui_story_6_7_86_dialog_content = "Me lo dijiste y debería haberme dado cuenta. Tuvimos nuestra oportunidad en ese entonces...",
  ui_story_6_7_87_dialog_content = "¡Gertzurde, Gertzurde! ¿Algo divertido que hacer cerca?",
  ui_story_6_7_88_dialog_content = "¿Quieres ir a alguna parte?",
  ui_story_6_7_89_dialog_content = "Sí, pero no solo por diversión. ¿Conoces el Pasillo Susurrante?",
  ui_story_6_7_90_dialog_content = "Parece ser un lugar muy apartado, uno en el que nadie nos encontrará, ¡donde podemos vivir para siempre!",
  ui_story_6_7_91_dialog_content = "O podría ser el desierto de Rediesel. Sin embargo, eso es demasiado caliente.",
  ui_story_6_7_92_dialog_content = "¿Estás pensando en salir de Lumopolis? ¿Es porque ofendiste a la nobleza?",
  ui_story_6_7_93_dialog_content = "No, es el Eclipse.",
  ui_story_6_7_94_dialog_content = "Quiero convertirme en diente de león.",
  ui_story_6_7_95_dialog_content = "¿Ah? ¿Qué provocó eso?",
  ui_story_6_7_96_dialog_content = "Porque nunca puedes retener los dientes de león. Se dispersan en miles de pequeñas versiones de sí mismos y desaparecen con el viento.",
  ui_story_6_7_97_dialog_content = "Pueden volar a cualquier parte del mundo.",
  ui_story_6_7_98_dialog_content = "Las \"pequeñas versiones de sí mismos\" son en realidad las semillas. Además, ¿y si caen al agua?",
  ui_story_6_7_99_dialog_content = "Tsk... ¡Cómo sea, no voy a hablar más de eso!",
  ui_story_6_7_100_dialog_content = "Libertad... Sí, Shelt a menudo hablaba de querer irse de Lumopolis debido al Eclipse.",
  ui_story_6_7_101_dialog_content = "Dijo que quería irse conmigo, libre como un diente de león.",
  ui_story_6_7_102_dialog_content = "Eres una tonta, Gertzurde. El Eclipse es el final de todo. No, es la Verdad...",
  ui_story_6_7_103_dialog_content = "¿PlayerName es realmente el que asesinó a Shelt?",
  ui_story_6_7_104_dialog_content = "Ya te he contado lo que pasó, pero sigues haciéndome todas estas preguntas. Quizás esperaba demasiado de ti.",
  ui_story_6_7_105_dialog_content = "Deja a un lado tu debilidad y deja de dudar de nosotros, Gertzurde.",
  ui_story_6_7_106_dialog_content = "Solo recuerda, podrían haber vivido, pero PlayerName reescribió su destino.",
  ui_story_6_7_107_dialog_content = "Y también reescribiste tu destino...",
  ui_story_6_7_108_dialog_content = "¡No, no! ¡No es verdad, no es verdad!",
  ui_story_6_7_109_dialog_content = "¡Gertzurde!",
  ui_story_6_7_110_dialog_content = "Yo... Yo... Shelt... Shelt quería irse... ¿Por qué elegiría fusionarse? ¿¡Por qué!?",
  ui_story_6_7_111_dialog_content = "Somos incapaces de manipular a Darkflow. Solo Darkflow podría haber hecho que las hermanas se fusionaran en un Eclipsite.",
  ui_story_6_7_112_dialog_content = "Incluso si no fue Schummer quien les infundió el Darkflow, los Eclipsites que lo hicieron estaban bajo su mando.",
  ui_story_6_7_113_dialog_content = "¡Debe ser, debe ser, debe ser ese bastardo...!",
  ui_story_6_7_114_dialog_content = "Cuéntanos lo que sabes, Gertzurde.",
  ui_story_6_7_116_dialog_content = "...",
  ui_story_6_7_119_dialog_content = "<color=#FFB400>Schummer</color>, sé dónde está.",
  ui_story_6_8_1_dialog_content = "¿Realmente nos llevarás a Schummer, Carleen?",
  ui_story_6_8_2_dialog_content = "Es extraño que no nos hayamos encontrado con ningún Eclipsite en el camino. ¿Podría ser esta otra trampa?",
  ui_story_6_8_F1_dialog_content = "¿Y qué, si es una trampa?",
  ui_story_6_8_3_dialog_content = "Si me traiciona de nuevo, lo golpearé de nuevo, pero esta vez, no mostraré piedad.",
  ui_story_6_8_F2_dialog_content = "...",
  ui_story_6_8_4_dialog_content = "Lo siento, Gertzurde. Todavía tenemos nuestras dudas sobre ti, pero si tienes algo que decir por ti mismo, dínoslo.",
  ui_story_6_8_5_dialog_content = "¿Qué puede decir un traidor de sí mismo?",
  ui_story_6_8_6_dialog_content = "Traidor, eh... Una vez fui campeón de Lumopolis.",
  ui_story_6_8_7_dialog_content = "Fui nombrado caballero a los dieciocho años, por el propio Señor de la Ciudad.",
  ui_story_6_8_8_dialog_content = "¿Conoces la <color=#FFB400>Crisis de Darkover</color>?",
  ui_story_6_8_9_dialog_content = "Es la guerra que comenzó hace 17 años y duró mucho tiempo...",
  ui_story_6_8_10_dialog_content = "Hace diecisiete años, los Eclipsites asaltaron Eraveil, hogar de los Celestitas. Este ataque se produjo sin ningún presagio, sorprendiendo incluso a Lumopolis.",
  ui_story_6_8_11_dialog_content = "Muy poco después, recibimos órdenes de intensificar nuestro entrenamiento, como respuesta a la posibilidad de un ataque Eclipsite a gran escala.",
  ui_story_6_8_12_dialog_content = "Yo era más joven que tú ahora cuando recibí mis órdenes y acababa de convertirme en escudero.",
  ui_story_6_8_13_dialog_content = "Entrené duro y pasé los siguientes cuatro años como reserva en los Guardianes de Lumopolis.",
  ui_story_6_8_14_dialog_content = "Entonces llegó tu oportunidad.",
  ui_story_6_8_15_dialog_content = "Sí. Fue una hermosa mañana. Lumopolis envió tropas para luchar contra los Eclipsites que atacaban Umbraton, ya que las defensas de la ciudad eran inadecuadas.",
  ui_story_6_8_16_dialog_content = "Algunos Eclipsites lograron entrar en Baja Lumopolis. Me encargué de aceptar el desafío y salvé a una noble chica en apuros.",
  ui_story_6_8_19_dialog_content = "Más tarde, fui asignado a luchar como miembro de los Guardianes, debido a mi valentía...",
  ui_story_6_8_20_dialog_content = "El Señor de la Ciudad me nombró caballero personalmente poco después de mi regreso.",
  ui_story_6_8_22_dialog_content = "Suena como un gran comienzo.",
  ui_story_6_8_23_dialog_content = "Sí, con un final de cuento de hadas, donde el caballero se casó con la princesa.",
  ui_story_6_8_27_dialog_content = "Un mes después, la noble chica y yo nos casamos.",
  ui_story_6_8_28_dialog_content = "Ese era Shelt, ¿verdad?",
  ui_story_6_8_29_dialog_content = "No.",
  ui_story_6_8_30_dialog_content = "Te refieres a...",
  ui_story_6_8_31_dialog_content = "Ella era la segunda hija de una gran familia noble.",
  ui_story_6_8_32_dialog_content = "La brecha entre nuestras estaciones fue imposible de cerrar, a pesar de mis esfuerzos.",
  ui_story_6_8_33_dialog_content = "La familia de mi esposa era tanto su fortaleza como su debilidad.",
  ui_story_6_8_34_dialog_content = "Nuestra relación se enfrió desde un dulce romance, luego vino el desapego, las comparaciones, la decepción, la queja, las peleas y finalmente la apatía.",
  ui_story_6_8_35_dialog_content = "En unos pocos años, no era más que una piedritas a en sus ojos.",
  ui_story_6_8_36_dialog_content = "Ella deseaba que yo desapareciera. Y luego conocí a Shelt.",
  ui_story_6_8_45_dialog_content = "Ella me inspiró cuando me había estancado y encendió la pasión de mi yo más joven.",
  ui_story_6_8_46_dialog_content = "La vista de ella me recordó mis días de gloria.",
  ui_story_6_8_47_dialog_content = "La familia y el estatus no eran nada. Solo quería ganar méritos en la batalla y ganarme el corazón de mi dama...",
  ui_story_6_8_49_dialog_content = "¡Suficiente! Nadie siente lástima por ti, Gertzurde.",
  ui_story_6_8_50_dialog_content = "¡Mira lo que has hecho realmente!",
  ui_story_6_8_51_dialog_content = "¡Engañar a tu esposa, conspirar con Eclipsites, atacar a los guardias y robar el Módulo Think Tank!",
  ui_story_6_8_53_dialog_content = "Puede que hayas sido un campeón de Lumopolis antes, ¡pero ahora no eres más que un pecador traicionero!",
  ui_story_6_8_54_dialog_content = "Sí, traicioné a Lumopolis. Sin excusas ni perdones.",
  ui_story_6_8_F3_dialog_content = "Pero no creo que haya hecho nada malo. Todo lo que hice fue en nombre del amor verdadero...",
  ui_story_6_8_55_dialog_content = "No lo entiendo. ¡Es ridículo!",
  ui_story_6_8_63_dialog_content = "Entonces, ¿se acabó la historia?",
  ui_story_6_8_64_dialog_content = "Lo siento, Señorita Sheol. ¡Olvidé que estabas aquí!",
  ui_story_6_8_65_dialog_content = "Solo quiero señalar que Gertzurde no te engañó.",
  ui_story_6_8_66_dialog_content = "Te llevó por una ruta idéntica a la que yo conozco. De hecho, incluso eludió lugares que en realidad podrían ser trampas.",
  ui_story_6_8_67_dialog_content = "...",
  ui_story_6_8_68_dialog_content = "No necesito tu comprensión. Te lo dije, te llevaré a Schummer. Entonces tengo mis propios asuntos que resolver.",
  ui_story_6_9_1_dialog_content = "Je, un cuidador de cercas siempre se sentará en la cerca.",
  ui_story_6_9_2_dialog_content = "¿Te refieres a Gertzurde?",
  ui_story_6_9_3_dialog_content = "Parece que no eres tan persuasivo como PlayerName.",
  ui_story_6_9_4_dialog_content = "¿Y qué? Sabía que Gertzurde se volvería contra nosotros. Es solo que las cosas resultaron un poco diferentes de lo que esperaba.",
  ui_story_6_9_5_dialog_content = "¿Por PlayerName?",
  ui_story_6_9_6_dialog_content = "Sí. No esperaba que perdonaran a Gertzurde. Debe ser PlayerName, tan moralista...",
  ui_story_6_9_7_dialog_content = "Qué inteligente, debería decir. Deja de asumir, Schummer, que pensar no te va bien.",
  ui_story_6_9_8_dialog_content = "Te romperé el cuello algún día...",
  ui_story_6_9_9_dialog_content = "De todos modos, estoy mucho más cerca de eso que ellos. Ya puedo oler el <color=#FFB400>Módulo de Control de Llama</color>.",
  ui_story_6_9_10_dialog_content = "Cuando lo consiga, todo lo que tengo que hacer es esperar a que PlayerName esté allí, luego...",
  ui_story_6_9_11_dialog_content = "Mátalos a todos.",
  ui_story_6_9_12_dialog_content = "Bien, mátalos a todos. Me gusta el sonido de eso.",
  ui_story_6_9_13_dialog_content = "Sí, pero eso se debe simplemente a tu vocabulario limitado. Aún así, procede con precaución. Tienen Lumopolis e Illumina como respaldo.",
  ui_story_6_9_14_dialog_content = "Ninguna de sus tropas vendrá. Los Aurorians están ocupados dudando entre sí.",
  ui_story_6_9_15_dialog_content = "¿Quieres venir a verlo? Será divertido ver sus reacciones.",
  ui_story_6_9_16_dialog_content = "No, gracias. Sabes que no me gusta ensuciarme las manos.",
  ui_story_6_9_17_dialog_content = "Pero puedo enviarte ayuda... No, haz que sea un <color=#FFB400>regalo</color>, un regalo para ellos.",
  ui_story_6_9_18_dialog_content = "¿Ayuda? ¿Regalo? ¿Es en quien estoy pensando?",
  ui_story_6_9_19_dialog_content = "Sí, su <color=#FFB400>viejo amigo</color>, a quien he mejorado.",
  ui_story_6_9_20_dialog_content = "Veo que también sabes cómo entretenerte, manteniéndote ocupado con todas estas \"creaciones.\"",
  ui_story_6_9_21_dialog_content = "Todo esto conduce a la realización de mi plan, mientras que todo lo que estás haciendo es causar problemas.",
  ui_story_6_9_22_dialog_content = "¿Y tú no?",
  ui_story_6_9_23_dialog_content = "Eso es suficiente. Echa un vistazo a este regalo...",
  ui_story_6_9_24_dialog_content = "Oh, es bonito. ¿Cómo se sentirá PlayerName al ver a este viejo amigo?",
  ui_story_6_9_25_dialog_content = "Casi no puedo esperar a ver...",
  ui_story_6_9_A1_dialog_content = "¿Cuánto más lejos, Gertzurde?",
  ui_story_6_9_A2_dialog_content = "No mucho. Créeme. Quiero ver a esa hipócrita más que tú.",
  ui_story_6_9_A3_dialog_content = "...",
  ui_story_6_9_A4_dialog_content = "Schummer dejó atrás a Eclipsites para emboscarte. Son poderosos luchadores, ¿verdad? Entonces, haz lo que mejor sabes hacer.",
  ui_story_6_13_1_dialog_content = "¿Es ese el final del Pasillo Susurrante por delante?",
  ui_story_6_13_2_dialog_content = "Sí, y sin duda Schummer está cerca.",
  ui_story_6_13_3_dialog_content = "Puedo sentir su aura allí.",
  ui_story_6_13_5_dialog_content = "Busca una botella de vidrio gigante con un número en la parte inferior.",
  ui_story_6_13_6_dialog_content = "Hmm, he olvidado qué era exactamente. Debería ser...",
  ui_story_6_13_7_dialog_content = "<color=#FFB400>RX6007</color>.",
  ui_story_6_13_8_dialog_content = "¡Si eso es! ¡Ese es el número de almacenamiento para eso! ¿Cómo lo supiste?",
  ui_story_6_13_10_dialog_content = "Schummer lo mencionó de pasada y recuerdo todo lo que escuché.",
  ui_story_6_13_11_dialog_content = "Ya sea información o memoria pasada, es una maldición.",
  ui_story_6_13_12_dialog_content = "Cuando llegue a este artículo numerado, lo que está buscando no estará muy lejos.",
  ui_story_6_13_14_dialog_content = "Ten cuidado. Si Schummer conoce el número, eso significa...",
  ui_story_6_13_16_dialog_content = "Sabía dónde encontrarlo y probablemente ya nos esté esperando allí.",
  ui_story_6_14_1_dialog_content = "Ah, nos volvemos a encontrar.",
  ui_story_6_14_2_dialog_content = "Schu...",
  ui_story_6_14_3_dialog_content = "¡Schummer!",
  ui_story_6_14_4_dialog_content = "Te ves enojado. ¿Es porque PlayerName te ganó?",
  ui_story_6_14_5_dialog_content = "¿Estás preso? ¿Debería rescatarte para que puedas tener una revancha?",
  ui_story_6_14_6_dialog_content = "Tú y ella, ambos me mintieron. ¡No me dijiste la verdad sobre la muerte de Shelt!",
  ui_story_6_14_7_dialog_content = "¿Te mentimos? No, Gertzurde, elegiste creer que Shelt fue asesinada por Lumopolis.",
  ui_story_6_14_8_dialog_content = "¡Para que puedas vengarte como es debido!",
  ui_story_6_14_9_dialog_content = "Nos mentiste a todos. Le mentiste a Shelt, la usaste... ¡y ahora se ha ido!",
  ui_story_6_14_10_dialog_content = "¿No tires tu pañuelo después de limpiarte la nariz con él?",
  ui_story_6_14_11_dialog_content = "¿Así es como ves a Shelt...?",
  ui_story_6_14_12_dialog_content = "Estás sudando profusamente. El viaje debe ser difícil. Aquí tienes un pañuelo.",
  ui_story_6_14_13_dialog_content = "Gracias...",
  ui_story_6_14_14_dialog_content = "En estado de shock, ¿verdad? Eso no es sudor en tu cara... ¿Son lágrimas?",
  ui_story_6_14_15_dialog_content = "¿Por qué lloras, Gertzurde? ¿No eres un traidor? ¿Qué hay para que un traidor llore?",
  ui_story_6_14_16_dialog_content = "Schummer... Tú... Qué le hiciste a Shelt...",
  ui_story_6_14_17_dialog_content = "¿Qué hice? Gertzurde, ¿qué puedes hacer ahora que no tienes el poder que te dimos?",
  ui_story_6_14_20_dialog_content = "¿Fuiste tú quien los fusionó, Schummer?",
  ui_story_6_14_22_dialog_content = "No. Bueno, técnicamente, se podría decir que fui yo...",
  ui_story_6_14_23_dialog_content = "¡Por qué tú...!",
  ui_story_6_14_24_dialog_content = "Sé que estás a punto de preguntar por qué hicimos eso.",
  ui_story_6_14_25_dialog_content = "Y te diré que es porque podemos.",
  ui_story_6_14_26_dialog_content = "¿Por qué estás enojado? ¿Qué tiene de malo limpiar y tirar la basura usada?",
  ui_story_6_14_27_dialog_content = "Preguntas, preguntas, preguntas. Suficiente.",
  ui_story_6_14_28_dialog_content = "PlayerName, y estas dos mujeres... Esta gentuza es la raíz de tus quejas.",
  ui_story_6_14_29_dialog_content = "Schummer, tú...",
  ui_story_6_14_30_dialog_content = "Puedo ayudarte a deshacerte de ellos...",
  ui_story_6_14_31_dialog_content = "¡Cuidado!",
  ui_story_6_14_32_dialog_content = "¡Carleen!",
  ui_story_6_14_33_dialog_content = "¡...!",
  ui_story_6_14_34_dialog_content = "¿Gert... zurde?",
  ui_story_6_14_35_dialog_content = "¡Tú!",
  ui_story_6_14_36_dialog_content = "Yo... Yo...",
  ui_story_6_14_37_dialog_content = "¿Estás loco, Gertzurde? ¿Te inclinas y complaces a cualquiera que se te presente?",
  ui_story_6_14_38_dialog_content = "Por qué...",
  ui_story_6_14_39_dialog_content = "No, no fue por ti... Fue por Shelt...",
  ui_story_6_14_40_dialog_content = "...",
  ui_story_6_14_A1_dialog_content = "Mata... Schummer...",
  ui_story_6_14_A2_dialog_content = "No soy lo suficientemente fuerte para hacerlo, pero tú... tú eres...",
  ui_story_6_14_A3_dialog_content = "Mátala... ¡con tus espadas!",
  ui_story_6_14_A5_dialog_content = "Schummer...",
  ui_story_6_14_A7_dialog_content = "¡Shelt y yo <anim type=Shake><size=50>te estaremos esperando en el infierno!</size></anim>",
  ui_story_6_14_44_dialog_content = "Gertzurde... Tú...",
  ui_story_6_14_45_dialog_content = "Carleen, él... Ese era su último deseo.",
  ui_story_6_14_46_dialog_content = "¡Esto se está volviendo muy, muy, muy, muy tedioso! Eso va para Gertzurde y el resto de ustedes...",
  ui_story_6_14_47_dialog_content = "¡Schummer! <color=#FFB400>Ya vienen</color>. Retrocede.",
  ui_story_6_14_48_dialog_content = "¡Corta el ruido! ¿Qué estás haciendo? ¡Fuera de mi camino!",
  ui_story_6_14_49_dialog_content = "Quiero que te vayas. Ahora.",
  ui_story_6_14_50_dialog_content = "¿Por qué?",
  ui_story_6_14_51_dialog_content = "¿Qué paso?",
  ui_story_6_14_52_dialog_content = "Parece que hay <color=#FFB400>tropas</color> que llevan la bandera de Illumina acercándose, ¡PlayerName! ¡A gran escala!",
  ui_story_6_14_53_dialog_content = "Solo espera. ¡Asediarán este lugar cuando lleguen!",
  ui_story_6_14_54_dialog_content = "Se acerca un enorme enjambre de enemigos. Toma el Módulo y sal de aquí inmediatamente.",
  ui_story_6_14_56_dialog_content = "¡Puedo matarlos a todos en un segundo! Luego toma a PlayerName y lentamente...",
  ui_story_6_14_57_dialog_content = "No puedes lograrlo.",
  ui_story_6_14_58_dialog_content = "¡Sí, puedo! Dame tres minutos. No, haz ese...",
  ui_story_6_14_59_dialog_content = "¡Y dije que no puedes lograrlo! ¡Las tropas de Illumina están en camino! No estoy dispuesto a correr el riesgo.",
  ui_story_6_14_60_dialog_content = "¡Oh, oh, oh! ¡Consigamos más humo!",
  ui_story_6_14_61_dialog_content = "Como vanguardia de las Legiones Illumina, soy...",
  ui_story_6_14_62_dialog_content = "El cazador de Eclipsites, el terminador nocturno, el experto en explosivos de Subciudad, el barquero de Acheron, ¡Charon!",
  ui_story_6_14_63_dialog_content = "¡Estoy llevando a innumerables soldados a asediar el Pasillo Susurrante! ¡Ningún Eclipsite escapará!",
  ui_story_6_14_X64_dialog_content = "No me hagas forzarte, Schummer.",
  ui_story_6_14_65_dialog_content = "Bien, ¡hazlo a tu manera! Tenemos el Módulo, de todos modos...",
  ui_story_6_14_66_dialog_content = "¡Alto, Schummer!",
  ui_story_6_14_67_dialog_content = "¿Dónde está el <color=#FFB400>Módulo de Control de Llama</color>?",
  ui_story_6_14_68_dialog_content = "<color=#FFB400>Está aquí</color>.",
  ui_story_6_14_69_dialog_content = "No puedes correr, especialmente cuando el ejército está aquí.",
  ui_story_6_14_70_dialog_content = "En su lugar, deberías preocuparte por Lumopolis.",
  ui_story_6_14_71_dialog_content = "¿Lumopolis?",
  ui_story_6_14_72_dialog_content = "Sí, ¿la supuesta Ciudad Inconquistable? Qué apodo tan absurdo.",
  ui_story_6_14_A8_dialog_content = "¡Espera hasta que recargue completamente el Colossus Negro! ¡Te mostraré exactamente qué es el poder supremo!",
  ui_story_6_14_73_dialog_content = "¡El terreno! ¡Tengan cuidado, todos!",
  ui_story_6_14_74_dialog_content = "¿Sorprendido?",
  ui_story_6_14_75_dialog_content = "Eso es... ¡Nozard! ¿Pero no está muerto?",
  ui_story_6_14_76_dialog_content = "<anim type=Shake><size=45>*Gimiendo*</size></anim>",
  ui_story_6_14_77_dialog_content = "Reciclar es una virtud. Reutiliza siempre todo.",
  ui_story_6_14_78_dialog_content = "Para de perder el tiempo. El Colossus Negro está descendiendo.",
  ui_story_6_14_79_dialog_content = "Es una lástima que no pueda quedarme para el espectáculo.",
  ui_story_6_14_80_dialog_content = "Bueno, debería haber más diversión en el futuro. ¡Ciao a todos!",
  ui_story_6_14_81_dialog_content = "¿Este Eclipsite es Nozard? ¡Puedo sentir una gran animosidad dentro de él!",
  ui_story_6_14_83_dialog_content = "Es diferente a la última vez que nos enfrentamos a Nozard. ¡Tengan cuidado, todos!",
  ui_story_6_14_84_dialog_content = "Deberíamos haber acabado con Nozard la última vez, pero esta vez ha vuelto y es más fuerte que nunca.",
  ui_story_6_14_85_dialog_content = "¿Alguna vez conociste a Eclipsites como este antes de dirigirte hacia Lumopolis?",
  ui_story_6_14_86_dialog_content = "Sí... Pero estábamos seguros de que estaba muerto.",
  ui_story_6_14_87_dialog_content = "Entonces, ¿quieres decir que el Eclipse lo restauró y lo convirtió en un nuevo tipo de arma? Qué espeluznante...",
  ui_story_6_14_90_dialog_content = "No ven a otros Eclipsites como aliados. Son solo sus herramientas, al igual que Shelt y Shire.",
  ui_story_6_14_92_dialog_content = "Se ha tomado el <color=#FFB400>Módulo de Control de Llama</color>. ¿Qué debemos hacer ahora?",
  ui_story_6_14_93_dialog_content = "Todavía tenemos que cuidar de Gertzurde...",
  ui_story_6_14_94_dialog_content = "¿Carleen?",
  ui_story_6_14_97_dialog_content = "Cremaré a Gertzurde.",
  ui_story_6_14_98_dialog_content = "¿No lo vas a enterrar? Pero eso va en contra de la tradición de Lumopolis...",
  ui_story_6_14_99_dialog_content = "Primero, es un traidor y, como tal, hay que deshacerse de su cuerpo. Segundo, el Eclipse puede intentar resucitar su cuerpo.",
  ui_story_6_14_100_dialog_content = "Es correcto. No lo pensarían dos veces antes de convertir su cadáver en un arma. Es repugnante.",
  ui_story_6_14_102_dialog_content = "Vice, PlayerName, reúne inflamables.",
  ui_story_6_14_103_dialog_content = "Yo, Carleen de Schwartz, Capitán de los Guardianes de Lumopolis, en nombre de Lumopolis, por la presente transmito el juicio final de Gertzurde:",
  ui_story_6_14_104_dialog_content = "Fue caballero de Lumopolis que demostró su valía en el caos de la batalla.",
  ui_story_6_14_105_dialog_content = "Pero, plagado de sus demonios internos y seducido por los Eclipsites, traicionó a Lumopolis.",
  ui_story_6_14_106_dialog_content = "Fue manipulado por nuestros enemigos, ayudó e instigó a los Eclipsites a poner en peligro imperdonablemente a la gente de Lumopolis.",
  ui_story_6_14_107_dialog_content = "Pero al final, perdió el rumbo y pagó con su vida. El crimen que cometió no se puede perdonar, pero se puede eximir del castigo de tener su cadáver abandonado.",
  ui_story_6_14_108_dialog_content = "Quemaremos su cuerpo para preservar su integridad... Noche Blanca en lo alto.",
  ui_story_6_14_109_dialog_content = "Descansa en paz, Gertzurde, campeón de Lumopolis, caballero de la Traición, esbirro del Eclipse.",
  ui_story_6_14_111_dialog_content = "Así, debe descansar en paz. PlayerName, ¿puedes sentir dónde está Schummer?",
  ui_story_6_14_112_dialog_content = "Ha dejado el Pasillo Susurrante.",
  ui_story_6_14_114_dialog_content = "En cuanto a su dirección, estoy un poco inseguro. Si debo adivinar, diría que está en el aire.",
  ui_story_6_14_115_dialog_content = "¿En el aire? Estás diciendo que cuando mencionó Lumopolis, se refería a...",
  ui_story_6_14_116_dialog_content = "Perdón por interrumpir, pero ¿sigues vivo?",
  ui_story_6_14_117_dialog_content = "¡Claro!",
  ui_story_6_14_118_dialog_content = "Alguien que irradiaba un aire poderoso apareció de repente ante mí. Pensé...",
  ui_story_6_14_119_dialog_content = "Aparte de no obtener el Módulo de Control de Llama, estamos bien.",
  ui_story_6_14_120_dialog_content = "Bien, bien.",
  ui_story_6_14_121_dialog_content = "¿Y las fuerzas de Illumina? ¿No dijiste que hay refuerzos aquí?",
  ui_story_6_14_122_dialog_content = "Bueno, lo verán ustedes mismos pronto.",
  ui_story_6_14_123_dialog_content = "Oye, Vice, PlayerName.",
  ui_story_6_14_124_dialog_content = "¿Oficial Charon?",
  ui_story_6_14_125_dialog_content = "¿Puedo tomar una copa primero? Estoy muy sediento corriendo todo este camino.",
  ui_story_6_14_126_dialog_content = "¿Qué está pasando? ¿Dónde están las fuerzas?",
  ui_story_6_14_127_dialog_content = "Philyshy me informó que podrías estar en un gran problema hace unas horas.",
  ui_story_6_14_128_dialog_content = "Pero Gannon se negó a enviar tropas, y pensé que venir por mi cuenta.",
  ui_story_6_14_129_dialog_content = "No me digas que tú eres las \"fuerzas\" que mencionó Señorita Sheol...",
  ui_story_6_14_130_dialog_content = "Es exactamente lo que piensas, Vice.",
  ui_story_6_14_131_dialog_content = "Noté un Colossus negro de aspecto extraño cuando llegué al área, luego me encontré con Señorita Sheol.",
  ui_story_6_14_132_dialog_content = "Le preocupaba que no pudieras vencer a Schummer, así que se me ocurrió un plan.",
  ui_story_6_14_133_dialog_content = "Así que... Ejem, digamos que no fue fácil hacer que parezca que hay miles de soldados ahí fuera.",
  ui_story_6_14_134_dialog_content = "Todo fue un engaño, ya veo. Pero, ¿y si Schummer no cae en la trampa?",
  ui_story_6_14_135_dialog_content = "Valió el intento. ¿En fin, quién podría decir cuántos soldados habían en el tren Illumina?",
  ui_story_6_14_136_dialog_content = "Hablando de eso, ¿a dónde se escapó Schummer?",
  ui_story_6_14_137_dialog_content = "Me lo perdí. No pude ver por todo el polvo que levanté...",
  ui_story_6_14_138_dialog_content = "Ahora estoy bastante segura hacia dónde se dirige su aura. Hacia el cielo... Hacia Lumopolis.",
  ui_story_6_14_139_dialog_content = "¡Lumopolis!",
  ui_story_6_14_140_dialog_content = "¡¿Lumopolis?!",
  ui_story_6_14_141_dialog_content = "¿Se dirige directamente allí, justo después de apoderarse de todos los módulos? ¿¡Está apuntando a Lumopolis!?",
  ui_story_6_14_142_dialog_content = "Hay un poderoso escudo que cubre Lumopolis. ¡No puede entrar!",
  ui_story_6_14_A9_dialog_content = "Pero ella debe dirigirse allí por una razón.",
  ui_story_6_14_143_dialog_content = "¿Entonces cree que puede luchar contra Lumopolis de frente con el Colossus que tiene ahora?",
  ui_story_6_14_144_dialog_content = "PlayerName, pon rumbo a Lumopolis, ¡inmediatamente!",
  ui_story_6_14_145_dialog_content = "Claro, ¡de prisa!",
  ui_story_7_1_1_dialog_content = "El Maestro de la Noche Blanca es mi armadura, mi carne y mis huesos. Con su protección, ningún mal puede dañarme...",
  ui_story_7_1_A1_dialog_content = "El Maestro de la Noche Blanca es mi armadura, mi carne y mis huesos. Con su protección, ningún mal... ¡Mantén la calma! ¡No te asustes!",
  ui_story_7_1_2_dialog_content = "¡Mira, se estrelló contra el escudo!",
  ui_story_7_1_3_dialog_content = "Es eso... un negro... ¿¡<color=#FFB400>dragón negro</color>!?",
  ui_story_7_1_4_dialog_content = "Eso no debería ser un problema, ¿verdad? ¡Nuestro escudo es impenetrable y no se puede destruir fácilmente!",
  ui_story_7_1_5_dialog_content = "Cree en el Maestro de la Noche Blanca. Cree en la protección de Aurora.",
  ui_story_7_1_6_dialog_content = "¡Mientras el escudo aguante, ningún mal puede entrar en la sagrada Zona residencial! ¡No hay que entrar en pánico!",
  ui_story_7_1_7_dialog_content = "¡Casi estamos allí! ¡Lumopolis está más adelante!",
  ui_story_7_1_8_dialog_content = "¿¡Por qué el cielo ha cambiado de color!?",
  ui_story_7_1_9_dialog_content = "El Señor de la Ciudad ha activado el <color=#FFB400>escudo</color>.",
  ui_story_7_1_X1_dialog_content = "Mucha gente podría estar en peligro ahora. ¡Debemos apresurarnos a entrar en la ciudad!",
  ui_story_7_1_X2_dialog_content = "¿Y Schummer?",
  ui_story_7_1_10_dialog_content = "Salva a los civiles primero. ¡Nos dirigimos a la ciudad!",
  ui_story_7_1_11_option_content = "Muy bien, aterrizaremos en la ciudad.",
  ui_story_7_1_12_option_content = "No, será mejor si aparcamos fuera de la ciudad.",
  ui_story_7_1_13_dialog_content = "No... Dado mi tamaño y el estado actual de Lumopolis, sería imposible.",
  ui_story_7_1_14_dialog_content = "Esto no se ve bien. El escudo <color=#FFB400>de Lumopolis ya ha sido activado</color>.",
  ui_story_7_1_A2_dialog_content = "El escudo mantendrá alejados a los Eclipsites, pero Soroz tampoco podrá entrar.",
  ui_story_7_1_16_dialog_content = "¿Por qué apresurarnos entonces, con un escudo tan poderoso?",
  ui_story_7_1_17_dialog_content = "El escudo sólo protege Zona residencial... ¡El resto de la ciudad está fuera de su protección!",
  ui_story_7_1_F1_dialog_content = "¡Los Eclipsites definitivamente entrarán desde Baja Lumopolis y atacarán el punto ciego del escudo!",
  ui_story_7_1_F2_dialog_content = "No podemos aterrizar Soroz en Baja Lumopolis cuando está lleno de Eclipsites.",
  ui_story_7_1_18_dialog_content = "PlayerName, puedo pasar el cursor sobre Lumopolis y encontrarme contigo cuando me necesites.",
  ui_story_7_1_19_dialog_content = "¿Pero no será eso peligroso?",
  ui_story_7_1_F3_dialog_content = "¡Haré todo lo posible para estar alerta contra Schummer y mantenerme en contacto contigo!",
  ui_story_7_1_F4_dialog_content = "Lamento hacerte pasar por esto, Soroz.",
  ui_story_7_1_20_dialog_content = "Carleen, ¿se puede atravesar Lumopolis?",
  ui_story_7_1_21_dialog_content = "No, es imposible. Mientras <color=#FFB400>ese hombre</color> esté allí, Lumopolis se mantendrá firme.",
  ui_story_7_1_22_dialog_content = "En efecto. Dado mi tamaño y la situación actual de Lumopolis, no se nos permitirá entrar.",
  ui_story_7_1_23_dialog_content = "PlayerName, ¿crees que sería mejor si dejáramos a Soroz afuera?",
  ui_story_7_1_24_dialog_content = "Bueno, si Schummer apunta a Lumopolis, Soroz debería alejarse de ella lo más que pueda.",
  ui_story_7_1_25_dialog_content = "Estoy de acuerdo. E incluso si quisiéramos llevar a Soroz a la ciudad, sería imposible.",
  ui_story_7_1_26_dialog_content = "El escudo <color=#FFB400>de Zona residencial está levantado</color>, por lo que no puede entrar nada.",
  ui_story_7_1_F5_dialog_content = "¡Pero los Eclipsites definitivamente entrarán desde Baja Lumopolis y atacarán el punto ciego del escudo!",
  ui_story_7_1_27_dialog_content = "PlayerName, puedo pasar el cursor sobre Lumopolis y encontrarme contigo cuando me necesites.",
  ui_story_7_1_28_dialog_content = "¿Pero no será eso peligroso?",
  ui_story_7_1_F6_dialog_content = "¡Haré todo lo posible para estar alerta contra Schummer y mantenerme en contacto contigo!",
  ui_story_7_1_F7_dialog_content = "Lamento hacerte pasar por esto, Soroz.",
  ui_story_7_1_29_dialog_content = "Vayamos tan rápido como podamos. Si Schummer está realmente segura de que puede tomar Lumopolis...",
  ui_story_7_1_30_dialog_content = "No, es imposible. Mientras <color=#FFB400>ese hombre</color> esté allí, Lumopolis se mantendrá firme.",
  ui_story_7_1_31_dialog_content = "Mi Señor, la amenaza ha sido determinada. ¡Es un Colossus y está atacando a Lumopolis!",
  ui_story_7_1_32_dialog_content = "Nuestro escudo ha sido activado y Zona residencial todavía está a salvo por ahora.",
  ui_story_7_1_33_dialog_content = "No seas descuidado. De momento, es imposible juzgar el poder y la intención del enemigo. Mantente alerta.",
  ui_story_7_1_34_dialog_content = "Deja que los Guardianes vigilen el movimiento del enemigo. El Departamento de Inteligencia nos informará de cualquier novedad.",
  ui_story_7_1_35_dialog_content = "¿Cuál es la situación actual en Baja Lumopolis?",
  ui_story_7_1_36_dialog_content = "Mi señor, los Eclipsites ya han invadido Baja Lumopolis. ¿Enviaremos fuerzas para apoyarlos?",
  ui_story_7_1_37_dialog_content = "No. Continúa enfocándote en proteger Zona residencial. No obligues a los nobles tomar decisiones estúpidas.",
  ui_story_7_1_38_dialog_content = "En cuanto a Baja Lumopolis, tienen sus formas de sobrevivir.",
  ui_story_7_1_39_dialog_content = "¿Y la Legión de Illumina?",
  ui_story_7_1_40_dialog_content = "Muchas de sus legiones están situadas lejos de aquí y no pueden regresar a tiempo para brindar apoyo.",
  ui_story_7_1_41_dialog_content = "Sólo dos escuadrones han llegado cerca de Lumopolis, comandados por la Jefe de Estado Mayor Vivian y la Comandante de la Legión Sharona.",
  ui_story_7_1_42_dialog_content = "¿Esas dos? Bien, ya veo. Y por último, ¿qué pasa con <color=#FFB400>Carleen</color>? ¿Hay noticias?",
  ui_story_7_1_43_dialog_content = "Acabo de recibir noticias de que la Capitana de los Guardianes se dirige ahora a Baja Lumopolis a pie.",
  ui_story_7_1_44_dialog_content = "Envíala de regreso a Zona residencial inmediatamente. No es momento para juegos. Rumores es lo último que necesitamos ahora.",
  ui_story_7_1_45_dialog_content = "<color=#e8d9bb>Dentro de Baja Lumopolis</color>",
  ui_story_7_1_46_dialog_content = "No he visto a un solo guardián.",
  ui_story_7_1_47_dialog_content = "Puedo sentir Eclipsites aquí.",
  ui_story_7_1_48_dialog_content = "Que desastre. Apenas puedo creer que esto sea Lumopolis.",
  ui_story_7_1_49_dialog_content = "Aterrizado... Aproximadamente sobre... donde estás.",
  ui_story_7_1_A3_dialog_content = "El escudo de Lumopolis... causando interferencia. Espero... oye esto...",
  ui_story_7_1_50_dialog_content = "¡No te preocupes, entiendo! Estamos a salvo. ¡Cuídate!",
  ui_story_7_1_51_dialog_content = "Esa es mi... línea, PlayerName.",
  ui_story_7_1_52_dialog_content = "¡Te estaré... esperando! Cuida... tu...",
  ui_story_7_1_53_dialog_content = "Ojalá alguien dijera cómo están las cosas en este momento...",
  ui_story_7_1_54_dialog_content = "No es tan malo como parece, Vice, PlayerName.",
  ui_story_7_1_55_dialog_content = "¡Señora <color=#FFB400>Vivian</color>!",
  ui_story_7_1_56_dialog_content = "Muchas legiones están defendiendo los alrededores, por lo que somos los únicos disponibles para ayudar por ahora.",
  ui_story_7_1_57_dialog_content = "¿Lumopolis está cayendo? ¡Estos civiles están fuera de control!",
  ui_story_7_1_A4_dialog_content = "¡Nos volvemos a encontrar, Celestita! Cada vez que surge un problema, ahí estás.",
  ui_story_7_1_58_dialog_content = "No quiero tener nada que ver con todo esto... Por favor no me culpes...",
  ui_story_7_1_59_dialog_content = "¿Por qué lo haríamos? Intentaste detener a Schummer, ¿no? No esperábamos esto, eso es todo.",
  ui_story_7_1_60_dialog_content = "Señora, ¿sabe lo que está pasando en Lumopolis?",
  ui_story_7_1_61_dialog_content = "Zona residencial está asegurada, claro. ¿Viste el escudo?",
  ui_story_7_1_62_dialog_content = "Ha sido activado. Nada puede penetrarlo. Eso es lo que quieren decir con la Ciudad Invencible.",
  ui_story_7_1_63_dialog_content = "Sin embargo, Baja Lumopolis no tiene tanta suerte.",
  ui_story_7_1_64_dialog_content = "¿Señora <color=#FFB400>Sharona</color>? Digo, Comandante de la Legión...",
  ui_story_7_1_65_dialog_content = "Ah, olvidé mencionar que la mayoría de las tropas respondiendo a esta emergencia fueron transferidas de la 1ra Legión.",
  ui_story_7_1_66_dialog_content = "El escudo no cubre Baja Lumopolis. Incluso un niño de tres años podría entrar y salir, y mucho menos Eclipsites.",
  ui_story_7_1_68_dialog_content = "¿Puedes controlarlo? ¿Qué está pasando? Dame los detalles.",
  ui_story_7_1_70_dialog_content = "Estamos haciendo un rastreo rápido y será difícil, pero mi gente apenas puede manejar lo que hay por ahora.",
  ui_story_7_1_71_dialog_content = "¿Y los Guardianes? Recibí una orden para regresar a Zona Residencial de inmediato. ¿Dónde están los otros Guardianes?",
  ui_story_7_1_72_dialog_content = "Carleen de Schwartz, no creo que me entiendas del todo.",
  ui_story_7_1_A5_dialog_content = "Tu padre ha ordenado a todos los Guardianes, incluyéndote a ti, que protejan la Zona Residencial.",
  ui_story_7_1_73_dialog_content = "No te sorprende, ¿verdad? Seguramente no podías esperar lo contrario.",
  ui_story_7_1_74_dialog_content = "¡No tienes que hablarme así, Sharona! ¡Creo que he hecho lo suficiente para merecer un poco de respeto!",
  ui_story_7_1_75_dialog_content = "¿Tus acciones realmente han cambiado algo? Lumopolis sigue siendo Lumopolis.",
  ui_story_7_1_76_option_content = "¡Suficiente, señoritas!",
  ui_story_7_1_77_option_content = "¡Cállense, las dos!\n¡Tenemos asuntos más urgentes!",
  ui_story_7_1_78_dialog_content = "No me interesan las peleas.",
  ui_story_7_1_79_dialog_content = "PlayerName, no es tu turno de jugar al pacificador.",
  ui_story_7_1_80_dialog_content = "Esto es entre Illumina y Lumopolis.",
  ui_story_7_1_81_dialog_content = "Ese no es el problema aquí. Además, ¿no son todos Aurorians?",
  ui_story_7_1_82_dialog_content = "Señora, PlayerName solo está preocupado por la situación actual. Estamos todos al límite...",
  ui_story_7_1_83_dialog_content = "Esa es una observación astuta, Vice. Lo que dijo PlayerName es cierto. ¿No somos una familia?",
  ui_story_7_1_84_dialog_content = "En primer lugar, lo más importante es que nosotros, como Aurorians, ¡debemos luchar juntos! ¿Cierto?",
  ui_story_7_1_85_dialog_content = "Estoy de acuerdo. Nuestras opiniones no importan ahora.",
  ui_story_7_1_86_dialog_content = "Hablando de eso, Carleen, ¿no deberías volver primero a Zona residencial? El Señor de la Ciudad parece estar buscándote.",
  ui_story_7_1_F8_dialog_content = "¿Soy el único que puede ver esos Eclipsites?",
  ui_story_7_1_87_dialog_content = "¡Cuidado con tu tono, PlayerName!",
  ui_story_7_1_88_dialog_content = "Estás hablando con el Comandante de la 1era Legión de Illumina y Carleen, PlayerName.",
  ui_story_7_1_89_dialog_content = "¡Lo se! Pero también sé que ya sea el Comandante de la Legión o el Capitán de los Guardianes, ¡no deberíamos esperar a salvar a la gente a favor del intercambio de palabras sin sentido!",
  ui_story_7_1_90_dialog_content = "Sí. Lo más importante en este momento es luchar contra los Eclipsites, no discutir entre nosotros por insignificantes luchas de poder.",
  ui_story_7_1_91_dialog_content = "Lamentablemente, no necesito que una niña me diga cómo comportarme, muchas gracias.",
  ui_story_7_1_92_dialog_content = "En cuanto a matar a los Eclipsites, lo hago repetidamente en las batallas todos los días.",
  ui_story_7_1_93_dialog_content = "Escuché que has pasado por muchas peleas recientemente. Deberías poder entenderlo, ¿correcto?",
  ui_story_7_1_94_dialog_content = "...",
  ui_story_7_1_95_dialog_content = "Bien, tenemos un acuerdo. Canalicemos nuestra energía hacia los Eclipsites, ¿de acuerdo?",
  ui_story_7_1_96_dialog_content = "¿Quieres volver primero, Carleen?",
  ui_story_7_1_97_dialog_content = "No. Nadie puede darme órdenes cuando estoy aquí afuera.",
  ui_story_7_1_98_dialog_content = "Pero, esto no es el exterior. Digo, básicamente estás en casa...",
  ui_story_7_1_F9_dialog_content = "Ya es suficiente, Vice...",
  ui_story_7_1_99_dialog_content = "¡Comandante de la Legión! ¡Hay más Eclipsites en Baja Lumopolis de las que esperábamos! ¡Nuestras defensas están al límite y hay una brecha!",
  ui_story_7_1_A6_dialog_content = "¡Los residentes cercanos no han tenido tiempo de evacuar! ¿Cuál es su orden?",
  ui_story_7_1_100_dialog_content = "¡Iré allí yo misma! En cuanto al resto , hagan lo que les plazca.",
  ui_story_7_1_101_dialog_content = "¡Por favor llévanos! ¡Podemos ayudar!",
  ui_story_7_1_102_dialog_content = "¡Seguro que estás emocionada, Vice! <color=#FFB400>De acuerdo. ¡Vayamos todos</color>!",
  ui_story_7_1_103_dialog_content = "Guiaré el camino. Baja Lumopolis es un lugar por el que he patrullado innumerables veces. Nadie está más familiarizado con sus calles que yo.",
  ui_story_7_1_104_dialog_content = "Carleen, ¿está realmente bien que no regreses?",
  ui_story_7_1_105_dialog_content = "No hay nada más que decir. He tomado una decisión. Pongamos fin a todo esto.",
  ui_story_7_1_106_dialog_content = "¡Lumopolis realmente tiene un caparazón duro!",
  ui_story_7_1_107_dialog_content = "Maldita sea, ¡¿por qué no me hablaste de esta defensa que estás desplegando?! ¿Qué tipo de táctica cobarde es esta?",
  ui_story_7_1_108_dialog_content = "Dije que lo hicieras alcanzar su máxima potencia antes de atacar, pero obvio, ¡eres muy engreído para aguantar!",
  ui_story_7_1_109_dialog_content = "Si todavía tienes tiempo para predicar, ¡por qué no envías más de tus lacayos para sembrar el caos en Lumopolis!",
  ui_story_7_1_110_dialog_content = "Shh, cállate. No me gustan las conmociones.",
  ui_story_7_1_111_dialog_content = "El escudo de Lumopolis se quedará sin energía pronto.",
  ui_story_7_1_A7_dialog_content = "Cuando eso suceda, podrás bailar el vals de inmediato.",
  ui_story_7_1_112_dialog_content = "¿Entonces qué hago ahora? Esperar, ¿o seguir atacando?",
  ui_story_7_1_113_dialog_content = "¿Quieres sentarte y ver cómo tus compinches inútiles se burlan de nosotros?",
  ui_story_7_1_114_dialog_content = "Paciencia, Schummer. Tu viejo enemigo acecha por aquí.",
  ui_story_7_1_116_dialog_content = "¿Te refieres a Soroz? ¿Y PlayerName?",
  ui_story_7_1_117_dialog_content = "Correcto. Parece que quieres salir a jugar... Qué divertido.",
  ui_story_7_1_X3_dialog_content = "Haré lo que me plazca. No lo olvides, no sigo las órdenes de nadie... Ni el tuyo, ni de los Eclipses.",
  ui_story_7_1_X4_dialog_content = "Suspiro. No tienes remedio.",
  ui_story_7_2_1_dialog_content = "Carleen, ¿qué tan lejos estamos del área que necesita apoyo?",
  ui_story_7_2_2_dialog_content = "¡Estamos aquí! Este es el lugar del que estaba hablando el soldado hace un momento.",
  ui_story_7_2_3_dialog_content = "El aura de los Eclipsites es muy fuerte aquí. Con respecto al <color=#FFB400>asunto más urgente</color> del que debemos ocuparnos aquí...",
  ui_story_7_2_4_option_content = "Primero deberíamos evacuar a la gente.",
  ui_story_7_2_5_option_content = "Eliminar Eclipsites errantes",
  ui_story_7_2_6_dialog_content = "PlayerName, ¡el campeón de la gente! ¡Quizás te conviertas en un gran líder en el futuro!",
  ui_story_7_2_7_dialog_content = "Me halagas, señora...",
  ui_story_7_2_8_dialog_content = "De acuerdo, iré a buscar personas que necesiten ayuda. Soy más rápido que cualquiera de ustedes.",
  ui_story_7_2_A1_dialog_content = "Elimina todos los Eclipsite que encuentres. Puedes manejar esta fácil tarea, ¿no?",
  ui_story_7_2_9_dialog_content = "¡Entendido! La única forma de garantizar un rescate tranquilo es eliminando la amenaza.",
  ui_story_7_2_10_dialog_content = "Dividámonos. Quizás los esfuerzos de rescate y limpieza se puedan llevar simultáneamente.",
  ui_story_7_2_11_dialog_content = "Iré a buscar personas que necesiten ayuda. Soy más rápido que cualquiera de ustedes.",
  ui_story_7_2_A2_dialog_content = "Elimina todos los Eclipsite que encuentres. Puedes manejar esta fácil tarea, ¿no?",
  ui_story_7_2_12_dialog_content = "No me subestimes, Sharona.",
  ui_story_7_2_13_dialog_content = "¡Supongo que estás listo para la acción! Genial, ¡vamos!",
  ui_story_7_2_14_dialog_content = "Iré por este camino. ¡Vice, ustedes se encargan de ese final!",
  ui_story_7_2_15_dialog_content = "¿Y tú Colossus? Todavía no estamos fuera de peligro. ¡Recuerda cuidar tu espalda!",
  ui_story_7_2_16_dialog_content = "Soroz está flotando fuera de la ciudad y debería estar seguro por ahora... Creo.",
  ui_story_7_2_17_dialog_content = "Nos faltan manos, así que denlo todo, todos.",
  ui_story_7_2_F1_dialog_content = "Bueno, si los Guardianes estuvieran aquí para ayudar...",
  ui_story_7_2_18_dialog_content = "¿No cuento como guardián?",
  ui_story_7_2_19_dialog_content = "Lo siento, no quise despreciar a nadie.",
  ui_story_7_2_21_dialog_content = "¡Movámonos y embolsemos algunos Eclipsites! ¡Mi objetivo para hoy es alcanzar los tres dígitos!",
  ui_story_7_2_22_dialog_content = "Eso es todo...",
  ui_story_7_2_23_dialog_content = "Cada oficial superior de Illumina es excepcional por derecho propio. ¡Empecemos a acabar con los enemigos por aquí!",
  ui_story_7_6_1_dialog_content = "Uf. ¡Todo despejado aquí!",
  ui_story_7_6_2_dialog_content = "¡Y por aquí también! Señora, ¿hay algún otro lugar en Baja Lumopolis que necesite apoyo?",
  ui_story_7_6_3_dialog_content = "Han aparecido más de esos cretinos, pero están bajo control. Lo has hecho genial.",
  ui_story_7_6_4_dialog_content = "Uf. La crisis se ha evitado. Parece que llegamos justo a tiempo.",
  ui_story_7_6_6_dialog_content = "Muy bien, Vice. Baja Lumopolis debería estar bien por ahora. ¡Podemos a buscar a otro lado!",
  ui_story_7_6_7_dialog_content = "¡El enemigo puede planear atacar un punto débil de nuestras defensas!",
  ui_story_7_6_8_dialog_content = "Señora, ¿sabes que eres natural con este poder llamado Jinx?",
  ui_story_7_6_9_dialog_content = "Para estar segura, ¿puedes confirmar el estado de Soroz, PlayerName?",
  ui_story_7_6_10_dialog_content = "Soroz no me ha contactado desde hace ratos.. Déjame intentarlo.",
  ui_story_7_6_12_dialog_content = "Normal. No hay Eclipsites cerca... pero la temperatura parece haber bajado considerablemente, yo...",
  ui_story_7_6_13_dialog_content = "<size=45>¡¿Qué?!</size>",
  ui_story_7_6_14_dialog_content = "¿Qué pasa, Carleen? ¿Estás herida?",
  ui_story_7_6_15_dialog_content = "No, ¡pero recibí un mensaje que <color=#FFB400>Zona residencial ha sido atravesada</color>!",
  ui_story_7_6_16_dialog_content = "¿Zona residencial? ¿Los Eclipsites rompieron las defensas de Baja Lumopolis y están invadiendo Zona residencial?",
  ui_story_7_6_17_dialog_content = "No, la línea de Baja Lumopolis no se ha roto. ¡Deben haberse infiltrado en Zona residencial de antemano!",
  ui_story_7_6_18_dialog_content = "¿Atacaron directamente el corazón de Lumopolis? ¿Zona residencial no está fuertemente defendida?",
  ui_story_7_6_19_dialog_content = "Sí, así es. Pero los Eclipsites actuaron raro hace poco...",
  ui_story_7_6_20_dialog_content = "Si Schummer se atrevió a atacar Lumopolis, esos Eclipsites seguro que venían listos.",
  ui_story_7_6_21_dialog_content = "Exacto. De repente tengo un mal presentimiento sobre esto. Debo regresar de inmediato.",
  ui_story_7_6_22_dialog_content = "¡Nosotros también! ¡Vamos, PlayerName!",
  ui_story_7_6_23_dialog_content = "Un enemigo que pudiera infiltrarse en Zona residencial debe poseer poderes aterradores. Agradezco tu disposición para venir conmigo.",
  ui_story_7_6_24_dialog_content = "¡Entendido! Señora, acabamos de recibir noticias de que Zona residencial está siendo atacada por un Eclipsite especial. ¡Debemos ir a apoyar a la fuerza de defensa, ahora!",
  ui_story_7_6_25_dialog_content = "¡Vamos en camino!",
  ui_story_7_6_26_dialog_content = "Estoy casi allí.",
  ui_story_7_6_27_dialog_content = "¡El Comandante de la Legión es realmente algo más!",
  ui_story_7_7_1_dialog_content = "¡Lo siento, llego tarde!",
  ui_story_7_7_2_dialog_content = "¡Capitán! ¡Por fin has vuelto! Los Eclipsites son...",
  ui_story_7_7_3_dialog_content = "¡No digas más! ¿¡Dónde está el enemigo!?",
  ui_story_7_7_4_dialog_content = "¡Aquí! ¡Sígueme!",
  ui_story_7_7_5_dialog_content = "<size=45>¡¡¡Woogagagagaga!!!</size>",
  ui_story_7_7_6_dialog_content = "¡Continua! ¡No dejes que avance más! ¡Zona residencial está adelante!",
  ui_story_7_7_7_dialog_content = "¡¡¡Wooga!!!",
  ui_story_7_7_8_dialog_content = "¡Maldita sea! ¡La defensa se ha roto! ¡Reagrupar! ¡No deben acercarse más a la ciudad!",
  ui_story_7_7_9_dialog_content = "¡Ah! ¡Carleen!",
  ui_story_7_7_10_dialog_content = "¿Qué hace todos? No te quedes ahí mirando el alboroto, ¡este es el corazón de Lumopolis!",
  ui_story_7_7_11_dialog_content = "Pero el Señor de la Ciudad nos dio órdenes. <color=#FFB400>Solo de proteger Zona residencial</color>...",
  ui_story_7_7_12_dialog_content = "Estrictamente hablando, ese enorme bicho aún no se ha abierto paso, así que no podemos salir ahora...",
  ui_story_7_7_13_dialog_content = "¿¡Qué tipo de lógica es esa!?",
  ui_story_7_7_15_dialog_content = "Carleen, si los Guardianes no pueden atacar, ¡aún podemos contar con el apoyo de Illumina! ¡Estos dos oficiales deberían poder lidiar con esto!",
  ui_story_7_7_16_dialog_content = "¿Limpiando el desorden de los Guardianes de nuevo?",
  ui_story_7_7_17_dialog_content = "¡Señora! Los Guardianes deben obedecer sus órdenes... No pueden dejar Zona residencial para enfrentarse al enemigo, ¡así que ocupémonos de esto!",
  ui_story_7_7_18_dialog_content = "Cada vez que me veo obligado a trabajar con Lumopolis, recuerdo el verdadero sentido de la burocracia.",
  ui_story_7_7_19_dialog_content = "De acuerdo, Sharona. Este no es el momento de quejarse. Esos soldados no pueden aguantar mucho más.",
  ui_story_7_7_21_dialog_content = "¡Trae la soga y el tractor! ¡Arranca esta cosa miembro por miembro!",
  ui_story_7_7_22_dialog_content = "¿¡Extremidad por extremidad!?",
  ui_story_7_7_23_dialog_content = "¿...?",
  ui_story_7_7_24_dialog_content = "Hablando por experiencia, ¡romper esto hace que el cuerpo sea más fácil de desechar! ¡Solo concéntrense en pelear, niños!",
  ui_story_7_7_25_dialog_content = "¡Exacto! Dinos que debemos hacer, señora...",
  ui_story_7_7_26_dialog_content = "¡Primero eliminemos a esta escoria! Vivian, recuerda cortarlo en el momento adecuado, ¡cómo antes!",
  ui_story_7_7_27_dialog_content = "¡Entendido, como antes!",
  ui_story_7_7_28_dialog_content = "¡Abriré un camino! El resto de ustedes, ¡quítense del camino! ¡No se dejen matar! En cuanto a nuestro <color=#FFB400>comandante</color>...",
  ui_story_7_7_29_dialog_content = "¡Lo tengo! ¡No hay forma de que pueda perder!",
  ui_story_7_7_30_dialog_content = "¡<color=#FFB400>Asegúrate que caiga fuera de Zona residencial</color>!",
  ui_story_7_7_31_dialog_content = "<anim type=Shake><size=45>¡Gahhhhhhhh!</size></anim>",
  ui_story_7_7_32_dialog_content = "¡Vivian, ahora!",
  ui_story_7_7_33_dialog_content = "¡Vamos! ¡Estoque de radio!",
  ui_story_7_7_34_dialog_content = "¡Sangre por sangre!",
  ui_story_7_7_36_dialog_content = "¡Cayó! ¡Finalmente!",
  ui_story_7_7_37_dialog_content = "¡Hemos neutralizado con éxito la amenaza! ¡Ustedes, niños, pueden ser muy útiles a la hora de la verdad!",
  ui_story_7_7_38_dialog_content = "...",
  ui_story_7_7_39_dialog_content = "Me siento halagado, señora.",
  ui_story_7_7_40_dialog_content = "Señora, ¡el Colossus negro sigue atacando y no da señales de ceder!",
  ui_story_7_7_41_dialog_content = "Schummer...",
  ui_story_7_7_42_dialog_content = "Todavía tan terca. ¿Qué gana ella luchando?",
  ui_story_7_7_43_dialog_content = "Es más de lo que puede manejar. Estos Eclipsites ni siquiera pueden poner un dedo en Zona residencial.",
  ui_story_7_7_44_dialog_content = "Quizás sean sólo estúpidos.",
  ui_story_7_7_45_dialog_content = "¿Se ha eliminado la amenaza a Zona residencial? Si no queda nada por hacer aquí, me iré primero.",
  ui_story_7_7_46_dialog_content = "La 1ra Legión todavía debe terminar de defender el lado este... Ejem, todo gracias a los Guardianes.",
  ui_story_7_7_47_dialog_content = "De todos modos, gracias por tu ayuda, Illumina.",
  ui_story_7_7_48_dialog_content = "No me agradezcas, agradece a PlayerName y Vice.",
  ui_story_7_7_A2_dialog_content = "No todos tiene la paciencia para trabajar con Lumopolis, y menos ocupar la retaguardia sin ayuda.",
  ui_story_7_7_49_dialog_content = "...",
  ui_story_7_7_50_dialog_content = "Ya veo, siendo ambiguo. Sharona hace eso a veces. No te preocupes demasiado por eso, Carleen.",
  ui_story_7_7_51_dialog_content = "La crisis se ha evitado. Es el mejor resultado y todo lo que importa ahora.",
  ui_story_7_7_52_dialog_content = "Schummer quería atacar a Lumopolis de frente sin darse cuenta de que teníamos un medio de defensa casi impenetrable.",
  ui_story_7_7_53_dialog_content = "¿Qué irá hacer después? Ese Colossus Negro de hace un momento, ¿estaba completamente cargado?",
  ui_story_7_7_X1_dialog_content = "Ella ha robado tres módulos, pero el Colossus Negro no parece ser demasiado poderoso.",
  ui_story_7_7_54_dialog_content = "Creo que Schummer no ha alcanzado su máxima potencia. Este asalto mostró claramente que ella nos subestimó.",
  ui_story_7_7_55_dialog_content = "Por lo que sabes de ella, ¿podemos esperar algún tipo de represalia frenética por lo que sucedió hoy aquí?",
  ui_story_7_7_56_dialog_content = "Tengo la sensación de que está a punto de suceder algo terrible.",
  ui_story_7_7_57_dialog_content = "Por favor, no diga eso, señora. Sueles tener razón en estas cosas.",
  ui_story_7_7_58_option_content = "Deberíamos tomar la iniciativa.",
  ui_story_7_7_59_option_content = "Es mejor que esperemos y veamos\nque pasa después.",
  ui_story_7_7_60_dialog_content = "Estoy de acuerdo. Por ahora, ¡debemos aprovechar al máximo nuestro impulso y aprovechar la oportunidad!",
  ui_story_7_7_61_dialog_content = "Exacto. ¡Hemos aceptando pasivamente todo lo que nos ha lanzado hasta ahora! ¡Es hora de tomar la ofensiva!",
  ui_story_7_7_62_dialog_content = "Tienes razón, PlayerName. Deberíamos estar quietos hasta tener más información.",
  ui_story_7_7_63_dialog_content = "Es probable que Schummer sea quien más pierda la paciencia.",
  ui_story_7_7_A3_dialog_content = "Claramente domina los tres módulos, pero ahora se ha estrellado contra una pared de ladrillos. ¡Esperemos a que ella se equivoque!",
  ui_story_7_7_64_dialog_content = "¡Ugh...!",
  ui_story_7_7_65_dialog_content = "¿PlayerName? ¿Qué ocurre?",
  ui_story_7_7_66_dialog_content = "(Mi mente... ¿¡Qué es este dolor agudo!?)",
  ui_story_7_7_67_dialog_content = "...",
  ui_story_7_7_68_dialog_content = "¡Soroz!",
  ui_story_7_7_69_dialog_content = "¡Bajo ataque! El enemigo... Ella invadió mi... Más de un enemigo... Hay otro...",
  ui_story_7_7_X2_dialog_content = "¡No puedo oírte! Soroz, ¿¡todavía estás en tus coordenadas!? ¡Venimos a ayudarte de inmediato!",
  ui_story_7_7_X3_dialog_content = "¡Cerca! Por favor... El enemigo ha invadido... ¡y no está solo!",
  ui_story_7_7_A4_dialog_content = "<color=#FFB400>Atrás</color>... ¡<color=#FFB400>Vuelve</color>!",
  ui_story_7_7_X4_dialog_content = "¡Soroz ha sido invadida! ¡Schummer cambió su objetivo!",
  ui_story_7_7_X5_dialog_content = "¡¿?!",
  ui_story_7_7_X6_dialog_content = "No podía entrar a Lumopolis, ¿así que decidió golpearnos?",
  ui_story_7_7_70_dialog_content = "Regresa por soporte de emergencia. Esta vez no traje un dirigible. ¿Podemos requisar uno de Lumopolis, Carleen?",
  ui_story_7_7_71_dialog_content = "Oh...",
  ui_story_7_7_72_dialog_content = "Capitán, el Señor de la Ciudad tiene una nueva orden. Debes regresar a Zona residencial.",
  ui_story_7_7_73_dialog_content = "Un momento. Esto es una emergencia. Necesito ayudarlos primero...",
  ui_story_7_7_74_dialog_content = "Lo siento, esta no es una solicitud. Si no regresa, me temo que los Cuatro Ángeles serán enviados.",
  ui_story_7_7_75_dialog_content = "¿Qué pasa? Sólo observo aquí. ¿Por qué me veo arrastrado a esto de repente?",
  ui_story_7_7_76_dialog_content = "...",
  ui_story_7_7_77_dialog_content = "Carleen, parece que tu padre tiene sus planes. Deberías volver.",
  ui_story_7_7_78_dialog_content = "No te preocupes, Soroz está ahora con Illumina. Nos haremos cargo de esto.",
  ui_story_7_7_79_dialog_content = "Espera, ¿cuándo me convertí parte de Illumina?",
  ui_story_7_7_80_dialog_content = "...",
  ui_story_7_7_81_dialog_content = "...",
  ui_story_7_7_82_dialog_content = "¿Por qué me siento obligado a conformarme con menos que perfecto? ¿Cuánto tiempo hasta que se complete mi Colossus?",
  ui_story_7_7_83_dialog_content = "Pronto. Pero nos estamos quedando sin tiempo y mi paciencia se está agotando, Schummer.",
  ui_story_7_7_85_dialog_content = "Por supuesto. Solo quiero completar lo que no logré terminar en el Pasillo Susurrante.",
  ui_story_7_7_86_dialog_content = "PlayerName es muy especial. Esta es la primera vez que considero salvarle la vida a un Celestita.",
  ui_story_7_7_87_dialog_content = "El Celestita vendrá, puedo sentirlo. Llámelo el sentido del deber o la locura de una fuerte moralidad.",
  ui_story_7_7_A5_dialog_content = "PlayerName será guiado de regreso aquí por esos ideales obsoletos.",
  ui_story_7_7_89_dialog_content = "Entonces no esperes. ¿Cuántos secuaces hemos perdido gracias a tus tonterías? ¿¡Necesito repetir!?",
  ui_story_7_7_90_dialog_content = "<color=#FFB400>Sólo mátalo</color>, Schummer.",
  ui_story_7_7_91_dialog_content = "Soroz, mi viejo amigo...",
  ui_story_7_7_92_dialog_content = "<size=45>¡Esto puede doler un poco!</size>",
  ui_story_7_8_1_dialog_content = "¿Puedes oírme, Soroz?",
  ui_story_7_8_2_option_content = "Prueba la telepatía",
  ui_story_7_8_3_dialog_content = "Soroz... Soroz...",
  ui_story_7_8_4_option_content = "Prueba la telepatía",
  ui_story_7_8_5_dialog_content = "No funciona. ¡Todavía no puedo sentir nada! Y la interferencia del escudo...",
  ui_story_7_8_6_dialog_content = "¡Necesitamos volver a él lo antes posible!",
  ui_story_7_8_7_dialog_content = "No tengo la autoridad para usar el dirigible de Lumopolis hasta que los Guardianes me aprueben.",
  ui_story_7_8_8_dialog_content = "Me temo que tomará demasiado tiempo requisar uno del bastión de Illumina más cercano.",
  ui_story_7_8_9_dialog_content = "No hay nada que Carleen pueda hacer al respecto, tampoco...",
  ui_story_7_8_11_dialog_content = "Como hija del Señor de la Ciudad y Capitana de los Guardianes de Lumopolis, ya ha hecho mucho por nosotros.",
  ui_story_7_8_12_dialog_content = "En efecto. Si ella se rebelara de nuevo y apareciera con un dirigible para nosotros... Eso sería demasiado.",
  ui_story_7_8_13_dialog_content = "Vaya, Vivian estás usando tu poder profético de nuevo...",
  ui_story_7_8_14_dialog_content = "¡Mira!",
  ui_story_7_8_15_dialog_content = "Perdón por interrumpir. ¡Un dirigible acaba de despegar allí!",
  ui_story_7_8_16_dialog_content = "¿Quién lo está pilotando? Está desviándose por todo el lugar. Espera, ¿viene hacia nosotros?",
  ui_story_7_8_17_dialog_content = "¿...?",
  ui_story_7_8_18_dialog_content = "¿Ah?",
  ui_story_7_8_19_dialog_content = "¡De ninguna manera, Carleen!",
  ui_story_7_8_20_dialog_content = "¡Sube a bordo rápido! ¡He <color=#FFB400>comandado</color> esta nave!",
  ui_story_7_8_21_dialog_content = "¿Comandado? ¿¡No eres la Capitana de los Guardianes!?",
  ui_story_7_8_22_dialog_content = "¡Lo explicaré luego! ¿No quieres volver a Soroz? ¿Vienes o no?",
  ui_story_7_8_23_dialog_content = "¡Bien, ahora podemos regresar!",
  ui_story_7_8_24_dialog_content = "Lo siento, PlayerName, por llegar tarde.",
  ui_story_7_8_25_option_content = "No, has hecho mucho por nosotros.",
  ui_story_7_8_26_option_content = "No te preocupes. No sabía que podías pilotar un dirigible.",
  ui_story_7_8_27_dialog_content = "Bueno, había querido proteger solo a Lumopolis...",
  ui_story_7_8_28_dialog_content = "Pero ahora hay algo más que quiero proteger.",
  ui_story_7_8_29_dialog_content = "Bueno, parece que alguien tiene la mente correcta.",
  ui_story_7_8_30_dialog_content = "¡Démonos prisa, Soroz nos está esperando!",
  ui_story_7_8_31_dialog_content = "Nunca he temido a la muerte, como <color=#FFB400>aquel año en ese entonces</color>, cuando no podías hacerme acobardar.",
  ui_story_7_8_32_dialog_content = "Puedes abandonar los principios de la luz y buscar refugio en la sombra de la oscuridad...",
  ui_story_7_8_A1_dialog_content = "Pero, al final, todos estamos destinados a la Aurora.",
  ui_story_7_8_33_dialog_content = "Schummer, puedes destruir mi conciencia, ¡pero nunca derrotarás a PlayerName!",
  ui_story_7_9_1_dialog_content = "Tal como pensamos, ¡Schummer finalmente atacó a Soroz!",
  ui_story_7_9_2_dialog_content = "Los Eclipsites corren desenfrenadas aquí. Puedo oler el hedor de el Darkflow en el aire.",
  ui_story_7_9_3_dialog_content = "¡¿Qué le han hecho a Soroz?!",
  ui_story_7_9_4_dialog_content = "Enemigos a las nueve. Las cosas inmundas nos encontraron...",
  ui_story_7_9_5_dialog_content = "¡Derribémoslos!",
  ui_story_7_9_6_dialog_content = "Bien, no hemos levantado mucho alboroto para alertar al enemigo.",
  ui_story_7_9_7_dialog_content = "Podríamos matarlos tan rápido como podamos antes que Schummer pueda reaccionar.",
  ui_story_7_9_8_dialog_content = "No creo que sea posible...",
  ui_story_7_9_9_dialog_content = "No tienes que arriesgar tu vida con nosotros, Carleen.",
  ui_story_7_9_10_dialog_content = "Somos amigos. Eso dijiste, ¿no?",
  ui_story_7_9_11_dialog_content = "Además, si no divido a un enemigo duro por la mitad con mi lanza, ¿cómo podré dormir por la noche?",
  ui_story_7_9_12_option_content = "No esperaría menos de ti, Carleen.",
  ui_story_7_9_13_option_content = "Sí, somos amigos.",
  ui_story_7_9_14_dialog_content = "¿Qué quieres decir?",
  ui_story_7_9_15_dialog_content = "Creo que PlayerName se refería a que no esperábamos menos de la Capitana de los Guardianes de Lumopolis.",
  ui_story_7_9_A1_dialog_content = "Se trata de responsabilidad y coraje.",
  ui_story_7_9_16_dialog_content = "Si lo dices, pero estar aquí felicitándome no cambiará nuestra situación actual.",
  ui_story_7_9_17_dialog_content = "E incluso si no dijeras eso, seguiría luchando junto a ti. Porque somos <color=#FFB400>amigos</color>.",
  ui_story_7_9_18_dialog_content = "Aunque todo el mundo dice que Lumopolis es apática, creo que eres diferente.",
  ui_story_7_9_19_dialog_content = "Y eso es algo de constante confusión para mí. ¿Debo defender a Lumopolis o a mí mismo?",
  ui_story_7_9_20_dialog_content = "Bueno, a juzgar por tus acciones, parece que has encontrado la respuesta.",
  ui_story_7_9_21_dialog_content = "Quizás.",
  ui_story_7_9_22_dialog_content = "Sé que somos amigos. ¿Debes repetirlo?",
  ui_story_7_9_23_dialog_content = "Tú eres quien preguntó. Olvídalo, tenemos peces más grandes para freír ahora mismo.",
  ui_story_7_9_24_dialog_content = "¿Sabes a qué nos enfrentamos, Carleen? Las últimas batallas estuvieron, pero...",
  ui_story_7_9_25_dialog_content = "Siento que lo peor está por venir.",
  ui_story_7_9_26_dialog_content = "Por favor, no diga eso, señora.",
  ui_story_7_9_27_dialog_content = "No importa cuán poderosa sea Schummer, todos tenemos nuestras razones para querer derrotarla, ¿no es así?",
  ui_story_7_9_28_dialog_content = "Aunque suena cursi cuando digo que quiero <color=#FFB400>proteger las cosas que más quiero</color>...",
  ui_story_7_9_A2_dialog_content = "Al final, ¿no se trata de luchar con todo lo que tienes para proteger a las personas y las cosas que te importan?",
  ui_story_7_9_29_dialog_content = "Cierto, como Soroz.",
  ui_story_7_9_30_dialog_content = "Cierto, Soroz.",
  ui_story_7_9_31_dialog_content = "PlayerName, ¿puedes sentir a Soroz? Será mejor que averigüemos si...",
  ui_story_7_9_32_dialog_content = "No puedo sentirlo, pero creo que todavía está vivo.",
  ui_story_7_9_33_dialog_content = "Nunca tuve la oportunidad de comunicarme con un Colossus. Tengo un poco de curiosidad por saber cómo es.",
  ui_story_7_9_A3_dialog_content = "Oh, lo siento, no te ofendas.",
  ui_story_7_9_34_dialog_content = "Pero usted, señora, ¿qué hace aquí?",
  ui_story_7_9_35_dialog_content = "Al igual que Carleen, ya he tenido suficiente de esa amenaza y también quiero darle su merecido.",
  ui_story_7_9_36_dialog_content = "Bueno, sigamos adelante. ¿Dónde está Schummer, PlayerName?",
  ui_story_7_9_37_dialog_content = "¡Siento la escalofriante presencia está en el <color=#FFB400>Puente</color>!",
  ui_story_7_9_A4_dialog_content = "Me temo que habrá muchos Eclipsites en el camino. ¿Están todos listos?",
  ui_story_7_9_A5_dialog_content = "¡Por supuesto! ¡Mi lanza siempre está lista para la acción!",
  ui_story_7_12_1_dialog_content = "PlayerName, no sé si puedes recibir este mensaje...",
  ui_story_7_12_2_dialog_content = "Ha sido un gran honor servirte. Me alegro de haberte protegido hace diecisiete años y de haber plantado las semillas de la esperanza en este mundo.",
  ui_story_7_12_3_dialog_content = "Si no es mucho pedir, <color=#FFB400>no vuelvas por mí</color>. Repito, <color=#FFB400>no vuelvas por mí</color>.",
  ui_story_7_12_A1_dialog_content = "El adversario es poderoso más allá de tu comprensión.",
  ui_story_7_12_4_dialog_content = "Sé fuerte, PlayerName. No pierdas el tiempo sintiéndote triste por mí.",
  ui_story_7_12_5_dialog_content = "Este Colossus <color=#FFB400>fue hecho para servirte</color>.",
  ui_story_7_13_1_dialog_content = "<size=45>¡Ay!</size>",
  ui_story_7_13_2_dialog_content = "(¡Mi corazón late <color=#FFB400>fuera de control</color>!)",
  ui_story_7_13_3_dialog_content = "¡Ahí está el puente! ¡Cuidado con los enemigos!",
  ui_story_7_13_4_dialog_content = "¿Todavía no hay forma de contactar a Soroz?",
  ui_story_7_13_5_dialog_content = "Lo estoy intentando. Creo que puedo escuchar algo. Suena como las mismas palabras repetidas una y otra vez.",
  ui_story_7_13_6_dialog_content = "Pero no puedo oírlo ahora. Tal vez sea...",
  ui_story_7_13_7_dialog_content = "(¿¡Mi corazón vuelve a latir fuera de control!?)",
  ui_story_7_13_8_dialog_content = "¿Qué pasa, PlayerName?",
  ui_story_7_13_9_dialog_content = "¿Es el Darkflow demasiado fuerte aquí para que PlayerName lo maneje?",
  ui_story_7_13_10_dialog_content = "¿O quizás estás sintiendo algo?",
  ui_story_7_13_11_dialog_content = "¿En serio? ¿Es Soroz?",
  ui_story_7_13_12_dialog_content = "No eso no es. Hasta yo lo sentí. ¿No te diste cuenta de cómo el <color=#FFB400>aire de repente se volvió frío</color>?",
  ui_story_7_13_13_dialog_content = "Este sentimiento familiar pero extraño debe ser esa desdichada arrogante y repugnante.",
  ui_story_7_13_14_dialog_content = "¡¿...?!",
  ui_story_7_13_15_dialog_content = "*Bostezos*",
  ui_story_7_13_16_dialog_content = "¡<size=45><color=#FFB400>Schummer</color>—!</size>",
  ui_story_7_13_17_dialog_content = "¡PlayerName! ¿Puedes sentir a Schummer? ¿Dónde está?",
  ui_story_7_13_18_dialog_content = "¿Qué le has hecho a Soroz, Schummer? ¡Ugh...!",
  ui_story_7_13_19_dialog_content = "Sigues siendo una plaga. No lo has aprendido, PlayerName.",
  ui_story_7_13_20_dialog_content = "¿Qué más puedo hacer con Soroz? Simplemente aplasté su plantilla de eco.",
  ui_story_7_13_21_dialog_content = "¿Plantilla de eco? ¿Destruiste la conciencia de Soroz?",
  ui_story_7_13_22_dialog_content = "Sí. ¿No sentiste, tu corazón hundido en la oscuridad y drenado de vida, el alma atravesada por un dolor indescriptible?",
  ui_story_7_13_23_dialog_content = "¡Schummer!",
  ui_story_7_13_24_dialog_content = "En caso de que aún no entiendas, déjame explicarte: Soroz está <color=#FFB400>muerto</color>.",
  ui_story_7_14_1_dialog_content = "¿Los perdimos?",
  ui_story_7_14_2_dialog_content = "¡Lo siento! Carleen corrió demasiado rápido para mí y desapareció en un instante...",
  ui_story_7_14_3_dialog_content = "Estaba patrullando arriba. ¡Todo lo que vi fue ese aterrador Colossus negro y un pequeño Colossus blanco!",
  ui_story_7_14_4_dialog_content = "Un Colossus blanco... Debe ser PlayerName. Los niños han salido a jugar.",
  ui_story_7_14_5_dialog_content = "¿El Colossus negro ha hecho algún movimiento?",
  ui_story_7_14_6_dialog_content = "No, todavía está atacando el escudo. Los Eclipsites también están atacando con toda su fuerza.",
  ui_story_7_14_7_dialog_content = "Mantén el escudo y da prioridad a la reserva de Lumina para restaurar el poder en los distritos de la nobleza y la infraestructura.",
  ui_story_7_14_A1_dialog_content = "Luego envía tropas para reforzar Baja Lumopolis.",
  ui_story_7_14_9_dialog_content = "¿Y Carleen?",
  ui_story_7_14_10_dialog_content = "Ella tomó su decisión, está preparada para aceptar las consecuencias.",
  ui_story_7_14_11_dialog_content = "Desde donde estoy parado, no hay razón para enviar Guardianes para que sigan su persecución sin sentido.",
  ui_story_7_14_12_dialog_content = "Sí.",
  ui_story_7_14_13_dialog_content = "Pero, ¿cómo consiguió ese dirigible? Sentó un precedente terrible.",
  ui_story_7_14_14_dialog_content = "Si otros Guardianes abandonan Lumopolis <color=#FFB400>para ayudarla</color>...",
  ui_story_7_14_15_dialog_content = "¿Por qué me miras?",
  ui_story_7_14_16_dialog_content = "¿Alguna pregunta más?",
  ui_story_7_14_17_dialog_content = "¡Oh, sí, lo entiendo!",
  ui_story_7_14_18_dialog_content = "Iré ahora. ¡Oh, quiero decir, pidiendo permiso para irme!",
  ui_story_7_14_19_dialog_content = "Más rápido, ratas. ¡Parece que te perderías en tu propia casa!",
  ui_story_7_14_20_dialog_content = "Cállate, Eclipsite. Si tienes unas últimas palabras, ¡dilas ahora!",
  ui_story_7_14_21_dialog_content = "Pareces haber entendido mal, princesa. Ahora poseo el poder de <color=#FFB400>todos los módulos</color>.",
  ui_story_7_14_X1_dialog_content = "Si no quieres seguir a PlayerName hasta el infierno, ¡es mejor que vuelvas a Lumopolis con el rabo entre las piernas!",
  ui_story_7_14_22_dialog_content = "No puedes romper el escudo de Lumopolis, ¿verdad? ¿Esperas que creamos que estás en plena potencia?",
  ui_story_7_14_23_dialog_content = "Silencio, Celestita. El Colossus negro aún no está lleno.",
  ui_story_7_14_A2_dialog_content = "Cuando llegue el tiempo, reservaré asientos de primera fila para todos.",
  ui_story_7_14_X2_dialog_content = "(¡Tal como pensamos, ella no ha completado el aumento!)",
  ui_story_7_14_X3_dialog_content = "No me mires así, PlayerName.",
  ui_story_7_14_24_dialog_content = "Tuve que venir y tratar contigo en persona mientras atacaba Lumopolis. Pones a prueba mi paciencia.",
  ui_story_7_14_25_dialog_content = "Díganme, Vice y PlayerName, ¿este Eclipsite es realmente tan poderoso?",
  ui_story_7_14_26_dialog_content = "A pesar de que parece difícil tratar con ella, esto debería ser muy fácil si trabajamos juntos, ¿no?",
  ui_story_7_14_27_dialog_content = "Sería más fácil si tuviéramos a Comandante Sharona...",
  ui_story_7_14_28_dialog_content = "Sigue soñando. Incluso si llamaras a todos tus aliados, aún no serías rival para eso.",
  ui_story_7_14_A3_dialog_content = "Mi Colossus se hace más fuerte con cada momento que pasa...",
  ui_story_7_14_29_dialog_content = "Sin embargo, debo decir que su optimismo es admirable. ¿Todos en Illumina están tan ciegos de confianza?",
  ui_story_7_14_30_dialog_content = "Sé breve, Schummer, no hay necesidad de parlotear.",
  ui_story_7_14_31_dialog_content = "Lo sé, cállate.",
  ui_story_7_14_32_dialog_content = "...",
  ui_story_7_14_33_dialog_content = "¿Qué pasa, señora?",
  ui_story_7_14_34_dialog_content = "La persona que mueve los hilos de Schummer parece <color=#FFB400>increíblemente familiar</color>.",
  ui_story_7_14_38_dialog_content = "Oye, ¿de qué estás susurrando? Incluso si estás gritando tus últimas palabras a todo pulmón, nadie las escuchará.",
  ui_story_7_14_39_dialog_content = "Pero PlayerName, eres especial.",
  ui_story_7_14_A4_dialog_content = "Sé que no estás dispuesto a permanecer débil, acobardado a la sombra de los fuertes por siempre. Eres igual que yo.",
  ui_story_7_14_40_dialog_content = "Ven, únete a nosotros. Elige el camino correcto.",
  ui_story_7_14_41_dialog_content = "Esta es la única forma en que obtendrás el poder de cambiar tu destino.",
  ui_story_7_14_42_dialog_content = "¿El poder de cambiar mi destino? ¿Qué quieres decir?",
  ui_story_7_14_43_dialog_content = "Visión, longevidad, conocimiento, poderoso Darkflow, la verdad de este mundo.",
  ui_story_7_14_44_dialog_content = "Lo más importante es que nunca tienes que preocuparte por ser derrotado, solo a quién deseas derrotar. Reinarás de forma suprema.",
  ui_story_7_14_46_dialog_content = "Ve al grano, tengo prisa.",
  ui_story_7_14_47_dialog_content = "¡Por qué, tú!",
  ui_story_7_14_48_dialog_content = "Lo siento, no me interesa nada de lo que tengas que decir.",
  ui_story_7_14_49_dialog_content = "Te gusta divagar y ni siquiera entiendes por qué. ¿Sabes siquiera lo que significa todo esto?",
  ui_story_7_14_50_dialog_content = "La verdad de este mundo. El poder de cambiar tu destino. Sin preocuparte por ser derrotado alguna vez.",
  ui_story_7_14_51_dialog_content = "Por eso que los que ponen en peligro la vida de otros no tienen lugar en este mundo.",
  ui_story_7_14_52_dialog_content = "¿Piensas que cuando te encuentras con alguien más débil que tú, debes eliminarlo, y cuando te encuentras con alguien más fuerte, debes arrodillarte, suplicar misericordia y someterte a un mayor poder?",
  ui_story_7_14_A5_dialog_content = "No puedo entender cómo te convenciste de eso. ¿De verdad crees que quiero ser como tú?",
  ui_story_7_14_53_dialog_content = "¿Estás presumiendo de ser recta y de nunca equivocarte?",
  ui_story_7_14_54_dialog_content = "Necesitas ver a un médico y que te revisen la cabeza. Nadie en su sano juicio podría estar tan ciego a la verdad.",
  ui_story_7_14_55_dialog_content = "...",
  ui_story_7_14_56_dialog_content = "¿De dónde vino eso, PlayerName?",
  ui_story_7_14_57_dialog_content = "¿Bien dicho...?",
  ui_story_7_14_F1_dialog_content = "Oh sí. Quería preguntarte, ¿cuánto tiempo estuviste de rodillas para obtener tu poder?",
  ui_story_7_14_58_dialog_content = "Gracioso.",
  ui_story_7_14_59_dialog_content = "<size=50>¡Muy gracioso!</size>",
  ui_story_7_14_60_dialog_content = "¡Miserable inútil! ¡Idiota! ¡Totalmente ciego!",
  ui_story_7_14_61_dialog_content = "¿Estás tratando de irritarme? ¿Tienes un deseo de muerte?",
  ui_story_7_14_63_dialog_content = "Oh, poniéndote seria ahora, ¿verdad?",
  ui_story_7_14_A6_dialog_content = "La ira es el catalizador perfecto para alcanzar un mayor poder.",
  ui_story_7_14_64_dialog_content = "¡Te mantendré vivo y te torturaré lentamente! ¡Te haré sentir humillación y desesperación!",
  ui_story_7_14_F2_dialog_content = "¡Entonces sabrás que tengo razón!",
  ui_story_7_14_65_dialog_content = "¡No, yo debería decirte eso, <color=#FFB400>Schummer, traidora de los Celestitas</color>!",
  ui_story_7_14_66_dialog_content = "¡Vamos! ¿¡Qué estás esperando!?",
  ui_story_7_14_67_dialog_content = "Ella es muy... muy fuerte... El poder...",
  ui_story_7_14_68_dialog_content = "Aún puedo moverme. ¡Prepárate para atacar de nuevo! No podemos dejar que se vaya...",
  ui_story_7_14_69_dialog_content = "¡No seas precipitado! Necesitamos encontrar una manera.",
  ui_story_7_14_70_dialog_content = "Odio admitirlo, pero PlayerName tiene razón...",
  ui_story_7_14_A7_dialog_content = "Es una suerte que no hayamos traído a nadie más. De lo contrario, todos estaríamos atrapados aquí.",
  ui_story_7_14_71_dialog_content = "Tal como está, ni siquiera podemos retirarnos.",
  ui_story_7_14_72_dialog_content = "¿Retirada? ¿Te quieres marchar? ¡Bien, puedes irte después de que te haga pedazos y te esparza al viento!",
  ui_story_7_14_73_dialog_content = "¡Los cielos de Lumopolis lloverán con tu sangre!",
  ui_story_7_14_74_dialog_content = "Se ha recargado, Schummer. El Colossus Negro ahora está <color=#FFB400>lleno</color>.",
  ui_story_7_14_75_dialog_content = "Justo a tiempo, ¿no es así? ¡Estas humildes criaturas que tenemos ante nosotros pueden servir como sacrificio para celebrar el nuevo nacimiento!",
  ui_story_7_14_76_dialog_content = "Lamento interrumpir, pero hay algo que necesito preguntar... ¿Quién eres tú?",
  ui_story_7_14_77_dialog_content = "¿Aún no lo sabes?",
  ui_story_7_14_78_dialog_content = "No tú. Hablo del que está detrás de ti. El poderoso Eclipsite de alto nivel.",
  ui_story_7_14_79_dialog_content = "...",
  ui_story_7_14_80_dialog_content = "No, eres más un <color=#FFB400>Aurorian</color> que un Eclipsite.",
  ui_story_7_14_81_dialog_content = "¿Aurorian?",
  ui_story_7_14_82_dialog_content = "Esa figura, el aura, la forma de hablar... Mi corazonada dice que no naciste Eclipsite.",
  ui_story_7_14_83_dialog_content = "Corazonada... Qué argumento poco inspirador.",
  ui_story_7_14_84_dialog_content = "¿<color=#FFB400>Quién eres</color>? Dime, debo saber.",
  ui_story_7_14_85_dialog_content = "Me niego.",
  ui_story_7_14_86_dialog_content = "<size=45>¡Dime! ¡Ahora!</size>",
  ui_story_7_14_87_dialog_content = "¿Por qué se está poniendo tan nerviosa de repente?",
  ui_story_7_14_88_dialog_content = "Una vez más, me niego. Porque...",
  ui_story_7_14_89_dialog_content = "Hace mucho tiempo que fui <color=#FFB400>despojado</color> de mi nombre.",
  ui_story_7_14_90_dialog_content = "...",
  ui_story_7_14_91_dialog_content = "En este maravilloso mundo, ¿cómo puede una persona sin nombre vivir dentro de <color=#FFB400>Illumina</color>?",
  ui_story_7_14_92_dialog_content = "¿Solías ser miembro de Illumina?",
  ui_story_7_14_94_dialog_content = "Sí.",
  ui_story_7_14_95_dialog_content = "Mira las cicatrices faciales. Fueron quemados en mi carne por una llama abrasadora. ¿Lo ves?",
  ui_story_7_14_97_dialog_content = "...",
  ui_story_7_14_F3_dialog_content = "¿Qué es?",
  ui_story_7_14_98_dialog_content = "¿Recuerdas algo?",
  ui_story_7_14_99_dialog_content = "No es tanto una idea, más bien una confirmación.",
  ui_story_7_14_100_dialog_content = "Eres tan entusiasta. Después de todos estos años, tu conocimiento es tan impresionante como siempre.",
  ui_story_7_14_101_dialog_content = "¿Se conocen, Vivian?",
  ui_story_7_14_102_dialog_content = "Más que eso, PlayerName...",
  ui_story_7_14_103_dialog_content = "Este Eclipsite de alto nivel fue una vez <color=#FFB400>mi socio en Illumina</color>.",
  ui_story_7_14_104_dialog_content = "¿Por qué es una sorpresa?",
  ui_story_7_14_A8_dialog_content = "Y tú, <color=#FFB400>Forsakin</color>, siempre me acusas de hablar demasiado, ¿por qué estás charlando con estas cucarachas ahora?",
  ui_story_7_14_105_dialog_content = "¿<color=#FFB400>Renegado</color>?",
  ui_story_7_14_109_dialog_content = "Solo poniéndome al día. Ya terminé. Siéntete libre de hacer lo que quieras.",
  ui_story_7_14_110_dialog_content = "Por cierto, mientras el Colossus se recarga, una parte significativa de su energía aún no está disponible.",
  ui_story_7_14_A9_dialog_content = "Encuentra un objetivo digno.",
  ui_story_7_14_111_dialog_content = "La ciudad de allí debería ser perfecta, ¿no?",
  ui_story_7_14_112_dialog_content = "Arrogante, corrupto, tontamente creyendo que su escudo es irrompible... ¡Romperé la fe de los Aurorians!",
  ui_story_7_14_113_dialog_content = "¡No te dejaré triunfar! Lumopolis nunca caerá. Cómo es posible que una simple Eclipsite...",
  ui_story_7_14_114_dialog_content = "<size=45>¡Cierra la boca, Aurorian!</size>",
  ui_story_7_14_115_dialog_content = "¡Ven, mi querido Colossus!",
  ui_story_7_14_116_dialog_content = "¡Con tu enorme cuerpo y tus ojos rojo sangre, hazlos temblar de miedo!",
  ui_story_7_14_117_dialog_content = "¿Ves ahora? Colossus Negro... Dragón Negro... No, tampoco es su nombre.",
  ui_story_7_14_118_dialog_content = "¡Si eso es! ¡Arrodíllate y adora! Todos alaben el poder de... ¡<size=45><color=#FFB400>Aviduz</color></size>!",
  ui_story_7_14_119_dialog_content = "¿Qué es eso, un Colossus? ¿Qué ha hecho? ¿Qué está pasando, PlayerName?",
  ui_story_7_14_120_dialog_content = "¿Cómo debería saberlo?",
  ui_story_7_14_121_dialog_content = "¡El Lumina se agota! ¡No, no podemos simplemente rendirnos!",
  ui_story_7_14_122_dialog_content = "No puedo moverme. ¿Alguno de ustedes puede moverse?",
  ui_story_7_14_123_dialog_content = "Prepárense todos. Te compraré algo de tiempo.",
  ui_story_7_14_128_dialog_content = "Su punto débil está a tus seis. Corre hacia él. Salta hacia abajo y existe la posibilidad de que vivas.",
  ui_story_7_14_129_dialog_content = "Vice, PlayerName, Carleen, nos vemos pronto.",
  ui_story_7_14_130_dialog_content = "¿Señora? ¿Eres tú...?",
  ui_story_7_14_131_dialog_content = "<size=50>¡Imposible!</size>",
  ui_story_7_14_133_dialog_content = "(Qué...)",
  ui_story_7_14_134_dialog_content = "(Sucedió...)",
  ui_story_8_1_1_1_dialog_content = "¿Qué estás mirando, PlayerName?",
  ui_story_8_1_1_2_dialog_content = "¡Te perderás si no sigues el ritmo!",
  ui_story_8_1_1_3_dialog_content = "Aquí, toma mi mano.",
  ui_story_8_1_1_4_dialog_content = "¿Qué pasa con esa mirada? ¿No acordamos ir al festival de Lumopolis?",
  ui_story_8_1_1_5_dialog_content = "¡Mira, bocadillos! ¡Veamos qué están vendiendo!",
  ui_story_8_1_1_6_option_content = "¿Dónde estamos?",
  ui_story_8_1_1_7_dialog_content = "¿No sabes? ¡Estás en Lumopolis!",
  ui_story_8_1_1_8_option_content = "¿Qué está pasando?",
  ui_story_8_1_1_9_dialog_content = "¿Qué más? Este festival solo viene una vez al año, ¡así que tenemos que divertirnos!",
  ui_story_8_1_1_10_dialog_content = "¿Qué pasa contigo? No me estás engañando, ¿verdad?",
  ui_story_8_1_1_11_dialog_content = "¡Me enojaré contigo si estás así! *Pucheros*",
  ui_story_8_1_1_12_option_content = "Estás actuando raro, Vice.",
  ui_story_8_1_1_13_dialog_content = "¿Lo estoy? Para nada, ¡sigo siendo tu linda y pequeña Vice!",
  ui_story_8_1_1_14_dialog_content = "¡No pienses demasiado y date prisa, o me enojaré de verdad!",
  ui_story_8_1_1_15_option_content = "¿Quién eres?",
  ui_story_8_1_1_16_dialog_content = "¿Qué pasa? ¡Soy Vice! ¿Quién más puedo ser?",
  ui_story_8_1_1_17_dialog_content = "¿Qué pasa con el interrogatorio? ¡Ven aquí o me enojaré de verdad!",
  ui_story_8_1_1_18_dialog_content = "...",
  ui_story_8_1_1_19_dialog_content = "¿Qué es ese ruido?",
  ui_story_8_1_1_20_dialog_content = "¿Escuchaste algo?",
  ui_story_8_1_1_21_dialog_content = "Algo no está bien aquí, Vice. No me siento bien, como...",
  ui_story_8_1_1_22_dialog_content = "Todo está en tu cabeza, PlayerName. Estás a salvo conmigo, así que confía en mí.",
  ui_story_8_1_1_23_dialog_content = "Si todavía tiene muchas preguntas, puedo responderlas todas. Pero por favor, solo toma mi mano, ¿de acuerdo?",
  ui_story_8_1_1_24_dialog_content = "Te diré. Te lo cuento todo...",
  ui_story_8_1_1_25_dialog_content = "¿PlayerName?",
  ui_story_8_1_1_26_dialog_content = "El pasado, el futuro, lo que quieras saber.",
  ui_story_8_1_1_27_dialog_content = "¡Vayamos juntos hacia el futuro!",
  ui_story_8_1_1_28_dialog_content = "Así que no me dejes sola. Nos prometimos el uno al otro, ¿no?",
  ui_story_8_1_1_29_dialog_content = "¿No puedes oír eso? ¡Eres sordo, PlayerName!",
  ui_story_8_1_1_30_option_content = "Te prometo que nunca te dejaré.",
  ui_story_8_1_1_31_dialog_content = "¡Estoy tan contenta de que finalmente lo entiendas! Nunca me puedes dejar ahora.",
  ui_story_8_1_1_32_dialog_content = "¡Suelta tu caparazón, Celestita, y abraza tu verdadero poder!",
  ui_story_8_1_1_33_option_content = "Me voy. No lo harás, Vice.",
  ui_story_8_1_1_34_dialog_content = "¡Espera, vuelve! ¡Estúpido Celestita!",
  ui_story_8_1_1_35_dialog_content = "¡La mayoría de la gente solo podría soñar con una oportunidad como esta! Eres tonto. ¡Lástima, trágicamente tonto!",
  ui_story_8_1_1_36_dialog_content = "Escúchame, necesitas escapar de esta dulce pero peligrosa fantasía...",
  ui_story_8_1_1_37_dialog_content = "Ven, sigue a Wispy y te llevará a la verdad.",
  ui_story_8_1_1_38_dialog_content = "¡¡Kyuu!!",
  ui_story_8_1_1_39_dialog_content = "(¡Ugh! ¿Por qué tengo tanto dolor?)",
  ui_story_8_1_1_42_dialog_content = "(¿Qué es esto que sale volando de mi cuerpo?)",
  ui_story_8_1_1_43_dialog_content = "(¿Qué es eso? Y por qué...)",
  ui_story_8_1_1_44_dialog_content = "*Rugidos*",
  ui_story_8_1_1_45_dialog_content = "¡¡Kyuu!!",
  ui_story_8_1_1_47_dialog_content = "¡Eres Curie, una de las seguidoras de Vivian!",
  ui_story_8_1_1_48_dialog_content = "¡¡¡Kyuu!!!",
  ui_story_8_1_1_49_dialog_content = "¿Dónde está tu amo? ¿Y dónde está Vice?",
  ui_story_8_1_1_50_dialog_content = "Esa cosa, ¿vino del interior de mi cuerpo? ¿Qué demonios fue eso?",
  ui_story_8_1_1_51_dialog_content = "Ay, me duele la cabeza... Ay, demasiado dolor... ¿Me golpeé la cabeza?",
  ui_story_8_1_1_52_dialog_content = "¡Kyuu!",
  ui_story_8_1_1_53_dialog_content = "Pobre pequeño Curie. ¿Cómo terminaste con todas estas lesiones? ¿También te separaste?",
  ui_story_8_1_1_54_dialog_content = "Me pregunto cómo les irá ahora.",
  ui_story_8_1_1_55_dialog_content = "¡Imposible!",
  ui_story_8_1_1_58_dialog_content = "Ay, ay, ay... No puedo recordar nada después de eso.",
  ui_story_8_1_1_59_dialog_content = "Me pregunto qué le va a Vice y a los demás...",
  ui_story_8_1_1_60_dialog_content = "¡PlayerName!",
  ui_story_8_1_1_61_dialog_content = "¿Vice?",
  ui_story_8_1_1_62_dialog_content = "Shh, silencio. Soy yo...",
  ui_story_8_1_1_63_dialog_content = "¿Estás bien? ¡Este lugar está lleno de Darkflow! Yo solo...",
  ui_story_8_1_1_64_dialog_content = "¡Lo se! Estoy bien. ¿Y tú? ¿Estás herida? ¡Déjame ver!",
  ui_story_8_1_1_65_option_content = "No me siento bien.",
  ui_story_8_1_1_66_dialog_content = "Me siento mal. No creo estar herido, pero mi cuerpo se siente pesado...",
  ui_story_8_1_1_67_dialog_content = "Incluso mi cabeza se siente confusa... ¿Qué tipo de lugar es éste?",
  ui_story_8_1_1_68_dialog_content = "¿No te acuerdas? Estamos dentro de Aviduz, PlayerName.",
  ui_story_8_1_1_69_option_content = "No recuerdo.",
  ui_story_8_1_1_70_dialog_content = "No recuerdo... Acabo de despertarme... Así es, ¡estaba teniendo una pesadilla!",
  ui_story_8_1_1_71_dialog_content = "Estabas en eso, pero no eras tú mismo en absoluto... No, no, no podrías haber sido tú.",
  ui_story_8_1_1_F1_dialog_content = "Y había alguien más.",
  ui_story_8_1_1_72_dialog_content = "¿Un sueño? ¿Soñaste conmigo, pero no era como yo? ¿Quién era la otra persona?",
  ui_story_8_1_1_F2_dialog_content = "No estoy seguro de lo que está pasando, lo siento.",
  ui_story_8_1_1_73_dialog_content = "¿Entonces, qué? ¿Te despertaste aquí? ¿Nada más?",
  ui_story_8_1_1_F3_dialog_content = "Exacto. Me desperté aquí.",
  ui_story_8_1_1_74_dialog_content = "Está bien. Puede haber sido el Darkflow afectando tu mente. Estamos dentro de Aviduz, después de todo.",
  ui_story_8_1_1_75_option_content = "¿Dónde estamos?",
  ui_story_8_1_1_76_dialog_content = "Estamos dentro de Aviduz, el Colossus.",
  ui_story_8_1_1_77_dialog_content = "Esta es la primera vez que veo un Colossus como este, si es que se le puede llamar Colossus.",
  ui_story_8_1_1_78_dialog_content = "¡Mira! Puedes ver las manchas de Darkflow en todas partes. Este es un patio de recreo para Eclipsites.",
  ui_story_8_1_1_79_dialog_content = "También me encontré con muchos de ellos en mi camino hacia aquí. Espero no haber hecho demasiado ruido.",
  ui_story_8_1_1_80_dialog_content = "Espera, dijiste...",
  ui_story_8_1_1_81_dialog_content = "¡¿Estamos DENTRO de Aviduz?!",
  ui_story_8_1_1_82_dialog_content = "Correcto. Descubrí que Schummer te arrastró hasta aquí, y luego...",
  ui_story_8_1_1_83_dialog_content = "La seguí adentro.",
  ui_story_8_1_1_84_dialog_content = "¿Qué pasa? ¿Por qué la seguirías a un lugar como este?",
  ui_story_8_1_1_88_dialog_content = "¡Para rescatarte, claro! Nos ayudaste alejándonos, pero permaneciste en Soroz. Cómo podría yo...",
  ui_story_8_1_1_89_dialog_content = "Espera un segundo, ¿qué pasó antes?",
  ui_story_8_1_1_90_dialog_content = "No, ¡pase lo que pase no es excusa para hacer algo tan peligroso como venir aquí tras de mí!",
  ui_story_8_1_1_91_dialog_content = "Lo sé, pero ¿qué se suponía que debía hacer? ¿Esperar y mirar?",
  ui_story_8_1_1_92_dialog_content = "Pensé que tal vez aún estabas vivo y que aún podía hacer algo.",
  ui_story_8_1_1_93_dialog_content = "Entiendo como te sientes Vice, pero aun así...",
  ui_story_8_1_1_94_dialog_content = "No sirve de nada discutir al respecto, PlayerName, ¡estoy aquí ahora!",
  ui_story_8_1_1_95_dialog_content = "Ahora tenemos que averiguar qué hacer a continuación. ¡En tus pies!",
  ui_story_8_1_1_96_dialog_content = "¡Kyuu!",
  ui_story_8_1_1_97_dialog_content = "Apóyame, Curie, y hazla entrar en razón, ¿quieres?",
  ui_story_8_1_1_98_dialog_content = "Cuéntame qué pasó antes. Siempre que trato de recordar, mi cabeza comienza a latir como loca.",
  ui_story_8_1_1_99_dialog_content = "¡Levántate primero! No podemos quedarnos aquí, te lo diré mientras caminamos.",
  ui_story_8_1_1_100_dialog_content = "La jefa Vivian acababa de dar la orden de retirarse, pero luego Schummer...",
  ui_story_8_1_1_101_dialog_content = "Prepárense todos. Te compraré algo de tiempo.",
  ui_story_8_1_1_103_dialog_content = "Su punto débil está a tus seis. Corre hacia él. Salta hacia abajo y existe la posibilidad de que sobrevivas.",
  ui_story_8_1_1_104_dialog_content = "Vice, PlayerName, Carleen, nos vemos pronto.",
  ui_story_8_1_1_105_dialog_content = "Señora, ¿estás...?",
  ui_story_8_1_1_106_dialog_content = "¡Imposible!",
  ui_story_8_1_1_107_dialog_content = "¡¡Tu oponente soy yo!!",
  ui_story_8_1_1_108_dialog_content = "Qué inesperado. ¡De hecho, luchas decentemente por una escoria inútil!",
  ui_story_8_1_1_109_dialog_content = "...",
  ui_story_8_1_1_110_dialog_content = "En ese caso, ¡al menos intenta hacer esto interesante!",
  ui_story_8_1_1_111_dialog_content = "¡¿Y adónde crees que vas?!",
  ui_story_8_1_1_112_dialog_content = "¡Rápido, salta!",
  ui_story_8_1_1_113_dialog_content = "¿De esta altura? Supongo que no tenemos otra opción... ¡Vamos!",
  ui_story_8_1_1_114_dialog_content = "¡Toma mi mano! Saltaremos juntos...",
  ui_story_8_1_1_115_dialog_content = "*Rugidos*",
  ui_story_8_1_1_116_dialog_content = "¡Suéltame!",
  ui_story_8_1_1_117_dialog_content = "¡¡PlayerName!!",
  ui_story_8_1_1_118_dialog_content = "(¡¡Nos están arrastrando de regreso!!)",
  ui_story_8_1_1_119_dialog_content = "No me quedan fuerzas... Como podemos...",
  ui_story_8_1_1_120_dialog_content = "...",
  ui_story_8_1_1_121_option_content = "¡Ve!",
  ui_story_8_1_1_122_dialog_content = "¡¿?!",
  ui_story_8_1_1_123_dialog_content = "¡PlayerName!",
  ui_story_8_1_1_124_dialog_content = "¡Está muy alto! ¡No lo lograremos!",
  ui_story_8_1_1_125_dialog_content = "¡Intenta estabilizar tu caída, Vice! Al menos tú puedes...",
  ui_story_8_1_1_126_dialog_content = "¡¡¡Carleen!!!",
  ui_story_8_1_1_127_dialog_content = "¡¡Te tengo!!",
  ui_story_8_1_1_128_dialog_content = "¿Raphaela? Por qué... ¡Uh! ¡Duele!",
  ui_story_8_1_1_129_dialog_content = "Este dirigible... ¿Pediste refuerzos, Carleen?",
  ui_story_8_1_1_130_dialog_content = "¡Oye, supongo que podrías llamarlo así! ¡Yo, la gran Raphaela, he venido a sacarte de este asqueroso lugar!",
  ui_story_8_1_1_131_dialog_content = "¡Parece que no es un muy pronto! Si hubiera llegado unos segundos después...",
  ui_story_8_1_1_132_dialog_content = "Eep...",
  ui_story_8_1_1_133_dialog_content = "¿Qué es ese ruido?",
  ui_story_8_1_1_134_dialog_content = "¿Ah? Creo que escuché algo debajo de mi trasero...",
  ui_story_8_1_1_135_dialog_content = "¡¡Kyuu!!",
  ui_story_8_1_1_136_dialog_content = "¡¿Curie?!",
  ui_story_8_1_1_137_dialog_content = "¡Perdóname, no me di cuenta de que estaba sentada encima de ti todo este tiempo!",
  ui_story_8_1_1_138_dialog_content = "¡Kyuu!",
  ui_story_8_1_1_139_dialog_content = "¿Es esa tu mascota, Vice?",
  ui_story_8_1_1_140_dialog_content = "No, ella pertenece al jefe Vivian.",
  ui_story_8_1_1_141_dialog_content = "¿Oh? ¿Dónde está? Y, ¿dónde está el Celestita?",
  ui_story_8_1_1_142_dialog_content = "Ellos están...",
  ui_story_8_1_1_143_dialog_content = "...",
  ui_story_8_1_1_144_dialog_content = "¡No es el momento de discutir estas cosas, Raphaela! La situación ha cambiado drásticamente. ¡Salgamos de aquí e informemos al Señor de la Ciudad lo antes posible!",
  ui_story_8_1_1_145_dialog_content = "PlayerName nos dio la oportunidad de escapar. No podemos desperdiciarla.",
  ui_story_8_1_1_146_dialog_content = "Tenemos que encontrar una forma de contraatacar.",
  ui_story_8_1_1_147_dialog_content = "Entonces, ¿tienes un plan, Carleen?",
  ui_story_8_1_1_148_dialog_content = "Sí. Regresamos y convencemos a ese hombre de que use Damocles.",
  ui_story_8_1_1_149_dialog_content = "¡¿?!",
  ui_story_8_1_1_150_dialog_content = "Esa es la única forma de tener una oportunidad contra Schummer.",
  ui_story_8_1_1_151_dialog_content = "Pero Damocles no se ha activado durante más de diez años, ¿verdad? ¿Estará de acuerdo?",
  ui_story_8_1_1_152_dialog_content = "¡Haré que esté de acuerdo! Solo Damocles puede detener a Aviduz ahora.",
  ui_story_8_1_1_153_dialog_content = "Pero PlayerName...",
  ui_story_8_1_1_154_dialog_content = "Este asunto se refiere a la supervivencia misma de Lumopolis. No tengo otra opción. No tenemos opciones, Vice.",
  ui_story_8_1_1_155_dialog_content = "...",
  ui_story_8_1_1_156_dialog_content = "¿Bien? ¿Qué tienes en mente?",
  ui_story_8_1_1_157_dialog_content = "¿Deseas volver a Soroz?",
  ui_story_8_1_1_158_dialog_content = "Sí.",
  ui_story_8_1_1_159_dialog_content = "Lo siento, Carleen, pero no puedo dejar a PlayerName ni a la Jefa Vivian atrás.",
  ui_story_8_1_1_160_dialog_content = "Vice...",
  ui_story_8_1_1_161_dialog_content = "Entiendo cómo te sientes, Carleen, ¡pero no puedo simplemente abandonar a mis amigos! ¡No lo haré!",
  ui_story_8_1_1_162_dialog_content = "Cálmate, Vice. ¡Es demasiado peligroso volver ahora!",
  ui_story_8_1_1_164_dialog_content = "¿O quieres que el sacrificio de PlayerName sea en vano?",
  ui_story_8_1_1_165_dialog_content = "Entiendo el peligro, Carleen. Descubriré algo.",
  ui_story_8_1_1_166_dialog_content = "¿Cómo qué? ¡Solo tenemos un dirigible!",
  ui_story_8_1_1_167_dialog_content = "Cierto.",
  ui_story_8_1_1_168_dialog_content = "Tú tampoco tienes alas, querida Vice. Por qué no...",
  ui_story_8_1_1_169_dialog_content = "...",
  ui_story_8_1_1_170_dialog_content = "Curie, cuenta contigo.",
  ui_story_8_1_1_171_dialog_content = "¿Kyuu?",
  ui_story_8_1_1_172_dialog_content = "¡¿Kyuu?!",
  ui_story_8_1_1_173_dialog_content = "Curie y yo podríamos volver juntos.",
  ui_story_8_1_1_174_dialog_content = "¿Estás segura que Curie es lo bastante fuerte para llevarte?",
  ui_story_8_1_1_175_dialog_content = "No soy exactamente ligera como una pluma, ¡pero Curie es muy fuerte!",
  ui_story_8_1_1_176_dialog_content = "¡Kyuu!",
  ui_story_8_1_1_177_dialog_content = "Entiendo, Curie. Quieres volver y rescatar a tu amo, ¿verdad?",
  ui_story_8_1_1_180_dialog_content = "Si te vas, despega de aquí. Aún estamos lo bastante cerca para que lo consigas.",
  ui_story_8_1_1_181_dialog_content = "Carleen...",
  ui_story_8_1_1_182_dialog_content = "Sé que no puedo cambiar tu opinión, así como tú no puedes cambiar la mía. Siempre hemos marchado a nuestro ritmo.",
  ui_story_8_1_1_183_dialog_content = "Solo recuerda mantenerte alerta. La suerte siempre ha estado de tu lado.",
  ui_story_8_1_1_184_dialog_content = "Ya sea activando a Soroz o arriesgando tu cuello para salvar a Gronru.",
  ui_story_8_1_1_185_dialog_content = "Pero, ¿y si finalmente tu suerte se acaba?",
  ui_story_8_1_1_186_dialog_content = "Creo en PlayerName. Sé que encontraremos una manera de escapar, como siempre.",
  ui_story_8_1_1_187_dialog_content = "Creo que mientras no nos rindamos, podemos hacer que suceda un milagro.",
  ui_story_8_1_1_188_dialog_content = "A veces no puedo lidiar con tu optimismo, Vice.",
  ui_story_8_1_1_189_dialog_content = "Ve. Ya que estaré ocupado convenciendo a otro viejo tonto, no iré contigo esta vez.",
  ui_story_8_1_1_190_dialog_content = "¡Cuida del Celestita por mí, Vice!",
  ui_story_8_1_1_191_dialog_content = "¡Ten cuidado también, Carleen! Si puedes activar Damocles, ¡Schummer se llevará una sorpresa!",
  ui_story_8_1_1_192_dialog_content = "¡Le espera algo más que eso! Solo espero que puedas salir a tiempo.",
  ui_story_8_1_1_193_dialog_content = "¡Volveremos antes de que te des cuenta, Carleen!",
  ui_story_8_1_1_194_dialog_content = "Hasta pronto, Vice.",
  ui_story_8_1_1_195_dialog_content = "(Hablando en Eclipsiano) ¡Allí! ¡Derriba eso! ¡Rápido!",
  ui_story_8_1_1_196_dialog_content = "(Hablando en Eclipsiano) ¡Salva todo lo que sea útil! ¡Nuestro maestro necesita más materiales de construcción para completar el Colossus!",
  ui_story_8_1_1_197_dialog_content = "(Hablando en Eclipsiano) ¡¿Escuchaste eso?!",
  ui_story_8_1_1_198_dialog_content = "¿¡Graagh!?",
  ui_story_8_1_1_200_dialog_content = "No grites, eres el único en esta habitación. ¿Dónde están los otros Eclipsites? ¿Ya se han ido de Soroz?",
  ui_story_8_1_1_201_dialog_content = "¡Nunca te perdonaré por derribar la amada casa de PlayerName de esta manera!",
  ui_story_8_1_1_202_dialog_content = "(Hablando en Eclipsiano) Escoria Aurorian... Debo advertir al maestro...",
  ui_story_8_1_1_203_dialog_content = "Lo siento, estoy segura de que no esperabas esto, pero tengo algo que preguntar.",
  ui_story_8_1_1_204_dialog_content = "¡¡Urraagh!!",
  ui_story_8_1_1_205_dialog_content = "Sé que es posible que no entiendas ni una sola palabra de lo que digo, pero...",
  ui_story_8_1_1_206_dialog_content = "Hay dos personas muy importantes, PlayerName y Jefa Vivian, y necesito saber dónde están.",
  ui_story_8_1_1_207_dialog_content = "(Hablando en Eclipsiano) ¿Quieres decir que ese Celestita es tu amigo? ¿No te escapaste ya? Mujer estúpida...",
  ui_story_8_1_1_208_dialog_content = "No puedo entenderte. Que pérdida de tiempo.",
  ui_story_8_1_1_209_dialog_content = "Si no puedes hablar Universés, ¡qué tal si usamos lápiz y papel!",
  ui_story_8_1_1_210_dialog_content = "?",
  ui_story_8_1_1_211_dialog_content = "Lo sacaré...",
  ui_story_8_1_1_212_dialog_content = "¿Dónde está esta persona?",
  ui_story_8_1_1_213_dialog_content = "(Hablando en Eclipsiano) ¡Lo sabía, estás aquí por el Celestita!",
  ui_story_8_1_1_214_dialog_content = "(Hablando en Eclipsiano) Recuerdo que el Celestita está en... No.",
  ui_story_8_1_1_215_dialog_content = "Oye, ¿qué estás mirando?",
  ui_story_8_1_1_216_dialog_content = "(Hablando en Eclipsiano) ¿Por qué te lo diría, asqueroso gusano? Si crees que puede interrumpir los planes del maestro, entonces...",
  ui_story_8_1_1_217_dialog_content = "¡Uh!",
  ui_story_8_1_1_218_dialog_content = "¿Estaba mirando en dirección a Aviduz?",
  ui_story_8_1_1_219_dialog_content = "Kyuu, kyuu...",
  ui_story_8_1_1_220_dialog_content = "¿Estás bien? ¿Te estás quedando sin vapor? Debes estar cansado de llevarme hasta aquí.",
  ui_story_8_1_1_221_dialog_content = "¡Kyuu!",
  ui_story_8_1_1_222_dialog_content = "Mientras sigas bien... Lo siento, Curie, pero necesito contar contigo una vez más.",
  ui_story_8_1_1_223_dialog_content = "¡Siguiente parada, Aviduz! ¡Ahí es donde probablemente encontraremos PlayerName y Jefa Vivian!",
  ui_story_8_1_1_224_dialog_content = "¡¿Kyuu?!",
  ui_story_8_1_1_225_dialog_content = "¿Así es como te infiltraste? ¿Eso realmente funcionó?",
  ui_story_8_1_1_226_dialog_content = "Puede parecer un poco difícil de creer, pero fue todo Curie.",
  ui_story_8_1_1_227_dialog_content = "Kyuu...",
  ui_story_8_1_1_228_dialog_content = "Parece que Curie está listo para dejarme caer.",
  ui_story_8_1_1_229_dialog_content = "Realmente ha sido duro para Curie. ¡Tendrá un gran regalo cuando regresemos!",
  ui_story_8_1_1_230_option_content = "Vámonos de aquí, entonces.",
  ui_story_8_1_1_231_dialog_content = "¡Kyuu!",
  ui_story_8_1_1_232_dialog_content = "Pero todavía no hemos encontrado a la Jefa Vivian, PlayerName.",
  ui_story_8_1_1_233_dialog_content = "Si te queda algo, espero que puedas aguantar un poco más.",
  ui_story_8_1_1_234_dialog_content = "¡Entonces podremos escapar todos juntos!",
  ui_story_8_1_1_235_option_content = "Pero no he visto a Vivian en ningún lugar.",
  ui_story_8_1_1_236_dialog_content = "Kyuu...",
  ui_story_8_1_1_237_dialog_content = "Creo que ella también terminó atrapada aquí, así que la vamos a encontrar.",
  ui_story_8_1_1_238_dialog_content = "No importa lo que esté planeando Schummer, ¡no podemos dejar atrás a la Jefe!",
  ui_story_8_1_1_239_dialog_content = "Ya me siento mucho mejor. ¡Hagámoslo!",
  ui_story_8_1_1_240_dialog_content = "¡Muy bien, vamos!",
  ui_story_8_1_1_241_dialog_content = "¡Kyuu!",
  ui_story_8_2_1_1_dialog_content = "Lo siento, profesor, ¿podría demostrarlo una vez más?",
  ui_story_8_2_1_2_dialog_content = "Fallé de nuevo. Supongo que todavía no puedo hacerlo.",
  ui_story_8_2_1_3_dialog_content = "Profesor... ¡¿Profesor?!",
  ui_story_8_2_1_4_dialog_content = "¡Oye!",
  ui_story_8_2_1_5_dialog_content = "¿En tu propio pequeño mundo de nuevo?",
  ui_story_8_2_1_6_dialog_content = "...",
  ui_story_8_2_1_7_dialog_content = "Cálmate. Pronto demostrarás tu valía ante ese Celestita, ¿no?",
  ui_story_8_2_1_8_dialog_content = "Suficiente.",
  ui_story_8_2_1_9_dialog_content = "No necesito discursos de motivación, y menos de ti.",
  ui_story_8_2_1_10_dialog_content = "Está bien.",
  ui_story_8_2_1_11_dialog_content = "...",
  ui_story_8_2_1_12_dialog_content = "No perdoné la vida de PlayerName por algo tan trillado como probarme a mí misma, Forsakin.",
  ui_story_8_2_1_13_dialog_content = "Oh...",
  ui_story_8_2_1_14_dialog_content = "Pero no lo entenderías, incluso si te lo explicara.",
  ui_story_8_2_1_15_dialog_content = "En cualquier caso, es lo mismo que cuando perdonaste a esa dama de Illumina.",
  ui_story_8_2_1_16_dialog_content = "No es lo mismo. Tú y yo no podríamos ser más diferentes.",
  ui_story_8_2_1_17_dialog_content = "Después de todo, no tengo nada que ver con Illumina, pero tú eres un Celestita.",
  ui_story_8_2_1_18_dialog_content = "¡¿A quién llamas Celestita?!",
  ui_story_8_2_1_19_dialog_content = "Tómalo con calma. Esta conversación terminó.",
  ui_story_8_2_1_20_dialog_content = "¡Estás tan lleno de eso!",
  ui_story_8_2_1_21_dialog_content = "Mas tarde.",
  ui_story_8_2_1_22_dialog_content = "¿Y adónde crees que vas?",
  ui_story_8_2_1_23_dialog_content = "Ya le he dado a ese Celestita el poder que tienes. Creo que pronto podrán volver a llamarse \"mi compañero\".",
  ui_story_8_2_1_24_dialog_content = "¿Qué quieres decir? ¡No te pedí que hicieras algo así!",
  ui_story_8_2_1_25_dialog_content = "¡Ella no tiene sentido!",
  ui_story_8_2_1_26_dialog_content = "¿Qué diablos está haciendo ella aquí? ¡Desde el día en que nos conocimos, ella siempre ha sido así!",
  ui_story_8_2_1_27_dialog_content = "Si no vas a ayudar, olvídalo. Cuando me estaba concentrando en Lumopolis, ella todavía estaba buscando problemas...",
  ui_story_8_2_1_28_dialog_content = "Schummer, me ofrezco a ayudar en tus esfuerzos bajo la orden de Señorita Forsakin...",
  ui_story_8_2_1_29_dialog_content = "Pero cuidado cómo le hablas.",
  ui_story_8_2_1_30_dialog_content = "Tsk. Supongo que no puede dejar esto en paz, ¿no?",
  ui_story_8_2_1_31_dialog_content = "El lugar está en un estado de completo caos...",
  ui_story_8_2_1_32_dialog_content = "Bueno, ¿PlayerName? ¿Pudiste hacerlo?",
  ui_story_8_2_1_33_dialog_content = "Sí. Me las arreglé para establecer un vínculo con este Colossus, pero no puedo entenderlo.",
  ui_story_8_2_1_F1_dialog_content = "No, no es que no puedas entenderlo.",
  ui_story_8_2_1_34_dialog_content = "No tiene una Plantilla de eco propia. Está completamente en blanco.",
  ui_story_8_2_1_35_dialog_content = "Ten cuidado, podría disparar una alarma.",
  ui_story_8_2_1_36_dialog_content = "No te preocupes, Vice. Siempre tengo cuidado.",
  ui_story_8_2_1_37_dialog_content = "Y mis poderes pueden evitar que haga sonar la alarma y mantener nuestra presencia oculta.",
  ui_story_8_2_1_F2_dialog_content = "¿Tus habilidades psíquicas pueden hacer eso?",
  ui_story_8_2_1_F3_dialog_content = "Sí. Después aprendí a usar la inmersión psíquica. Puedo hacer bastantes cosas con solo una pequeña cantidad de energía psíquica.",
  ui_story_8_2_1_38_dialog_content = "¿Eres capaz de sentir a la Jefa Vivian?",
  ui_story_8_2_1_F4_dialog_content = "Lo siento, pero no me atrevería a usar más poder del que ya uso ahora.",
  ui_story_8_2_1_F5_dialog_content = "Estamos en el Aviduz, así que puedo usar mis poderes directamente a través del tacto.",
  ui_story_8_2_1_39_dialog_content = "Pero si hago una investigación extensa, Schummer nos encontrará.",
  ui_story_8_2_1_40_dialog_content = "Entiendo. Tendremos que confiar en nuestros propios ojos para encontrarla, después de todo.",
  ui_story_8_2_1_41_dialog_content = "¿Cómo te sientes? ¿Crees que puedes resistir la Materia Oscura aquí?",
  ui_story_8_2_1_42_dialog_content = "Estoy bien ahora. Ya no me duele la cabeza.",
  ui_story_8_2_1_43_dialog_content = "Es más, me siento mejor ahora, como si hubiera despertado de un largo y reparador sueño.",
  ui_story_8_2_1_44_dialog_content = "¿En serio? Eso es extraño. De vuelta en el Pasillo Susurrante, se ve que no podías con el Darkflow.",
  ui_story_8_2_1_45_dialog_content = "¡Kyuu!",
  ui_story_8_2_1_46_dialog_content = "¿Qué hueles, Curie?",
  ui_story_8_2_1_47_dialog_content = "¡Achuu!",
  ui_story_8_2_1_48_dialog_content = "Kyuu...",
  ui_story_8_2_1_49_dialog_content = "El Darkflow aquí es tan denso que incluso Curie no puede soportarlo ...",
  ui_story_8_2_1_50_dialog_content = "Eres muy lento.",
  ui_story_8_2_1_51_dialog_content = "¿Quién está ahí?",
  ui_story_8_2_1_52_dialog_content = "Tardaste mucho más de lo esperado y la rueda del destino no se detiene para nadie.",
  ui_story_8_2_1_53_dialog_content = "Ven, Celestita, lo que buscas está al final de este pasillo.",
  ui_story_8_2_1_54_dialog_content = "¿Quién eres? ¿Eres Aurorian o Eclipsite?",
  ui_story_8_2_1_55_dialog_content = "Shh... No importa. Todo lo que importa pasará. Aquello que buscamos ardientemente...",
  ui_story_8_2_1_56_dialog_content = "La verdad.",
  ui_story_8_2_1_57_dialog_content = "¿Qué te pasa, PlayerName? Te ves terrible...",
  ui_story_8_2_1_58_dialog_content = "Acabo de ver algo extraño.",
  ui_story_8_2_1_59_dialog_content = "Un hombre de blanco que lleva una maleta. Me dijo que fuera por ese camino.",
  ui_story_8_2_1_60_dialog_content = "¿Qué pasa? ¿Dónde está?",
  ui_story_8_2_1_F6_dialog_content = "Quizás lo sentí. Dijo que fuera por ese camino. Parecía digno de confianza.",
  ui_story_8_2_1_F7_dialog_content = "Pero no está claro camino es \"ese camino\" en absoluto.",
  ui_story_8_2_1_61_dialog_content = "No estoy muy familiarizado con el interior de Aviduz, pero considerando los caminos que hemos tomado...",
  ui_story_8_2_1_62_dialog_content = "Bueno, ¡puedo dibujar un mapa simple!",
  ui_story_8_2_1_63_dialog_content = "Afortunadamente, todavía tengo este papel.",
  ui_story_8_2_1_64_dialog_content = "¿Qué son estas líneas que dibujaste allí, Vice?",
  ui_story_8_2_1_65_dialog_content = "¡Ignora eso! ¡Eso no es nada!",
  ui_story_8_2_1_66_dialog_content = "Y estas personitas que dibujaste...",
  ui_story_8_2_1_68_dialog_content = "¡Los dibujé para poder preguntarles dónde estás!",
  ui_story_8_2_1_F8_dialog_content = "¿Ese soy yo?",
  ui_story_8_2_1_69_dialog_content = "Lo admito, no es exactamente una obra maestra, ¡pero hizo el trabajo!",
  ui_story_8_2_1_70_dialog_content = "En fin, ¡deja de divagar! Debo trazar la ruta que acabamos de tomar mientras me acuerdo.",
  ui_story_8_2_1_72_dialog_content = "(¿El Eclipsite puede realmente entender esta imagen?)",
  ui_story_8_2_1_73_dialog_content = "Y pongamos una escala aquí, entonces...",
  ui_story_8_2_1_74_dialog_content = "¡Hecho!",
  ui_story_8_2_1_75_dialog_content = "(No debería reírme de la falta de habilidades. Ella se esforzó mucho, después de todo.)",
  ui_story_8_2_1_76_dialog_content = "Es... excelente, ¡cómo el sueño de un cartógrafo!",
  ui_story_8_2_1_77_dialog_content = "Servirá. Solo puedo manejar cosas simples como esta con el tiempo que tenemos.",
  ui_story_8_2_1_78_dialog_content = "¡Sencillo! Puedo entender cómo podrías dibujar figuras tan \"finas\", ¿¡pero también puedes dibujar mapas así de bien!?",
  ui_story_8_2_1_79_dialog_content = "Ya te lo dije antes, lo estudié en Illumina.",
  ui_story_8_2_1_80_dialog_content = "Además, la reparación y el mantenimiento de Soroz requieren este tipo de conocimiento.",
  ui_story_8_2_1_81_dialog_content = "¡Kyuu!",
  ui_story_8_2_1_82_dialog_content = "¿Qué pasa, Curie?",
  ui_story_8_2_1_83_dialog_content = "¡Kyuu! ¡Kyuu!",
  ui_story_8_2_1_84_dialog_content = "¿Por aquí? Pero...",
  ui_story_8_2_1_85_dialog_content = "¿No es donde señaló el hombre?",
  ui_story_8_2_1_86_dialog_content = "¡Curie ha captado la esencia de Vivian, PlayerName! ¡Vamos!",
  ui_story_8_2_1_87_dialog_content = "(Supongo que el hombre no es un enemigo...)",
  ui_story_8_2_1_88_dialog_content = "Estoy seguro de que habrá muchos Eclipsites allí. ¡Eliminémoslos lo más rápido posible!",
  ui_story_8_2_1_89_dialog_content = "¡Prepárate para luchar!",
  ui_story_8_2_2_1_dialog_content = "<color=#e8d9bb>Zona residencial, Jardines de Lumopolis</color>",
  ui_story_8_2_2_2_dialog_content = "Quieres activar...",
  ui_story_8_2_2_3_dialog_content = "¿Damocles?",
  ui_story_8_2_2_5_dialog_content = "Correcto. ¡Es nuestra única solución al problema actual!",
  ui_story_8_2_2_6_dialog_content = "¿Eres consciente de lo que estás diciendo, Carleen?",
  ui_story_8_2_2_7_dialog_content = "Para iniciar eso, necesitaremos una resolución tripartita, además de los protocolos necesarios.",
  ui_story_8_2_2_F1_dialog_content = "¿¡Tienes idea de cuánta energía consume!?",
  ui_story_8_2_2_8_dialog_content = "¡Drenará toda la energía del escudo! ¡Toda Lumopolis se detendrá!",
  ui_story_8_2_2_9_dialog_content = "Lo se.",
  ui_story_8_2_2_10_dialog_content = "¡Debes estar loco para siquiera considerar esto!",
  ui_story_8_2_2_11_dialog_content = "Otto.",
  ui_story_8_2_2_12_dialog_content = "Hmph.",
  ui_story_8_2_2_13_dialog_content = "Mi Señor, no ha visto de lo que son capaces Schummer y el Colossus Negro, ¡pero yo sí! ¡Solo pude escapar saltando desde su parte superior!",
  ui_story_8_2_2_14_dialog_content = "¡Nadie puede detener al Colossus Negro completamente recargado, y mucho menos mientras lucha contra sus aliados!",
  ui_story_8_2_2_15_dialog_content = "¡Debemos hacer nuestro último esfuerzo! Nuestro escudo no nos protegerá para siempre, está destinado a caer eventualmente.",
  ui_story_8_2_2_16_dialog_content = "¿Estás herida?",
  ui_story_8_2_2_17_dialog_content = "¿Qué?",
  ui_story_8_2_2_18_dialog_content = "¿Estás herida, Carleen?",
  ui_story_8_2_2_19_dialog_content = "Cuando Raphaela te rescató, ella dijo que nunca te había visto en tal estado antes. Parecías tan derrotada.",
  ui_story_8_2_2_20_dialog_content = "...",
  ui_story_8_2_2_21_dialog_content = "Aprecio tu preocupación, mi Señor, pero estoy perfectamente bien.",
  ui_story_8_2_2_22_dialog_content = "Seguro.",
  ui_story_8_2_2_23_dialog_content = "Entonces, ¿qué piensan los demás?",
  ui_story_8_2_2_24_dialog_content = "Ya hablé mi paz. Sacrificar Lumopolis es un precio muy alto a pagar.",
  ui_story_8_2_2_25_dialog_content = "¿Qué dice el Salón de Justicia?",
  ui_story_8_2_2_26_dialog_content = "Estoy de acuerdo con la resolución. Si la propuesta es aceptada por las tres partes, así será.",
  ui_story_8_2_2_27_dialog_content = "De lo contrario, el Salón de Justicia rechaza de plano la idea, independientemente del proponente.",
  ui_story_8_2_2_28_dialog_content = "Muy bien. Celebremos un breve consejo sobre el tema.",
  ui_story_8_2_2_29_dialog_content = "Otto, como representante del Consejo de Ancianos, estoy seguro de que vetará la propuesta.",
  ui_story_8_2_2_30_dialog_content = "Por supuesto.",
  ui_story_8_2_2_31_dialog_content = "Irridon, como juez principal del Salón de Justicia, ¿cuál es tu decisión?",
  ui_story_8_2_2_32_dialog_content = "Me abstengo.",
  ui_story_8_2_2_33_dialog_content = "Está bien...",
  ui_story_8_2_2_34_dialog_content = "Finalmente, yo, Schwartz, Señor de la Ciudad de Lumopolis y el representante de las familias nobles ...",
  ui_story_8_2_2_35_dialog_content = "Por lo tanto la propuesta.",
  ui_story_8_2_2_36_dialog_content = "¡...!",
  ui_story_8_2_2_37_dialog_content = "Dos votos en contra, uno se abstuvo. El Salón de Justicia no actuará sobre esta propuesta.",
  ui_story_8_2_2_38_dialog_content = "Tu padre comprende claramente la importancia de proteger Lumopolis, Carleen.",
  ui_story_8_2_2_39_dialog_content = "¡Qué farsa! ¡Quién diría que la llamada \"resolución tripartita\" podía comenzar y terminar tan casual!",
  ui_story_8_2_2_40_dialog_content = "En tiempos de crisis, no es necesario que las decisiones pasen por un proceso fijo. Mientras el Salón de Justicia esté presente y reconozca el voto, es igualmente válido.",
  ui_story_8_2_2_41_dialog_content = "Ahora respeta nuestra decisión, Carleen.",
  ui_story_8_2_2_42_dialog_content = "Pero...",
  ui_story_8_2_2_43_dialog_content = "¿Oyes eso? Tenemos que poner toda nuestra energía en usarlo, incluso desactivando el escudo.",
  ui_story_8_2_2_44_dialog_content = "¡Es esencialmente un suicidio! Al menos todavía tenemos el escudo ahora mismo.",
  ui_story_8_2_2_45_dialog_content = "Honestamente, pensarías que la hija del Señor de la Ciudad sabría mejor que eso.",
  ui_story_8_2_2_46_dialog_content = "...",
  ui_story_8_2_2_47_dialog_content = "Carleen.",
  ui_story_8_2_2_48_dialog_content = "...",
  ui_story_8_2_2_49_dialog_content = "¡Levanta la cabeza y mira bien, Carleen de Schwartz!",
  ui_story_8_2_2_50_dialog_content = "¡Esto es Lumopolis! ¡No una banda errante de aventureros volando en un Colossus!",
  ui_story_8_2_2_51_dialog_content = "Esta ciudad no necesita esas caprichosas nociones, ¿entiendes?",
  ui_story_8_2_2_52_dialog_content = "...",
  ui_story_8_2_2_53_dialog_content = "¡Responde a mi pregunta! ¡¿Lo entiendes?!",
  ui_story_8_2_2_54_dialog_content = "Sí, mi Señor.",
  ui_story_8_2_2_55_dialog_content = "Hasta que tengamos pleno conocimiento de la situación, mantener nuestros escudos es nuestra mejor estrategia. En cuanto a activar Damocles...",
  ui_story_8_2_2_56_dialog_content = "Está completamente fuera de discusión.",
  ui_story_8_2_2_57_dialog_content = "¡Todo se arruinará y no tendremos forma de detenerlo! Carleen, no eres diferente de cuando eras una niña. ¡No has aprendido nada!",
  ui_story_8_2_2_58_dialog_content = "¿...?",
  ui_story_8_2_2_59_dialog_content = "Cuando te caíste de la casa del árbol por intentar salvar a un gato, pensé que era el colmo de tu tontería.",
  ui_story_8_2_2_60_dialog_content = "¡Pero ahora veo que no has madurado en absoluto desde entonces!",
  ui_story_8_2_2_61_dialog_content = "(¿Casa del árbol...?)",
  ui_story_8_2_2_62_dialog_content = "Aunque salvaste a ese gato y tomaste la decisión correcta, ¿qué importaba?",
  ui_story_8_2_2_63_dialog_content = "¿Valió la pena ir en contra del mejor juicio de los demás y romperse la pierna por la vida de ese gato?",
  ui_story_8_2_2_64_dialog_content = "(¿...?)",
  ui_story_8_2_2_65_dialog_content = "¡Te hice una pregunta! ¡¿Valió la pena?!",
  ui_story_8_2_2_66_dialog_content = "¿Cuál es el significado de esto, Schwartz? ¿Por qué mencionas historias familiares aquí?",
  ui_story_8_2_2_67_dialog_content = "¿Estaba hablando contigo, Otto Troy?",
  ui_story_8_2_2_68_dialog_content = "...",
  ui_story_8_2_2_69_dialog_content = "Sí.",
  ui_story_8_2_2_70_dialog_content = "Creo que valió la pena, padre.",
  ui_story_8_2_2_71_dialog_content = "Así veo. Entonces estás más allá de toda esperanza, Carleen.",
  ui_story_8_2_2_72_dialog_content = "Ve, enciérrate en la torre de marfil, como ese gato tuyo.",
  ui_story_8_2_2_73_dialog_content = "...",
  ui_story_8_2_2_74_dialog_content = "Vaya, las palabras del Señor cortan como un cuchillo...",
  ui_story_8_2_2_75_dialog_content = "Pero, ¿qué sentido tenía sacar a relucir el pasado? Mas bien peculiar, si no un poco espeluznante.",
  ui_story_8_2_2_77_dialog_content = "¿Por qué sonríes, Carleen? ¡Esto se está poniendo aún más espeluznante ahora!",
  ui_story_8_2_2_78_dialog_content = "Porque creo saber lo que estaba tratando de decirme.",
  ui_story_8_2_2_79_dialog_content = "¿Ah?",
  ui_story_8_2_2_80_dialog_content = "La casa del árbol, el gato. Eso sucedió en el pasado.",
  ui_story_8_2_2_81_dialog_content = "Pero...",
  ui_story_8_2_2_82_dialog_content = "No pude salvar al gato.",
  ui_story_8_2_2_83_dialog_content = "¿El Señor de la Ciudad recordó mal? O es eso...",
  ui_story_8_2_2_84_dialog_content = "Es posible...",
  ui_story_8_2_2_85_dialog_content = "¿¡Qué el Señor de la Ciudad se está volviendo senil!?",
  ui_story_8_2_2_86_dialog_content = "No lo entiendes, pero está bien. Sígueme, hay un lugar al que debemos ir.",
  ui_story_8_2_2_87_dialog_content = "¡Muy bien! ¿A dónde?",
  ui_story_8_2_2_88_dialog_content = "...",
  ui_story_8_2_2_89_dialog_content = "A sala de control de Damocles.",
  ui_story_8_3_1_1_dialog_content = "<color=#e8d9bb>Dentro de Aviduz</color>",
  ui_story_8_3_1_2_dialog_content = "¡Jejeje! Jejeje♪",
  ui_story_8_3_1_3_dialog_content = "Lo siento, me dejé llevar un poco.",
  ui_story_8_3_1_4_dialog_content = "¡Ven, sigue por aquí! Es la primera vez que hago turismo aquí también.",
  ui_story_8_3_1_5_dialog_content = "¡Kyuu!",
  ui_story_8_3_1_6_dialog_content = "(Curie puede rastrear el olor de Vivian. Si cree que deberíamos ir en esta dirección...)",
  ui_story_8_3_1_7_dialog_content = "Sigue adelante. Este debe ser el camino.",
  ui_story_8_3_1_8_dialog_content = "...",
  ui_story_8_3_1_9_dialog_content = "¿Qué ocurre? ¿Por qué me miras así?",
  ui_story_8_3_1_10_dialog_content = "¿Estás seguro que estás bien? Apenas puedo soportar el Darkflow aquí, pero ¿estás bien?",
  ui_story_8_3_1_11_dialog_content = "¡Oh, estoy bien, de verdad!",
  ui_story_8_3_1_12_dialog_content = "Es extraño, pero el Darkflow aquí apenas me afecta en absoluto. Al contrario, creo que...",
  ui_story_8_3_1_13_dialog_content = "Que huele bastante bien.",
  ui_story_8_3_1_14_dialog_content = "¿Ah?",
  ui_story_8_3_1_15_dialog_content = "Aunque me pica un poco la piel. ¿Crees que podría ser una alergia?",
  ui_story_8_3_1_16_dialog_content = "¿Produce picazón? Déjame ver.",
  ui_story_8_3_1_17_dialog_content = "Está bien, es sobre todo en mi espalda. Si pudieras rascarlo por mí...",
  ui_story_8_3_1_18_dialog_content = "Pero más importante...",
  ui_story_8_3_1_19_option_content = "No te sentías muy bien, ¿verdad? ¿Vice?",
  ui_story_8_3_1_20_dialog_content = "Siempre poniendo a otros antes que a ti, ¿eh?",
  ui_story_8_3_1_21_dialog_content = "Estoy bien. Esto es difícil, pero nada es peor que cuando Schummer me tuvo bajo su control.",
  ui_story_8_3_1_22_dialog_content = "He crecido mucho entonces, PlayerName.",
  ui_story_8_3_1_23_dialog_content = "¡Solo espero que podamos seguir superando cualquier cosa que venga!",
  ui_story_8_3_1_24_dialog_content = "Claro que podemos. ¡No pararemos hasta vencer a Schummer!",
  ui_story_8_3_1_25_dialog_content = "¡Ese es el espíritu, PlayerName!",
  ui_story_8_3_1_26_option_content = "Me pregunto cómo le va a Carleen...",
  ui_story_8_3_1_27_dialog_content = "Ya debería estar de vuelta en Lumopolis.",
  ui_story_8_3_1_28_dialog_content = "Ella debe estar luchando contra Schummer a su manera, lo sé.",
  ui_story_8_3_1_29_dialog_content = "Entonces, ¿qué ES Damocles? ¿Es una especie de arma superpoderosa?",
  ui_story_8_3_1_30_dialog_content = "No lo he visto por mí mismo, pero escuché sobre su poder cuando estaba estudiando allí.",
  ui_story_8_3_1_31_dialog_content = "Según todos, es el último recurso devastador que solo se usa en circunstancias más difíciles.",
  ui_story_8_3_1_32_dialog_content = "Parece que tampoco sabes exactamente qué es.",
  ui_story_8_3_1_33_option_content = "¿Dónde está la Jefa Vivian?",
  ui_story_8_3_1_34_dialog_content = "No estoy segura, pero a juzgar por la reacción de Curie, ¡debe estar por delante!",
  ui_story_8_3_1_35_dialog_content = "¡Curie seguro nos llevará hasta Vivian!",
  ui_story_8_3_1_36_dialog_content = "Si no fuera por Vivian, es posible que no tuviéramos la oportunidad de escapar.",
  ui_story_8_3_1_37_dialog_content = "Tú también has hecho mucho por nosotros, PlayerName, y al final, incluso tomaste una decisión como esa.",
  ui_story_8_3_1_38_dialog_content = "¿Te refieres a cuando empujé a las dos?",
  ui_story_8_3_1_39_dialog_content = "Tal vez fue solo una especie de reacción instintiva, subconsciente. Casi me olvido de lo que pasó.",
  ui_story_8_3_1_40_dialog_content = "En cualquier caso, espero que no vuelvas a hacer nada parecido.",
  ui_story_8_3_1_41_dialog_content = "Siempre atacas sin pensarlo dos veces, como esa vez con Gronru y yo...",
  ui_story_8_3_1_42_dialog_content = "¡¡¡Kyuu!!!",
  ui_story_8_3_1_43_dialog_content = "Lo siento, Curie tiene prisa. ¡Vamos, aceleremos el paso!",
  ui_story_8_3_1_44_dialog_content = "PlayerName, deberías prestar más atención a su bienestar físico.",
  ui_story_8_3_1_46_dialog_content = "¡Entendido! ¡No te preocupes por mí!",
  ui_story_8_6_1_1_dialog_content = "Muy brillante...",
  ui_story_8_6_1_3_option_content = "¡No! ¡Necesito esconderme!",
  ui_story_8_6_1_4_dialog_content = "¿PlayerName? ¿Qué haces ahí en la esquina?",
  ui_story_8_6_1_5_dialog_content = "¿Qué estás haciendo? ¡Ven aquí!",
  ui_story_8_6_1_6_dialog_content = "¡Kyuu!",
  ui_story_8_6_1_7_dialog_content = "¡Lo siento! Es tan brillante que me aturdió por un segundo.",
  ui_story_8_6_1_8_dialog_content = "¿Brillante? Es solo una cuarto normal.",
  ui_story_8_6_1_9_dialog_content = "¿No puedes manejar ni esto?",
  ui_story_8_6_1_10_dialog_content = "No estoy seguro. Está bien, creo que mis ojos se están adaptando ahora.",
  ui_story_8_6_1_11_option_content = "Ay, la picazón...",
  ui_story_8_6_1_12_dialog_content = "¿Entonces tus ojos están bien ahora, pero la espalda te pica de nuevo?",
  ui_story_8_6_1_13_dialog_content = "Sí. ¿Crees que necesito ver a un médico?",
  ui_story_8_6_1_14_dialog_content = "Tomemos un descanso. No hay nadie aquí, así que podemos reagruparnos un poco...",
  ui_story_8_6_1_15_dialog_content = "¡Kyuu!",
  ui_story_8_6_1_16_dialog_content = "¿A dónde vas, Curie?",
  ui_story_8_6_1_17_dialog_content = "¡Kyuu! ¡Kyuu!",
  ui_story_8_6_1_18_dialog_content = "¿Es Vivian? ¿Está ella aquí en alguna parte?",
  ui_story_8_6_1_19_dialog_content = "¡Kyuu! ¡Kyuu! ¡Kyuu!",
  ui_story_8_6_1_20_dialog_content = "¡Encontraremos una manera de abrir la puerta, Curie! ¡Qué no cunda el pánico! Si nos encuentran...",
  ui_story_8_6_1_21_dialog_content = "(Este aroma... ¿Podría ser...?)",
  ui_story_8_6_1_22_dialog_content = "¡¡Cuidado, Vice!!",
  ui_story_8_6_1_23_dialog_content = "¡Graaaah!",
  ui_story_8_6_1_24_dialog_content = "¡Vienen justo por ti!",
  ui_story_8_6_1_25_dialog_content = "¡Eso es un éxito! ¡Tengo algunos más, pero no podemos dejar que avisen a otros Eclipsites!",
  ui_story_8_6_1_26_dialog_content = "¡Deshazte del resto!",
  ui_story_8_6_1_27_dialog_content = "Déjamelo a mí. ¡Terminaré con esto rápidamente!",
  ui_story_8_6_2_1_dialog_content = "Bien, no llamamos más la atención.",
  ui_story_8_6_2_2_dialog_content = "Me pregunto si alguno de ellos logró escapar.",
  ui_story_8_6_2_3_dialog_content = "¡Ten cuidado detrás de ti!",
  ui_story_8_6_2_4_dialog_content = "¡Urraagh!",
  ui_story_8_6_2_5_dialog_content = "(¡¿Pasó por mi lado?!)",
  ui_story_8_6_2_6_dialog_content = "Uf. Parece que el Darkflow me está afectando después de todo. Casi dejo que uno se escape.",
  ui_story_8_6_2_7_dialog_content = "Um, Vice...",
  ui_story_8_6_2_8_dialog_content = "Ese Eclipsite pasó corriendo a mi lado. ¡No, era como si no me hubiera visto!",
  ui_story_8_6_2_9_dialog_content = "También me di cuenta de eso, y no solo ahora. Parece que se han interesado cada vez menos en ti.",
  ui_story_8_6_2_10_dialog_content = "Es casi como si...",
  ui_story_8_6_2_11_dialog_content = "No te consideran un enemigo.",
  ui_story_8_6_2_12_dialog_content = "...",
  ui_story_8_6_2_13_dialog_content = "¿Pero por qué?",
  ui_story_8_6_2_14_dialog_content = "No estoy seguro. ¿Estás bien, PlayerName? ¿Sientes alguna molestia?",
  ui_story_8_6_2_15_dialog_content = "No lo sé, Vice.",
  ui_story_8_6_2_16_dialog_content = "¡Kyuu!",
  ui_story_8_6_2_17_dialog_content = "Lo sé, Curie, pero PlayerName...",
  ui_story_8_6_2_18_dialog_content = "Estoy bien. Si la Jefa Vivian está aquí, ¡rescatarla tiene prioridad!",
  ui_story_8_7_1_A1_dialog_content = "¿Mamá? ¿Papá?",
  ui_story_8_7_1_A2_dialog_content = "¿No cayó ya la ciudad? Me alegro mucho de que estés bien.",
  ui_story_8_7_1_1_dialog_content = "Sí, tómalo. Deja que haga realidad tus sueños más dulces.",
  ui_story_8_7_1_2_dialog_content = "Blanco y puro, marcado con el signo del origen. (Habla en Eclipsiano) Regalo de madre.",
  ui_story_8_7_1_3_dialog_content = "Desbloquea el potencial oculto dentro de su caparazón físico, reuniéndolo para crear un poder incomparable.",
  ui_story_8_7_1_4_dialog_content = "Más importante aún, te trae a nuestro redil, como uno más.",
  ui_story_8_7_1_5_dialog_content = "Rápido, ven al templo de nuestro origen...",
  ui_story_8_7_1_6_dialog_content = "No me importa lo que tengas. ¡Aléjate de ella, Eclipsite!",
  ui_story_8_7_1_7_dialog_content = "¿Aurorian? ¿Cuándo llegaste aquí?",
  ui_story_8_7_1_8_dialog_content = "¿Puedes oírme, señora?",
  ui_story_8_7_1_9_dialog_content = "Mmm...",
  ui_story_8_7_1_10_dialog_content = "¡Gracias a Dios estás viva!",
  ui_story_8_7_1_11_dialog_content = "Tus compañeros, haciendo todo lo posible para rescatarte.",
  ui_story_8_7_1_12_dialog_content = "¿O están prestando atención a la llamada de Eclipse?",
  ui_story_8_7_1_A3_dialog_content = "Soy Caída de sol y es un placer ser tu guía.",
  ui_story_8_7_1_13_dialog_content = "¿\"Llamada de Eclipse\"? Si es una invitación para convertirse en ustedes horribles Eclipsites, ¡no gracias!",
  ui_story_8_7_1_14_dialog_content = "(Hablando en Eclipsiano) ¡Ya deberías haberte convertido, Celestita!",
  ui_story_8_7_1_15_dialog_content = "No puedo entenderte. ¿Alguna posibilidad de que hables Universés?",
  ui_story_8_7_1_16_dialog_content = "¿Por qué el maestro no nos advirtió? No se envió una sola alerta. ¿Qué has hecho?",
  ui_story_8_7_1_17_dialog_content = "Ese es mi poder, Eclipsite. Puedo establecer un vínculo mental con Aviduz, hasta cierto punto. ¿Entiendes?",
  ui_story_8_7_1_18_dialog_content = "Siempre y cuando no hagamos demasiado ruido, debería ser más que suficiente permanecer oculto y apagar las alarmas.",
  ui_story_8_7_1_19_dialog_content = "Un desarrollo inesperado, pero no importa. Si tu olor es una indicación...",
  ui_story_8_7_1_20_dialog_content = "Pronto te convertirás en uno de nosotros, Celestita.",
  ui_story_8_7_1_21_dialog_content = "¿Qué quieres decir?",
  ui_story_8_7_1_F1_dialog_content = "PlayerName, ¡no dejes que se meta en tu mente!",
  ui_story_8_7_1_22_dialog_content = "¿Qué estabas haciendo a Vivian? ¿Qué es esa cosa brillante?",
  ui_story_8_7_1_23_dialog_content = "(Hablando en Eclipsiano) Una pregunta sin sentido.",
  ui_story_8_7_1_24_dialog_content = "¡No pruebes mi paciencia, Eclipsite! ¡No tengo tiempo para jugar contigo!",
  ui_story_8_7_1_25_dialog_content = "¡Es un regalo! ¡Un regalo de Mamá!",
  ui_story_8_7_1_26_dialog_content = "Nuestro maestro se esforzó mucho por hacer esto. Ella pudo aplastarte en un parpadear, sin embargo, te dejó ir por una razón.",
  ui_story_8_7_1_27_dialog_content = "Incluso te invitó gentilmente aquí y te bendijo con un poder recién descubierto.",
  ui_story_8_7_1_28_dialog_content = "¡Es un honor! ¡¡El más alto de los honores!!",
  ui_story_8_7_1_29_dialog_content = "¿\"El regalo de la Madre\"? ¡¿De qué estás hablando?!",
  ui_story_8_7_1_30_dialog_content = "¡Basta de preguntas! Pronto aprenderás.",
  ui_story_8_7_1_31_dialog_content = "No me digas...",
  ui_story_8_7_1_32_dialog_content = "¡No escuches una palabra! Todavía hay tiempo. ¡Vamos a acabar con ellos!",
  ui_story_8_7_1_33_dialog_content = "¡Tú otra vez! ¿Dónde estás?",
  ui_story_8_7_1_34_dialog_content = "¿Importa? Podría estar detrás de ti, por lo que sabes.",
  ui_story_8_7_1_35_dialog_content = "¡Tú! Si quieres seguir siendo Celestita, ¡haz lo que te digo! ¡Acaba con ellos y hazlo rápido!",
  ui_story_8_7_1_36_dialog_content = "(Hablando en Eclipsiano) Tiembla ante nuevas vistas frente ante ti. ¡Descarta tu vergonzosa ignorancia!",
  ui_story_8_7_1_37_dialog_content = "¡Uh!",
  ui_story_8_7_1_38_dialog_content = "¡Algo se mueve en mi cuerpo, Vice! No, es una especie de poder...",
  ui_story_8_7_1_39_dialog_content = "Algún tipo de energía...",
  ui_story_8_7_1_40_dialog_content = "¡Mantén la calma y concéntrate, PlayerName!",
  ui_story_8_7_1_41_dialog_content = "¡Argh! ¡Mi cabeza! ¡Se siente como si se partiera en dos!",
  ui_story_8_7_1_43_dialog_content = "¡Tan fuerte! ¡Tienes que salir de él, PlayerName!",
  ui_story_8_7_1_44_option_content = "Lo sé, debo estar consciente...",
  ui_story_8_7_1_45_dialog_content = "Llegas muy tarde. Nuestro plan ha dado sus frutos.",
  ui_story_8_7_1_46_dialog_content = "La Semilla echó raíces y ha comenzado a brotar. Puedo escuchar sus aullidos ahora.",
  ui_story_8_7_1_47_dialog_content = "¡Una preciosa nueva alma para Madre!",
  ui_story_8_7_1_48_option_content = "Mantente consciente...",
  ui_story_8_7_1_49_dialog_content = "¡¡¡Kyuu!!!",
  ui_story_8_7_1_51_dialog_content = "¡Hagamos esto, Curie!",
  ui_story_8_7_1_52_dialog_content = "Que lamentable. ¡Sin el Celestita, no eres nada!",
  ui_story_8_7_1_53_dialog_content = "¡Uh!",
  ui_story_8_7_1_54_dialog_content = "PlayerName...",
  ui_story_8_7_1_55_dialog_content = "¿Qué estás haciendo acá?",
  ui_story_8_7_1_56_dialog_content = "¡No deberías perder así!",
  ui_story_8_7_1_57_dialog_content = "Eres Celestita. Nadie debería poder controlarte.",
  ui_story_8_7_1_58_option_content = "(¡Mantente consciente!)",
  ui_story_8_7_1_59_dialog_content = "¿...?",
  ui_story_8_7_1_60_dialog_content = "Eso estuvo cerca, casi pierdo el control.",
  ui_story_8_7_1_61_dialog_content = "¿¡Detuviste la transformación!?",
  ui_story_8_7_1_62_dialog_content = "¡Shh, cállate!",
  ui_story_8_7_1_63_dialog_content = "No has dejado de hablar todo este tiempo y me está dando un maldito dolor de cabeza.",
  ui_story_8_7_1_64_dialog_content = "¡No, esto no puede ser! ¿Cómo resististe a la Semilla?",
  ui_story_8_7_1_65_dialog_content = "Yap, yap, yap... Basta ya.",
  ui_story_8_7_1_66_dialog_content = "Eres tan ruidosa que Schummer pudo oírnos.",
  ui_story_8_7_1_67_dialog_content = "Aunque creo que ahora puedes gritar todo lo que quieras. He restablecido el vínculo mental con Aviduz.",
  ui_story_8_7_1_F2_dialog_content = "Estoy controlando el Colossus y he insonorizado completamente esta habitación.",
  ui_story_8_7_1_68_dialog_content = "Tus llantos no llegarán a los oídos de esa supuesta Madre.",
  ui_story_8_7_1_69_dialog_content = "Me alegro que vuelvas a tu normalidad, PlayerName.",
  ui_story_8_7_1_70_dialog_content = "Ahora estoy bien. Perdón por dejarte solo con esa cosa.",
  ui_story_8_7_1_71_dialog_content = "Me empieza a doler la cabeza de nuevo, pero creo que puedo soportarlo un rato.",
  ui_story_8_7_1_73_dialog_content = "¡Ingratos tontos! ¡Profanadores de los dones de la Madre! ¡Solo hay un lugar para escorias como tú!",
  ui_story_8_7_1_74_dialog_content = "¡¡Tarde o temprano, te convertirás en uno de nosotros!!",
  ui_story_8_7_1_75_dialog_content = "Calla esa cosa, Vice.",
  ui_story_8_7_1_76_dialog_content = "La Jefa Vivian todavía nos espera.",
  ui_story_8_7_1_77_dialog_content = "¡Está bien!",
  ui_story_8_7_2_1_dialog_content = "¡Señora!",
  ui_story_8_7_2_2_dialog_content = "¡Kyuu! ¡Kyuu!",
  ui_story_8_7_2_4_dialog_content = "Mmm...",
  ui_story_8_7_2_5_dialog_content = "Señora, te ves terrible. Lo siento, llegamos tan rápido como pudimos.",
  ui_story_8_7_2_6_dialog_content = "Quizás deberías preocuparte por ti antes de preocuparte por los demás.",
  ui_story_8_7_2_7_dialog_content = "¿Quién está ahí?",
  ui_story_8_7_2_8_dialog_content = "¡Eres tú! Vice, lo he visto antes. Él es quien me mostró el camino.",
  ui_story_8_7_2_9_dialog_content = "¿Es el hombre de el Maletín Blanco que mencionaste?",
  ui_story_8_7_2_10_dialog_content = "No soy tu enemigo. Como puedes ver, soy Aurorian.",
  ui_story_8_7_2_11_dialog_content = "Puedes llamarme Faust. Soy un sirviente de la Verdad.",
  ui_story_8_7_2_12_dialog_content = "¿La Verdad? ¿Por qué suena algo sospechoso?",
  ui_story_8_7_2_13_dialog_content = "La Verdad es el principio de orden eterno e inmutable, y la ley de todas las cosas. No te preocupes. Estoy aquí para ayudar.",
  ui_story_8_7_2_14_dialog_content = "Esa introducción no nos ayudó a entender quién eres en absoluto.",
  ui_story_8_7_2_15_dialog_content = "Eso no es importante en este momento. Concéntrate en tu mente...",
  ui_story_8_7_2_16_dialog_content = "La Semilla dentro de ti está comenzando a brotar.",
  ui_story_8_7_2_17_dialog_content = "¡¿Qué es esta semilla de la que todos hablan?!",
  ui_story_8_7_2_18_dialog_content = "Te lo explicaré luego. Debemos ocuparnos de eso ahora.",
  ui_story_8_7_2_19_dialog_content = "Quítate la ropa, PlayerName.",
  ui_story_8_7_2_20_dialog_content = "¿Qué?",
  ui_story_8_7_2_21_dialog_content = "Ahora no es el momento de ser tímido. Por favor, haz lo que te digo.",
  ui_story_8_7_2_22_dialog_content = "¿Sientes alguna sensación extraña en tu cuerpo?",
  ui_story_8_7_2_23_dialog_content = "Bueno, tan pronto como dijiste eso, mi espalda volvió a picarme.",
  ui_story_8_7_2_24_dialog_content = "Entonces, está en tu espalda.",
  ui_story_8_7_2_25_dialog_content = "Créeme, puedo ayudarte.",
  ui_story_8_7_2_26_option_content = "Bien, me desvestiré.",
  ui_story_8_7_2_27_dialog_content = "...",
  ui_story_8_7_2_28_dialog_content = "También ropa interior.",
  ui_story_8_7_2_29_dialog_content = "¿Debería alejarme, PlayerName?",
  ui_story_8_7_2_30_dialog_content = "No es nada raro ni nada, solo la parte de atrás. Por favor, no tardes demasiado.",
  ui_story_8_7_2_31_option_content = "Bien, me desvestiré...",
  ui_story_8_7_2_32_dialog_content = "Bueno...",
  ui_story_8_7_2_33_dialog_content = "Lo sabía.",
  ui_story_8_7_2_34_dialog_content = "¿Qué es? ¿Qué tengo en la espalda?",
  ui_story_8_7_2_35_dialog_content = "Para permanecer consciente bajo las circunstancias, eres muy poderoso o muy lento.",
  ui_story_8_7_2_36_dialog_content = "¡Dime qué está pasando!",
  ui_story_8_7_2_37_dialog_content = "¿Puedes sacarlo, Señorita Vice?",
  ui_story_8_7_2_38_dialog_content = "Está casi debajo de la piel, pero como todavía podemos verlo, hagamos el trabajo, no es necesario un procedimiento delicado.",
  ui_story_8_7_2_39_dialog_content = "Espera, nunca te dije mi nombre.",
  ui_story_8_7_2_40_dialog_content = "Cierto, pero eso es irrelevante, especialmente ahora.",
  ui_story_8_7_2_41_dialog_content = "¿Sientes alguna hostilidad proveniente de mí?",
  ui_story_8_7_2_42_dialog_content = "...",
  ui_story_8_7_2_43_dialog_content = "Muy bien. Debería poder forzar la salida de esa cosa, sin problema.",
  ui_story_8_7_2_44_dialog_content = "¡Oye! ¿Alguien podría decirme qué está pasando?",
  ui_story_8_7_2_45_dialog_content = "¡Deja de retorcerte!",
  ui_story_8_7_2_46_dialog_content = "Eres todo tú, Vice.",
  ui_story_8_7_2_47_dialog_content = "Esto puede doler un poco, PlayerName.",
  ui_story_8_7_2_48_dialog_content = "¡Ay!",
  ui_story_8_7_2_50_dialog_content = "(¡Me duele tanto que ni siquiera puedo hablar! ¿Llamas a esto \"un poco\"?)",
  ui_story_8_7_2_51_dialog_content = "¡Vuelve, Vice! No te acerques demasiado...",
  ui_story_8_7_2_52_dialog_content = "Esta cosa es peligrosa sin duda, pero fascinante al mismo tiempo.",
  ui_story_8_7_2_53_option_content = "¿Qué diablos es?",
  ui_story_8_7_2_54_dialog_content = "Una semilla, según los Eclipsites.",
  ui_story_8_7_2_55_dialog_content = "Es conocido por muchos nombres, \"El origen del poder\", \"El beso de la madre\", \"La marca de la Ascensión,\" etc.",
  ui_story_8_7_2_56_dialog_content = "Independientemente de sus apodos, una cosa es segura, los Eclipsites lo usan para obtener poderes extraordinarios y únicos.",
  ui_story_8_7_2_57_dialog_content = "Más importante aún, puede corromper y convertir su huésped en Eclipsite.",
  ui_story_8_7_2_58_dialog_content = "Corromper... ¿Es eso también lo que le pasó a Gertzurde?",
  ui_story_8_7_2_59_dialog_content = "¿Y a Schummer?",
  ui_story_8_7_2_60_dialog_content = "No estoy seguro de quién hablas, pero si son seres de Luz que pueden aprovechar el poder de la Oscuridad...",
  ui_story_8_7_2_61_dialog_content = "La Semilla debe haber echado raíces en ellos.",
  ui_story_8_7_2_62_option_content = "Entonces, me curaste, ¿no?",
  ui_story_8_7_2_63_dialog_content = "En cierto modo, sí. Aunque si no fuera por tu tremenda fuerza de voluntad, te habrías convertido mucho antes de que yo llegara.",
  ui_story_8_7_2_64_dialog_content = "Además, la Semilla no es tanto una enfermedad como una conciencia.",
  ui_story_8_7_2_65_dialog_content = "¿Cómo te sientes ahora?",
  ui_story_8_7_2_66_dialog_content = "Deberías sentirte mucho mejor, ahora que...",
  ui_story_8_7_2_67_dialog_content = "No, todavía no me siento bien.",
  ui_story_8_7_2_68_dialog_content = "¿Qué?",
  ui_story_8_7_2_69_dialog_content = "Siento que me han quitado el aire y no puedo respirar. Siento apretado mi pecho, también mi garganta. Yo tampoco puedo ver bien.",
  ui_story_8_7_2_70_dialog_content = "Eso es normal.",
  ui_story_8_7_2_71_dialog_content = "El Darkflow en este lugar es opresivamente intenso. Es natural que un Celestita como tú experimente este tipo de reacción.",
  ui_story_8_7_2_72_dialog_content = "Anteriormente no te afectaba porque la Semilla te estaba convirtiendo lentamente en un Eclipsite. ¿Entiendes ahora?",
  ui_story_8_7_2_73_dialog_content = "Ya veo... *tos*",
  ui_story_8_7_2_74_dialog_content = "Esta cosa es demasiado peligrosa. ¡Tenemos que destruirla!",
  ui_story_8_7_2_75_dialog_content = "Alto, señorita Vice.",
  ui_story_8_7_2_76_dialog_content = "Esta Semilla es veneno para muchos, pero un tesoro para otros... Como yo.",
  ui_story_8_7_2_77_dialog_content = "¡¿...?!",
  ui_story_8_7_2_78_dialog_content = "Tenga la seguridad de que nunca lo usaría en otra criatura viviente. Solo tengo curiosidad sobre su naturaleza.",
  ui_story_8_7_2_79_dialog_content = "Como devotos buscadores de La Verdad, tenemos nuestro camino a seguir. Eso es todo.",
  ui_story_8_7_2_80_dialog_content = "Y no supondrá ningún peligro, siempre que esté en mi maleta.",
  ui_story_8_7_2_81_dialog_content = "Esa maleta... ¿Se está moviendo?",
  ui_story_8_7_2_82_dialog_content = "No te preocupes, esta maleta es especial. Los secretos de los Aurorians y Eclipsites algún día serán revelados.",
  ui_story_8_7_2_83_dialog_content = "Debemos seguir apoyándonos unos a otros en el largo camino hacia la Verdad.",
  ui_story_8_7_2_84_dialog_content = "Más acertijos. ¿No puedes decirnos qué vas a hacer con él?",
  ui_story_8_7_2_85_dialog_content = "Estoy seguro de que lo sabrás pronto. Hasta que nos volvamos a encontrar, PlayerName, Vice.",
  ui_story_8_7_2_86_dialog_content = "Que su escape proceda sin problemas. En todo caso...",
  ui_story_8_7_2_87_dialog_content = "Ya he previsto la heroicidad de tu fuga en un futuro no muy lejano.",
  ui_story_8_7_2_88_dialog_content = "Que la Verdad los bendiga.",
  ui_story_8_7_2_89_dialog_content = "¿Vice?",
  ui_story_8_7_2_90_dialog_content = "¡Kyuu! ¡Kyuu!",
  ui_story_8_7_2_91_dialog_content = "¡Señora! Lo siento, estaba atendiendo la lesión de PlayerName...",
  ui_story_8_7_2_92_dialog_content = "Bueno, parece que escuché tu conversación. ¿PlayerName, estás bien?",
  ui_story_8_7_2_F1_dialog_content = "PlayerName está bien ahora. ¿Y tú, señora?",
  ui_story_8_7_2_F2_dialog_content = "Yo también estoy bien. Estaba atrapado en una ilusión, pero ahora he vuelto a ser mi antiguo yo.",
  ui_story_8_7_2_93_dialog_content = "¡Kyuu!",
  ui_story_8_7_2_94_dialog_content = "Debes haber estado muy preocupado, Curie.",
  ui_story_8_7_2_95_dialog_content = "Perdóname, causé muchos problemas a todos.",
  ui_story_8_7_2_96_option_content = "No lo menciones.",
  ui_story_8_7_2_97_dialog_content = "Si no fuera por ti, señora, es posible que ni siquiera hubiéramos tenido la oportunidad de escapar.",
  ui_story_8_7_2_98_dialog_content = "¿Entonces elegiste volver y rescatarme?",
  ui_story_8_7_2_99_dialog_content = "Han pasado muchas cosas desde entonces. ¡Te lo contaré todo una vez que salgamos de este lugar!",
  ui_story_8_7_2_100_dialog_content = "¿Qué pasa con Forsakin y la chica psicópata?",
  ui_story_8_7_2_101_dialog_content = "¿Schummer? No están cerca, pero es solo cuestión de tiempo antes de que nos encuentren.",
  ui_story_8_7_2_102_dialog_content = "Schummer podría haber sentido toda la conmoción en este momento, ¡así que tenemos que irnos de inmediato!",
  ui_story_8_7_2_103_option_content = "Todo está bien ahora, señora.",
  ui_story_8_7_2_104_dialog_content = "Todo está bien ahora. Pudimos evitar que la Eclipsite plantara la Semilla en su cuerpo.",
  ui_story_8_7_2_105_dialog_content = "¿Semilla? ¿Te refieres a lo que hablabas antes?",
  ui_story_8_7_2_106_dialog_content = "Salgamos de aquí primero. Te contaré todos los detalles una vez que estemos a salvo.",
  ui_story_8_7_2_107_dialog_content = "Entiendo. Cuento contigo entonces.",
  ui_story_8_7_2_108_dialog_content = "Oh, ¿qué pasa con Forsakin? ¿Y esa chica increíblemente poderosa?",
  ui_story_8_7_2_109_dialog_content = "No están ni cerca, pero no podemos quedarnos satisfechos.",
  ui_story_8_7_2_110_dialog_content = "Schummer podría haber sentido toda la conmoción en este momento, ¡así que tenemos que irnos de inmediato!",
  ui_story_8_7_2_111_dialog_content = "Entonces, ¿nuestra opción es escapar, no enfrentar al enemigo?",
  ui_story_8_7_2_112_dialog_content = "Una vez que regresemos a la ciudad de Gannon, reportaré todo al Gran Mariscal y enfrentaré mi castigo por todo esto.",
  ui_story_8_7_2_113_dialog_content = "...",
  ui_story_8_7_2_114_dialog_content = "Perforarlos, hacerlos añicos y aplastarlos hasta convertirlos en polvo.",
  ui_story_8_7_2_115_dialog_content = "Esas reglas sin sentido, la moralidad, así como la ciudad vil y odiosa que tenemos ante nosotros, se convertirán en polvo.",
  ui_story_8_7_2_116_dialog_content = "Espera, PlayerName.",
  ui_story_8_7_2_117_dialog_content = "Dejemos que el último par de ojos Celestitas sean testigo de la visión infernal.",
  ui_story_8_7_2_118_dialog_content = "Deja que se impriman en tus patéticos genes inferiores.",
  ui_story_8_8_1_1_dialog_content = "¡Esto es Lumopolis! ¡No una banda errante de aventureros volando en un Colossus!",
  ui_story_8_8_1_2_dialog_content = "Cuando te caíste de la casa del árbol por intentar salvar a un gato, pensé que era el colmo de tu tontería.",
  ui_story_8_8_1_3_dialog_content = "Aunque salvaste a ese gato y tomaste la decisión correcta, ¿qué importaba?",
  ui_story_8_8_1_4_dialog_content = "¡Te hice una pregunta! ¡¿Valió la pena?!",
  ui_story_8_8_1_5_dialog_content = "...",
  ui_story_8_8_1_6_dialog_content = "Solo espero no malinterpretarlo.",
  ui_story_8_8_1_7_dialog_content = "Increíble, ese hombre nunca había hablado así antes.",
  ui_story_8_8_1_8_dialog_content = "Incluso si malinterpretaste sus palabras, Carleen, creo que ahora no hay vuelta atrás.",
  ui_story_8_8_1_9_dialog_content = "En fin, ya estamos aquí.",
  ui_story_8_8_1_10_dialog_content = "En sala de control de Damocles.",
  ui_story_8_8_1_11_dialog_content = "Exacto. Si alguien te atrapa, dile que te obligué a hacerlo.",
  ui_story_8_8_1_12_dialog_content = "¡A la gran Raphaela no le importa un asunto tan trivial!",
  ui_story_8_8_1_13_dialog_content = "Tus ojos brillan con increíble resolución a veces, Carleen, como ahora.",
  ui_story_8_8_1_14_dialog_content = "Siempre que me siento inseguro, solo debo echar un vistazo a tus ojos, ¡y sé que puedo seguirte sin arrepentirme!",
  ui_story_8_8_1_15_dialog_content = "Ya sea que una decisión sea correcta o incorrecta, lo importante es reunir el valor para tomar una decisión, ¿no es así?",
  ui_story_8_8_1_16_dialog_content = "...",
  ui_story_8_8_1_17_dialog_content = "Toda una declaración filosófica, dado que es completamente irracional.",
  ui_story_8_8_1_18_dialog_content = "...",
  ui_story_8_8_1_19_dialog_content = "¡Oye, Michele! ¡Llegaste justo a tiempo!",
  ui_story_8_8_1_20_dialog_content = "...",
  ui_story_8_8_1_21_dialog_content = "Gracias, Michele. Nunca podría esperar que todos los miembros de los Guardianes vinieran en mi ayuda, pero eres más que suficiente.",
  ui_story_8_8_1_22_dialog_content = "¡Michele es bastante confiable! Especialmente porque ella no hace un montón de preguntas extrañas, ¿verdad?",
  ui_story_8_8_1_23_dialog_content = "...",
  ui_story_8_8_1_24_dialog_content = "¿Cómo es la situación ahí fuera? ¿Siguen resistiendo los escudos?",
  ui_story_8_8_1_25_dialog_content = "...",
  ui_story_8_8_1_26_dialog_content = "Los escudos ahora están visiblemente debilitados, según el último informe.",
  ui_story_8_8_1_27_dialog_content = "No puedo creer que hayan logrado atravesar la poderosa barrera Lumina. Eso es muy impresionante.",
  ui_story_8_8_1_28_dialog_content = "Ella no es la misma Schummer que antes, y falle en detenerla en ese entonces.",
  ui_story_8_8_1_29_dialog_content = "¡Pero esta vez, sé que puedo!",
  ui_story_8_8_1_30_dialog_content = "¡Es correcto! ¡Haré mi mejor esfuerzo también!",
  ui_story_8_8_1_31_dialog_content = "¡Michele también está lista para partir!",
  ui_story_8_8_1_32_dialog_content = "...",
  ui_story_8_8_1_33_dialog_content = "Exacto. Tu tarea es muy simple, ustedes dos...",
  ui_story_8_8_1_34_dialog_content = "Ayúdame a hacer una barricada en la entrada de la sala de control. ¡No dejes entrar a nadie!",
  ui_story_8_8_1_35_dialog_content = "Una vez que active Damocles, canalizará toda la energía de Lumopolis hacia aquí.",
  ui_story_8_8_1_36_dialog_content = "Los escudos solo estarán abajo por un corto tiempo, pero lo suficiente como para asustar a las masas.",
  ui_story_8_8_1_37_dialog_content = "Raphaela, ¿puedes volver a llamar a los otros miembros de los Guardianes?",
  ui_story_8_8_1_38_dialog_content = "¡Diles que vayan a proteger las otras áreas de Lumopolis mientras Damocles carga!",
  ui_story_8_8_1_39_dialog_content = "¡Seguro, lo intentaré una vez más!",
  ui_story_8_8_1_40_dialog_content = "¡Solo concéntrate en hacer lo que crees que es correcto, Carleen!",
  ui_story_8_8_1_41_dialog_content = "Cuento contigo. Este lugar está ahora en tus manos.",
  ui_story_8_8_1_42_dialog_content = "...",
  ui_story_8_8_1_43_dialog_content = "Padre, esto podría ser lo más loco que he hecho en mi vida.",
  ui_story_8_8_1_44_dialog_content = "Pero realmente creo...",
  ui_story_8_8_1_45_dialog_content = "Proteger a las personas que me importan a mi manera...",
  ui_story_8_8_1_46_dialog_content = "¡Siempre es la elección correcta!",
  ui_story_8_8_1_47_dialog_content = "<color=#e8d9bb>Fuera de la sala de control</color>",
  ui_story_8_8_1_48_dialog_content = "Entró como se esperaba, Juez Principal.",
  ui_story_8_8_1_49_dialog_content = "...",
  ui_story_8_8_1_50_dialog_content = "¿Qué debemos hacer? Dada la situación...",
  ui_story_8_8_1_51_dialog_content = "Si Carleen no hizo nada más que entrar en la sala de control de Damocles, no rompió ninguna regla, ¿verdad?",
  ui_story_8_8_1_52_dialog_content = "Como Capitana de los Guardianes, tiene derecho a ir a cualquier parte.",
  ui_story_8_8_1_53_dialog_content = "Sin embargo, si activa a Damocles, sería completamente diferente.",
  ui_story_8_8_1_54_dialog_content = "¡Pero entonces sería demasiado tarde!",
  ui_story_8_8_1_55_dialog_content = "¿Demasiado tarde?",
  ui_story_8_8_1_56_dialog_content = "Lumopolis se basa en la ley y el orden. Para aquellos que violan sus leyes y actúan como les place...",
  ui_story_8_8_1_57_dialog_content = "Eso es muy tarde para ellos.",
  ui_story_8_8_1_58_dialog_content = "Entiendo. Estaremos a la espera de órdenes.",
  ui_story_8_8_1_59_dialog_content = "Prepárese para enviar un destacamento de tropas a otras áreas como refuerzo.",
  ui_story_8_8_1_60_dialog_content = "¿Refuerzos?",
  ui_story_8_8_1_61_dialog_content = "Si activa Damocles, las defensas de Lumopolis bajarán por un breve momento.",
  ui_story_8_8_1_62_dialog_content = "¿Será esta nuestra oportunidad de salvación o el momento en que bajemos al infierno?",
  ui_story_8_8_1_63_dialog_content = "Carleen de Schwartz...",
  ui_story_8_9_1_1_dialog_content = "¡Por aquí! Si recuerdo los caminos bien, nosotros...",
  ui_story_8_9_1_2_dialog_content = "Espera, Vice.",
  ui_story_8_9_1_3_dialog_content = "¿Qué tal?",
  ui_story_8_9_1_4_dialog_content = "Debemos detenernos un minuto.",
  ui_story_8_9_1_5_dialog_content = "¡No podemos parar, señora! ¡No podemos retrasarnos ni un segundo! ¡Aquí, déjame llevarte!",
  ui_story_8_9_1_6_dialog_content = "No, no me refiero a eso. ¿Dónde estamos exactamente en Aviduz?",
  ui_story_8_9_1_7_dialog_content = "Ah... Ya deberíamos estar cerca de la entrada.",
  ui_story_8_9_1_8_dialog_content = "¿Está peleando ahora mismo?",
  ui_story_8_9_1_9_dialog_content = "Me temo que Aviduz puede estar atacando los escudos de Lumopolis.",
  ui_story_8_9_1_10_dialog_content = "Es solo cuestión de tiempo antes que caigan los escudos...",
  ui_story_8_9_1_11_dialog_content = "¿Cómo planeas contrarrestar Lumopolis?",
  ui_story_8_9_1_12_dialog_content = "Carleen regresó y está luchando para activar Damocles.",
  ui_story_8_9_1_13_dialog_content = "Entonces, en realidad ha llegado a esto.",
  ui_story_8_9_1_14_dialog_content = "Sí. Aviduz se ha cargado a plena potencia.",
  ui_story_8_9_1_15_dialog_content = "...",
  ui_story_8_9_1_16_dialog_content = "¿Y Schummer? ¿Ella no nos ha notado todavía?",
  ui_story_8_9_1_17_dialog_content = "PlayerName ha estado usando habilidades psíquicas para limitar al Colossus.",
  ui_story_8_9_1_18_dialog_content = "Correcto, pero solo su capacidad para monitorear su interior. Dado que Schummer está conectada con él, ninguno de ellos es consciente de nuestra fuga.",
  ui_story_8_9_1_19_dialog_content = "Es difícil medir cuánta energía usar. Usarlo sin cuidado podría alertar a Schummer de que algo está mal.",
  ui_story_8_9_1_20_dialog_content = "Eso significa que las reglas han cambiado ahora.",
  ui_story_8_9_1_21_dialog_content = "Enemigos al aire libre, mientras estamos en la sombra.",
  ui_story_8_9_1_22_dialog_content = "Vivian, no te refieres a...",
  ui_story_8_9_1_23_dialog_content = "No nos vamos, Vice.",
  ui_story_8_9_1_24_dialog_content = "¿Qué?",
  ui_story_8_9_1_25_dialog_content = "¿Has olvidado los fundamentos de la guerra tan pronto? Somos los únicos que podemos...",
  ui_story_8_9_1_26_dialog_content = "¡Derrotar al enemigo desde dentro!",
  ui_story_8_9_1_27_dialog_content = "Pero señora, no estás en forma...",
  ui_story_8_9_1_28_dialog_content = "Este no es el momento de preocuparse por mí.",
  ui_story_8_9_1_29_dialog_content = "No podemos desperdiciar esta oportunidad. Si lo logramos, tal vez podamos salvar toda la ciudad.",
  ui_story_8_9_1_30_dialog_content = "...",
  ui_story_8_9_1_31_dialog_content = "Puedes sopesar las opciones tú mismo, ¿no?",
  ui_story_8_9_1_32_dialog_content = "Siempre eres una chica tranquila y decidida, Vice. Pero parece que últimamente has dudado.",
  ui_story_8_9_1_33_dialog_content = "Señora, no quiero dejar a nadie atrás. Después de todo, eres...",
  ui_story_8_9_1_34_dialog_content = "Déjame preguntarte, si estuvieras en mi posición, ¿nos dejarías desperdiciar una oportunidad de oro como esta?",
  ui_story_8_9_1_35_dialog_content = "Oh...",
  ui_story_8_9_1_36_dialog_content = "Además, gracias a PlayerName, mis heridas ahora se están curando.",
  ui_story_8_9_1_37_dialog_content = "Nuestro enemigo está ante nuestros ojos, Vice, ¿cómo podríamos dar media vuelta y huir ahora?",
  ui_story_8_9_2_1_dialog_content = "<color=#e8d9bb>Hace Varios Años en Lumopolis</color>",
  ui_story_8_9_2_2_dialog_content = "(\"Proteger a las personas que me importan a mi manera...\")",
  ui_story_8_9_2_3_dialog_content = "...",
  ui_story_8_9_2_4_dialog_content = "Pero...",
  ui_story_8_9_2_5_dialog_content = "Está muerto.",
  ui_story_8_9_2_6_dialog_content = "Todos los seres vivos morirán algún día, Carleen.",
  ui_story_8_9_2_7_dialog_content = "No pude salvarlo. Si tan solo tuviera un poco más de cuidado...",
  ui_story_8_9_2_8_dialog_content = "Saltó de la casa del árbol porque estaba asustado, Carleen. No fue culpa tuya.",
  ui_story_8_9_2_9_dialog_content = "Pero podría haberlo ayudado... ¡Sé que podría haberlo hecho!",
  ui_story_8_9_2_10_dialog_content = "Parece que no tiene sentido razonar con un niño que llora.",
  ui_story_8_9_2_11_dialog_content = "Si hay algo que aprender de esto, no es arrepentirse de algo que \"podría haber\" hecho, sino el hecho de que protegerse a sí mismo viene antes que salvar a los demás.",
  ui_story_8_9_2_F1_dialog_content = "¿Sabes cuántas personas tienes preocupadas por tu seguridad?",
  ui_story_8_9_2_12_dialog_content = "Ambos se cayeron de la casa del árbol y el gato murió, pero no sufrieron ni un solo rasguño por la caída.",
  ui_story_8_9_2_13_dialog_content = "¿Qué tipo de monstruos son los Schwartz?",
  ui_story_8_9_2_14_dialog_content = "En cualquier caso, sé buena chica y espera aquí. Ya le he informado a tu padre y haré que el médico te examine más tarde.",
  ui_story_8_9_2_15_dialog_content = "Sr. Otto.",
  ui_story_8_9_2_16_dialog_content = "¿Si?",
  ui_story_8_9_2_17_dialog_content = "¿Puedo preguntarle algo?",
  ui_story_8_9_2_18_dialog_content = "Adelante.",
  ui_story_8_9_2_19_dialog_content = "¿Estabas ahí cuando mi mamá falleció?",
  ui_story_8_9_2_20_dialog_content = "...",
  ui_story_8_9_2_21_dialog_content = "No, Carleen, no lo estaba. Nadie estaba, salvo tu padre.",
  ui_story_8_9_2_22_dialog_content = "...",
  ui_story_8_9_2_23_dialog_content = "No debí haber ido a Northland en ese momento. Debí quedarme a su lado y protegerla.",
  ui_story_8_9_2_24_dialog_content = "Si la hubiera protegido, tal vez ella no...",
  ui_story_8_9_2_25_dialog_content = "Aunque estuvieras a su lado, es posible que no puedas cambiar nada.",
  ui_story_8_9_2_26_dialog_content = "¿Qué?",
  ui_story_8_9_2_27_dialog_content = "Y esa es la verdad. Incluso Schwartz no pudo cambiar el resultado, ¿qué te hace pensar que podrías haberlo hecho?",
  ui_story_8_9_2_28_dialog_content = "¿Eso significa que sigo siendo un niña que no puede proteger a nadie?",
  ui_story_8_9_2_29_dialog_content = "¿Y qué si lo eres?",
  ui_story_8_9_2_30_dialog_content = "...",
  ui_story_8_9_2_31_dialog_content = "Era solo un gato, Carleen.",
  ui_story_8_9_2_32_dialog_content = "La próxima vez, no huyas por tu cuenta. Eres una dama de familia noble.",
  ui_story_8_9_2_33_dialog_content = "...",
  ui_story_8_9_2_34_dialog_content = "¡Carleen!",
  ui_story_8_9_2_35_dialog_content = "Adelante.",
  ui_story_8_9_2_36_dialog_content = "¡El Salón de Justicia nos tiene rodeados!",
  ui_story_8_9_2_37_dialog_content = "¿En serio? ¿Han hecho un movimiento todavía?",
  ui_story_8_9_2_38_dialog_content = "Todavía no, pero están observando todos nuestros movimientos. ¡Tengo un terrible presentimiento sobre esto!",
  ui_story_8_9_2_39_dialog_content = "El juez principal Irridon también está presente.",
  ui_story_8_9_2_40_dialog_content = "...",
  ui_story_8_9_2_41_dialog_content = "En espera, Raphaela y Michele.",
  ui_story_8_9_2_42_dialog_content = "¡Sí!",
  ui_story_8_9_2_43_dialog_content = "Vigilen esa puerta y quien la sala de control de Damocles, ¿entendido?",
  ui_story_8_9_2_44_dialog_content = "¡Entendido!",
  ui_story_8_9_2_45_dialog_content = "Damocles...",
  ui_story_8_9_2_46_dialog_content = "Por favor, conviértete en la hoja brillante y atraviesa la oscuridad que nos rodea.",
  ui_story_8_9_2_47_dialog_content = "¡Damocles, <color=#FFB400>activate</color>!",
  ui_story_8_10_1_1_dialog_content = "¿Qué está pasando?",
  ui_story_8_10_1_2_dialog_content = "¿Corte de energía?",
  ui_story_8_10_1_3_dialog_content = "La sala de control... ¡La sala de control de Damocles!",
  ui_story_8_10_1_4_dialog_content = "¡No se queden ahí, tontos! ¡Ve a ver qué pasó!",
  ui_story_8_10_1_5_dialog_content = "...",
  ui_story_8_10_1_6_dialog_content = "Schwartz, si esto fue obra de Carleen, ya conoces las consecuencias, ¡¿no?!",
  ui_story_8_10_1_7_dialog_content = "Ella no está actuando bajo mis instrucciones. Ella está en su sano juicio y actúa por su propia voluntad.",
  ui_story_8_10_1_8_dialog_content = "¡Pero no debes eludir tu responsabilidad!",
  ui_story_8_10_1_9_dialog_content = "¿Dónde está Irridon? Deja que el Salón de Justicia...",
  ui_story_8_10_1_10_dialog_content = "¡El Juez Principal está en la entrada de la sala de control!",
  ui_story_8_10_1_11_dialog_content = "¡Los jardines de Lumopolis están en un estado de caos! Los nobles están en pánico...",
  ui_story_8_10_1_12_dialog_content = "¡Impongan el orden público y digan a todos que guarden la calma! Incluso si Damocles ha sido activado, la energía de Lumopolis no lo hará de inmediato...",
  ui_story_8_10_1_14_dialog_content = "¡¿La ciudad está descendiendo?!",
  ui_story_8_10_1_15_dialog_content = "El poder de la ciudad está convergiendo dentro de Damocles, incluido el poder de nuestros sistemas de propulsión.",
  ui_story_8_10_1_16_dialog_content = "¡Yo sé! ¡Yo sé!",
  ui_story_8_10_1_17_dialog_content = "Ya he ordenado a los Guardianes que se mantengan al margen en todos los distritos de Lumopolis y se preparen para defender la ciudad, ¿o prefieres concederme la autoridad para movilizar al Consejo de Ancianos también?",
  ui_story_8_10_1_18_dialog_content = "¡Tú!",
  ui_story_8_10_1_19_dialog_content = "¡Señor Schwartz! ¡Señor Otto! Los escudos están...",
  ui_story_8_10_1_20_dialog_content = "<color=#e8d9bb>Mientras tanto, dentro de Aviduz</color>",
  ui_story_8_10_1_22_dialog_content = "¿Qué fue eso?",
  ui_story_8_10_1_23_dialog_content = "¿Aviduz acaba de moverse? ¿Qué está sucediendo?",
  ui_story_8_10_1_24_dialog_content = "¡Kyuu!",
  ui_story_8_10_1_25_dialog_content = "...",
  ui_story_8_10_1_26_dialog_content = "Los escudos de Lumopolis están cayendo.",
  ui_story_8_10_1_27_dialog_content = "¿Estás seguro? ¿Entonces Carleen logró activar Damocles?",
  ui_story_8_10_1_28_dialog_content = "También podría ser que Schummer rompiera los escudos. No estamos seguros de lo que está pasando realmente.",
  ui_story_8_10_1_29_dialog_content = "¡Creo que es Carleen!",
  ui_story_8_10_1_30_dialog_content = "Espera, ¿por qué se han ido los escudos?",
  ui_story_8_10_1_31_dialog_content = "Damocles necesita redirigir casi todo el poder en Lumopolis hacia sí mismo para recargarse, incluido el poder que mantiene los escudos.",
  ui_story_8_10_1_32_dialog_content = "Pero es solo por poco tiempo. Espera un poco.",
  ui_story_8_10_1_34_dialog_content = "Tenemos un problema, ¡Schummer nos ha notado!",
  ui_story_8_10_1_35_dialog_content = "Lo siento, no esperaba que comenzara a moverse de repente, así que no pude...",
  ui_story_8_10_1_36_dialog_content = "¡¡PlayerName!!",
  ui_story_8_10_1_37_dialog_content = "¡Schummer!",
  ui_story_8_10_1_38_dialog_content = "¿Cuándo saliste?",
  ui_story_8_10_1_39_dialog_content = "Contéstame primero. ¡¿Qué diablos has hecho?!",
  ui_story_8_10_1_40_dialog_content = "¿Por qué te niegas a aceptar tu destino? ¿¡Por qué insistes en luchar inútilmente contra él!?",
  ui_story_8_10_1_41_dialog_content = "Tú y los escudos de esta maldita ciudad son sin duda iguales. ¡Al final, te estrellarás y te rendirás a mí!",
  ui_story_8_10_1_42_dialog_content = "¿Crees que derribaste los escudos de Lumopolis? Eres...",
  ui_story_8_10_1_43_dialog_content = "(¡Espera, puede que aún no sepa sobre Damocles!)",
  ui_story_8_10_1_F1_dialog_content = "¡Ja! ¿Has sido testigo del poder de Aviduz?",
  ui_story_8_10_1_44_dialog_content = "¿No tienes curiosidad, PlayerName? ¿No quieres saber por qué te dejé vivir después de golpearte tantas veces?",
  ui_story_8_10_1_45_dialog_content = "...",
  ui_story_8_10_1_46_dialog_content = "Al principio fue por piedad, considerando lo débil que eras. Más tarde, fue por ira, incluso por odio.",
  ui_story_8_10_1_47_dialog_content = "Pero ya he tenido suficiente de todo. Al final, lo que quiero es demostrártelo a ti y a tu gente.",
  ui_story_8_10_1_48_dialog_content = "¡Ese verdadero poder no es lo que ustedes tontos siguen diciendo!",
  ui_story_8_10_1_49_dialog_content = "¡No tengo idea de lo que estás hablando!",
  ui_story_8_10_1_50_dialog_content = "Oh, pero lo harás.",
  ui_story_8_10_1_51_dialog_content = "Lo sabrás muy pronto.",
  ui_story_8_10_1_52_dialog_content = "¿Qué pasa, PlayerName? ¿Estás bien? ¡Despierta!",
  ui_story_8_10_1_53_dialog_content = "No te preocupes, estoy despierto. Estaba hablando con Schummer.",
  ui_story_8_10_1_54_dialog_content = "Nos encontró. ¡Debemos detenerla ahora!",
  ui_story_8_10_1_55_dialog_content = "Concurrido. ¡Date prisa, debemos movernos!",
  ui_story_8_10_1_56_dialog_content = "¡Kyuu!",
  ui_story_8_10_1_57_dialog_content = "Solo necesitamos crear una distracción y mantener a Schummer ocupada todo lo posible ¿no?",
  ui_story_8_10_1_58_dialog_content = "Espero que podamos ganar suficiente tiempo para Carleen.",
  ui_story_8_10_2_1_dialog_content = "¡Cuidado, señora!",
  ui_story_8_10_2_2_dialog_content = "Lo siento, mi cuerpo todavía está rígido, así que no te sirvo de mucho ahora.",
  ui_story_8_10_2_3_dialog_content = "Debería esperarnos aquí, señora. Cuanto más nos acerquemos al Puente, más Eclipsites nos encontraremos.",
  ui_story_8_10_2_4_dialog_content = "No me subestimes, Vice. ¿Cómo podría dejarte luchando por tu cuenta?",
  ui_story_8_10_2_5_dialog_content = "¡Agárrate fuerte!",
  ui_story_8_10_2_6_dialog_content = "¡Está enfocado en atacar Lumopolis ahora mismo! No sabemos de la situación exterior.",
  ui_story_8_10_2_7_dialog_content = "Envía... Equipo 3... a...",
  ui_story_8_10_2_8_dialog_content = "¡Reagrupar! No... apuntes a las grieta ... capa exterior...",
  ui_story_8_10_2_9_dialog_content = "¡Es la comunicación de los Guardianes!",
  ui_story_8_10_2_10_dialog_content = "Pero Aviduz puede bloquear nuestras comunicaciones. Cómo...",
  ui_story_8_10_2_11_dialog_content = "¿Quizás las señales de corto alcance son lo suficientemente fuertes para pasar? A juzgar por el mensaje, ahora están afuera.",
  ui_story_8_10_2_12_dialog_content = "¿Están afuera? ¿Se están enfrentando a Aviduz?",
  ui_story_8_10_2_13_dialog_content = "Es correcto. Lo más probable es que hayan reunido una fuerza masiva y estén tomando la iniciativa.",
  ui_story_8_10_2_14_dialog_content = "¡A la carga! Somos la última esperanza de Lempo...",
  ui_story_8_10_2_15_dialog_content = "Sígueme... ¡No les des tregua! No dejes...",
  ui_story_8_10_2_16_dialog_content = "¡El dirigible está fuera de control! Estamos cayendo del cielo... ¡No! ¡Me llevaré esta basura si es lo último que hago!",
  ui_story_8_10_2_17_dialog_content = "<color=#e8d9bb>¡¡¡Boom!!!</color>",
  ui_story_8_10_2_18_dialog_content = "...",
  ui_story_8_10_2_19_dialog_content = "¿Fue un ataque suicida?",
  ui_story_8_10_2_20_dialog_content = "Oh...",
  ui_story_8_10_2_21_dialog_content = "Señora, tus heridas...",
  ui_story_8_10_2_22_dialog_content = "Vamos, no hay tiempo que perder.",
  ui_story_8_10_2_23_dialog_content = "No dejes que se repita la tragedia de hace diecisiete años. Necesitamos detener estos Eclipsites.",
  ui_story_8_10_2_24_dialog_content = "Está bien...",
  ui_story_8_10_2_25_dialog_content = "Nos estamos acercando al Puente. ¿Estás seguro de que Schummer está ahí, PlayerName?",
  ui_story_8_10_2_26_dialog_content = "Positivo. ¡Terminemos esto de una vez por todas!",
  ui_story_8_10_2_27_dialog_content = "No hay un solo Eclipsite que pueda detenernos ahora.",
  ui_story_8_13_2_1_dialog_content = "Profesor, volví a fallar.",
  ui_story_8_13_2_2_dialog_content = "Está bien, inténtalo de nuevo.",
  ui_story_8_13_2_3_dialog_content = "Pero yo...",
  ui_story_8_13_2_4_dialog_content = "Nadie nace con poder, niña. Solo creciendo a través del entrenamiento y levantándose después de cada derrota...",
  ui_story_8_13_2_5_dialog_content = "Puedes volverte verdaderamente fuerte.",
  ui_story_8_13_2_6_dialog_content = "Pero...",
  ui_story_8_13_2_7_dialog_content = "¡Schummer!",
  ui_story_8_13_2_8_dialog_content = "Has venido. Eso es todo por hoy, Schummer, ve a jugar con tus amigos.",
  ui_story_8_13_2_9_dialog_content = "¡Es correcto! ¡No hagas esperar a tus amigos!",
  ui_story_8_13_2_10_dialog_content = "¡Hahaha!",
  ui_story_8_13_2_11_dialog_content = "...",
  ui_story_8_13_2_12_dialog_content = "¿Qué tal?",
  ui_story_8_13_2_13_dialog_content = "Yo...",
  ui_story_8_13_2_14_dialog_content = "...",
  ui_story_8_13_2_15_dialog_content = "Los maté a todos.",
  ui_story_8_13_2_16_dialog_content = "Los estrangulé con mis propias manos. El sonido de sus huesos aplastados fue como una canción para mí.",
  ui_story_8_13_2_17_dialog_content = "Una canción de puro y absoluto poder.",
  ui_story_8_13_2_18_dialog_content = "¿Cuál es la situación, Schummer?",
  ui_story_8_13_2_19_dialog_content = "No me interrumpas. Se han roto las defensas de Lumopolis y los Aurorians están haciendo su última resistencia.",
  ui_story_8_13_2_20_dialog_content = "Te dije que podía manejar esto, ¿no?",
  ui_story_8_13_2_22_dialog_content = "¡Tuve éxito donde todos ustedes fallaron! Ja...",
  ui_story_8_13_2_23_dialog_content = "¡Hahaha!",
  ui_story_8_13_2_24_dialog_content = "...",
  ui_story_8_13_2_25_dialog_content = "Ahora, ¿te importaría salirte de mi camino?",
  ui_story_8_13_2_26_dialog_content = "El Celestita casi está aquí.",
  ui_story_8_13_2_27_dialog_content = "Tiempo perfecto. La masacre de hoy comenzará pronto. ¡Ven, cariño!",
  ui_story_8_13_2_28_dialog_content = "¿No vas a matar al Celestita?",
  ui_story_8_13_2_29_dialog_content = "¿Por qué iba a matar a mi \"compañero\"?",
  ui_story_8_13_2_30_dialog_content = "Pero no dijiste antes...",
  ui_story_8_13_2_31_dialog_content = "¡Cállate ya! Siempre es algo contigo. ¡¿Por qué no me dejas en paz?!",
  ui_story_8_13_2_32_dialog_content = "¡Únete a mí, PlayerName, perteneces a mi lado!",
  ui_story_8_13_2_33_dialog_content = "Espera hasta que veas en lo que me he convertido. Solo abre los ojos...",
  ui_story_8_14_1_1_dialog_content = "...",
  ui_story_8_14_1_3_dialog_content = "¡La caballería está aquí, Michele!",
  ui_story_8_14_1_4_dialog_content = "¿...?",
  ui_story_8_14_1_5_dialog_content = "¿Carleen? ¡Ella está bien! ¡Tiene a otros vigilando la puerta!",
  ui_story_8_14_1_6_dialog_content = "<color=#e8d9bb>Fuera de la sala de control de Damocles</color>",
  ui_story_8_14_1_7_dialog_content = "¡Hazte a un lado! ¡Todos ustedes, fuera de mi camino!",
  ui_story_8_14_1_8_dialog_content = "¿Qué diablos crees que estás haciendo, Irridon? ¿Por qué no has derribado la puerta?",
  ui_story_8_14_1_9_dialog_content = "Como puedes ver.",
  ui_story_8_14_1_10_dialog_content = "Ten paciencia, Señor Otto.",
  ui_story_8_14_1_11_dialog_content = "¡Atrás! ¡En nombre del Consejo de Ancianos, les ordeno a todos que se aparten!",
  ui_story_8_14_1_F1_dialog_content = "¿¡Quién te dijo que vigilaras la sala de control!? ¡Fuera de mi camino!",
  ui_story_8_14_1_12_dialog_content = "¿Y a dónde diablos se ha ido Schwartz, en un momento como este? ¡¿Se preocupa tan poco por su propia hija?!",
  ui_story_8_14_1_13_dialog_content = "Señor Otto, por favor cálmate y escucha...",
  ui_story_8_14_1_14_dialog_content = "Mira por encima de nosotros, el cielo está lleno de Eclipsites. ¿No crees que el Salón de Justicia y el Consejo de Ancianos deberían hacer algo al respecto?",
  ui_story_8_14_1_15_dialog_content = "Gabriela...",
  ui_story_8_14_1_16_dialog_content = "¿Puedo ir a quemar los Eclipsites hasta las cenizas?",
  ui_story_8_14_1_17_dialog_content = "¡Seguro! No quemes las casas de los nobles, ¿de acuerdo?",
  ui_story_8_14_1_18_dialog_content = "Sí, pero eso me va a costar mucho...",
  ui_story_8_14_1_19_dialog_content = "...",
  ui_story_8_14_1_20_dialog_content = "¿Estás seguro de que quieres interponerte en mi camino, Gabriela?",
  ui_story_8_14_1_21_dialog_content = "¡Sí, positivo!",
  ui_story_8_14_1_22_dialog_content = "Aunque \"pararse\" no es realmente la palabra correcta. ¡Yo diría que estoy \"sentado\" en tu camino!",
  ui_story_8_14_1_23_dialog_content = "¡Soldados del Salón de Justicia, avancen!",
  ui_story_8_14_1_24_dialog_content = "<size=45>¿Por qué no lo pruebas?</size>",
  ui_story_8_14_1_25_dialog_content = "¡El edificio se derrumba! Retrocedan a...",
  ui_story_8_14_1_26_dialog_content = "¡¡!!",
  ui_story_8_14_1_27_dialog_content = "¡Hay demasiados de ellos! ¡¡Perderemos todo si seguimos así!!",
  ui_story_8_14_1_28_dialog_content = "¡...!",
  ui_story_8_14_1_29_dialog_content = "¡Entendido! ¡Retrocedan al espacio estrecho y asuman posiciones defensivas!",
  ui_story_8_14_1_30_dialog_content = "¡No podemos dejar que los Eclipsites nos pasen!",
  ui_story_8_14_1_31_dialog_content = "*Rugidos*",
  ui_story_8_14_1_33_dialog_content = "<color=#e8d9bb>Sala de control Damocles</color>",
  ui_story_8_14_1_34_dialog_content = "...",
  ui_story_8_14_1_35_dialog_content = "(Raphaela, Michele, Gabriela y los demás, ¿están peleando en este momento?)",
  ui_story_8_14_1_36_dialog_content = "Por favor, date prisa, Damocles...",
  ui_story_8_14_1_37_dialog_content = "¡La gente de Lumopolis y esta ciudad necesitan que despiertes!",
  ui_story_8_14_1_38_dialog_content = "Todavía es muy lento. Tengo que acelerar el proceso de carga, ¡incluso si me puede costar cada gramo de mi poder!",
  ui_story_8_14_1_39_dialog_content = "<color=#e8d9bb>El puente Aviduz</color>",
  ui_story_8_14_1_40_dialog_content = "Torretas.",
  ui_story_8_14_1_41_dialog_content = "Paredes de la cuidad.",
  ui_story_8_14_1_42_dialog_content = "Y esas miserables moscas que llamas \"dirigibles.\"",
  ui_story_8_14_1_43_dialog_content = "Los engranajes de guerra están en movimiento. Ustedes, tontos, no pudieron detenerme en mil vidas.",
  ui_story_8_14_1_44_dialog_content = "¡Nadie puede detenerme ahora!",
  ui_story_8_14_1_45_dialog_content = "Schummer.",
  ui_story_8_14_1_46_dialog_content = "PlayerName.",
  ui_story_8_14_1_47_dialog_content = "¿Estás nervioso? El espectáculo acaba de comenzar y ya estás sin aliento.",
  ui_story_8_14_1_48_dialog_content = "Ven, toma asiento.",
  ui_story_8_14_1_49_dialog_content = "¡Tienes que detener esto! Esto no puede continuar.",
  ui_story_8_14_1_50_dialog_content = "¡Está ocupada controlando Aviduz ahora mismo, PlayerName! Ahora es nuestra oportunidad.",
  ui_story_8_14_1_51_dialog_content = "¡A tu izquierda, Vice!",
  ui_story_8_14_1_52_dialog_content = "*Rugidos*",
  ui_story_8_14_1_53_dialog_content = "¡Una Eclipsite de alto nivel!",
  ui_story_8_14_1_54_dialog_content = "Se siente diferente esta vez. Parece que ese Eclipsite va a oponer resistencia.",
  ui_story_8_14_1_55_dialog_content = "Déjalos venir, tonto. No estropees mi diversión.",
  ui_story_8_14_1_56_dialog_content = "No fue fácil montar este espectáculo. Sería un desperdicio si no hubiera nadie que lo viera.",
  ui_story_8_14_1_57_dialog_content = "Una y otra vez, has ido en contra de las órdenes de Señorita Forsakin, Schummer. Incluso en un momento así, te mantienes firme en tu obstinación.",
  ui_story_8_14_1_58_dialog_content = "No tengo derecho a detener tu espantosa actitud. Pero tampoco tienes derecho a mandarme.",
  ui_story_8_14_1_59_dialog_content = "Al igual que nuestros maestros, nos dedicamos a nuestro trabajo y a la Madre, ¡no a deseos egoístas!",
  ui_story_8_14_1_60_dialog_content = "Madre esto, madre aquello... Qué aburrido.",
  ui_story_8_14_1_61_dialog_content = "Como puedes ver, PlayerName, estoy muy ocupada ahora.",
  ui_story_8_14_1_62_dialog_content = "Pero pase lo que pase, necesito que seas testigo de la completa destrucción de Lumopolis. Es por eso...",
  ui_story_8_14_1_63_dialog_content = "Tengo que pedirte mi primer favor. Mata a este Eclipsite y ponte a mi lado.",
  ui_story_8_14_1_64_dialog_content = "¿Tú...?",
  ui_story_8_14_1_65_dialog_content = "¿Qué está tramando esta vez? ¡En guardia, PlayerName!",
  ui_story_8_14_1_66_dialog_content = "Exacto. De igual manera, tiene razón. ¡Tenemos que encargarnos de ese Eclipsite antes que nada!",
  ui_story_8_14_1_67_dialog_content = "Es un honor conocerte finalmente, Celestita. Tú también, Aurorian.",
  ui_story_8_14_1_68_dialog_content = "Ambos han sido una espina a nuestro lado por mucho tiempo. Es momento de cumplir la voluntad de la Madre y la voluntad de Eclipse. Ahora...",
  ui_story_8_14_1_69_dialog_content = "Ven.",
  ui_story_8_14_1_70_dialog_content = "No me decepciones, PlayerName.",
  ui_story_8_14_2_1_dialog_content = "Imposible... ¡No hay forma!",
  ui_story_8_14_2_2_dialog_content = "Madre, Señorita Forsakin, ¡denme una oportunidad más! Concédeme el poder de...",
  ui_story_8_14_2_3_dialog_content = "Suficiente.",
  ui_story_8_14_2_4_dialog_content = "¡Uh!",
  ui_story_8_14_2_5_dialog_content = "¡Schummer, traidora!",
  ui_story_8_14_2_6_dialog_content = "¿Traidora? Por favor. Nunca le prometí lealtad a nadie.",
  ui_story_8_14_2_7_dialog_content = "Se acabó, Schummer.",
  ui_story_8_14_2_8_dialog_content = "¿Acabó? ¡Recién estamos comenzando!",
  ui_story_8_14_2_9_dialog_content = "¡Conéctate, Aviduz!",
  ui_story_8_14_2_10_dialog_content = "¡PlayerName!",
  ui_story_8_14_2_11_dialog_content = "¿Qué estás haciendo?",
  ui_story_8_14_2_12_dialog_content = "¡Deteniéndote a ti y a este Colossus!",
  ui_story_8_14_2_13_dialog_content = "Aviduz soy yo y yo soy Aviduz. ¡No puedes controlarlo!",
  ui_story_8_14_2_14_dialog_content = "¿No puedo? Todo lo que quiero es evitar que te acerques más a Lumopolis.",
  ui_story_8_14_2_15_dialog_content = "Ese es el hogar de los Aurorians...",
  ui_story_8_14_2_16_dialog_content = "Y mis amigos... ¡¡También es su hogar!!",
  ui_story_8_14_2_18_dialog_content = "Así que, si esto es lo que se necesita... Ugh... ¡Ay!",
  ui_story_8_14_2_19_dialog_content = "¡Te sangra la nariz, PlayerName!",
  ui_story_8_14_2_20_dialog_content = "¡Quédate atrás! ¡¡Ve... derriba a Schummer!!",
  ui_story_8_14_2_21_dialog_content = "Te dije, no puedes controlarlo.",
  ui_story_8_14_2_22_dialog_content = "¡¡Cuidado, Vice!!",
  ui_story_8_14_2_23_dialog_content = "(¡Vuelve a conectarte con Aviduz!)",
  ui_story_8_14_2_24_dialog_content = "Aún no sabes cuándo rendirte, ¿verdad? ¿PlayerName?",
  ui_story_8_14_2_25_dialog_content = "¡Nunca! No me rendiré, ¡ni siquiera si me matas!",
  ui_story_8_14_2_26_dialog_content = "¡No tienes posibilidad de ganar ahora, Schummer!",
  ui_story_8_14_2_27_dialog_content = "¿Sabes siquiera de lo qué hablas? ¡¡Abre los ojos y mira bien!!",
  ui_story_8_14_2_28_dialog_content = "¡Lumopolis está condenada! Sus defensas, sus soldados... ¡todos condenados!",
  ui_story_8_14_2_29_dialog_content = "¡Lo hice, PlayerName! ¡Hice lo que nadie más pudo hacer!",
  ui_story_8_14_2_30_dialog_content = "¿¡Por qué no lo aceptas!? Deberías estar arrastrándote ante mi poder absoluto, así que, ¿¡por qué sigues luchando!?",
  ui_story_8_14_2_31_dialog_content = "Aviduz, apaga... generadores...",
  ui_story_8_14_2_32_dialog_content = "¡El Colossus es mío!",
  ui_story_8_14_2_33_dialog_content = "¡¡¡Aaaarrrgh!!!",
  ui_story_8_14_2_35_dialog_content = "Oh, mi cabeza da vueltas... Yo...",
  ui_story_8_14_2_36_dialog_content = "PlayerName...",
  ui_story_8_14_2_37_dialog_content = "Lo siento, no pudimos superar las defensas de Schummer.",
  ui_story_8_14_2_38_dialog_content = "Ahora, ¿ves la diferencia en nuestro poder? Tú y tus compañeros de alimañas... ¡¿Cómo pudiste superarme?!",
  ui_story_8_14_2_39_dialog_content = "Mantén los ojos abiertos, PlayerName. No quiero seguir torturándote, especialmente ahora mismo...",
  ui_story_8_14_2_40_dialog_content = "Necesito que veas esto. Ser testigo de esto, como Celestita...",
  ui_story_8_14_2_41_dialog_content = "¿Qué?",
  ui_story_8_14_2_42_dialog_content = "¿...?",
  ui_story_8_14_2_43_dialog_content = "(¿Por qué todo en silencio?)",
  ui_story_8_14_2_44_dialog_content = "...",
  ui_story_8_14_2_45_dialog_content = "Miserables, ¿qué han hecho esta vez?",
  ui_story_8_14_2_46_dialog_content = "(Schummer no sabe lo que está pasando, ¿entonces ella no hizo esto?)",
  ui_story_8_14_2_47_dialog_content = "¿Qué?",
  ui_story_8_14_2_48_dialog_content = "¿Por qué siento que todos los pelos de mi cuerpo se erizan?",
  ui_story_8_14_2_49_dialog_content = "Algo se siente diferente en el aire, Vice.",
  ui_story_8_14_2_50_dialog_content = "¿Y por qué todo en silencio de repente?",
  ui_story_8_14_2_51_dialog_content = "Tienes razón, está muy silencioso. No escucho ningún otro sonido.",
  ui_story_8_14_2_52_dialog_content = "¡Mira al suelo, Vice!",
  ui_story_8_14_2_53_dialog_content = "La tierra, se está moviendo, y en cierta dirección, parece...",
  ui_story_8_14_2_54_dialog_content = "Quizás sea el viento. ¿Puedes sentirlo? El aire que nos rodea se acumula, como...",
  ui_story_8_14_2_55_dialog_content = "¿Cómo si algo se estuviera formando?",
  ui_story_8_14_2_56_dialog_content = "¡Esto no augura nada bueno!",
  ui_story_8_14_2_58_dialog_content = "Señora, PlayerName, agáchate y agárrate de algo.",
  ui_story_8_14_2_59_dialog_content = "Si estoy en lo cierto, finalmente ha llegado el momento.",
  ui_story_8_14_2_62_dialog_content = "Hay algo por encima de Lumopolis. ¿Qué es eso?",
  ui_story_8_14_2_63_dialog_content = "¿De dónde viene esa luz?",
  ui_story_8_14_2_64_dialog_content = "...",
  ui_story_8_14_2_65_dialog_content = "Noche Blanca en lo alto... Mi juramento está completo.",
  ui_story_8_14_2_66_dialog_content = "Schummer, traidora de los Celestitas, yo, Carleen de Schwartz, seré quien libere...",
  ui_story_8_14_2_67_dialog_content = "¡¡¡Tu juicio final!!!",
  ui_story_8_14_2_68_dialog_content = "¿Es eso...?",
  ui_story_8_14_2_69_dialog_content = "¡¡Abajo, todos!!",
  ui_story_8_14_2_70_dialog_content = "<color=#e8d9bb>¡¡¡Boom!!!</color>",
  ui_story_8_14_2_73_dialog_content = "(¿Qué, un cañón Lumina...? ¡Mis ojos!)",
  ui_story_8_14_2_74_dialog_content = "(¿Por qué no puedo moverme? ¿¡Por qué no puedo mover mi cuerpo!?)",
  ui_story_8_14_2_75_dialog_content = "(Schummer...)",
  ui_story_8_14_2_76_dialog_content = "(¡Tú!)",
  ui_story_8_14_2_77_dialog_content = "(Te dije que te detendría, incluso si me mataba...)",
  ui_story_8_14_2_78_dialog_content = "(¡¿Crees que puedes detenerme así?!)",
  ui_story_8_14_2_82_dialog_content = "¡Schummer!",
  ui_story_8_14_2_83_dialog_content = "¡¡Ni siquiera pienses en dar una última pelea!!",
  ui_story_8_14_2_F1_dialog_content = "¡El rayo de Damocles te atravesará a ti y a Aviduz!",
  ui_story_8_14_2_84_dialog_content = "(¡Carleen!)",
  ui_story_8_14_2_87_dialog_content = "¡Esquiva, Aviduz! ¡Muévete!",
  ui_story_8_14_2_88_dialog_content = "No te dejaré... escapar... ¡Ugh...!",
  ui_story_8_14_2_89_dialog_content = "¡Evade el blaster! ¿Por qué no te mueves?",
  ui_story_8_14_2_90_dialog_content = "(¡Tengo que... dar todo lo que tengo! ¡¡No puedo dejar que el Colossus escape!!)",
  ui_story_8_14_2_91_dialog_content = "¡Suelta mi Colossus, PlayerName! ¡Rompe tu vínculo mental con Aviduz!",
  ui_story_8_14_2_92_dialog_content = "(No... El rayo... ¿falló?)",
  ui_story_8_14_2_93_dialog_content = "¡Tu Lumina es demasiado débil, Carleen! ¡Ya no puedes apuntar los rayos! ¡Apártate!",
  ui_story_8_14_2_94_dialog_content = "¡¿?!",
  ui_story_8_14_2_95_dialog_content = "¿Mi señor? ¿Pero por qué?",
  ui_story_8_14_2_96_dialog_content = "¡Solo ayudándote a guiar el ataque de Damocles, nada más!",
  ui_story_8_14_2_97_dialog_content = "No mires hacia atrás. Tu objetivo está frente a ti, ¿no?",
  ui_story_8_14_2_98_dialog_content = "¿Recuerdas l que no debes hacer antes de derrotar a un enemigo?",
  ui_story_8_14_2_99_dialog_content = "¡Por supuesto que sí, padre!",
  ui_story_8_14_2_100_dialog_content = "\"¡Nunca aflojes tu agarre hasta que tu lanza atraviese el pecho del enemigo!\"",
  ui_story_8_14_2_101_dialog_content = "(¡Voy a morir! A este paso, estoy...)",
  ui_story_8_14_2_102_dialog_content = "(¡Para! ¡Fuera, PlayerName!)",
  ui_story_8_14_2_103_dialog_content = "¡Schummer!",
  ui_story_8_14_2_104_dialog_content = "¡¡¡Mírame a los ojos antes de morir!!!",
  ui_story_8_14_2_105_dialog_content = "No, no...",
  ui_story_8_14_2_106_dialog_content = "¡Nooooo!",
  ui_story_8_14_2_112_dialog_content = "Schummer.",
  ui_story_8_14_2_113_dialog_content = "Estoy aquí, profesor.",
  ui_story_8_14_2_114_dialog_content = "¿Por qué lo hiciste?",
  ui_story_8_14_2_115_dialog_content = "...",
  ui_story_8_14_2_116_dialog_content = "Por qué...",
  ui_story_8_14_2_117_dialog_content = "¿Por qué matarnos a todos?",
  ui_story_8_14_2_118_dialog_content = "Con mi último aliento, te maldigo, Schummer, traidora de los Celestitas y mi mayor fracaso.",
  ui_story_8_14_2_119_dialog_content = "Te maldigo a una muerte cien veces más agonizante que la nuestra, Schummer.",
  ui_story_8_14_2_120_dialog_content = "Te maldigo, por todos tus días.",
  ui_story_8_14_2_121_dialog_content = "Nunca conocerás la paz.",
  ui_story_8_15_1_1_dialog_content = "Llegas muy tarde, Forsakin.",
  ui_story_8_15_1_2_dialog_content = "Este lugar está tan lejos. ¿Es necesario esconderse aquí?",
  ui_story_8_15_1_3_dialog_content = "¿Lo trajiste?",
  ui_story_8_15_1_4_dialog_content = "Schummer lo tiene. Debería terminar pronto, así que no me apresures.",
  ui_story_8_15_1_5_dialog_content = "¿Por qué complacer a Schummer con el ataque a Lumopolis? Tu tarea fue bastante simple, solo deja que esa cosa en su cuerpo...",
  ui_story_8_15_1_6_dialog_content = "Era muy inmadura para comprender.",
  ui_story_8_15_1_7_dialog_content = "¿Importa?",
  ui_story_8_15_1_8_dialog_content = "...",
  ui_story_8_15_1_9_dialog_content = "No olvides tu deber, Aurorian.",
  ui_story_8_15_1_10_dialog_content = "*Bostezos*",
  ui_story_8_15_1_11_dialog_content = "Eso es todo para el informe de muertes de Baja Lumopolis. Y aquí están los castigos propuestos para la Capitana de los Guardianes...",
  ui_story_8_15_1_12_dialog_content = "Muy bien, eso servirá por ahora.",
  ui_story_8_15_1_13_dialog_content = "Ve afuera por ahora. Puedes regresar y continuar en cinco minutos.",
  ui_story_8_15_1_14_dialog_content = "¡Sí!",
  ui_story_8_15_1_15_dialog_content = "Adelante.",
  ui_story_8_15_1_16_dialog_content = "Cuánto tiempo sin verte, Schwartz.",
  ui_story_8_15_1_17_dialog_content = "¿Estás aquí para consolarme?",
  ui_story_8_15_1_18_dialog_content = "¿Y lo creerás si lo estoy?",
  ui_story_8_15_1_19_dialog_content = "Estás de muy buen humor para alguien que ha mostrado todas las cartas.",
  ui_story_8_15_1_20_dialog_content = "No seas presuntuoso. Hasta ahora solo he jugado una carta.",
  ui_story_8_15_1_21_dialog_content = "Además, ya no estamos solos en nuestro juego. Hay otros defendiendo esta ciudad ahora.",
  ui_story_8_15_1_22_dialog_content = "No tengo ningún interés en enseñarle a jugar a tu hija, Schwartz.",
  ui_story_8_15_1_23_dialog_content = "A decir verdad, no participé en el juego de hoy. No te importa, ¿verdad?",
  ui_story_8_15_1_24_dialog_content = "No. Es porque creo en el poder de Lumopolis. Oh gran Señor de la Ciudad Invencible.",
  ui_story_8_15_1_25_dialog_content = "También he tenido desarrollos interesantes de mi parte, y no puedo esperar para compartirlos contigo.",
  ui_story_8_15_1_26_dialog_content = "Muy bien. Veremos de qué es capaz la Federación Illumina.",
  ui_story_8_15_1_27_dialog_content = "La llama parpadeante, ¿finalmente abrirá un camino a través de la oscuridad?",
  ui_story_8_15_1_28_dialog_content = "¡Esplendor Illumina!",
  ui_story_9_1_1_1_dialog_content = "Ambos pueden entrar ahora.",
  ui_story_9_1_1_2_dialog_content = "Gracias. Vamos, PlayerName.",
  ui_story_9_1_1_3_dialog_content = "<color=#e8d9bb>Crujido—</color>",
  ui_story_9_1_1_4_dialog_content = "Vice, todavía no lo sé ...",
  ui_story_9_1_1_5_option_content = "¿Dónde estamos?",
  ui_story_9_1_1_6_dialog_content = "Estamos en el Salón de la Justicia de los Jardines de Lumopolis.",
  ui_story_9_1_1_7_dialog_content = "La dama en el escenario con el personal debe ser la juez principal <color=#FFB400> Irridon </color>.",
  ui_story_9_1_1_8_option_content = "¿Quiénes son estos personas?",
  ui_story_9_1_1_9_dialog_content = "Si estoy en lo cierto ...",
  ui_story_9_1_1_10_dialog_content = "La del escenario con el personal es el juez principal <color=#FFB400> Irridon </color>, quien dirige este Salón de Justicia.",
  ui_story_9_1_1_11_dialog_content = "Y el hombre estoico a su lado...",
  ui_story_9_1_1_12_dialog_content = "Oh, lo recuerdo, es el padre de Carleen, ¿verdad?",
  ui_story_9_1_1_13_dialog_content = "Sí, ese es el Señor de Lumopolis, <color=#FFB400> Daniel de Schwartz </color>.",
  ui_story_9_1_1_14_dialog_content = "Estoy temblando por alguna razón ...",
  ui_story_9_1_1_15_dialog_content = "Shhh...",
  ui_story_9_1_1_16_dialog_content = "...",
  ui_story_9_1_1_17_dialog_content = "¿Ustedes son los compañeros de la Capitán Carleen, supongo?",
  ui_story_9_1_1_18_dialog_content = "Uh, sí. ¿Cómo está, mi señor?",
  ui_story_9_1_1_19_dialog_content = "Soy Vice, de la Federación Illumina. Este es PlayerName.",
  ui_story_9_1_1_20_dialog_content = "¿Cómo estás? Soy PlayerName.",
  ui_story_9_1_1_21_dialog_content = "Un placer conocerte.",
  ui_story_9_1_1_22_dialog_content = "Tengo entendido que retrasó el asalto del enemigo y luchó valientemente para ser una parte clave en la defensa de la ciudad.",
  ui_story_9_1_1_23_dialog_content = "Les expresaré mi gratitud a ambos.",
  ui_story_9_1_1_24_dialog_content = "Es nuestro honor, señor. Solo hicimos lo que se suponía que debíamos hacer.",
  ui_story_9_1_1_25_dialog_content = "¿Cómo te recuperas de tus heridas?",
  ui_story_9_1_1_26_dialog_content = "Gracias a los médicos que nos envió, ahora nos sentimos mucho mejor.",
  ui_story_9_1_1_27_dialog_content = "Bien. Lumopolis nunca olvidará el hecho de que la Federación Illumina envió ayuda para aliviar la crisis.",
  ui_story_9_1_1_28_dialog_content = "Por favor, transmita también mi agradecimiento a la gente de Illumina en nombre de Lumopolis.",
  ui_story_9_1_1_29_dialog_content = "Lo haré, señor.",
  ui_story_9_1_1_X29_dialog_content = "Está bien.",
  ui_story_9_1_1_X30_dialog_content = "Bueno, entonces, Juez Principal, puede seguir adelante y anunciar el comienzo de la sesión la corte.",
  ui_story_9_1_1_X31_dialog_content = "Si mi señor.",
  ui_story_9_1_1_30_dialog_content = "La corte está ahora en sesión. La parte involucrada, por favor, suba al estrado.",
  ui_story_9_1_1_31_dialog_content = "¡Sí!",
  ui_story_9_1_1_32_dialog_content = "(Carleen...)",
  ui_story_9_1_1_33_dialog_content = "Noche Blanca en lo alto.",
  ui_story_9_1_1_34_dialog_content = "En nombre del Salón de Justicia, dictaré la sentencia contra Carleen de Schwartz.",
  ui_story_9_1_1_35_dialog_content = "Carleen de Schwartz, capitana titular de los Guardianes de Lumopolis ...",
  ui_story_9_1_1_36_dialog_content = "Se ha encontrado durante su mandato para ...",
  ui_story_9_1_1_37_dialog_content = "Descuida la resolución tripartita, fuerza la entrada a la Sala de Control con un comandante caballero como rehén e inicia a Damocles sin autorización.",
  ui_story_9_1_1_38_dialog_content = "Eso fue directamente responsable de la falla del escudo, exponiendo posteriormente el Patio y Jardines de Lumopolis a los ataques.",
  ui_story_9_1_1_39_dialog_content = "Lo que lleva a ciento ocho nobles heridos e innumerables sirvientes heridos o muertos, además de una gran pérdida de propiedades.",
  ui_story_9_1_1_40_dialog_content = "Estas acciones violaron las leyes de Lumopolis y deben ser castigadas en consecuencia.",
  ui_story_9_1_1_41_dialog_content = "Sin embargo, en consideración a su esfuerzo por expulsar a los invasores, ",
  ui_story_9_1_1_42_dialog_content = "la Sala de Justicia ha decidido suspender Carleen Delaware Schwartz de servicio por 1 año...",
  ui_story_9_1_1_43_dialog_content = "¿Qué pasa? ¡Que ridículo! ¿¡Cómo pudiste llegar a un veredicto tan absurdo!?",
  ui_story_9_1_1_44_dialog_content = "...",
  ui_story_9_1_1_45_dialog_content = "¡Lo que hizo fue un desprecio flagrante por la vida de todos los nobles de Lumopolis!",
  ui_story_9_1_1_46_dialog_content = "¡Solo tuvo suerte esta vez! Si la dejamos ir con solo una palmada en la muñeca, ¿quién sabe qué hará la próxima vez?",
  ui_story_9_1_1_47_dialog_content = "No estás confabulado con el Salón para proteger a tu hija, ¿verdad, Schwartz?",
  ui_story_9_1_1_48_dialog_content = "¿Cuestiona el veredicto del juez principal, Otto Troy? Eso es impropio de un noble.",
  ui_story_9_1_1_49_dialog_content = "¡Hmph!",
  ui_story_9_1_1_50_dialog_content = "Continúe, señoría.",
  ui_story_9_1_1_51_dialog_content = "El Salón de Justicia ha decidido suspender a Carleen de Schwartz del cargo por 1 año.",
  ui_story_9_1_1_52_dialog_content = "Mientras tanto, debe descubrir la verdad detrás de la incursión.",
  ui_story_9_1_1_53_dialog_content = "Y proporcionar un hallazgo satisfactorio a los nobles.",
  ui_story_9_1_1_54_dialog_content = "Si no puede, despojaremos a Carleen de Schwartz de su cargo, título...",
  ui_story_9_1_1_55_dialog_content = "y residencia en Lumopolis.",
  ui_story_9_1_1_56_dialog_content = "Noche Blanca en lo alto. Que la Luz bendiga a todos en Lumopolis.",
  ui_story_9_1_1_57_dialog_content = "Noche Blanca en lo alto.",
  ui_story_9_1_1_58_dialog_content = "Por aquí, Vice y PlayerName.",
  ui_story_9_1_1_59_dialog_content = "¿Cómo te sientes, Carleen?",
  ui_story_9_1_1_60_dialog_content = "Bien, gracias por preguntar.",
  ui_story_9_1_1_61_dialog_content = "¿Y tú, PlayerName? ¿Están todos curados?",
  ui_story_9_1_1_62_dialog_content = "¡Eso fue tenso!",
  ui_story_9_1_1_63_dialog_content = "Lamento que hayas sido testigo.",
  ui_story_9_1_1_64_dialog_content = "Parece que PlayerName está del todo curado.",
  ui_story_9_1_1_65_dialog_content = "Ja, supongo que sí.",
  ui_story_9_1_1_66_dialog_content = "Ese tipo Otto ...",
  ui_story_9_1_1_67_dialog_content = "Él objetó ruidosamente incluso antes de que el Juez Principal terminara de dictar el veredicto.",
  ui_story_9_1_1_68_dialog_content = "¡No mostró respeto alguno por el señor de la ciudad y Carleen!",
  ui_story_9_1_1_69_dialog_content = "Obviamente, Carleen empezó Damocles para proteger Lumopolis.",
  ui_story_9_1_1_70_dialog_content = "Y el enemigo fue derrotado.",
  ui_story_9_1_1_71_dialog_content = "¿Por qué hizo que pareciera que Carleen cometió un pecado imperdonable?",
  ui_story_9_1_1_72_dialog_content = "¡Ese es el típico noble viejo y ridículo de Lumopolis para ti!",
  ui_story_9_1_1_73_dialog_content = "...",
  ui_story_9_1_1_74_dialog_content = "!",
  ui_story_9_1_1_75_dialog_content = "Lo siento, no quise hablar mal de Lumopolis ...",
  ui_story_9_1_1_76_dialog_content = "Está bien. Sé que no querías malicia. Asimismo, creo en la ley y el veredicto de Lumopolis.",
  ui_story_9_1_1_77_dialog_content = "Incluso si el Salón no me ordenara, investigaría el asunto de todos modos.",
  ui_story_9_1_1_78_dialog_content = "Se como te sientes. Yo también quiero encontrar la verdad.",
  ui_story_9_1_1_79_dialog_content = "Pero, ¿por qué el Hall no le autorizó más ayuda en la investigación, Carleen?",
  ui_story_9_1_1_80_dialog_content = "Quizás el señor de la ciudad nunca consideró a Schummer como una amenaza ...",
  ui_story_9_1_1_81_dialog_content = "¿Qué pasa? ¿Cómo es posible?",
  ui_story_9_1_1_82_dialog_content = "Me reuní con él en privado después del veredicto.",
  ui_story_9_1_1_83_dialog_content = "Me gustaría preguntarle sobre el ataque de Schummer a Lumopolis, padre.",
  ui_story_9_1_1_84_dialog_content = "Adelante.",
  ui_story_9_1_1_85_dialog_content = "¿Cómo es que la ciudad no contraatacó al principio?",
  ui_story_9_1_1_86_dialog_content = "¿Pero dejó que golpeen el escudo en su lugar?",
  ui_story_9_1_1_87_dialog_content = "¿Se da cuenta de cuál es su responsabilidad como Capitán de los Guard. de Jardines de Lumopolis?",
  ui_story_9_1_1_88_dialog_content = "¿Esto es?",
  ui_story_9_1_1_89_dialog_content = "Por supuesto, es para proteger a la gente.",
  ui_story_9_1_1_90_dialog_content = "Por favor, discúlpeme, pero no entiendo por qué ignoró la pregunta por un non sequitur.",
  ui_story_9_1_1_91_dialog_content = "Veo que todavía no entiendes.",
  ui_story_9_1_1_92_dialog_content = "Es deber del capitán defender los Jardines, también conocido como el lugar donde residen los nobles.",
  ui_story_9_1_1_93_dialog_content = "Solo debido a la escasez de mano de obra en los últimos años, los Guardianes han asumido más poder y responsabilidades. ",
  ui_story_9_1_1_94_dialog_content = "incluyendo el mantenimiento de la paz de ciertas partes de la Baja Lumopolis.",
  ui_story_9_1_1_95_dialog_content = "Por lo tanto, en realidad, para la gente, su obligación es garantizar la seguridad de la clase alta.",
  ui_story_9_1_1_96_dialog_content = "...",
  ui_story_9_1_1_97_dialog_content = "Creo que ahora probablemente te has dado cuenta de tu error.",
  ui_story_9_1_1_98_dialog_content = "En cuanto a tu pregunta de ahora ...",
  ui_story_9_1_1_99_dialog_content = "¿Realmente crees que la basura podría romper el escudo?",
  ui_story_9_1_1_100_dialog_content = "Te refieres a...",
  ui_story_9_1_1_101_dialog_content = "Descúbrelo tú mismo. Tengo otra reunión a la que asistir.",
  ui_story_9_1_1_102_dialog_content = "...",
  ui_story_9_1_1_103_dialog_content = "Entonces, ¿qué estaba diciendo ...?",
  ui_story_9_1_1_104_dialog_content = "Yo tampoco lo entiendo. ¿A qué se refería exactamente?",
  ui_story_9_1_1_105_dialog_content = "Quizás no debería preocuparme por los asuntos de Lumopolis o Illumina ...",
  ui_story_9_1_1_106_dialog_content = "¡Solo quiero saber qué sucedió en el pasado!",
  ui_story_9_1_1_107_dialog_content = "PlayerName...",
  ui_story_9_1_1_108_dialog_content = "Todavía me estremezco al pensar en eso.",
  ui_story_9_1_1_109_dialog_content = "¡El blaster estaba a centímetros de distancia y PlayerName todavía no se movía!",
  ui_story_9_1_1_110_dialog_content = "Jefe Vivian y no pude arrastrar PlayerName lejos en absoluto.",
  ui_story_9_1_1_111_dialog_content = "Afortunadamente, Curie vino a ayudar. Así escapamos antes de que golpearan a Aviduz.",
  ui_story_9_1_1_112_dialog_content = "Estaba decidido a no dejar escapar a Aviduz en ese momento.",
  ui_story_9_1_1_113_dialog_content = "Hubiera sido peor si Carleen no hubiera ordenado a Damocles que golpeara a Aviduz.",
  ui_story_9_1_1_114_dialog_content = "...",
  ui_story_9_1_1_115_dialog_content = "Tú... ¿¡Por qué!?",
  ui_story_9_1_1_116_dialog_content = "¡Te estoy ayudando a dirigir el ataque de Damocles, nada más!",
  ui_story_9_1_1_117_dialog_content = "Es mi deber proteger Lumopolis, después de todo.",
  ui_story_9_1_1_118_dialog_content = "Entonces, ¿Vivian y Curie están de vuelta en Illumina ahora?",
  ui_story_9_1_1_119_dialog_content = "Oh, todavía están en el hospital de Lumopolis.",
  ui_story_9_1_1_120_dialog_content = "Pero no te preocupes, no están en peligro a pesar de sus heridas, solo necesitan convalecer en paz por un tiempo.",
  ui_story_9_1_1_X120_dialog_content = "Las alas de Curie se llevaron la peor parte del ataque, pero se ha recuperado más o menos. Ella ha estado al lado de Vivian todo este tiempo.",
  ui_story_9_1_1_121_dialog_content = "Es bueno escuchar, pero ...",
  ui_story_9_1_1_122_dialog_content = "¿Schummer está realmente muerto?",
  ui_story_9_1_1_123_dialog_content = "Hasta que salimos, Schummer estaba en el puente de Aviduz y aparentemente no podía moverse.",
  ui_story_9_1_1_124_dialog_content = "No creo que ninguna criatura pueda sobrevivir al encuentro.",
  ui_story_9_1_1_125_dialog_content = "Creo que sé lo que te molesta, PlayerName.",
  ui_story_9_1_1_126_dialog_content = "Tampoco me detendría hasta ver el cadáver de Schummer.",
  ui_story_9_1_1_X126_dialog_content = "Pero antes de eso, tengo una misión importante que atender.",
  ui_story_9_1_1_X127_dialog_content = "¿Ah? ¿Qué misión?",
  ui_story_9_1_1_X128_dialog_content = "Necesito llevarte a ver a Soroz.",
  ui_story_9_1_1_127_dialog_content = "Encargamos los servicios de especialistas que pueden reparar Soroz. Al parecer, ya completaron su tarea.",
  ui_story_9_1_1_128_dialog_content = "¡<color=#FFB400>Soroz</color>!",
  ui_story_9_1_1_129_dialog_content = "Sin respuesta en absoluto...",
  ui_story_9_1_1_130_dialog_content = "Oye, justo a tiempo.",
  ui_story_9_1_1_131_dialog_content = "¿Señora Gronru? ¿No estás de vacaciones en Gannon?",
  ui_story_9_1_1_132_dialog_content = "¿Y te perdiste la misión secundaria que es difícil de conseguir? ¡Claro que no, sobre todo cuando se trata de un Colossus!",
  ui_story_9_1_1_133_dialog_content = "¡Soy yo quien realmente llamó a Gronru aquí!",
  ui_story_9_1_1_134_dialog_content = "Cuando Raphaela visitó Illumina por primera vez, nos conocimos y nos llevamos bien como dos guisantes en una vaina, como pájaros del mismo plumaje, como mantequilla de maní y mermelada ...",
  ui_story_9_1_1_135_dialog_content = "De acuerdo, no repasemos todas las repeticiones.",
  ui_story_9_1_1_136_dialog_content = "De todos modos, ¡ya encontré las piezas y arreglé el Colossus para PlayerName!",
  ui_story_9_1_1_137_dialog_content = "Y dado que PlayerName ayudó a recuperar mi PS la última vez, incluso renunciaré a la recompensa por completar el escenario esta vez.",
  ui_story_9_1_1_138_dialog_content = "¿Ya lo arreglaste?",
  ui_story_9_1_1_139_dialog_content = "Soroz fue destrozado por los Eclipsites.",
  ui_story_9_1_1_140_dialog_content = "¡Pero ahora ni siquiera puedo ver una abolladura!",
  ui_story_9_1_1_141_dialog_content = "Esto es muy impresionante. ¡No es de extrañar que seas el oficial de tecnología!",
  ui_story_9_1_1_142_dialog_content = "Bueno, ¡Raphaela también ayudó!",
  ui_story_9_1_1_143_dialog_content = "Gracias, gracias a todos. Y ahora...",
  ui_story_9_1_1_144_dialog_content = "¿Soroz está completamente restaurado y es funcional?",
  ui_story_9_1_1_145_dialog_content = "Todo debería estar bien desde el controlador primario hasta el soporte vital y los mód. biológicos.",
  ui_story_9_1_1_146_dialog_content = "¡Incluso aproveché la oportunidad para mejorar la eficiencia del motor!",
  ui_story_9_1_1_147_dialog_content = "Los componentes que utilizaste para la reparación ...",
  ui_story_9_1_1_148_dialog_content = "¡Eres en realidad un celestita para sentir eso!",
  ui_story_9_1_1_149_dialog_content = "Siento la presencia del <color=#FFB400> Mantiz </color>.",
  ui_story_9_1_1_150_dialog_content = "La inspección reveló una similitud del 99,9% entre Soroz y Mantiz en términos de piezas.",
  ui_story_9_1_1_151_dialog_content = "Mantiz es esencialmente chatarra ahora ...",
  ui_story_9_1_1_152_dialog_content = "Así que salvé todo lo que pude para Soroz.",
  ui_story_9_1_1_153_dialog_content = "¡Compartiré Soroz contigo, <color=#FFB400> Mendelson </color>!",
  ui_story_9_1_1_154_dialog_content = "Ahora y siempre, Soroz será tus ojos y oídos para captar todo lo que esté por encima de las nubes.",
  ui_story_9_1_1_155_dialog_content = "¿Así es la muerte? Es un poco diferente... de lo que imaginaba... Se siente tan solo...",
  ui_story_9_1_1_156_dialog_content = "(Mendelson, al final, tanto tú como Mantiz nos ayudaron ...)",
  ui_story_9_1_1_157_dialog_content = "Pero, ¿por qué no puedo sentir la presencia de Soroz?",
  ui_story_9_1_1_158_dialog_content = "Bien... Encontré algo en el puente que podría ser un componente.",
  ui_story_9_1_1_159_dialog_content = "Pero estaba dañado irreparablemente. Solo esta pequeña parte parece estar relativamente completa.",
  ui_story_9_1_1_160_dialog_content = "Esto es... Recuerdo que Soroz mencionó que hay un componente central en la Plantilla de Eco.",
  ui_story_9_1_1_161_dialog_content = "La conciencia de un Colossus está realmente almacenada en el centro.",
  ui_story_9_1_1_162_dialog_content = "Si esto es el centro, ¡entonces podemos restaurar la conciencia de Soroz!",
  ui_story_9_1_1_163_dialog_content = "¡Excelente! ¿Es este el centro?",
  ui_story_9_1_1_164_dialog_content = "Debería ser... Soroz mencionó la Plantilla de Eco antes, pero no me la mostró...",
  ui_story_9_1_1_165_dialog_content = "Bueno, no hay forma de que un Colossus lo haya desconectado para echarle un vistazo, ¿verdad?",
  ui_story_9_1_1_166_dialog_content = "Así que... ¿Crees que este es el centro?",
  ui_story_9_1_1_167_dialog_content = "Eso creo...",
  ui_story_9_1_1_168_dialog_content = "Bueno, ¿sabes cómo solucionarlo?",
  ui_story_9_1_1_169_dialog_content = "...",
  ui_story_9_1_1_170_dialog_content = "Yo...",
  ui_story_9_1_1_171_dialog_content = "PlayerName y señora Gronru, ninguno de ustedes tiene idea de cómo solucionarlo?",
  ui_story_9_1_1_172_dialog_content = "Lo siento.",
  ui_story_9_1_1_173_dialog_content = "Todavía no soy lo suficientemente bueno para desentrañar la tecnología de esa época.",
  ui_story_9_1_1_174_dialog_content = "Yo ... solo aprendí un poco sobre Colossi de Soroz.",
  ui_story_9_1_1_175_dialog_content = "Pero eso nunca me molestó, y nunca pensé que algún día ... Podría perder a Soroz.",
  ui_story_9_1_1_X175_dialog_content = "Si me hubiera preocupado un poco más por Soroz, tal vez ...",
  ui_story_9_1_1_176_dialog_content = "Esta es una prueba, PlayerName. Solo mejorando tu voluntad en soledad puedes volverte fuerte.",
  ui_story_9_1_1_177_dialog_content = "La realidad es que estás vivo y es mi deber mantenerlo así.",
  ui_story_9_1_1_178_dialog_content = "PlayerName, puedo pasar el cursor sobre Lumopolis y encontrarme contigo cuando me necesites.",
  ui_story_9_1_1_179_dialog_content = "Lamento hacerte pasar por esto, Soroz.",
  ui_story_9_1_1_180_dialog_content = "¿Puedes oírme, Soroz?",
  ui_story_9_1_1_181_dialog_content = "Lo siento.",
  ui_story_9_1_1_182_dialog_content = "Perdón por ser descuidado y no cuidarte.",
  ui_story_9_1_1_183_dialog_content = "PlayerName...",
  ui_story_9_1_1_184_dialog_content = "No lo entiendo. ¿No es el Colossus más resistente que antes?",
  ui_story_9_1_1_185_dialog_content = "¿Por qué PlayerName está triste por eso?",
  ui_story_9_1_1_186_dialog_content = "Silencio, Raphaela.",
  ui_story_9_1_1_187_dialog_content = "Oh, lo siento.",
  ui_story_9_1_1_188_dialog_content = "Dejaste Soroz para proteger a la gente de Lumopolis, PlayerName.",
  ui_story_9_1_1_189_dialog_content = "También soy responsable de esto.",
  ui_story_9_1_1_190_dialog_content = "Agradezco tu ayuda, pero no puedo culpar a ninguno de ustedes por lo que le sucedió a Soroz.",
  ui_story_9_1_1_191_dialog_content = "¡Todo esto es obra de Schummer y los Eclipsites!",
  ui_story_9_1_1_192_dialog_content = "¡Bien, Schummer, casi lo olvido!",
  ui_story_9_1_1_193_dialog_content = "Tengo algo importante que decirte, Carleen.",
  ui_story_9_1_1_194_dialog_content = "¿Qué es?",
  ui_story_9_1_1_195_dialog_content = "¡Los Caballeros Lumo descubrieron que Aviduz se estrelló en <color=#FFB400> Eraveil </color>!",
  ui_story_9_1_1_196_dialog_content = "Ya veo. Supongo que ahora iremos a la ciudad natal de PlayerName.",
  ui_story_9_1_1_197_dialog_content = "¿Eraveil ...?",
  ui_story_9_1_1_198_dialog_content = "Qué irónico que Aviduz se estrelle en Eraveil.",
  ui_story_9_1_1_199_dialog_content = "Y tengo algo más que decirte, PlayerName.",
  ui_story_9_1_1_200_dialog_content = "El ataque específico de Aviduz a la ciudad así como a los tres módulos ...",
  ui_story_9_1_1_201_dialog_content = "Los he denunciado a Lumopolis.",
  ui_story_9_1_1_202_dialog_content = "Espero que lo entiendas, PlayerName.",
  ui_story_9_1_1_203_dialog_content = "Está bien, lo entiendo.",
  ui_story_9_1_1_204_dialog_content = "Los tres módulos ...",
  ui_story_9_1_1_205_dialog_content = "¿Todavía recuerdas uno de los tres módulos, el <color=#FFB400> Módulo Think Tank</color>, PlayerName?",
  ui_story_9_1_1_206_dialog_content = "Por supuesto. Recuerdo que Mendelson dijo ...",
  ui_story_9_1_1_207_dialog_content = "Que en él se guarda mucha información, prácticamente la que quieras.",
  ui_story_9_1_1_208_dialog_content = "Sí, también lo recuerdo.",
  ui_story_9_1_1_209_dialog_content = "Encuentre el módulo Think Tank y sabremos cómo arreglar la plantilla de eco.",
  ui_story_9_1_1_210_dialog_content = "¡Sí! PlayerName, Carleen ...",
  ui_story_9_1_1_211_dialog_content = "¡Adelante a Eraveil!",
  ui_story_9_1_1_212_dialog_content = "<color=#e8d9bb> Eraveil </color>",
  ui_story_9_1_1_213_dialog_content = "Tal como esperaba, todavía eres un celestita de corazón...",
  ui_story_9_1_1_214_dialog_content = "Volviendo a Eraveil, la fosa común, solo para morir.",
  ui_story_9_1_1_215_dialog_content = "...",
  ui_story_9_1_1_216_dialog_content = "Solo eres bueno para causar problemas a los demás.",
  ui_story_9_1_1_217_dialog_content = "Pero hasta que consiga lo que quiero",
  ui_story_9_1_1_218_dialog_content = "no puedes morir.",
  ui_story_9_1_1_219_dialog_content = "*Tose*",
  ui_story_9_1_1_220_dialog_content = "Finalmente, estás despierto.",
  ui_story_9_1_1_221_dialog_content = "... Me hace... enojar cuando... eres la primera persona ... Ok...",
  ui_story_9_1_1_222_dialog_content = "Es una buena forma de agradecer a tu salvador después de la paliza que recibiste.",
  ui_story_9_1_1_223_dialog_content = "Disparates... *Tose*",
  ui_story_9_1_1_224_dialog_content = "Admítelo, Schummer. Perdiste. Minuciosamente.",
  ui_story_9_1_1_225_dialog_content = "Yo... no perdí... con esos peones.",
  ui_story_9_1_1_226_dialog_content = "Humph, seguro que no. ¿Sabes por qué perdiste?",
  ui_story_9_1_1_227_dialog_content = "Alto... *Tose*",
  ui_story_9_1_1_228_dialog_content = "Porque no eres tan poderoso.",
  ui_story_9_1_1_229_dialog_content = "Yo... No quiero escucharlo...",
  ui_story_9_1_1_230_dialog_content = "Puedo darte otra oportunidad, supongo.",
  ui_story_9_1_1_231_dialog_content = "Ayúdame a completar el experimento y te garantizo que lo sabrás ...",
  ui_story_9_1_1_232_dialog_content = "Cómo es ser verdaderamente invencible.",
  ui_story_9_1_1_233_dialog_content = "¿Otra oportunidad...? ¿Mejorar la semilla?",
  ui_story_9_1_1_234_dialog_content = "Bien, tu cerebro todavía funciona.",
  ui_story_9_1_1_235_dialog_content = "*Tose*... Tengo... solo una pregunta...",
  ui_story_9_1_1_236_dialog_content = "Eres muy molesto, ya veo.",
  ui_story_9_1_1_237_dialog_content = "¿Por qué me estás ayudando?",
  ui_story_9_1_1_238_dialog_content = "No se equivoque, solo quiero completar el experimento.",
  ui_story_9_1_1_239_dialog_content = "...",
  ui_story_9_1_1_240_dialog_content = "Y tú, eres mi asignatura favorita.",
  ui_story_9_1_1_241_dialog_content = "...",
  ui_story_9_1_1_242_dialog_content = "¿Por qué me ayudarías?",
  ui_story_9_1_1_243_dialog_content = "Yo... Sé que estaban equivocados ...",
  ui_story_9_2_1_1_dialog_content = "Aquí es donde se estrelló Aviduz ... <color=#FFB400> Eraveil </color>.",
  ui_story_9_2_1_2_dialog_content = "Eso es todo...",
  ui_story_9_2_1_3_dialog_content = "(La ciudad natal con la que he soñado durante 17 años ...)",
  ui_story_9_2_1_4_dialog_content = "(Ya Casi...)",
  ui_story_9_2_1_5_dialog_content = "Estamos todos aquí contigo, PlayerName.",
  ui_story_9_2_1_6_dialog_content = "No olvides que todavía nos tienes, PlayerName.",
  ui_story_9_2_1_7_dialog_content = "Gracias, Vice y Carleen.",
  ui_story_9_2_1_8_dialog_content = "¿Cuántas veces tenemos que decirte que no es necesario, PlayerName?",
  ui_story_9_2_1_9_dialog_content = "Aún así, es correcto que te agradezca.",
  ui_story_9_2_1_10_dialog_content = "Gracias a ti, tengo el coraje de enfrentarme al mundo.",
  ui_story_9_2_1_11_dialog_content = "En ese caso, también tengo que agradecerles a los dos.",
  ui_story_9_2_1_12_dialog_content = "Porque me diste la oportunidad de conocer el mundo.",
  ui_story_9_2_1_13_dialog_content = "PlayerName, Carleen ...",
  ui_story_9_2_1_14_dialog_content = "¡Nuestro viaje acaba de comenzar!",
  ui_story_9_2_1_15_dialog_content = "Entonces, ¿alguien sabe qué tipo de lugar es Eraveil?",
  ui_story_9_2_1_16_dialog_content = "Lo leí antes, pero PlayerName probablemente sepa más.",
  ui_story_9_2_1_17_dialog_content = "Eraveil es mi hogar. Mantiene un clima templado durante todo el año.",
  ui_story_9_2_1_18_dialog_content = "Reproduce algunos clips en Eraveil, Soroz.",
  ui_story_9_2_1_19_dialog_content = "...",
  ui_story_9_2_1_20_dialog_content = "...",
  ui_story_9_2_1_21_dialog_content = "¿Soroz? Sor ...",
  ui_story_9_2_1_22_dialog_content = "Uh, PlayerName, la plantilla de eco de Soroz es, eh ...",
  ui_story_9_2_1_23_dialog_content = "...",
  ui_story_9_2_1_24_dialog_content = "Tócala de nuevo, Soroz.",
  ui_story_9_2_1_25_dialog_content = "Interpretando a Eraveil por decimosexta vez.",
  ui_story_9_2_1_26_dialog_content = "\"En el sur de la columna vertebral del mundo, Eraveil es un valle fértil rodeado de montañas\".",
  ui_story_9_2_1_27_dialog_content = "“Mantiene un clima templado durante todo el año y es el hogar de generaciones de celestitas amables y trabajadores\".",
  ui_story_9_2_1_28_dialog_content = "¿Qué son esas cosas borrosas, Soroz?",
  ui_story_9_2_1_29_dialog_content = "Diente de León. La parte amarilla es la flor, la pelusa blanca es la semilla.",
  ui_story_9_2_1_30_dialog_content = "¿Por qué no puedo sostenerlos?",
  ui_story_9_2_1_31_dialog_content = "Es solo un video, PlayerName.",
  ui_story_9_2_1_32_dialog_content = "Puedo reproducirlo de nuevo si quieres.",
  ui_story_9_2_1_33_dialog_content = "Interpretando a Eraveil por decimoséptima vez.",
  ui_story_9_2_1_34_dialog_content = "... 90ª vez.",
  ui_story_9_2_1_35_dialog_content = "... 437ª vez.",
  ui_story_9_2_1_36_dialog_content = "... 2,628ª vez.",
  ui_story_9_2_1_37_dialog_content = "¡Te juro que recuperaré tu conciencia, Soroz!",
  ui_story_9_2_1_38_dialog_content = "<color=#e8d9bb> Eraveil </color>",
  ui_story_9_2_1_39_dialog_content = "Ya estamos acá.",
  ui_story_9_2_1_40_dialog_content = "¿Este es Eraveil?",
  ui_story_9_2_1_41_dialog_content = "No es lo que imaginaba en absoluto ...",
  ui_story_9_2_1_42_dialog_content = "¡Esto es completamente diferente al video que vi!",
  ui_story_9_2_1_43_dialog_content = "¿Estás seguro de que estamos en el lugar correcto?",
  ui_story_9_2_1_44_dialog_content = "Esta es la ubicación de las coordenadas.",
  ui_story_9_2_1_45_dialog_content = "...",
  ui_story_9_2_1_46_dialog_content = "Hierbas marchitas en todas partes ...",
  ui_story_9_2_1_47_dialog_content = "Oye, veo algunas rocas blancas debajo de la hierba.",
  ui_story_9_2_1_48_dialog_content = "Las rocas están ordenadas, probablemente los cimientos de una casa.",
  ui_story_9_2_1_49_dialog_content = "Yo también lo veo aquí ... Y por allí...",
  ui_story_9_2_1_50_dialog_content = "Este fue probablemente un asentamiento considerable.",
  ui_story_9_2_1_51_option_content = "Escaneo psíquico",
  ui_story_9_2_1_52_dialog_content = "(Nada...)",
  ui_story_9_2_1_53_dialog_content = "¿Por qué no puedo sentir nada ...?",
  ui_story_9_2_1_54_dialog_content = "Ha pasado demasiado tiempo, PlayerName. Incluso las rocas se han erosionado.",
  ui_story_9_2_1_55_option_content = "Escaneo psíquico",
  ui_story_9_2_1_56_dialog_content = "...",
  ui_story_9_2_1_57_dialog_content = "Sigamos adelante, PlayerName, tal vez ...",
  ui_story_9_2_1_58_option_content = "Escaneo psíquico",
  ui_story_9_2_1_59_dialog_content = "¡Achuu!",
  ui_story_9_2_1_60_dialog_content = "¡Cuidado, estoy detectando <color=#FFB400>Darkflow</color>!",
  ui_story_9_2_1_61_dialog_content = "¿Es porque Aviduz está cerca?",
  ui_story_9_2_1_62_dialog_content = "No creo que sea eso ... El Darkflow es muy fuerte aquí. Algo más parece haber entrado.",
  ui_story_9_2_1_63_dialog_content = "¿Estás bien, PlayerName?",
  ui_story_9_2_1_64_dialog_content = "Mejor que nunca.",
  ui_story_9_2_1_65_dialog_content = "¡Carleen, detrás de ti!",
  ui_story_9_2_1_66_dialog_content = "¡Gahhhhhh!",
  ui_story_9_2_1_67_dialog_content = "¡Extendido! ¡Flor de Hielo!",
  ui_story_9_2_1_68_dialog_content = "¡Eclipsites! ¡Cómo te atreves a destruir la casa de PlayerName!",
  ui_story_9_2_1_69_dialog_content = "Toma el mando, PlayerName.",
  ui_story_9_2_2_1_dialog_content = "<color=#e8d9bb>Dentro de Aviduz</color>",
  ui_story_9_2_2_2_dialog_content = "Quédate quieto.",
  ui_story_9_2_2_3_dialog_content = "¿Es esta la <color=#FFB400> cápsula curativa </color>?",
  ui_story_9_2_2_4_dialog_content = "¿Te sientes mejor?",
  ui_story_9_2_2_5_dialog_content = "Veo que te anticipaste a esto ... *Tose*",
  ui_story_9_2_2_6_dialog_content = "Por eso ... pones esta basura en mi Colossus ...",
  ui_story_9_2_2_7_dialog_content = "Cuida tus palabras.",
  ui_story_9_2_2_8_dialog_content = "Esto solo se ve ... repugnante.",
  ui_story_9_2_2_9_dialog_content = "No tienes remedio.",
  ui_story_9_2_2_10_dialog_content = "¿Qué pasa? No... *Tose*... ¿No vas a guardar tu asignatura favorita?",
  ui_story_9_2_2_11_dialog_content = "Te lo dije, puedes tener un poder incomparable una vez que estés dispuesto a dejar atrás todo celestita.",
  ui_story_9_2_2_12_dialog_content = "Y te dije más de una vez que ya no soy celestita.",
  ui_story_9_3_2_1_dialog_content = "Oye, ¿estás seguro de que este es el camino?",
  ui_story_9_3_2_2_dialog_content = "¿Estás dudando de mí, el hombre más confiable de Rediesel Wrench?",
  ui_story_9_3_2_3_dialog_content = "¿Qué pasa? ¿Has estado liderando el camino todo este tiempo?",
  ui_story_9_3_2_4_dialog_content = "¡Qué suerte encontrar una bomba en un lugar como este!",
  ui_story_9_3_2_5_dialog_content = "Extraño, ¿no es este el fiasco que acabo de descartar?",
  ui_story_9_3_2_6_dialog_content = "Entonces, ¿nos hemos estado moviendo en círculo?",
  ui_story_9_3_2_7_dialog_content = "¿De qué estás hablando? ¡Seguí el mapa!",
  ui_story_9_3_2_8_dialog_content = "Brock, idiota, ¡tienes el mapa al revés!",
  ui_story_9_3_2_9_dialog_content = "Es un milagro que no estemos más perdidos de lo que estamos.",
  ui_story_9_3_2_10_dialog_content = "<size=45> ¡Brock! </size>",
  ui_story_9_3_2_11_dialog_content = "¡Te abriré el cráneo y descubriré qué es exactamente lo que está mal en esa cabeza!",
  ui_story_9_3_2_12_dialog_content = "♪¡No temas, Barbara está aquí!",
  ui_story_9_3_2_13_dialog_content = "<anim type=Shake>♪¡Cuando hay amor, hay esperanza! </anim>",
  ui_story_9_3_2_14_dialog_content = "¡Argh! ¡No puedo soportarlo más, jefe! ¿Puedo aplastarla?",
  ui_story_9_3_2_X14_dialog_content = "El jefe dijo que hoy deberíamos tratar de llevarnos bien. ¡No soñaría con rebajarme para desperdiciar la más mínima atención en ti!",
  ui_story_9_3_2_X15_dialog_content = "Si no te callas, ni siquiera el jefe podrá evitar que termine contigo aquí y ahora ...",
  ui_story_9_3_2_15_dialog_content = "Oye. ¿Dónde está el jefe, de todos modos?",
  ui_story_9_3_2_16_dialog_content = "¿Alguno de ustedes sabe dónde está el jefe?",
  ui_story_9_3_2_17_dialog_content = "¡Mi aura de asombro probablemente lo asustó! ¡Sabía que soy el número 1!",
  ui_story_9_3_2_18_dialog_content = "Estaba aquí hace un segundo.",
  ui_story_9_3_2_19_dialog_content = "¿Honcho Sinsa se ha ido?",
  ui_story_9_3_2_20_dialog_content = "Oye, Bopper también se ha ido.",
  ui_story_9_3_2_21_dialog_content = "¡Carguen, seguidores míos!",
  ui_story_9_3_2_22_dialog_content = "¡Vuelve aquí, Brock!",
  ui_story_9_3_2_23_dialog_content = "<size=45><anim type=Shake>&*#%#%……！</anim></size>",
  ui_story_9_3_2_24_dialog_content = "<color=#e8d9bb> ¡Bonk! </color>",
  ui_story_9_3_2_25_dialog_content = "¡Ay, eso duele!",
  ui_story_9_3_2_26_dialog_content = "¡¿Quién me lanzó la maldita trampa ?!",
  ui_story_9_3_2_27_dialog_content = "¡Solo los cobardes emboscan a la gente!",
  ui_story_9_3_2_28_dialog_content = "¡Sal y lucha como un hombre! ¡Te haré carne picada!",
  ui_story_9_3_2_29_dialog_content = "Ese lugar que pisamos no se veía diferente ...",
  ui_story_9_3_2_30_dialog_content = "Esto podría parecer una trampa artificial.",
  ui_story_9_3_2_31_dialog_content = "Sin embargo, a juzgar por el follaje que cubre el agujero ...",
  ui_story_9_3_2_32_dialog_content = "¡Sal ahora!",
  ui_story_9_3_2_33_dialog_content = "¿Me escuchaste, jefe?",
  ui_story_9_3_2_34_dialog_content = "¿Qué dijiste?",
  ui_story_9_3_2_35_dialog_content = "¡Es un pozo natural, no una trampa! ¡Nadie nos ataca!",
  ui_story_9_3_2_36_dialog_content = "...",
  ui_story_9_3_2_37_dialog_content = "No escuchaste nada, Bopper, y no le digas a mi hermana pequeña que maldije.",
  ui_story_9_3_2_38_dialog_content = "Claro, siempre y cuando dejes de fingir que no me escuchas ...",
  ui_story_9_3_2_39_dialog_content = "<anim type=Shake> ¡Carguen, mis seguidores! </anim>",
  ui_story_9_3_2_40_dialog_content = "<anim type=Shake> ¡Vuelve aquí, Brock! </anim>",
  ui_story_9_3_2_41_dialog_content = "Está bien, está bien, está bien ...",
  ui_story_9_3_2_42_dialog_content = "Como no es una trampa, no tenemos que preocuparnos por ser emboscados. Salgamos de aquí, rápido.",
  ui_story_9_3_2_X42_dialog_content = "¡Regina! ¡Brock! ¿¡Puedes oírme!?",
  ui_story_9_3_2_43_dialog_content = "Basado en cuánto tiempo caímos y la aceleración gravitacional ...",
  ui_story_9_3_2_44_dialog_content = "No nos escucharán por mucho que gritemos.",
  ui_story_9_3_2_45_dialog_content = "¡Regina!",
  ui_story_9_3_2_46_dialog_content = "¡Le voy a decir a Eve que maldijo, jefe!",
  ui_story_9_3_2_47_dialog_content = "No, no, no... ¿Qué dijiste sobre cuánto tiempo y aceleración?",
  ui_story_9_3_2_48_dialog_content = "En pocas palabras, el pozo es demasiado profundo para que nos escuchen.",
  ui_story_9_3_2_49_dialog_content = "*Tose* Ya veo ...",
  ui_story_9_3_2_50_dialog_content = "Debería haber esperado el análisis sensato del piloto de <color=#FFB400> Lepidoz </color>.",
  ui_story_9_3_2_51_dialog_content = "Muy bien, movámonos y veamos qué tan lejos llega este agujero.",
  ui_story_9_3_2_52_dialog_content = "<color=#e8d9bb> ¡Ding! ¡Clang! </color>",
  ui_story_9_3_2_53_dialog_content = "Mire, jefe, ¡hay tantas piezas de Colossus aquí!",
  ui_story_9_3_2_54_dialog_content = "Vaya, una cabecita tan redonda y una linda ala diminuta ... ¡Qué artesanía tan fina!",
  ui_story_9_3_2_55_dialog_content = "Primera vez que veo una luciérnaga tan bonita ... ¡A Lepidoz le encantará, seguro!",
  ui_story_9_3_2_56_dialog_content = "A esta cosa solo le queda un ala. ¿De qué sirve además de un balón de fútbol?",
  ui_story_9_3_2_57_dialog_content = "¡Hay más allá! Me llevo este y aquél ...",
  ui_story_9_3_2_58_dialog_content = "¡Deberías dejar algo de espacio para lo que realmente vinimos a hacer aquí!",
  ui_story_9_3_2_59_dialog_content = "Lo sé, pero también le prometí a Lepidoz que llevaría souvenirs.",
  ui_story_9_3_2_60_dialog_content = "Estoy seguro de que encontraremos aún más objetos de valor una vez que nos encontremos con el Colossus negro que se estrelló.",
  ui_story_9_3_2_61_dialog_content = "Oh...",
  ui_story_9_3_2_62_dialog_content = "Pero, ¿por qué habría tantas partes esparcidas en esta cueva?",
  ui_story_9_3_2_63_dialog_content = "No me digas que realmente encontramos ...",
  ui_story_9_3_2_64_dialog_content = "?",
  ui_story_9_3_2_65_dialog_content = "¡Tenemos que encontrar una salida e irnos!",
  ui_story_9_3_2_66_dialog_content = "Siento que hay alguien más aquí además de nosotros.",
  ui_story_9_4_1_1_dialog_content = "¡Algo esta mal!",
  ui_story_9_4_1_2_dialog_content = "¡Empala a los enemigos!",
  ui_story_9_4_1_3_dialog_content = "Oye, nena, será mejor que reconsideres ese ataque furtivo.",
  ui_story_9_4_1_4_dialog_content = "¿Son Aurorians?",
  ui_story_9_4_1_5_dialog_content = "No está mal como luchador, pero su juicio deja algo que desear.",
  ui_story_9_4_1_6_dialog_content = "¡Por qué tú...!",
  ui_story_9_4_1_7_dialog_content = "¿Qué está pasando, Carleen?",
  ui_story_9_4_1_8_dialog_content = "¿Estás bien, Jefe?",
  ui_story_9_4_1_9_dialog_content = "¡Estoy genial!",
  ui_story_9_4_1_10_dialog_content = "¡Eres tú!",
  ui_story_9_4_1_11_dialog_content = "¿Conoces a este delincuente Rediesel Wrench, PlayerName?",
  ui_story_9_4_1_12_option_content = "Cuando estaba en Illumina ...",
  ui_story_9_4_1_13_dialog_content = "Después de que Soroz y yo saliéramos de la superficie, nos estrellamos cerca de la Subciudad.",
  ui_story_9_4_1_14_dialog_content = "Era el líder de los bandidos.",
  ui_story_9_4_1_15_dialog_content = "¿Por qué dices eso? Te salvamos de los Eclipsites, ¿de acuerdo?",
  ui_story_9_4_1_16_dialog_content = "¡En el desierto de Rediesel, Soroz casi fue saqueado y destrozado por ese tipo!",
  ui_story_9_4_1_17_option_content = "Cuando estaba en el desierto de Rediesel ...",
  ui_story_9_4_1_18_dialog_content = "Nos interceptó con su pandilla cuando intentamos irnos.",
  ui_story_9_4_1_19_dialog_content = "Y casi destroza a Soroz en pedazos.",
  ui_story_9_4_1_20_dialog_content = "Bueno, no puedo refutar eso. Eso fue culpa mía.",
  ui_story_9_4_1_21_dialog_content = "Fue gracias a ti que mi hermana fue rescatada más tarde.",
  ui_story_9_4_1_22_dialog_content = "Te debo una, PlayerName.",
  ui_story_9_4_1_23_dialog_content = "¿Has estado en el desierto de Rediesel?",
  ui_story_9_4_1_24_dialog_content = "Después de que dejamos Lumopolis la última vez.",
  ui_story_9_4_1_25_dialog_content = "Veo que la princesa de Lumopolis sigue siendo su antiguo yo agresivo.",
  ui_story_9_4_1_26_dialog_content = "Atacar antes de saber lo que está pasando ... ¿Qué pasa si personas inocentes resultan heridas?",
  ui_story_9_4_1_27_dialog_content = "No lo hizo a propósito, Sinsa.",
  ui_story_9_4_1_28_dialog_content = "Eso fue culpa mía, de hecho.",
  ui_story_9_4_1_29_dialog_content = "Yo, Carleen de Schwartz, me disculpo por mis acciones.",
  ui_story_9_4_1_30_dialog_content = "Pero si insistes en difamar Lumopolis ...",
  ui_story_9_4_1_31_dialog_content = "Ahora podemos arreglar algunas viejas cuentas entre nosotros.",
  ui_story_9_4_1_X31_dialog_content = "Si quieres pelear, ¡al menos puedes elegir un momento y un lugar razonables!",
  ui_story_9_4_1_32_dialog_content = "Ella es una luchadora, ¿no es así, PlayerName? ¿Cómo es que están trabajando juntos?",
  ui_story_9_4_1_33_dialog_content = "Bueno, no sé cuál es el problema entre ustedes dos ...",
  ui_story_9_4_1_34_dialog_content = "Pero como ustedes dos han luchado junto a mí y Vice, espero que puedas dejar tus diferencias a un lado por ahora.",
  ui_story_9_4_1_35_dialog_content = "Claro, iré con lo que dijo PlayerName.",
  ui_story_9_4_1_36_dialog_content = "Esa es mi línea.",
  ui_story_9_4_1_X36_dialog_content = "Tenga en cuenta que me detuve simplemente porque tengo otras misiones que atender. No tengo tiempo que perder contigo.",
  ui_story_9_4_1_X37_dialog_content = "Ja, no puedo creer que hayas dicho eso ...",
  ui_story_9_4_1_37_dialog_content = "¡Ejem! ¡Ey! Cambiemos de tema, Sinsa ...",
  ui_story_9_4_1_38_option_content = "¿Quién es la chica detrás de ti?",
  ui_story_9_4_1_39_dialog_content = "Oh, este es Bopper.",
  ui_story_9_4_1_40_dialog_content = "Hola a todos, soy Bopper.",
  ui_story_9_4_1_41_dialog_content = "¿Entonces eres PlayerName? ¡Eve te menciona mucho!",
  ui_story_9_4_1_42_dialog_content = "Vimos un Colossus negro estrellándose por aquí y vino mirando.",
  ui_story_9_4_1_43_dialog_content = "Solo para caer accidentalmente en un agujero, antes de chocar contigo después de que salimos.",
  ui_story_9_4_1_44_option_content = "¿Qué estás haciendo acá?",
  ui_story_9_4_1_45_dialog_content = "¡Por supuesto, estamos aquí por el botín! ¡Jajajajaja!",
  ui_story_9_4_1_46_dialog_content = "¿Botín? ¿A qué te refieres con eso?",
  ui_story_9_4_1_47_dialog_content = "Vimos un Colossus negro estrellándose por aquí y vino mirando.",
  ui_story_9_4_1_48_dialog_content = "Solo para caer accidentalmente en un agujero, antes de chocar contigo después de que salimos.",
  ui_story_9_4_1_49_dialog_content = "Hola, soy Bopper. ¿Debes ser PlayerName? ¡Eve te menciona mucho!",
  ui_story_9_4_1_50_dialog_content = "¿También estás buscando tesoros, PlayerName?",
  ui_story_9_4_1_51_dialog_content = "Bueno, es una larga historia ...",
  ui_story_9_4_1_52_dialog_content = "<color=#e8d9bb>Algún tiempo después...</color>",
  ui_story_9_4_1_53_dialog_content = "<size=45> ¡¿Eraveil ?! </size>",
  ui_story_9_4_1_54_dialog_content = "Así que este es Eraveil ...",
  ui_story_9_4_1_55_dialog_content = "Has pasado por muchas cosas en poco tiempo, PlayerName.",
  ui_story_9_4_1_56_dialog_content = "Probablemente sea la prueba y la tribulación que debo atravesar para regresar al mundo de la superficie.",
  ui_story_9_4_1_57_dialog_content = "Pero nunca abandonaré la esperanza.",
  ui_story_9_4_1_58_dialog_content = "Estoy emocionado, así que te acompaño en este viaje.",
  ui_story_9_4_1_59_dialog_content = "¿Ah?",
  ui_story_9_4_1_60_dialog_content = "¿Tienes objeciones?",
  ui_story_9_4_1_61_dialog_content = "Ninguno en absoluto. ¡Bienvenido al equipo!",
  ui_story_9_4_1_62_dialog_content = "De todos modos, deberíamos utilizar toda la ayuda que podamos conseguir.",
  ui_story_9_4_1_63_dialog_content = "¡Supongo que tenemos un consenso!",
  ui_story_9_4_1_64_dialog_content = "Pero que pasa Regina ¿y los otros?",
  ui_story_9_4_1_65_dialog_content = "Oh sí... Dime, ¿viste alguna otra Rediesel Wrench en tu camino?",
  ui_story_9_4_1_66_dialog_content = "¿Hay más de ustedes?",
  ui_story_9_4_1_X66_dialog_content = "Sí, nos encantan nuestras salidas grupales en Rediesel Wrench.",
  ui_story_9_4_1_67_dialog_content = "No vimos a nadie más que a Eclipsites todo el camino hasta aquí.",
  ui_story_9_4_1_X67_dialog_content = "Ugh...",
  ui_story_9_4_1_68_dialog_content = "Bueno, en cuanto terminas de hablar, aparecen Eclipsites ... Típico.",
  ui_story_9_4_1_69_dialog_content = "¡Déjame ver si tu liderazgo ha mejorado, PlayerName!",
  ui_story_9_4_2_1_dialog_content = "(Hablando en eclipsiano) Se acerca un grupo de Aurorians, mi señora.",
  ui_story_9_4_2_2_dialog_content = "(Hablando en eclipsiano) También tienen un celestita.",
  ui_story_9_4_2_3_dialog_content = "(Hablando en eclipsiano) Pero somos demasiado escasos para impedirlos.",
  ui_story_9_4_2_4_dialog_content = "¿Celestita?",
  ui_story_9_4_2_5_dialog_content = "¿Puede ser el que se llama PlayerName?",
  ui_story_9_4_2_6_dialog_content = "No, la escoria debería ser...",
  ui_story_9_4_2_7_dialog_content = "...",
  ui_story_9_4_2_8_dialog_content = "No sirve para nada, Schummer.",
  ui_story_9_4_2_9_dialog_content = "(Habla en eclipsiano) Ve y tráeme a los peones de Lumopolis.",
  ui_story_9_4_2_10_dialog_content = "(Hablando en eclipsiano) Sí, mi señora.",
  ui_story_9_4_2_11_dialog_content = "Desprecio las complicaciones ...",
  ui_story_9_4_2_12_dialog_content = "y detesta el desperdicio de recursos.",
  ui_story_9_4_2_13_dialog_content = "Pero nada interrumpirá el experimento.",
  ui_story_9_5_2_1_dialog_content = "<color=#e8d9bb> Escondite secreto del True Order </color>",
  ui_story_9_5_2_2_dialog_content = "¿Cuál es su pedido, estimada Lady Victoria?",
  ui_story_9_5_2_3_dialog_content = "Reunirás más <color=#FFB400> Semillas </color> para el gran Señor de la Verdad, Faust.",
  ui_story_9_5_2_4_dialog_content = "Será un honor, Lady Victoria.",
  ui_story_9_5_2_5_dialog_content = "Trae también Pact y Nails.",
  ui_story_9_5_2_6_dialog_content = "Sí, Lady Victoria. Que la Verdad los bendiga.",
  ui_story_9_5_2_7_dialog_content = "¿Es esto lo que mencionaste antes?",
  ui_story_9_5_2_8_dialog_content = "Poder de la oscuridad que es temida y codiciada.",
  ui_story_9_5_2_9_dialog_content = "De hecho, hay personas que, viviendo bajo el sol brillante, traicionarían la Verdad y buscarían voluntariamente el poder de la Semilla.",
  ui_story_9_5_2_10_dialog_content = "Lástima de aquellos que le dieron la espalda a su naturaleza Aurorian.",
  ui_story_9_5_2_11_dialog_content = "¿Seguro de que quieres ingerir esto?",
  ui_story_9_5_2_12_dialog_content = "Oh, lo olvidé, eres solo un libro y probablemente no conoces la naturaleza.",
  ui_story_9_5_2_13_dialog_content = "Victoria Varaki.",
  ui_story_9_5_2_X13_dialog_content = "Basta de hablar. Todo lo que tienes que hacer es ponérmelo.",
  ui_story_9_5_2_14_dialog_content = "Ok. Veamos si puedes devorarlo.",
  ui_story_9_5_2_15_dialog_content = "<color=#e8d9bb> ¡Crunch! ¡Gulp! </color>",
  ui_story_9_5_2_16_dialog_content = "¿A qué sabe?",
  ui_story_9_5_2_17_dialog_content = "Tiene un matiz de carne.",
  ui_story_9_5_2_18_dialog_content = "Esta es una semilla extraída de un celestita.",
  ui_story_9_5_2_19_dialog_content = "¿Celestita?",
  ui_story_9_5_2_20_dialog_content = "Entonces, ¿estás interesado en la carne celestita ahora?",
  ui_story_9_5_2_21_dialog_content = "¡Cuidado con tus palabras, Victoria Varaki!",
  ui_story_9_5_2_22_dialog_content = "Parece que lo estás asimilando bien.",
  ui_story_9_5_2_23_dialog_content = "Esto es solo el comienzo.",
  ui_story_9_5_2_24_dialog_content = "Sí. Se está volviendo cada vez más intrigante.",
  ui_story_9_5_2_25_dialog_content = "No olvides el pacto que hicimos.",
  ui_story_9_5_2_26_dialog_content = "¿Cómo puedo? Ya envié a más personas por Semillas.",
  ui_story_9_5_2_27_dialog_content = "Además, no olvides los que debes eliminar.",
  ui_story_9_5_2_28_dialog_content = "No seas codicioso.",
  ui_story_9_5_2_29_dialog_content = "Debemos esperar a que llegue la oportunidad.",
  ui_story_9_5_2_30_dialog_content = "<color=#e8d9bb> En lo profundo de Eraveil </color>",
  ui_story_9_5_2_31_dialog_content = "¡Nada mal, chico!",
  ui_story_9_5_2_32_dialog_content = "¡Estás mejorando en estas cosas de líder!",
  ui_story_9_5_2_33_dialog_content = "Gracias...",
  ui_story_9_5_2_X33_dialog_content = "*Tosiendo*",
  ui_story_9_5_2_34_dialog_content = "¿Qué pasa, PlayerName?",
  ui_story_9_5_2_35_option_content = "Es muy frío.",
  ui_story_9_5_2_36_dialog_content = "Toma, bebe agua caliente.",
  ui_story_9_5_2_37_dialog_content = "No esperaba que fueras tan considerado ...",
  ui_story_9_5_2_38_dialog_content = "Siempre lleva un termo para su hermana pequeña.",
  ui_story_9_5_2_39_dialog_content = "Es genial. Me acostumbre.",
  ui_story_9_5_2_40_option_content = "Nada...",
  ui_story_9_5_2_41_dialog_content = "Dame tus manos, PlayerName.",
  ui_story_9_5_2_42_dialog_content = "¡Tus manos están tan frías!",
  ui_story_9_5_2_43_dialog_content = "Estoy bien, Vice.",
  ui_story_9_5_2_44_dialog_content = "Extraño, ¿por qué hace más frío cuanto más lejos estamos?",
  ui_story_9_5_2_45_dialog_content = "¿No se supone que Eraveil es cálido?",
  ui_story_9_5_2_46_dialog_content = "...",
  ui_story_9_5_2_47_dialog_content = "¡Tengan cuidado, todos, el Darkflow se está volviendo más intenso!",
  ui_story_9_5_2_48_dialog_content = "Me temo que Eraveil se ha convertido en una guarida para los Eclipsites.",
  ui_story_9_5_2_49_dialog_content = "!",
  ui_story_9_5_2_50_dialog_content = "Eso explicaría las hordas de Eclipsites con las que nos encontramos.",
  ui_story_9_5_2_51_dialog_content = "Quizás no sea una coincidencia que Aviduz se estrellara aquí.",
  ui_story_9_5_2_52_dialog_content = "Podría ser...",
  ui_story_9_7_1_1_dialog_content = "¡Graaah!",
  ui_story_9_7_1_2_dialog_content = "Vamos, ¿más bichos?",
  ui_story_9_7_1_3_dialog_content = "¡Está bien! ¡Genial!",
  ui_story_9_7_1_4_dialog_content = "¿Qué estás haciendo, Bopper?",
  ui_story_9_7_1_5_dialog_content = "Buscando objetos de valor.",
  ui_story_9_7_1_6_dialog_content = "¿Por qué estás rebuscando entre las sobras?",
  ui_story_9_7_1_7_dialog_content = "¡Estos no son mensajes para el bloc de notas, jefe!",
  ui_story_9_7_1_8_dialog_content = "¡Esta pieza es perfecta para Lepidoz!",
  ui_story_9_7_1_9_dialog_content = "Y nunca había visto este tornillo antes ... ¡Tengo que mostrárselo a Tiny One!",
  ui_story_9_7_1_10_dialog_content = "Y mira esto, ¡he recolectado luciérnagas en rojo, amarillo, azul y verde!",
  ui_story_9_7_1_11_dialog_content = "Buen trabajo, Bopper.",
  ui_story_9_7_1_12_dialog_content = "¡Ni siquiera me di cuenta de que había tantas cosas interesantes aquí!",
  ui_story_9_7_1_13_dialog_content = "Oh, hay más ...",
  ui_story_9_7_1_14_dialog_content = "¿Qué son estos, PlayerName?",
  ui_story_9_7_1_15_dialog_content = "Piezas de Colossus, pero no de Aviduz ...",
  ui_story_9_7_1_16_dialog_content = "¿Entonces se separaron de otros Colossi?",
  ui_story_9_7_1_17_dialog_content = "¿Esa noche hace 17 años?",
  ui_story_9_7_1_18_dialog_content = "A juzgar por el daño que les hicieron, fue una pura atrocidad.",
  ui_story_9_7_1_19_dialog_content = "...",
  ui_story_9_7_1_20_dialog_content = "Lo siento. Pensé que era un desperdicio dejarlos aquí.",
  ui_story_9_7_1_21_dialog_content = "Pero si PlayerName lo encuentra ofensivo, no aceptaré ninguno de ellos ...",
  ui_story_9_7_1_22_dialog_content = "No me importa, Bopper.",
  ui_story_9_7_1_23_dialog_content = "Estoy seguro de que querrían un hogar y alguien que los apreciara.",
  ui_story_9_7_1_24_dialog_content = "¿En serio? ¡Gracias, PlayerName!",
  ui_story_9_7_1_25_dialog_content = "¡Bopper!",
  ui_story_9_7_1_26_dialog_content = "Pero PlayerName ya dijo que está bien ...",
  ui_story_9_7_1_27_dialog_content = "No sabemos hasta dónde nos queda llegar y en cuántas peleas nos meteremos.",
  ui_story_9_7_1_28_dialog_content = "Tienes que aprender a elegir tu lugar.",
  ui_story_9_7_1_29_dialog_content = "Bien...",
  ui_story_9_7_1_30_dialog_content = "¿Puedo quedarme con este?",
  ui_story_9_7_1_31_dialog_content = "Claro, es lo suficientemente pequeño.",
  ui_story_9_7_1_32_dialog_content = "!",
  ui_story_9_7_1_33_dialog_content = "¿Reconoces esto, Carleen?",
  ui_story_9_7_1_34_dialog_content = "Es una insignia de <color=#FFB400> Guardia Lumo </color> ... Pero, ¿cómo llegó aquí?",
  ui_story_9_7_1_35_dialog_content = "¿Dónde encontraste esto, Bopper?",
  ui_story_9_7_1_36_dialog_content = "La encrucijada donde nos saltaron los Eclipsites.",
  ui_story_9_7_1_37_dialog_content = "¿Puedo verlo?",
  ui_story_9_7_1_38_dialog_content = "Seguro.",
  ui_story_9_7_1_39_option_content = "Escaneo psíquico",
  ui_story_9_7_1_40_dialog_content = "¡Por fin llevo la insignia!",
  ui_story_9_7_1_41_dialog_content = "¿Estás viendo esto, madre?",
  ui_story_9_7_1_42_dialog_content = "¡Su hijo ahora es un Guardia Lumo certificable!",
  ui_story_9_7_1_43_dialog_content = "¡Ya no tengo que servir a los cascarrabias de Zona residencial!",
  ui_story_9_7_1_44_dialog_content = "Pero te has ido ahora ...",
  ui_story_9_7_1_45_dialog_content = "¿Por qué te distraes como un idiota? ¡Ve a luchar contra los Eclipsites!",
  ui_story_9_7_1_46_dialog_content = "¡Sí!",
  ui_story_9_7_1_47_dialog_content = "¡Gahhhhhh!",
  ui_story_9_7_1_48_dialog_content = "¡Bendíceme y protégeme, madre!",
  ui_story_9_7_1_49_dialog_content = "¿Dónde estoy...?",
  ui_story_9_7_1_50_dialog_content = "(Hablando en eclipsiano) Estos son los cautivos de Lumopolis, mi señora.",
  ui_story_9_7_1_51_dialog_content = "(Hablando en eclipsiano) Bien hecho.",
  ui_story_9_7_1_52_dialog_content = "¿Eclipsites? ¿Qué me estás haciendo?",
  ui_story_9_7_1_53_dialog_content = "¡Déjame ir!",
  ui_story_9_7_1_54_dialog_content = "No tengas miedo, no te dolerá en absoluto.",
  ui_story_9_7_1_55_dialog_content = "¡No te acerques! ¡Quédate donde estás!",
  ui_story_9_7_1_56_dialog_content = "¡Arrgh!",
  ui_story_9_7_1_57_dialog_content = "!",
  ui_story_9_7_1_58_dialog_content = "¿Qué viste, PlayerName?",
  ui_story_9_7_1_59_dialog_content = "Yo vi...",
  ui_story_9_7_1_60_option_content = "Un guardia.",
  ui_story_9_7_1_61_dialog_content = "Esta insignia pertenecía a un Guardia Lumo.",
  ui_story_9_7_1_62_dialog_content = "!",
  ui_story_9_7_1_63_dialog_content = "Fue lanzado a la batalla inmediatamente después de unirse a la Guardia.",
  ui_story_9_7_1_64_dialog_content = "Pero al final se convirtió en un Eclipsite.",
  ui_story_9_7_1_65_option_content = "Una Eclipsite.",
  ui_story_9_7_1_66_dialog_content = "Esta insignia pertenecía a un Eclipsite.",
  ui_story_9_7_1_67_dialog_content = "¡Imposible!",
  ui_story_9_7_1_68_dialog_content = "Pero el Eclipsite solía ser un Guardia Lumo.",
  ui_story_9_7_1_69_dialog_content = "¿Puedes explicármelo otra vez? ¿Es una guardia o una Eclipsite?",
  ui_story_9_7_1_70_dialog_content = "Alguien obligó a este guardia a transformarse en un Eclipsite ...",
  ui_story_9_7_1_71_dialog_content = "Y sé exactamente quién era: ¡<color=#FFB400>Forsakin</color>!",
  ui_story_9_7_1_72_dialog_content = "¿La figura misteriosa junto a Schummer?",
  ui_story_9_7_1_73_dialog_content = "¡Sí! ¿Aún recuerdas la Semilla que me sacaste, Vice?",
  ui_story_9_7_1_74_dialog_content = "Sí, ¡casi te convierte en un Eclipsite!",
  ui_story_9_7_1_75_dialog_content = "¿Wow en serio?",
  ui_story_9_7_1_76_dialog_content = "Vi a Forsakin forzando a la Semilla a entrar en el cuerpo del guardia.",
  ui_story_9_7_1_77_dialog_content = "!",
  ui_story_9_7_1_78_dialog_content = "Y un hombre con un maletín blanco decía ...",
  ui_story_9_7_1_79_dialog_content = "La Semilla es la única forma de convertir a otras criaturas en Eclipsites.",
  ui_story_9_7_1_80_dialog_content = "¿Quieres decir que ese tipo Forsakin convirtió a un Guardia Lumo en un Eclipsite?",
  ui_story_9_7_1_81_dialog_content = "Sí.",
  ui_story_9_7_1_82_dialog_content = "¿Entonces el Eclipsite que acabamos de matar era un guardia de Lumopolis?",
  ui_story_9_7_1_83_dialog_content = "Sí...",
  ui_story_9_7_1_84_dialog_content = "...",
  ui_story_9_7_1_85_dialog_content = "¡Niños, dejen de culparse a sí mismos y de revolcarse en la lástima!",
  ui_story_9_7_1_86_dialog_content = "No matamos al guardia. ¡Fue ese Forsakin!",
  ui_story_9_7_1_87_dialog_content = "Sinsa tiene razón.",
  ui_story_9_7_1_88_dialog_content = "Aunque matamos a este guardia a mano ...",
  ui_story_9_7_1_89_dialog_content = "Pero si no fuera por Forsakin, no se habría convertido en un Eclipsite.",
  ui_story_9_7_1_90_dialog_content = "...",
  ui_story_9_7_1_91_dialog_content = "Sra. Carleen...",
  ui_story_9_7_1_92_dialog_content = "Creo que es mejor que te lleves la placa.",
  ui_story_9_7_1_93_dialog_content = "...Okey.",
  ui_story_9_7_1_94_dialog_content = "Yo, Carleen de Schwartz, por la presente lloro a los fallecidos.",
  ui_story_9_7_1_95_dialog_content = "Un guardia de Lumopolis, poseedor de esta insignia.",
  ui_story_9_7_1_96_dialog_content = "Sirvió bien en su puesto y luchó valientemente.",
  ui_story_9_7_1_97_dialog_content = "Aunque fue capturado, se convirtió en un Eclipsite y atacó a los Aurorians, no fue por su voluntad.",
  ui_story_9_7_1_98_dialog_content = "Perdónanos por poner fin a su sufrimiento.",
  ui_story_9_7_1_99_dialog_content = "Puede él descansar en paz. Noche Blanca en lo alto.",
  ui_story_9_7_1_100_dialog_content = "Descansen en paz...",
  ui_story_9_7_1_101_dialog_content = "...",
  ui_story_9_7_1_102_dialog_content = "Aviduz, Eraveil, Forsakin ... Todo esto es demasiado extraño.",
  ui_story_9_7_1_103_dialog_content = "Tengo un mal presentimiento sobre esto...",
  ui_story_9_7_1_104_dialog_content = "Schummer...",
  ui_story_9_7_1_105_dialog_content = "¿Quizás Schummer todavía está vivo?",
  ui_story_9_7_1_106_dialog_content = "!",
  ui_story_9_7_1_107_dialog_content = "Independientemente, ¡tenemos que ponernos en marcha rápido!",
  ui_story_9_7_1_108_dialog_content = "¡Gahhhhhh!",
  ui_story_9_7_1_109_dialog_content = "¡Cuidado, aquí viene otro!",
  ui_story_9_7_1_110_dialog_content = "¿Es un Eclipsite de alto nivel?",
  ui_story_9_7_1_111_dialog_content = "Nunca antes había visto una Eclipsite tan mutilada.",
  ui_story_9_7_1_112_dialog_content = "<anim type=Shake> Yo ... quiero ... casa ... </anim>",
  ui_story_9_7_1_113_dialog_content = "<anim type=Shake> Casa ... quiero ... ir ... </anim>",
  ui_story_9_7_1_114_dialog_content = "¿Habla Universés?",
  ui_story_9_7_1_115_dialog_content = "No tengo ni idea de lo que está tratando de decir ...",
  ui_story_9_7_1_116_dialog_content = "Siento el aura Aurorian fuera de él.",
  ui_story_9_7_1_117_dialog_content = "¿También solía ser un Aurorian?",
  ui_story_9_7_1_118_dialog_content = "!",
  ui_story_9_7_1_119_dialog_content = "Puedo sentir las fuertes emociones que está emitiendo ...",
  ui_story_9_7_1_120_dialog_content = "Dolor, desesperación, rabia, impotencia ... Todo embotellado sin liberación.",
  ui_story_9_7_1_121_dialog_content = "El pobre Aurorian solo quiere irse a casa ...",
  ui_story_9_7_1_122_dialog_content = "...",
  ui_story_9_7_1_123_dialog_content = "<anim type=Shake> ¡Gruñido! </anim>",
  ui_story_9_7_1_124_dialog_content = "Parece que no sabe que se ha transformado en una Eclipsite. No hay vuelta a casa para ti, guardia ...",
  ui_story_9_7_1_125_dialog_content = "¡Acabemos con su sufrimiento!",
  ui_story_9_7_2_1_dialog_content = "<anim type=Shake> Inicio ... Vete... a casa... </anim>",
  ui_story_9_7_2_2_dialog_content = "Noche Blanca en lo alto, que descanses en paz.",
  ui_story_9_7_2_3_dialog_content = "Ya no estás atormentado por tu forma física.",
  ui_story_9_7_2_4_dialog_content = "Lamentamos no poder liberarte ...",
  ui_story_9_7_2_5_dialog_content = "Hicimos todo lo posible para minimizar sus sufrimientos en la batalla.",
  ui_story_9_7_2_6_dialog_content = "No te culpes demasiado, PlayerName.",
  ui_story_9_7_2_X6_dialog_content = "Ahora, lo único que podemos hacer por estos Aurorians es encontrar a Forsakin y detenerla.",
  ui_story_9_7_2_7_dialog_content = "Cierto.",
  ui_story_9_7_2_8_dialog_content = "Tienes razón, ¡tenemos que encontrar a Forsakin y evitar que cree más Eclipsites!",
  ui_story_9_7_2_9_dialog_content = "¿Quién es este Forsakin? El nombre me suena a Aurorian.",
  ui_story_9_7_2_10_option_content = "Lo eres.",
  ui_story_9_7_2_11_dialog_content = "Desde la estatura física hasta el aura y los gestos, Forsakin es similar a los Aurorians.",
  ui_story_9_7_2_12_dialog_content = "Pero ella se alineó con los eclipsites.",
  ui_story_9_7_2_13_dialog_content = "Y Vivian reveló que Forsakin una vez sirvió a Illumina ...",
  ui_story_9_7_2_14_option_content = "No.",
  ui_story_9_7_2_15_dialog_content = "Forsakin podría ser una Aurorian en algún momento, pero ahora está del lado de los eclipsites.",
  ui_story_9_7_2_16_dialog_content = "Aunque Vivian dijo que una vez sirvió a Illumina ...",
  ui_story_9_7_2_17_dialog_content = "¿Vivian?",
  ui_story_9_7_2_18_dialog_content = "El Jefe de Personal de Illumina, mi superior.",
  ui_story_9_7_2_19_dialog_content = "Antes de partir, nos recordó que tuviéramos cuidado con Forsakin específicamente.",
  ui_story_9_7_2_20_dialog_content = "Ella clavó eso justo en el punto.",
  ui_story_9_7_2_21_dialog_content = "No lo entiendo. Si Forsakin realmente funcionó para Illumina ...",
  ui_story_9_7_2_22_dialog_content = "¿Cómo podía ser tan insensible?",
  ui_story_9_7_2_23_dialog_content = "Es como si estuviera obsesionada con convertir a los Aurorians en eclipsites.",
  ui_story_9_7_2_24_dialog_content = "Nunca escuché de nadie así cuando estuve en Illumina ...",
  ui_story_9_7_2_25_dialog_content = "No creo que los altos mandos de Illumina te dejen entrar en ese esqueleto en el armario.",
  ui_story_9_7_2_26_dialog_content = "Sinsa, sé que no confías en Illumina por lo que le pasó a Eve ...",
  ui_story_9_7_2_27_dialog_content = "Pero los oficiales de Illumina siempre están a la vanguardia de la batalla, dando ejemplos admirables a quienes luchan bajo sus órdenes ...",
  ui_story_9_7_2_X27_dialog_content = "Quizás han estado investigando todo este tiempo ...",
  ui_story_9_7_2_28_dialog_content = "Je... Debes ser ingenuo para seguir cayendo en esa tontería.",
  ui_story_9_7_2_29_dialog_content = "Mi hermana Eve sufrió una grave complicación tras ser atacada por eclipsites.",
  ui_story_9_7_2_30_dialog_content = "Me enamoré de la gloriosa propaganda de Illumina y tontamente la envié allí para recibir tratamiento.",
  ui_story_9_7_2_31_dialog_content = "...",
  ui_story_9_7_2_32_dialog_content = "¿Y luego qué pasó? No solo no mejoraron su condición, ¡ella casi muere en un incendio!",
  ui_story_9_7_2_33_dialog_content = "Ese fuego ...",
  ui_story_9_7_2_34_dialog_content = "!",
  ui_story_9_7_2_35_dialog_content = "Debería haber hecho la conexión antes ... Forsakin tiene cicatrices faciales de un incendio.",
  ui_story_9_7_2_36_dialog_content = "¡¿Qué dijiste?!",
  ui_story_9_7_2_37_dialog_content = "Fuego en Illumina ...",
  ui_story_9_7_2_38_dialog_content = "¡Arrgh!",
  ui_story_9_7_2_39_dialog_content = "Las cicatrices de Forsakin ...",
  ui_story_9_7_2_40_dialog_content = "Mira mi cara, estas cicatrices ... Estos fueron quemados en mi carne por llamas abrasadoras. ¿Lo ves?",
  ui_story_9_7_2_41_dialog_content = "Podría ser...",
  ui_story_9_7_2_42_dialog_content = "Déjame preguntarte algo, Sinsa ... ¿Qué pasó con la persona responsable de tratar a Eve?",
  ui_story_9_7_2_43_dialog_content = "Cuando llegué a Illumina, me dijeron que ...",
  ui_story_9_7_2_44_dialog_content = "El responsable del tratamiento experimental murió en el incendio.",
  ui_story_9_7_2_45_dialog_content = "¿Es verdad?",
  ui_story_9_7_2_46_dialog_content = "No creí que esa explicación los absolviera, por supuesto.",
  ui_story_9_7_2_47_dialog_content = "Pero se negaron a divulgar el nombre de esa persona.",
  ui_story_9_7_2_48_dialog_content = "Así que envié a mi propia gente a husmear.",
  ui_story_9_7_2_49_dialog_content = "Pero todavía no podía desenterrar nada nuevo.",
  ui_story_9_7_2_50_dialog_content = "Sin embargo, nunca olvidaré el nombre mientras viva: <color=#FFB400> Denier </color>.",
  ui_story_9_7_2_X50_dialog_content = "La información que obtuvimos antes, nos puso en el camino equivocado. Todos pensamos que el investigador murió en el incendio.",
  ui_story_9_7_2_51_dialog_content = "¡Así que no reconocimos a Forsakin la primera vez que la vimos!",
  ui_story_9_7_2_52_dialog_content = "Cierto... Pero pensando en ello ahora, me temo que Forsakin es Denier.",
  ui_story_9_7_2_53_dialog_content = "!",
  ui_story_9_7_2_54_dialog_content = "¡Arrgh!",
  ui_story_9_7_2_55_dialog_content = "Eve.",
  ui_story_9_7_2_56_dialog_content = "¡Maldita sea, voy a sacar la verdad a la parrilla de ese Forsakin!",
  ui_story_9_7_2_57_dialog_content = "¡Si hizo mal a Eve, la haré pagar!",
  ui_story_9_8_1_1_dialog_content = "<color=#e8d9bb> Dentro de la cápsula de sanación de Aviduz </color>",
  ui_story_9_8_1_2_dialog_content = "Profesor...",
  ui_story_9_8_1_3_dialog_content = "Discúlpame... Profesor... De nuevo...",
  ui_story_9_8_1_4_dialog_content = "Por qué...",
  ui_story_9_8_1_5_dialog_content = "<color=#e8d9bb> Hangar instructivo Colossus en Eraveil </color>",
  ui_story_9_8_1_6_dialog_content = "Disculpe, profesor Handro, ¿puedo intentarlo de nuevo?",
  ui_story_9_8_1_7_dialog_content = "Usaste las tres oportunidades, Schummer.",
  ui_story_9_8_1_8_dialog_content = "Lo siento, pero no pasaste la prueba para pilotar Colossus.",
  ui_story_9_8_1_9_dialog_content = "¡Pero no puedo registrarme para la selección de Navegador de Aviduz si no apruebo!",
  ui_story_9_8_1_10_dialog_content = "¡Tengo que pasar esta prueba!",
  ui_story_9_8_1_11_dialog_content = "Entiendo cómo te sientes, Schummer.",
  ui_story_9_8_1_12_dialog_content = "Eres una de mis estudiantes más talentosas y realmente quiero que estés en la selección.",
  ui_story_9_8_1_13_dialog_content = "Pero ya sea una prueba o la selección en sí, debe ser justa.",
  ui_story_9_8_1_14_dialog_content = "¡Estoy lista para la prueba, profesor Handro! ¿Podemos empezar ahora?",
  ui_story_9_8_1_15_dialog_content = "Bien, ahora voy.",
  ui_story_9_8_1_16_dialog_content = "Me complace lo duro que trabaja, Schummer.",
  ui_story_9_8_1_17_dialog_content = "¡Creo que si sigues practicando, tus habilidades psíquicas mejorarán a pasos agigantados!",
  ui_story_9_8_1_18_dialog_content = "¡Y no tengo ninguna duda de que serás elegida para pilotar Aviduz la próxima vez!",
  ui_story_9_8_1_19_dialog_content = "¿Pero cuándo será eso ...?",
  ui_story_9_8_1_20_dialog_content = "...",
  ui_story_9_8_1_21_dialog_content = "No vas a ver ese día, ¡ya que la última selección fue hace varias décadas!",
  ui_story_9_8_1_X1_dialog_content = "(Cállate mujer... ¿Recuerdas que ahora tienes una hija? ¿Solo porque voy a participar en la selección?)",
  ui_story_9_8_1_X2_dialog_content = "Schummer, aunque llegaste en primer lugar en la última prueba ...",
  ui_story_9_8_1_X3_dialog_content = "No puede permitirse perder el enfoque ahora. La vinculación con un Colossus es diferente a las otras pruebas. Tendrás que darlo todo.",
  ui_story_9_8_1_X4_dialog_content = "(Lo sé... No necesito que me lo recuerdes.)",
  ui_story_9_8_1_22_dialog_content = "¿No apruebas cada examen que haces, Schummer?",
  ui_story_9_8_1_23_dialog_content = "¿Cómo es que no puedes manejar algo tan simple como dirigir un Colossus?",
  ui_story_9_8_1_X5_dialog_content = "(Puedo hacerlo, solo espera y verás).",
  ui_story_9_8_1_X6_dialog_content = "¡Ni siquiera puede vincularse con el Colossus! ¿Eres incluso una celestita, Schummer?",
  ui_story_9_8_1_X7_dialog_content = "(¡Cállate! Crees que eres un pez gordo solo porque puedes conectarte solo un poco).",
  ui_story_9_8_1_24_dialog_content = "¿Schummer falló la prueba piloto? De ninguna manera...",
  ui_story_9_8_1_X8_dialog_content = "(Es solo otra prueba. La próxima vez...)",
  ui_story_9_8_1_X9_dialog_content = "¿Handro dijo que serías una navegadora adecuada para Aviduz?",
  ui_story_9_8_1_X10_dialog_content = "Deberías rendirte.",
  ui_story_9_8_1_X11_dialog_content = "No tienes ni el talento ni la calificación para ello ...",
  ui_story_9_8_1_X12_dialog_content = "(¡Cierra la boca! ¡Son todos idiotas! ¡No entienden nada!)",
  ui_story_9_8_1_X13_dialog_content = "(¡Un día, les mostraré a todos!)",
  ui_story_9_8_1_X14_dialog_content = "...",
  ui_story_9_8_1_25_dialog_content = "¡Ni siquiera puede vincularse con el Colossus! ¿Eres incluso una celestita, Schummer?",
  ui_story_9_8_1_26_dialog_content = "¡Por qué tú...!",
  ui_story_9_8_1_27_dialog_content = "¡Oh, mira, es Mendelson el Cobarde!",
  ui_story_9_8_1_28_dialog_content = "¿Por qué no nos dices qué tienes en mente?",
  ui_story_9_8_1_29_dialog_content = "Detente, ya es suficiente ...",
  ui_story_9_8_1_30_dialog_content = "¿Quién eres tú para decirnos qué hacer?",
  ui_story_9_8_1_31_dialog_content = "Profesor Handro...",
  ui_story_9_8_1_32_dialog_content = "¿Oh? ¿Y el profesor?",
  ui_story_9_8_1_33_dialog_content = "Yo diré...",
  ui_story_9_8_1_34_dialog_content = "¿Vas a delatar al profesor Handro? ¿Qué puedes hacer además de besarte?",
  ui_story_9_8_1_35_dialog_content = "De acuerdo, deja de hablar.",
  ui_story_9_8_1_36_dialog_content = "Está bien. ¡Vamos!",
  ui_story_9_8_1_X15_dialog_content = "¿La estás intimidando de nuevo ...? ¡Se lo diré al profesor Handro!",
  ui_story_9_8_1_37_dialog_content = "¿Estás bien?",
  ui_story_9_8_1_38_dialog_content = "¿Quién eres? ¿¡Parece que necesito tu ayuda !? ¡Métete en tus asuntos!",
  ui_story_9_8_1_39_dialog_content = "Soy Mendelson... Los vi intimidarte ...",
  ui_story_9_8_1_X16_dialog_content = "Solo pensé... que necesitabas ayuda ...",
  ui_story_9_8_1_X17_dialog_content = "¿Pensaste que los veías intimidándome, y pensaste que lo usarías como una oportunidad para venir a molestarme?",
  ui_story_9_8_1_40_dialog_content = "Solo estás tratando de manipularme. ¿Crees que esto te hace sentir mejor?",
  ui_story_9_8_1_X18_dialog_content = "¿No te hace eso igual a ellos?",
  ui_story_9_8_1_X19_dialog_content = "Cuando estás de buen humor, vienes y finges que te preocupas, y cuando estás de mal humor, ¿simplemente vienes y te ríes?",
  ui_story_9_8_1_41_dialog_content = "No, en absoluto...",
  ui_story_9_8_1_X20_dialog_content = "¿No? ¿Entonces por qué?",
  ui_story_9_8_1_42_dialog_content = "¿Por qué me ayudarías?",
  ui_story_9_8_1_43_dialog_content = "Yo... Sé que estaban equivocados ...",
  ui_story_9_8_1_44_dialog_content = "(Por supuesto, se equivocan ...)",
  ui_story_9_8_1_45_dialog_content = "(Creen que son tan grandes ...)",
  ui_story_9_8_1_46_dialog_content = "¿Qué estás haciendo aquí sola, Schummer?",
  ui_story_9_8_1_47_dialog_content = "!",
  ui_story_9_8_1_48_dialog_content = "¡Es la Schummer que no puede pilotar un Colossus!",
  ui_story_9_8_1_49_dialog_content = "¿Estás intentando conectarte con un Colossus? ¡Qué diligente!",
  ui_story_9_8_1_50_dialog_content = "Vamos, dejémosla en paz ...",
  ui_story_9_8_1_51_dialog_content = "Espera un minuto, tengo una idea.",
  ui_story_9_8_1_52_dialog_content = "¿Qué tal si hacemos una apuesta?",
  ui_story_9_8_1_53_dialog_content = "¿Qué quieres apostar?",
  ui_story_9_8_1_54_dialog_content = "Schummer, ¿tienes las agallas para salir de Eraveil con nosotros?",
  ui_story_9_8_1_X21_dialog_content = "¿Ah? ¿No es eso lo que estábamos planeando la última vez ...?",
  ui_story_9_8_1_X22_dialog_content = "¡Jaja! Mira a Schummer, ni siquiera se atreve a levantar la cabeza. Quizás ella te tiene miedo ...",
  ui_story_9_8_1_55_dialog_content = "Dime si primero tienes las agallas.",
  ui_story_9_8_1_56_dialog_content = "¡Adelante!",
  ui_story_9_8_1_57_dialog_content = "Quizás puedas enlazar con Colossus, pero ¿te atreves a llevar uno fuera de Eraveil?",
  ui_story_9_8_1_58_dialog_content = "Como dije la última vez... El Profesor Handro nos dijo que es peligroso ahí fuera por los Eclipsites.",
  ui_story_9_8_1_59_dialog_content = "¿Así que tienes miedo?",
  ui_story_9_8_1_60_dialog_content = "¿A qué le temes? ¡Salgamos con el Colossus!",
  ui_story_9_8_1_61_dialog_content = "Ganas si puedes hacer un viaje de ida y vuelta en un Colossus.",
  ui_story_9_8_1_62_dialog_content = "¡Lo tendrás cuando ganemos!",
  ui_story_9_8_1_63_dialog_content = "¡Tomemos al Aprendiz I!",
  ui_story_9_8_1_64_dialog_content = "¿Seguro que no me atraparán?",
  ui_story_9_8_1_65_dialog_content = "¡No te preocupes, el profesor Handro te ve como el próximo Navegador de Aviduz!",
  ui_story_9_8_1_66_dialog_content = "!",
  ui_story_9_8_1_67_dialog_content = "Así es, ¡creemos en tus habilidades!",
  ui_story_9_8_1_68_dialog_content = "Aún si te atrapan, ¡nadie te culpará!",
  ui_story_9_8_1_69_dialog_content = "Okay... Pero sólo esta vez.",
  ui_story_9_8_1_70_dialog_content = "Muy bien, ¡despegamos!",
  ui_story_9_8_1_X23_dialog_content = "Schummer, ¿vienes o qué?",
  ui_story_9_8_1_X24_dialog_content = "¡Apuesto a que no! ¡Apuesto tres libros a ello!",
  ui_story_9_8_1_71_dialog_content = "(Aviduz... es mío...)",
  ui_story_9_8_1_72_dialog_content = "(No entiendes nada... Así que...)",
  ui_story_9_8_1_73_dialog_content = "<color=#e8d9bb>Fuera de Eraveil</color>",
  ui_story_9_8_1_74_dialog_content = "¡Colossus no se mueve!",
  ui_story_9_8_1_75_dialog_content = "...",
  ui_story_9_8_1_76_dialog_content = "¡Eclipsites están derribando la puerta!",
  ui_story_9_8_1_77_dialog_content = "¿Qué hacemos ahora?",
  ui_story_9_8_1_78_dialog_content = "¡Tsk!",
  ui_story_9_8_1_79_dialog_content = "¡No puedo creer que las presas se entregaran a mí!",
  ui_story_9_8_1_X25_dialog_content = "(Todos están mejor muertos.)",
  ui_story_9_8_1_80_dialog_content = "¡Debemos luchar!",
  ui_story_9_8_1_81_dialog_content = "¡Agh!",
  ui_story_9_8_1_82_dialog_content = "Bastardillos estúpidos. Pude haber sido tolerante contigo.",
  ui_story_9_8_1_83_dialog_content = "Err...",
  ui_story_9_8_1_84_dialog_content = "Oh...",
  ui_story_9_8_1_85_dialog_content = "¿Es así?",
  ui_story_9_8_1_86_dialog_content = "Eso fue sólo una pequeña prueba. Odio cuando mueren sin permiso.",
  ui_story_9_8_1_87_dialog_content = "...",
  ui_story_9_8_1_88_dialog_content = "¿Eso es todo lo que puedes tomar? Todo lo que necesito es apretar mi agarre para aplastar tus huesos.",
  ui_story_9_8_1_89_dialog_content = "¡Tomaré tus huesos como mi trofeo y los usaré como un collar!",
  ui_story_9_8_1_90_dialog_content = "...",
  ui_story_9_8_1_91_dialog_content = "(Escapar... ¿Cómo... puedo escapar...?)",
  ui_story_9_8_1_X91_dialog_content = "Ugh...",
  ui_story_9_8_1_92_dialog_content = "¿Ah? ¿Quieres decir que hay una criaturita oculta en las ruinas?",
  ui_story_9_8_1_X92_dialog_content = "Tsk, tsk, tsk... Qué interesante.",
  ui_story_9_8_1_X26_dialog_content = "(¡...!)",
  ui_story_9_8_1_S1_dialog_content = "¡Quédate donde estás!",
  ui_story_9_8_1_X27_dialog_content = "Cállate... Tengo buenas noticias para ti.",
  ui_story_9_8_1_X28_dialog_content = "¿Te gustaría escucharla?",
  ui_story_9_8_1_X29_dialog_content = "... ¿Sabes hablar Universés?",
  ui_story_9_8_1_S2_dialog_content = "¡Tsk! ¿Todavía piensas en cosas así ahora? ¿No temes que te mate?",
  ui_story_9_8_1_S3_dialog_content = "... Lo estoy.",
  ui_story_9_8_1_X30_dialog_content = "¡Tsk, tsk, tsk! Entonces escucha y no olvides ni una palabra.",
  ui_story_9_8_1_93_dialog_content = "La Gran Madre ha decretado que los Celestitas serán completamente erradicados en el día del Juicio.",
  ui_story_9_8_1_94_dialog_content = "¡Es el juicio final contra los Celestitas, y el final feliz concedido por la Madre!",
  ui_story_9_8_1_95_dialog_content = "¡Así que, celebra el hecho de que serás testigo del momento histórico!",
  ui_story_9_8_1_96_dialog_content = "... ¿¡Q-qué!?",
  ui_story_9_8_1_97_dialog_content = "¡No tienes derecho a hacer preguntas!",
  ui_story_9_8_1_98_dialog_content = "¡Los débiles merecen la muerte!",
  ui_story_9_8_1_99_dialog_content = "Al igual que tus amiguitos, contorsionados en bolitas y pereciendo de dolor.",
  ui_story_9_8_1_100_dialog_content = "¡...!",
  ui_story_9_8_1_101_dialog_content = "Tsk, tsk... Pero no te preocupes. He decidido seleccionarte. He decidido darte una oportunidad.",
  ui_story_9_8_1_102_dialog_content = "¡Te concederé el poder de superar a los Celestitas! ¡Te concederé la oportunidad de olvidar tu patética existencia!",
  ui_story_9_8_1_103_dialog_content = "Olvidar...",
  ui_story_9_8_1_104_dialog_content = "¿No apruebas cada examen que haces, Schummer?",
  ui_story_9_8_1_105_dialog_content = "¿Cómo es que no puedes manejar algo tan simple como dirigir un Colossus?",
  ui_story_9_8_1_106_dialog_content = "¿Schummer falló la prueba piloto? De ninguna manera...",
  ui_story_9_8_1_107_dialog_content = "¡Ni siquiera puede vincularse con el Colossus! ¿Eres incluso una celestita, Schummer?",
  ui_story_9_8_1_108_dialog_content = "¿Seguro que no me atraparán?",
  ui_story_9_8_1_109_dialog_content = "¡No te preocupes, el profesor Handro te ve como el próximo Navegador de Aviduz!",
  ui_story_9_8_1_110_dialog_content = "¿Ves esta semilla? Esta es tu esperanza.",
  ui_story_9_8_1_111_dialog_content = "Mi... esperanza...",
  ui_story_9_8_1_112_dialog_content = "Excelente. Puedo sentir tu deseo de poder.",
  ui_story_9_8_1_113_dialog_content = "Poder.",
  ui_story_9_8_1_114_dialog_content = "¿Qué haces, Schummer...?",
  ui_story_9_8_1_115_dialog_content = "Sí, ¡sólo convirtiéndote en hija de la Madre puedes vivir!",
  ui_story_9_8_1_116_dialog_content = "Debo vivir...",
  ui_story_9_8_1_117_dialog_content = "¡Ya no serás débil ni conocerás el miedo!",
  ui_story_9_8_1_118_dialog_content = "Acepta este regalo, sé más fuerte... ¡y únete a nosotros!",
  ui_story_9_8_1_119_dialog_content = "¡Gobernarás el mundo... gobernarás todo!",
  ui_story_9_8_1_120_dialog_content = "Gobernar... todo...",
  ui_story_9_8_1_121_dialog_content = "No lo hagas, Schummer...",
  ui_story_9_8_1_122_dialog_content = "Sí, eso es. Ven.",
  ui_story_9_8_1_123_dialog_content = "No... Por favor, te ruego...",
  ui_story_9_8_1_124_dialog_content = "...",
  ui_story_9_8_1_125_dialog_content = "¿Qué pasa?",
  ui_story_9_8_1_126_dialog_content = "Yo...",
  ui_story_9_8_1_127_dialog_content = "¡Levanta la navaja!",
  ui_story_9_8_1_128_dialog_content = "Yo...",
  ui_story_9_8_1_129_dialog_content = "¡No lo dudes! ¡No pruebes mi paciencia! ¿¡Qué estás esperando!?",
  ui_story_9_8_1_130_dialog_content = "Me convertiré en un Eclipsite... ¿Verdad?",
  ui_story_9_8_1_131_dialog_content = "Olvídalo...",
  ui_story_9_8_1_132_dialog_content = "¡Agh!",
  ui_story_9_8_1_133_dialog_content = "¡Tú!",
  ui_story_9_8_1_134_dialog_content = "La odias, ¿verdad?",
  ui_story_9_8_1_135_dialog_content = "...",
  ui_story_9_8_1_136_dialog_content = "¿No deberías agradecerme por matarla?",
  ui_story_9_8_1_137_dialog_content = "¿Me matarás a mí también?",
  ui_story_9_8_1_138_dialog_content = "¿Por qué lo haría?",
  ui_story_9_8_1_139_dialog_content = "Puedo ver que eres diferente a ellos. Tienes el potencial para ser grande.",
  ui_story_9_8_1_140_dialog_content = "Por supuesto. Si te conviertes en un Eclipsite, obtendrás el poder de superar a los Celestitas, ¡e incluso a los Aurorians!",
  ui_story_9_8_1_141_dialog_content = "Pero. ¿Qué clase de poder es ese?",
  ui_story_9_8_1_142_dialog_content = "Una bendición de la Madre que alimenta al mundo, un regalo muy apreciado que cualquiera podría recibir.",
  ui_story_9_8_1_143_dialog_content = "Vivirás, sin temer nada.",
  ui_story_9_8_1_144_dialog_content = "Te refieres a. ¿Sólo puedo vivir si lo acepto...?",
  ui_story_9_8_1_145_dialog_content = "Por supuesto. Puedes sobrevivir a este valle en el que estamos.",
  ui_story_9_8_1_146_dialog_content = "¿Y nunca más seré débil?",
  ui_story_9_8_1_147_dialog_content = "Por supuesto. Sólo \"formidable\" podría usarse para describirte en adelante.",
  ui_story_9_8_1_S147_dialog_content = "¿Aceptarlo... y estaré calificada para poseer el Aviduz?",
  ui_story_9_8_1_S148_dialog_content = "¿Aviduz? ¿Eso es un Colossus?",
  ui_story_9_8_1_S149_dialog_content = "Tsk, tsk, tsk... Dime, ¿qué tipo de Colossus deseas?",
  ui_story_9_8_1_S150_dialog_content = "Aviduz... es el Colossus más poderoso que existe. Sólo el Celestita más fuerte... tiene derecho a comandarlo.",
  ui_story_9_8_1_S151_dialog_content = "¡Tsk, tsk, tsk! ¡Entonces estarás más capacitada para comandarlo que cualquier otro Celestita! ¡Y tú los superarás a todos!",
  ui_story_9_8_1_148_dialog_content = "...",
  ui_story_9_8_1_149_dialog_content = "Yo...",
  ui_story_9_8_1_150_dialog_content = "Acepto.",
  ui_story_9_8_1_151_dialog_content = "¡Tsk!",
  ui_story_9_8_1_152_dialog_content = "¡Oh...!",
  ui_story_9_8_1_153_dialog_content = "¡Has ganado otra sirviente, gran Madre!",
  ui_story_9_8_1_154_dialog_content = "¿Me has dado poder?",
  ui_story_9_8_1_155_dialog_content = "Porque no me siento diferente...",
  ui_story_9_8_1_156_dialog_content = "Schummer... Ese es tu nombre, ¿cierto?",
  ui_story_9_8_1_157_dialog_content = "Ten esto en mente, Schummer, nunca dudes de la Madre. Debes aprender a ser paciente.",
  ui_story_9_8_1_158_dialog_content = "...",
  ui_story_9_8_1_159_dialog_content = "¿A dónde me llevas ahora?",
  ui_story_9_8_1_160_dialog_content = "No vamos a ninguna parte, Schummer. Quiero que vuelvas a Eraveil. Conmigo, claro.",
  ui_story_9_8_1_161_dialog_content = "¿Regreso a Eraveil?",
  ui_story_9_8_1_162_dialog_content = "¿Olvidaste que Aviduz sigue esperándote allí?",
  ui_story_9_8_1_163_dialog_content = "¡No serás completa e invencible hasta que tengas a Aviduz!",
  ui_story_9_8_1_164_dialog_content = "No lo olvidé. Es que no soy como los otros.",
  ui_story_9_8_1_165_dialog_content = "Yo... no puedo enlazar con ningún Colossus. Pensé que podría esperar hasta que todo esto pasara.",
  ui_story_9_8_1_166_dialog_content = "¿Qué, un Celestita que no puede enlazar con Colossus?",
  ui_story_9_8_1_167_dialog_content = "¡Cállate! ¡No quiero escucharlo!",
  ui_story_9_8_1_168_dialog_content = "No importa, la Semilla ya se está apoderando de ti.",
  ui_story_9_8_1_169_dialog_content = "Ya no eres una Celestita a partir de este momento.",
  ui_story_9_8_1_170_dialog_content = "Intenta iniciar el Colossus ahora.",
  ui_story_9_8_1_171_dialog_content = "...Okey.",
  ui_story_9_8_1_172_dialog_content = "¡No puede ser real...!",
  ui_story_9_8_1_173_dialog_content = "Yo no perdí... ¡Yo no perdí...!",
  ui_story_9_8_1_174_dialog_content = "¡Schummer!",
  ui_story_9_8_1_175_dialog_content = "¡¡¡Mírame a los ojos antes de morir!!!",
  ui_story_9_8_1_176_dialog_content = "No, no...",
  ui_story_9_8_1_177_dialog_content = "¡No!",
  ui_story_9_9_1_1_dialog_content = "¡Cuidado con los pies, todos!",
  ui_story_9_9_1_2_dialog_content = "¿Qué está pasando?",
  ui_story_9_9_1_3_dialog_content = "<color=#e8d9bb>lamento—lamento—lamento—</color>",
  ui_story_9_9_1_4_dialog_content = "Escucho mucho sonido...",
  ui_story_9_9_1_5_dialog_content = "¿Te refieres a que el suelo tiembla?",
  ui_story_9_9_1_6_dialog_content = "No, es... es Aviduz, sollozando y lamentándose...",
  ui_story_9_9_1_7_dialog_content = "<color=#e8d9bb>lamento—lamento—lamento—</color>",
  ui_story_9_9_1_8_dialog_content = "(Es... el lamento de Colossus... Parece que aún los Colossus que una vez fueron enterrados aquí se lamentan...)",
  ui_story_9_9_1_9_dialog_content = "<color=#e8d9bb><anim type=Shake>lamento—lamento—lamento—</anim></color>",
  ui_story_9_9_1_10_dialog_content = "(Es como un cuchillo que atraviesa mi corazón...)",
  ui_story_9_9_1_11_dialog_content = "(Siento líquido caliente fluyendo...)",
  ui_story_9_9_1_12_dialog_content = "¿Lágrimas?",
  ui_story_9_9_1_13_dialog_content = "PlayerName...",
  ui_story_9_9_1_14_dialog_content = "PlayerName... ¿Estás llorando?",
  ui_story_9_9_1_15_dialog_content = "PlayerName...",
  ui_story_9_9_1_16_dialog_content = "No es nada... Sólo... pensé en Soroz por un momento.",
  ui_story_9_9_1_X16_dialog_content = "PlayerName...",
  ui_story_9_9_1_17_dialog_content = "Vice.",
  ui_story_9_9_1_18_dialog_content = "¿Percibiste algo? ¡Estamos aquí si nos necesitas!",
  ui_story_9_9_1_19_dialog_content = "Por favor, toma esto, si no te importa.",
  ui_story_9_9_1_20_dialog_content = "¿Mm...?",
  ui_story_9_9_1_21_dialog_content = "Un pañuelo para secarte las lágrimas, PlayerName.",
  ui_story_9_9_1_22_dialog_content = "Lo siento, no sé por qué...",
  ui_story_9_9_1_23_dialog_content = "No tienes que disculparte, PlayerName.",
  ui_story_9_9_1_24_dialog_content = "Las lágrimas no son sólo para débiles. A veces necesitamos desahogarnos.",
  ui_story_9_9_1_25_dialog_content = "Está bien...",
  ui_story_9_9_1_26_dialog_content = "¿Qué percibiste, niño?",
  ui_story_9_9_1_27_dialog_content = "Escuché los lamentos de los Colossus, una ola tras otra.",
  ui_story_9_9_1_28_dialog_content = "Sonaba como un duelo, como si alguien estuviera de luto por el fallecimiento de sus seres queridos ...",
  ui_story_9_9_1_29_dialog_content = "Sentí sus penas ... como si fueran las mías.",
  ui_story_9_9_1_30_dialog_content = "¿Hay otros Colossus alrededor?",
  ui_story_9_9_1_31_dialog_content = "No lo creo. Esos sonidos que escuché, no eran reales...",
  ui_story_9_9_1_32_dialog_content = "Lo que oí fueron sus pensamientos prolongados.",
  ui_story_9_9_1_33_dialog_content = "¿Pero por qué ahora?",
  ui_story_9_9_1_34_dialog_content = "...",
  ui_story_9_9_1_35_dialog_content = "¿Aún puedes percibir a Aviduz, PlayerName?",
  ui_story_9_9_1_36_dialog_content = "El Darkflow se hace más denso en Eraveil.",
  ui_story_9_9_1_37_dialog_content = "Apenas puedo sentir la presencia del debilitado Aviduz.",
  ui_story_9_9_1_38_dialog_content = "Pero ahora, no recibo nada.",
  ui_story_9_9_1_39_dialog_content = "Envidio tu poder de percibir Colossus, PlayerName.",
  ui_story_9_9_1_40_dialog_content = "Es el talento innato de Celestitas, así como puedes usar Lumina para luchar.",
  ui_story_9_9_1_41_dialog_content = "De hecho, tengo curiosidad...",
  ui_story_9_9_1_42_dialog_content = "¿Qué se siente al enlazar con un Colossus?",
  ui_story_9_9_1_43_dialog_content = "¿Qué se siente?",
  ui_story_9_9_1_44_dialog_content = "Sabes, no sé cómo responder a eso.",
  ui_story_9_9_1_45_dialog_content = "(Me acostumbré a tener a Soroz cerca durante 17 años.)",
  ui_story_9_9_1_46_dialog_content = "(Pero si no puedo volver a enlazar con Soroz...)",
  ui_story_9_9_1_47_dialog_content = "Está bien si no te sientes cómodo hablando de ello, PlayerName.",
  ui_story_9_9_1_48_dialog_content = "Estoy bien, no es cuestión de si estoy cómodo.",
  ui_story_9_9_1_49_dialog_content = "Sino que me he dado cuenta de que nunca me he planteado el tema.",
  ui_story_9_9_1_50_dialog_content = "Creo sentirme seguro y cálido cuando enlazo con un Colossus.",
  ui_story_9_9_1_51_dialog_content = "Es un confidente que siempre sabe lo que estás pensando.",
  ui_story_9_9_1_52_dialog_content = "Y tú eres el único que lo entiende.",
  ui_story_9_9_1_53_dialog_content = "Claro que a veces pensarás que es molesto con tanto fastidio.",
  ui_story_9_9_1_54_dialog_content = "Pero cuando cese, también lo extrañarás.",
  ui_story_9_9_1_55_dialog_content = "Diría que enlazar con un Colossus es una feliz sensación.",
  ui_story_9_9_1_56_dialog_content = "Feliz sensación...",
  ui_story_9_9_1_57_dialog_content = "Me gustaría saber qué piensa Lepidoz también.",
  ui_story_9_9_1_58_dialog_content = "¿Este Lepidoz del que hablas es un Colossus?",
  ui_story_9_9_1_59_dialog_content = "¡Lepidoz es el orgullo de Rediesel Wrench!",
  ui_story_9_9_1_60_dialog_content = "Hallamos un casco semienterrado en el desierto de Rediesel.",
  ui_story_9_9_1_61_dialog_content = "Excavamos y vimos que era un Colossus hecho trizas.",
  ui_story_9_9_1_62_dialog_content = "Nuestros técnicos pasaron mucho tiempo armándolo de nuevo.",
  ui_story_9_9_1_63_dialog_content = "Pero Lepidoz sólo deja que Bopper lo pilotee.",
  ui_story_9_9_1_64_dialog_content = "Con cualquier otro, ni siquiera se inmutaría.",
  ui_story_9_9_1_65_dialog_content = "Me llevó mucho tiempo aprender a pilotear Lepidoz.",
  ui_story_9_9_1_66_dialog_content = "¿Pudiste pilotearlo sin conectarte?",
  ui_story_9_9_1_67_dialog_content = "Sí. No sé cómo, tampoco.",
  ui_story_9_9_1_68_dialog_content = "Pero a veces me parece que sé lo que siente Lepidoz.",
  ui_story_9_9_1_69_dialog_content = "Cuando lo vimos por primera vez, probablemente se sintió muy solo y perdido.",
  ui_story_9_9_1_70_dialog_content = "Pero el hecho de no saber lo que piensa no me impide hablar con él todos los días.",
  ui_story_9_9_1_71_dialog_content = "Ahora, ¡ama su vida como Rediesel Wrench!",
  ui_story_9_9_1_72_dialog_content = "Conectarse o no, no le importa a Bopper.",
  ui_story_9_9_1_73_dialog_content = "¡La destreza de pilotaje que tiene ahora mismo es suficiente!",
  ui_story_9_9_1_74_dialog_content = "Nunca esperaría ver forajidos del desierto tener un Colossus propio.",
  ui_story_9_9_1_75_dialog_content = "Hay muchas cosas que no se esperan en el mundo real, princesa.",
  ui_story_9_9_1_76_dialog_content = "Es bueno salir del castillo de vez en cuando.",
  ui_story_9_9_1_77_dialog_content = "...",
  ui_story_9_9_1_78_dialog_content = "¡Cuidado atrás de ti!",
  ui_story_9_9_1_79_dialog_content = "¿Podría ser... más Eclipsites que solían ser Aurorians?",
  ui_story_9_9_1_80_dialog_content = "Pero, ¿tantos...? Hay demasiados de ellos...",
  ui_story_9_9_1_81_dialog_content = "Sin duda, los guardias de Lumopolis que venían a investigar fueron capturados y utilizados como sujetos de prueba.",
  ui_story_9_9_1_82_dialog_content = "!",
  ui_story_9_9_1_83_dialog_content = "¡PlayerName, dame tus órdenes! Acabemos con ellos lo antes posible, antes de que sientan dolor.",
  ui_story_9_13_1_1_dialog_content = "Noche Blanca en lo alto, que descansen en paz.",
  ui_story_9_13_1_2_dialog_content = "Descansen en paz...",
  ui_story_9_13_1_3_dialog_content = "¿Cuánto falta, PlayerName?",
  ui_story_9_13_1_4_dialog_content = "La señal es débil, pero Aviduz debería estar por aquí.",
  ui_story_9_13_1_X4_dialog_content = "¿En qué dirección? ¿Izquierda? ¿Derecha? ¿Enfrente?",
  ui_story_9_13_1_5_dialog_content = "¡Gahhhhhh!",
  ui_story_9_13_1_6_dialog_content = "¡Hay un enorme enjambre de Eclipsites cargando frente a nosotros!",
  ui_story_9_13_1_7_dialog_content = "PlayerName, ¡dime por dónde ir y te abriré un camino!",
  ui_story_9_13_2_1_dialog_content = "Veo uno, en la nuca de ese Eclipsite muerto allá.",
  ui_story_9_13_2_2_dialog_content = "¡Es increíble lo asqueroso que es este Eclipsite! No sé ni por dónde empezar.",
  ui_story_9_13_2_3_dialog_content = "¿Podrías ayudar a Pact a salir, Nails?",
  ui_story_9_13_2_4_dialog_content = "...",
  ui_story_9_13_2_5_dialog_content = "Por favor, perdóname, gran Señor de La Verdad.",
  ui_story_9_13_2_6_dialog_content = "La doctrina prohíbe tocar cualquier cosa impura.",
  ui_story_9_13_2_7_dialog_content = "Pero para buscar tus rastros, debo ver lo que no debo ver, tocar lo que no debo tocar.",
  ui_story_9_13_2_8_dialog_content = "Me bañaré durante 3 días en expiación tras de mi regreso.",
  ui_story_9_13_2_9_dialog_content = "...",
  ui_story_9_13_2_10_dialog_content = "Por favor, dáselo al Maletín Blanco.",
  ui_story_9_13_2_11_dialog_content = "<color=#e8d9bb>¡Whoosh!</color>",
  ui_story_9_13_2_12_dialog_content = "¿Por qué alimentaría la Semilla al Maletín Blanco?",
  ui_story_9_13_2_X12_dialog_content = "Al Maletín Blanco parece gustarle esas cosas... ¿Qué debemos hacer si no quiere vomitar después?",
  ui_story_9_13_2_X13_dialog_content = "Deja que Nails se lo quede ya que está interesado.",
  ui_story_9_13_2_X14_dialog_content = "...",
  ui_story_9_13_2_13_dialog_content = "Por favor, perdóname, Lady Victoria. Debería intentar calmarme...",
  ui_story_9_13_2_14_dialog_content = "Pact, por favor no subestimes a la Semilla.",
  ui_story_9_13_2_X15_dialog_content = "Aunque es pequeño, el Darkflow contenido en la Semilla puede tener un efecto significativo en la mente de un Aurorian normal.",
  ui_story_9_13_2_X16_dialog_content = "Nuestro cuerpo contiene poderosa Lumina, pero sólo podemos resistir sus efectos brevemente.",
  ui_story_9_13_2_X17_dialog_content = "No podemos tocarla por largo rato.",
  ui_story_9_13_2_15_dialog_content = "Y así tenemos otra regla que no podemos ignorar. No debería subestimarla...",
  ui_story_9_14_1_1_dialog_content = "Es más adelante.",
  ui_story_9_14_1_2_dialog_content = "¡Estén atentos!",
  ui_story_9_14_1_3_dialog_content = "¿Es ese el Aviduz?",
  ui_story_9_14_1_4_dialog_content = "Se ve temible... Lepidoz es más adorable.",
  ui_story_9_14_1_5_dialog_content = "Explosión del cañón Lumina más impacto del choque...",
  ui_story_9_14_1_6_dialog_content = "Aviduz se encuentra en un estado terrible ahora.",
  ui_story_9_14_1_7_dialog_content = "Hmm... Justo ahora... cuando Aviduz gemía, sonaba como su último grito antes de dejar este mundo...",
  ui_story_9_14_1_8_dialog_content = "Entremos y busquemos el cuerpo de Schummer, igualmente.",
  ui_story_9_14_1_9_dialog_content = "¡Espera, alguien va saliendo!",
  ui_story_9_14_1_10_dialog_content = "¿Es Schummer?",
  ui_story_9_14_1_11_dialog_content = "No, definitivamente no es Schummer.",
  ui_story_9_14_1_12_dialog_content = "¡Es <color=#FFB400>Forsakin</color>!",
  ui_story_9_14_1_13_dialog_content = "!",
  ui_story_9_14_1_14_dialog_content = "!",
  ui_story_9_14_1_15_dialog_content = "¿Me preguntaba quién está tratando de interrumpirme ahora?",
  ui_story_9_14_1_16_dialog_content = "Veo que eres tú.",
  ui_story_9_14_1_17_dialog_content = "¿Nadie te ha dicho que siempre hay que llamar antes de hacer una visita?",
  ui_story_9_14_1_18_dialog_content = "Deberíamos decírtelo a ti.",
  ui_story_9_14_1_19_dialog_content = "¡Esto es Eraveil, donde no deberías estar!",
  ui_story_9_14_1_20_dialog_content = "Como estoy aquí, obviamente no estoy sujeta a tus reglas.",
  ui_story_9_14_1_21_dialog_content = "¡Eres tú!",
  ui_story_9_14_1_22_dialog_content = "¡Pensé que morías en ese incendio!",
  ui_story_9_14_1_23_dialog_content = "Pero reconocería hasta tus cenizas, ¡así que no creas que podrías librarte cambiando tu nombre!",
  ui_story_9_14_1_24_dialog_content = "...",
  ui_story_9_14_1_25_dialog_content = "¿Qué le hiciste a mi hermana, <color=#FFB400>Denier</color>?",
  ui_story_9_14_1_26_dialog_content = "...",
  ui_story_9_14_1_27_dialog_content = "Oye, ¡¿estás sorda?!",
  ui_story_9_14_1_28_dialog_content = "PlayerName, no puedo sentir ningún Darkflow en ti...",
  ui_story_9_14_1_29_option_content = "¿Quién eres en serio?",
  ui_story_9_14_1_30_dialog_content = "No me digas que fuiste investigadora de Illumina.",
  ui_story_9_14_1_31_dialog_content = "¿Y a ti qué, en todo caso?",
  ui_story_9_14_1_32_dialog_content = "¿Es eso importante?",
  ui_story_9_14_1_33_dialog_content = "No lo es en absoluto.",
  ui_story_9_14_1_34_dialog_content = "¿Dónde está la semilla en ti, PlayerName?",
  ui_story_9_14_1_35_dialog_content = "¡Así que fuiste tú quien la plantó en mi espalda!",
  ui_story_9_14_1_36_dialog_content = "Me dio picazón por un tiempo.",
  ui_story_9_14_1_37_dialog_content = "¿Picazón?",
  ui_story_9_14_1_38_dialog_content = "Entonces, ¿qué pasó? ¿Cuánto duró la picazón?",
  ui_story_9_14_1_39_dialog_content = "Sobre... Oye, ¿por qué debo decírtelo?",
  ui_story_9_14_1_40_dialog_content = "Cuidado, PlayerName, y no dejes que te guíe.",
  ui_story_9_14_1_41_dialog_content = "¿Cómo te retiraste la semilla de la espalda?",
  ui_story_9_14_1_42_dialog_content = "Si quieres saberlo, tienes que responderme primero...",
  ui_story_9_14_1_43_option_content = "¿Por qué estás en Eraveil?",
  ui_story_9_14_1_44_dialog_content = "¿Por qué has convertido Aurorians en Eclipsites? ¿Por qué los experimentos crueles?",
  ui_story_9_14_1_45_option_content = "¿Por qué plantaste la semilla en mí?",
  ui_story_9_14_1_46_dialog_content = "¿Me convertiría en un Eclipsite si no pudiera sacarla?",
  ui_story_9_14_1_47_dialog_content = "Haces muchas preguntas.",
  ui_story_9_14_1_48_dialog_content = "Sólo puedo decirte que estoy muy decepcionada, PlayerName.",
  ui_story_9_14_1_49_dialog_content = "Te di la oportunidad de tener gran poder y aprender la verdad sobre el mundo.",
  ui_story_9_14_1_50_dialog_content = "Pero desperdiciaste la oportunidad y le diste la espalda.",
  ui_story_9_14_1_51_dialog_content = "Qué pena.",
  ui_story_9_14_1_52_dialog_content = "Y ya no lo podrás descubrir, PlayerName.",
  ui_story_9_14_1_53_dialog_content = "¡No la escuches!",
  ui_story_9_14_1_54_dialog_content = "¡Seguro que es esa ex-investigadora de Illumina, Negadora!",
  ui_story_9_14_1_55_dialog_content = "¿Negadora? No me suena ese nombre.",
  ui_story_9_14_1_56_dialog_content = "¡Deja de actuar!",
  ui_story_9_14_1_57_dialog_content = "¡Eve sufrió durante años por tu culpa!",
  ui_story_9_14_1_58_dialog_content = "¿Eve?",
  ui_story_9_14_1_59_dialog_content = "¿Te suena?",
  ui_story_9_14_1_60_dialog_content = "Un poco, pero aún no recuerdo.",
  ui_story_9_14_1_61_dialog_content = "En fin, he realizado incontables experimentos y temas.",
  ui_story_9_14_1_62_dialog_content = "¡Tú!",
  ui_story_9_14_1_63_dialog_content = "Tranquilo, Sinsa. Forsakin sólo está tratando de meterse en tu piel.",
  ui_story_9_14_1_64_dialog_content = "¡Estoy bien!",
  ui_story_9_14_1_65_dialog_content = "¡Tan bien, que ya pensé en cien formas de descuartizarla pieza por pieza!",
  ui_story_9_14_1_66_dialog_content = "A mí me parece que has pensado en cien formas de que te den una paliza.",
  ui_story_9_14_1_67_dialog_content = "¡Creo que tendré que hacerte entrar en razón!",
  ui_story_9_14_1_68_dialog_content = "...",
  ui_story_9_14_1_69_dialog_content = "Todos ladran, pocos muerden.",
  ui_story_9_14_1_70_dialog_content = "¿Estás bien, Jefe?",
  ui_story_9_14_1_71_dialog_content = "*Tose*... ¡Estoy bien!",
  ui_story_9_14_1_72_dialog_content = "¿Qué ha pasado?",
  ui_story_9_14_1_73_dialog_content = "Ella agitó su mano y Sinsa salió volando.",
  ui_story_9_14_1_74_dialog_content = "Está usando Eclipsium.",
  ui_story_9_14_1_75_dialog_content = "¡La Forsakin frente a nosotros ha abandonado su origen Aurorian para convertirse en un monstruo!",
  ui_story_9_14_1_76_dialog_content = "¡Te mataré, bruja!",
  ui_story_9_14_1_77_dialog_content = "Silencio... No seas tan malagradecido.",
  ui_story_9_14_1_78_dialog_content = "No me gusta pelear.",
  ui_story_9_14_1_79_dialog_content = "Pero si insistes, puedo encontrar un oponente idóneo para ti.",
  ui_story_9_14_1_80_dialog_content = "Ven a jugar con tus nuevos amigos, Mad Horn.",
  ui_story_9_14_1_81_dialog_content = "<anim type=Shake>¡Taba... nunca... muere!</anim>",
  ui_story_9_14_1_82_dialog_content = "¿Mad Horn? ¡Este es claramente el Tabaad con el que luchamos antes!",
  ui_story_9_14_1_X82_dialog_content = "Ese nombre es sólo un código creado por conveniencia...",
  ui_story_9_14_1_83_dialog_content = "¿Ya conocían este Eclipsite?",
  ui_story_9_14_1_84_dialog_content = "La Comandante Hiiro le dio un golpe fatal en Mantiz...",
  ui_story_9_14_1_85_dialog_content = "Es otra reanimación.",
  ui_story_9_14_1_86_dialog_content = "¡Así que Forsakin ha estado reanimando a los muertos!",
  ui_story_9_14_1_87_dialog_content = "Llamémoslo reciclaje eficiente.",
  ui_story_9_14_1_88_dialog_content = "Pero es más que suficiente para ti manejar.",
  ui_story_9_14_1_89_dialog_content = "<anim type=Shake>¡Gahhhhhh!</anim>",
  ui_story_9_14_1_90_dialog_content = "<anim type=Shake>¡Taba... nunca... muere!</anim>",
  ui_story_9_14_2_1_dialog_content = "<anim type=Shake>¡Ugh!</anim>",
  ui_story_9_14_2_2_dialog_content = "¡Vigila a Forsakin!",
  ui_story_9_14_2_3_dialog_content = "¡Cuidado, PlayerName!",
  ui_story_9_14_2_4_dialog_content = "!",
  ui_story_9_14_2_5_dialog_content = "¡No vas a tocar a nadie!",
  ui_story_9_14_2_6_dialog_content = "...",
  ui_story_9_14_2_7_dialog_content = "¡Jefe!",
  ui_story_9_14_2_8_dialog_content = "¿Estás bien, Sinsa?",
  ui_story_9_14_2_9_dialog_content = "¡Me va muy bien! *Tose*",
  ui_story_9_14_2_10_dialog_content = "Un paso más, Aurorian corompida, y ¡haré justicia sobre ti!",
  ui_story_9_14_2_11_dialog_content = "No te emociones tanto.",
  ui_story_9_14_2_12_dialog_content = "Sólo quiero ver a PlayerName de cerca.",
  ui_story_9_14_2_13_dialog_content = "¿Qué es lo que quieres con PlayerName, Forsakin?",
  ui_story_9_14_2_14_dialog_content = "Rehusaste responder a mis preguntas, así que debo realizar mi propia investigación.",
  ui_story_9_14_2_15_dialog_content = "En efecto, no hay rastro de la Semilla en ti, PlayerName.",
  ui_story_9_14_2_16_dialog_content = "Por última vez, ¿cómo te las arreglaste para sacarla?",
  ui_story_9_14_2_17_dialog_content = "Primero dime por qué harías tal experimento.",
  ui_story_9_14_2_18_dialog_content = "Todavía no sabes en la situación en la que estás, PlayerName.",
  ui_story_9_14_2_19_dialog_content = "No estás apto ni tienes poder para negociar conmigo.",
  ui_story_9_14_2_20_dialog_content = "No gastes tu energía en ella, PlayerName.",
  ui_story_9_14_2_21_dialog_content = "¿Ah?",
  ui_story_9_14_2_22_dialog_content = "Lo saqué de PlayerName. ¿Algún problema con eso?",
  ui_story_9_14_2_23_dialog_content = "¿Cómo pudo Illumina producir una traidora como tú?",
  ui_story_9_14_2_24_dialog_content = "¡No hagas nada estúpido, Vice!",
  ui_story_9_14_2_25_dialog_content = "Será mejor que digas la verdad.",
  ui_story_9_14_2_26_dialog_content = "¡Arrgh! Oh.",
  ui_story_9_14_2_27_dialog_content = "¡Vice!",
  ui_story_9_14_2_28_dialog_content = "¡Forsakin! ¡Suelta a Vice, ya!",
  ui_story_9_14_2_29_dialog_content = "Me detendré, pero tienes que darme la misma cortesía.",
  ui_story_9_14_2_30_dialog_content = "Dime, ¿a dónde fue la Semilla?",
  ui_story_9_14_2_31_dialog_content = "...",
  ui_story_9_14_2_32_dialog_content = "(No puedo poner a Vice en peligro...)",
  ui_story_9_14_2_33_dialog_content = "(Supongo que debo decírselo.)",
  ui_story_9_14_2_34_dialog_content = "Te diré lo que quieres saber, ¡pero primero déjala ir! ¡Prometo que te lo diré!",
  ui_story_9_14_2_X34_dialog_content = "Está bien.",
  ui_story_9_14_2_X35_dialog_content = "*Tose*",
  ui_story_9_14_2_X36_dialog_content = "¡Vice, ven aquí!",
  ui_story_9_14_2_X37_dialog_content = "Está bien. Habla.",
  ui_story_9_14_2_35_dialog_content = "La semilla la tomó un hombre con un maletín blanco.",
  ui_story_9_14_2_36_dialog_content = "Hombre con maletín blanco...",
  ui_story_9_14_2_37_dialog_content = "¿Quién es?",
  ui_story_9_14_2_38_dialog_content = "No lo conozco ni sé por qué tomó la Semilla.",
  ui_story_9_14_2_39_dialog_content = "¡Pero dijo que podía transformar a los Aurorians en Eclipsites!",
  ui_story_9_14_2_40_dialog_content = "¡Estabas tratando de usarlo no solo para convertirme en un Eclipsite, sino que incluso convertiste a los soldados de Lumopolis en Eclipsites!",
  ui_story_9_14_2_41_dialog_content = "¡Los sujetos, como los llamaste, son en realidad víctimas de la Semilla!",
  ui_story_9_14_2_42_dialog_content = "¿Verdad?",
  ui_story_9_14_2_43_dialog_content = "Ya que estás tan convencido, no tengo nada más que decir.",
  ui_story_9_14_2_44_dialog_content = "No, quiero saber ¿por qué cometerías tales experimentos inhumanos?",
  ui_story_9_14_2_45_dialog_content = "¿Por qué conspirar con la oscuridad cuando eres Aurorian?",
  ui_story_9_14_2_46_dialog_content = "Te lo dije, PlayerName. Te quedaste sin oportunidades para averiguarlo.",
  ui_story_9_14_2_47_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_9_14_2_48_dialog_content = "Hmm, ya es hora.",
  ui_story_9_14_2_49_dialog_content = "¿Qué es ese ruido?",
  ui_story_9_14_2_50_dialog_content = "Vino del interior de Aviduz.",
  ui_story_9_14_2_51_dialog_content = "Es el sonido cuando un Colossus deja de funcionar.",
  ui_story_9_14_2_52_dialog_content = "(Ya no puedo percibir nada de Aviduz.)",
  ui_story_9_14_2_53_dialog_content = "(¿Está... muerto?)",
  ui_story_9_14_2_54_dialog_content = "¡¿Ni siquiera perdonaste a Aviduz, Forsakin?!",
  ui_story_9_14_2_55_dialog_content = "¿Qué le hiciste?",
  ui_story_9_14_2_56_dialog_content = "De verdad hiciste muchas preguntas, PlayerName.",
  ui_story_9_14_2_57_dialog_content = "¿Por qué no entras en Colossus y le preguntas a tu <color=#FFB400>vieja amiga</color> si quieres saberlo?",
  ui_story_9_14_2_58_dialog_content = "¡Forsakin entró en Colossus!",
  ui_story_9_14_2_59_dialog_content = "¡Oye, vuelve aquí ahora!",
  ui_story_9_14_2_60_dialog_content = "¿\"<color=#FFB400>Vieja amiga</color>\"?",
  ui_story_9_14_2_61_dialog_content = "...",
  ui_story_9_14_2_62_dialog_content = "Schummer...",
  ui_story_9_14_2_63_dialog_content = "<size=45>¡Schummer sigue viva!</size>",
  ui_story_10_1_1_1_dialog_content = "<color=#e8d9bb>Lumopolis, frente al centro médico</color>",
  ui_story_10_1_1_2_dialog_content = "¿Así que así es como se ve el Patio de Lumopolis ahora, miau?",
  ui_story_10_1_1_S1_dialog_content = "Estos edificios... Cada uno es más lujoso que el anterior.",
  ui_story_10_1_1_3_dialog_content = "Seguro que espero Jefe Vivian se queda un poco más para recuperar su fuerza. De esa manera, Philyshy puede descansar un poco mas...",
  ui_story_10_1_1_4_dialog_content = "¿Miau?",
  ui_story_10_1_1_5_dialog_content = "¿Dónde está la nueva paciente? ¡Voy en camino!",
  ui_story_10_1_1_6_dialog_content = "¡Señora, por favor, no vuele por aquí!",
  ui_story_10_1_1_7_dialog_content = "¿Ya te fuiste, miau?",
  ui_story_10_1_1_8_dialog_content = "Nyejeje, parece ser la oportunidad de Philyshy...",
  ui_story_10_1_1_9_dialog_content = "<color=#e8d9bb>¡Whoosh!</color>",
  ui_story_10_1_1_10_dialog_content = "Uf, ¿cuánto tiempo más debo estar aquí? No me dejan hacer nada hasta que me recupere...",
  ui_story_10_1_1_11_dialog_content = "¡Kyuu!",
  ui_story_10_1_1_12_dialog_content = "Gracias por consolarme, Curie. Estoy un poco ansiosa, es todo...",
  ui_story_10_1_1_13_dialog_content = "¿Por qué no ayudas a vigilar fuera un rato?",
  ui_story_10_1_1_14_dialog_content = "¡Kyuu!",
  ui_story_10_1_1_15_dialog_content = "Además...",
  ui_story_10_1_1_16_dialog_content = "<color=#e8d9bb>*Susurro*</color>",
  ui_story_10_1_1_17_dialog_content = "Tú, allí. Tus oídos han barrido el suelo, gatito fisgón.",
  ui_story_10_1_1_18_dialog_content = "¿Miau? ¡Pero Philyshy no está barriendo el suelo!",
  ui_story_10_1_1_19_dialog_content = "¡Philyshy sólo quiere intentar oír el movimiento del enemigo en el suelo, es todo!",
  ui_story_10_1_1_20_dialog_content = "Sé lo que te preocupa.",
  ui_story_10_1_1_21_dialog_content = "Aunque han arreglado esta habitación sólo para mí, no hay duda de que...",
  ui_story_10_1_1_22_dialog_content = "No hay vigilancia en el lugar.",
  ui_story_10_1_1_S2_dialog_content = "Sólo quieren que me quede en Lumopolis un poco más.",
  ui_story_10_1_1_23_dialog_content = "Ahora, ¿qué noticias tienes para mí?",
  ui_story_10_1_1_24_dialog_content = "Jeje, ¡esa es la Vivian que conozco! ¡Has visto a través de Philyshy!",
  ui_story_10_1_1_25_dialog_content = "Ejem, una vez que Philyshy ha obtenido información sobre <color=#FFB400>Forsakin</color>, Philyshy te la trae.",
  ui_story_10_1_1_26_dialog_content = "¿Qué has averiguado sobre ella?",
  ui_story_10_1_1_27_dialog_content = "Difícil decir, miau.",
  ui_story_10_1_1_28_dialog_content = "Y es que... incluso en el informe interno, lleva 9 años <color=#FFB400>muerta</color>.",
  ui_story_10_1_1_29_dialog_content = "Después que el gran incendio consumiera toda la Subciudad...",
  ui_story_10_1_1_30_dialog_content = "Todos asumieron que murió en el incendio.",
  ui_story_10_1_1_31_dialog_content = "Pero, un equipo de investigación encontró cadáveres de Eclipsites y Aurorians en las ruinas.",
  ui_story_10_1_1_32_dialog_content = "Cuando supe que Forsakin había plantado la <color=#FFB400>Semilla</color> en el cuerpo de PlayerName...",
  ui_story_10_1_1_33_dialog_content = "¡Justo ahí, armé todo, miau!",
  ui_story_10_1_1_34_dialog_content = "¿Crees que esto tiene algo que ver con lo que Forsakin estaba investigando entonces?",
  ui_story_10_1_1_35_dialog_content = "Posiblemente, ella... <color=#FFB400>ya se convirtió en un Eclipsite</color>.",
  ui_story_10_1_1_36_dialog_content = "¿Cómo reaccionó la Gran Mariscal al descubrir que Forsakin aún vive?",
  ui_story_10_1_1_37_dialog_content = "Miau... Acerca de eso...",
  ui_story_10_1_1_38_dialog_content = "¿Qué es? ¿Por qué tan nerviosa?",
  ui_story_10_1_1_39_dialog_content = "¿T-tú sabes la relación entre ellas dos, verdad? Así que...",
  ui_story_10_1_1_40_dialog_content = "Sé lo que te preocupa. Es porque <color=#FFB400>Forsakin es la hermana menor de la Gran Mariscal</color>, ¿correcto?",
  ui_story_10_1_1_41_dialog_content = "¡Exacto! Mi superior, sin duda, miau. Una pequeña pista y puedes ver todo en el corazón de Philyshy.",
  ui_story_10_1_1_42_dialog_content = "Dime lo que sucedió.",
  ui_story_10_1_1_43_dialog_content = "La Gran Mariscal tomó a los Comandantes de la Legión y se fue. Dijo que era para una reunión de comandantes, pero...",
  ui_story_10_1_1_44_dialog_content = "Philyshy cree que esta vez es diferente.",
  ui_story_10_1_1_45_dialog_content = "Los cuatro Comandantes de la Legión son la gente más confiable de la Gran Mariscal, y los guerreros más poderosos de Illumina.",
  ui_story_10_1_1_46_dialog_content = "Señora... ¿crees que la Gran Mariscal los llevaba para cazar a Forsakin?",
  ui_story_10_1_1_47_dialog_content = "Tu evaluación de los Eclipsites es ejemplar, Philyshy.",
  ui_story_10_1_1_48_dialog_content = "Sin embargo, cuando se trata de tus aliados, parece que todavía tienes que mejorar tus análisis.",
  ui_story_10_1_1_49_dialog_content = "Miau...",
  ui_story_10_1_1_50_dialog_content = "¿P-podría decirme la respuesta, Señora? La mente de Philyshy se queda corta...",
  ui_story_10_1_1_51_dialog_content = "¿Crees sinceramente que nuestra Gran Mariscal abusaría de su poder y haría algo tan precipitado por una venganza personal?",
  ui_story_10_1_1_52_dialog_content = "¿Nyeh? ¡P-Philyshy no estaba acusando a la Gran Mariscal de nada! ¡De verdad!",
  ui_story_10_1_1_53_dialog_content = "Lo sé... no tengas miedo, sólo déjame explicarte.",
  ui_story_10_1_1_54_dialog_content = "La aparición de Forsakin es señal para nosotros.",
  ui_story_10_1_1_55_dialog_content = "Cuando los depredadores acorralan a su presa y se preparan para matar... Es cuando son más vulnerables.",
  ui_story_10_1_1_56_dialog_content = "¡Miau! ¡Entiendo! Philyshy no debió husmear en los asuntos de la Gran Mariscal, ¿verdad?",
  ui_story_10_1_1_57_dialog_content = "¡Al fin y al cabo, la Gran Mariscal tiene su propio plan!",
  ui_story_10_1_1_58_dialog_content = "Sí. Sólo espero que entiendas de verdad. En todo caso, trata de no presumir demasiado sobre el asunto de la Gran Mariscal, Philishy.",
  ui_story_10_1_1_59_dialog_content = "¡Miau-bien!",
  ui_story_10_1_1_60_dialog_content = "Entonces, ¿debe Philyshy seguir investigando la Semilla?",
  ui_story_10_1_1_61_dialog_content = "¡Pero claro!",
  ui_story_10_1_1_62_dialog_content = "¿Y podría Philyshy ir a buscar a Vice y a los demás, miau?",
  ui_story_10_1_1_63_dialog_content = "¿Mmm? ¿Cómo llegaste a esa conclusión?",
  ui_story_10_1_1_64_dialog_content = "¡Sencillo, obtuve mi información sobre la Semilla de Vice y PlayerName mismo!",
  ui_story_10_1_1_65_dialog_content = "De camino aquí, les oí decir algo sobre que Aviduz cayó del cielo, ¡miau!",
  ui_story_10_1_1_66_dialog_content = "¡Y luego dijeron que un Colossus salió de Lumopolis hace unos días!",
  ui_story_10_1_1_67_dialog_content = "¡Estoy muy segura de que eso significa que Vice y sus amigos salieron <color=#FFB400>tras Aviduz</color>, miau!",
  ui_story_10_1_1_68_dialog_content = "Ya que la Semilla y Aviduz están relacionados así... ¿Por qué no voy a por Aviduz?",
  ui_story_10_1_1_69_dialog_content = "Philyshy... realmente eres brillante...",
  ui_story_10_1_1_70_dialog_content = "Tienes toda la razón, PlayerName y Vice están de camino a la ubicación de Aviduz mientras hablamos.",
  ui_story_10_1_1_71_dialog_content = "¿Puede Philyshy ir también?",
  ui_story_10_1_1_72_dialog_content = "Para que quede claro, no vas sólo por diversión, ¿correcto?",
  ui_story_10_1_1_73_dialog_content = "¡Para nada! Philyshy ha tenido mala sensación en todo esto últimamente...",
  ui_story_10_1_1_74_dialog_content = "En fin, está vinculado de algún modo con Schummer y Forsakin. No sólo para investigar, sino también por seguridad.",
  ui_story_10_1_1_75_dialog_content = "¡Es mejor que vaya con ellos!",
  ui_story_10_1_1_76_dialog_content = "¡Además, sólo pensar en toda la información sobre Forsakin me pone emocionada que no puedo ni sentarme, miau!",
  ui_story_10_1_1_77_dialog_content = "¿Y si Forsakin consiguió capturar a PlayerName y a Vice y experimentar con ellos?",
  ui_story_10_1_1_78_dialog_content = "Ok... Ahora entiendo tu forma de pensar.",
  ui_story_10_1_1_79_dialog_content = "Pero no debes preocuparte mucho por Vice y sus amigos.",
  ui_story_10_1_1_80_dialog_content = "Antes de que partieran, hablamos de varias posibilidades que podrían ocurrir cuando se encontraran con Forsakin.",
  ui_story_10_1_1_81_dialog_content = "Lo más importante es que la Capitana Carleen también está con ellos.",
  ui_story_10_1_1_82_dialog_content = "Eso significa... Lumopolis se ha encargado del asunto de Schummer, y de todo lo relacionado con ella.",
  ui_story_10_1_1_83_dialog_content = "¿Miau? Ya veo...",
  ui_story_10_1_1_84_dialog_content = "Entonces creo es mejor quedarme...",
  ui_story_10_1_1_85_dialog_content = "Así es. Hasta que se determine la situación, debemos esperar primero la comunicación de Vice.",
  ui_story_10_2_1_1_dialog_content = "Em...",
  ui_story_10_2_1_2_dialog_content = "¿Qué hacemos ahora?",
  ui_story_10_2_1_3_dialog_content = "¡Matar para entrar, claro! ¿Qué más se puede hacer? ¿O quieres que se escape?",
  ui_story_10_2_1_4_dialog_content = "Cálmate.",
  ui_story_10_2_1_5_dialog_content = "No importa cómo lo veas, está claro que nos están engañando para que entremos.",
  ui_story_10_2_1_6_dialog_content = "¡Pues claro, duh!",
  ui_story_10_2_1_7_dialog_content = "Si entramos, podemos caer en la trampa de Forsakin.",
  ui_story_10_2_1_8_dialog_content = "¡Pero si no lo hacemos, podemos enviarla nosotros mismos!",
  ui_story_10_2_1_9_dialog_content = "Sin mencionar a esa <color=#FFB400>Schummer</color> que persigues, también.",
  ui_story_10_2_1_10_dialog_content = "¡Todo lo que sé es que Schummer sigue viva, y está dentro de Aviduz!",
  ui_story_10_2_1_11_dialog_content = "Puedo sentir su presencia, pero es muy débil... Creo que está herida.",
  ui_story_10_2_1_12_dialog_content = "No podemos actuar imprudentemente. Tal vez si reforzamos y defendemos esta posición...",
  ui_story_10_2_1_13_dialog_content = "Parece que quieres llamar a Lumopolis o Illumina para pedir refuerzos. ¿Cierto?",
  ui_story_10_2_1_14_dialog_content = "Ni lo pienses. Estaremos viejos y canosos para cuando vengan sus peones.",
  ui_story_10_2_1_15_dialog_content = "Deja de juzgar todo basándote en tu instinto.",
  ui_story_10_2_1_16_dialog_content = "¡Ja! Viendo que sólo te enviaron a ti... Es obvio, ¿no?",
  ui_story_10_2_1_17_dialog_content = "Muchos soldados de Lumopolis murieron en este lugar... ¡Sabían cómo serían las cosas aquí!",
  ui_story_10_2_1_18_dialog_content = "Si realmente tuvieran la intención de ayudar, no esperarían tu llamada.",
  ui_story_10_2_1_19_dialog_content = "Uh, N-no creo que discutir sea lo correcto...",
  ui_story_10_2_1_20_dialog_content = "Quizá si gritamos fuerte, nuestros aliados escuchen y vengan a salvarnos...",
  ui_story_10_2_1_21_dialog_content = "¿Quieres esperar a que nos encuentren? ¡Nos caímos aquí! ¡Nadie nos encontrará si no caen ellos también!",
  ui_story_10_2_1_22_dialog_content = "Eso es cierto... además, no creo que puedan encontrar su camino aquí...",
  ui_story_10_2_1_23_dialog_content = "¿Realmente Forsakin puso una trampa sólo para matarnos?",
  ui_story_10_2_1_24_dialog_content = "De algún modo, no creo que sea el caso...",
  ui_story_10_2_1_25_dialog_content = "Cuando peleamos más temprano, no pudimos ponerle ni un dedo encima.",
  ui_story_10_2_1_26_dialog_content = "Aunque tenga esa clase de poder, pareciera que...",
  ui_story_10_2_1_27_dialog_content = "<color=#FFB400>No piensa atacarnos.</color>",
  ui_story_10_2_1_28_dialog_content = "¿Querrá que veamos a Schummer?",
  ui_story_10_2_1_29_dialog_content = "Si tuviéramos más información...",
  ui_story_10_2_1_30_dialog_content = "PlayerName, ¿crees que puedes usar tus poderes psíquicos para sentir lo que piensa Forsakin?",
  ui_story_10_2_1_31_dialog_content = "En realidad... Intenté eso antes...",
  ui_story_10_2_1_32_dialog_content = "Lo siento, pero <color=#FFB400>no puedo usar mis poderes en Forsakin de ese modo</color>.",
  ui_story_10_2_1_33_dialog_content = "¿Por qué?",
  ui_story_10_2_1_34_dialog_content = "Tampoco sé cómo explicarlo. Es solo que...",
  ui_story_10_2_1_35_dialog_content = "Percibir los pensamientos de alguien ya es bastante difícil.",
  ui_story_10_2_1_36_dialog_content = "La distancia, el poder del usuario y si el sujeto se resiste o no... Hay muchos factores que pueden influir en el resultado de esa habilidad.",
  ui_story_10_2_1_37_dialog_content = "En verdad, sólo funcionó bien cuando percibí a Schummer justo ahora...",
  ui_story_10_2_1_38_dialog_content = "Además... parece ser cada vez más fácil.",
  ui_story_10_2_1_39_dialog_content = "Lo único que sé con seguridad ahora mismo es que Schummer está gravemente herida.",
  ui_story_10_2_1_40_dialog_content = "Vice, Carleen... Yo...",
  ui_story_10_2_1_41_dialog_content = "¡Vamos! ¡Siempre atacamos cuando las cosas se ven peligrosas, y hoy no es la excepción!",
  ui_story_10_2_1_42_dialog_content = "Muy bien, entremos a inspeccionar la zona. Guiaré el camino.",
  ui_story_10_2_1_43_dialog_content = "¿Ahora quieres entrar? ¡Incluso caminas más rápido que yo, ahora!",
  ui_story_10_2_1_44_dialog_content = "Seguro que hablaron hasta la saciedad para llegar a la misma conclusión que antes...",
  ui_story_10_2_1_45_dialog_content = "Sé que tú y Vice son íntimos, pero ¿cuándo empezó a escucharte esa chica Carleen también?",
  ui_story_10_2_1_46_dialog_content = "No me están escuchando a mí... Vice y Carleen me han ayudado todo este tiempo, no al revés, así que les estoy agradecido.",
  ui_story_10_2_1_47_dialog_content = "Sólo espero poder devolverles toda su ayuda cuando esto termine.",
  ui_story_10_2_1_48_dialog_content = "Vamos...",
  ui_story_10_2_1_49_dialog_content = "¿Así que este es Aviduz?",
  ui_story_10_2_1_50_dialog_content = "¡Ja, no hay nada de miedo en ello, para nada! Todo está tan destrozado que no parece que pueda matar ni a un gusano de arena.",
  ui_story_10_2_1_51_dialog_content = "Eso es porque Lumopolis lo derribó.",
  ui_story_10_2_1_52_dialog_content = "Sí, sí, no tienes que recordármelo.",
  ui_story_10_2_1_53_dialog_content = "Sólo respondía a tus dudas... ¿O pensabas que Lumopolis no era bastante poderosa para hacer esto?",
  ui_story_10_2_1_54_dialog_content = "*Tosiendo* Uh, el que Aviduz gastara todo su poder podría haber tenido algo que ver también...",
  ui_story_10_2_1_55_dialog_content = "*Tosiendo*",
  ui_story_10_2_1_56_dialog_content = "¿Por qué tanto carraspeo? ¿Tienes miedo que empecemos a discutir de nuevo?",
  ui_story_10_2_1_57_dialog_content = "No... es por el Darkflow...",
  ui_story_10_2_1_58_dialog_content = "Está destrozado sin remedio, pero el Darkflow es aún muy denso aquí...",
  ui_story_10_2_1_59_dialog_content = "Grrr...",
  ui_story_10_2_1_60_dialog_content = "¿Un Eclipsite? ¡Alerta, todos!",
  ui_story_10_2_1_61_dialog_content = "¡Gahhhhhh!",
  ui_story_10_2_2_1_dialog_content = "¡Graaah—!",
  ui_story_10_2_2_2_dialog_content = "¡Oh, no! ¡Cuidado, PlayerName!",
  ui_story_10_2_2_3_dialog_content = "¡Fuera de aquí!",
  ui_story_10_2_2_4_dialog_content = "¿Estás bien?",
  ui_story_10_2_2_5_dialog_content = "*Jadeando* Ah... gracias...",
  ui_story_10_2_2_6_dialog_content = "Estoy bien, sólo que mis pantalones casi se queman...",
  ui_story_10_2_2_7_dialog_content = "¡Lo siento! Uno me pasó...",
  ui_story_10_2_2_8_dialog_content = "¡Está por allá!",
  ui_story_10_2_2_9_dialog_content = "¡Gahhhhhh!",
  ui_story_10_2_2_10_dialog_content = "¿Ah? ¿Por qué huyó? Vuelve aquí...",
  ui_story_10_2_2_11_dialog_content = "¡¿A dónde crees que vas?!",
  ui_story_10_2_2_12_dialog_content = "Grrr...",
  ui_story_10_2_2_13_dialog_content = "Raro... es como si estos Eclipsites fueran ciegos. ¿No pueden vernos?",
  ui_story_10_2_2_14_dialog_content = "Es raro... Normalmente, los Eclipsites atacan en cuanto nos ven.",
  ui_story_10_2_2_15_dialog_content = "Pero estos Eclipsites parecen no querer emboscarnos...",
  ui_story_10_2_2_16_dialog_content = "Tanto como huir de nosotros.",
  ui_story_10_2_2_17_dialog_content = "Eh, sirve igualmente. Olvídate de estes qualesquiera, vamos directamente a buscar a Forsakin y saldar cuentas.",
  ui_story_10_2_2_18_dialog_content = "Este comportamiento errático podría tener algo que ver con Forsakin. Sea como sea, debemos estar alerta.",
  ui_story_10_2_2_19_dialog_content = "Es posible, coincido.",
  ui_story_10_2_2_20_dialog_content = "Tenemos que quitar estos Eclipsites del camino a medida que avanzamos. De lo contrario.",
  ui_story_10_2_2_21_dialog_content = "Es posible que nos flanqueen los Eclipsites y nos ataquen por ambos lados.",
  ui_story_10_2_2_22_dialog_content = "Sé que el Darkflow aquí es difícil de tratar para ti, PlayerName...",
  ui_story_10_2_2_23_dialog_content = "Pero,¿puedes usar tus poderes psíquicos para explorar la zona?",
  ui_story_10_2_2_24_dialog_content = "Puedo intentarlo.",
  ui_story_10_2_2_25_dialog_content = "...",
  ui_story_10_2_2_26_dialog_content = "<color=#e8d9bb>Whoosh.</color>",
  ui_story_10_2_2_27_dialog_content = "¡Brrr! ¿De dónde viene ese viento...?",
  ui_story_10_2_2_28_dialog_content = "¡Shh! Cállate, ¿no ves que PlayerName se está concentrando?",
  ui_story_10_2_2_29_dialog_content = "Pero jefe... Eres mucho más ruidoso que yo...",
  ui_story_10_2_2_30_dialog_content = "Shhh...",
  ui_story_10_2_2_31_dialog_content = "(El Darkflow...)",
  ui_story_10_2_2_32_dialog_content = "(El Darkflow parece concentrarse en una dirección.)",
  ui_story_10_2_2_33_dialog_content = "(Qué asco... La densidad va cambiando entre grueso y fino... No puedo soportar mucho más.)",
  ui_story_10_2_2_34_dialog_content = "(Eclipsite... Eclipsite...)",
  ui_story_10_2_2_35_dialog_content = "(Todos son Eclipsites.)",
  ui_story_10_2_2_36_dialog_content = "(Me voy a enfermar... ¿Qué es ese olor...?)",
  ui_story_10_2_2_37_dialog_content = "(Y...)",
  ui_story_10_2_2_38_dialog_content = "<color=#e8d9bb>Crujido...</color>",
  ui_story_10_2_2_39_dialog_content = "(¿Qué es ese ruido?)",
  ui_story_10_2_2_40_dialog_content = "<color=#e8d9bb>Crujido</color>",
  ui_story_10_2_2_41_dialog_content = "(¿Algo rechina los dientes?)",
  ui_story_10_2_2_42_dialog_content = "<color=#e8d9bb>Crujido</color>",
  ui_story_10_2_2_43_dialog_content = "(No, está masticando algo...)",
  ui_story_10_2_2_44_dialog_content = "<color=#e8d9bb>Crujido</color>",
  ui_story_10_2_2_45_dialog_content = "(Algo... pegajoso... huele mal...)",
  ui_story_10_2_2_46_dialog_content = "(Ese olor... Es nauseabundo...)",
  ui_story_10_2_2_47_dialog_content = "(También puedo sentir el dolor...)",
  ui_story_10_2_2_48_dialog_content = "(¿Qué es? Entre sus dientes, y bajo su lengua...)",
  ui_story_10_2_2_49_dialog_content = "(En su garganta, también... ¡¿Algo abultado y húmedo?!)",
  ui_story_10_2_2_50_dialog_content = "Ugh...",
  ui_story_10_2_2_51_dialog_content = "Estos Eclipsites... saben horrible.",
  ui_story_10_3_1_1_dialog_content = "¡Urgh!",
  ui_story_10_3_1_2_dialog_content = "¡PlayerName! ¡Despierta!",
  ui_story_10_3_1_3_dialog_content = "Urgh. *Tosiendo*",
  ui_story_10_3_1_4_dialog_content = "Yo... He vuelto... ¡Urk!",
  ui_story_10_3_1_5_dialog_content = "¿Qué te pasó? ¡Nunca te he visto así después de usar tus poderes!",
  ui_story_10_3_1_6_dialog_content = "*Tosiendo* Lo siento... Sentí algo realmente asqueroso. ¡Urk!",
  ui_story_10_3_1_7_dialog_content = "Está bien, está bien, déjalo salir por ahora.",
  ui_story_10_3_1_8_dialog_content = "Oh... Tal vez deberías vomitar primero, o podrías ahogarte mientras hablas.",
  ui_story_10_3_1_9_dialog_content = "¿Los Celestitas tienen este tipo de reacciones después de usar sus habilidades psíquicas, Vice?",
  ui_story_10_3_1_10_dialog_content = "No, esto nunca ha ocurrido antes... a menos que haya pasado algo.",
  ui_story_10_3_1_11_dialog_content = "Algo realmente horrible.",
  ui_story_10_3_1_12_dialog_content = "Grrr...",
  ui_story_10_3_1_13_dialog_content = "¡Ven aquí, es una orden!",
  ui_story_10_3_1_14_dialog_content = "Grrr...",
  ui_story_10_3_1_15_dialog_content = "¡Arrástrate hacia adentro!",
  ui_story_10_3_1_16_dialog_content = "Grrr...",
  ui_story_10_3_1_17_dialog_content = "Excelente.",
  ui_story_10_3_1_18_dialog_content = "¡Graagh!",
  ui_story_10_3_1_19_dialog_content = "Cállate. Me estás aplastando.",
  ui_story_10_3_1_20_dialog_content = "¡Gah... gah!",
  ui_story_10_3_1_21_dialog_content = "...",
  ui_story_10_3_1_22_dialog_content = "Eso es mejor.",
  ui_story_10_3_1_23_dialog_content = "Forsakin, ¿no puedes hacer que tengan más cuidado cuando entren?",
  ui_story_10_3_1_24_dialog_content = "Todo mi cuerpo me está matando... ¿También tratas de aplastarme con estas cosas asquerosas?",
  ui_story_10_3_1_25_dialog_content = "¿Cómo? No te escuché bien.",
  ui_story_10_3_1_26_dialog_content = "No te hagas la tonta.",
  ui_story_10_3_1_27_dialog_content = "Puedo oír tu voz muy bien... ¿Cómo es posible que no me hayas oído gritar?",
  ui_story_10_3_1_28_dialog_content = "¿Crees que el volumen de tu voz tiene algo que ver con que te escuche o no?",
  ui_story_10_3_1_29_dialog_content = "Pero si te hace comer un poco más, supongo que no me importa charlar contigo un rato.",
  ui_story_10_3_1_30_dialog_content = "¿Quién podría comer estas cosas?",
  ui_story_10_3_1_31_dialog_content = "La ira estimulará tu crecimiento. Tienes que aprender a usarla.",
  ui_story_10_3_1_32_dialog_content = "No te comas realmente los Eclipsites, sólo toma uno o dos mordiscos y absorbe su Darkflow.",
  ui_story_10_3_1_33_dialog_content = "Este es el método más sencillo. No me digas que has llegado hasta aquí sin aprender a comer bien.",
  ui_story_10_3_1_34_dialog_content = "No te atrevas a condescender conmigo...",
  ui_story_10_3_1_35_dialog_content = "Las Semillas en sus espaldas son muy duras... No puedo comerlas.",
  ui_story_10_3_1_36_dialog_content = "Sólo la capa exterior es dura. Apriétalo, tus dientes de Eclipsite son mucho más fuertes de lo que crees.",
  ui_story_10_3_1_37_dialog_content = "Yo sé... Sólo quería desahogarme, es todo.",
  ui_story_10_3_1_38_dialog_content = "...",
  ui_story_10_3_1_39_dialog_content = "Parece que tu estado de ánimo está mejorando mucho, ahora que te estás recuperando de tus heridas.",
  ui_story_10_3_1_40_dialog_content = "Siento que debo elogiarte un poco.",
  ui_story_10_3_1_41_dialog_content = "¿Qué significa eso?",
  ui_story_10_3_1_42_dialog_content = "Tengo que decir que tienes buen ojo para elegir a la gente, supongo que PlayerName no es inútil, después de todo.",
  ui_story_10_3_1_43_dialog_content = "Aunque mi invitación fue un fracaso, pero ese Celestita es una gran causa para seguir estimulando tu crecimiento.",
  ui_story_10_3_1_44_dialog_content = "Supongo que debes estar muy feliz, para ser tan herida por tu viejo amigo y Lumopolis.",
  ui_story_10_3_1_45_dialog_content = "Insúltame una vez más, y yo misma te arrancaré los dientes de la cabeza...",
  ui_story_10_3_1_46_dialog_content = "Que delicada. Tendrás que crear cierta tolerancia mental, y rápido.",
  ui_story_10_3_1_47_dialog_content = "¿Qué tratas de decir?",
  ui_story_10_3_1_48_dialog_content = "Lo que digo... es que tu viejo amigo PlayerName ya entró en Aviduz.",
  ui_story_10_3_1_49_dialog_content = "Ese Celestita definitivamente quiere matarte y se venga.",
  ui_story_10_3_1_50_dialog_content = "...",
  ui_story_10_3_1_51_dialog_content = "Sólo te hago saber que te haré ganar tiempo.",
  ui_story_10_3_1_52_dialog_content = "Buscaré la manera de detenerlos hasta que termines de absorber suficiente energía y completes tu transformación.",
  ui_story_10_3_1_53_dialog_content = "Como sea, no tenemos mucho tiempo.",
  ui_story_10_3_1_54_dialog_content = "<color=#e8d9bb>Crujido</color>",
  ui_story_10_3_1_55_dialog_content = "Espero que finalmente puedas <color=#FFB400>completarte</color>.",
  ui_story_10_3_1_56_dialog_content = "Si lo haces, intenta no ser como tu Aviduz...",
  ui_story_10_3_1_57_dialog_content = "Llegar a Lumopolis no fue fácil, y aun así fue derribado tras un solo golpe.",
  ui_story_10_3_1_58_dialog_content = "Cierra la boca...",
  ui_story_10_3_1_59_dialog_content = "No necesito ser recordada.",
  ui_story_10_3_1_60_dialog_content = "Subestimar a tu enemigo siempre ha sido tu debilidad...",
  ui_story_10_3_1_61_dialog_content = "...",
  ui_story_10_3_1_62_dialog_content = "Mi único caso de negligencia... fue sobreestimar la mente de PlayerName.",
  ui_story_10_3_1_63_dialog_content = "Aprovechar las oportunidades, ganar fuerza, volverme poderosa...",
  ui_story_10_3_1_64_dialog_content = "En esa mente obstinada, nada de eso importó, ¡incluso esos Aurorians eran más valiosos!",
  ui_story_10_3_1_65_dialog_content = "Qué chiste. ¿Se hizo amigo de algunos Aurorians y se sintió más fuerte que nunca? ¡Qué patético!",
  ui_story_10_3_1_66_dialog_content = "Mostré mi sinceridad, y mi generosidad, pero ¿a dónde me llevó eso?",
  ui_story_10_3_1_67_dialog_content = "Oh, PlayerName, nada diferente de aquellos asquerosos Celestitas, que no podían distinguir lo bueno de lo malo.",
  ui_story_10_3_1_68_dialog_content = "Tontos, todos ellos.",
  ui_story_10_3_1_69_dialog_content = "Los liberaré de sus mentes tontas...",
  ui_story_10_3_1_70_dialog_content = "Los haré pagar, los llevaré a la muerte, con miedo y pesar.",
  ui_story_10_3_1_71_dialog_content = "¿Te sientes mejor? Vamos, dinos lo que has percibido.",
  ui_story_10_3_1_72_dialog_content = "Schummer comía Eclipsites...",
  ui_story_10_3_1_73_dialog_content = "¿Ah? Y yo que pensaba que realmente percibías algo malo, pero sólo era ella comiendo algunos Eclipsites.",
  ui_story_10_3_1_74_dialog_content = "No te preocupes, seguro que las lesiones le han recordado que llevaba unos días sin comer, así que está comiendo lo que puede.",
  ui_story_10_3_1_75_dialog_content = "¿Se puede comer Eclipsites? ¿No se rompen en pedazos después de morir?",
  ui_story_10_3_1_76_dialog_content = "Puedes darle un bocado o dos antes de que lo hagan, pero por lo que he oído, saben peor que el vómito de las bestias.",
  ui_story_10_3_1_77_dialog_content = "Quien pueda soportar comer un Eclipsite está definitivamente mal de la cabeza.",
  ui_story_10_3_1_78_dialog_content = "Pero por lo que sabemos de ellos, los Eclipsites no necesitan comer y no muestran ningún comportamiento caníbal.",
  ui_story_10_3_1_79_dialog_content = "Creo que está absorbiendo su energía... el Darkflow era especialmente espeso allí.",
  ui_story_10_3_1_80_dialog_content = "Busca una manera de curarse a sí misma. Debemos darnos prisa. Blegh...",
  ui_story_10_3_1_81_dialog_content = "Ugh... Sólo con escucharlos me dan ganas de vomitar.",
  ui_story_10_3_1_82_dialog_content = "Estoy bien, no creo que me quede nada por vomitar. Urk...",
  ui_story_10_3_1_83_dialog_content = "Yuck, aún tu jadeo seco es asqueroso... ¡Sólo mírate, tiemblas por todas partes!",
  ui_story_10_3_1_84_dialog_content = "Vamos...",
  ui_story_10_3_1_85_dialog_content = "Espera, ¡apenas puedes levantarte! ¡Vamos, siéntate unos minutos!",
  ui_story_10_3_1_86_dialog_content = "¡Sólo un rato!",
  ui_story_10_3_1_87_dialog_content = "Estaré bien. Todavía puedo ayudarlos...",
  ui_story_10_3_1_88_dialog_content = "Ya basta, niño. Dijimos descansa, así que descansa.",
  ui_story_10_3_1_89_dialog_content = "Si esta persona Schummer eligió curarse a sí misma en este momento, sólo significa que no puede huir.",
  ui_story_10_3_1_90_dialog_content = "Toma, bebe agua caliente.",
  ui_story_10_3_1_91_dialog_content = "¿Por qué no comer algo para recuperar fuerzas también? Trajimos algunas especialidades de Rediesel.",
  ui_story_10_3_1_92_dialog_content = "¡Bopper! ¡Ven aquí y reparte tu cecina de lagarto a todos!",
  ui_story_10_3_1_93_dialog_content = "¡S-seguro! Ya que Schummer recupera su energía, ¿por qué no hacemos lo mismo? ¡Ten, toma un poco!",
  ui_story_10_3_1_94_dialog_content = "No te pongas muy cómodo.",
  ui_story_10_3_1_95_dialog_content = "Sólo dame un paquete, e iré a explorar adelante.",
  ui_story_10_3_1_96_dialog_content = "Sí, ok. También son muy convenientes. ¡Puedes comerlos directamente del paquete! ¡Son dulces y picantes, y además son buenos para reponer fuerzas!",
  ui_story_10_3_1_97_dialog_content = "¿Ves, PlayerName? Hasta Carleen está dispuesta a comer, así que tú deberías hacerlo también.",
  ui_story_10_3_1_98_dialog_content = "Tu estómago debe estar bien vacío después de todo ese vómito. ¡No podrás luchar muy bien con el estómago vacío!",
  ui_story_10_3_1_99_dialog_content = "Lo siento, realmente no quiero comer nada después de eso. Quizá lo vomite de nuevo.",
  ui_story_10_3_1_100_dialog_content = "¿Ah? Ok... Entonces al menos bebe más agua, ¿sí?",
  ui_story_10_3_1_101_dialog_content = "Tenemos otra botella aquí. Tómala.",
  ui_story_10_3_1_102_dialog_content = "Una horda de Eclipsites adelante. Llegarán en cualquier momento.",
  ui_story_10_3_1_103_dialog_content = "No te preocupes por dar órdenes, PlayerName.",
  ui_story_10_3_1_104_dialog_content = "Mientras luchamos, tómate ese tiempo para recuperar el aliento.",
  ui_story_10_3_1_105_dialog_content = "¡Claro que sí! No dejaremos que ni un Eclipsite se te acerque, ¡así que siéntate y descansa!",
  ui_story_10_3_1_106_dialog_content = "¡Eclipsites avistados! ¡Prepárense para luchar!",
  ui_story_10_3_2_1_dialog_content = "¡PlayerName! ¿Acabas de dar órdenes?",
  ui_story_10_3_2_2_dialog_content = "¿No te dijimos que te sentaras y reunieras fuerzas?",
  ui_story_10_3_2_3_dialog_content = "Estoy bien. Me siento mejor ahora.",
  ui_story_10_3_2_4_dialog_content = "Además, establecer un vínculo mental con ustedes es mucho mejor que con Eclipsites.",
  ui_story_10_3_2_5_dialog_content = "Estos Eclipsites... Parece que volvieron a encontrar las ganas de luchar, ¿no?",
  ui_story_10_3_2_6_dialog_content = "Sí, parece que tendremos que eliminarlos mientras nos abrimos paso.",
  ui_story_10_3_2_7_dialog_content = "Vamos. Estoy mejor, lo prometo.",
  ui_story_10_3_2_8_dialog_content = "Lo siento mucho. Si no fuera porque te pedí que exploraras con tus poderes, no te habrías hecho daño.",
  ui_story_10_3_2_9_dialog_content = "No, no es tu culpa.",
  ui_story_10_3_2_10_dialog_content = "Es porque de repente percibí que el enemigo se entregaba a comer Eclipsites.",
  ui_story_10_3_2_11_dialog_content = "La próxima vez no me afectará.",
  ui_story_10_3_2_12_dialog_content = "Muy bien niño, parece que recuperaste algo de fuerza después de todo.",
  ui_story_10_3_2_13_dialog_content = "Entonces, ¿pudiste sentir a Forsakin antes o no?",
  ui_story_10_3_2_14_dialog_content = "Fue vago, pero percibí algo antes...",
  ui_story_10_3_2_15_dialog_content = "Creo que Forsakin y Schummer están en el mismo lugar ahora mismo.",
  ui_story_10_3_2_16_dialog_content = "Entonces, movámonos. Ahora todos tenemos el mismo destino.",
  ui_story_10_3_2_17_dialog_content = "<color=#e8d9bb>Whoosh.</color>",
  ui_story_10_3_2_18_dialog_content = "Este Colossus, es como si entre más avanzamos, más roto se pone...",
  ui_story_10_3_2_19_dialog_content = "Realmente parece que se derrumbará en cualquier momento. Ningún Colossus debería ser dañado así.",
  ui_story_10_3_2_20_dialog_content = "Bueno, fue golpeado por Damocles.",
  ui_story_10_3_2_21_dialog_content = "Además, Schummer le drenó hasta la última gota de energía.",
  ui_story_10_3_2_22_dialog_content = "Este Colossus ya está <color=#FFB400>muerto</color>...",
  ui_story_10_3_2_23_dialog_content = "Me dices que Schummer, como navegadora de este Colossus...",
  ui_story_10_3_2_24_dialog_content = "¿Mató su propio Colossus con sus propias manos?",
  ui_story_10_3_2_25_dialog_content = "Incluso los Eclipsites no se hacen daño entre sí, y ella sí. Si alguien puede hacer algo tan perverso, es ella.",
  ui_story_10_3_2_26_dialog_content = "Te creería si dices que va a destruir al Colossus, así que, ¿qué es lo que le drena su energía?",
  ui_story_10_3_2_27_dialog_content = "Está mal hasta la médula. PlayerName lo sabe mejor que nadie.",
  ui_story_10_3_2_28_dialog_content = "Vamos. Debemos evitar que siga recuperándose...",
  ui_story_10_7_1_1_dialog_content = "Absorber energía de otros Eclipsites es un buen método para aumentar el propio Darkflow.",
  ui_story_10_7_1_2_dialog_content = "Pero sólo algunos Eclipsites son capaces de dominar el arte de absorción del Darkflow...",
  ui_story_10_7_1_3_dialog_content = "...",
  ui_story_10_7_1_4_dialog_content = "¿Oh? Dormida ya, parece que todavía hay alguna esperanza para este experimento.",
  ui_story_10_7_1_5_dialog_content = "¿Quién fue que vino a hablarme de poder la última vez? Oh, ya lo recuerdo.",
  ui_story_10_7_1_6_dialog_content = "Alguien de Lumopolis... con cola de bicho... ¿Cómo se llamaba...?",
  ui_story_10_7_1_7_dialog_content = "¿<color=#FFB400>Boredom</color>?",
  ui_story_10_7_1_8_dialog_content = "<color=#e8d9bb>Whoosh.</color>",
  ui_story_10_7_1_9_dialog_content = "Ugh... ¿Otra corriente de viento?",
  ui_story_10_7_1_10_dialog_content = "No... esto es...",
  ui_story_10_7_1_11_dialog_content = "*Llanto*",
  ui_story_10_7_1_12_dialog_content = "¿Llanto?",
  ui_story_10_7_1_13_dialog_content = "¿Los Eclipsites también lloran?",
  ui_story_10_7_1_14_dialog_content = "Retrocedan, se acercan.",
  ui_story_10_7_1_15_dialog_content = "Este Eclipsite es aterrador.",
  ui_story_10_7_1_16_dialog_content = "Un momento... ¿Por qué me parece que he visto este Eclipsite antes?",
  ui_story_10_7_1_17_dialog_content = "¡¿No... no me digas que es otro Aurorian que se convirtió en Eclipsite?!",
  ui_story_10_7_1_18_dialog_content = "Esa apariencia, esas extremidades como raíces, y esa voz... Lo único que se me ocurre...",
  ui_story_10_7_1_19_dialog_content = "Esas hermanas, <color=#FFB400>Shelt</color> y <color=#FFB400>Shire</color>, se transformaron finalmente en ese monstruo.",
  ui_story_10_7_1_20_dialog_content = "¿Hermanas? ¿No es sólo un Eclipsite?",
  ui_story_10_7_1_21_dialog_content = "Vimos cómo se fusionaron a la fuerza.",
  ui_story_10_7_1_22_dialog_content = "Sí, seguían diciendo que \"el amo nos concedió el poder\", y ahora aquí es donde terminan.",
  ui_story_10_7_1_23_dialog_content = "*Llanto*",
  ui_story_10_7_1_24_dialog_content = "Um, parecen estar avanzando hacia nosotros, aunque muy lentamente... ¿Nos preparamos para contraatacar?",
  ui_story_10_7_1_25_dialog_content = "*Llantos* Matar...",
  ui_story_10_7_1_26_dialog_content = "¿Matar? ¿Acaban de decir \"matar\"? ¿Piensan matarnos?",
  ui_story_10_7_1_27_dialog_content = "No... Quieren ser liberadas.",
  ui_story_10_7_1_28_dialog_content = "<color=#FFB400>\"Mátennos\"</color>... Eso es lo que nos dijeron una vez.",
  ui_story_10_7_1_29_dialog_content = "Pero ahora, parece que siguen atrapadas en el dolor.",
  ui_story_10_7_1_30_dialog_content = "Sus cadáveres fueron arrastrados hasta aquí y devueltos a la vida para ser utilizados de nuevo.",
  ui_story_10_7_1_31_dialog_content = "Utilizando métodos tan crueles y sin escrúpulos una y otra vez. ¡Sólo alguien en verdad desquiciado haría esto!",
  ui_story_10_7_1_32_dialog_content = "¡Urgh!",
  ui_story_10_7_1_33_dialog_content = "A estas alturas, no queda ni una pizca de humanidad o conciencia en esa forma.",
  ui_story_10_7_1_34_dialog_content = "Acaba con ellas.",
  ui_story_10_7_1_35_dialog_content = "¡Y una vez hecho, buscaremos al monstruo responsable de esta atrocidad y lo enviaremos a la tumba!",
  ui_story_10_7_2_1_dialog_content = "¿S-se están calmando?",
  ui_story_10_7_2_2_dialog_content = "Sí. Ahora están muertas, por segunda vez.",
  ui_story_10_7_2_3_dialog_content = "Vice, PlayerName, busquen materiales inflamables.",
  ui_story_10_7_2_4_dialog_content = "Vamos a incinerarlas.",
  ui_story_10_7_2_5_dialog_content = "Espero podamos ayudarles a encontrar paz como hizo una vez <color=#FFB400>Gertzurde</color>.",
  ui_story_10_7_2_6_dialog_content = "Seguro. Echemos un vistazo.",
  ui_story_10_7_2_7_dialog_content = "¿Quién rayos es Gertzurde?",
  ui_story_10_7_2_8_dialog_content = "Un caballero de Lumopolis, y el amor de Shelt.",
  ui_story_10_7_2_9_dialog_content = "Él y Shelt se unieron a las filas de los Eclipsites, pero al final...",
  ui_story_10_7_2_10_dialog_content = "Se sacrificó para salvarnos.",
  ui_story_10_7_2_11_dialog_content = "Lumopolis, de nuevo... Aunque no sea el momento ni el lugar adecuado, tengo que preguntarte algo.",
  ui_story_10_7_2_12_dialog_content = "¿Por qué los de Lumopolis elegirían unirse a los Eclipsites?",
  ui_story_10_7_2_13_dialog_content = "No tienen que preocuparse por ser atacados por Eclipsites, sus vidas tampoco son tan duras.",
  ui_story_10_7_2_14_dialog_content = "¿No es extraño?",
  ui_story_10_7_2_15_dialog_content = "Ahora estamos trabajando todos juntos por un objetivo común, Sinsa.",
  ui_story_10_7_2_16_dialog_content = "Así que no saques a relucir cosas como ésta.",
  ui_story_10_7_2_17_dialog_content = "Está bien.",
  ui_story_10_7_2_18_dialog_content = "Sólo decía lo que pensaba. No siempre se tiene la suerte de hablar con alguien de Lumopolis todos los días.",
  ui_story_10_7_2_19_dialog_content = "En fin, si no te importa usar mi fuego, también puedo ayudar con la cremación.",
  ui_story_10_7_2_20_dialog_content = "Yo misma me encargaré de todas estas cosas, Sinsa. Tu atención no es necesaria.",
  ui_story_10_7_2_21_dialog_content = "Tampoco necesito tu ayuda.",
  ui_story_10_7_2_22_dialog_content = "No pensaba ayudar. Mientras sepas lo que debes hacer, eso me sirve.",
  ui_story_10_7_2_23_dialog_content = "Iré a vigilar.",
  ui_story_10_7_2_24_dialog_content = "...",
  ui_story_10_7_2_25_dialog_content = "Uh, iré ayudar a buscar cosas inflamables, también.",
  ui_story_10_7_2_26_dialog_content = "Sinsa puede ser un poco excesivo a veces, y no puede evitar decir lo que piensa...",
  ui_story_10_7_2_27_dialog_content = "Pero él no tiene nada en contra de ti o de tu gente.",
  ui_story_10_7_2_28_dialog_content = "Si entiendo.",
  ui_story_10_7_2_29_dialog_content = "Enciende el fuego.",
  ui_story_10_7_2_30_dialog_content = "Noche Blanca en lo alto...",
  ui_story_10_7_2_31_dialog_content = "En busca de su libertad, Shelt y Shire fueron dos hermanas que se extraviaron. Que encuentren la paz y la libertad que tanto anhelaban.",
  ui_story_10_7_2_32_dialog_content = "Deja que el juicio se reserve para quienes las engañaron y manipularon.",
  ui_story_10_7_2_33_dialog_content = "Y que <color=#FFB400>Schummer</color>, la autora de estos viles crímenes, sea la próxima en ser enviada a la tumba.",
  ui_story_10_7_2_34_dialog_content = "Puedo intentar encontrar el camino a seguir...",
  ui_story_10_7_2_35_dialog_content = "¿PlayerName? ¿Estás usando tus habilidades psíquicas de nuevo?",
  ui_story_10_7_2_36_dialog_content = "Sí.",
  ui_story_10_7_2_37_dialog_content = "¡Alto! ¿Y si te haces daño otra vez?",
  ui_story_10_7_2_38_dialog_content = "Urgh.",
  ui_story_10_7_2_39_dialog_content = "¡¿PlayerName?!",
  ui_story_10_7_2_40_dialog_content = "Profesor...",
  ui_story_10_7_2_41_dialog_content = "Espera, ¿qué estoy viendo aquí...?",
  ui_story_10_7_2_42_dialog_content = "Estoy bien, hallaré una forma de ir más adelante. No te preocupes.",
  ui_story_10_7_2_43_dialog_content = "Profesor Handro...",
  ui_story_10_7_2_44_dialog_content = "¿Qué rayos has hecho? ¡¿Por qué lo hiciste?!",
  ui_story_10_7_2_45_dialog_content = "¡¿Por qué mataste a tus compañeros?! ¡Contéstame!",
  ui_story_10_7_2_46_dialog_content = "No hice nada, profesor.",
  ui_story_10_7_2_47_dialog_content = "Lo que hice fue probar mi valor.",
  ui_story_10_7_2_48_dialog_content = "¡¿Qué sucede contigo?!",
  ui_story_10_7_2_49_dialog_content = "¿Probar tu valor? ¡¿Matando a tus compañeros?!",
  ui_story_10_7_2_50_dialog_content = "Otra vez no, profesor, siempre escucha a medias lo que la gente tiene que decir antes de juzgarla.",
  ui_story_10_7_2_51_dialog_content = "¡¿Tú?!",
  ui_story_10_7_2_52_dialog_content = "¡B-bien! ¡Habla, entonces!",
  ui_story_10_7_2_53_dialog_content = "Apostaron conmigo. ¡Esto era yo cumpliendo mi parte de la apuesta!",
  ui_story_10_7_2_54_dialog_content = "Esos tontos creyeron ser lo suficientemente fuertes para luchar contra los Eclipsites.",
  ui_story_10_7_2_55_dialog_content = "Así que apostamos, a ver quién era bastante valiente para salir.",
  ui_story_10_7_2_56_dialog_content = "¿Todo esto sucedió por eso?",
  ui_story_10_7_2_57_dialog_content = "Sólo salimos a echar un vistazo, profesor. Ninguno de nosotros esperaba encontrarse con Eclipsites...",
  ui_story_10_7_2_58_dialog_content = "¡Siempre me excluyeron! ¡Me miraban con desprecio! ¡Todo porque no podía usar mis habilidades psíquicas tan bien como ellos!",
  ui_story_10_7_2_59_dialog_content = "¡Usted siempre dijo que nunca debemos subestimar el potencial de otros, profesor! Pero, ¿acaso escucharon?",
  ui_story_10_7_2_60_dialog_content = "¡No! ¡No lo hicieron!",
  ui_story_10_7_2_61_dialog_content = "¡Pero encontré mi prueba al final! ¡La única que sobrevivió fui yo!",
  ui_story_10_7_2_62_dialog_content = "¡Significa soy la más fuerte!",
  ui_story_10_7_2_63_dialog_content = "*Suspira*",
  ui_story_10_7_2_64_dialog_content = "¡Que volvieras con vida fue suerte, Schummer!",
  ui_story_10_7_2_65_dialog_content = "Te lo he dicho muchas veces.",
  ui_story_10_7_2_66_dialog_content = "Los Celestitas hemos sido y siempre seremos una raza amable y pacífica.",
  ui_story_10_7_2_67_dialog_content = "Como tal, no necesitamos demostrarle nada a nadie.",
  ui_story_10_7_2_68_dialog_content = "Lo que más importa cuando se trata de fuerza no es quién es más fuerte, sino cómo nos apoyamos unos a otros, enfrentamos los peligros y duras realidades del mundo.",
  ui_story_10_7_2_69_dialog_content = "¿Encarar peligro? Profesor, ¿crees que esconderse en Eraveil y no atreverse a marcharse cuenta como afrontar un peligro?",
  ui_story_10_7_2_70_dialog_content = "Una vez más, malinterpretando mis palabras. Te he advertido más veces de las que puedo contar.",
  ui_story_10_7_2_71_dialog_content = "Hay innumerables Eclipsites deambulando por el mundo fuera de Eraveil.",
  ui_story_10_7_2_72_dialog_content = "No somos como los Aurorians. No podemos aprovechar el poder de Lumina para luchar o defendernos.",
  ui_story_10_7_2_73_dialog_content = "Sin una forma de defendernos, encontrarnos con un Eclipsite algo fuerte significa la muerte de nuestra especie.",
  ui_story_10_7_2_74_dialog_content = "Afortunadamente, tenemos a Eraveil y Colossi.",
  ui_story_10_7_2_75_dialog_content = "Eraveil nos protege, y Colossi pueden llevarnos muy por encima del suelo y lejos de los ataques Eclipsites.",
  ui_story_10_7_2_76_dialog_content = "Lo más valioso es que tenemos nuestras <color=#FFB400>habilidades psíquicas</color>, exclusivas de nuestra raza.",
  ui_story_10_7_2_77_dialog_content = "Con ellas, podemos sentir estelas de luz, entender pensamientos de nuestros compañeros y detectar a enemigos y peligros.",
  ui_story_10_7_2_78_dialog_content = "Pero sin las habilidades adecuadas, no tienes forma de usar tus habilidades psíquicas para detectar y escapar del peligro.",
  ui_story_10_7_2_79_dialog_content = "¡Que todos ustedes dejaran Eraveil así equivalía a un suicidio!",
  ui_story_10_7_2_80_dialog_content = "Detectar, escapar, ¡todos aquí son exactamente iguales!",
  ui_story_10_7_2_81_dialog_content = "¡¿Alguno de ustedes ha pensado alguna vez que haríamos si Eclipsites aparecieran aquí?!",
  ui_story_10_7_2_82_dialog_content = "¡¿Crees que Eraveil puede protegernos para siempre?!",
  ui_story_10_7_2_83_dialog_content = "Dime, ¿qué haríamos? ¿Abrigarnos en Colossi y volar? ¿Dónde iríamos?",
  ui_story_10_7_2_84_dialog_content = "¿En el mundo grande y malo afuera, donde moriríamos en cualquier momento?",
  ui_story_10_7_2_85_dialog_content = "¡¿Quién diablos te dijo que morirías en cualquier momento?!",
  ui_story_10_7_2_86_dialog_content = "¿No te lo he dicho ya suficientes veces? Mientras tengamos Colossi...",
  ui_story_10_7_2_87_dialog_content = "Basta, ya sé lo que vas a decir.",
  ui_story_10_7_2_88_dialog_content = "Profesor, la razón por la que somos una raza amable y pacifica es que carecemos de la fuerza para luchar por nosotros mismos.",
  ui_story_10_7_2_89_dialog_content = "*Suspiros* Siempre obstinada, ya veo. No puedo culparte, Schummer.",
  ui_story_10_7_2_90_dialog_content = "Algún día entenderás.",
  ui_story_10_7_2_91_dialog_content = "No entiendo. Y no creo hacerlo nunca.",
  ui_story_10_7_2_92_dialog_content = "Puedes irte ahora, profesor.",
  ui_story_10_7_2_93_dialog_content = "No me harás arrepentir de nada de lo que ha sucedido.",
  ui_story_10_7_2_94_dialog_content = "Necesitas tiempo para calmarte.",
  ui_story_10_7_2_95_dialog_content = "Los ancianos ya arreglaron para que se investigue el asunto.",
  ui_story_10_7_2_96_dialog_content = "Creo que no tenías intención de llevar a tus compañeros a la muerte.",
  ui_story_10_7_2_97_dialog_content = "Pero hasta que los ancianos decidan tu castigo, no tengo más remedio que mantenerte aquí bajo llave.",
  ui_story_10_7_2_98_dialog_content = "Además, este libro es de un amigo tuyo. Me pidió que te lo trajera.",
  ui_story_10_7_2_99_dialog_content = "¿Amigo? ¿Quién? No tengo amigos...",
  ui_story_10_7_2_100_dialog_content = "Es <color=#FFB400>Mendelson</color>. Se preocupa por ti. Sus notas fueron malas también.",
  ui_story_10_7_2_101_dialog_content = "Creo que puede comprender tus circunstancias y desea hacerse tu amigo.",
  ui_story_10_7_2_102_dialog_content = "¿Se preocupa por mí?",
  ui_story_10_7_2_103_dialog_content = "Schummer... Oro con todo mi corazón para que algún día te des cuenta de que todo el mundo te ama.",
  ui_story_10_7_2_104_dialog_content = "Reflexiona profundamente sobre lo que sucedió durante tu encierro y ayuno. Todo el mundo espera grandes cosas de ti, así que no los defraudes.",
  ui_story_10_7_2_105_dialog_content = "...",
  ui_story_10_7_2_106_dialog_content = "¿Darme cuenta que <color=#FFB400>todo mundo me ama</color>?",
  ui_story_10_7_2_107_dialog_content = "Siempre usan eso como excusa para atormentarme. Qué exasperante...",
  ui_story_10_7_2_108_dialog_content = "...",
  ui_story_10_7_2_109_dialog_content = "¿Un libro?",
  ui_story_10_7_2_110_dialog_content = "¡¿<color=#FFB400>Ada y el Colossus</color>?!",
  ui_story_10_7_2_111_dialog_content = "¡¿Qué tipo de broma es esta?! ¿Se burlan de mí porque saben que no puedo conectarme con un Colossus?",
  ui_story_10_7_2_112_dialog_content = "...",
  ui_story_10_7_2_113_dialog_content = "Mendelson...",
  ui_story_10_7_2_114_dialog_content = "Oh, el tipo cuyo cabello es aún más rojo que el mío, se ve aún más débil que yo.",
  ui_story_10_7_2_115_dialog_content = "Él también debe ser incapaz de acercarse a un Colossus.",
  ui_story_10_7_2_116_dialog_content = "<color=#e8d9bb>Tinteo</color>",
  ui_story_10_7_2_117_dialog_content = "¿Qué es esto?",
  ui_story_10_7_2_118_dialog_content = "¡¿<color=#FFB400>La llave</color>?!",
  ui_story_10_7_2_119_dialog_content = "Tsk. Esta puerta, podría romperla ahora mismo, si quisiera.",
  ui_story_10_8_1_1_dialog_content = "Después de aumentar el Darkflow de la Semilla.",
  ui_story_10_8_1_2_dialog_content = "Darkflow comenzará a hacerlos sentir más cómodos.",
  ui_story_10_8_1_3_dialog_content = "Mientras erosiona lentamente su discernimiento.",
  ui_story_10_8_1_4_dialog_content = "Generalmente, los sujetos de prueba que adquieren Darkflow revelan sus deseos fuertes más fácilmente.",
  ui_story_10_8_1_5_dialog_content = "En este punto, lo que más afecta su libre albedrío, es su apego a ciertas cosas...",
  ui_story_10_8_1_6_dialog_content = "¡No te apresures! Seguramente tus habilidades psíquicas pueden mejorarse con el entrenamiento.",
  ui_story_10_8_1_7_dialog_content = "Aviduz es especial por sí solo. Normalmente, un navegador adecuado se tarda mucho más en aparecer.",
  ui_story_10_8_1_8_dialog_content = "Mientras estudies mucho y te vuelvas más fuerte, tal vez algún día lo hagas.",
  ui_story_10_8_1_9_dialog_content = "Aviduz.... Donde estás...",
  ui_story_10_8_1_10_dialog_content = "Colossus.",
  ui_story_10_8_1_11_dialog_content = "Colossus.",
  ui_story_10_8_1_12_dialog_content = "Un Colossus normal...",
  ui_story_10_8_1_13_dialog_content = "No, esto no es...",
  ui_story_10_8_1_14_dialog_content = "Este tampoco...",
  ui_story_10_8_1_15_dialog_content = "¿Qué debería hacer?",
  ui_story_10_8_1_16_dialog_content = "Destruye todos sus núcleos de poder, pero deja uno intacto.",
  ui_story_10_8_1_17_dialog_content = "Es una orden.",
  ui_story_10_8_1_18_dialog_content = "Destruye sus núcleos de poder.",
  ui_story_10_8_1_19_dialog_content = "Destruye todos los núcleos de poder de Colossi, excepto el de Aviduz.",
  ui_story_10_8_1_20_dialog_content = "Te encontré.",
  ui_story_10_8_1_21_dialog_content = "Si destruyo tu plantilla de eco, me obedecerás, ¿verdad?",
  ui_story_10_8_1_22_dialog_content = "<color=#e8d9bb>Motor normal. Involucrando...</color>",
  ui_story_10_8_1_23_dialog_content = "Negro azabache, potente, especial.",
  ui_story_10_8_1_24_dialog_content = "<color=#e8d9bb>16%... 33%...</color>",
  ui_story_10_8_1_25_dialog_content = "<color=#FFB400>Dentro de Aviduz</color>",
  ui_story_10_8_1_26_dialog_content = "<color=#e8d9bb>100%... Comprometidos con éxito.</color>",
  ui_story_10_8_1_27_dialog_content = "¡Sabía que funcionaría!",
  ui_story_10_8_1_28_dialog_content = "Mientras te tenga, Aviduz.",
  ui_story_10_8_1_29_dialog_content = "¡SCHUMMER!",
  ui_story_10_8_1_30_dialog_content = "¡¿?!",
  ui_story_10_8_1_31_dialog_content = "¡¿Esa era tu voz?!",
  ui_story_10_8_1_32_dialog_content = "¿Es esa una forma apropiada de responder a tus superiores?",
  ui_story_10_8_1_33_dialog_content = "Debería estar diciendo: \"¡Sí, maestro Figerald! ¡Espero humildemente tu orden!”",
  ui_story_10_8_1_34_dialog_content = "Sí... <color=#FFB400>m-maestro Figerald</color>.",
  ui_story_10_8_1_35_dialog_content = "Incapaz de siquiera repetir mis palabras, imbécil.",
  ui_story_10_8_1_36_dialog_content = "Tsk, pero no puedo compararte con los demás, así que está bien.",
  ui_story_10_8_1_37_dialog_content = "Tienes valor especial para nosotros ahora.",
  ui_story_10_8_1_38_dialog_content = "Te acabas de convertir en un Eclipsite, todavía no entiendes lo que está sucediendo.",
  ui_story_10_8_1_39_dialog_content = "Así es como se comunican los Eclipsites, un poder que nos otorga la Madre.",
  ui_story_10_8_1_40_dialog_content = "Incluso si estamos en lugares completamente diferentes, aún puedo transmitirte mi voz.",
  ui_story_10_8_1_41_dialog_content = "¿Un poder de la Madre?",
  ui_story_10_8_1_42_dialog_content = "No olvides, fue la voluntad de mi madre que te eligiera y te concediera poder y una nueva oportunidad.",
  ui_story_10_8_1_43_dialog_content = "Que pudieras adaptarte a la Semilla tan rápidamente y ganar tal poder es un testimonio del impecable juicio de Madre.",
  ui_story_10_8_1_44_dialog_content = "Sin embargo, como estás ahora, no estás en condiciones de saber más que eso.",
  ui_story_10_8_1_45_dialog_content = "Solo si te vuelve aún más fuerte y demuestras tu devoción, obtendrás el privilegio de escuchar las enseñanzas de la Madre.",
  ui_story_10_8_1_46_dialog_content = "Ahora dime, ¿has terminado la tarea que te di?",
  ui_story_10_8_1_47_dialog_content = "Está terminado.",
  ui_story_10_8_1_48_dialog_content = "Muy bien. Ahora pilota tu Colossus a mi lado.",
  ui_story_10_8_1_49_dialog_content = "El ejército Eclipsite llego a Eraveil, como previsto. El juicio está a la mano.",
  ui_story_10_8_1_50_dialog_content = "No te queda mucho tiempo. No olvides que tienes un deber como enviada.",
  ui_story_10_8_1_51_dialog_content = "Erm... ¿Enviada?",
  ui_story_10_8_1_S1_dialog_content = "Sí. Debes llevarme a los Celestitas que crees que son dignos de nuestro poder.",
  ui_story_10_8_1_52_dialog_content = "Les daré la oportunidad de alcanzar <color=#FFB400>la salvación</color>.",
  ui_story_10_8_1_S2_dialog_content = "Mmm...",
  ui_story_10_8_1_S3_dialog_content = "Schummer... ¿Por qué dudas?",
  ui_story_10_8_1_S4_dialog_content = "De repente siento picazón.",
  ui_story_10_8_1_S5_dialog_content = "¿Picazón?",
  ui_story_10_8_1_S6_dialog_content = "¡Tsk, tsk, tsk! ¿Estás empezando a sentir algo? ¿Hay otras anomalías que deba conocer?",
  ui_story_10_8_1_S7_dialog_content = "Otras anomalías...",
  ui_story_10_8_1_S8_dialog_content = "No puedo abrir los ojos. La luz exterior es demasiado fuerte.",
  ui_story_10_8_1_S9_dialog_content = "De verdad... ¡Es impresionante que permitieras que la Semilla dentro de ti se transformara tan rápidamente!",
  ui_story_10_8_1_S10_dialog_content = "Siento que el Darkflow dentro de ti ha madurado.",
  ui_story_10_8_1_S11_dialog_content = "Deberías tener una nueva perspectiva. Vamos a Eraveil.",
  ui_story_10_8_1_S12_dialog_content = "Una nueva perspectiva.",
  ui_story_10_8_1_S13_dialog_content = "Sí. Has superado a los Celestitas. La sangre Celestita no te quedaba bien.",
  ui_story_10_8_1_S14_dialog_content = "Pero. Nací así.",
  ui_story_10_8_1_S15_dialog_content = "Puedes deshacerte de ello, así como puedes deshacerte de tu destino de ser para siempre una Celestita débil, condenada a la destrucción.",
  ui_story_10_8_1_S16_dialog_content = "Deshacerme de eso. ¿Qué debo hacer?",
  ui_story_10_8_1_S17_dialog_content = "¿Qué deberías hacer? Tsk, tsk, tsk...",
  ui_story_10_8_1_S18_dialog_content = "¡Debes desear la fuerza! ¡Solo así el poder oculto en tu interior te dirá lo que debes hacer!",
  ui_story_10_8_1_S19_dialog_content = "...",
  ui_story_10_8_1_S20_dialog_content = "Deseo, poder...",
  ui_story_10_8_1_S21_dialog_content = "Deseo de librarme de la debilidad.",
  ui_story_10_8_1_S22_dialog_content = "Transformación del deseo...",
  ui_story_10_8_1_S23_dialog_content = "No... No soy igual a ellos.",
  ui_story_10_8_1_S24_dialog_content = "¡Tengo todo ya!",
  ui_story_10_8_1_53_dialog_content = "¡Mira allá! ¡Apúrate!",
  ui_story_10_8_1_54_dialog_content = "¡Trae armas! ¡Trae armas!",
  ui_story_10_8_1_55_dialog_content = "¿Qué es toda esa conmoción?",
  ui_story_10_8_1_56_dialog_content = "¿Qué paso?",
  ui_story_10_8_1_57_dialog_content = "Entonces, aquí es donde te escondes.",
  ui_story_10_8_1_58_dialog_content = "¡¿Quién eres?!",
  ui_story_10_8_1_59_dialog_content = "¡Ja! ¡Soy yo Schummer! ¿No crees tus ojos?",
  ui_story_10_8_1_60_dialog_content = "¿Schummer? No... Tus cuernos y ojos. ¡Estas muy diferente!",
  ui_story_10_8_1_61_dialog_content = "No dudes de mí y no tengas miedo. Todo esto prueba de que soy la enviada elegida.",
  ui_story_10_8_1_62_dialog_content = "Fui elegida y he recibido un poder mucho mayor que el de los Celestitas.",
  ui_story_10_8_1_63_dialog_content = "¿Enviada? ¿Poder? ¡¿De qué estás hablando?!",
  ui_story_10_8_1_64_dialog_content = "...",
  ui_story_10_8_1_65_dialog_content = "¡Sabía que no entenderías! Recuerda: ¡Soy más fuerte que todos los Celestitas!",
  ui_story_10_8_1_66_dialog_content = "Ahora dime, ¿por qué me ayudaste? ¿Por qué pusiste esa llave en el libro que me diste?",
  ui_story_10_8_1_67_dialog_content = "Dijeron que te van a encerrar hasta que mueras.",
  ui_story_10_8_1_68_dialog_content = "Que si le decía algo al profesor, yo sería el próximo.",
  ui_story_10_8_1_69_dialog_content = "¡Somos hermanos! Y los hermanos no deberían...",
  ui_story_10_8_1_70_dialog_content = "Simpatía aburrida.",
  ui_story_10_8_1_71_dialog_content = "Entonces, ¿simpatizabas con mi difícil situación?",
  ui_story_10_8_1_72_dialog_content = "Cuando esos tipos me vieron encerrada, empezaron a decir todo tipo de mentiras, qué chiste.",
  ui_story_10_8_1_73_dialog_content = "No entiendo. ¿Qué pasó exactamente? ¿No te estaban intimidando?",
  ui_story_10_8_1_74_dialog_content = "Los estudiantes salieron de Eraveil sin permiso y fueron asesinados por Eclipsites. Los ancianos no dirán nada.",
  ui_story_10_8_1_75_dialog_content = "Tienen miedo, si todos saben que viene el juicio, nadie acatará sus estúpidas reglas.",
  ui_story_10_8_1_76_dialog_content = "Escucha bien para que no te hagas una mala idea. Nunca tuve la intención de aceptar ese libro o la llave que trae.",
  ui_story_10_8_1_77_dialog_content = "Aún tengo un corazón. Dado que trataste de ayudarme en el pasado, estoy dispuesta a darte la oportunidad de sobrevivir.",
  ui_story_10_8_1_78_dialog_content = "Y la oportunidad de obtener un poder increíble. Desde este momento.",
  ui_story_10_8_1_79_dialog_content = "Qué estás diciendo. ¿Qué tipo de oportunidad?",
  ui_story_10_8_1_80_dialog_content = "¿Aún no entiendes?",
  ui_story_10_8_1_81_dialog_content = "Ha llegado el fin de Eraveil, y los Eclipsites han traído consigo el juicio del mundo.",
  ui_story_10_8_1_82_dialog_content = "Todos van a morir.",
  ui_story_10_8_1_83_dialog_content = "¡Hazte Eclipsite como yo!",
  ui_story_10_8_1_84_dialog_content = "No, no... Y-yo...",
  ui_story_10_8_1_85_dialog_content = "¿Es este aquí?",
  ui_story_10_8_1_86_dialog_content = "Estoy ocupado, haz esto rápido.",
  ui_story_10_8_1_87_dialog_content = "!",
  ui_story_10_8_1_88_dialog_content = "Si te rehúsas, morirás.",
  ui_story_10_8_1_89_dialog_content = "Dilo alto, ¿quieres morir o vivir?",
  ui_story_10_8_1_90_dialog_content = "Yo...",
  ui_story_10_8_1_91_dialog_content = "Oh...",
  ui_story_10_8_1_92_dialog_content = "Un solo Eclipsite es más de lo que podemos manejar.",
  ui_story_10_8_1_93_dialog_content = "¡Handro! ¡Han encontrado Eclipsites en el Este también!",
  ui_story_10_8_1_94_dialog_content = "¡Sigan adelante! ¡Detrás tuyo!",
  ui_story_10_8_1_95_dialog_content = "¡Profesor! ¡Volví!",
  ui_story_10_8_1_96_dialog_content = "¡Ven conmigo!",
  ui_story_10_8_1_97_dialog_content = "¡¿Tú?!",
  ui_story_10_8_1_98_dialog_content = "¡¿Schummer?!",
  ui_story_10_8_1_99_dialog_content = "No tengas miedo, profesor.",
  ui_story_10_8_1_100_dialog_content = "Los ancianos nunca dijeron que Eraveil estaba condenada a ser destruida por los Eclipsites. Es por eso que todos tienen pánico.",
  ui_story_10_8_1_101_dialog_content = "¿De qué hablas?",
  ui_story_10_8_1_102_dialog_content = "El juicio de Eraveil en realidad estaba listo hace mucho.",
  ui_story_10_8_1_103_dialog_content = "El mundo tomó una decisión y su decisión es evolucionar.",
  ui_story_10_8_1_104_dialog_content = "Eclipsites no dañarán a alguien a quien no deban dañar. Mientras seas digno...",
  ui_story_10_8_1_105_dialog_content = "¡Puedes vivir a través de su juicio!",
  ui_story_10_8_1_106_dialog_content = "Me he convertido en un enviada de los Eclipsites. ¡Te recomendaré a ellos!",
  ui_story_10_8_1_107_dialog_content = "¡Cógela! ¡Amárrala rápido!",
  ui_story_10_8_1_108_dialog_content = "¡Rápido! ¡Todos juntos!",
  ui_story_10_8_1_109_dialog_content = "¿...?",
  ui_story_10_8_1_110_dialog_content = "¡Abre la puerta al cuarto oculto! ¡Apúrate!",
  ui_story_10_8_1_111_dialog_content = "Enciérrala. Toma a Schummer y enciérrala ahí.",
  ui_story_10_8_1_112_dialog_content = "...",
  ui_story_10_8_1_113_dialog_content = "¿Esta es tu respuesta?",
  ui_story_10_8_1_114_dialog_content = "Que cobarde.",
  ui_story_10_8_1_115_dialog_content = "Pero eso no importa.",
  ui_story_10_8_1_116_dialog_content = "Pronto lo sabrás y lamentarás.",
  ui_story_10_8_1_117_dialog_content = "¡Cuando lleguen todos lo lamentaran! Y luego vendrán a suplicarme...",
  ui_story_10_8_1_118_dialog_content = "Suplicar otra oportunidad.",
  ui_story_10_8_1_119_dialog_content = "¡Ah!",
  ui_story_10_8_1_120_dialog_content = "¡Corre! ¡Rápido por aquí!",
  ui_story_10_8_1_121_dialog_content = "¿Algún Colossus que aún se pueda mover?",
  ui_story_10_8_1_122_dialog_content = "¡Escapen si sienten al enemigo! ¡Llévense los niños!",
  ui_story_10_8_1_123_dialog_content = "Imposible, demasiados Eclipsites.",
  ui_story_10_8_1_124_dialog_content = "Ah... Que maravilloso sonido.",
  ui_story_10_8_1_125_dialog_content = "No desde que erradicamos a esos semi-humanos, que no eran mejores que los animales comunes.",
  ui_story_10_8_1_126_dialog_content = "Ha pasado demasiado tiempo desde que escuché esos gritos de agonía.",
  ui_story_10_8_1_127_dialog_content = "Es posible que estos Celestitas no sean tan ruidosos como los semi-humanos, pero sus gritos agudos son agradables también.",
  ui_story_10_8_1_128_dialog_content = "No esperaría menos de una raza amante de la música como ellos. Tsk, tsk, tsk.",
  ui_story_10_8_1_129_dialog_content = "Grrr...",
  ui_story_10_8_1_130_dialog_content = "¡Ve! ¡Haz que griten aún más por mí! ¡Mátalos a todos!",
  ui_story_10_8_1_131_dialog_content = "¡Gahhhh!",
  ui_story_10_8_1_132_dialog_content = "¡Trae los Colossi que aún se mueven!",
  ui_story_10_8_1_133_dialog_content = "¡Apúrate! ¡Ayuda sobrevivientes!",
  ui_story_10_8_1_134_dialog_content = "*Tose*",
  ui_story_10_8_1_135_dialog_content = "*Tose*",
  ui_story_10_8_1_136_dialog_content = "Hay un sobreviviente. Gracias a Dios.",
  ui_story_10_8_1_137_dialog_content = "¡Profesor! ¡Profesor!",
  ui_story_10_8_1_138_dialog_content = "Mendelson, estás vivo, vamos, tenemos que irnos.",
  ui_story_10_8_1_139_dialog_content = "Profesor, todos están muertos.",
  ui_story_10_8_1_140_dialog_content = "¿Podemos seguir, profesor? ¿Si podemos escapar?",
  ui_story_10_8_1_141_dialog_content = "Claro que sí. *Tose* ven conmigo.",
  ui_story_10_8_1_142_dialog_content = "Rápido por aquí. <color=#FFB400>Mantiz</color> está esperando.",
  ui_story_10_8_1_143_dialog_content = "...",
  ui_story_10_8_1_144_dialog_content = "¿Profesor?",
  ui_story_10_8_1_145_dialog_content = "Escúchame, Mendelson. Puedo sentir que todos han sido eliminados ya.",
  ui_story_10_8_1_146_dialog_content = "Voy a distraer a los Eclipsites que nos rodean y llevarlos lejos. Esa será tu oportunidad de subir a bordo del Mantiz y activarlo.",
  ui_story_10_8_1_147_dialog_content = "Dentro de Mantiz, hay una sala especial. Cuando escapes de Eraveil debes encontrar esa habitación especial.",
  ui_story_10_8_1_148_dialog_content = "En el interior un <color=#FFB400>módulo especial</color>. Ese módulo.",
  ui_story_10_8_1_149_dialog_content = "Puede cambiar las funciones cognitivas de un Colossus.",
  ui_story_10_8_1_150_dialog_content = "Si cae en las manos equivocadas, las consecuencias pueden ser desastrosas.",
  ui_story_10_8_1_151_dialog_content = "La única persona capaz de pilotar Mantiz se fue. Eres el único que queda.",
  ui_story_10_8_1_152_dialog_content = "Pero no puedo. Nunca he podido conectarme con éxito con un Colossus.",
  ui_story_10_8_1_153_dialog_content = "Creo en ti, Mendelson. Tienes tanto potencial, todo lo que necesitas es confianza.",
  ui_story_10_8_1_154_dialog_content = "Notamos tu idoneidad para pilotar Mantiz y originalmente teníamos la intención de convertirte en su próximo Navegador.",
  ui_story_10_8_1_155_dialog_content = "Pero profesor, puedes conectarte con Colossi. ¿No sería mejor si fuéramos juntos?",
  ui_story_10_8_1_156_dialog_content = "No puedo ir contigo, Mendelson. <color=#FFB400>Liebowitz</color> todavía me espera.",
  ui_story_10_8_1_157_dialog_content = "Creo en tí. Se que podrás activarlo.",
  ui_story_10_8_1_158_dialog_content = "Dentro de Mantiz hay dos guardias. <color=#FFB400>Philex</color> y <color=#FFB400>Vani</color>. Ellos te ayudarán y te harán compañía.",
  ui_story_10_8_1_159_dialog_content = "Yo... Pero Profesor. ¡No puedo hacerlo solo! Nunca he podido conectarme con...",
  ui_story_10_8_1_160_dialog_content = "Sé que puedes hacerlo y hacerlo bien. ¡No es el momento de dudar de ti mismo!",
  ui_story_10_8_1_161_dialog_content = "¡Pero esos Eclipsites están en todas partes! Y también hay uno que parece particularmente peligroso.",
  ui_story_10_8_1_162_dialog_content = "Incluso si logro activar el Colossus, no podré escapar.",
  ui_story_10_8_1_163_dialog_content = "Vamos a morir, a este paso, todos vamos a morir.",
  ui_story_10_8_1_164_dialog_content = "Profesor, Schummer dijo que tenía una forma de sobrevivir.",
  ui_story_10_8_1_165_dialog_content = "¡¿Tú?! ¿Ella también vino a ti?",
  ui_story_10_8_1_166_dialog_content = "¿Quizás hay otra forma de mantenernos con vida?",
  ui_story_10_8_1_167_dialog_content = "Poder vivir el juicio final.",
  ui_story_10_8_1_168_dialog_content = "¿Te has divertido lo suficiente, Schummer?",
  ui_story_10_8_1_169_dialog_content = "Maestro Figerald, no me queda nadie para elegir.",
  ui_story_10_8_1_170_dialog_content = "Es una pena, pero he esperado lo suficiente.",
  ui_story_10_8_1_171_dialog_content = "No tendrán otra oportunidad de sobrevivir.",
  ui_story_10_8_1_172_dialog_content = "¡Tsk! ¡Tsk! ¡Tsk! En ese caso, ¡ven y sé testigo de la gloria del día del juicio!",
  ui_story_10_8_1_173_dialog_content = "¡El Eclipse está a mano!",
  ui_story_10_9_1_1_dialog_content = "¡¿PlayerName?!",
  ui_story_10_9_1_2_dialog_content = "El día del juicio y el <color=#FFB400>Eclipse</color>.",
  ui_story_10_9_1_3_dialog_content = "¿Día del juicio? ¿Qué significa eso? Concéntrate y cuéntanos lo que viste.",
  ui_story_10_9_1_4_dialog_content = "Lo he visto antes, la destrucción de Eraveil.",
  ui_story_10_9_1_5_dialog_content = "Todo es real.",
  ui_story_10_9_1_6_dialog_content = "Vi recuerdos de Schummer de Eraveil hace un rato. El día que fue atacado por los Eclipsites.",
  ui_story_10_9_1_7_dialog_content = "Schummer llevó a los Eclipsites a Eraveil.",
  ui_story_10_9_1_8_dialog_content = "El cielo se oscureció y hubo Eclipse.",
  ui_story_10_9_1_9_dialog_content = "Pero lo más importante, había un Eclipsite con figura humana llamado <color=#FFB400>Figerald</color>.",
  ui_story_10_9_1_10_dialog_content = "¡Ese Eclipsite lideró el ataque que destruyó todo Eraveil!",
  ui_story_10_9_1_11_dialog_content = "¿Estás bien?",
  ui_story_10_9_1_12_dialog_content = "Estoy bien. Hay una gran multitud de Eclipsites acercándose desde el frente. Debemos alistarnos para pelear.",
  ui_story_10_9_1_13_dialog_content = "¿Puedes sentir un ataque Eclipsite en un lugar tan silencioso como este?",
  ui_story_10_9_1_14_dialog_content = "¡Puedo oír algo! ¡Los Eclipsites llegaron!",
  ui_story_10_9_1_15_dialog_content = "Ja y yo pensé que estabas perdiendo la cabeza hace un momento.",
  ui_story_10_9_1_16_dialog_content = "No pensé que estuvieras en condiciones de evaluar el campo de batalla.",
  ui_story_10_9_1_17_dialog_content = "Pero déjame decirte algo, poner tu mirada en la venganza no será suficiente.",
  ui_story_10_9_1_18_dialog_content = "No pierdas la calma cuando veas a la persona que buscas. Solo mantén la calma y manda como siempre lo haces, y estaremos bien.",
  ui_story_10_9_1_19_dialog_content = "Lo haré. Gracias, Sinsa.",
  ui_story_10_9_1_20_dialog_content = "La enfrentaré con calma y racionalidad y pondré fin a las cosas.",
  ui_story_10_13_1_1_dialog_content = "Convertirse en un Eclipsite no garantiza la capacidad de controlar su poder.",
  ui_story_10_13_1_2_dialog_content = "Siempre existe la posibilidad de que Darkflow te consuma y te haga perder el control.",
  ui_story_10_13_1_3_dialog_content = "Incluso alguien como Schummer, que más que nada tiene sed de fuerza, solo puede obtener un poder limitado.",
  ui_story_10_13_1_4_dialog_content = "Si las cosas continúan de esta manera no será necesario registrar ninguno de los resultados de este experimento.",
  ui_story_10_13_1_5_dialog_content = "(Hablando Eclipsiano) ¡Señora mía! ¿Qué hacemos ahora?",
  ui_story_10_13_1_6_dialog_content = "(Hablando Eclipsiano) Los Aurorians llegarán aquí muy pronto.",
  ui_story_10_13_1_7_dialog_content = "Parece que ya no puedo confiar en que Schummer progrese por su cuenta.",
  ui_story_10_13_1_8_dialog_content = "Tendré que animarla.",
  ui_story_10_13_1_9_dialog_content = "Sigue viendo a los Aurorians.",
  ui_story_10_13_1_10_dialog_content = "(Eclipsian) Entendido.",
  ui_story_10_13_1_11_dialog_content = "Schummer.",
  ui_story_10_13_1_12_dialog_content = "Silencio.",
  ui_story_10_13_1_13_dialog_content = "¿Aún dormida?",
  ui_story_10_13_1_14_dialog_content = "¿Ah?",
  ui_story_10_13_1_15_dialog_content = "Limpia esa expresión tonta de tu rostro. Vengo a contarte los resultados del experimento.",
  ui_story_10_13_1_16_dialog_content = "¿Qué?",
  ui_story_10_13_1_17_dialog_content = "La conclusión es que eres un <color=#FFB400>fracaso total</color>.",
  ui_story_10_13_1_18_dialog_content = "For... sakin...",
  ui_story_10_13_1_19_dialog_content = "No te ofendas Schummer. Solo te estoy diciendo la verdad objetiva del asunto.",
  ui_story_10_13_1_20_dialog_content = "Has consumido todo el poder de Aviduz y un montón de Eclipsites, pero aún no has completado tu transformación.",
  ui_story_10_13_1_21_dialog_content = "Consumí... ¿Aviduz?",
  ui_story_10_13_1_22_dialog_content = "Es cierto. ¿Ves esta cápsula de cura? Está conectada a tu preciosa Aviduz.",
  ui_story_10_13_1_23_dialog_content = "La usaste para succionar todo el poder de él. Aviduz ahora no es más que una enorme pieza de chatarra.",
  ui_story_10_13_1_24_dialog_content = "Por qué, por qué no me dijiste.",
  ui_story_10_13_1_25_dialog_content = "Porque sé que te preocupas mucho por este Colossus.",
  ui_story_10_13_1_26_dialog_content = "Como un niño que finalmente obtiene el juguete que siempre ha querido, no estás dispuesto a soltarlo ni por un segundo. Esto es normal.",
  ui_story_10_13_1_27_dialog_content = "Y perfectamente obvio, también, que en el interior, todavía no eres más que una Celestita débil.",
  ui_story_10_13_1_28_dialog_content = "Por eso, cada vez que te encontrabas con PlayerName, no estabas dispuesta a matar ni a dejar ir a tu compatriota.",
  ui_story_10_13_1_29_dialog_content = "Después de todo, todavía estás encadenada por tu pasado. Qué pena.",
  ui_story_10_13_1_30_dialog_content = "Espero que no te hayas hecho ilusiones acerca de tener el control de tu propio destino, ¿verdad?",
  ui_story_10_13_1_31_dialog_content = "Eso no es algo de lo que los débiles son dignos.",
  ui_story_10_13_1_32_dialog_content = "Maldita seas.",
  ui_story_10_13_1_33_dialog_content = "Deberías molestarte.",
  ui_story_10_13_1_34_dialog_content = "Porque tienes la culpa de todo esto.",
  ui_story_10_13_1_35_dialog_content = "Por ser tan débil, tan inmadura, tan mediocre y tan tonta.",
  ui_story_10_13_1_36_dialog_content = "Matarte.",
  ui_story_10_13_1_37_dialog_content = "Te equivocas. No soy yo quien merece tu odio.",
  ui_story_10_13_1_38_dialog_content = "Te has olvidado.",
  ui_story_10_13_1_39_dialog_content = "¿Quiénes fueron los que te empujaron a este punto?",
  ui_story_10_13_1_40_dialog_content = "¿Recuerdas lo que dijo antes ese Celestita?",
  ui_story_10_13_1_41_dialog_content = "Siempre estás arrodillada en el suelo, suplicando poder.",
  ui_story_10_13_1_42_dialog_content = "Tu compatriota vio a través de ti.",
  ui_story_10_13_1_43_dialog_content = "Pero están aquí ahora.",
  ui_story_10_13_1_44_dialog_content = "Y cuando te encuentren, te matarán.",
  ui_story_10_13_1_45_dialog_content = "O puedes intentar suplicar su perdón.",
  ui_story_10_13_1_46_dialog_content = "Imposible.",
  ui_story_10_13_1_47_dialog_content = "Puedes rogarles que te dejen ir. Pedir a PlayerName que no te mate.",
  ui_story_10_13_1_48_dialog_content = "Ni en un millón de años.",
  ui_story_10_13_1_49_dialog_content = "Entonces, si no quieres morir.",
  ui_story_10_13_1_50_dialog_content = "Si quieres sobrevivir y matar a esos tontos.",
  ui_story_10_13_1_51_dialog_content = "Entonces solo queda una opción.",
  ui_story_10_13_1_52_dialog_content = "Necesitarás desear aún más poder.",
  ui_story_10_13_1_53_dialog_content = "Poder.",
  ui_story_10_13_1_54_dialog_content = "...",
  ui_story_10_13_1_55_dialog_content = "¿Schummer?",
  ui_story_10_13_1_56_dialog_content = "<size=45>¡Dame poder!</size>",
  ui_story_10_13_1_57_dialog_content = "...",
  ui_story_10_13_1_58_dialog_content = "Aunque anticipé que a estas alturas te resultaría difícil controlar tus emociones.",
  ui_story_10_13_1_59_dialog_content = "No esperaba que perdieras completamente el control de ti misma.",
  ui_story_10_13_1_60_dialog_content = "<size=45>¡Poder!</size>",
  ui_story_10_13_1_61_dialog_content = "Yá no hay esperanza.",
  ui_story_10_13_1_62_dialog_content = "<color=#e8d9bb>¡Gahhhhhh!</color>",
  ui_story_10_13_1_63_dialog_content = "¿Qué fue eso?",
  ui_story_10_13_1_64_dialog_content = "¿Puedes sentir lo que acaba de pasar, PlayerName?",
  ui_story_10_13_1_65_dialog_content = "No estoy seguro. Aún utilizando todas mis fuerzas, solo puedo obtener poca información sobre la mente de Schummer.",
  ui_story_10_13_1_66_dialog_content = "Hay pensamientos abstractos como fuerza, poder, especial pasando por su cabeza.",
  ui_story_10_13_1_67_dialog_content = "Algo más también. Un sentimiento intenso.",
  ui_story_10_13_1_68_dialog_content = "<color=#FFB400>Odio.</color>",
  ui_story_10_13_1_69_dialog_content = "¡Parece que se ha vuelto completamente loca!",
  ui_story_10_13_1_70_dialog_content = "¿Loca? Pensé que estaba muy loca luego que dijiste que estaba comiendo Eclipsites.",
  ui_story_10_13_1_71_dialog_content = "Sin embargo, suena muy extraño.",
  ui_story_10_13_1_72_dialog_content = "Tiene algo que ver con Forsakin.",
  ui_story_10_13_1_73_dialog_content = "Seguro le contó a Schummer de que estamos aquí.",
  ui_story_10_13_1_74_dialog_content = "Parece que está planeando luchar contra nosotros al final.",
  ui_story_10_13_1_75_dialog_content = "Si te está apuntando, es probable que tenga alguna forma de superar al resto de nosotros.",
  ui_story_10_13_1_76_dialog_content = "Viendo que Forsakin esta aquí. Es posible que no podamos protegerlo cuando sea el momento.",
  ui_story_10_13_1_77_dialog_content = "Iré a comprobar las cosas por ahora. Ustedes mantengan a PlayerName a toda costa.",
  ui_story_10_13_1_78_dialog_content = "Entendido.",
  ui_story_10_13_1_79_dialog_content = "¡Eclipsites, muertos!",
  ui_story_10_13_1_80_dialog_content = "¡Sácalos, rápido!",
  ui_story_10_13_1_81_dialog_content = "¡Graagh!",
  ui_story_10_13_1_82_dialog_content = "¿Qué está sucediendo? ¡Estos Eclipsites están todos alterados, de repente!",
  ui_story_10_13_1_83_dialog_content = "¿Fue por el terremoto de ahora?",
  ui_story_10_13_1_84_dialog_content = "Tengo un mal presentimiento sobre esto...",
  ui_story_10_13_1_85_dialog_content = "Aun Pact puede sentirlo.",
  ui_story_10_13_1_86_dialog_content = "Debe haber aparecido algo peligroso.",
  ui_story_10_13_1_87_dialog_content = "Lady Victoria ordena.",
  ui_story_10_13_1_88_dialog_content = "Debemos evitar involucrarnos en estas disputas, por el momento.",
  ui_story_10_13_1_89_dialog_content = "De acuerdo. Dado que se han recuperado muchas semillas, deberíamos dejar este lugar también.",
  ui_story_10_13_1_90_dialog_content = "La batalla está por comenzar.",
  ui_story_10_13_2_1_dialog_content = "¡Graagh!",
  ui_story_10_13_2_2_dialog_content = "...",
  ui_story_10_13_2_3_dialog_content = "¡¿Schummer?!",
  ui_story_10_13_2_4_dialog_content = "¿Ella simplemente se abalanzó sobre ese Eclipsite?",
  ui_story_10_13_2_5_dialog_content = "¿Se lo comió?",
  ui_story_10_13_2_6_dialog_content = "¿Es realmente Schummer? ¡Se ve muy diferente!",
  ui_story_10_13_2_7_dialog_content = "¡Schummer!",
  ui_story_10_13_2_8_dialog_content = "¡Sé todo sobre tus crímenes ahora!",
  ui_story_10_13_2_9_dialog_content = "No querías morir, así que te uniste a los Eclipsites, ¿no fue eso suficiente para ti?",
  ui_story_10_13_2_10_dialog_content = "¡¿Por qué tuviste que llevarlos a Eraveil?!",
  ui_story_10_13_2_11_dialog_content = "¡¿Por qué tuviste que matar a todos?!",
  ui_story_10_13_2_12_dialog_content = "...",
  ui_story_10_13_2_13_dialog_content = "Traidora... ¡Pagaras por todo!",
  ui_story_10_13_2_14_dialog_content = "¡Gahhhh!",
  ui_story_10_13_2_15_dialog_content = "¡Cuidado, PlayerName!",
  ui_story_10_13_2_16_dialog_content = "¿¡Graagh!?",
  ui_story_10_13_2_17_dialog_content = "¿Ella, esta atacando a esos Eclipsites?",
  ui_story_10_13_2_18_dialog_content = "...",
  ui_story_10_13_2_19_dialog_content = "Poder.",
  ui_story_10_13_2_20_dialog_content = "¿Qué está pasando aquí?",
  ui_story_10_13_2_21_dialog_content = "¡Es como si no pudiera vernos en absoluto!",
  ui_story_10_13_2_22_dialog_content = "¡Maldición, PlayerName! ¡Fue muy imprudente de tu parte justo ahora!",
  ui_story_10_13_2_23_dialog_content = "¡Eres el comandante, idiota! ¡¿Por qué atacarías delante de tus guerreros?!",
  ui_story_10_13_2_24_dialog_content = "Perdón, me dejé llevar, pero ya estoy tranquilo.",
  ui_story_10_13_2_25_dialog_content = "...",
  ui_story_10_13_2_26_dialog_content = "¿Qué hacemos ahora?",
  ui_story_10_13_2_27_dialog_content = "Schummer, me temo que hizo todos los trucos sucios que se le ocurrieron para obtener poder, pero al final, perdió la cabeza.",
  ui_story_10_13_2_28_dialog_content = "Todos estén atentos. El mejor chance es poner a prueba su fuerza antes de probar derribarla.",
  ui_story_10_13_2_29_dialog_content = "Grrr...",
  ui_story_10_13_2_30_dialog_content = "¡Está mirando hacia aquí! ¡¿Es porque terminó de comer esos Eclipsites?!",
  ui_story_10_13_2_31_dialog_content = "...",
  ui_story_10_13_2_32_dialog_content = "PlayerName...",
  ui_story_10_13_2_33_dialog_content = "¡Esta respondiendo!",
  ui_story_10_13_2_34_dialog_content = "PlayerName... Te mataré.",
  ui_story_10_13_2_35_dialog_content = "¡Primero tendrás que pasar por mí!",
  ui_story_10_13_2_36_dialog_content = "<anim type=Shake><size=50>¡PlayerName! ¡¡Muere!! ¡MUERE!</size></anim>",
  ui_story_10_14_2_1_dialog_content = "¡¿Ganamos?!",
  ui_story_10_14_2_2_dialog_content = "¡Ahora! ¡Acaba con ella!",
  ui_story_10_14_2_3_dialog_content = "¡Schummer! ¡Este es el fin!",
  ui_story_10_14_2_4_dialog_content = "¡Gahhhhhh!",
  ui_story_10_14_2_5_dialog_content = "Uf, qué sueño tan largo y repugnante.",
  ui_story_10_14_2_6_dialog_content = "Vamos, este es un recuerdo de hace 17 años.",
  ui_story_10_14_2_7_dialog_content = "Ya basta...",
  ui_story_10_14_2_8_dialog_content = "¡Basta!",
  ui_story_10_14_2_9_dialog_content = "¡Cuidado, PlayerName!",
  ui_story_10_14_2_10_dialog_content = "¡Boom!",
  ui_story_10_14_2_11_dialog_content = "*Tose*",
  ui_story_10_14_2_12_dialog_content = "¿Todavía puede luchar después de todo eso?",
  ui_story_10_14_2_13_dialog_content = "Debes estar bromeando. ¡¿Qué tan fuerte es?!",
  ui_story_10_14_2_14_dialog_content = "...",
  ui_story_10_14_2_15_dialog_content = "Vice, PlayerName, ¿están bien?",
  ui_story_10_14_2_16_dialog_content = "He estado mejor pero sí.",
  ui_story_10_14_2_17_dialog_content = "Estoy bien. Gracias por protegerme Bopper.",
  ui_story_10_14_2_18_dialog_content = "No te preocupes, con tal estés a salvo.",
  ui_story_10_14_2_19_dialog_content = "...",
  ui_story_10_14_2_20_dialog_content = "¿Esta muerta?",
  ui_story_10_14_2_21_dialog_content = "No, algo anda mal.",
  ui_story_10_14_2_22_dialog_content = "Ha, haha hahaha.",
  ui_story_10_14_2_23_dialog_content = "¡Schummer tiene control de si misma! ¡Todos listos para pelear de nuevo! ¡Todavía tiene fuerza de sobra!",
  ui_story_10_14_2_24_dialog_content = "¿Control?",
  ui_story_10_14_2_25_dialog_content = "Así es, antes estaba furiosa.",
  ui_story_10_14_2_26_dialog_content = "Pero ahora recuerdo que PlayerName estás aquí. ¡Me siento feliz ahora!",
  ui_story_10_14_2_27_dialog_content = "!",
  ui_story_10_14_2_28_dialog_content = "¡¿Qué raro es esa?!",
  ui_story_10_14_2_29_dialog_content = "¡PlayerName, atrás!",
  ui_story_10_14_2_30_dialog_content = "¡Bopper! ¡Dejo a PlayerName en tus manos! ¡Mantén nuestro comandante a salvo!",
  ui_story_10_14_2_31_dialog_content = "¡Entendido!",
  ui_story_10_14_2_32_dialog_content = "¡Oye aberración! ¡Dime donde esta Forsakin!",
  ui_story_10_14_2_33_dialog_content = "¿Aberración? ¿Es un insulto eso?",
  ui_story_10_14_2_34_dialog_content = "No importa, no puedo enojarme contigo, no lo vales.",
  ui_story_10_14_2_35_dialog_content = "Por Forsakin, No hay por qué preocuparse.",
  ui_story_10_14_2_36_dialog_content = "Juro que encontraré a esa cobarde y la haré pagar.",
  ui_story_10_14_2_37_dialog_content = "Pero antes de eso, tú y yo tenemos asuntos que resolver, PlayerName.",
  ui_story_10_14_2_38_dialog_content = "Y esta vez, prometo que usaré todo mi poder.",
  ui_story_10_14_2_39_dialog_content = "¡Para darte la muerte más dolorosa imaginable!",
  ui_story_10_14_2_40_dialog_content = "!",
  ui_story_10_14_2_41_dialog_content = "¿Planeas luchar contra ellos hasta morir? Eso no servirá.",
  ui_story_10_14_2_42_dialog_content = "¡¿Forsakin?!",
  ui_story_10_14_2_43_dialog_content = "Bien hecho Schummer. La Semilla respondió a tu voluntad de luchar y finalmente ha madurado.",
  ui_story_10_14_2_44_dialog_content = "Desafortunadamente, usaste la mayoría de tu poder en esa última pelea.",
  ui_story_10_14_2_45_dialog_content = "Si sigues así, todo el trabajo duro que puse en tu Semilla se desperdiciará.",
  ui_story_10_14_2_46_dialog_content = "¡¿Tú?!",
  ui_story_10_14_2_47_dialog_content = "Compórtate hasta que pueda cosechar mi Semilla.",
  ui_story_10_14_2_48_dialog_content = "¡Sinsa! ¡El objetivo de Forsakin es Schummer! ¡Está tras la <color=#FFB400>Semilla</color>!",
  ui_story_10_14_2_49_dialog_content = "¡Cómo si te dejara ir con eso!",
  ui_story_10_14_2_50_dialog_content = "No te preocupes tanto. Teniendo en cuenta mi objetivo, puedo salvarlos a todos.",
  ui_story_10_14_2_51_dialog_content = "Después de que obtenga mi Semilla, puedes lidiar con Schummer como quieras.",
  ui_story_10_14_2_52_dialog_content = "Todos obtienen lo que quieren y todos nos alejamos felices.",
  ui_story_10_14_2_53_dialog_content = "Además, no tienes forma de detenerme.",
  ui_story_10_14_2_54_dialog_content = "¡Cuidado, Sinsa!",
  ui_story_10_14_2_55_dialog_content = "¡¿Un ataque grande?!",
  ui_story_10_14_2_56_dialog_content = "Abajo, todos ustedes.",
  ui_story_10_14_2_57_dialog_content = "Ahora bien.",
  ui_story_10_14_2_58_dialog_content = "¿Últimas palabras antes de morir Schummer?",
  ui_story_10_14_2_59_dialog_content = "Dime cómo se siente haber perdido tu poder. O más bien, cómo se siente volver a ser Celestita.",
  ui_story_10_14_2_60_dialog_content = "Si tienes algo importante que decir, prometo escribirlo en mis notas de investigación.",
  ui_story_10_14_2_61_dialog_content = "...",
  ui_story_10_14_2_62_dialog_content = "Tch...",
  ui_story_10_14_2_63_dialog_content = "Muy bien.",
  ui_story_10_14_2_64_dialog_content = "Entonces, como recompensa por tu ayuda para concluir mi experimento, dejaré a Schummer en tus manos ahora.",
  ui_story_10_14_2_65_dialog_content = "Adiós, Schummer.",
  ui_story_10_14_2_66_dialog_content = "*Tose*",
  ui_story_10_14_2_67_dialog_content = "Sinsa, hagas lo que hagas. No la sigas.",
  ui_story_10_14_2_68_dialog_content = "Lo se.",
  ui_story_10_14_2_69_dialog_content = "¿Qué debemos hacer con Schummer, PlayerName? Es tu decisión.",
  ui_story_10_14_2_70_dialog_content = "No vivirá mucho más con esas heridas, apenas puede moverse en esa condición.",
  ui_story_10_14_2_71_dialog_content = "No pienses en lo que acaba de pasar. Haz lo que tu corazón te diga.",
  ui_story_10_14_2_72_dialog_content = "Si deseas, puedo hacer un carámbano para que puedas ajustar la cuenta personalmente, PlayerName.",
  ui_story_10_14_2_73_dialog_content = "Antes, tengo preguntas que necesitan respuesta.",
  ui_story_10_14_2_74_dialog_content = "¡Ja! ¿Ajustar cuentas? ¿Cuestionándome?",
  ui_story_10_14_2_75_dialog_content = "¿Porqué no me preguntas? Te respondo.",
  ui_story_10_14_2_76_dialog_content = "Dime, ¿dónde están esos tres módulos Colossus?",
  ui_story_10_14_2_77_dialog_content = "¡Vete al infierno!",
  ui_story_10_14_2_78_dialog_content = "¡Sucio Celestita! ¡¿Quieres mis módulos?! ¡Ni lo pienses!",
  ui_story_10_14_2_79_dialog_content = "¡No tienes idea de lo que valen! ¡Esas partes pertenecen a Aviduz y a nadie más!",
  ui_story_10_14_2_80_option_content = "Tienes razón, no lo sé, pero ¿es Aviduz tan importante para ti?",
  ui_story_10_14_2_81_dialog_content = "La razón por la que traicionaste a los Celestitas, ¿fue porque pudiste apoderarte de Aviduz?",
  ui_story_10_14_2_82_dialog_content = "No puedo culparte por no querer morir frente a un ataque Eclipsite.",
  ui_story_10_14_2_83_dialog_content = "¡Vive tu vida Eclipsite! ¡Vete y nunca vuelvas! ¡¿Por qué los guiaste a entrar en Eraveil?!",
  ui_story_10_14_2_84_dialog_content = "¡¿Por qué?!",
  ui_story_10_14_2_85_dialog_content = "Jeje...",
  ui_story_10_14_2_86_dialog_content = "No entenderías.",
  ui_story_10_14_2_87_dialog_content = "No has visto el final con tus propios ojos. No han sido testigos del verdadero juicio por ustedes mismos, no lo entenderían.",
  ui_story_10_14_2_88_dialog_content = "¡Eraveil, descendieron sobre el Eraveil!",
  ui_story_10_14_2_89_dialog_content = "¡No hay escape! ¡No había escapatoria para nadie!",
  ui_story_10_14_2_90_dialog_content = "Y lo mismo para ustedes. Todos serán destruidos.",
  ui_story_10_14_2_91_dialog_content = "¡Tonterías! ¡Los Eclipsites te lavaron el cerebro para que creyeras eso!",
  ui_story_10_14_2_92_dialog_content = "¡No dejes que te engañe, PlayerName!",
  ui_story_10_14_2_93_option_content = "¡No lo sé y no quiero saber! ¡Entrega los módulos!",
  ui_story_10_14_2_94_dialog_content = "¡No son tuyos para empezar!",
  ui_story_10_14_2_95_dialog_content = "¡Pertenecen a los Celestitas!",
  ui_story_10_14_2_96_dialog_content = "¡Fueron guardados por los Celestitas, para ellos!",
  ui_story_10_14_2_97_dialog_content = "¡Siempre han pertenecido a los Celestitas!",
  ui_story_10_14_2_98_dialog_content = "¡Una traidora como tú no tiene derecho a llevárselos!",
  ui_story_10_14_2_99_dialog_content = "...",
  ui_story_10_14_2_100_dialog_content = "¡No sabes nada!",
  ui_story_10_14_2_101_dialog_content = "¿Y qué eran esos Celestitas, de todos modos? ¡Un grupo de débiles que no sabían lo que era bueno para ellos!",
  ui_story_10_14_2_102_dialog_content = "¡Esos tontos no conocían el verdadero valor de los Colossi, el valor del poder!",
  ui_story_10_14_2_103_dialog_content = "¡Eran todos un montón de idiotas incompetentes y estúpidos, como tú!",
  ui_story_10_14_2_104_dialog_content = "¡Cállate!",
  ui_story_10_14_2_105_dialog_content = "PlayerName, ¡no pierdas la cabeza!",
  ui_story_10_14_2_106_dialog_content = "Lo se.",
  ui_story_10_14_2_107_dialog_content = "Yo sé...",
  ui_story_10_14_2_108_dialog_content = "Lo descubrí de camino aquí. El objetivo de los Eclipsites era destruir a Eraveil desde el principio.",
  ui_story_10_14_2_109_dialog_content = "De alguna manera, algún día, finalmente atacarían.",
  ui_story_10_14_2_110_dialog_content = "Schummer, no fuiste más que un lamentable sacrificio en todo esto.",
  ui_story_10_14_2_111_dialog_content = "¿Ah?",
  ui_story_10_14_2_112_dialog_content = "¿De qué estás hablando?",
  ui_story_10_14_2_113_dialog_content = "¡Fui elegida para vivir porque era digna!",
  ui_story_10_14_2_114_dialog_content = "¿Cómo están tus heridas, Vice?",
  ui_story_10_14_2_115_dialog_content = "¿E-eh? Están bien. Estoy bien.",
  ui_story_10_14_2_116_dialog_content = "¡Oye!",
  ui_story_10_14_2_117_dialog_content = "¡¿No me escuchaste?!",
  ui_story_10_14_2_118_dialog_content = "La mayoría de los Colossi son parecidos. Creo que puedo encontrar los módulos, Vice.",
  ui_story_10_14_2_119_dialog_content = "Dame una mano, ¿por favor?",
  ui_story_10_14_2_120_dialog_content = "Está bien...",
  ui_story_10_14_2_121_dialog_content = "...",
  ui_story_10_14_2_122_dialog_content = "...",
  ui_story_10_14_2_123_dialog_content = "¿Y tu venganza?",
  ui_story_10_14_2_124_dialog_content = "¿Dónde están esos gritos y maldiciones? ¿Ya no quieres venganza? ¿Solo porque no aceptas los Eclipsites?",
  ui_story_10_14_2_125_dialog_content = "Oh, ¿entonces crees que vas a tomar los módulos, matarme, irte a casa y tomar el té con tus queridos amigos?",
  ui_story_10_14_2_126_dialog_content = "Solo di la palabra, PlayerName, y la callaré muy rápido.",
  ui_story_10_14_2_127_dialog_content = "¡Ignórala! Tienes que cuidar tus heridas, Sinsa.",
  ui_story_10_14_2_128_dialog_content = "Bopper, ¿te importaría ayudarme a recuperar los módulos también?",
  ui_story_10_14_2_129_dialog_content = "Bien...",
  ui_story_10_14_2_130_dialog_content = "¡Ja! Jajaja...",
  ui_story_10_14_2_131_dialog_content = "No esperaba menos de una raza amable y pacífica.",
  ui_story_10_14_2_132_dialog_content = "Los Celestitas son tontos.",
  ui_story_10_14_2_133_dialog_content = "Carleen, hazme un carámbano por favor.",
  ui_story_10_14_2_134_dialog_content = "Entendido.",
  ui_story_10_14_2_135_dialog_content = "...",
  ui_story_10_14_2_136_dialog_content = "Dime, Schummer, ¿quién es <color=#FFB400>Figerald</color>?",
  ui_story_10_14_2_137_dialog_content = "¿Y qué es el <color=#FFB400>Eclipse</color>?",
  ui_story_10_14_2_138_dialog_content = "!",
  ui_story_10_14_2_139_dialog_content = "¡¿Viste mis recuerdos?!",
  ui_story_10_14_2_140_dialog_content = "Así es, pero desafortunadamente solo pude ver partes de ellos.",
  ui_story_10_14_2_141_dialog_content = "Por eso voy a sacar el resto de la historia directamente de tu boca.",
  ui_story_10_14_2_142_dialog_content = "...",
  ui_story_10_14_2_143_dialog_content = "Jajaja...",
  ui_story_10_14_2_144_dialog_content = "Está bien. Acércate y te lo diré.",
  ui_story_10_14_2_145_dialog_content = "Un poco más cerca nada más.",
  ui_story_10_14_2_146_dialog_content = "¿No vas a sacarme de mi miseria con ese carámbano, de todos modos?",
  ui_story_10_14_2_147_dialog_content = "¡Algo no está bien, PlayerName! ¡No caigas en sus trucos!",
  ui_story_10_14_2_148_dialog_content = "No te preocupes, no pensaba acercarme a ella.",
  ui_story_10_14_2_149_dialog_content = "Es muy tarde ahora.",
  ui_story_10_14_2_150_dialog_content = "Grrr...",
  ui_story_10_14_2_151_dialog_content = "Grrr...",
  ui_story_10_14_2_152_dialog_content = "¡Detrás tuyo!",
  ui_story_10_14_2_153_dialog_content = "¡Graagh!",
  ui_story_10_14_2_154_dialog_content = "Hahaha haha.",
  ui_story_10_14_2_155_dialog_content = "¡Te dije que fui elegida! ¡Soy la enviada del Eclipse!",
  ui_story_10_14_2_156_dialog_content = "Ven, ven y rodéalos.",
  ui_story_10_14_2_157_dialog_content = "Grrr...",
  ui_story_10_14_2_158_dialog_content = "Grrr...",
  ui_story_10_14_2_159_dialog_content = "Al final, yo gano.",
  ui_story_10_14_2_160_dialog_content = "PlayerName.",
  ui_story_10_14_2_161_dialog_content = "Competencia, evolución, ¡la única forma de darse cuenta de esto es pisar la cabeza de otras personas!",
  ui_story_10_14_2_162_dialog_content = "¡Tú y Eraveil son los reales sacrificios aquí!",
  ui_story_10_14_2_163_dialog_content = "¡Los superé a todos, superé estas pruebas y ahora me he vuelto imparable!",
  ui_story_10_14_2_164_dialog_content = "...",
  ui_story_10_14_2_165_dialog_content = "Todos, prepárense para retirarse.",
  ui_story_10_14_2_166_dialog_content = "¡¿Qué?! ¡No vamos a tener otra oportunidad como esta! ¡Luchemos!",
  ui_story_10_14_2_167_dialog_content = "Es obvio que ninguno de nosotros está en condiciones de defenderse de tantos Eclipsites ahora, con todas nuestras heridas.",
  ui_story_10_14_2_168_dialog_content = "Todos deberían saberlo mejor que yo.",
  ui_story_10_14_2_169_dialog_content = "Quiero mi venganza, pero no voy a sacrificar a ninguno de ustedes por ella.",
  ui_story_10_14_2_170_dialog_content = "¿Retirada? ¡Los invito! Me encantaría verlo por mí misma.",
  ui_story_10_14_2_171_dialog_content = "¡Quién será más rápido, mis Eclipsites o ustedes, tontos heridos!",
  ui_story_10_14_2_172_dialog_content = "¡Háganlos pedazos!",
  ui_story_10_14_2_173_dialog_content = "Grrr...",
  ui_story_10_14_2_174_dialog_content = "¿¡Que están esperando!? ¡Atáquenlos!",
  ui_story_10_14_2_175_dialog_content = "¡Graagh!",
  ui_story_10_14_2_176_dialog_content = "¡¿Qué?!",
  ui_story_10_14_2_177_dialog_content = "¡Argh! ¡Déjame ir!",
  ui_story_10_14_2_178_dialog_content = "¡A mi no! ¡No!",
  ui_story_10_14_2_179_dialog_content = "¡Nooo!",
  ui_story_10_14_2_180_dialog_content = "¡Graagh!",
  ui_story_10_14_2_181_dialog_content = "...",
  ui_story_10_14_2_182_dialog_content = "No hay tiempo que perder. ¡Deberíamos irnos!",
  ui_story_10_14_2_183_dialog_content = "¡De lo contrario seguimos nosotros!",
  ui_story_10_14_2_184_dialog_content = "¡PlayerName!",
  ui_story_10_14_2_185_dialog_content = "¡Saquen a PlayerName de aquí! ¡Ve!",
  ui_story_10_14_2_186_dialog_content = "¡Vamos!",
  ui_story_10_14_2_187_dialog_content = "Este fin.",
  ui_story_10_14_2_188_dialog_content = "(¡No lo acepto!)",
  ui_story_10_14_2_189_dialog_content = "(Trabajé tan duro para sobrevivir y ganarme todo esto.)",
  ui_story_10_14_2_190_dialog_content = "(¡Todos mienten!)",
  ui_story_10_14_2_191_dialog_content = "(¡Todo es falso!)",
  ui_story_10_14_2_192_dialog_content = "(¡Poder falso! ¡Falso juicio!)",
  ui_story_10_14_2_193_dialog_content = "(Forsakin, Figerald, el Eclipse)",
  ui_story_10_14_2_194_dialog_content = "(Desde el principio, nunca planearon dejarme ir.)",
  ui_story_10_14_2_195_dialog_content = "(Malditos sean todos.)",
  ui_story_10_14_2_196_dialog_content = "(Raza débil que estaba destinada a ser aniquilada.)",
  ui_story_10_14_2_197_dialog_content = "(Los Celestitas fueron maldecidos, desde que nacieron.)",
  ui_story_10_14_2_198_dialog_content = "(Y no eres diferente, morirás de una muerte horrible y trágica, como yo.)",
  ui_story_10_14_2_199_dialog_content = "(Te maldigo.)",
  ui_story_10_14_2_200_dialog_content = "(PlayerName.)",
  ui_story_10_14_2_201_dialog_content = "(Acepta el terror de tu destrucción predestinada.)",
  ui_story_10_14_2_202_dialog_content = "(<color=#FFB400>¡El Eclipse hace mucho que llegó!</color>)",
  ui_story_10_15_1_1_dialog_content = "(¿Qué más puedo hacer?)",
  ui_story_10_15_1_2_dialog_content = "(Ya esta muerta.)",
  ui_story_10_15_1_3_dialog_content = "(Comida por Eclipsites. Qué forma tan miserable de morir.)",
  ui_story_10_15_1_4_dialog_content = "¿Qué hacemos ahora? Que debo hacer.)",
  ui_story_10_15_1_5_dialog_content = "Grrr...",
  ui_story_10_15_1_6_dialog_content = "(Todos están heridos, y estos Eclipsites no nos dejarán ir tan fácilmente.)",
  ui_story_10_15_1_7_dialog_content = "(Al igual que lo que hizo el Eclipse.)",
  ui_story_10_15_1_8_dialog_content = "(Todos fueron masacrados ese día.)",
  ui_story_10_15_1_9_dialog_content = "¿Qué hacemos?",
  ui_story_10_15_1_10_dialog_content = "¡Corre!",
  ui_story_10_15_1_11_dialog_content = "¡Levanta a PlayerName!",
  ui_story_10_15_1_12_dialog_content = "¡Vamos! Vamos a salir de aquí.",
  ui_story_10_15_1_13_dialog_content = "¡Corre! ¡Por donde vinimos!",
  ui_story_10_15_1_14_dialog_content = "Los Eclipsites nos están ganando.",
  ui_story_10_15_1_15_dialog_content = "¡Yo traeré la fuerza!",
  ui_story_10_15_1_16_dialog_content = "¡Graagh!",
  ui_story_10_15_1_17_dialog_content = "¡¿Carleen?!",
  ui_story_10_15_1_18_dialog_content = "*Tose* ¡Todo bien, corre!",
  ui_story_10_15_1_19_dialog_content = "Justo las cosas están a punto de terminar y hay más problemas.",
  ui_story_10_15_1_20_dialog_content = "...",
  ui_story_10_15_1_21_dialog_content = "¿Nos persiguen hasta aquí? ¡Qué persistente!",
  ui_story_10_15_1_22_dialog_content = "¡Graagh!",
  ui_story_10_15_1_23_dialog_content = "!",
  ui_story_10_15_1_24_dialog_content = "¡PlayerName! ¡Cálmate!",
  ui_story_10_15_1_25_dialog_content = "¡Necesitamos ayuda!",
  ui_story_10_15_1_26_dialog_content = "...",
  ui_story_10_15_1_27_dialog_content = "...",
  ui_story_10_15_1_28_dialog_content = "¡Vice, los Eclipsites están bloqueando el camino! ¡Derríbalos!",
  ui_story_10_15_1_29_dialog_content = "¡Carleen, primero crea algo de distancia, flanquea por la parte trasera izquierda y ataca!",
  ui_story_10_15_1_30_dialog_content = "¡Torrente rápido!",
  ui_story_10_15_1_31_dialog_content = "¡Entendido!",
  ui_story_10_15_1_32_dialog_content = "¡Graagh!",
  ui_story_10_15_1_33_dialog_content = "¡Ya es hora de que recuperes el sentido!",
  ui_story_10_15_1_34_dialog_content = "Lo siento, Schummer logró entrar a mi cabeza antes de que ella muriera. Me confundió un poco.",
  ui_story_10_15_1_35_dialog_content = "No es necesario disculparse, solo intente recuperar la compostura lo antes posible.",
  ui_story_10_15_1_36_dialog_content = "Aún no hemos terminado con esto.",
  ui_story_10_15_1_37_dialog_content = "Aún necesito informar a Lumopolis y tú aún necesitas reparar tu Soroz.",
  ui_story_10_15_1_38_dialog_content = "¡Así que eliminemos estos Eclipsites y salgamos de aquí con vida!",
  ui_story_10_15_1_39_dialog_content = "Absolutamente correcto.",
  ui_story_10_15_1_40_dialog_content = "Me siento como yo de nuevo. ¡Puedo ayudarles a todos!",
  ui_story_10_15_1_41_dialog_content = "Me alegro mucho de que estés mejor PlayerName.",
  ui_story_10_15_1_42_dialog_content = "¡Pero el Eclipsite!",
  ui_story_10_15_1_43_dialog_content = "¡Gahhhhhh!",
  ui_story_10_15_1_44_dialog_content = "Quiero decir que la muerte no asusta.",
  ui_story_10_15_1_45_dialog_content = "¡Pero todavía tengo una hermanita esperándome en casa!",
  ui_story_10_15_1_46_dialog_content = "<size=45>¡Estamos luchando a muerte ahora, todos! ¡Ninguno debería morir!</size>",
  ui_story_10_15_1_47_dialog_content = "¡Baja la voz, Sinsa! ¡No eres tú quien da órdenes aquí!",
  ui_story_10_15_1_48_dialog_content = "Grrr...",
  ui_story_10_15_1_49_dialog_content = "¡Graagh!",
  ui_story_10_15_1_50_dialog_content = "¡Ven aquí!",
  ui_story_10_15_1_51_dialog_content = "¡¿Los Eclipsites están sendo succionados?!",
  ui_story_10_15_1_52_dialog_content = "¡Abajo!",
  ui_story_10_15_1_53_dialog_content = "¡Graagh!",
  ui_story_10_15_1_54_dialog_content = "¡Sinsa! ¡Brock está aquí para rescatarte!",
  ui_story_10_15_1_55_dialog_content = "¡Jajaja! Nunca pensaste que verías ese día, ¿eh? ¡Jajajaja!",
  ui_story_10_15_1_56_dialog_content = "¡Cuidado con la explosión!",
  ui_story_10_15_1_57_dialog_content = "¡Waaaaah!",
  ui_story_10_15_1_58_dialog_content = "¡Oye, mira dónde disparas esa cosa! ¡Casi me haces volar!",
  ui_story_10_15_1_59_dialog_content = "¡Tú eres el que arrastró a todos los Eclipsites hasta aquí sin acabar con ellos!",
  ui_story_10_15_1_60_dialog_content = "¿Qué es esto?",
  ui_story_10_15_1_61_dialog_content = "Jaja...",
  ui_story_10_15_1_62_dialog_content = "Lo siento parece que mis amigos de Rediesel Wrench están aquí para ayudar.",
  ui_story_10_15_1_63_dialog_content = "Son fuertes, no me malinterpreten, solo un poco ruidosos, eso es todo.",
  ui_story_10_15_1_64_dialog_content = "¡Estamos salvados! ¡Son increíbles!",
  ui_story_10_15_1_65_dialog_content = "Sí... estamos a salvo.",
  ui_story_10_15_1_66_dialog_content = "¡Vaya, una pelea agotadora! Hay demasiados de ellos Eclipsites.",
  ui_story_10_15_1_67_dialog_content = "¡Oye, Sinsa! ¿Adivina cómo estamos acá? Te lo diré, todo empezó cuando esa montaña tembló.",
  ui_story_10_15_1_68_dialog_content = "¡Jefe! ¡¿Estás bien?!",
  ui_story_10_15_1_69_dialog_content = "Estoy bien, estos son solo rasguños.",
  ui_story_10_15_1_70_dialog_content = "¡Wow, súper Colossus!",
  ui_story_10_15_1_71_dialog_content = "¡Todo esto valdrá la pena si podemos arrastrar esto con nosotros!",
  ui_story_10_15_1_72_dialog_content = "¡Todos ustedes, vengan aquí y ayúdenme a romperlo para que podamos moverlo!",
  ui_story_10_15_1_73_dialog_content = "¡Espera un segundo!",
  ui_story_10_15_1_74_dialog_content = "¿Eres de Lumopolis?",
  ui_story_10_15_1_75_dialog_content = "Lo siento Odi, no tuve la oportunidad de presentarte antes.",
  ui_story_10_15_1_76_dialog_content = "Esta es Carleen, de Lumopolis. Esos dos son Vice y PlayerName.",
  ui_story_10_15_1_77_dialog_content = "Espera, espera, espera... Jefe, ¿no es esta Carleen, de Lumopolis, la Capitana de los Guardianes?",
  ui_story_10_15_1_78_dialog_content = "¡Ponle un calcetín, Brock!",
  ui_story_10_15_1_79_dialog_content = "Todos somos socios de armas aquí, hoy.",
  ui_story_10_15_1_80_dialog_content = "¿No es así, Carleen?",
  ui_story_10_15_1_81_dialog_content = "...",
  ui_story_10_15_1_82_dialog_content = "Entonces, ¿también están detrás de este Colossus?",
  ui_story_10_15_1_83_dialog_content = "Si es así, digo que lo dividamos según quién hizo más trabajo. ¿Suena bien?",
  ui_story_10_15_1_84_dialog_content = "Tomaré la decisión, mantengan la boca cerrada y escuchen, todos ustedes.",
  ui_story_10_15_1_85_dialog_content = "Si aún tienes dudas, me ocuparé de ellas cuando este de regreso en nuestra base.",
  ui_story_10_15_1_86_dialog_content = "¡PlayerName!",
  ui_story_10_15_1_87_dialog_content = "¿Quieres este Colossus negro? ¡Ayudaremos a traerlo si lo haces!",
  ui_story_10_15_1_88_dialog_content = "¿Eh?",
  ui_story_10_15_1_89_dialog_content = "¿Qué, todavía aturdido de antes? ¡Consíguelo, chico!",
  ui_story_10_15_1_90_dialog_content = "Estoy bien. He estado bien por un tiempo.",
  ui_story_10_15_1_91_dialog_content = "Bueno, entonces.",
  ui_story_10_15_1_92_dialog_content = "Lo que intento decir es que esta cosa debería ser tuya. Después de todo, es un Colossus de los Celestitas.",
  ui_story_10_15_1_93_dialog_content = "Sin embargo, si pudiera dar una sugerencia.",
  ui_story_10_15_1_94_dialog_content = "¿Qué es eso?",
  ui_story_10_15_1_95_dialog_content = "¿Por qué no te unes a Rediesel Wrench? ¡Eso haría arrastrar esto de regreso a nuestra base más justificable!",
  ui_story_10_15_1_96_dialog_content = "Yo...",
  ui_story_10_15_1_97_dialog_content = "¡No debes decidir ya! Solo lo proponía.",
  ui_story_10_15_1_98_dialog_content = "Si alguna vez quieres unirte a Rediesel Wrench, la puerta siempre está abierta.",
  ui_story_10_15_1_99_dialog_content = "Gracias.",
  ui_story_10_15_1_100_dialog_content = "Pero solo necesito tres módulos del Colossus.",
  ui_story_10_15_1_101_dialog_content = "Para el resto de Aviduz, ustedes pueden hacer lo que quieran con él.",
  ui_story_10_15_1_102_dialog_content = "Ok ¿y ustedes dos? ¿Algo que gustarían compartir?",
  ui_story_10_15_1_103_dialog_content = "Si Lumopolis o Illumina están interesados ​​en él, supongo que ustedes dos no dejarán que nos vayamos así.",
  ui_story_10_15_1_104_dialog_content = "Si PlayerName dice que puedes tenerlo, no tengo ninguna intención de detenerte.",
  ui_story_10_15_1_105_dialog_content = "No lo necesitamos.",
  ui_story_10_15_1_106_dialog_content = "Para ser honesto, sabía que ustedes estaban aquí por el Colossus desde que nos conocimos.",
  ui_story_10_15_1_107_dialog_content = "En ese momento, ya había decidido que no intentaría quitarte Aviduz.",
  ui_story_10_15_1_108_dialog_content = "¡Bien! ¡Es leal de tu parte!",
  ui_story_10_15_1_109_dialog_content = "No se trata de lealtad ni nada por el estilo, simplemente no me interesa.",
  ui_story_10_15_1_110_dialog_content = "PlayerName.",
  ui_story_10_15_1_111_dialog_content = "Probablemente estés sintiendo cientos de cosas diferentes después de lo que acabamos de pasar.",
  ui_story_10_15_1_112_dialog_content = "Pero trata de no pensar mucho en ello. ¡Ya has hecho más que suficiente!",
  ui_story_10_15_1_113_dialog_content = "Si quieres volver a tener una vida pacífica, ¡nadie te culpará por ello!",
  ui_story_10_15_1_114_dialog_content = "Sinsa.",
  ui_story_10_15_1_115_dialog_content = "Gracias.",
  ui_story_10_15_1_116_dialog_content = "Whoa, ¿qué es esto que estoy escuchando?",
  ui_story_10_15_1_117_dialog_content = "¡Solo estaba elogiando al niño, nada más! ¡No me mires así!",
  ui_story_10_15_1_118_dialog_content = "¡Bien, terminamos! ¡A trabajar!",
  ui_story_10_15_1_119_dialog_content = "Urgh, descansa si lo necesitas, ¡el resto a trabajar!",
  ui_story_10_15_1_120_dialog_content = "¡Muévanse!",
  ui_story_10_15_1_121_dialog_content = "¡Jalamos a las tres! ¿Entiendes?",
  ui_story_10_15_1_122_dialog_content = "¡Entendido!",
  ui_story_10_15_1_123_dialog_content = "¡Brock! ¡¿Qué diablos estás haciendo ahí solo?!",
  ui_story_10_15_1_124_dialog_content = "¡Calentando, obviamente!",
  ui_story_10_15_1_125_dialog_content = "¡¿De verdad pensaste que iba a esperar a que me dijeras cuándo empezar?!",
  ui_story_10_15_1_126_dialog_content = "¡No hay forma de que arrastremos esto hacia atrás! ¡Dios mío, es un Colossus!",
  ui_story_10_15_1_127_dialog_content = "¿O deberíamos desarmarlo y recuperar algo útil?",
  ui_story_10_15_1_128_dialog_content = "De acuerdo.",
  ui_story_10_15_1_129_dialog_content = "Hola Bopper, ¿todavía necesitan ayuda? Realmente me gustaría volver a Soroz primero.",
  ui_story_10_15_1_130_dialog_content = "No, creo que podemos hacer esto.",
  ui_story_10_15_1_131_dialog_content = "Ahí veremos, así que no te preocupes.",
  ui_story_10_15_1_132_dialog_content = "Vayan a su Colossus y descansen un poco. ¡Cuidar tus heridas es lo primero!",
  ui_story_10_15_1_133_dialog_content = "Descuida, no lo olvidaremos. Todavía duelen.",
  ui_story_10_15_1_134_dialog_content = "Sin embargo, queremos despedirnos de Sinsa. ¿Dónde está?",
  ui_story_10_15_1_135_dialog_content = "Sí, sobre eso, dijo que no hay necesidad de despedidas cursis, así que no te preocupes por eso.",
  ui_story_10_15_1_136_dialog_content = "Bien...",
  ui_story_10_15_1_137_dialog_content = "Supongo que realmente nos iremos ahora. Adiós.",
  ui_story_10_15_1_138_dialog_content = "Si, adiós.",
  ui_story_10_15_1_139_dialog_content = "Cuídense, ¿si? ¡Nos veremos otro día!",
  ui_story_10_15_1_140_dialog_content = "¡Sí! Hasta la próxima.",
  ui_story_10_15_1_141_dialog_content = "¿Cómo llegue hasta aquí?",
  ui_story_10_15_1_142_dialog_content = "Al principio pensaba que era un sueño.",
  ui_story_10_15_1_143_dialog_content = "\"Vivir...\"",
  ui_story_10_15_1_144_dialog_content = "¿Tuviste <color=#FFB400>ese sueño</color> de nuevo?",
  ui_story_10_15_1_145_dialog_content = "Sí.",
  ui_story_10_15_1_146_dialog_content = "Los sueños son la visualización de esperanzas y deseos por lo desconocido. Son ilusiones.",
  ui_story_10_15_1_147_dialog_content = "Y luego. Murió Mendelson.",
  ui_story_10_15_1_148_dialog_content = "Ese día, hace 17 años, acepté el <color=#FFB400>Poder de los Eclipsites</color> para poder sobrevivir.",
  ui_story_10_15_1_149_dialog_content = "Ojalá pudiera ver el cielo, aunque sea por última vez.",
  ui_story_10_15_1_150_dialog_content = "Y poco después, vi morir a Schummer ante mis ojos.",
  ui_story_10_15_1_151_dialog_content = "(Te maldigo.)",
  ui_story_10_15_1_152_dialog_content = "(PlayerName.)",
  ui_story_10_15_1_153_dialog_content = "No eran sueños en absoluto, todos eran reales.",
  ui_story_10_15_1_154_dialog_content = "Soroz...",
  ui_story_10_15_1_155_dialog_content = "Tengo el módulo Think Tank, pero no sé si tiene un sistema al que conectar este componente.",
  ui_story_10_15_1_156_dialog_content = "Al final, eres un Colossus de Nivel 6, e incluso eso es lo que me dijeron los demás.",
  ui_story_10_15_1_E1_dialog_content = "...",
  ui_story_10_15_1_E2_dialog_content = "Será mejor que guarde mis quejas para cuando regrese.",
  ui_story_10_15_1_157_dialog_content = "Los tres puertos en el módulo Think Tank.",
  ui_story_10_15_1_158_dialog_content = "Todos se ven iguales.",
  ui_story_10_15_1_159_dialog_content = "...",
  ui_story_10_15_1_160_dialog_content = "<color=#e8d9bb>Control Primario normal</color>",
  ui_story_10_15_1_161_dialog_content = "<color=#e8d9bb>\"Módulos biológicos... en hibernación\".</color>",
  ui_story_10_15_1_162_dialog_content = "<color=#e8d9bb>\"Soporte vital... operativo. Capacidad actual: 1 persona.\"</color>",
  ui_story_10_15_1_163_dialog_content = "<color=#e8d9bb>Motor normal.</color>",
  ui_story_10_15_1_164_dialog_content = "<color=#e8d9bb>Módulo Think Tank detectado Conectando. </color>",
  ui_story_10_15_1_165_dialog_content = "<color=#e8d9bb>1%... 3%... 8%...</color>",
  ui_story_10_15_1_166_dialog_content = "Así que...",
  ui_story_10_15_1_167_dialog_content = "Esto es final, ¿no es así?",
  ui_story_10_15_1_168_dialog_content = "Sabes, casi nada queda del cuerpo de Schummer.",
  ui_story_10_15_1_169_dialog_content = "Sí... PlayerName ni quería comprobarlo.",
  ui_story_10_15_1_170_dialog_content = "Creo que PlayerName sintió la muerte de Schummer con habilidades psíquicas.",
  ui_story_10_15_1_171_dialog_content = "Bueno, ahora que está muerta, podemos sacarla de nuestras mentes.",
  ui_story_10_15_1_172_dialog_content = "¿Y realmente podemos hacer eso?",
  ui_story_10_15_1_173_dialog_content = "Schummer puede estar muerta, pero los Eclipsites que destruyeron Eraveil.",
  ui_story_10_15_1_174_dialog_content = "Todavía están en todo el mundo.",
  ui_story_10_15_1_175_dialog_content = "Sin mencionar que todavía hay un Eclipsite que PlayerName mencionó antes, <color=#FFB400>Figerald</color>.",
  ui_story_10_15_1_176_dialog_content = "Pero hasta el final, PlayerName no preguntó quién era este Figerald.",
  ui_story_10_15_1_177_dialog_content = "Pasaron tantas cosas en tan poco tiempo.",
  ui_story_10_15_1_178_dialog_content = "Quizás PlayerName no pudo preguntarle a tiempo.",
  ui_story_10_15_1_179_dialog_content = "Después de ver morir a Schummer, PlayerName parecía estar aturdido.",
  ui_story_10_15_1_180_dialog_content = "PlayerName salió de eso poco después, pero de alguna manera parece que algo no está bien.",
  ui_story_10_15_1_181_dialog_content = "Quizás PlayerName no quería que nos preocupáramos y volvió a ser el de siempre.",
  ui_story_10_15_1_182_dialog_content = "O tal vez, PlayerName se está enfocando en algo más importante ahora.",
  ui_story_10_15_1_183_dialog_content = "En cualquier caso, estoy segura de que PlayerName no dudará en pedirnos ayuda si es necesario.",
  ui_story_10_15_1_184_dialog_content = "Hmm... Tiene un punto.",
  ui_story_10_15_1_185_dialog_content = "Por cierto, PlayerName lleva un tiempo dentro de Soroz y aún no ha salido.",
  ui_story_10_15_1_186_dialog_content = "Estoy un poco preocupada.",
  ui_story_10_15_1_187_dialog_content = "PlayerName quería llevar los componentes adentro solo, por alguna razón.",
  ui_story_10_15_1_188_dialog_content = "Esperemos un poco más.",
  ui_story_10_15_1_189_dialog_content = "Bien...",
  ui_story_10_15_1_190_dialog_content = "<color=#e8d9bb>10%... 23%...</color>",
  ui_story_10_15_1_191_dialog_content = "<color=#e8d9bb>33%... 35%...</color>",
  ui_story_10_15_1_192_dialog_content = "<color=#e8d9bb>Fallo de conexión. Recuento de Fallos: 1</color>",
  ui_story_10_15_1_193_dialog_content = "Está bien. Probemos de nuevo.",
  ui_story_10_15_1_194_dialog_content = "Conectar el Módulo Think Tank.",
  ui_story_10_15_1_195_dialog_content = "<color=#e8d9bb>Módulo Think Tank detectado Conectando. </color>",
  ui_story_10_15_1_196_dialog_content = "<color=#e8d9bb>1%... 3%... 8%...</color>",
  ui_story_10_15_1_197_dialog_content = "<color=#e8d9bb>61%... 67%...</color>",
  ui_story_10_15_1_198_dialog_content = "<color=#e8d9bb>76%... 85%...</color>",
  ui_story_10_15_1_199_dialog_content = "<color=#e8d9bb>Fallo de conexión. Recuento de Fallos: 2</color>",
  ui_story_10_15_1_200_dialog_content = "Son solo dos intentos fallidos. ¿Recuerdas cuántas veces necesitaste para activar tus motores?",
  ui_story_10_15_1_201_dialog_content = "Se necesitaron más de tres mil intentos.",
  ui_story_10_15_1_202_dialog_content = "Está bien.",
  ui_story_10_15_1_203_dialog_content = "De nuevo. Una vez más.",
  ui_story_10_15_1_204_dialog_content = "Comencemos desde el primer paso e intentemos de nuevo.",
  ui_story_10_15_1_205_dialog_content = "<color=#e8d9bb>Control Primario normal</color>",
  ui_story_10_15_1_206_dialog_content = "<color=#e8d9bb>\"Módulos biológicos... en hibernación\".</color>",
  ui_story_10_15_1_207_dialog_content = "<color=#e8d9bb>Plantilla de eco dañada.</color>",
  ui_story_10_15_1_208_dialog_content = "<color=#e8d9bb>\"Soporte vital... operativo. Capacidad actual: 1 persona.\"</color>",
  ui_story_10_15_1_209_dialog_content = "<color=#e8d9bb> Generador normal.</color>",
  ui_story_10_15_1_210_dialog_content = "<color=#e8d9bb>Módulo Think Tank detectado Conectando. </color>",
  ui_story_10_15_1_211_dialog_content = "<color=#e8d9bb>1%... 3%... 8%...</color>",
  ui_story_10_15_1_212_dialog_content = "<color=#e8d9bb>10%... 25%...</color>",
  ui_story_10_15_1_213_dialog_content = "...",
  ui_story_10_15_1_214_dialog_content = "...",
  ui_story_10_15_1_215_dialog_content = "¡Basta, vamos adentro para echar un vistazo!",
  ui_story_10_15_1_216_dialog_content = "¡Por lo menos, necesitamos verificar PlayerName!",
  ui_story_10_15_1_217_dialog_content = "Te meterás al camino de PlayerName si lo haces, Vice.",
  ui_story_10_15_1_218_dialog_content = "Lo sé pero.",
  ui_story_10_15_1_219_dialog_content = "Si el módulo Think Tank no puede conectarse al Colossus.",
  ui_story_10_15_1_220_dialog_content = "Si no hay forma de reparar a Soroz.",
  ui_story_10_15_1_221_dialog_content = "No quiero tener que lidiar con PlayerName sola.",
  ui_story_10_15_1_222_dialog_content = "¡Solo voy a verificar PlayerName! Haré lo posible para no estorbar, ¡lo prometo!",
  ui_story_10_15_1_223_dialog_content = "*Suspira* ahí.",
  ui_story_10_15_1_224_dialog_content = "Si estás tan preocupada, ¿por qué no gritas desde la entrada?",
  ui_story_10_15_1_225_dialog_content = "PlayerName es un Celestita, al final. Entre los sentidos y las habilidades psíquicas de un Celestita.",
  ui_story_10_15_1_226_dialog_content = "Seguro PlayerName te escuchará.",
  ui_story_10_15_1_227_dialog_content = "De esa manera, no irás en contra de los deseos de PlayerName de entrar solo.",
  ui_story_10_15_1_228_dialog_content = "¡Estás en lo correcto! ¡Haré eso!",
  ui_story_10_15_1_229_dialog_content = "¡Deja que tú pienses en una idea tan brillante, Carleen!",
  ui_story_10_15_1_230_dialog_content = "¡¿De qué estás hablando?! Al final lo aprendí de ti.",
  ui_story_10_15_1_231_dialog_content = "*Inhala*",
  ui_story_10_15_1_232_dialog_content = "¡PlayerName!",
  ui_story_10_15_1_233_dialog_content = "<color=#e8d9bb>89%... 97%...</color>",
  ui_story_10_15_1_234_dialog_content = "<color=#e8d9bb>100%... Conexión exitosa.</color>",
  ui_story_10_15_1_235_dialog_content = "<color=#e8d9bb>Gracias por utilizar el módulo Think Tank. </color>",
  ui_story_10_15_1_236_dialog_content = "¡Vice! ¡Carleen!",
  ui_story_10_15_1_237_dialog_content = "¡La conexión fue un éxito! ¡Encontré como arreglar la Plantilla Echo!",
  ui_story_10_15_1_238_dialog_content = "¡Creo poder salvar Soroz!",
  ui_story_10_15_1_239_dialog_content = "Me estás diciendo.",
  ui_story_10_15_1_240_dialog_content = "¿Ese Celestita llamado PlayerName logró derrotar a Schummer, la Celestita traidora?",
  ui_story_10_15_1_241_dialog_content = "¿Y después, este Celestita dejó que Rediesel Wrench se llevara el Colossus Negro?",
  ui_story_10_15_1_242_dialog_content = "Forsakin no solo no los detuvo, sino incluso los ayudó a promover sus objetivos. ¿Es eso correcto?",
  ui_story_10_15_1_243_dialog_content = "Sí.",
  ui_story_10_15_1_244_dialog_content = "¿Crees que el Celestita interferirá con nuestros planes?",
  ui_story_10_15_1_245_dialog_content = "No, PlayerName simplemente hará las cosas más interesantes.",
  ui_story_10_15_1_246_dialog_content = "Estoy segura de que Schwartz también siente lo mismo.",
  ui_story_70000101_1_dialog_content = "<color=#e8d9bb>\"Ejecutando el autodiagnóstico\".</color>",
  ui_story_70000101_2_dialog_content = "<color=#e8d9bb>\"Comprobación del sistema de control principal... En funcionamiento. Integridad de los componentes reducida en un 39%. Se requiere mantenimiento\".</color>",
  ui_story_70000101_3_dialog_content = "<color=#e8d9bb>\"Comprobación del módulo biológico... En funcionamiento. Integridad del módulo reducida en un 46 %. Se requiere mantenimiento.</color>",
  ui_story_70000101_4_dialog_content = "<color=#e8d9bb>\"Comprobación del sistema de soporte vital... En funcionamiento. Advertencia: carga completa. Requiere mantenimiento\".</color>",
  ui_story_70000101_5_dialog_content = "<color=#e8d9bb>\"Comprobación del sistema de mantenimiento... Normal. Activando...\"</color>",
  ui_story_70000101_6_dialog_content = "<color=#e8d9bb>\"Error: Falta la plantilla de eco. Las funciones de mantenimiento no se pueden activar\".</color>",
  ui_story_70000101_7_dialog_content = "<color=#e8d9bb>\"Error al iniciar. Recuento de fallas: 1012\".</color>",
  ui_story_70000101_8_dialog_content = "<color=#e8d9bb>\"Instala la plantilla de eco para acceder a las funciones de mantenimiento\".</color>",
  ui_story_70000101_9_dialog_content = "<color=#e8d9bb>\"Advertencia: Ya no se podrá acceder a las funciones relevantes si la integridad de los componentes se reduce en un 50 %\".</color>",
  ui_story_70000101_10_dialog_content = "<color=#e8d9bb>\"Favor firmar y confirmar.\"</color>",
  ui_story_70000101_11_dialog_content = "Soroz...",
  ui_story_70000101_12_dialog_content = "PlayerName, como esta el Soroz?",
  ui_story_70000101_13_dialog_content = "...",
  ui_story_70000101_14_dialog_content = "Siempre lo mismo. Falta plantilla de eco. No se puede realizar el automantenimiento. La situación es crítica.",
  ui_story_70000101_15_dialog_content = "Debería haber hecho reparar a Soroz sin demora; en cambio, me dejé llevar por muchas otras cosas.",
  ui_story_70000101_16_dialog_content = "No te eches la culpa de todo. No me di cuenta del estado anormal de Soroz después de pasar tanto tiempo con él. Debo rendir cuentas por esto.",
  ui_story_70000101_17_dialog_content = "Pero no te preocupes demasiado. Ya hemos encontrado una solución, ¿no?",
  ui_story_70000101_18_dialog_content = "¡Encontré algunas pistas!",
  ui_story_70000101_19_dialog_content = "Think Tank Module nos dio un conjunto de coordenadas, pero... ¿dónde está esto?",
  ui_story_70000101_20_dialog_content = "¿Puedo ver?",
  ui_story_70000101_21_dialog_content = "Estas coordenadas están en el <color=#FFB400>Zona Oscura</color>?!",
  ui_story_70000101_22_dialog_content = "Si no recuerdo mal... ahí es donde <color=#FFB400>Entrañas 80</color> se encuentra.",
  ui_story_70000101_23_option_content = "¿La Zona Oscura...?",
  ui_story_70000101_24_option_content = "Entrañas 80...?",
  ui_story_70000101_25_dialog_content = "La Zona Oscura es un nombre colectivo para las regiones cercanas a la Noche Eterna.",
  ui_story_70000101_26_dialog_content = "Entrañas 80 es la ubicación a la que apuntan las coordenadas.",
  ui_story_70000101_27_dialog_content = "La Zona Oscura es un lugar muy peligroso.",
  ui_story_70000101_28_dialog_content = "Allí el día es corto y la noche larga. También se dice que tiene grandes grupos de eclipses reunidos allí.",
  ui_story_70000101_29_dialog_content = "Oye, tú ahí, PlayerName?",
  ui_story_70000101_30_dialog_content = "¿Eh? ¿Comunicación del Seol...?",
  ui_story_70000101_31_dialog_content = "Escuché que estás investigando la Zona Oscura. Resulta que tengo algo de información.",
  ui_story_70000101_32_dialog_content = "¿Eh? ¡¿Como supiste?!",
  ui_story_70000101_33_dialog_content = "Los comerciantes de Umbraton siempre están atentos a posibles oportunidades comerciales.",
  ui_story_70000101_34_dialog_content = "Ya veo. Debe ser alguna \"red de inteligencia especial\" o algo así, ¿verdad?",
  ui_story_70000101_35_dialog_content = "Como era de esperar de un habitual, me conoces bien.",
  ui_story_70000101_X35_dialog_content = "Me siento un poco generoso, así que te daré información gratis.",
  ui_story_70000101_36_dialog_content = "El conjunto de coordenadas que tienes es un lugar llamado <color=#FFB400>Fango</color>. Es un lugar muy peligroso.",
  ui_story_70000101_37_dialog_content = "... Aún así, sigo yendo.",
  ui_story_70000101_38_dialog_content = "Es la única pista del Módulo Think Tank. No puedo sentarme aquí y no ayudar a Soroz.",
  ui_story_70000101_39_dialog_content = "PlayerName, piensa con tu cerebro, no con tu corazón.",
  ui_story_70000101_40_dialog_content = "No es prudente adentrarse en el fango sin información ni preparación.",
  ui_story_70000101_41_dialog_content = "...",
  ui_story_70000101_42_dialog_content = "Eso es correcto. Esto es exactamente lo que yo aconsejaría.",
  ui_story_70000101_43_dialog_content = "Sin embargo, si está dispuesto a hacer algo por mí a cambio, veré si puedo reunir más información pertinente para usted.",
  ui_story_70000101_44_dialog_content = "No me digas... ¿Nightium otra vez?",
  ui_story_70000101_45_dialog_content = "Lumopolis debería tener alguna información sobre esa región.",
  ui_story_70000101_46_dialog_content = "Puedo ir a ver si encuentro algo.",
  ui_story_70000101_47_dialog_content = "Entonces te lo dejo a ti, por favor ayúdame.",
  ui_story_70000101_48_dialog_content = "Revisé la situación de Soroz nuevamente. Todavía está operativo. Nada de qué preocuparse por el momento.",
  ui_story_70000101_49_dialog_content = "Ha sido un tiempo. Carleen y Sheol deberían volver pronto con información.",
  ui_story_70000101_50_dialog_content = "También le pedí a mi gente en Illumina que me ayudara a buscar pistas. No te preocupes.",
  ui_story_70000101_51_dialog_content = "Espero que les sirva de algo, ya que...",
  ui_story_70000101_52_dialog_content = "Esta es la única forma de salvar a Soroz.",
  ui_story_70000101_53_dialog_content = "Si este conjunto de coordenadas es exacto, me temo que tendremos que buscar en toda Entrañas.",
  ui_story_70000101_54_dialog_content = "Incluso si es la ciudad interior más pequeña, aún tomaría días atravesarla.",
  ui_story_70000101_55_dialog_content = "¿No podemos obtener una ubicación más precisa?",
  ui_story_70000101_56_dialog_content = "No. Esto es todo lo que tenemos que hacer ahora.",
  ui_story_70000101_57_dialog_content = "Tal vez si podemos acercarnos al objetivo...",
  ui_story_70000101_58_dialog_content = "Puedes oírme, PlayerName?",
  ui_story_70000101_59_dialog_content = "¡Carleen! ¡Si puedo oirte!",
  ui_story_70000101_60_dialog_content = "Bien. Estoy en la biblioteca de la Academia Dawn. La recepción es mala aquí, así que seré breve.",
  ui_story_70000101_61_dialog_content = "Hay algunos registros de antiguas guerras en Entrañas 80 aquí.",
  ui_story_70000101_62_dialog_content = "Según los registros, Entrañas 80 fue una vez un puesto de avanzada y un centro de transporte de Illumina.",
  ui_story_70000101_63_dialog_content = "Está cerca de la Noche Eterna, por lo que solía servir como frente de batalla de la Federación Illumina y los Eclipsites.",
  ui_story_70000101_64_dialog_content = "Sin embargo, durante el <color=#FFB400>Guerra de la Zona Oscura</color>, su ubicación remota dificultaba el refuerzo contra la feroz ofensiva de los Eclipsites.",
  ui_story_70000101_65_dialog_content = "Illumina pronto evacuó y abandonó Entrañas 80.",
  ui_story_70000101_66_option_content = "¿La Guerra de la Zona Oscura?",
  ui_story_70000101_67_dialog_content = "Escuché sobre esa guerra. Fue una invasión de Eclipsite a gran escala que ocurrió hace más de veinte años.",
  ui_story_70000101_68_dialog_content = "Grandes cantidades de Eclipsite acudieron en masa desde la Noche Eterna... Fue una guerra brutal.",
  ui_story_70000101_69_dialog_content = "Aunque la Federación Illumina finalmente ganó la guerra, innumerables Entrañas y soldados fueron sacrificados.",
  ui_story_70000101_70_dialog_content = "Eso es lo que dice aquí también.",
  ui_story_70000101_71_dialog_content = "Cuando Illumina se retiró, una gran cantidad de equipos quedaron atrás. Puede que encuentres lo que necesitas.",
  ui_story_70000101_72_dialog_content = "¡Ya veo! ¡Muchas gracias!",
  ui_story_70000101_73_dialog_content = "No hay problema. Cualquier cosa para ayudar.",
  ui_story_70000101_X74_dialog_content = "<color=#e8d9bb>Bwooommm... Bwooommm...</color>",
  ui_story_70000101_75_dialog_content = "¿Otra comunicación entrante? ¿Hola?",
  ui_story_70000101_76_dialog_content = "Soy yo, PlayerName.",
  ui_story_70000101_77_dialog_content = "Hola, Seol. ¿Qué tienes?",
  ui_story_70000101_X77_dialog_content = "Obtuve más información... pero no es lo ideal.",
  ui_story_70000101_78_dialog_content = "Mis fuentes me dicen que ese lugar está repleto de eclipses.",
  ui_story_70000101_79_dialog_content = "Sin Soroz, no hay forma de que puedas acercarte al Mire.",
  ui_story_70000101_80_dialog_content = "En cuanto a Entrañas... No hay nada allí excepto ruinas que muestran las huellas de batallas pasadas.",
  ui_story_70000101_81_dialog_content = "El núcleo de energía todavía está en funcionamiento por ahora, pero en su estado comprometido, no puede mantener el sistema de defensa. Es probable que se apague en cualquier segundo.",
  ui_story_70000101_82_dialog_content = "La única persona lo suficientemente afortunada para salir con vida dice que la única forma de entrar o salir de la ciudad subterránea es...",
  ui_story_70000101_83_dialog_content = "UN <color=#FFB400>abismo</color> causado por el derrumbe.",
  ui_story_70000101_84_dialog_content = "Ok...",
  ui_story_70000101_85_dialog_content = "Entiendo.",
  ui_story_70000101_86_dialog_content = "Buena suerte, gente.",
  ui_story_70000101_87_dialog_content = "Será mejor que vuelvas con vida y pagues.",
  ui_story_70000101_88_dialog_content = "E-Está bien...",
  ui_story_70000101_89_dialog_content = "Extraño. ¿Todavía no hay información de Philyshy?",
  ui_story_70000101_90_dialog_content = "<color=#e8d9bb>Bip... Bip...</color>",
  ui_story_70000101_91_dialog_content = "¿Eh? Philyshy envió un archivo.",
  ui_story_70000101_92_dialog_content = "¿Qué es? Déjeme ver.",
  ui_story_70000101_93_dialog_content = "<color=#FFB400>¿Manual de combate de la zona oscura?</color>",
  ui_story_70000101_94_option_content = "¿Tienen manuales como este?",
  ui_story_70000101_95_dialog_content = "Nunca había oído hablar de algo así antes...",
  ui_story_70000101_96_dialog_content = "Se ve barato y toscamente ensamblado...",
  ui_story_70000101_97_dialog_content = "No hay índice y el formato no es correcto.",
  ui_story_70000101_98_dialog_content = "No parece ni remotamente auténtico.",
  ui_story_70000101_99_dialog_content = "Que sospechoso...",
  ui_story_70000101_100_dialog_content = "Philyshy no proporcionaría información poco fiable.",
  ui_story_70000101_101_option_content = "¿Ella realmente accedió a ayudar?",
  ui_story_70000101_102_dialog_content = "Eso es tan diferente a ella.",
  ui_story_70000101_103_dialog_content = "Ese no es el punto... Bueno, no hay nada de malo en decírtelo, supongo...",
  ui_story_70000101_104_dialog_content = "Philyshy quiere que mantenga la boca cerrada sobre cómo faltó al trabajo la última vez para tomar una siesta...",
  ui_story_70000101_105_dialog_content = "Así que accedió a darnos información sobre Entrañas 80 a cambio de mi silencio.",
  ui_story_70000101_106_dialog_content = "Eso suena más a ella...",
  ui_story_70000101_107_dialog_content = "Quiero decir, Philyshy siempre tiene la información más confiable.",
  ui_story_70000101_108_dialog_content = "Pero... ¿por qué este manual se ve tan de mala calidad?",
  ui_story_70000101_109_dialog_content = "¿Qué dice ahí?",
  ui_story_70000101_110_dialog_content = "\"Regla de combate de la zona oscura 1\"",
  ui_story_70000101_111_dialog_content = "\"¡Se debe evitar el combate en la Zona Oscura a menos que sea absolutamente necesario!\"",
  ui_story_70000101_112_dialog_content = "¡¿Qué?!",
  ui_story_70000101_113_dialog_content = "¿Es The Dark Zone realmente un lugar tan peligroso?",
  ui_story_70000101_114_dialog_content = "\"Según toda la información conocida, la Zona Oscura es una región altamente peligrosa\".",
  ui_story_70000101_115_dialog_content = "\"El Darkflow concentrado dificulta el movimiento de los aurorianos, y los efectos son aún más pronunciados por la noche\".",
  ui_story_70000101_116_dialog_content = "\"La Zona Oscura es el hogar de los Eclipsites, por lo tanto, hay Eclipsites extremadamente poderosos que residen dentro. ¡Es muy peligroso!\"",
  ui_story_70000101_117_dialog_content = "Los Illumina Soldiers tienen prohibido entrar... ¿Eso te complicaría las cosas?",
  ui_story_70000101_119_dialog_content = "No puedo dejar que te metas en problemas por esto.",
  ui_story_70000101_120_dialog_content = "¡Tal vez pueda ir a pedirle un favor a Hiiro!",
  ui_story_70000101_121_dialog_content = "PlayerName.",
  ui_story_70000101_122_dialog_content = "No te preocupes por mí.",
  ui_story_70000101_123_dialog_content = "Soroz es importante para los dos.",
  ui_story_70000101_124_dialog_content = "No hay forma de que me quede fuera cuando mis amigos me necesitan.",
  ui_story_70000101_125_dialog_content = "Además, ya estoy involucrado. No informarlo sería considerado un delito por Illumina Military.",
  ui_story_70000101_126_dialog_content = "Ocultadlo al Gran Mariscal y a los Comandantes de la Legión, y debería estar bien...",
  ui_story_70000101_127_dialog_content = "¡Definitivamente va a estar bien!",
  ui_story_70000101_128_dialog_content = "Lo siento por hacerte correr tanto riesgo...",
  ui_story_70000101_129_dialog_content = "Este manual parece detallar todo acerca de entrar en combate en la Zona Oscura...",
  ui_story_70000101_130_dialog_content = "¿Pero quién lo escribió...?",
  ui_story_70000101_131_dialog_content = "Veamos eso en otro momento.",
  ui_story_70000101_132_dialog_content = "En este momento, nuestra prioridad es formar un plan basado en lo que tenemos.",
  ui_story_70000101_133_dialog_content = "Hay tantos Eclipsites, además la influencia de Darkflow es más pronunciada por la noche... y la noche es larga...",
  ui_story_70000101_134_dialog_content = "Esta va a ser una operación difícil.",
  ui_story_70000101_135_dialog_content = "Podríamos llevar a Soroz allí, sin pasar por todos los Eclipsites en el camino.",
  ui_story_70000101_136_dialog_content = "Una vez que lleguemos a Entrañas, podemos usar el módulo Think Tank para ubicar el objetivo.",
  ui_story_70000101_137_dialog_content = "Haremos un trabajo rápido y terminaremos todo antes del anochecer...",
  ui_story_70000101_138_dialog_content = "Es igual de arriesgado. ¿Qué pasa si somos emboscados por eclipses subterráneos de alto nivel?",
  ui_story_70000101_139_dialog_content = "Rodéalos. Debemos evitar el combate a toda costa. Una vez que encontremos el módulo, nos retiraremos.",
  ui_story_70000101_140_dialog_content = "Entendido.",
  ui_story_70000101_141_dialog_content = "Bien entonces. Salgamos. Destino: Entrañas 80!",
  ui_story_70000101_142_dialog_content = "<color=#e8d9bb>Línea Segura Illumina</color>",
  ui_story_70000101_143_dialog_content = "El Soroz está a punto de pasar por la línea segura, en dirección a Entrañas 80.",
  ui_story_70000101_144_dialog_content = "¿De verdad vas a dejarlos pasar?",
  ui_story_70000101_145_dialog_content = "¿Hmm? ¿Me dijiste algo?",
  ui_story_70000101_146_dialog_content = "S-Sí... Eres el Gran Mariscal. Esta es tu decisión.",
  ui_story_70000101_147_dialog_content = "Como descubriste que Philyshy había investigado Entrañas 80, entonces debes conocer su objetivo.",
  ui_story_70000101_148_dialog_content = "Sí. PlayerName obtuvo información de que hay un elemento tecnológico de origen antiguo que podría reparar la plantilla de eco del Coloso en Entrañas 80.",
  ui_story_70000101_149_dialog_content = "¿Por qué crees que lo está buscando?",
  ui_story_70000101_150_dialog_content = "Su Coloso, el Soroz, perdió su Plantilla de Eco en la pelea con Schummer y Forsakin...",
  ui_story_70000101_151_dialog_content = "Para él, el Coloso es su familia. Perder la Plantilla de eco es probablemente como si el Coloso hubiera perdido la vida.",
  ui_story_70000101_152_dialog_content = "Si lo pones así...",
  ui_story_70000101_153_dialog_content = "¿Qué razones tengo para impedir que un hombre salve a su familia?",
  ui_story_70000101_154_dialog_content = "No tiene malas intenciones. Creo que puedo hacer la vista gorda esta vez.",
  ui_story_70000101_155_dialog_content = "Lo trataremos como pago por su servicio contra los Eclipsites.",
  ui_story_70000101_156_dialog_content = "Pero, ¿cómo se lo explicamos al Comité? Le prohíben a cualquiera explorar la Zona Oscura, especialmente a usted, Gran Mariscal.",
  ui_story_70000101_157_dialog_content = "Seguro que es un problema...",
  ui_story_70000101_158_dialog_content = "Diles esto entonces: Caelestite entró en la Zona Oscura sin autorización. Intentamos interceptarlo pero fallamos.",
  ui_story_70000101_159_dialog_content = "Debido a las restricciones del Comité, nuestras tropas no pueden perseguir pasar la línea segura.",
  ui_story_70000101_160_dialog_content = "Caelestite no es ciudadano de Illumina y está conectado a todas las facciones.",
  ui_story_70000101_161_dialog_content = "Confío en que el Comité no le haría nada basándose solo en eso.",
  ui_story_70000101_162_dialog_content = "Pero, Gran Mariscal, sigo pensando que es demasiado peligroso ahí dentro.",
  ui_story_70000101_163_dialog_content = "Han visto su parte de batallas. Confío en que tienen la capacidad de manejar el peligro.",
  ui_story_70000101_164_dialog_content = "Siempre y cuando sean diligentes... y cumplan con el Manual. Deberían estar bien.",
  ui_story_70000101_165_dialog_content = "Entonces... ¿por qué estamos aquí?",
  ui_story_70000101_166_dialog_content = "A pesar de sus habilidades de combate, necesitarán algo más para salir con vida...",
  ui_story_70000101_167_dialog_content = "Como una cuerda de seguridad que puede sacarlos del fango si es necesario.",
  ui_story_70000101_168_dialog_content = "Manténgase en alerta amarilla y continúe monitoreando la Zona Oscura.",
  ui_story_70000101_169_dialog_content = "Sí, Gran Mariscal.",
  ui_story_70000101_170_dialog_content = "¿Philyshy?",
  ui_story_70000101_171_dialog_content = "¿¡Maullar!?",
  ui_story_70000101_172_dialog_content = "Custodiaré tu terminal de comunicación por ahora.",
  ui_story_70000101_173_dialog_content = "En cuanto a que te saltaste el trabajo... Hablaremos de eso cuando termine.",
  ui_story_70000101_174_dialog_content = "Ok...",
  ui_story_70000101_175_dialog_content = "Ahora, ve a monitorear Entrañas 80 y avísame si hay algún cambio en la situación.",
  ui_story_70000101_176_dialog_content = "Sí señor...",
  ui_story_70000101_177_dialog_content = "Vice... ahora estás en un gran problema...",
  ui_story_70000101_178_dialog_content = "Entrañas 80...",
  ui_story_70000101_179_dialog_content = "No es lugar para cualquiera. Seguro que esos dos son audaces.",
  ui_story_70000201_1_dialog_content = "Hemos pasado por la línea segura cerca del límite de la Noche Eterna establecida por la Federación Illumina.",
  ui_story_70000201_2_dialog_content = "Pronto llegaremos a Entrañas 80.",
  ui_story_70000201_3_dialog_content = "Claramente está oscureciendo. ¿Es esta la Zona Oscura?",
  ui_story_70000201_4_dialog_content = "Este ambiente realmente me hace sentir incómodo. Se siente como si estuviera respirando con medio pulmón...",
  ui_story_70000201_5_dialog_content = "Espero que esto no afecte nuestras capacidades de combate...",
  ui_story_70000201_6_dialog_content = "¿Qué dice en el Manual?",
  ui_story_70000201_7_dialog_content = "Déjame ver...",
  ui_story_70000201_8_dialog_content = "\"Regla 3: Evita el combate a toda costa en el Mire. Sepa cuándo retirarse\".",
  ui_story_70000201_9_dialog_content = "\"Undercity 80 también se conoce como Mire por su Darkflow altamente concentrado que hace que respirar sea una tarea\".",
  ui_story_70000201_10_dialog_content = "\"Darkflow también interfiere fuertemente con las señales de comunicación, incluso las paraliza por completo a solo unos pocos pies de distancia\".",
  ui_story_70000201_11_dialog_content = "\"Los efectos negativos de Darkflow se intensifican con el tiempo\".",
  ui_story_70000201_12_dialog_content = "\"Nightfall también multiplica los efectos negativos por un factor de 2 como mínimo\".",
  ui_story_70000201_13_dialog_content = "En otras palabras, incluso los eclipses normales se volverán extremadamente difíciles de manejar.",
  ui_story_70000201_14_dialog_content = "Parece que realmente tenemos que evitar el combate.",
  ui_story_70000201_15_dialog_content = "Y estamos en un temporizador. Las cosas serían aún peores por la noche.",
  ui_story_70000201_16_dialog_content = "Tendremos que confiar en la movilidad del Soroz para entrar en él durante el día, y acabar con él lo antes posible.",
  ui_story_70000201_17_dialog_content = "PlayerName... pareces más confiable, de alguna manera.",
  ui_story_70000201_18_dialog_content = "Oh, ¿en serio?",
  ui_story_70000201_19_dialog_content = "Me estás haciendo sonrojar...",
  ui_story_70000201_20_dialog_content = "Pero he estado pensando en algo por un rato.",
  ui_story_70000201_21_dialog_content = "Quienquiera que haya escrito el Manual claramente sabe todo lo que hay que saber sobre Entrañas 80. ¿Podría él o ella ser un veterano de guerra?",
  ui_story_70000201_22_dialog_content = "no sabríamos...",
  ui_story_70000201_23_dialog_content = "Este Manual no es oficial de ninguna manera. Ni siquiera tiene el nombre del autor.",
  ui_story_70000201_24_dialog_content = "Suena más como una lista de puntos de atención redactada por un comandante de primera línea para los soldados.",
  ui_story_70000201_25_dialog_content = "Extraño...",
  ui_story_70000201_26_dialog_content = "Pero como Philyshy nos lo dio, estoy seguro de que podemos confiar en él.",
  ui_story_70000201_27_dialog_content = "Solo espero que no veamos lo peor que la Zona Oscura tiene para ofrecer.",
  ui_story_70000201_28_dialog_content = "PlayerName, ¡Mira!",
  ui_story_70000201_29_dialog_content = "¿Eso es Entrañas 80?",
  ui_story_70000201_30_dialog_content = "¿Estamos aquí?",
  ui_story_70000201_31_dialog_content = "No se parece a nada de lo que esperaba...",
  ui_story_70000201_32_dialog_content = "Por lo que recuerdo, todas las Entrañas de Illumina tienen paredes gruesas y una gran cantidad de baterías de armas...",
  ui_story_70000201_33_dialog_content = "Pero todo lo que puedo ver aquí son ruinas y edificios derrumbados con agujeros de bala... y armas rotas descartadas.",
  ui_story_70000201_34_dialog_content = "Casi se siente como si este lugar hubiera sido devastado por guerras y desastres...",
  ui_story_70000201_35_dialog_content = "¿Está lo que estamos buscando... realmente aquí?",
  ui_story_70000201_36_dialog_content = "Es de esperar. Una guerra terrible tuvo lugar aquí, y ha sido abandonada por mucho tiempo...",
  ui_story_70000201_37_dialog_content = "Probablemente sea un nido para los Eclipsites ahora...",
  ui_story_70000201_38_dialog_content = "Creo que algún día Illumina reclamará este lugar.",
  ui_story_70000201_39_dialog_content = "Cada Entrañas contiene valiosa energía, recursos y tecnología.",
  ui_story_70000201_40_dialog_content = "Illumina... nunca dejará que los Eclipsites lo tengan.",
  ui_story_70000201_41_dialog_content = "...",
  ui_story_70000201_42_dialog_content = "Hay muchos eclipses vagando por la superficie. No podemos perder el tiempo luchando contra ellos.",
  ui_story_70000201_43_dialog_content = "Encuentra un lugar tranquilo para aterrizar. Nos colaremos a pie.",
  ui_story_70000201_44_dialog_content = "Es el amanecer en este momento. Deberíamos tener tiempo suficiente para completar la operación.",
  ui_story_70000201_45_dialog_content = "<color=#e8d9bb>No mucho después...</color>",
  ui_story_70000201_46_dialog_content = "¿Es eso lo que nos hace Darkflow?",
  ui_story_70000201_47_dialog_content = "Mi cuerpo se siente tan pesado... como si estuviera cargando pesas en mi espalda...",
  ui_story_70000201_48_dialog_content = "Lo mismo aquí... Solo toma unos pocos pasos antes de que empiece a jadear...",
  ui_story_70000201_49_dialog_content = "Debe ser lo que dice el Manual... el impacto de la Zona Oscura...",
  ui_story_70000201_50_dialog_content = "Es casi imposible luchar en estas circunstancias...",
  ui_story_70000201_51_dialog_content = "Encontremos una forma de entrar primero.",
  ui_story_70000201_52_dialog_content = "Todo está colapsado. No hay forma de encontrar la entrada original a Entrañas.",
  ui_story_70000201_53_dialog_content = "Solo el número 80 blanco vagamente visible en la placa de acero descartada puede probar que esta fue una vez una Ciudad Entrañas de Illumina...",
  ui_story_70000201_54_dialog_content = "La estructura principal comprometida, la pared exterior completamente colapsada, el marco arquitectónico todo retorcido...",
  ui_story_70000201_55_dialog_content = "Un terremoto de 9.0 debe haber ocurrido aquí, eso, o haber sido atacado por Eclipsites de élite durante 24 horas sin parar...",
  ui_story_70000201_56_dialog_content = "De lo contrario, no hay forma de dañar las defensas de Entrañas de Illumina hasta este punto.",
  ui_story_70000201_57_dialog_content = "¿Cómo están las puertas delanteras?",
  ui_story_70000201_58_dialog_content = "Completamente enterrado.",
  ui_story_70000201_59_dialog_content = "No hay ninguna ruta hacia el área subterránea a la vista.",
  ui_story_70000201_60_dialog_content = "Parece que tendremos que encontrar eso. <color=#FFB400>abismo</color> Seol nos habló de.",
  ui_story_70000201_61_dialog_content = "*Rugido*",
  ui_story_70000201_62_dialog_content = "Cuida tu flanco, PlayerName!",
  ui_story_70000201_63_dialog_content = "¿¡De dónde vienen!?",
  ui_story_70000201_64_dialog_content = "¡Parece haber una grieta o algún tipo en la dirección de donde aparecieron los Eclipsites!",
  ui_story_70000201_65_dialog_content = "Parece que no vamos a salir de esta batalla...",
  ui_story_70000201_66_dialog_content = "Vice, sigue el Manual y ten cuidado.",
  ui_story_70000201_67_dialog_content = "¡Lo tienes!",
  ui_story_70000202_1_dialog_content = "*Roncando*",
  ui_story_70000202_2_dialog_content = "¿Se acabó... finalmente?",
  ui_story_70000202_3_dialog_content = "tengo un dolor de cabeza atroz...",
  ui_story_70000202_4_dialog_content = "Ya ni siquiera puedo ver el rastro de luz...",
  ui_story_70000202_5_dialog_content = "¡¿PlayerName?!",
  ui_story_70000202_6_dialog_content = "Estoy bien... Solo que casi me desmayo.",
  ui_story_70000202_7_dialog_content = "Mantengamos un perfil bajo de ahora en adelante para evitar problemas...",
  ui_story_70000202_8_dialog_content = "No esperaba que las cosas fueran tan difíciles aquí...",
  ui_story_70000202_9_dialog_content = "No puedo rendirme... Necesito salvar a los Soroz...",
  ui_story_70000202_10_dialog_content = "Vamos a comprobar el abismo.",
  ui_story_70000202_11_dialog_content = "Bueno.",
  ui_story_70000202_12_dialog_content = "Esto no es un abismo.",
  ui_story_70000202_13_dialog_content = "¡Esto es un acantilado!",
  ui_story_70000202_14_dialog_content = "Casi puedo distinguir algo que brilla ahí abajo.",
  ui_story_70000202_15_dialog_content = "¡Parece la luz de señal de una máquina de algún tipo!",
  ui_story_70000202_16_dialog_content = "¿¡La ciudad sigue operativa!?",
  ui_story_70000202_17_dialog_content = "Esa tubería de extrusión debería servir como base...",
  ui_story_70000202_18_dialog_content = "A esta altura, puedo tomar PlayerName y aterrizar en el fondo.",
  ui_story_70000202_19_dialog_content = "Pero tendremos que encontrar otra salida.",
  ui_story_70000202_20_dialog_content = "La salida... ¿Dice algo en el Manual?",
  ui_story_70000202_21_dialog_content = "¡Creo que sí! ¡Déjeme ver!",
  ui_story_70000202_22_dialog_content = "\"Entrañas 80 tiene un pasaje de escape que va desde la Habitación del Núcleo a la superficie\".",
  ui_story_70000202_23_dialog_content = "Sin embargo, para evitar que el enemigo externo penetre en la ciudad a través del túnel, solo se puede acceder desde adentro.",
  ui_story_70000202_24_dialog_content = "La entrada al túnel está bien escondida detrás de una puerta secreta al lado del núcleo de energía de Entrañas.",
  ui_story_70000202_25_dialog_content = "\"Dale 3 golpes ligeros, 3 golpes fuertes y luego 3 golpes suaves a lo largo de la pared norte de la Habitación del Núcleo para abrir la puerta secreta\".",
  ui_story_70000202_26_dialog_content = "¿¡Hay cosas de las que incluso Sheol no es consciente!?",
  ui_story_70000202_27_dialog_content = "El autor debe haber trabajado o peleado aquí para saber tanto sobre Entrañas 80.",
  ui_story_70000202_28_dialog_content = "Ahora que hemos asegurado la ruta de escape, es hora de moverse.",
  ui_story_70000202_29_dialog_content = "Aférrate a mí, PlayerName.",
  ui_story_70000202_30_dialog_content = "¿Puedo decir que no? Esto casi se siente como...",
  ui_story_70000202_31_dialog_content = "¡Oye!",
  ui_story_70000202_32_dialog_content = "<anim type=Shake>¡Ahhhhhhhhhhh!</anim>",
  ui_story_70000202_33_dialog_content = "Casi como...",
  ui_story_70000202_34_dialog_content = "PlayerName, ¡ten cuidado de no morderte la lengua!",
  ui_story_70000202_35_dialog_content = "<size=45><anim type=Shake>¡Ahhhhhhhh!</anim></size>",
  ui_story_70000202_36_dialog_content = "¡Hola!",
  ui_story_70000202_37_dialog_content = "<size=50><anim type=Shake>¡Ahhhhhhhh!</anim></size>",
  ui_story_70000202_38_dialog_content = "Ya hemos aterrizado, PlayerName...",
  ui_story_70000202_39_dialog_content = "Oh... ¿Es así?",
  ui_story_70000202_40_dialog_content = "¿Estás bien?",
  ui_story_70000202_41_dialog_content = "¿Estamos en el suelo?",
  ui_story_70000202_42_dialog_content = "Estoy tan mareado... Espera...",
  ui_story_70000202_43_dialog_content = "¿Eh? ¿Es porque fue un aterrizaje forzoso? ¿Necesitas descansar un poco?",
  ui_story_70000202_44_dialog_content = "Sólo déjame recuperar el aliento...",
  ui_story_70000202_45_dialog_content = "¿Cómo es la situación circundante?",
  ui_story_70000202_46_dialog_content = "No hay eclipses a la vista todavía.",
  ui_story_70000202_47_dialog_content = "Parece ser el terreno más bajo de Entrañas cercano.",
  ui_story_70000202_48_dialog_content = "Restos de la ruina y máquinas por doquier. También parece haber fragmentos del equipo estándar de Illumina.",
  ui_story_70000202_49_dialog_content = "La marca en la pared dice... <color=#FFB400>Pozo de ventilación 02</color>?",
  ui_story_70000202_50_dialog_content = "Parece que estamos dentro de Entrañas, ¿de acuerdo?",
  ui_story_70000202_51_dialog_content = "Agujeros de bala por todas las paredes... Aquí tuvo lugar una feroz batalla.",
  ui_story_70000202_52_dialog_content = "¿La Guerra de la Zona Oscura?",
  ui_story_70000202_53_dialog_content = "Los casquillos de bala en el suelo son consistentes con las armas estándar de la antigua Illumina. Entonces, eso es probablemente un sí.",
  ui_story_70000202_54_dialog_content = "No es de extrañar que quien haya escrito este manual no quiera que nadie vuelva aquí.",
  ui_story_70000202_55_dialog_content = "Es casi como un fango que... devora la vida.",
  ui_story_70000202_56_dialog_content = "...",
  ui_story_70000202_57_option_content = "(Toca los agujeros de bala)",
  ui_story_70000202_58_option_content = "(Recoge los casquillos de bala)",
  ui_story_70000202_59_dialog_content = "¡N-No te acerques más!",
  ui_story_70000202_60_dialog_content = "*Rugido*",
  ui_story_70000202_61_dialog_content = "Ayuda... ayúdame...",
  ui_story_70000202_62_dialog_content = "¿Eh?",
  ui_story_70000202_63_dialog_content = "¡No me comas! ¡No soy bueno para comer!",
  ui_story_70000202_64_dialog_content = "*Rugido*",
  ui_story_70000202_65_dialog_content = "Mami... quiero a mi mami...",
  ui_story_70000202_66_dialog_content = "Yo... ya no puedo volver...",
  ui_story_70000202_67_dialog_content = "...",
  ui_story_70000202_68_dialog_content = "Lo viste, ¿no? PlayerName?",
  ui_story_70000202_69_dialog_content = "Hmm...",
  ui_story_70000202_70_dialog_content = "No hay nada que podamos hacer al respecto... Déjalo ir.",
  ui_story_70000202_71_dialog_content = "Comprobemos la ubicación de nuestro objetivo.",
  ui_story_70000202_72_dialog_content = "Bueno. Déjame tratar de sentirlo.",
  ui_story_70000202_73_option_content = "¡Establece un vínculo mental!",
  ui_story_70000202_74_dialog_content = "¡...!",
  ui_story_70000202_75_dialog_content = "Lo que estamos buscando todavía está debajo de nosotros.",
  ui_story_70000202_76_dialog_content = "La interferencia es fuerte. Sólo pude obtener una dirección general.",
  ui_story_70000202_77_dialog_content = "¡De esa manera!",
  ui_story_70000202_78_dialog_content = "Otro acantilado...",
  ui_story_70000202_79_dialog_content = "Parece ser más profundo que el anterior, y no hay forma de bajar...",
  ui_story_70000202_80_dialog_content = "Los eclipses definitivamente nos notarán si simplemente saltamos así.",
  ui_story_70000202_81_dialog_content = "Entonces quizás seamos emboscados.",
  ui_story_70000202_82_dialog_content = "Pero mis sentidos nos trajeron aquí, lo que debe significar que esta es la ruta más rápida.",
  ui_story_70000202_83_dialog_content = "¿Cuánto nos queda?",
  ui_story_70000202_84_dialog_content = "No mucho.",
  ui_story_70000202_85_dialog_content = "El día aquí es mucho más corto que en otros lugares. 6 horas como máximo.",
  ui_story_70000202_86_dialog_content = "Si queremos escaparnos durante el día, solo nos quedan unas 3 horas.",
  ui_story_70000202_87_dialog_content = "Vayamos por este camino. Nos ocultaremos en el momento en que aterricemos. Debería ser suficiente.",
  ui_story_70000202_88_dialog_content = "Bien... Confío en ti.",
  ui_story_70000301_1_dialog_content = "¿Dónde están esos dos ahora?",
  ui_story_70000301_2_dialog_content = "A juzgar por el ping en ellos, todavía están dentro de Entrañas 80.",
  ui_story_70000301_3_dialog_content = "Pero la fuerte interferencia de Darkflow está interfiriendo con la señal. Tal vez... ¿en lo más profundo?",
  ui_story_70000301_4_dialog_content = "Espero que todo les vaya bien.",
  ui_story_70000301_5_dialog_content = "No te preocupes. Mantén la cabeza despejada.",
  ui_story_70000301_6_dialog_content = "Ninguna noticia es la mejor noticia con respecto a los operativos encubiertos.",
  ui_story_70000301_7_dialog_content = "¿Por qué dices eso?",
  ui_story_70000301_8_dialog_content = "Cada individuo de Illumina está debajo de mí. Como Gran Mariscal, conozco muy bien las habilidades de mi gente.",
  ui_story_70000301_9_dialog_content = "Además de eso, he mantenido una estrecha vigilancia sobre Vice desde que empezó a trabajar con <color=#FFB400>ese individuo</color>.",
  ui_story_70000301_10_dialog_content = "Así que no tienes que preocuparte. He dejado algunas medidas de seguridad en el Manual.",
  ui_story_70000301_11_dialog_content = "Medidas de seguridad...?",
  ui_story_70000301_12_dialog_content = "Si todavía están en Entrañas en una hora y media, contáctalos a través del comunicador.",
  ui_story_70000301_13_dialog_content = "Sí.",
  ui_story_70000301_14_dialog_content = "...",
  ui_story_70000301_15_dialog_content = "PlayerName, Por aquí.",
  ui_story_70000301_16_dialog_content = "Claramente hemos visto más eclipses aquí...",
  ui_story_70000301_17_dialog_content = "También es cada vez más difícil simplemente caminar...",
  ui_story_70000301_18_dialog_content = "Solo espera, PlayerName.",
  ui_story_70000301_19_dialog_content = "No puedo... estoy exhausto...",
  ui_story_70000301_20_dialog_content = "Es demasiado peligroso aquí. Necesitamos encontrar un lugar seguro si necesitamos descansar.",
  ui_story_70000301_21_dialog_content = "Mira, estamos a solo unos cientos de metros de llegar a la parte superior de la sala principal.",
  ui_story_70000301_22_dialog_content = "Si realmente no puedes caminar... Puedo llevarte.",
  ui_story_70000301_23_dialog_content = "No, está bien.",
  ui_story_70000301_24_dialog_content = "¡Solo necesito recuperar el aliento, eso es todo!",
  ui_story_70000301_25_dialog_content = "Una vez que volvamos a Soroz con el objetivo, ¡te prepararé un festín!",
  ui_story_70000301_26_dialog_content = "No hay necesidad de eso... ¡de verdad!",
  ui_story_70000301_27_dialog_content = "¡No estoy cansada en absoluto! ¡Vamos!",
  ui_story_70000301_28_dialog_content = "¡Eclipsitos por delante! No puedo ver cuántos... Es demasiado oscuro.",
  ui_story_70000301_29_dialog_content = "¿Justo fuera de la entrada del túnel a la cámara central? Esto es difícil.",
  ui_story_70000301_30_dialog_content = "¿Podemos rodearlos?",
  ui_story_70000301_31_dialog_content = "Déjame revisar el mapa.",
  ui_story_70000301_32_dialog_content = "¿¡De dónde sacaste un mapa!?",
  ui_story_70000301_33_dialog_content = "¿Eh? ¿No te diste cuenta?",
  ui_story_70000301_34_dialog_content = "Encontré medio mapa en las ruinas mientras descansabas. Así que simplemente lo copié en el cuaderno.",
  ui_story_70000301_35_dialog_content = "¿Tu memoria es tan buena?",
  ui_story_70000301_36_dialog_content = "Es un dibujo estructural, así que, ¡pan comido!",
  ui_story_70000301_37_dialog_content = "Todas las Entrañas se construyeron siguiendo una cierta lógica. No es difícil recordar el mapa si conoces la lógica de construcción.",
  ui_story_70000301_38_dialog_content = "Por ejemplo, siempre habrá dos o más vías de escape, y los pozos de ventilación están ubicados...",
  ui_story_70000301_39_dialog_content = "¡Detenerse! Solo necesito saber si podemos dar la vuelta a los eclipses.",
  ui_story_70000301_40_dialog_content = "Sí, pero no sé si está bloqueado o no.",
  ui_story_70000301_41_dialog_content = "Además, es todo un desvío. A juzgar por la velocidad a la que vamos ahora mismo, nos costará al menos media hora más.",
  ui_story_70000301_42_dialog_content = "Media hora, ¿verdad? Para empezar, no tenemos mucho tiempo... Cuanto más tiempo estemos aquí, más peligroso es para nosotros...",
  ui_story_70000301_43_dialog_content = "Asi que que hacemos, PlayerName?",
  ui_story_70000301_44_dialog_content = "Se me acaba el tiempo.",
  ui_story_70000301_45_dialog_content = "No tenemos tiempo y no podemos permitirnos el riesgo de un desvío.",
  ui_story_70000301_46_dialog_content = "Qué tal esto, flanqueemos a los Eclipsites.",
  ui_story_70000301_X46_dialog_content = "Llamaré su atención y tú los atacarás por la espalda. Solo asegúrate de conseguirlos rápido.",
  ui_story_70000301_47_dialog_content = "Vamos a hacerlo.",
  ui_story_70000301_48_dialog_content = "Míralo, PlayerName.",
  ui_story_70000302_1_dialog_content = "¿Has notado que esos eclipses eran mucho más fuertes que los que hemos encontrado?",
  ui_story_70000302_2_dialog_content = "Tal vez no sean ellos... Somos nosotros los que nos estamos debilitando.",
  ui_story_70000302_3_dialog_content = "Cuanto más profundo vamos, más difícil me resulta incluso respirar.",
  ui_story_70000302_4_dialog_content = "Además del tiempo, la profundidad también podría desempeñar un papel en la fluctuación de la concentración de Darkflow aquí.",
  ui_story_70000302_5_dialog_content = "Cuanto menos probable es que escapemos, más profundo nos adentramos... No es de extrañar que se llame Mire.",
  ui_story_70000302_6_dialog_content = "Ahora estamos justo encima de la sala central. No hay eclipses alrededor. Estamos a salvo por el momento.",
  ui_story_70000302_7_dialog_content = "PlayerName, no te ves muy bien. Será mejor que te tomes un descanso.",
  ui_story_70000302_8_dialog_content = "Todavía tenemos una hora y media. Unos minutos no afectarán nada.",
  ui_story_70000302_9_dialog_content = "Todavía puedo aguantar un poco más... No puedo esperar...",
  ui_story_70000302_10_dialog_content = "El Manual dice que debes aprovechar cada oportunidad para descansar y mantener tu fuerza cuando luchas en la Zona Oscura.",
  ui_story_70000302_11_dialog_content = "Si no me escuchas, entonces escucha a este veterano.",
  ui_story_70000302_12_dialog_content = "Okay, lo siento, Vice. Nos estoy retrasando.",
  ui_story_70000302_13_dialog_content = "No te preocupes por eso. Somos amigos.",
  ui_story_70000302_14_dialog_content = "Aquí. Siéntate en esta roca.",
  ui_story_70000302_15_dialog_content = "¿Dónde estamos ahora?",
  ui_story_70000302_16_dialog_content = "Según el Manual, deberíamos estar en el almacén ahora. Estamos bastante metidos ahora.",
  ui_story_70000302_17_dialog_content = "Hay bastantes cosas esparcidas por ahí.",
  ui_story_70000302_18_dialog_content = "Latas, cajas médicas vacías y casquillos de bala...",
  ui_story_70000302_19_dialog_content = "Además de fortificaciones improvisadas andrajosas hechas con gasas sucias y restos de hierro.",
  ui_story_70000302_20_dialog_content = "El Soldado Illumina aquí debe haber luchado hasta el último hombre.",
  ui_story_70000302_21_dialog_content = "Sin embargo, todavía lo perdieron.",
  ui_story_70000302_22_dialog_content = "...",
  ui_story_70000302_23_dialog_content = "Solo sé que Illumina perdió mucha gente buena en esa guerra...",
  ui_story_70000302_24_dialog_content = "Si tenemos tiempo, probablemente podríamos encontrar sus placas de identificación aquí...",
  ui_story_70000302_25_dialog_content = "Si podemos llevarlos de regreso a Illumina, sería un cierre para sus familias...",
  ui_story_70000302_26_dialog_content = "Vice...",
  ui_story_70000302_27_dialog_content = "Solo si yo también pudiera ayudar...",
  ui_story_70000302_28_dialog_content = "¿Eh?",
  ui_story_70000302_29_dialog_content = "Esto es-!",
  ui_story_70000302_30_dialog_content = "Que encontraste, PlayerName?",
  ui_story_70000302_31_dialog_content = "Esos fragmentos enterrados en las ruinas... parecen algo familiares.",
  ui_story_70000302_32_dialog_content = "Tienen polvo en la parte superior, pero parecen ser blancos, y los patrones en la parte superior se parecen a...",
  ui_story_70000302_33_dialog_content = "<color=#FFB400>el coloso?</color>",
  ui_story_70000302_34_dialog_content = "¿Eh?",
  ui_story_70000302_35_dialog_content = "Ahora que lo dijiste...",
  ui_story_70000302_36_dialog_content = "Puede parecer que no son más que restos a primera vista, pero si miro más de cerca...",
  ui_story_70000302_37_dialog_content = "¿Son piezas de Colossus?",
  ui_story_70000302_38_dialog_content = "Incluso si no lo son, definitivamente son algo que solo existe en Eraveil.",
  ui_story_70000302_39_dialog_content = "No es de extrañar que el módulo Think Tank diga que lo que necesitamos para reparar el Colossus está aquí.",
  ui_story_70000302_40_dialog_content = "Parece que estamos en el camino correcto.",
  ui_story_70000302_41_dialog_content = "Déjame sentir la ubicación del objetivo de nuevo.",
  ui_story_70000302_42_option_content = "Enlace mental!",
  ui_story_70000302_43_dialog_content = "Esto es-!",
  ui_story_70000302_44_dialog_content = "¡Rugido!",
  ui_story_70000302_45_dialog_content = "¡¿?!",
  ui_story_70000302_46_dialog_content = "PlayerName? ¿Estás bien?",
  ui_story_70000302_47_dialog_content = "Sentí algo... poderoso...",
  ui_story_70000302_48_dialog_content = "Una Eclipsite?",
  ui_story_70000302_49_dialog_content = "Se siente como... pero no estoy seguro...",
  ui_story_70000302_50_dialog_content = "Puedo sentir el poderoso Darkflow que emana de él, pero también a Lumina escondida en su interior.",
  ui_story_70000302_51_dialog_content = "Es como...",
  ui_story_70000302_52_dialog_content = "¿Son monstruos creados por Forsakin aquí?",
  ui_story_70000302_53_dialog_content = "No estoy seguro.",
  ui_story_70000302_54_dialog_content = "Solo sé que esa cosa es muy poderosa.",
  ui_story_70000302_55_dialog_content = "No está cerca de nosotros. Creo que podemos escabullirnos y salir con lo que necesitamos.",
  ui_story_70000302_56_dialog_content = "En silencio...",
  ui_story_70000302_57_dialog_content = "En silencio...",
  ui_story_70000302_58_dialog_content = "Se acabó el tiempo. ¿Eres capaz de contactar con ellos?",
  ui_story_70000302_59_dialog_content = "No, su señal se ha ido por completo, miau.",
  ui_story_70000302_60_dialog_content = "¿Debo enviar un equipo de búsqueda y rescate?",
  ui_story_70000302_61_dialog_content = "Tenga el equipo preparado... Yo mismo lo dirigiré.",
  ui_story_70000302_62_dialog_content = "¿¡Vas!?",
  ui_story_70000302_63_dialog_content = "Por supuesto. Es hora de que haga algo de ejercicio, de todos modos.",
  ui_story_70000302_64_dialog_content = "¿Es demasiado pronto para un desafío a este nivel?",
  ui_story_70000302_65_dialog_content = "Parece que realmente tengo que seguir las reglas...",
  ui_story_70000302_66_dialog_content = "Ya veo. ¡Equipo de rescate, prepárense!",
  ui_story_70000302_67_dialog_content = "(Eclipsian) Las tropas de Illumina se están reuniendo cerca de la frontera de Eternal Night.",
  ui_story_70000302_68_dialog_content = "(Eclipsian) \"Él\" está entre ellos.",
  ui_story_70000302_69_dialog_content = "(Eclipsian) Casi al mismo tiempo, Caelestite llegó a Entrañas 80.",
  ui_story_70000302_70_dialog_content = "Entrañas 80...",
  ui_story_70000302_71_dialog_content = "¿Ella también está buscando <color=#FFB400>\"ese\"</color>?",
  ui_story_70000302_72_dialog_content = "Suficientemente cierto. Es el único lugar donde aún podría existir una pista en este mundo.",
  ui_story_70000302_73_dialog_content = "Muéstrame lo que puedes encontrar...",
  ui_story_70000302_74_dialog_content = "Mi hermana.\"",
  ui_story_70000401_1_dialog_content = "Dame tu mano, PlayerName.",
  ui_story_70000401_2_dialog_content = "¡Oye!",
  ui_story_70000401_3_dialog_content = "Finalmente... estamos... aquí...",
  ui_story_70000401_4_dialog_content = "No es broma lo concentrado que está Darkflow aquí... Mover un músculo nunca ha sido tan difícil.",
  ui_story_70000401_5_dialog_content = "PlayerName, es lo que estamos buscando realmente aquí?",
  ui_story_70000401_6_dialog_content = "Puedo sentirlo. Está cerca.",
  ui_story_70000401_7_dialog_content = "Debería estar... justo encima de la máquina en la sala principal.",
  ui_story_70000401_8_dialog_content = "Debe ser esa cosa!",
  ui_story_70000401_9_dialog_content = "¿Es esto... realmente una plantilla de eco?",
  ui_story_70000401_10_dialog_content = "No se parece en nada al que tenían los Soroz.",
  ui_story_70000401_11_dialog_content = "Pero el módulo Think Tank nos señaló esto.",
  ui_story_70000401_12_dialog_content = "Nada alrededor podría ser una plantilla de eco.",
  ui_story_70000401_13_dialog_content = "Regresemos al Soroz y veamos.",
  ui_story_70000401_14_dialog_content = "Está bien, pero está instalado en el núcleo.",
  ui_story_70000401_15_dialog_content = "Voy a ver si puedo sacarlo.",
  ui_story_70000401_16_dialog_content = "Hmm...",
  ui_story_70000401_17_dialog_content = "Sin alegría. Está realmente incrustado allí.",
  ui_story_70000401_18_dialog_content = "PlayerName, dame una mano con esto.",
  ui_story_70000401_19_dialog_content = "¡Aquí vienen!",
  ui_story_70000401_20_dialog_content = "A la cuenta de tres...",
  ui_story_70000401_21_dialog_content = "Tres...",
  ui_story_70000401_22_dialog_content = "Dos...",
  ui_story_70000401_23_dialog_content = "Uno...",
  ui_story_70000401_24_dialog_content = "¡Ahora!",
  ui_story_70000401_25_dialog_content = "¡Agh!",
  ui_story_70000401_26_dialog_content = "Creo que me golpeé algo en la nuca... ¿Está intacto el módulo?",
  ui_story_70000401_27_dialog_content = "Se ve bien. ¡Démonos prisa y salgamos de aquí!",
  ui_story_70000401_28_dialog_content = "<color=#e8d9bb>*retumba*</color>",
  ui_story_70000401_29_dialog_content = "¿Es un terremoto?",
  ui_story_70000401_30_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_70000401_31_dialog_content = "El suministro de energía de Entrañas... ¿acaba de detenerse?",
  ui_story_70000401_32_dialog_content = "¿Es porque tomamos el módulo?",
  ui_story_70000401_33_dialog_content = "No sé, pero puedo sentir...",
  ui_story_70000401_34_dialog_content = "<color=#e8d9bb>¡¡Boom—!!</color>",
  ui_story_70000401_36_dialog_content = "¡Se está acercando!",
  ui_story_70000401_37_dialog_content = "¡Está bajando!",
  ui_story_70000401_37X1_dialog_content = "PlayerName¡Aléjate de esa pared!",
  ui_story_70000401_37X2_dialog_content = "*tos tos*",
  ui_story_70000401_37X3_dialog_content = "tan polvoriento...",
  ui_story_70000401_37X4_dialog_content = "...",
  ui_story_70000401_37X5_dialog_content = "¿Hay un espacio abierto en la parte posterior de la pared derrumbada...?",
  ui_story_70000401_37X6_dialog_content = "Qué hay adentro...?",
  ui_story_70000401_37X7_dialog_content = "...",
  ui_story_70000401_37X8_dialog_content = "¡El Darkflow es sofocante!",
  ui_story_70000401_37X9_dialog_content = "¿Podría ser el eclipse? PlayerName sentido...?",
  ui_story_70000401_37X10_dialog_content = "¡...!",
  ui_story_70000401_37X11_dialog_content = "¡Realmente es un eclipse! ¡Un tipo que nunca hemos visto antes!",
  ui_story_70000401_37X12_dialog_content = "No parece reaccionar a nuestra presencia... ¿Estará durmiendo?",
  ui_story_70000401_37X13_dialog_content = "No lo molestemos. Pasémoslo a escondidas y encontremos la salida...",
  ui_story_70000401_37X14_dialog_content = "Sin embargo, debemos golpear la pared para revelar la salida, que definitivamente lo despertará.",
  ui_story_70000401_37X15_dialog_content = "Si eso sucede, usted—",
  ui_story_70000401_37X16_dialog_content = "Ilu...",
  ui_story_70000401_37X17_dialog_content = "¿Está hablando en sueños?",
  ui_story_70000401_37X18_dialog_content = "Es demasiado lejos. No puedo hacerlo.",
  ui_story_70000401_37X19_dialog_content = "Hay montones de eclipses que hablan...",
  ui_story_70000401_37X20_dialog_content = "No importa. ¡Intentemos salir de aquí primero!",
  ui_story_70000401_37X21_dialog_content = "Estás en lo correcto.",
  ui_story_70000401_37X22_dialog_content = "Ilu...mina...!",
  ui_story_70000401_37X23_dialog_content = "Espera, ¿escuchaste eso? Decía-",
  ui_story_70000401_37X24_dialog_content = "¡Rugido!",
  ui_story_70000401_37X25_dialog_content = "¡Ay! ¡Está despierto!",
  ui_story_70000401_37X26_dialog_content = "¡Correr! ¡Nos ha visto!",
  ui_story_70000401_38_dialog_content = "¡Cuidado, PlayerName!",
  ui_story_70000401_39_dialog_content = "¡Vice! ¿Estás bien?",
  ui_story_70000401_39X1_dialog_content = "El Darkflow es demasiado fuerte. ¡No podemos luchar aquí! ¡Busca una oportunidad para salir de aquí!",
  ui_story_70000401_40_dialog_content = "¡Tú mantenlo distraído mientras yo encuentro la salida!",
  ui_story_70000401_41_dialog_content = "Argh...",
  ui_story_70000401_42_dialog_content = "¡Entiendo! ¡No puedo aguantar mucho, así que será mejor que te des prisa y encuentres esa puerta secreta!",
  ui_story_70000402_1_dialog_content = "La luz llama...",
  ui_story_70000402_2_dialog_content = "<color=#e8d9bb>¡Toc, toc, toc!</color>",
  ui_story_70000402_3_dialog_content = "Tres fuertes golpes...",
  ui_story_70000402_4_dialog_content = "<color=#e8d9bb>¡Golpe! ¡Golpe! ¡Golpe!</color>",
  ui_story_70000402_5_dialog_content = "La luz llama...",
  ui_story_70000402_6_dialog_content = "<color=#e8d9bb>¡Toc, toc, toc!</color>",
  ui_story_70000402_7_dialog_content = "...",
  ui_story_70000402_8_dialog_content = "¿¡Ninguna cosa!? ¿En serio?",
  ui_story_70000402_9_dialog_content = "¡Abrir!",
  ui_story_70000402_10_dialog_content = "Ya lo tienes, PlayerName?",
  ui_story_70000402_11_dialog_content = "¡No está haciendo nada!",
  ui_story_70000402_12_dialog_content = "*Rugido*",
  ui_story_70000402_13_dialog_content = "¡Urgh...!",
  ui_story_70000402_14_dialog_content = "¡Esto no funcionará! ¡Retirémonos más adentro!",
  ui_story_70000402_15_dialog_content = "¡Es un callejón sin salida allá atrás!",
  ui_story_70000402_16_dialog_content = "¡No hay otra manera!",
  ui_story_70000402_17_dialog_content = "Pero esa cosa está en nuestro camino de regreso a la superficie... ¡No podemos abrirnos paso!",
  ui_story_70000402_18_dialog_content = "¡Podríamos tener una oportunidad en las profundidades!",
  ui_story_70000402_19_dialog_content = "Tienes razón...",
  ui_story_70000402_20_dialog_content = "¡Entonces deja de pararte y corre!",
  ui_story_70000402_21_dialog_content = "*Rugido*",
  ui_story_70000402_22_dialog_content = "<color=#e8d9bb>¡Estruendo...!</color>",
  ui_story_70000402_23_dialog_content = "R-Informe!",
  ui_story_70000402_24_dialog_content = "¡Se detecta un fuerte terremoto en la dirección de las ruinas de Entrañas 80!",
  ui_story_70000402_25_dialog_content = "¡Firme! ¡Firme!",
  ui_story_70000402_26_dialog_content = "Mantén tu formación defensiva. Continúe hasta Entrañas 80.",
  ui_story_70000402_27_dialog_content = "¡Sí!",
  ui_story_70000402_28_dialog_content = "<color=#e8d9bb>¡Gahhhhhh!</color>",
  ui_story_70000402_29_dialog_content = "¡¿Qué es ese sonido?!",
  ui_story_70000402_30_dialog_content = "Eso es...",
  ui_story_70000402_31_dialog_content = "¡...!",
  ui_story_70000402_32_dialog_content = "Esta sensación...",
  ui_story_70000402_33_dialog_content = "No, no es posible...",
  ui_story_70000402_34_dialog_content = "Gran Mariscal, ¿estás bien?",
  ui_story_70000402_35_dialog_content = "...",
  ui_story_70000402_36_dialog_content = "No. No puedo enviarlos.",
  ui_story_70000402_37_dialog_content = "No es algo que puedan manejar.",
  ui_story_70000402_38_dialog_content = "¡Rescate, regrese a la Línea Segura inmediatamente! ¡Es una orden!",
  ui_story_70000402_39_dialog_content = "No entres en la Zona Oscura pase lo que pase.",
  ui_story_70000402_40_dialog_content = "¡Sí, señor! Pero... Gran Mariscal...",
  ui_story_70000402_41_dialog_content = "No te preocupes. Ciertas cosas que debo cuidar de mí mismo.",
  ui_story_70000402_42_dialog_content = "también, pase Vivian un mensaje de mi...",
  ui_story_70000402_43_dialog_content = "Pídele que se ocupe de \"esa gente\" antes de que yo regrese.",
  ui_story_70000402_44_dialog_content = "¡Sí!",
  ui_story_70000402_45_dialog_content = "<color=#e8d9bb>¡Gahhhhhh!</color>",
  ui_story_70000402_46_dialog_content = "...",
  ui_story_70000402_47_dialog_content = "Así que quedan \"pistas\" aquí, de hecho.",
  ui_story_70000402_48_dialog_content = "\"Nada no deja rastro\".",
  ui_story_70000402_49_dialog_content = "Tomaré esta pieza del rompecabezas, entonces.",
  ui_story_70000402_50_dialog_content = "abandonando...",
  ui_story_70000402_51_dialog_content = "No olvides tu promesa.",
  ui_story_70000402_52_dialog_content = "Tsk...",
  ui_story_70000402_53_dialog_content = "Bien.",
  ui_story_70000402_54_dialog_content = "Todo lo que tienes que hacer es esperar mi señal y ahuyentar a esos gusanos.",
  ui_story_70000402_55_dialog_content = "Su vacilación sólo conducirá a su fracaso.",
  ui_story_70000402_56_dialog_content = "Aficionado.",
  ui_story_70000402_57_dialog_content = "Que tonto...",
  ui_story_70000501_1_dialog_content = "Hay rastros de Luminatic aún no devorados por Darkflow. Es bastante reciente.",
  ui_story_70000501_2_dialog_content = "Huellas de eclipses... Unas diez de ellas. Sin embargo, no es señal de una gran batalla.",
  ui_story_70000501_3_dialog_content = "Debe ser un ataque furtivo para evitar una batalla prolongada.",
  ui_story_70000501_4_dialog_content = "Las tácticas se usaron maravillosamente. Incluso el terreno fue bien tomado en consideración...",
  ui_story_70000501_5_dialog_content = "Bien hecho. Finalmente te estás convirtiendo en un líder.",
  ui_story_70000501_6_dialog_content = "Pero... ¿cuánto tiempo puedes seguir con vida en un lugar como este?",
  ui_story_70000501_7_dialog_content = "<color=#e8d9bb>*retumba*</color>",
  ui_story_70000501_8_dialog_content = "¿Atrapado?",
  ui_story_70000501_9_dialog_content = "Se enfatiza repetidamente en el Manual, pero aun así cometieron un error de novato como este.",
  ui_story_70000501_10_dialog_content = "Debería darles una lección cuando regresen.",
  ui_story_70000501_11_dialog_content = "Vice, muévase hacia atrás a su derecha!",
  ui_story_70000501_12_dialog_content = "¡Ok!",
  ui_story_70000501_13_dialog_content = "¡Prueba esto!",
  ui_story_70000501_14_dialog_content = "*Rugido*",
  ui_story_70000501_15_dialog_content = "¡Nuestros ataques no funcionan!",
  ui_story_70000501_16_dialog_content = "¡El Darkflow es demasiado fuerte aquí!",
  ui_story_70000501_17_dialog_content = "¡Intentaré contenerlo!",
  ui_story_70000501_18_option_content = "Control forzado...",
  ui_story_70000501_19_dialog_content = "Ilu...",
  ui_story_70000501_20_dialog_content = "Ilu?",
  ui_story_70000501_21_dialog_content = "¿Qué... está tratando de decir?",
  ui_story_70000501_22_dialog_content = "Ilumina... mina...",
  ui_story_70000501_23_dialog_content = "¿Ilumina? ¿La Federación Illumina?",
  ui_story_70000501_24_dialog_content = "¡Illumina!",
  ui_story_70000501_25_dialog_content = "¡Puaj! ¡Qué odio tan fuerte!",
  ui_story_70000501_26_dialog_content = "¡¿PlayerName?!",
  ui_story_70000501_27_dialog_content = "¡Estoy bien!",
  ui_story_70000501_28_dialog_content = "Ese Eclipsite es diferente... ¡Parece albergar un fuerte odio por Illumina!",
  ui_story_70000501_29_dialog_content = "¡Ilumina... mina! ¡Rugido!",
  ui_story_70000501_30_dialog_content = "¿Nos atacó porque me vio usando el uniforme de Illumina?",
  ui_story_70000501_31_dialog_content = "PlayerName¡Lo mantendré ocupado mientras intentas salir!",
  ui_story_70000501_32_dialog_content = "¿¡Tú que tal!?",
  ui_story_70000501_33_dialog_content = "¡No te preocupes por mí! ¡Preocúpate por ti mismo!",
  ui_story_70000501_34_dialog_content = "¡Illumina!",
  ui_story_70000501_35_dialog_content = "¡Urgh...!",
  ui_story_70000501_36_dialog_content = "¡Vice!",
  ui_story_70000501_37_dialog_content = "necesito ahorrar Vice!",
  ui_story_70000501_38_dialog_content = "¡Yo! ¡Eres un gran estúpido! ¡Oye! ¡Estoy aquí!",
  ui_story_70000501_39_dialog_content = "*Rugido*",
  ui_story_70000501_40_dialog_content = "PlayerName... Corre corre...!",
  ui_story_70000501_41_dialog_content = "¡Venir a buscarme!",
  ui_story_70000501_42_dialog_content = "*Rugido*",
  ui_story_70000501_43_dialog_content = "¡Tan rapido!",
  ui_story_70000501_44_dialog_content = "¡Uh!",
  ui_story_70000501_45_dialog_content = "¡¿PlayerName?!",
  ui_story_70000501_46_dialog_content = "¿Voy a... morir aquí...?",
  ui_story_70000501_47_dialog_content = "Alguien... Por favor... Sálvanos...",
  ui_story_70000501_48_dialog_content = "*Rugidos*",
  ui_story_70000501_49_dialog_content = "<color=#e8d9bb>¡Clang—!</color>",
  ui_story_70000501_50_dialog_content = "Un comandante nunca debe apartar la vista del campo de batalla.",
  ui_story_70000501_51_dialog_content = "Eso es...",
  ui_story_70000501_52_dialog_content = "¿¡Reinhardt!?",
  ui_story_70000501_53_dialog_content = "PlayerName Caelestite, tienes potencial para ser un buen comandante, pero necesitas mucho entrenamiento.",
  ui_story_70000501_54_dialog_content = "Lo tendré Barton y Gram para ponerte en forma!",
  ui_story_70000501_55_dialog_content = "¡¿Eh?!",
  ui_story_70000501_56_dialog_content = "¡Ilumina! ¡Ilumina!",
  ui_story_70000501_57_dialog_content = "!",
  ui_story_70000501_58_dialog_content = "¡Gran Mariscal... Reinhardt...!",
  ui_story_70000501_59_dialog_content = "Si todavía puedes moverte, encuentra algo de cobertura.",
  ui_story_70000501_60_dialog_content = "¡Vicio! ¡De esta manera!",
  ui_story_70000501_61_dialog_content = "¡Rugido!",
  ui_story_70000501_62_dialog_content = "Entonces, realmente eres tú.",
  ui_story_70000501_63_dialog_content = "Incluso si te convirtió en la mitad de un Eclipsite, todavía no ha cambiado la forma en que peleas.",
  ui_story_70000501_64_dialog_content = "¿Reinhardt... está hablando con ese Eclipsite?",
  ui_story_70000501_65_dialog_content = "¿Olvidaste quién eres?",
  ui_story_70000501_66_dialog_content = "Mi viejo amigo.\"",
  ui_story_70000501_67_dialog_content = "\"Viejo amigo\"...?",
  ui_story_70000501_68_dialog_content = "¡Gahhhh!",
  ui_story_70000501_69_dialog_content = "¡El Darkflow es fuerte aquí! ¡Reinhardt está en desventaja!",
  ui_story_70000501_70_dialog_content = "Tendremos que intentar distraer a ese Eclipsite...",
  ui_story_70000501_71_dialog_content = "Enlace mental!",
  ui_story_70000501_72_dialog_content = "*Rugidos*",
  ui_story_70000501_73_dialog_content = "¡Ahhh!",
  ui_story_70000501_74_dialog_content = "<color=#e8d9bb>¡Estruendo...!</color>",
  ui_story_70000501_75_dialog_content = "¡Este tipo... literalmente está tirando su vida por la borda!",
  ui_story_70000501_76_dialog_content = "¿Acaso le importa que pueda derribar a toda Entrañas?",
  ui_story_70000501_77_dialog_content = "PlayerName, Déjame esto a mi.",
  ui_story_70000501_78_dialog_content = "Calma.",
  ui_story_70000501_78X1_dialog_content = "!",
  ui_story_70000501_78X2_dialog_content = "Reinhardt?! ¡Aléjate de ahí!",
  ui_story_70000501_78X3_dialog_content = "Gran Mariscal!",
  ui_story_70000501_78X4_dialog_content = "No te preocupes. De verdad, estoy bien.",
  ui_story_70000501_78X5_dialog_content = "Hay una cosa... que tengo que probar primero.",
  ui_story_70000501_79_dialog_content = "Pero...",
  ui_story_70000501_80_dialog_content = "PlayerName, sólo confía en el Gran Mariscal...",
  ui_story_70000501_81_dialog_content = "Reinhardt... ¿Por qué no se defiende?",
  ui_story_70000501_82_dialog_content = "¿Aún recuerdas?",
  ui_story_70000501_83_dialog_content = "Una vez luchamos codo con codo y rechazamos a innumerables enemigos.",
  ui_story_70000501_84_dialog_content = "...",
  ui_story_70000501_85_dialog_content = "Cavamos las trincheras, resistimos oleadas tras oleadas de ataques enemigos solo para proteger nuestro hogar, Gannon.",
  ui_story_70000501_86_dialog_content = "Gan... no...",
  ui_story_70000501_87_dialog_content = "Sí. Gannon. Éramos sus hijos, e hicimos votos en su nombre.",
  ui_story_70000501_88_dialog_content = "¿Todavía recuerdas tu nombre?",
  ui_story_70000501_89_dialog_content = "Gah...",
  ui_story_70000501_90_dialog_content = "Usted está... <color=#FFB400>Helio</color>.",
  ui_story_70000501_91_dialog_content = "Ilumina... mina...",
  ui_story_70000501_92_dialog_content = "¡Illumina!",
  ui_story_70000501_93_dialog_content = "*Rugido*",
  ui_story_70000501_94_dialog_content = "Tsk... ¿No funcionó...?",
  ui_story_70000501_95_dialog_content = "Gran Mariscal! ¡Cuidado!",
  ui_story_70000501_96_dialog_content = "¡La estructura aquí es demasiado frágil para soportar otro golpe!",
  ui_story_70000501_97_dialog_content = "¡Si esto continúa, toda Entrañas podría colapsar!",
  ui_story_70000501_98_dialog_content = "¡Rugido!",
  ui_story_70000501_99_dialog_content = "A veces hay que mirarse al espejo...",
  ui_story_70000501_100_dialog_content = "Recuerda... Recuerda quién eres en realidad.",
  ui_story_70000501_101_dialog_content = "Vuelve a Illumina conmigo. ¡Encontraré una manera de tratarte y hacerte regresar!",
  ui_story_70000501_102_dialog_content = "*Rugido*",
  ui_story_70000501_103_dialog_content = "*Tose*",
  ui_story_70000501_104_dialog_content = "PlayerName, ¡Por aquí!",
  ui_story_70000501_105_dialog_content = "<color=#e8d9bb>Timbre...</color>",
  ui_story_70000501_106_dialog_content = "!",
  ui_story_70000501_107_dialog_content = "Aquí...",
  ui_story_70000501_108_dialog_content = "El sonido de una campana... ¿De dónde viene?",
  ui_story_70000501_109_dialog_content = "¡Rugido!",
  ui_story_70000501_110_dialog_content = "Ese eclipse de alto nivel... ¿Se subió al acantilado y despegó sin mirar atrás?",
  ui_story_70000501_111_dialog_content = "¿La campana controla los eclipses?",
  ui_story_70000501_112_dialog_content = "No.",
  ui_story_70000501_113_dialog_content = "Esa campana solo significa una cosa: <color=#FFB400>\"Llegó el refuerzo. Retirada\".</color>",
  ui_story_70000501_114_dialog_content = "Ese Eclipsite... ¿es alguien que conocías?",
  ui_story_70000501_115_dialog_content = "Más que conocidos. Éramos hermanos de armas.",
  ui_story_70000501_116_dialog_content = "Alguien en quien pudiera confiar con mi vida.",
  ui_story_70000501_117_dialog_content = "Fue MIA en esta Entrañas durante la Guerra de la Zona Oscura.",
  ui_story_70000501_118_dialog_content = "Pensé que había muerto... No pensé...",
  ui_story_70000501_119_dialog_content = "No pensé que se hubiera convertido en un Eclipsite en su lugar.",
  ui_story_70000501_120_dialog_content = "¿Convertido en un eclipse? Eso casi suena como...",
  ui_story_70000501_121_dialog_content = "Estoy realmente confundido acerca de lo que realmente le sucedió en este momento.",
  ui_story_70000501_122_dialog_content = "<color=#e8d9bb>¡Estruendo...!</color>",
  ui_story_70000501_123_dialog_content = "Me temo que este será el final de Entrañas.",
  ui_story_70000501_124_dialog_content = "Salgamos de aquí, y hablaremos de eso en el camino de regreso.",
  ui_story_70000501_125_dialog_content = "Eso es lo que haremos entonces.",
  ui_story_70000501_126_dialog_content = "Conozco la salida. Sígueme.",
  ui_story_70000601_1_dialog_content = "Una vez tuve dos queridos amigos. <color=#FFB400>helios</color>, El era uno de ellos.",
  ui_story_70000601_1X1_dialog_content = "Creo que el otro tampoco es extraño para ti. En ese entonces era conocida como <color=#FFB400>negador</color>.",
  ui_story_70000601_1X2_dialog_content = "¿Renegado?",
  ui_story_70000601_1X3_dialog_content = "Sí. Ese es su nombre ahora.",
  ui_story_70000601_2_dialog_content = "Juntos crecimos en el Hospital Fundador de Illumina. Juntos nos unimos al ejército y luchamos en las batallas.",
  ui_story_70000601_3_dialog_content = "Denier, Reinhardt, ¿saben lo que van a hacer?",
  ui_story_70000601_4_dialog_content = "Estoy bastante dotado según mi instructor. Podría convertirme en un explorador excepcional algún día.",
  ui_story_70000601_5_dialog_content = "Soy diferente a todos ustedes. El laboratorio es mi campo de batalla.",
  ui_story_70000601_6_dialog_content = "Parece que alguien encaja mejor para el papel de imbécil que yo.",
  ui_story_70000601_7_dialog_content = "Sigues siendo aficionado al sarcasmo como siempre.",
  ui_story_70000601_8_dialog_content = "¿Y tú, Reinhardt?",
  ui_story_70000601_9_dialog_content = "¿Yo?",
  ui_story_70000601_10_dialog_content = "Todavía estoy pensando en ello. Pero tal vez voy a empezar poco a poco.",
  ui_story_70000601_11_dialog_content = "Comenzaré siendo el Gran Mariscal de Illumina.",
  ui_story_70000601_12_dialog_content = "Poco después, nuestro logro fue finalmente reconocido por el liderazgo y el comité de Illumina.",
  ui_story_70000601_13_dialog_content = "Y todos nos convertimos en candidatos para el próximo Gran Mariscal.",
  ui_story_70000601_14_dialog_content = "Ustedes son los mejores soldados de Illumina. El futuro de Illumina está sobre tus hombros.",
  ui_story_70000601_15_dialog_content = "Y estás a punto de pasar por el entrenamiento intenso más brutal de todo Illumina.",
  ui_story_70000601_16_dialog_content = "Cada día, cada hora, alguien será eliminado.",
  ui_story_70000601_17_dialog_content = "El vencedor al final se convertirá en el Gran Mariscal de Illumina.",
  ui_story_70000601_18_dialog_content = "¿Tienes la confianza?",
  ui_story_70000601_19_dialog_content = "¿¡Ser el más fuerte de tu grupo!?",
  ui_story_70000601_20_dialog_content = "Sí.",
  ui_story_70000601_21_dialog_content = "¡Sí!",
  ui_story_70000601_22_dialog_content = "¡SÍ!",
  ui_story_70000601_23_dialog_content = "<color=#FFB400>El Comité</color>? ¿Que es eso?",
  ui_story_70000601_24_dialog_content = "¿Eh? No has oído hablar del Comité, PlayerName?",
  ui_story_70000601_25_dialog_content = "¡Nada en absoluto!",
  ui_story_70000601_26_dialog_content = "¡La agencia que gestiona todos los asuntos de Illumina junto con el Gran Mariscal Reinhardt!",
  ui_story_70000601_27_dialog_content = "Bueno, todo el mundo habla del Gran Mariscal...",
  ui_story_70000601_28_dialog_content = "Pero en realidad nadie dice nada sobre algún comité.",
  ui_story_70000601_29_dialog_content = "*Tose*",
  ui_story_70000601_30_dialog_content = "(¡Oh, maldita sea! ¡Olvidé que el Gran Mariscal está aquí mismo!)",
  ui_story_70000601_31_dialog_content = "El comité es la abreviatura de <color=#FFB400>El Comité de Asuntos Militares y Políticos de la Federación Illumina</color>.",
  ui_story_70000601_32_dialog_content = "Son un montón de antigüedades obsoletas a las que les gusta microgestionar todo lo relacionado con Illumina.",
  ui_story_70000601_33_dialog_content = "Pero saben cómo mantener un perfil bajo, por lo que es normal que las personas rara vez sepan de ellos.",
  ui_story_70000601_34_dialog_content = "(Gracias a Dios, la propia Reinhardt viene a rescatarme...)",
  ui_story_70000601_35_dialog_content = "¿Eh? Espera... ¿Eso significa...?",
  ui_story_70000601_36_dialog_content = "¿El Comité decide quién llega a ser el Gran Mariscal?",
  ui_story_70000601_37_dialog_content = "¿Eh?",
  ui_story_70000601_38_dialog_content = "¿No debería el Gran Mariscal ser alguien muy condecorado?",
  ui_story_70000601_39_dialog_content = "Al menos el libro de texto de mis días escolares lo decía...",
  ui_story_70000601_40_dialog_content = "Eso es solo una parte.",
  ui_story_70000601_41_dialog_content = "Es una cosa difícil unir a la gente.",
  ui_story_70000601_41X_dialog_content = "La Federación Illumina está compuesta por muchas Entrañas. La reputación por sí sola no puede ganárselos.",
  ui_story_70000601_42_dialog_content = "Si la reputación militar por sí sola determina quién llega a ser el Gran Mariscal... ¿Qué pasa si no tienen ninguna habilidad de liderazgo?",
  ui_story_70000601_43_dialog_content = "¿Qué pasaría si fuera un tipo grosero que desenfrenadamente participara en una agresión militar?",
  ui_story_70000601_44_dialog_content = "¿Deberíamos seguirlos y poner todos los recursos de Illumina en la construcción de muros y baterías de armas?",
  ui_story_70000601_44X_dialog_content = "¿Y luego esperar a marchitarse y morir?",
  ui_story_70000601_45_dialog_content = "Bueno.",
  ui_story_70000601_46_dialog_content = "Ya estamos acá.",
  ui_story_70000601_47_dialog_content = "¡Estamos... completamente rodeados de ruinas aquí!",
  ui_story_70000601_48_dialog_content = "No entrar en pánico. Recuerdo que la entrada es...",
  ui_story_70000601_49_dialog_content = "¿¡Un pasaje oculto, aquí!?",
  ui_story_70000601_50_dialog_content = "Para ser precisos, es un túnel de escape.",
  ui_story_70000601_51_dialog_content = "Los túneles de escape de Entrañas se han reforzado probablemente debido a los frecuentes terremotos.",
  ui_story_70000601_52_dialog_content = "Una vez llevé a los hombres a romper un sitio aquí.",
  ui_story_70000601_53_dialog_content = "Pasa adelante...",
  ui_story_70000601_54_dialog_content = "Hay tanto silencio...",
  ui_story_70000601_55_dialog_content = "Vice, dame tu mano.",
  ui_story_70000601_56_dialog_content = "Gracias, PlayerName.",
  ui_story_70000601_57_dialog_content = "Estoy bien con eso.",
  ui_story_70000601_58_dialog_content = "Estabas bajo un ataque feroz. Será mejor que guardes tus fuerzas.",
  ui_story_70000601_59_dialog_content = "Ya sabes... Incluso si ustedes dos son extremadamente capaces, deben conocer sus límites.",
  ui_story_70000601_60_dialog_content = "Solo si seguiste el Manual y regresaste a la superficie cuando se acabó el tiempo...",
  ui_story_70000601_60X_dialog_content = "Habrías evitado todo esto.",
  ui_story_70000601_61_dialog_content = "¿Conocías el Manual? Será que...",
  ui_story_70000601_62_dialog_content = "Yo lo escribí, por supuesto. Y también sé que le pediste a Philyshy que investigara Entrañas 80.",
  ui_story_70000601_63_dialog_content = "!",
  ui_story_70000601_64_dialog_content = "¿Por qué me miras?",
  ui_story_70000601_65_dialog_content = "Soy el único en toda la Federación Illumina que luchó en la Guerra de la Zona Oscura y volvió con vida.",
  ui_story_70000601_66_dialog_content = "Esta Entrañas 80 era donde yo estaba destinado.",
  ui_story_70000601_67_dialog_content = "¿Cómo no saber si alguien está investigando esta Entrañas?",
  ui_story_70000601_68_dialog_content = "Entonces, porque estas aqui...?",
  ui_story_70000601_69_dialog_content = "Pensé que estarías en Gannon.",
  ui_story_70000601_70_dialog_content = "Te permití explorar esta región porque confío en tus habilidades.",
  ui_story_70000601_71_dialog_content = "Pero eso no significa que no piense en posibles accidentes. Ni dejaré a ninguno de vosotros en peligro.",
  ui_story_70000601_72_dialog_content = "Es el deber de un Gran Mariscal proteger a todos en Illumina.",
  ui_story_70000601_73_dialog_content = "Que te incluye a ti, un aliado de Illumina, PlayerName.",
  ui_story_70000601_74_dialog_content = "Uf... Cierto...",
  ui_story_70000601_75_dialog_content = "Tan pronto como supe que ibas a investigar Entrañas 80...",
  ui_story_70000601_75X_dialog_content = "Inmediatamente llevé a los hombres a esperar en la Línea Segura en el borde de la Zona Oscura.",
  ui_story_70000601_76_dialog_content = "Quería que fuera una prueba de tu fuerza.",
  ui_story_70000601_77_dialog_content = "Si completaste tu misión sin problemas, fingiría que no pasó nada.",
  ui_story_70000601_78_dialog_content = "Pero para mi sorpresa, te metiste en un peligro real.",
  ui_story_70000601_79_dialog_content = "Todo iba sobre ruedas, hasta que nos encontramos con un enemigo poderoso que no esperábamos bajo tierra...",
  ui_story_70000601_79X_dialog_content = "Las consecuencias serían demasiado espantosas para contemplarlas si no hubiera sentido la presencia de Helios y corrido a rescatarlo.",
  ui_story_70000601_80_dialog_content = "Confía en la información, pero prepárate para más.",
  ui_story_70000601_81_dialog_content = "Harías bien en recordar eso si quieres ser un buen comandante.",
  ui_story_70000601_82_dialog_content = "Ok...",
  ui_story_70000601_83_dialog_content = "No regresaste en el tiempo asignado. Tuve que asumir lo peor.",
  ui_story_70000601_84_dialog_content = "Inicialmente, pensé que eran solo algunos eclipses. Realmente no esperaba que fuera él...",
  ui_story_70000601_85_dialog_content = "Oh, cómo el destino tiene un sentido del humor retorcido.",
  ui_story_70000601_86_dialog_content = "...",
  ui_story_70000601_87_dialog_content = "Olvida eso.",
  ui_story_70000601_88_dialog_content = "Abre esta puerta y estaremos en el túnel de escape.",
  ui_story_70000601_89_dialog_content = "Síguelo hacia arriba para llegar a la superficie.",
  ui_story_70000601_90_dialog_content = "<color=#e8d9bb>Criiiiik...</color>",
  ui_story_70000601_91_dialog_content = "Realmente no ha sido dañado por los terremotos.",
  ui_story_70000601_92_dialog_content = "Incluso puedo sentir una brisa fresca.",
  ui_story_70000601_93_dialog_content = "¡Esto significa que conduce al exterior!",
  ui_story_70000601_94_dialog_content = "Tranquilo. El túnel amplifica tu voz.",
  ui_story_70000601_95_dialog_content = "Puede haber eclipses al acecho en el túnel.",
  ui_story_70000601_96_dialog_content = "*Rugido*",
  ui_story_70000601_97_dialog_content = "Hablando del diablo...",
  ui_story_70000601_98_dialog_content = "¡Lo-lo siento!",
  ui_story_70000601_99_dialog_content = "Prepárate para luchar, Caelestite. ¡Muéstrame lo bueno que eres como comandante!",
  ui_story_70000602_1_dialog_content = "Por qué...",
  ui_story_70000602_2_dialog_content = "Vamos hacia arriba, pero, de alguna manera, Darkflow solo se vuelve más fuerte... ¿Por qué?",
  ui_story_70000602_3_dialog_content = "De verdad...",
  ui_story_70000602_4_dialog_content = "Justo ahora, pude manejar algunos eclipses, pero ahora, incluso uno o dos es más de lo que puedo manejar...",
  ui_story_70000602_5_dialog_content = "Anoté la razón en el Manual. ¿Todavía recuerdas por qué?",
  ui_story_70000602_6_dialog_content = "¿Agotamiento físico?",
  ui_story_70000602_7_dialog_content = "No.",
  ui_story_70000602_8_dialog_content = "Esa es una razón, seguro, pero no la razón principal.",
  ui_story_70000602_9_dialog_content = "¿Podría ser... el tiempo?",
  ui_story_70000602_10_dialog_content = "Sí.",
  ui_story_70000602_11_dialog_content = "¿Porque ya es de noche?",
  ui_story_70000602_12_dialog_content = "Buen trabajo.",
  ui_story_70000602_13_dialog_content = "Parece que leyó el Manual.",
  ui_story_70000602_14_dialog_content = "Traté de advertir en múltiples ocasiones para llevar la cuenta del tiempo para evitar el peor escenario, en el que ahora estamos.",
  ui_story_70000602_15_dialog_content = "Pero incluso si te lo dijera, no te importaría, ¿verdad?",
  ui_story_70000602_16_dialog_content = "Después de todo, Soroz también es un amigo y una familia importante para ti.",
  ui_story_70000602_17_dialog_content = "Ves a través de mí...",
  ui_story_70000602_18_dialog_content = "Eres tú quien es fácil de leer.",
  ui_story_70000602_19_dialog_content = "Eso, y Vice siguió hablando de ti sin parar.",
  ui_story_70000602_20_dialog_content = "Incluso si no quisiera escuchar, no podía bloquearlos a todos.",
  ui_story_70000602_21_dialog_content = "¡Gran Mariscal Reinhardt!",
  ui_story_70000602_22_dialog_content = "Pero, tengo otra pregunta.",
  ui_story_70000602_23_dialog_content = "¿Cómo es que puedes sentir a Helios?",
  ui_story_70000602_24_dialog_content = "Probablemente un vínculo compartido entre nosotros.",
  ui_story_70000602_25_dialog_content = "Hemos estado muy unidos mientras crecíamos.",
  ui_story_70000602_26_dialog_content = "Y siempre puedes saber cuándo un miembro de la familia está en problemas.",
  ui_story_70000602_27_dialog_content = "Esta Entrañas lleva mucho tiempo sellada. Tanto Darkflow como la distancia cortaron esta conexión entre nosotros.",
  ui_story_70000602_28_dialog_content = "Pero lo abriste. Incluso despertaste a Helios, que ha estado atrapado allí durante años.",
  ui_story_70000602_29_dialog_content = "El vínculo entre nosotros se renueva...",
  ui_story_70000602_30_dialog_content = "¿Reinhardt también tiene la habilidad psíquica?",
  ui_story_70000602_31_dialog_content = "Me encantaría que.",
  ui_story_70000602_32_dialog_content = "Eso hará que dar órdenes sea mucho más fácil.",
  ui_story_70000602_33_dialog_content = "Solía haber algún tipo de vínculo entre nosotros, camaradas.",
  ui_story_70000602_34_dialog_content = "Se rompió…",
  ui_story_70000602_34X_dialog_content = "Pero su operación reavivó nuestro vínculo y nos unió una vez más.",
  ui_story_70000602_35_dialog_content = "Personalmente, lo atribuiría a cierta experiencia compartida...",
  ui_story_70000602_36_dialog_content = "La experiencia de vivir juntos la vida y la muerte.",
  ui_story_70000602_36X1_dialog_content = "Esos son los recuerdos que compartimos los tres.",
  ui_story_70000602_36X2_dialog_content = "¿Qué te ha pasado?",
  ui_story_70000602_36X3_dialog_content = "Una batalla sangrienta. Pero para ellos, era más como la última traición.",
  ui_story_70000602_36X4_dialog_content = "Illumina y yo los traicionamos... Los abandonamos.",
  ui_story_70000602_36X5_dialog_content = "¿Abandonar?",
  ui_story_70000602_36X6_dialog_content = "Pero Reinhardt... ¡No creo que dejarías a nadie atrás!",
  ui_story_70000602_37_dialog_content = "Larga historia. Permítanme ordenar mis pensamientos.",
  ui_story_70000602_38_dialog_content = "Me temo que es esta traición la que ha convertido a Helios en este monstruo.",
  ui_story_70000602_39_dialog_content = "Y Denier... No, ahora ha adoptado un nuevo nombre...",
  ui_story_70000602_40_dialog_content = "<color=#FFB400>Abandonado.</color>",
  ui_story_70000602_41_dialog_content = "abandonando...",
  ui_story_70000602_42_dialog_content = "¿La decepción causada por este abandono la llevó a su posterior deserción de Illumina?",
  ui_story_70000602_43_dialog_content = "No sé.",
  ui_story_70000602_44_dialog_content = "Pero eso no justifica que use humanos como sujetos de prueba y dañe a la gente de Illumina.",
  ui_story_70000602_45_dialog_content = "Sé que guarda un profundo rencor por no haber sido rescatada.",
  ui_story_70000602_46_dialog_content = "Fue mi culpa por ser débil y frágil. Debería ser yo quien soportara su odio.",
  ui_story_70000602_47_dialog_content = "Pero, aun así, se desquitó con los demás...",
  ui_story_70000602_48_dialog_content = "Schummer, yo y mucha, mucha más gente inocente...",
  ui_story_70000602_49_dialog_content = "Sí. Ese es su crimen.",
  ui_story_70000602_50_dialog_content = "Un crimen del que tendrá que responder.",
  ui_story_70000602_51_dialog_content = "Estoy de acuerdo contigo. Estas dos cosas no son lo mismo.",
  ui_story_70000602_51X1_dialog_content = "A veces, no puedo dejar de pensar...",
  ui_story_70000602_51X2_dialog_content = "Si no fueran parte del plan de entrenamiento del comité y no libraran esa horrible batalla...",
  ui_story_70000602_51X3_dialog_content = "¿Estarían viviendo una vida mejor ahora como humanos, no Eclipsitas?",
  ui_story_70000602_52_dialog_content = "¿Qué clase de entrenamiento era ese?",
  ui_story_70000602_52X1_dialog_content = "No parece algo que un hombre común pueda soportar.",
  ui_story_70000602_53_dialog_content = "El proyecto de desarrollo del Comité no es cualquier <color=#FFB400>capacitación</color>.",
  ui_story_70000602_54_dialog_content = "Los tres... ¿pasaron por el entrenamiento del Comité?",
  ui_story_70000602_55_dialog_content = "El proyecto de desarrollo del Comité no es una formación cualquiera.",
  ui_story_70000602_56_dialog_content = "Perder la vida es un riesgo posible.",
  ui_story_70000602_57_dialog_content = "Eso suena duro.",
  ui_story_70000602_58_dialog_content = "¿Illumina tiene que... elegir a su Gran Mariscal de esta manera?",
  ui_story_70000602_59_dialog_content = "Para la gente de Illumina, el Gran Mariscal es una luz en la oscuridad.",
  ui_story_70000602_60_dialog_content = "Solo la llama más brillante puede iluminar el rincón más oscuro, brindando esperanza a cada hombre desesperado.",
  ui_story_70000602_61_dialog_content = "La esperanza es lo que une a la gente de Illumina y los motiva a seguir avanzando en este mundo difícil.",
  ui_story_70000602_62_dialog_content = "Pero si quisieras esperar a que un ser supremo naciera en este mundo, las posibilidades de ver uno en tu vida son casi nulas.",
  ui_story_70000602_63_dialog_content = "Para esto, quiero convertirme en el Gran Mariscal de Illumina, sin importar cuánto sufrimiento y dolor tenga que pasar.",
  ui_story_70000602_63X_dialog_content = "El ser más poderoso de la tierra.",
  ui_story_70000602_64_dialog_content = "...",
  ui_story_70000602_65_dialog_content = "Chico, no me mires así.",
  ui_story_70000602_66_dialog_content = "¿Cómo decía el refrán?",
  ui_story_70000602_67_dialog_content = "\"Inquieta yace la cabeza que lleva la corona\".",
  ui_story_70000602_68_dialog_content = "No te preocupes. Aunque el cielo se cayera, el más alto de nosotros lo mantendría sobre vuestras cabezas.",
  ui_story_70000602_69_dialog_content = "Lo mismo se aplica aquí. Cuando Illumina está en problemas, el Gran Mariscal está ahí.",
  ui_story_70000602_70_dialog_content = "Incluyéndote.",
  ui_story_70000602_71_dialog_content = "Ya estamos acá.",
  ui_story_70000701_1_dialog_content = "Estos parecen ser los niveles superiores de Entrañas, similar al área por la que entramos.",
  ui_story_70000701_2_dialog_content = "Pero el túnel está interfiriendo con mi sentido de orientación. Realmente no sé mi camino ahora...",
  ui_story_70000701_3_dialog_content = "PlayerName, no es el mismo lugar donde entramos.",
  ui_story_70000701_4_dialog_content = "En realidad estamos en una ubicación completamente diferente.",
  ui_story_70000701_5_dialog_content = "¡¿Qué?!",
  ui_story_70000701_6_dialog_content = "¿Es difícil de decir? Puedes verlo con solo mirar el diseño de la tubería en el techo, también los conductos de ventilación están...",
  ui_story_70000701_7_dialog_content = "(Vaya... Ahí va Vice otra vez...)",
  ui_story_70000701_8_dialog_content = "Uf... ¡Tengo una pregunta!",
  ui_story_70000701_9_dialog_content = "¿Podría ser la curiosidad uno de los rasgos distintivos de los Caelestitas?",
  ui_story_70000701_10_dialog_content = "Lo siento. ¡Prometo que este es el último!",
  ui_story_70000701_11_dialog_content = "Esta bien. No es algo malo tener.",
  ui_story_70000701_12_dialog_content = "El Eclipsite de alto nivel que se escapó... era un amigo tuyo de la guerra, ¿no es así, Reinhardt?",
  ui_story_70000701_13_dialog_content = "¿Cómo se volvió así?",
  ui_story_70000701_14_dialog_content = "¿Fue esto también obra de Forsakin? Pero no noté ningún rastro de la semilla en él.",
  ui_story_70000701_15_dialog_content = "La respuesta a tu pregunta es: no lo sé.",
  ui_story_70000701_16_dialog_content = "Fue una guerra brutal. Todos creíamos que estaba muerto.",
  ui_story_70000701_17_dialog_content = "¿Qué pasó... en ese entonces?",
  ui_story_70000701_18_dialog_content = "...",
  ui_story_70000701_19_dialog_content = "En aquel entonces, todos los candidatos a Gran Mariscal se pusieron en un equipo especializado.",
  ui_story_70000701_20_dialog_content = "Hace once años, recibimos una orden del comité para recuperar los materiales científicos perdidos de Entrañas 80, que estuvo abandonada durante mucho tiempo.",
  ui_story_70000701_21_dialog_content = "Nuestra información sugirió que, a pesar de que Entrañas 80 estaba bajo el control de los Eclipsites, no eran grandes en número.",
  ui_story_70000701_22_dialog_content = "Así que tomamos la misma decisión que la tuya, viajar ligero.",
  ui_story_70000701_22X_dialog_content = "Planeamos entrar en Entrañas y recuperar el objetivo durante las cortas horas del día.",
  ui_story_70000701_23_dialog_content = "Sin embargo... La inteligencia que teníamos estaba muy lejos.",
  ui_story_70000701_24_dialog_content = "¡De ningún modo! ¡Hay demasiados de ellos!",
  ui_story_70000701_25_dialog_content = "Solicitando apoyo! Solicitando⁠—",
  ui_story_70000701_26_dialog_content = "Los Eclipsites de Entrañas estaban empaquetados como sardinas en lata. No importa cuántos matemos, había más de ellos.",
  ui_story_70000701_27_dialog_content = "El 20 % del cuerpo murió antes de que llegáramos al Almacén objetivo.",
  ui_story_70000701_28_dialog_content = "Entonces, las fortificaciones y el equipo roto que vimos en el almacén eran...",
  ui_story_70000701_29_dialog_content = "Restos de nuestros valientes soldados.",
  ui_story_70000701_30_dialog_content = "...",
  ui_story_70000701_31_dialog_content = "Y cuando recuperamos el objeto objetivo y estábamos listos para evacuar...",
  ui_story_70000701_32_dialog_content = "Cayó la noche.",
  ui_story_70000701_33_dialog_content = "Muchos Eclipsitas poderosos cargaron en Entrañas 80 como si se sintieran atraídos por algo...",
  ui_story_70000701_34_dialog_content = "Lo mismo que está pasando ahora.",
  ui_story_70000701_35_dialog_content = "¡Rugido!",
  ui_story_70000701_36_dialog_content = "Vicio, PlayerName, ¡prepárate para luchar!",
  ui_story_70000702_1_dialog_content = "Gah...",
  ui_story_70000702_2_dialog_content = "¡Batalla terminada!",
  ui_story_70000702_3_dialog_content = "No hay hostiles en el área inmediata... por ahora.",
  ui_story_70000702_4_dialog_content = "¡Vice!",
  ui_story_70000702_5_dialog_content = "Ugh... Mi cuerpo se siente... tan pesado...",
  ui_story_70000702_6_dialog_content = "Es medianoche, cuando la concentración de Darkflow está en su punto más alto.",
  ui_story_70000702_7_dialog_content = "Ustedes dos lo están haciendo bien. La última vez, muchos se desmayaron.",
  ui_story_70000702_8_dialog_content = "Y tuvimos que luchar contra cientos, miles de eclipses más...",
  ui_story_70000702_9_dialog_content = "<color=#e8d9bb>Durante la Guerra de la Zona Oscura</color>",
  ui_story_70000702_10_dialog_content = "¡Mira tus 3 en punto!",
  ui_story_70000702_11_dialog_content = "*Rugido*",
  ui_story_70000702_12_dialog_content = "<color=#e8d9bb>papá...</color>",
  ui_story_70000702_13_dialog_content = "¡Objetivo abajo!",
  ui_story_70000702_14_dialog_content = "¡Eclipsitas de alto nivel a tus 10!",
  ui_story_70000702_15_dialog_content = "1, 2, 3... ¡Son demasiados!",
  ui_story_70000702_16_dialog_content = "¡Necesitamos apoyo de fuego inmediato!",
  ui_story_70000702_17_dialog_content = "¡No te dejaré pasar por aquí!",
  ui_story_70000702_18_dialog_content = "¡¡Graaoooooohhh!!",
  ui_story_70000702_19_dialog_content = "¡No decía que nos encontraríamos con tantos eclipses en la información!",
  ui_story_70000702_20_dialog_content = "¿Incluso la información del Comité puede estar equivocada...?",
  ui_story_70000702_21_dialog_content = "Es algo que todos queremos evitar, pero lo hecho, hecho está. ¡Todo lo que podemos hacer ahora es tratar de salir de aquí con los datos!",
  ui_story_70000702_22_dialog_content = "Sabes lo que pasó después, ¿no?",
  ui_story_70000702_23_dialog_content = "El Flujo Oscuro en Entrañas cortó nuestras comunicaciones, así que tuve la tarea de abrirme paso para llegar.",
  ui_story_70000702_24_dialog_content = "Cuando regresé al otro lado de la Línea Segura... Entrañas se sumergió y colapsó.",
  ui_story_70000702_25_dialog_content = "En esa situación... ir a Entrañas rodeada, luchar mientras excavamos para salvar a nuestra gente...",
  ui_story_70000702_26_dialog_content = "La escasa tasa de éxito y las grandes pérdidas estimadas...",
  ui_story_70000702_27_dialog_content = "Al final, no tenía sentido aprobar una misión de rescate como esa después de mucha consideración.",
  ui_story_70000702_28_option_content = "¿Como pudiste?",
  ui_story_70000702_29_dialog_content = "Eran soldados de Illumina... personas vivas...",
  ui_story_70000702_30_dialog_content = "¿Por qué? ¿Por qué los dejaron morir?",
  ui_story_70000702_31_dialog_content = "...",
  ui_story_70000702_32_dialog_content = "Esta pregunta me molestó durante mucho tiempo. Es comprensible que no puedas verlo.",
  ui_story_70000702_33_dialog_content = "Nuestro equipo que fue enviado a Entrañas era el equipo de élite mejor equipado de Illumina.",
  ui_story_70000702_34_dialog_content = "Aunque no pudimos lograr la victoria en Entrañas 80, entonces, ¿qué posibilidades tienen las tropas regulares que custodian la Línea Segura?",
  ui_story_70000702_35_dialog_content = "Los que estaban atrapados bajo tierra eran mis hermanos y hermanas. No quería perderlos.",
  ui_story_70000702_36_dialog_content = "¿Pero los soldados regulares de Illumina no eran mis hermanos y hermanas?",
  ui_story_70000702_37_dialog_content = "Si salvar a uno significa costar la vida a diez... ¿Harías ese intercambio?",
  ui_story_70000702_38_dialog_content = "Yo...",
  ui_story_70000702_39_dialog_content = "Estoy seguro de que puedes entender... Cada uno de nosotros tiene una familia, amigos y personas importantes para nosotros.",
  ui_story_70000702_40_dialog_content = "Darkflow solo puede estorbarme a mí, pero puede ser letal para una persona normal.",
  ui_story_70000702_41_dialog_content = "Además de eso, está el asunto de los interminables Eclipses...",
  ui_story_70000702_42_dialog_content = "Si ni siquiera nosotros podíamos salir de esta peligrosa situación, ¿qué posibilidades tenían?",
  ui_story_70000702_43_option_content = "Ok...",
  ui_story_70000702_44_dialog_content = "Sólo si pudieras entender.",
  ui_story_70000702_45_option_content = "sigo sin estar de acuerdo",
  ui_story_70000702_46_dialog_content = "Pase lo que pase, nunca me rendiré con mis amigos.",
  ui_story_70000702_47_dialog_content = "Nunca.",
  ui_story_70000702_48_dialog_content = "No necesito que estés de acuerdo. Solo necesito que entiendas...",
  ui_story_70000702_49_dialog_content = "Como Gran Mariscal de Illumina, mi decisión debe ser en el mejor interés de todos en Illumina.",
  ui_story_70000702_50_dialog_content = "...",
  ui_story_70000702_51_dialog_content = "(¿Yo... llevé esta conversación por una ruta sombría...?)",
  ui_story_70000702_52_dialog_content = "Bueno... Esta ruta en realidad es bastante suave...",
  ui_story_70000702_53_dialog_content = "Seguro que sí.",
  ui_story_70000702_54_dialog_content = "Estaba pavimentado con interminables sacrificios y sangre.",
  ui_story_70000702_55_dialog_content = "Y solo escapé pisando sus sacrificios.",
  ui_story_70000702_56_dialog_content = "<color=#e8d9bb>Timbre...</color>",
  ui_story_70000702_57_dialog_content = "PlayerName, ¿se enteró que?",
  ui_story_70000702_58_dialog_content = "¡Otra vez el sonido de esa campana!",
  ui_story_70000702_59_dialog_content = "¡Lo escuché! ¡Está cerca!",
  ui_story_70000702_60_dialog_content = "El eclipse de alto nivel que se escapó inmediatamente después de escuchar la campana...",
  ui_story_70000702_61_dialog_content = "¿Podría estar todavía por aquí?",
  ui_story_70000702_62_dialog_content = "Maldita sea... Solo si Darkflow es menos fuerte, podría haber usado mi habilidad psíquica...",
  ui_story_70000702_63_dialog_content = "Está bien. Estoy seguro de que está por aquí en alguna parte.",
  ui_story_70000702_64_dialog_content = "¿Cómo puede estar seguro, Gran Mariscal Reinhardt?",
  ui_story_70000702_65_dialog_content = "Antes de mi intento de fuga, les hice una promesa.",
  ui_story_70000702_66_dialog_content = "Señalaré su evacuación una vez que regrese con los refuerzos.",
  ui_story_70000702_67_dialog_content = "Como siempre, la evacuación será señalada por el sonido de la campana.",
  ui_story_70000702_68_dialog_content = "Está bien, entiendo.",
  ui_story_70000702_69_dialog_content = "No te preocupes. Podemos mantener nuestro terreno.",
  ui_story_70000702_70_dialog_content = "¡Esperaría tu señal incluso si yo mismo me convirtiera en un Eclipsite!",
  ui_story_70000702_71_dialog_content = "Muy bien...",
  ui_story_70000702_72_dialog_content = "¡Tan pronto como escuchemos el sonido de la campana, saldremos a la carga!",
  ui_story_70000702_73_dialog_content = "Qué ironía que su broma se hiciera realidad al final...",
  ui_story_70000702_74_dialog_content = "Siempre maldiciendo las cosas...",
  ui_story_70000702_75_dialog_content = "Entonces... ¿Todavía recuerda esa promesa?",
  ui_story_70000702_76_dialog_content = "O tal vez \"él\" ha perdido la cabeza por completo y se mueve solo por instinto.",
  ui_story_70000702_77_dialog_content = "...",
  ui_story_70000702_78_dialog_content = "...",
  ui_story_70000702_79_dialog_content = "Prepárate para una batalla. \"Él\" puede estar esperándonos.",
  ui_story_70000702_80_dialog_content = "Solo por favor dame una última oportunidad...",
  ui_story_70000702_81_dialog_content = "No puedo desperdiciar otra oportunidad de salvarlo... No después de la última vez.",
  ui_story_70000801_1_dialog_content = "<color=#e8d9bb>Timbre...</color>",
  ui_story_70000801_2_dialog_content = "¡Por fin salimos!",
  ui_story_70000801_3_dialog_content = "Pero... El Darkflow no es más fácil de manejar...",
  ui_story_70000801_4_dialog_content = "No te excedas, PlayerName.",
  ui_story_70000801_5_dialog_content = "Dejame ayudarte a levantarte.",
  ui_story_70000801_6_dialog_content = "<color=#e8d9bb>Timbre...</color>",
  ui_story_70000801_7_dialog_content = "La campana... Está cerca...",
  ui_story_70000801_8_dialog_content = "¡Allá!",
  ui_story_70000801_9_dialog_content = "Gah...",
  ui_story_70000801_10_dialog_content = "¿Está buscando la fuente del anillo?",
  ui_story_70000801_11_dialog_content = "¿Son todos esos eclipses a su alrededor?",
  ui_story_70000801_12_dialog_content = "¿Realmente vamos a tratar de acercarnos así?",
  ui_story_70000801_13_dialog_content = "Esta es una solicitud personal. Por favor, dame cinco minutos.",
  ui_story_70000801_14_dialog_content = "Este será mi último intento de salvarlo.",
  ui_story_70000801_15_dialog_content = "Evacuaremos inmediatamente una vez que pasen los cinco minutos.",
  ui_story_70000801_16_dialog_content = "¡Ayudaré!",
  ui_story_70000801_17_dialog_content = "Y tú, PlayerName?",
  ui_story_70000801_18_dialog_content = "Cuenta conmigo.",
  ui_story_70000801_19_dialog_content = "¡Esta vez lo salvaremos!",
  ui_story_70000801_20_dialog_content = "Bueno, mejor abre los ojos y míralo.",
  ui_story_70000801_21_dialog_content = "Sea testigo de la voluntad de Illumina.",
  ui_story_70000801_22_dialog_content = "Igual que la última vez. Vamos a dividir.",
  ui_story_70000801_23_dialog_content = "Vice, daremos la vuelta a los Eclipsites hacia el lado opuesto.",
  ui_story_70000801_24_dialog_content = "Claro.",
  ui_story_70000801_25_dialog_content = "Supongo que ahora estamos en posición.",
  ui_story_70000801_26_dialog_content = "Bien. Reinhardt también está listo.",
  ui_story_70000801_27_dialog_content = "Bueno.",
  ui_story_70000801_28_dialog_content = "¡Oigan, estúpidos Eclipsitas! ¡Venir a buscarme!",
  ui_story_70000801_29_dialog_content = "Rugido...!",
  ui_story_70000801_30_dialog_content = "¡Rugido!",
  ui_story_70000801_31_dialog_content = "¿Eh?",
  ui_story_70000801_32_dialog_content = "¿Tantos de ellos?",
  ui_story_70000801_33_dialog_content = "Aférrate, PlayerName!",
  ui_story_70000802_1_dialog_content = "¿Has olvidado?",
  ui_story_70000802_2_dialog_content = "¿El sueño de Ilumina?",
  ui_story_70000802_3_dialog_content = "¿La voluntad de Illumina?",
  ui_story_70000802_4_dialog_content = "¿La gloria de Illumina?",
  ui_story_70000802_5_dialog_content = "Los recuerdos de Illumina...",
  ui_story_70000802_6_dialog_content = "¿¡Los olvidaste a todos!?",
  ui_story_70000802_7_dialog_content = "*Rugido*",
  ui_story_70000802_8_dialog_content = "Dígame...",
  ui_story_70000802_9_dialog_content = "¿Por qué abandonaste la luz y abrazaste la oscuridad?",
  ui_story_70000802_10_dialog_content = "¿Para su supervivencia?",
  ui_story_70000802_11_dialog_content = "¿O estás cumpliendo las órdenes de otra persona?",
  ui_story_70000802_12_dialog_content = "Dame...",
  ui_story_70000802_13_dialog_content = "<size=45>¡Contestas!</size>",
  ui_story_70000802_14_dialog_content = "*Rugido*",
  ui_story_70000802_15_dialog_content = "<color=#e8d9bb>Timbre...</color>",
  ui_story_70000802_16_dialog_content = "¡...!",
  ui_story_70000802_17_dialog_content = "¡Son las campanas otra vez!",
  ui_story_70000802_18_dialog_content = "Está cerca... ¡muy cerca! ¡Allí!",
  ui_story_70000802_19_dialog_content = "<color=#e8d9bb>Timbre...</color>",
  ui_story_70000802_20_dialog_content = "E-Eso es porque...",
  ui_story_70000802_21_dialog_content = "¿¡Abandonado!?",
  ui_story_70000802_22_dialog_content = "...",
  ui_story_70000802_23_dialog_content = "Mucho tiempo sin verlo. Te estás volviendo hablador.",
  ui_story_70000802_24_dialog_content = "Reinhardt.",
  ui_story_70000802_25_dialog_content = "Negador... No. Abandonado.",
  ui_story_70000802_26_dialog_content = "¿Tú también tienes algo que ver con lo que le pasó a Helios?",
  ui_story_70000802_27_dialog_content = "No sé nada más que tú sobre este asunto.",
  ui_story_70000802_28_dialog_content = "Pero, sin lugar a dudas, es un buen sujeto de prueba.",
  ui_story_70000802_29_dialog_content = "Entonces, ¿cómo se convirtió en esto...",
  ui_story_70000802_30_dialog_content = "¿Aún no entiendes?",
  ui_story_70000802_31_dialog_content = "No olvidó nada.",
  ui_story_70000802_32_dialog_content = "Todo lo contrario... Lo recuerda demasiado bien.",
  ui_story_70000802_33_dialog_content = "¡¿...?!",
  ui_story_70000802_34_dialog_content = "El hijo marginado. Lo único que ha olvidado es el odio hacia Illumina.",
  ui_story_70000802_35_dialog_content = "Es hora de recordarlo.",
  ui_story_70000802_36_dialog_content = "<size=45>Graah! ¡Rugido!</size>",
  ui_story_70000802_37_dialog_content = "¡Urgh...!",
  ui_story_70000802_38_dialog_content = "Esto es... ¿¡recuerdos!?",
  ui_story_70000802_39_dialog_content = "Han pasado cuatro horas desde que Reinhardt irrumpió...",
  ui_story_70000802_40_dialog_content = "Aún sin campanas...",
  ui_story_70000802_41_dialog_content = "Todavía me quedan fuerzas en mí. Voy a mostrarles a los Eclipsites lo que tengo incluso con mis puños de oso.",
  ui_story_70000802_42_dialog_content = "¿Y usted? ¿Cuánta munición y suministros te quedan?",
  ui_story_70000802_43_dialog_content = "10 rondas y... dos bollos de aserrín.",
  ui_story_70000802_44_dialog_content = "Si hubiera sabido que esto iba a pasar, me hubiera quedado en Gannon y me hubiera ocupado de esas pésimas normas de laboratorio.",
  ui_story_70000802_45_dialog_content = "Soy mucho más hábil en la disección de eclipses con bisturí que con rifles y balas.",
  ui_story_70000802_46_dialog_content = "¡Jajaja! Qué estrella en ascenso de investigador eres.",
  ui_story_70000802_47_dialog_content = "Apuesto a que aún puedes atar nudos en los Eclipsites con puntadas.",
  ui_story_70000802_48_dialog_content = "Decir ah. Gracias por el voto de confianza.",
  ui_story_70000802_49_dialog_content = "Pero, ¿cuánto tiempo podemos aguantar?",
  ui_story_70000802_50_dialog_content = "O... ¿Hemos sido todos abandonados?",
  ui_story_70000802_51_dialog_content = "...",
  ui_story_70000802_52_dialog_content = "No importa. No podemos perder la esperanza.",
  ui_story_70000802_53_dialog_content = "Reinhardt... Volverá con refuerzos de Illumina.",
  ui_story_70000802_54_dialog_content = "Antes de que eso suceda, tendremos que aguantar.",
  ui_story_70000802_55_dialog_content = "¡Mira, la salida está más adelante!",
  ui_story_70000802_56_dialog_content = "Hay muchos eclipses dando vueltas cerca... También...",
  ui_story_70000802_57_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_70000802_58_dialog_content = "La última batalla fue demasiado feroz. Va a colapsar en cualquier segundo.",
  ui_story_70000802_59_dialog_content = "Es el amanecer en este momento, cuando los Eclipsites están en su punto más débil.",
  ui_story_70000802_60_dialog_content = "Si no aprovechamos esta oportunidad para salir, moriremos aquí.",
  ui_story_70000802_61_dialog_content = "Sígueme. Intentaremos abrirnos paso cuando los eclipses se alejen.",
  ui_story_70000802_62_dialog_content = "¡11 en punto!",
  ui_story_70000802_63_dialog_content = "¡Lo se!",
  ui_story_70000802_64_dialog_content = "¡Maldita sea! ¡Esto no tiene fin!",
  ui_story_70000802_65_dialog_content = "¡Todavía puedo aguantar! ¡Denier, muévete hacia la salida!",
  ui_story_70000802_66_dialog_content = "<color=#e8d9bb>¡Boom!</color>",
  ui_story_70000802_67_dialog_content = "¡El suelo se está rompiendo! ¡Cuidado!",
  ui_story_70000802_68_dialog_content = "¡Agh!",
  ui_story_70000802_69_dialog_content = "Helios!",
  ui_story_70000802_70_dialog_content = "Tengo... para sobrevivir.",
  ui_story_70000802_71_dialog_content = "Tengo que esperar... por el refuerzo.",
  ui_story_70000802_72_dialog_content = "¿Cuántos días han pasado...?",
  ui_story_70000802_73_dialog_content = "Mi cuerpo... algo malo me está pasando...",
  ui_story_70000802_74_dialog_content = "Campanas... Por favor, déjame escuchar el sonido de las campanas...",
  ui_story_70000802_75_dialog_content = "Un día... dos días...",
  ui_story_70000802_76_dialog_content = "Un año... dos años...",
  ui_story_70000802_77_dialog_content = "¿Dónde está mi refuerzo?",
  ui_story_70000802_78_dialog_content = "¿¡Por qué me abandonaste!?",
  ui_story_70000802_79_dialog_content = "¡Rugido!",
  ui_story_70000802_80_dialog_content = "Parece que lo estás recordando ahora.",
  ui_story_70000802_81_dialog_content = "Pero eso no es suficiente.",
  ui_story_70000802_82_dialog_content = "Al igual que la Semilla. La ira es la mejor nutrición...",
  ui_story_70000802_83_dialog_content = "Déjame echarte una mano.",
  ui_story_70000802_84_dialog_content = "¿¡Qué estás haciendo, Renegado!?",
  ui_story_70000802_85_dialog_content = "...",
  ui_story_70000802_86_dialog_content = "Reinhardt...",
  ui_story_70000802_87_dialog_content = "¿Por qué... no regresaste con refuerzos?",
  ui_story_70000802_88_dialog_content = "Porque...",
  ui_story_70000802_89_dialog_content = "Bajo la terrible situación, sacrificarte es la única respuesta lógica.",
  ui_story_70000802_90_dialog_content = "Entonces, realmente...",
  ui_story_70000802_91_dialog_content = "...no ha cambiado.",
  ui_story_70000802_92_dialog_content = "Tanto tú como Illumina.",
  ui_story_70000802_93_dialog_content = "¡Rugido!",
  ui_story_70000802_94_dialog_content = "¡Cuidado! ¡Viene por aquí!",
  ui_story_70000802_95_dialog_content = "¡Furia! Y... crecer.",
  ui_story_70000802_96_dialog_content = "¡Devora todo... en esta Zona Oscura!",
  ui_story_70000802_97_dialog_content = "¡Rugido!",
  ui_story_70000802_98_dialog_content = "Es hora de terminar con esto.",
  ui_story_70000802_99_dialog_content = "¡Vicio, prepárate para luchar!",
  ui_story_70000802_100_dialog_content = "¡Sí!",
  ui_story_70000902_1_dialog_content = "Graah! ¡Rugido!",
  ui_story_70000902_2_dialog_content = "¿Todavía reprimido incluso en esta condición?",
  ui_story_70000902_3_dialog_content = "Supongo que todavía eres solo un <color=#FFB400>sujeto defectuoso</color>.",
  ui_story_70000902_4_dialog_content = "Pero ser capaz de moverse ya es un gran avance en el experimento.",
  ui_story_70000902_5_dialog_content = "Al menos eso es algo valioso.",
  ui_story_70000902_6_dialog_content = "Desafortunadamente, no tengo una cantidad infinita de tiempo.",
  ui_story_70000902_7_dialog_content = "¡Urgh...!",
  ui_story_70000902_8_dialog_content = "¡El Darkflow se está... concentrando en el área!",
  ui_story_70000902_9_dialog_content = "El Darkflow es... ¡demasiado fuerte! No puedo...",
  ui_story_70000902_10_dialog_content = "*tos* Entonces, después de todos estos años, incluso un investigador débil puede convertirse en un luchador.",
  ui_story_70000902_11_dialog_content = "Ciérralo.",
  ui_story_70000902_12_dialog_content = "Los débiles deben quedarse en el suelo.",
  ui_story_70000902_13_dialog_content = "En cuanto a ti... ¡Toma este Darkflow y muéstrame lo que vales!",
  ui_story_70000902_14_dialog_content = "¡Rugido!",
  ui_story_70000902_15_dialog_content = "¡Los Eclipsite están... desapareciendo...!",
  ui_story_70000902_16_dialog_content = "Graah! ¡Rugido!",
  ui_story_70000902_17_dialog_content = "¡Están... llorando de dolor!",
  ui_story_70000902_18_dialog_content = "Forsakin está tomando su fuerza vital... ¡atrayendo el Darkflow!",
  ui_story_70000902_19_dialog_content = "Si esta cantidad de Darkflow se convierte en un ataque...",
  ui_story_70000902_20_dialog_content = "¡Incluso una explosión arrasaría toda Entrañas!",
  ui_story_70000902_21_dialog_content = "¡Reinhardt, cuidado!",
  ui_story_70000902_22_dialog_content = "¡...!",
  ui_story_70000902_23_dialog_content = "PlayerName, encuentra cobertura!",
  ui_story_70000902_24_dialog_content = "Demasiado lento.",
  ui_story_70000902_25_dialog_content = "(Eso es lo más devastador que he visto en mi vida).",
  ui_story_70000902_26_dialog_content = "(El Darkflow que lo abarca todo y la oscuridad de la Noche Eterna llamando como el mar, devastando la tierra y todo lo que está a la vista).",
  ui_story_70000902_27_dialog_content = "(Vice y yo, atados al suelo por la tremenda presión, yacemos impotentes ante una fuerza tan terrible.)",
  ui_story_70000902_28_dialog_content = "(Todo lo que puedo hacer es levantar la cabeza y ver cómo Darkflow me devora).",
  ui_story_70000902_29_dialog_content = "Y luego, en la oscuridad sin fin...",
  ui_story_70000902_30_dialog_content = "Yo vi <color=#FFB400>luz</color>.",
  ui_story_70000902_31_dialog_content = "No. ¡No lo haré a tu manera!",
  ui_story_70000902_32_dialog_content = "¿¡Reinhardt!?",
  ui_story_70000902_33_dialog_content = "(En medio de esa oscuridad eterna, la luz puede ser solo un destello que podría extinguirse en cualquier momento...)",
  ui_story_70000902_34_dialog_content = "(Pero aun así persistió y resistió la oscuridad, extendiendo su resplandor).",
  ui_story_70000902_35_dialog_content = "(Como el sol naciente en el horizonte, prediciendo la llegada del día).",
  ui_story_70000902_36_dialog_content = "Es solo... un pequeño Darkflow.",
  ui_story_70000902_37_dialog_content = "¡Y llevo la Luz de Illumina sobre mis hombros!",
  ui_story_70000902_38_dialog_content = "¡Sostendré el cielo aunque caiga sobre Illumina!",
  ui_story_70000902_39_dialog_content = "(Poco a poco, la oscuridad se aleja...)",
  ui_story_70000902_40_dialog_content = "(Luz, atraviesa las nubes.)",
  ui_story_70000902_41_dialog_content = "¡Uh!",
  ui_story_70000902_42_dialog_content = "¡...!",
  ui_story_70000902_43_dialog_content = "¡Reinhardt!",
  ui_story_70000902_44_dialog_content = "Renunciar a la defensa por completo por una ofensiva completa... ¿o sí?",
  ui_story_70000902_45_dialog_content = "Aun así, la mayoría de los ataques se pueden bloquear fácilmente...",
  ui_story_70000902_46_dialog_content = "Ja... que tonto",
  ui_story_70000902_47_dialog_content = "Un tonto loco.",
  ui_story_70000902_48_dialog_content = "Este nivel de potencia cae dentro de los parámetros esperados.",
  ui_story_70000902_49_dialog_content = "Cualquier otro Auroriano común se habría vuelto loco por el Darkflow de esta magnitud.",
  ui_story_70000902_50_dialog_content = "Tu eres digno.",
  ui_story_70000902_51_dialog_content = "Tan digno como puede ser el \"monstruo\" más grande que salió vivo del fango.",
  ui_story_70000902_52_dialog_content = "Esas personas realmente te han \"enseñado\" bien.",
  ui_story_70000902_53_dialog_content = "Igualmente.",
  ui_story_70000902_54_dialog_content = "Sostener una tecnología tan avanzada pero solo imaginarte a ti mismo como un héroe en un juego de niños...",
  ui_story_70000902_55_dialog_content = "Y realmente pareces estar... divirtiéndote.",
  ui_story_70000902_56_dialog_content = "Porque era nuestro sueño... ¿no?",
  ui_story_70000902_57_dialog_content = "Para convertirse en el Gran Mariscal de Illumina y guiar a la gente de Illumina a un mundo mejor.",
  ui_story_70000902_58_dialog_content = "Por Illumina y su gente...",
  ui_story_70000902_59_dialog_content = "Que ingenuo. ¿Qué hicieron realmente por ti? Nada, sino darte por sentado y pedir tu protección sin fin.",
  ui_story_70000902_60_dialog_content = "A sus ojos, eres solo un símbolo en forma humana. Fácilmente reemplazable y desechado.",
  ui_story_70000902_61_dialog_content = "La verdad es que no eres diferente de esos animales de prueba vivos.",
  ui_story_70000902_62_dialog_content = "Un investigador sólo se preocupa por los datos obtenidos de los sujetos de prueba.",
  ui_story_70000902_63_dialog_content = "Y a esas personas solo les importa... una imagen aparentemente poderosa. No les importa a quién se superpone esa imagen.",
  ui_story_70000902_64_dialog_content = "Jeje...",
  ui_story_70000902_65_dialog_content = "¡Jajaja!",
  ui_story_70000902_66_dialog_content = "Abandonar... No. Negar...",
  ui_story_70000902_67_dialog_content = "Tú también te has convertido en un charlatán.",
  ui_story_70000902_68_dialog_content = "Todavía recuerdo cómo siempre te encerrabas en un laboratorio, haciendo tus experimentos.",
  ui_story_70000902_69_dialog_content = "No importa lo que te dije, solo quieres demostrarle al mundo que eres el mejor.",
  ui_story_70000902_70_dialog_content = "...",
  ui_story_70000902_71_dialog_content = "En ese entonces, nunca te importó cómo te veían los demás.",
  ui_story_70000902_72_dialog_content = "Estoy en tus zapatos ahora. Soy el Gran Mariscal de Illumina. Protegeré a Illumina y a su gente. Eso es todo al respecto.",
  ui_story_70000902_73_dialog_content = "¿En cuanto a cómo me ven? No podría molestarme con eso.",
  ui_story_70000902_74_dialog_content = "Quién soy hoy, en realidad lo aprendí de ti.",
  ui_story_70000902_75_dialog_content = "...",
  ui_story_70000902_76_dialog_content = "¿Sabes qué? Pondré una etiqueta en tus datos de prueba: \"lunático\".",
  ui_story_70000902_77_dialog_content = "Ahora que obtuve los materiales que necesito, es hora de volver a mis experimentos.",
  ui_story_70000902_78_dialog_content = "For... sakin...",
  ui_story_70000902_79_dialog_content = "Un pero que simplemente no morirá.",
  ui_story_70000902_80_dialog_content = "No como este artículo experimental fallido...",
  ui_story_70000902_81_dialog_content = "...",
  ui_story_70000902_82_dialog_content = "Eso es todo...?",
  ui_story_70000902_83_dialog_content = "Bueno... supongo que es algo digno como tema de estudio.",
  ui_story_70000902_84_dialog_content = "No es un Aurorian ni un Eclipsite.",
  ui_story_70000902_85_dialog_content = "Sólo algo con... algo de valor como peón.",
  ui_story_70000902_86_dialog_content = "¿¡Qué estás haciendo!? ¡Bajalo!",
  ui_story_70000902_87_dialog_content = "¿Crees que puedes detenerme? ¿Quién crees que eres?",
  ui_story_70000902_88_dialog_content = "\"Es la hora.\"",
  ui_story_70000902_89_dialog_content = "¿Temblores y polvo... viniendo del horizonte...?",
  ui_story_70000902_90_dialog_content = "PlayerName.... ¿Que es eso?",
  ui_story_70000902_91_dialog_content = "No sé... Déjame ver...",
  ui_story_70000902_92_option_content = "¡Potencia de fuerza!",
  ui_story_70000902_93_dialog_content = "¡...!",
  ui_story_70000902_94_dialog_content = "(¿Son esos... eclipses?)",
  ui_story_70000902_95_dialog_content = "(Toda una legión de... ¡Eclipsitos!)",
  ui_story_70000902_96_dialog_content = "(Eclipsian) Ayuda... ¡Renegados!",
  ui_story_70000902_97_dialog_content = "(¿¡Vienen aquí!?)",
  ui_story_70000902_98_dialog_content = "(Incluso si tenemos a Reinhardt, todavía hay demasiados de ellos...)",
  ui_story_70000902_99_dialog_content = "(Y... sufrió graves heridas por su ataque desesperado anterior...)",
  ui_story_70000902_100_dialog_content = "(Ella está aguantando solo por su pura voluntad...)",
  ui_story_70000902_101_dialog_content = "(¡Tenemos que retirarnos ahora!)",
  ui_story_70000902_102_dialog_content = "¡Reinhardt! ¡Es en serio!",
  ui_story_70000902_103_dialog_content = "¿Qué?",
  ui_story_70000902_104_dialog_content = "¡Puedo sentir que una gran cantidad de eclipses se dirigen hacia nosotros! ¡Estarán aquí en cualquier segundo!",
  ui_story_70000902_105_dialog_content = "¡También hay entidades poderosas entre ellos!",
  ui_story_70000902_106_dialog_content = "¡Tenemos que irnos, ahora!",
  ui_story_70000902_107_dialog_content = "Sólo tres minutos... ¡Es todo lo que necesito!",
  ui_story_70000902_108_dialog_content = "¡Rugido!",
  ui_story_70000902_109_dialog_content = "¡No hay tiempo, Reinhardt!",
  ui_story_70000902_110_dialog_content = "¡Estaremos rodeados si esperamos!",
  ui_story_70000902_111_dialog_content = "...",
  ui_story_70000902_112_dialog_content = "\"Regla 3: Evita el combate a toda costa en el Mire. Sepa cuándo retirarse\".",
  ui_story_70000902_113_dialog_content = "...",
  ui_story_70000902_114_dialog_content = "Debiluchos.",
  ui_story_70000902_115_dialog_content = "Sabes en tu corazón que él es nuestro hermano de armas.",
  ui_story_70000902_116_dialog_content = "Si te atreves con él o con la gente de Illumina... te haré pagar.",
  ui_story_70000902_117_dialog_content = "Decir ah.",
  ui_story_70000902_118_dialog_content = "¿Qué tal si logras sobrevivir primero y luego me lo dices a la cara?",
  ui_story_70000902_119_dialog_content = "No tienes el lujo de elegir en este momento.",
  ui_story_70000902_120_dialog_content = "...",
  ui_story_70000902_121_dialog_content = "Vicio, PlayerName, prepárese para evacuar.",
  ui_story_70000902_122_dialog_content = "...",
  ui_story_70000902_123_dialog_content = "Te estás quedando sin tiempo...",
  ui_story_70000902_124_dialog_content = "Mi hermana.\"",
  ui_story_70001001_1_dialog_content = "¡Vicio, levanta a Reinhardt y yo iré a activar el Coloso!",
  ui_story_70001001_2_dialog_content = "¡Está bien!",
  ui_story_70001001_3_dialog_content = "¿Estamos... en el aire?",
  ui_story_70001001_4_dialog_content = "¡Sí, ahora estamos en el aire!",
  ui_story_70001001_5_dialog_content = "Apenas logramos despegar a tiempo...",
  ui_story_70001001_6_dialog_content = "OTR... A toda velocidad...",
  ui_story_70001001_7_dialog_content = "Gran Mariscal Reinhardt?",
  ui_story_70001001_8_dialog_content = "Sus heridas son demasiado graves... Es un milagro que haya aguantado tanto tiempo.",
  ui_story_70001001_9_dialog_content = "PlayerName, vas a pilotar el Soroz. Traeré el botiquín de primeros auxilios.",
  ui_story_70001001_10_dialog_content = "¡Está bien!",
  ui_story_70001001_11_dialog_content = "Solo espera... Reinhardt...",
  ui_story_70001001_12_dialog_content = "Err...",
  ui_story_70001001_13_dialog_content = "No se ve bien. El Gran Mariscal se encuentra en condiciones críticas.",
  ui_story_70001001_14_dialog_content = "Ella necesita tratamiento médico inmediato!",
  ui_story_70001001_15_dialog_content = "<color=#e8d9bb>\"Palabra clave detectada: Tratamiento médico\".</color>",
  ui_story_70001001_16_dialog_content = "<color=#e8d9bb>\"Escaneando datos... Escaneo completo\".</color>",
  ui_story_70001001_17_dialog_content = "<color=#e8d9bb>\"Actualización del módulo de reparación de plantilla de eco encontrada\".</color>",
  ui_story_70001001_18_dialog_content = "<color=#e8d9bb>\"Instalar Echo Template para actualizar el sistema de soporte vital al sistema médico de emergencia\".</color>",
  ui_story_70001001_19_option_content = "¿Soroz?",
  ui_story_70001001_20_dialog_content = "¿¡De repente se activó!?",
  ui_story_70001001_21_dialog_content = "Unidad de reparación de plantilla de eco... ¿Significa esto? ¿Cómo puedo olvidarlo?",
  ui_story_70001001_22_dialog_content = "Dado que es un sistema médico, probablemente pueda ayudar a Reinhardt.",
  ui_story_70001001_23_dialog_content = "¡Vamos a instalarlo y ver!",
  ui_story_70001001_24_dialog_content = "<color=#e8d9bb>\"Módulo de reparación de plantilla de eco detectado\".</color>",
  ui_story_70001001_25_dialog_content = "<color=#e8d9bb>\"Estableciendo conexión... Completado\".</color>",
  ui_story_70001001_26_dialog_content = "<color=#e8d9bb>\"Priorización del sistema... Completa\".</color>",
  ui_story_70001001_27_dialog_content = "<color=#e8d9bb>\"Actualización del sistema de soporte vital encontrada. Iniciando actualización\".</color>",
  ui_story_70001001_28_dialog_content = "¿¡El módulo de reparación está... cambiando!?",
  ui_story_70001001_29_dialog_content = "<color=#e8d9bb>\"Actualización completa. Sistema médico de emergencia operativo\".</color>",
  ui_story_70001001_30_dialog_content = "<color=#e8d9bb>\"Carga actual: 1; Ranura restante: 1\"</color>",
  ui_story_70001001_31_dialog_content = "<color=#e8d9bb>\"Favor firmar y confirmar.\"</color>",
  ui_story_70001001_32_dialog_content = "Pero... ¿No deberíamos hacer una revisión completa primero?",
  ui_story_70001001_33_dialog_content = "Err...",
  ui_story_70001001_34_dialog_content = "No creo que tengamos tiempo para eso.",
  ui_story_70001001_35_dialog_content = "Tenemos que aprovechar la oportunidad...",
  ui_story_70001001_36_dialog_content = "¡Sí!",
  ui_story_70001001_37_dialog_content = "Espero que esto funcione...",
  ui_story_70001001_38_dialog_content = "Ella estará bien.",
  ui_story_70001001_39_dialog_content = "Yo le creo, y yo creo en la Soroz.",
  ui_story_70001001_40_dialog_content = "La indicación de voz hace un momento... La Soroz debe saber que necesitábamos ayuda, así que nos la proporcionó...",
  ui_story_70001001_41_dialog_content = "Hmm...",
  ui_story_70001001_42_dialog_content = "El Sistema Médico de Emergencia parece necesitar algo de tiempo con ella...",
  ui_story_70001001_43_dialog_content = "Centremos nuestra atención en encontrar una forma de reparar la plantilla de eco mientras tanto.",
  ui_story_70001001_44_dialog_content = "Bueno. Yo también ayudaré.",
  ui_story_70001001_45_dialog_content = "<color=#e8d9bb>\"Reanudar el procedimiento de reparación de la plantilla de eco\".</color>",
  ui_story_70001001_46_dialog_content = "<color=#e8d9bb>\"Paso uno: instale el complemento de base de datos estándar Colossus Echo Template\".</color>",
  ui_story_70001001_47_dialog_content = "¿Eh?",
  ui_story_70001001_48_dialog_content = "Que qué...?",
  ui_story_70001001_49_dialog_content = "PlayerName, ¿conseguiste otros módulos en tus manos?",
  ui_story_70001001_50_dialog_content = "Uf... Sólo el uno...",
  ui_story_70001001_51_dialog_content = "Soroz, ¿qué es este complemento de base de datos?",
  ui_story_70001001_52_dialog_content = "<color=#e8d9bb>\"Buscando información sobre el complemento de base de datos estándar de Colossus Echo Template... Búsqueda completa\".</color>",
  ui_story_70001001_53_dialog_content = "<color=#e8d9bb>\"Respuesta: el complemento de base de datos estándar de la plantilla Colossus Echo es una plantilla para The Colossus' Echo\".</color>",
  ui_story_70001001_54_dialog_content = "<color=#e8d9bb>\"Módulo actual en almacenamiento: 0\"</color>",
  ui_story_70001001_55_dialog_content = "<color=#e8d9bb>\"Nota: los complementos de base de datos estándar de Colossus Echo Template se pueden encontrar en las bases de mantenimiento de Colossi\".</color>",
  ui_story_70001001_56_dialog_content = "<color=#e8d9bb>\"Buscando la base de mantenimiento Colossus más cercana... Búsqueda completa\".</color>",
  ui_story_70001001_57_dialog_content = "<color=#e8d9bb>\"Objetivo ubicado en: Eraveil\".</color>",
  ui_story_70001001_58_dialog_content = "Eraveil...!?",
  ui_story_70001001_59_dialog_content = "¿Todavía hay una base en Eraveil?",
  ui_story_70001001_60_dialog_content = "¿Cómo es que nunca escuché sobre eso...?",
  ui_story_70001001_61_dialog_content = "<color=#e8d9bb>\"Nota: si no se puede instalar el complemento, el módulo de reparación de plantilla de eco se suspenderá en modo de espera\".</color>",
  ui_story_70001001_62_dialog_content = "Entrar en modo de espera...",
  ui_story_70001001_63_dialog_content = "<color=#e8d9bb>\"Módulo de reparación de plantilla de eco de Soroz entrando en modo de espera\".</color>",
  ui_story_70001001_64_dialog_content = "En cuanto volvamos a Eraveil, iré a buscarlo. <color=#FFB400>Base de mantenimiento del coloso</color>.",
  ui_story_70001001_65_dialog_content = "Incluso si tuviera que entregar a Eraveil, encontraré una manera de salvar a los Soroz...",
  ui_story_70001001_66_dialog_content = "Pero nuestra primera prioridad es enviar al Gran Mariscal de regreso a la Línea Segura.",
  ui_story_70001001_67_dialog_content = "De verdad...",
  ui_story_70001001_68_dialog_content = "¿Cómo está Reinhardt?",
  ui_story_70001001_69_dialog_content = "El sistema médico la está tratando.",
  ui_story_70001001_70_dialog_content = "no se que tan efectivo es...",
  ui_story_70001001_71_dialog_content = "Espero que todo vaya bien.",
  ui_story_70001001_72_dialog_content = "<color=#e8d9bb>¡Bip, bip, bip!</color>",
  ui_story_70001001_73_dialog_content = "¿Una solicitud de comunicación de Illumina...? Pero la persona que llama es desconocida.",
  ui_story_70001001_74_dialog_content = "Pueden ser nuestros refuerzos. ¡Escuchémoslos!",
  ui_story_70001001_75_dialog_content = "Saludando a los Soroz... Teniente Vice, Caelestite PlayerName...",
  ui_story_70001001_76_dialog_content = "¿Puedes escucharme?",
  ui_story_70001001_77_dialog_content = "¿Cómo debo responder a esto...?",
  ui_story_70001001_78_dialog_content = "Derecha. Este es el Soroz. Te recibimos.",
  ui_story_70001001_79_dialog_content = "Este es el oficial de inteligencia Aison de Illumina.",
  ui_story_70001001_80_dialog_content = "¿Cuál es tu ubicación actual?",
  ui_story_70001001_81_dialog_content = "Suroeste de Entrañas 80. Tiempo estimado hasta la línea de defensa Illumina... 10 minutos.",
  ui_story_70001001_82_dialog_content = "¡Tenemos una situación urgente que reportar!",
  ui_story_70001001_83_dialog_content = "El Gran Mariscal Reinhardt está gravemente herido en combate. Requerimos tratamiento médico inmediato.",
  ui_story_70001001_84_dialog_content = "Lo sabía.",
  ui_story_70001001_85_dialog_content = "Ninguna cosa.",
  ui_story_70001001_86_dialog_content = "Haré que un equipo médico te reciba en la línea de defensa Illumina. Solo llévala ahí tan pronto como puedas.",
  ui_story_70001001_87_dialog_content = "¡Lo se!",
  ui_story_70001001_88_dialog_content = "Afuera.",
  ui_story_70001001_89_dialog_content = "Realmente tienen prisa.",
  ui_story_70001001_90_dialog_content = "Gran Mariscal!",
  ui_story_70001001_91_dialog_content = "¡Reinhardt...!",
  ui_story_70001001_92_dialog_content = "¿Cómo te sientes?",
  ui_story_70001001_93_dialog_content = "Estoy bien. Siento que todo mi cuerpo está a punto de explotar... pero no voy a morir hoy.",
  ui_story_70001001_94_dialog_content = "Necesitarás unos días de descanso para recuperarte.",
  ui_story_70001001_95_dialog_content = "La tecnología de Caelestite es realmente algo.",
  ui_story_70001001_96_dialog_content = "Si tuviéramos algunas de estas unidades médicas en Entrañas de Illumina, la mayoría de la gente habría sobrevivido...",
  ui_story_70001001_97_dialog_content = "No sabría sobre esta función si Soroz no me lo recordara.",
  ui_story_70001001_98_dialog_content = "Ah, y ¿cómo está el Soroz ahora mismo?",
  ui_story_70001001_99_dialog_content = "Tenemos el módulo requerido, pero aún necesitamos algo más para reparar el Soroz.",
  ui_story_70001001_100_dialog_content = "Es así...",
  ui_story_70001001_101_dialog_content = "Espero que puedas repararlo pronto.",
  ui_story_70001001_102_dialog_content = "...",
  ui_story_70001001_103_dialog_content = "Reinhardt, hay algo que no entiendo.",
  ui_story_70001001_104_dialog_content = "¿Hmm? ¿No tenías ya tu \"última pregunta\"?",
  ui_story_70001001_105_dialog_content = "No. No es una pregunta... Solo algo que encuentro contradictorio...",
  ui_story_70001001_106_dialog_content = "No eres alguien que abandonaría a sus amigos.",
  ui_story_70001001_107_dialog_content = "Pero, ¿por qué elegirías abandonarlos entonces?",
  ui_story_70001001_108_dialog_content = "Fue la decisión más razonable... en aquel entonces.",
  ui_story_70001001_109_dialog_content = "No permitiré que los soldados de Illumina sean sacrificados sin una buena razón.",
  ui_story_70001001_110_dialog_content = "Pero en ese entonces, no eras el Gran Mariscal. Eras solo un soldado.",
  ui_story_70001001_111_dialog_content = "Estoy seguro de que hay más.",
  ui_story_70001001_112_dialog_content = "Es extraño... de hecho.",
  ui_story_70001001_113_dialog_content = "Gran mariscal, usted personalmente vino a salvarnos por su cuenta e intentó todo para atraer a sus antiguos camaradas.",
  ui_story_70001001_114_dialog_content = "Creo que habrías regresado para salvarlos sin importar qué en ese entonces...",
  ui_story_70001001_115_dialog_content = "...",
  ui_story_70001001_116_dialog_content = "La Caelestita es difícil de manejar.",
  ui_story_70001001_117_option_content = "Lo tomaré como un cumplido",
  ui_story_70001001_118_option_content = "Puedes decir que estoy más atento a los detalles.",
  ui_story_70001001_119_dialog_content = "No quería revivir el pasado, pero si realmente pienso en el pasado...",
  ui_story_70001001_120_dialog_content = "Cuando atravesé las líneas enemigas y regresé a la Línea Segura en ese entonces...",
  ui_story_70001001_121_dialog_content = "¡Tengo noticias urgentes que informar!",
  ui_story_70001001_122_dialog_content = "¡La información anterior estaba equivocada! ¡El interior de Entrañas 80 está repleto de eclipses!",
  ui_story_70001001_123_dialog_content = "Me abrí paso solo para ayudar a mi equipo que aún estaba atrapado allí. ¡Tenemos muchas bajas!",
  ui_story_70001001_124_dialog_content = "¡Necesitamos apoyo!",
  ui_story_70001001_125_dialog_content = "Comprendido. Lo investigaremos. Médico, atienda sus heridas.",
  ui_story_70001001_126_dialog_content = "Por aqui por favor...",
  ui_story_70001001_127_dialog_content = "¡No! ¡No entiendes la urgencia de esto!",
  ui_story_70001001_128_dialog_content = "¡Necesitan apoyo YA!",
  ui_story_70001001_129_dialog_content = "De lo contrario... mis amigos... ¡morirán allí!",
  ui_story_70001001_130_dialog_content = "Es necesario planificar y discutir una operación de búsqueda y rescate. Esta no es tu preocupación ahora. Estás despedido.",
  ui_story_70001001_131_dialog_content = "Ni siquiera vas a tratar de salvarlos, ¿verdad?",
  ui_story_70001001_132_dialog_content = "No haga suposiciones salvajes.",
  ui_story_70001001_133_dialog_content = "Bien. Si no envías ayuda, regresaré yo mismo.",
  ui_story_70001001_134_dialog_content = "¡No los abandonaré!",
  ui_story_70001001_135_dialog_content = "Eres un soldado de Illumina y estás sujeto a órdenes. Desafía mis órdenes de nuevo y haré que te arresten.",
  ui_story_70001001_136_dialog_content = "Mis amigos todavía están esperando que regrese.",
  ui_story_70001001_137_dialog_content = "¡Médico!",
  ui_story_70001001_138_dialog_content = "Cómo te atreves...",
  ui_story_70001001_139_dialog_content = "Ponla debajo y atiende sus heridas. Y obsérvala de cerca.",
  ui_story_70001001_140_dialog_content = "Sí.",
  ui_story_70001001_141_dialog_content = "Cuando finalmente volví en mí, ya habían pasado días.",
  ui_story_70001001_142_dialog_content = "Me transfirieron al centro médico de Gannon. Las personas que regresaron de la Línea Segura me dijeron...",
  ui_story_70001001_143_dialog_content = "Al final, el Comité nunca envió refuerzos a Entrañas 80.",
  ui_story_70001001_144_dialog_content = "Yo fui el único sobreviviente de ese incidente.",
  ui_story_70001001_145_dialog_content = "...",
  ui_story_70001001_146_dialog_content = "Después de calmarme, me sumergí en mis pensamientos y eventualmente entendí sus razones.",
  ui_story_70001001_147_dialog_content = "Cada vida es Illumina es igualmente importante.",
  ui_story_70001001_148_dialog_content = "Las necesidades de muchos superan las necesidades de unos pocos.",
  ui_story_70001001_149_dialog_content = "Esto es algo que un Gran Mariscal debe aceptar y hacer. Este es el precio a pagar.",
  ui_story_70001001_150_dialog_content = "Hasta que Denier regresó a Illumina a pesar de sus graves heridas.",
  ui_story_70001001_151_dialog_content = "¿Quién es ahora Forsakin...?",
  ui_story_70001001_152_dialog_content = "Estaba feliz de ver a mi amigo con vida, pero algo cambió entre nosotros después.",
  ui_story_70001001_153_dialog_content = "Al final, nos separamos.",
  ui_story_70001001_154_dialog_content = "Le mentiste. No fue tu decisión abandonarlos.",
  ui_story_70001001_155_dialog_content = "Sentí que preferiría que me odiara en lugar de odiar a Illumina.",
  ui_story_70001001_156_dialog_content = "Ella es extremadamente brillante pero también vengativa.",
  ui_story_70001001_157_dialog_content = "Si su ira se centrara solo en mí, entonces la gente inocente de Illumina se salvaría.",
  ui_story_70001001_158_dialog_content = "De todos modos, un \"monstruo\" como yo sería difícil de matar.",
  ui_story_70001001_159_dialog_content = "Ahora entiendo.",
  ui_story_70001001_160_dialog_content = "Parece que te he entendido mal.",
  ui_story_70001001_161_dialog_content = "¿Vaya? ¿Cómo?",
  ui_story_70001001_162_dialog_content = "Pensé que eras un bastardo de sangre fría.",
  ui_story_70001001_163_dialog_content = "PlayerName... Eso no es algo para decir frente al Gran Mariscal...",
  ui_story_70001001_164_dialog_content = "Jajaja⁠—¡Gah! ¡Ay! *tos*",
  ui_story_70001001_165_dialog_content = "*tos* Estoy bien.",
  ui_story_70001001_166_dialog_content = "Estoy acostumbrado a que me malinterpreten. Uno menos, uno más, no me importa.",
  ui_story_70001001_167_dialog_content = "Mientras pueda mantener a salvo a la gente de Illumina... puedo con todo.",
  ui_story_70001001_168_dialog_content = "Hmm...",
  ui_story_70001001_169_dialog_content = "Tuvimos una larga charla. Pronto estaremos llegando a Illumina Safe Line.",
  ui_story_70001001_170_dialog_content = "Derecha. De la sartén al fuego... Tengo que lidiar con \"ellos\" ahora.",
  ui_story_70001001_171_dialog_content = "¡Gran Mariscal, has vuelto!",
  ui_story_70001001_172_dialog_content = "Si no lo hubieras hecho, el Comité nos estaría enviando a todos al tribunal militar...",
  ui_story_70001001_173_dialog_content = "Nos enteramos de tu lesión. ¡El equipo médico está esperando ahora mismo!",
  ui_story_70001001_174_dialog_content = "Está bien. Estoy bien.",
  ui_story_70001001_175_dialog_content = "Gracias a Caelestite y Colossus, mi tratamiento médico de emergencia ya se ha realizado. Estoy estable por el momento.",
  ui_story_70001001_176_dialog_content = "Todo es gracias al oportuno recordatorio de Soroz.",
  ui_story_70001001_177_dialog_content = "Por favor, permítanos realizar un chequeo completo, ¡solo para estar seguros!",
  ui_story_70001001_178_dialog_content = "No podemos darnos el lujo de perder al Gran Mariscal.",
  ui_story_70001001_179_dialog_content = "Perder el \"Gran Mariscal\"... ¿o sí?",
  ui_story_70001001_180_dialog_content = "Mira, eso es lo que quiero decir. Los procedimientos pueden ser necesarios, pero siguen siendo una molestia.",
  ui_story_70001001_181_dialog_content = "Un físico, ¿verdad? Bien. Haré lo que dices.",
  ui_story_70001001_182_dialog_content = "Por aquí por favor.",
  ui_story_70001001_183_dialog_content = "Dame un momento. Necesito tener algunas palabras con PlayerName.",
  ui_story_70001001_184_dialog_content = "¿Eh? Oh, todo bien.",
  ui_story_70001001_185_dialog_content = "Si te preguntan qué pasó en Entrañas 80, solo diles la verdad.",
  ui_story_70001001_186_dialog_content = "A pesar de ser conservadores y obstinados por derecho propio, el Comité todavía hace las cosas por números. No te echarán la culpa.",
  ui_story_70001001_187_dialog_content = "Pero, ¿y tú...?",
  ui_story_70001001_188_dialog_content = "No es para preocuparse. La última vez que miré, todavía soy el Gran Mariscal de Illumina.",
  ui_story_70001001_189_dialog_content = "Está bien... Cuídate. Espero que nos crucemos de nuevo.",
  ui_story_70001001_190_dialog_content = "Me gustaría eso.",
  ui_story_70001001_191_dialog_content = "Observé a Reinhardt desde atrás hasta que desapareció de Entrañas.",
  ui_story_70001001_192_dialog_content = "Las preocupaciones brotaron en mi corazón.",
  ui_story_70001001_193_dialog_content = "De todos modos, debería volver y comprobar el estado de Soroz.",
  ui_story_70001001_194_dialog_content = "Luego regresa a Eraveil y encuentra una manera de repararlo."
}
return config
